(** * Rule plans, plan checking and saturation rounds

    The planner compiles each rule into join plans over shared index slots, the checker
    validates a plan against its program, a round joins, filters and applies the plans of a
    program, and a run drives rounds under its limits.
    For example, the rule [path(x, z) :- path(x, y), edge(y, z)] joins the slots
    [(path, [0; 1])] and [(edge, [0; 1])] on the join variable of [y].
    Builds on: RunSig, Sorts, the binary trie, the self-delimiting codes and the binary-fuel
    loop.

    Main results
    - [universe_spec] The finite universe contains exactly declared relational tuples over active
      values.
    - [herbrand_spec] The Herbrand budget counts the pinned finite universe.
    - [load_spec] Loading initializes precisely the declarations and compiled index slots.
    - [run_least] A saturated relational result is included in every closed extension of its seed
      that keeps the program's kinds and sorts, so a relation row of the extension has no output.
    - [plan_complexity] Planning is cubic in the program text, because sorting the positions of an
      atom compares unary join indices.
    - [load_complexity] Loading is linear in its declarations and slots, with the layout work of
      sorting.
    - [check_plan_complexity] Plan checking is linear in the program and plan syntax at their
      identifier width.
    - [run_complexity] A run costs its trace work at the identifier width, its fuel counter and
      its scaled initial credit.
    - [round_complexity] A round costs its round work at the identifier width and its scaled
      initial credit. *)

From Stdlib Require Import List PArith NArith Arith Bool Lia Relations.Relation_Operators
  Sorting.Sorted Sorting.Permutation PeanoNat.
From Argent Require Import Time Tactics Std Loop Complexity.
From Galois.Base Require Import Code Loop Trie.
From Galois.Egglog Require Import ValueSig IndexSig JoinSig DatabaseSig Syntax Model Sorts RunSig.
Import ComplexityNotations.

Import Lia.
Import List.ListNotations.

(** * Record readers *)

(** A reader takes one field of a plan record by one record elimination. *)
Definition plan_rule_ix {V : Type} (c : cplan V) : N :=
  match c with
  | CPlan _ ix _ _ _ _ => ix
  end.
TimeFun plan_rule_ix.

Definition plan_join {V : Type} (c : cplan V) : jplan :=
  match c with
  | CPlan _ _ j _ _ _ => j
  end.
TimeFun plan_join.

Definition plan_sources {V : Type} (c : cplan V) : list (source V) :=
  match c with
  | CPlan _ _ _ srcs _ _ => srcs
  end.
TimeFun plan_sources.

Definition plan_vars {V : Type} (c : cplan V) : list positive :=
  match c with
  | CPlan _ _ _ _ vars _ => vars
  end.
TimeFun plan_vars.

Definition plan_post {V : Type} (c : cplan V) : list nat :=
  match c with
  | CPlan _ _ _ _ _ post => post
  end.
TimeFun plan_post.

Definition compiled_slots {V : Type} (cp : compiled V) : list (positive * list nat) :=
  match cp with
  | Compiled _ sl _ _ => sl
  end.
TimeFun compiled_slots.

Definition compiled_naive {V : Type} (cp : compiled V) : list (cplan V) :=
  match cp with
  | Compiled _ _ nv _ => nv
  end.
TimeFun compiled_naive.

Definition compiled_semi {V : Type} (cp : compiled V) : list (cplan V) :=
  match cp with
  | Compiled _ _ _ sn => sn
  end.
TimeFun compiled_semi.

Definition limits_iter (lim : limits) : N :=
  match lim with
  | Limits it _ => it
  end.
TimeFun limits_iter.

Definition limits_ids (lim : limits) : N :=
  match lim with
  | Limits _ ids => ids
  end.
TimeFun limits_ids.

(** * Rule access and binding tries *)

(** The rule at a binary position walks the list with a binary countdown, and a position past
    the end gives the empty rule. *)
Fixpoint rule_at {V : Type} (n : N) (rs : list (rule V)) : rule V :=
  match rs with
  | [] => Rule V [] []
  | r :: rest =>
      match n with
      | N0 => r
      | Npos _ => rule_at (N.pred n) rest
      end
  end.
TimeFun rule_at.

(** The binary walk finds the rule that unary indexing names. *)
Lemma rule_at_nth : forall (V : Type) n (rs : list (rule V)),
  rule_at n rs = nth (N.to_nat n) rs (Rule V [] []).
Proof.
  intros V n rs. revert n.
  induction rs as [| r rest IH]; intro n.
  - destruct (N.to_nat n); reflexivity.
  - destruct n as [| p].
    + reflexivity.
    + cbn [rule_at]. rewrite IH, N2Nat.inj_pred.
      change (N.to_nat (Npos p)) with (Pos.to_nat p).
      destruct (Pos2Nat.is_succ p) as [m Hm]. rewrite Hm. reflexivity.
Qed.

(** The first binding of a name wins, as in [binding_env]. *)
Fixpoint bind_cells {V : Type} (vars : list positive) (cells : list (cell V))
    (t : ptrie (cell V)) : ptrie (cell V) :=
  match vars, cells with
  | x :: xs, c :: cs =>
      match trie_get x t with
      | Some _ => bind_cells xs cs t
      | None => bind_cells xs cs (PTrieCode.set x c t)
      end
  | _, _ => t
  end.
TimeFun bind_cells.

(** Binding onto a trie keeps its entries and adds the first binding of each new name. *)
Lemma bind_cells_get : forall (V : Type) vars (cells : list (cell V)) t x,
  trie_get x (bind_cells vars cells t) =
    match trie_get x t with
    | Some c => Some c
    | None => binding_env vars cells x
    end.
Proof.
  intros V vars. induction vars as [| v vs IH]; intros cells t x.
  - cbn [bind_cells binding_env]. destruct (trie_get x t); reflexivity.
  - destruct cells as [| c cs].
    + cbn [bind_cells binding_env]. destruct (trie_get x t); reflexivity.
    + cbn [bind_cells binding_env].
      destruct (Pos.eqb_spec x v) as [Hxv | Hxv].
      * subst v. destruct (trie_get x t) as [d |] eqn:Hget.
        -- rewrite IH, Hget. reflexivity.
        -- rewrite IH, PTrie.get_set_same. reflexivity.
      * destruct (trie_get v t) as [d |] eqn:Hget.
        -- apply IH.
        -- rewrite IH, PTrie.get_set_other by congruence. reflexivity.
Qed.

(** * Post filters *)

Definition cell_eqb {V : Type} (eqb : V -> V -> bool) (a b : cell V) : bool :=
  match a, b with
  | Id i, Id j => Pos.eqb i j
  | Val v, Val w => eqb v w
  | _, _ => false
  end.
TimeFun cell_eqb.

(** A term of a primitive atom names a value of the binding trie. *)
Definition trie_term {V : Type} (t : ptrie (cell V)) (x : term V) : option V :=
  match x with
  | Var y =>
      match trie_get y t with
      | Some (Val v) => Some v
      | _ => None
      end
  | Lit v => Some v
  end.
TimeFun trie_term.

Fixpoint trie_terms {V : Type} (t : ptrie (cell V)) (xs : list (term V)) : option (list V) :=
  match xs with
  | [] => Some []
  | x :: rest =>
      match trie_term t x with
      | Some v =>
          match trie_terms t rest with
          | Some vs => Some (v :: vs)
          | None => None
          end
      | None => None
      end
  end.
TimeFun trie_terms.

(** A primitive atom holds when its arguments are values and its result agrees with the
    primitive. The known result value is the first operand of the comparison. *)
Definition prim_holds {V : Type} (prim : positive -> list V -> option V)
    (eqb : V -> V -> bool) (t : ptrie (cell V)) (p : positive) (args : list (term V))
    (res : term V) : bool :=
  match trie_terms t args with
  | Some vs =>
      match prim p vs with
      | Some v =>
          match trie_term t res with
          | Some w => eqb w v
          | None => false
          end
      | None => false
      end
  | None => false
  end.
TimeFun prim_holds.

(** A later occurrence of a variable in one atom reads the next copy name of the plan, and the
    copy cell must equal the cell of the variable. The result is the unread copy names. *)
Fixpoint copies_ok {V : Type} (eqb : V -> V -> bool) (t : ptrie (cell V))
    (seen : ptrie unit) (xs : list (term V)) (copies : list positive)
    : option (list positive) :=
  match xs with
  | [] => Some copies
  | Lit _ :: rest => copies_ok eqb t seen rest copies
  | Var x :: rest =>
      match trie_get x seen with
      | Some _ =>
          match copies with
          | z :: more =>
              match trie_get z t, trie_get x t with
              | Some c, Some d =>
                  if cell_eqb eqb c d then copies_ok eqb t seen rest more else None
              | _, _ => None
              end
          | [] => None
          end
      | None => copies_ok eqb t (PTrieCode.set x tt seen) rest copies
      end
  end.
TimeFun copies_ok.

(** The post filter checks its listed atoms in order. It evaluates each primitive atom and
    compares the copies of each function atom. *)
Fixpoint keep_post {V : Type} (prim : positive -> list V -> option V) (eqb : V -> V -> bool)
    (q : list (atom V)) (t : ptrie (cell V)) (post : list nat) (copies : list positive)
    : bool :=
  match post with
  | [] => true
  | i :: rest =>
      match nth_error q i with
      | Some (Prim _ p args res) =>
          if prim_holds prim eqb t p args res then keep_post prim eqb q t rest copies
          else false
      | Some (Fun _ _ args res) =>
          match copies_ok eqb t Empty (args ++ option_list res) copies with
          | Some more => keep_post prim eqb q t rest more
          | None => false
          end
      | None => false
      end
  end.
TimeFun keep_post.

(** * Action terms *)

(** Variables bound by earlier actions shadow the binding environment. *)
Definition look {V : Type} (s : positive -> option (cell V)) (locals : ptrie (cell V))
    (x : positive) : option (cell V) :=
  match trie_get x locals with
  | Some c => Some c
  | None => s x
  end.
TimeFun look.

Definition term_cell {V : Type} (s : positive -> option (cell V)) (locals : ptrie (cell V))
    (t : term V) : option (cell V) :=
  match t with
  | Var x => look s locals x
  | Lit v => Some (Val v)
  end.
TimeFun term_cell.

Fixpoint term_cells {V : Type} (s : positive -> option (cell V)) (locals : ptrie (cell V))
    (ts : list (term V)) : option (list (cell V)) :=
  match ts with
  | [] => Some []
  | t :: rest =>
      match term_cell s locals t with
      | Some c =>
          match term_cells s locals rest with
          | Some cs => Some (c :: cs)
          | None => None
          end
      | None => None
      end
  end.
TimeFun term_cells.

Fixpoint term_values {V : Type} (s : positive -> option (cell V)) (locals : ptrie (cell V))
    (ts : list (term V)) : option (list V) :=
  match ts with
  | [] => Some []
  | t :: rest =>
      match term_cell s locals t with
      | Some (Val v) =>
          match term_values s locals rest with
          | Some vs => Some (v :: vs)
          | None => None
          end
      | _ => None
      end
  end.
TimeFun term_values.

Definition result_cell {V : Type} (s : positive -> option (cell V)) (locals : ptrie (cell V))
    (res : option (term V)) : option (option (cell V)) :=
  match res with
  | None => Some None
  | Some t =>
      match term_cell s locals t with
      | Some c => Some (Some c)
      | None => None
      end
  end.
TimeFun result_cell.

(** * Planning *)

(** Slots are identified by a self-delimiting code of the function and the permutation. *)
Fixpoint nat_code (n : nat) : positive :=
  match n with
  | O => xH
  | S m => xO (nat_code m)
  end.
TimeFun nat_code.

Definition slot_code (f : positive) (perm : list nat) : positive :=
  glue f (list_code nat_code perm).
TimeFun slot_code.

Fixpoint count_from (start len : nat) : list nat :=
  match len with
  | O => []
  | S len' => start :: count_from (S start) len'
  end.
TimeFun count_from.

(** The planner's slot state maps slot codes to slot numbers and keeps the slots reversed. *)
Inductive slot_state : Type :=
  | SlotState (table : ptrie N) (next : N) (rows : list (positive * list nat)).

(** A slot keeps the number of its first registration. *)
Definition add_slot (f : positive) (perm : list nat) (st : slot_state) : N * slot_state :=
  match st with
  | SlotState table next rows =>
      let key := slot_code f perm in
      match trie_get key table with
      | Some s => (s, st)
      | None => (next, SlotState (PTrieCode.set key next table) (N.succ next) ((f, perm) :: rows))
      end
  end.
TimeFun add_slot.

(** Each identifier function, at its first declaration, gets the slot of all its positions in
    declaration order. *)
Fixpoint full_slots (ds : list decl) (seen : ptrie unit) (st : slot_state) : slot_state :=
  match ds with
  | [] => st
  | Decl f ss o :: rest =>
      match trie_get f seen with
      | Some _ => full_slots rest seen st
      | None =>
          match o with
          | OId =>
              full_slots rest (PTrieCode.set f tt seen)
                (snd (add_slot f (count_from 0 (S (length ss))) st))
          | _ => full_slots rest (PTrieCode.set f tt seen) st
          end
      end
  end.
TimeFun full_slots.

Definition pos_max (a b : positive) : positive :=
  match Pos.compare a b with
  | Lt => b
  | _ => a
  end.
TimeFun pos_max.

Definition term_max {V : Type} (t : term V) (m : positive) : positive :=
  match t with
  | Var x => pos_max x m
  | Lit _ => m
  end.
TimeFun term_max.

Fixpoint terms_max {V : Type} (ts : list (term V)) (m : positive) : positive :=
  match ts with
  | [] => m
  | t :: rest => terms_max rest (term_max t m)
  end.
TimeFun terms_max.

(** The largest variable of a query bounds the names of its plan's real variables. *)
Fixpoint query_max {V : Type} (q : list (atom V)) (m : positive) : positive :=
  match q with
  | [] => m
  | Fun _ _ args res :: rest => query_max rest (terms_max (args ++ option_list res) m)
  | Prim _ _ args res :: rest => query_max rest (terms_max (res :: args) m)
  end.
TimeFun query_max.

(** Later occurrences of a variable in one function atom need copies. *)
Fixpoint term_copies {V : Type} (seen : ptrie unit) (ts : list (term V)) (n : nat) : nat :=
  match ts with
  | [] => n
  | Lit _ :: rest => term_copies seen rest n
  | Var x :: rest =>
      match trie_get x seen with
      | Some _ => term_copies seen rest (S n)
      | None => term_copies (PTrieCode.set x tt seen) rest n
      end
  end.
TimeFun term_copies.

Fixpoint query_copies {V : Type} (q : list (atom V)) (n : nat) : nat :=
  match q with
  | [] => n
  | Fun _ _ args res :: rest => query_copies rest (term_copies Empty (args ++ option_list res) n)
  | Prim _ _ _ _ :: rest => query_copies rest n
  end.
TimeFun query_copies.

(** The layout numbers the join variables of a rule. Copies come first, and real variables and
    literals follow in the order of their first positions. Its name lists are reversed. *)
Inductive var_layout : Type :=
  | VarLayout (names : ptrie nat) (copies mains : nat) (fresh : positive)
      (copy_names main_names : list positive).

(** Each atom position receives a join variable. A literal and the first query occurrence of a
    variable take the next main variable, a later occurrence in the same atom takes the next
    copy, and any other occurrence reuses its variable. *)
Fixpoint place_terms {V : Type} (base : nat) (ts : list (term V)) (pos : nat)
    (seen : ptrie unit) (lay : var_layout) (pairs : list (nat * nat))
    (lits : list (nat * V)) (copied : bool)
    : var_layout * list (nat * nat) * list (nat * V) * bool :=
  match ts with
  | [] => (lay, pairs, lits, copied)
  | t :: rest =>
      match lay with
      | VarLayout names nc nm fresh cn mn =>
          match t with
          | Lit v =>
              let j := base + nm in
              place_terms base rest (S pos) seen
                (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn))
                ((j, pos) :: pairs) ((j, v) :: lits) copied
          | Var x =>
              match trie_get x seen with
              | Some _ =>
                  place_terms base rest (S pos) seen
                    (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn)
                    ((nc, pos) :: pairs) lits true
              | None =>
                  match trie_get x names with
                  | Some j =>
                      place_terms base rest (S pos) (PTrieCode.set x tt seen) lay
                        ((j, pos) :: pairs) lits copied
                  | None =>
                      let j := base + nm in
                      place_terms base rest (S pos) (PTrieCode.set x tt seen)
                        (VarLayout (PTrieCode.set x j names) nc (S nm) fresh cn (x :: mn))
                        ((j, pos) :: pairs) lits copied
                  end
              end
          end
      end
  end.
TimeFun place_terms.

Fixpoint insert_pair (j pos : nat) (l : list (nat * nat)) : list (nat * nat) :=
  match l with
  | [] => [(j, pos)]
  | (k, q) :: rest =>
      if Nat.leb j k then (j, pos) :: l else (k, q) :: insert_pair j pos rest
  end.
TimeFun insert_pair.

(** Sorting the positions of an atom by join variable gives its column and its permutation. *)
Fixpoint sort_pairs (l : list (nat * nat)) : list (nat * nat) :=
  match l with
  | [] => []
  | (j, pos) :: rest => insert_pair j pos (sort_pairs rest)
  end.
TimeFun sort_pairs.

(** A planned function atom has a slot, a column and the literals of its positions. *)
Inductive atom_plan (V : Type) : Type :=
  | AtomPlan (slot : N) (col : list nat) (lits : list (nat * V)).

Arguments AtomPlan {V}.

(** Prim atoms and function atoms with copies enter the post filter in query order. *)
Fixpoint plan_atoms {V : Type} (base : nat) (q : list (atom V)) (ai : nat)
    (lay : var_layout) (st : slot_state) (outs : list (atom_plan V)) (post : list nat)
    : var_layout * slot_state * list (atom_plan V) * list nat :=
  match q with
  | [] => (lay, st, outs, post)
  | Prim _ _ _ _ :: rest => plan_atoms base rest (S ai) lay st outs (ai :: post)
  | Fun _ f args res :: rest =>
      let '(lay', pairs, lits, copied) :=
        place_terms base (args ++ option_list res) 0 Empty lay [] [] false in
      let sorted := sort_pairs pairs in
      let '(s, st') := add_slot f (map snd sorted) st in
      plan_atoms base rest (S ai) lay' st'
        (AtomPlan s (map fst sorted) (rev_append lits []) :: outs)
        (if copied then ai :: post else post)
  end.
TimeFun plan_atoms.

Fixpoint literal_cols {V : Type} (lits : list (nat * V)) (tail : list (list nat))
    : list (list nat) :=
  match lits with
  | [] => tail
  | (j, _) :: rest => [j] :: literal_cols rest tail
  end.
TimeFun literal_cols.

(** Each atom's column is followed by the columns of its literals in position order. *)
Fixpoint plan_cols {V : Type} (atoms : list (atom_plan V)) : list (list nat) :=
  match atoms with
  | [] => []
  | AtomPlan _ col lits :: rest => col :: literal_cols lits (plan_cols rest)
  end.
TimeFun plan_cols.

Fixpoint literal_sources {V : Type} (lits : list (nat * V)) (tail : list (source V))
    : list (source V) :=
  match lits with
  | [] => tail
  | (_, v) :: rest => Const V (Val v) :: literal_sources rest tail
  end.
TimeFun literal_sources.

Definition pivot_source {V : Type} (s : N) (pivot : option nat) : source V :=
  match pivot with
  | Some O => New V s
  | _ => All V s
  end.
TimeFun pivot_source.

Definition pivot_next (pivot : option nat) : option nat :=
  match pivot with
  | Some (S k) => Some k
  | _ => None
  end.
TimeFun pivot_next.

(** The atom at the pivot reads the new rows of its slot and every other atom reads all rows. *)
Fixpoint plan_srcs {V : Type} (atoms : list (atom_plan V)) (pivot : option nat)
    : list (source V) :=
  match atoms with
  | [] => []
  | AtomPlan s _ lits :: rest =>
      pivot_source s pivot :: literal_sources lits (plan_srcs rest (pivot_next pivot))
  end.
TimeFun plan_srcs.

(** A rule has one semi-naive plan for each function atom. *)
Fixpoint semi_plans {V : Type} (i : N) (j : jplan) (vars : list positive) (post : list nat)
    (atoms : list (atom_plan V)) (m : nat) (todo : list (atom_plan V)) : list (cplan V) :=
  match todo with
  | [] => []
  | _ :: rest =>
      CPlan V i j (plan_srcs atoms (Some m)) vars post ::
        semi_plans i j vars post atoms (S m) rest
  end.
TimeFun semi_plans.

(** A rule's naive plan and its semi-naive plans share one layout. *)
Definition plan_rule {V : Type} (i : N) (r : rule V) (st : slot_state)
    : slot_state * cplan V * list (cplan V) :=
  match r with
  | Rule _ q _ =>
      let base := query_copies q 0 in
      let '(lay, st', outs, post) :=
        plan_atoms base q 0 (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] [])
          st [] [] in
      match lay with
      | VarLayout _ _ nm _ cn mn =>
          let atoms := rev_append outs [] in
          let vars := rev_append cn (rev_append mn []) in
          let j := JPlan (base + nm) (plan_cols atoms) in
          let ps := rev_append post [] in
          (st', CPlan V i j (plan_srcs atoms None) vars ps, semi_plans i j vars ps atoms 0 atoms)
      end
  end.
TimeFun plan_rule.

Fixpoint plan_rules {V : Type} (rs : list (rule V)) (i : N) (st : slot_state)
    (naive semi : list (cplan V)) : slot_state * list (cplan V) * list (cplan V) :=
  match rs with
  | [] => (st, naive, semi)
  | r :: rest =>
      let '(st', c, cs) := plan_rule i r st in
      plan_rules rest (N.succ i) st' (c :: naive) (rev_append cs semi)
  end.
TimeFun plan_rules.

(** The full slots come first, and the rules follow in program order. *)
Definition plan_program {V : Type} (p : program V) : compiled V :=
  match p with
  | Program _ ds rs =>
      let '(st, naive, semi) :=
        plan_rules rs 0%N (full_slots ds Empty (SlotState Empty 0%N [])) [] [] in
      match st with
      | SlotState _ _ rows =>
          Compiled V (rev_append rows []) (rev_append naive []) (rev_append semi [])
      end
  end.
TimeFun plan_program.

(** * Checking *)

(** The first declaration of a name fixes its row width. *)
Fixpoint decl_widths (ds : list decl) (t : ptrie nat) : ptrie nat :=
  match ds with
  | [] => t
  | Decl f ss o :: rest =>
      match trie_get f t with
      | Some _ => decl_widths rest t
      | None =>
          let width := match o with
            | ORel => length ss
            | _ => S (length ss)
            end in
          decl_widths rest (PTrieCode.set f width t)
      end
  end.
TimeFun decl_widths.

(** A slot permutation lists distinct positions within the row width. *)
Fixpoint perm_ok (width : nat) (perm : list nat) (seen : ptrie unit) : bool :=
  match perm with
  | [] => true
  | i :: rest =>
      let key := nat_code i in
      match trie_get key seen with
      | Some _ => false
      | None =>
          if Nat.leb (S i) width then perm_ok width rest (PTrieCode.set key tt seen) else false
      end
  end.
TimeFun perm_ok.

(** The slot table maps the code of each valid slot to its first number and its contents. *)
Fixpoint slot_table (widths : ptrie nat) (sl : list (positive * list nat)) (next : N)
    (table : ptrie (N * (positive * list nat)))
    : option (ptrie (N * (positive * list nat))) :=
  match sl with
  | [] => Some table
  | (f, perm) :: rest =>
      match trie_get f widths with
      | Some width =>
          if perm_ok width perm Empty then
            let key := slot_code f perm in
            match trie_get key table with
            | Some _ => slot_table widths rest (N.succ next) table
            | None =>
                slot_table widths rest (N.succ next)
                  (PTrieCode.set key (next, (f, perm)) table)
            end
          else None
      | None => None
      end
  end.
TimeFun slot_table.

(** The names of a plan are distinct, and each names its join variable. *)
Fixpoint var_table (vars : list positive) (j : N) (t : ptrie N) : option (ptrie N) :=
  match vars with
  | [] => Some t
  | x :: rest =>
      match trie_get x t with
      | Some _ => None
      | None => var_table rest (N.succ j) (PTrieCode.set x j t)
      end
  end.
TimeFun var_table.

Fixpoint nat_n (n : nat) : N :=
  match n with
  | O => 0%N
  | S m => N.succ (nat_n m)
  end.
TimeFun nat_n.

Fixpoint nats_eqb (a b : list nat) : bool :=
  match a, b with
  | [], [] => true
  | x :: xs, y :: ys => if Nat.eqb x y then nats_eqb xs ys else false
  | _, _ => false
  end.
TimeFun nats_eqb.

(** A column is nonempty, strictly increasing and below the variable count. *)
Fixpoint column_ok (n : nat) (lv : list nat) (prev : option nat) : bool :=
  match lv with
  | [] =>
      match prev with
      | Some _ => true
      | None => false
      end
  | l :: rest =>
      let above := match prev with
        | Some k => Nat.leb (S k) l
        | None => true
        end in
      if above then if Nat.leb (S l) n then column_ok n rest (Some l) else false else false
  end.
TimeFun column_ok.

(** Each position of an atom has a join variable. The first occurrence of a variable in the
    atom has the variable of its name, a later occurrence has the next copy, and a literal has
    the column of its constant source. The inverse table maps join variables to positions. *)
Fixpoint check_terms {V : Type} (eqb : V -> V -> bool) (names : ptrie N)
    (ts : list (term V)) (pos : nat) (seen : ptrie unit) (copy : N) (inv : ptrie nat)
    (srcs : list (source V)) (cols : list (list nat)) (copied : bool)
    : option (N * ptrie nat * list (source V) * list (list nat) * bool) :=
  match ts with
  | [] => Some (copy, inv, srcs, cols, copied)
  | Lit v :: rest =>
      match srcs, cols with
      | Const _ (Val w) :: srcs', [l] :: cols' =>
          if eqb w v then
            check_terms eqb names rest (S pos) seen copy
              (PTrieCode.set (N.succ_pos (nat_n l)) pos inv) srcs' cols' copied
          else None
      | _, _ => None
      end
  | Var x :: rest =>
      match trie_get x seen with
      | Some _ =>
          check_terms eqb names rest (S pos) seen (N.succ copy)
            (PTrieCode.set (N.succ_pos copy) pos inv) srcs cols true
      | None =>
          match trie_get x names with
          | Some j =>
              check_terms eqb names rest (S pos) (PTrieCode.set x tt seen) copy
                (PTrieCode.set (N.succ_pos j) pos inv) srcs cols copied
          | None => None
          end
      end
  end.
TimeFun check_terms.

(** The column of an atom reads its permutation from the inverse table and counts the distinct
    join variables that the plan uses. *)
Fixpoint column_perm (inv : ptrie nat) (lv : list nat) (used : ptrie unit) (count : N)
    : option (list nat * ptrie unit * N) :=
  match lv with
  | [] => Some ([], used, count)
  | l :: rest =>
      let key := N.succ_pos (nat_n l) in
      match trie_get key inv with
      | Some pos =>
          let count' := match trie_get key used with
            | Some _ => count
            | None => N.succ count
            end in
          match column_perm inv rest (PTrieCode.set key tt used) count' with
          | Some (perm, used', count'') => Some (pos :: perm, used', count'')
          | None => None
          end
      | None => None
      end
  end.
TimeFun column_perm.

Definition slot_matches (table : ptrie (N * (positive * list nat))) (f : positive)
    (perm : list nat) (s : N) : bool :=
  match trie_get (slot_code f perm) table with
  | Some (s', (f', perm')) =>
      if N.eqb s' s then if Pos.eqb f' f then nats_eqb perm' perm else false else false
  | None => false
  end.
TimeFun slot_matches.

Definition source_slot {V : Type} (newok : bool) (src : source V) : option N :=
  match src with
  | All _ s => Some s
  | New _ s => if newok then Some s else None
  | Const _ _ => None
  end.
TimeFun source_slot.

(** A function atom reads one slot source whose slot lays out its positions by join variable,
    and then the constant sources of its literals. *)
Definition check_atom {V : Type} (eqb : V -> V -> bool) (newok : bool) (names : ptrie N)
    (n : nat) (table : ptrie (N * (positive * list nat))) (f : positive) (ts : list (term V))
    (copy : N) (used : ptrie unit) (count : N) (srcs : list (source V))
    (cols : list (list nat))
    : option (N * ptrie unit * N * list (source V) * list (list nat) * bool) :=
  match srcs, cols with
  | src :: srcs', lv :: cols' =>
      match source_slot newok src with
      | Some s =>
          if column_ok n lv None then
            if Nat.eqb (length lv) (length ts) then
              match check_terms eqb names ts 0 Empty copy Empty srcs' cols' false with
              | Some (copy', inv, srcs'', cols'', copied) =>
                  match column_perm inv lv used count with
                  | Some (perm, used', count') =>
                      if slot_matches table f perm s then
                        Some (copy', used', count', srcs'', cols'', copied)
                      else None
                  | None => None
                  end
              | None => None
              end
            else None
          else None
      | None => None
      end
  | _, _ => None
  end.
TimeFun check_atom.

(** The query check returns the count of used join variables, the unread sources and columns,
    and the reversed post list that the query requires. *)
Fixpoint check_query {V : Type} (eqb : V -> V -> bool) (newok : bool) (names : ptrie N)
    (n : nat) (table : ptrie (N * (positive * list nat))) (q : list (atom V)) (ai : nat)
    (copy : N) (used : ptrie unit) (count : N) (srcs : list (source V))
    (cols : list (list nat)) (post : list nat)
    : option (N * list (source V) * list (list nat) * list nat) :=
  match q with
  | [] => Some (count, srcs, cols, post)
  | Prim _ _ _ _ :: rest =>
      check_query eqb newok names n table rest (S ai) copy used count srcs cols (ai :: post)
  | Fun _ f args res :: rest =>
      match check_atom eqb newok names n table f (args ++ option_list res) copy used count
          srcs cols with
      | Some (copy', used', count', srcs', cols', copied) =>
          check_query eqb newok names n table rest (S ai) copy' used' count' srcs' cols'
            (if copied then ai :: post else post)
      | None => None
      end
  end.
TimeFun check_query.

(** Copy variables precede the real variables and have names above every query variable.
    Later fresh names are the only indices that a literal may use. *)
Fixpoint layout_fresh (bound : positive) (copies : nat) (vars : list positive)
    (j : N) (allowed : ptrie unit) : option (ptrie unit) :=
  match vars with
  | [] =>
      match copies with
      | O => Some allowed
      | S _ => None
      end
  | x :: rest =>
      match copies with
      | S copies' =>
          if Pos.ltb bound x then layout_fresh bound copies' rest (N.succ j) allowed
          else None
      | O =>
          let allowed' := if Pos.ltb bound x
            then PTrieCode.set (N.succ_pos j) tt allowed else allowed in
          layout_fresh bound 0 rest (N.succ j) allowed'
      end
  end.
TimeFun layout_fresh.

(** A literal consumes one fresh noncopy index, which no later literal may reuse. *)
Fixpoint layout_literals {V : Type} (srcs : list (source V)) (cols : list (list nat))
    (allowed : ptrie unit) : bool :=
  match srcs, cols with
  | [], [] => true
  | Const _ _ :: rest, [j] :: tail =>
      let key := N.succ_pos (nat_n j) in
      match trie_get key allowed with
      | Some _ => layout_literals rest tail (PTrieCode.remove key allowed)
      | None => false
      end
  | All _ _ :: rest, _ :: tail | New _ _ :: rest, _ :: tail =>
      layout_literals rest tail allowed
  | _, _ => false
  end.
TimeFun layout_literals.

(** Copies, query variables and literals occupy separate join variables. *)
Definition layout_ok {V : Type} (q : list (atom V)) (vars : list positive)
    (srcs : list (source V)) (cols : list (list nat)) : bool :=
  match layout_fresh (query_max q 1%positive) (query_copies q 0) vars 0 Empty with
  | Some allowed => layout_literals srcs cols allowed
  | None => false
  end.
TimeFun layout_ok.

(** A plan names its rule, uses every join variable and lists the post filter of its query. *)
Definition check_cplan {V : Type} (eqb : V -> V -> bool) (newok : bool)
    (table : ptrie (N * (positive * list nat))) (i : N) (r : rule V) (c : cplan V) : bool :=
  match r, c with
  | Rule _ q _, CPlan _ ix (JPlan n cols) srcs vars post =>
      if N.eqb ix i then
        if Nat.eqb (length vars) n then
          match var_table vars 0 Empty with
          | Some names =>
              if layout_ok q vars srcs cols then
                match check_query eqb newok names n table q 0 0 Empty 0 srcs cols [] with
                | Some (count, [], [], expected) =>
                    if N.eqb count (nat_n n) then nats_eqb (rev_append expected []) post
                    else false
                | _ => false
                end
              else false
          | None => false
          end
        else false
      else false
  end.
TimeFun check_cplan.

(** The layout check with the query's largest variable and copy count already computed. *)
Definition layout_ok_at {V : Type} (bound : positive) (copies : nat) (vars : list positive)
    (srcs : list (source V)) (cols : list (list nat)) : bool :=
  match layout_fresh bound copies vars 0 Empty with
  | Some allowed => layout_literals srcs cols allowed
  | None => false
  end.
TimeFun layout_ok_at.

(** The plan check with the query's largest variable and copy count already computed, so that
    a rule's plans share one scan of the query. *)
Definition check_cplan_at {V : Type} (bound : positive) (copies : nat) (eqb : V -> V -> bool)
    (newok : bool) (table : ptrie (N * (positive * list nat))) (i : N) (r : rule V)
    (c : cplan V) : bool :=
  match r, c with
  | Rule _ q _, CPlan _ ix (JPlan n cols) srcs vars post =>
      if N.eqb ix i then
        if Nat.eqb (length vars) n then
          match var_table vars 0 Empty with
          | Some names =>
              if layout_ok_at bound copies vars srcs cols then
                match check_query eqb newok names n table q 0 0 Empty 0 srcs cols [] with
                | Some (count, [], [], expected) =>
                    if N.eqb count (nat_n n) then nats_eqb (rev_append expected []) post
                    else false
                | _ => false
                end
              else false
          | None => false
          end
        else false
      else false
  end.
TimeFun check_cplan_at.

(** Scanning the query once agrees with scanning it for every plan. *)
Lemma check_cplan_at_agrees : forall {V : Type} (eqb : V -> V -> bool) newok table i q acts c,
  check_cplan eqb newok table i (Rule V q acts) c =
  check_cplan_at (query_max q 1%positive) (query_copies q 0) eqb newok table i
    (Rule V q acts) c.
Proof.
  intros V eqb newok table i q acts [ix [n cols] srcs vars post]. reflexivity.
Qed.

Fixpoint fun_count {V : Type} (q : list (atom V)) : nat :=
  match q with
  | [] => O
  | Fun _ _ _ _ :: rest => S (fun_count rest)
  | Prim _ _ _ _ :: rest => fun_count rest
  end.
TimeFun fun_count.

Fixpoint check_semis {V : Type} (eqb : V -> V -> bool)
    (table : ptrie (N * (positive * list nat))) (i : N) (r : rule V) (k : nat)
    (cs : list (cplan V)) : option (list (cplan V)) :=
  match k with
  | O => Some cs
  | S k' =>
      match cs with
      | [] => None
      | c :: rest =>
          if check_cplan eqb true table i r c then check_semis eqb table i r k' rest else None
      end
  end.
TimeFun check_semis.

(** Each rule has one naive plan and one semi-naive plan per function atom, in rule order. *)
Fixpoint check_rule_plans {V : Type} (eqb : V -> V -> bool)
    (table : ptrie (N * (positive * list nat))) (rs : list (rule V)) (i : N)
    (naive semi : list (cplan V)) : bool :=
  match rs, naive with
  | [], [] =>
      match semi with
      | [] => true
      | _ :: _ => false
      end
  | r :: rest, c :: naive' =>
      if check_cplan eqb false table i r c then
        match r with
        | Rule _ q _ =>
            match check_semis eqb table i r (fun_count q) semi with
            | Some semi' => check_rule_plans eqb table rest (N.succ i) naive' semi'
            | None => false
            end
        end
      else false
  | _, _ => false
  end.
TimeFun check_rule_plans.

(** The semi-naive plan check with the rule's scan results passed in. *)
Fixpoint check_semis_at {V : Type} (bound : positive) (copies : nat) (eqb : V -> V -> bool)
    (table : ptrie (N * (positive * list nat))) (i : N) (r : rule V) (k : nat)
    (cs : list (cplan V)) : option (list (cplan V)) :=
  match k with
  | O => Some cs
  | S k' =>
      match cs with
      | [] => None
      | c :: rest =>
          if check_cplan_at bound copies eqb true table i r c then
            check_semis_at bound copies eqb table i r k' rest
          else None
      end
  end.
TimeFun check_semis_at.

(** The rule plan check scans each rule's query once and shares the result among its plans. *)
Fixpoint check_rule_plans_at {V : Type} (eqb : V -> V -> bool)
    (table : ptrie (N * (positive * list nat))) (rs : list (rule V)) (i : N)
    (naive semi : list (cplan V)) : bool :=
  match rs, naive with
  | [], [] =>
      match semi with
      | [] => true
      | _ :: _ => false
      end
  | r :: rest, c :: naive' =>
      match r with
      | Rule _ q _ =>
          let bound := query_max q 1%positive in
          let copies := query_copies q 0 in
          if check_cplan_at bound copies eqb false table i r c then
            match check_semis_at bound copies eqb table i r (fun_count q) semi with
            | Some semi' => check_rule_plans_at eqb table rest (N.succ i) naive' semi'
            | None => false
            end
          else false
      end
  | _, _ => false
  end.
TimeFun check_rule_plans_at.

Lemma check_semis_at_agrees : forall {V : Type} (eqb : V -> V -> bool) table i q acts k cs,
  check_semis eqb table i (Rule V q acts) k cs =
  check_semis_at (query_max q 1%positive) (query_copies q 0) eqb table i (Rule V q acts) k cs.
Proof.
  intros V eqb table i q acts k. induction k as [|k IH]; intros [|c cs]; try reflexivity.
  cbn [check_semis check_semis_at]. rewrite check_cplan_at_agrees.
  destruct (check_cplan_at _ _ _ _ _ _ _ _); [apply IH|reflexivity].
Qed.

(** Sharing the scans does not change the shape check's answer. *)
Lemma check_rule_plans_at_agrees : forall {V : Type} (eqb : V -> V -> bool) table rs i naive semi,
  check_rule_plans_at eqb table rs i naive semi = check_rule_plans eqb table rs i naive semi.
Proof.
  intros V eqb table rs. induction rs as [|[q acts] rs IH]; intros i naive semi.
  - destruct naive; reflexivity.
  - destruct naive as [|c naive]; [reflexivity|].
    cbn [check_rule_plans_at check_rule_plans]. rewrite check_cplan_at_agrees.
    destruct (check_cplan_at _ _ _ _ _ _ _ _); [|reflexivity].
    rewrite check_semis_at_agrees.
    destruct (check_semis_at _ _ _ _ _ _ _ _); [apply IH|reflexivity].
Qed.

(** The shape check validates the slots and then every plan against its rule. *)
Definition check_shape_with {V : Type} (eqb : V -> V -> bool) (p : program V)
    (cp : compiled V) : bool :=
  match p, cp with
  | Program _ ds rs, Compiled _ sl naive semi =>
      match slot_table (decl_widths ds Empty) sl 0 Empty with
      | Some table => check_rule_plans_at eqb table rs 0 naive semi
      | None => false
      end
  end.
TimeFun check_shape_with.

(** * Finite universes *)

(** Every tuple of a width over the listed values. *)
Fixpoint value_tuples {V : Type} (n : nat) (vs : list V) : list (list (cell V)) :=
  match n with
  | O => [[]]
  | S m => flat_map (fun v => map (fun k => Val v :: k) (value_tuples m vs)) vs
  end.

(** The first declaration of each relation name, with its arity. *)
Fixpoint relation_arities (ds : list decl) (seen : list positive) : list (positive * nat) :=
  match ds with
  | [] => []
  | Decl f ss o :: rest =>
      if existsb (Pos.eqb f) seen then relation_arities rest seen
      else
        match o with
        | ORel => (f, length ss) :: relation_arities rest (f :: seen)
        | _ => relation_arities rest (f :: seen)
        end
  end.

(** A value is kept unless an equal value was kept before it. *)
Definition distinct_values {V : Type} (eqb : V -> V -> bool) (vs : list V) : list V :=
  fold_left (fun acc v => if existsb (eqb v) acc then acc else v :: acc) vs [].

Definition program_literals {V : Type} (p : program V) : list V :=
  flat_map (fun t => match t with
    | Lit v => [v]
    | Var _ => []
    end) (program_terms p).

Module RunCode (V : VALUE_OPS) (I : INDEX_OPS V) (J : JOIN_OPS V I)
    (D : DATABASE_OPS V I) <: RUN_OPS V I J D.
  Definition plan (p : program V.t) : compiled V.t := plan_program p.

  Definition check_shape (p : program V.t) (cp : compiled V.t) : bool :=
    check_shape_with V.eqb p cp.

  Definition check_plan (p : program V.t) (cp : compiled V.t) : bool :=
    check_program p && check_shape p cp.

  Definition load (p : program V.t) (cp : compiled V.t) : D.t :=
    D.init (decls V.t p) (compiled_slots cp).

  (** Actions run in order. A failed term lookup or primitive ends the application, and a union
      of two values changes nothing. *)
  Fixpoint apply_go (acts : list (action V.t)) (s : Model.env (V := V.t))
      (locals : ptrie (cell V.t)) (db : D.t) : D.t :=
    match acts with
    | [] => db
    | Make x f args :: rest =>
        match term_cells s locals args with
        | Some cells =>
            let '(i, db') := D.make f cells db in
            apply_go rest s (PTrieCode.set x (Id i) locals) db'
        | None => db
        end
    | Put f args res :: rest =>
        match term_cells s locals args, result_cell s locals res with
        | Some cells, Some out => apply_go rest s locals (D.put f cells out db)
        | _, _ => db
        end
    | Union a b :: rest =>
        match term_cell s locals a, term_cell s locals b with
        | Some (Id i), Some (Id j) => apply_go rest s locals (D.union i j db)
        | Some _, Some _ => apply_go rest s locals db
        | _, _ => db
        end
    | Let x p args :: rest =>
        match term_values s locals args with
        | Some vs =>
            match V.prim p vs with
            | Some v => apply_go rest s (PTrieCode.set x (Val v) locals) db
            | None => db
            end
        | None => db
        end
    end.

  Definition apply (acts : list (action V.t)) (s : Model.env (V := V.t)) (db : D.t) : D.t :=
    apply_go acts s Empty db.

  Definition bind_trie (c : cplan V.t) (b : list (cell V.t)) : ptrie (cell V.t) :=
    bind_cells (plan_vars c) b Empty.

  (** The post filter reads the copy names at the front of the plan's variables. *)
  Definition keep (p : program V.t) (c : cplan V.t) (t : ptrie (cell V.t)) : bool :=
    match rule_at (plan_rule_ix c) (rules V.t p) with
    | Rule _ q _ => keep_post V.prim V.eqb q t (plan_post c) (plan_vars c)
    end.

  Definition source_ix (db : D.t) (s : source V.t) : I.t :=
    match s with
    | All _ slot => D.index slot false db
    | New _ slot => D.index slot true db
    | Const _ c => I.insert [c] I.empty
    end.

  Definition plan_bindings (_ : compiled V.t) (c : cplan V.t) (db : D.t)
      : list (list (cell V.t)) :=
    J.run (plan_join c) (map (source_ix db) (plan_sources c)).

  Definition jobs (p : program V.t) (cp : compiled V.t) (nv : bool) (db : D.t)
      : list (cplan V.t * list (cell V.t)) :=
    flat_map (fun c => map (fun b => (c, b))
        (filter (fun b => keep p c (bind_trie c b)) (plan_bindings cp c db)))
      (if nv then compiled_naive cp else compiled_semi cp).

  (** Each job builds its binding trie once and applies the actions of its rule. *)
  Fixpoint apply_all (p : program V.t) (js : list (cplan V.t * list (cell V.t))) (db : D.t)
      : D.t :=
    match js with
    | [] => db
    | (c, b) :: rest =>
        let t := bind_trie c b in
        apply_all p rest
          (apply (actions V.t (rule_at (plan_rule_ix c) (rules V.t p)))
            (fun x => trie_get x t) db)
    end.

  (** Read the current delta, then clear it before applying jobs to form the next delta. *)
  Definition round (p : program V.t) (cp : compiled V.t) (nv : bool) (db : D.t) : D.t :=
    D.rebuild (apply_all p (jobs p cp nv db) (D.advance db)).

  (** Keep the round's delta for the next step. A quiet semi-naive round is followed by a
      naive round, and a quiet naive round saturates. *)
  Definition driver (p : program V.t) (cp : compiled V.t) (lim : limits) (st : bool * D.t)
      : (bool * D.t) + (stop * D.t) :=
    let '(nv, db) := st in
    let next := round p cp nv db in
    if N.ltb (limits_ids lim) (D.ids next) then inr (IdLimit, next)
    else if andb nv (negb (D.changed next)) then inr (Saturated, next)
    else inl (negb (D.changed next), next).

  (** The final rebuild makes the result canonical even when the fuel is zero. *)
  Definition run (p : program V.t) (cp : compiled V.t) (lim : limits) (db : D.t)
      : stop * D.t :=
    match loopN (driver p cp lim) (limits_iter lim) (false, db) with
    | inl (_, final) => (IterLimit, D.rebuild final)
    | inr (st, final) => (st, D.rebuild final)
    end.
End RunCode.

Module Run (V : VALUE) (I : INDEX V) (J : JOIN V I) (D : DATABASE V I) <: RUN V I J D.
  Include RunCode V I J D.
  Include RUN_SPEC V I J D.

  (** The cells on the edges below a node, down to the slot's tuple width. *)
  Fixpoint index_cells (fuel : nat) (ix : I.t) (n : positive) : list (cell V.t) :=
    match fuel with
    | O => []
    | S fuel' =>
        flat_map (fun c => c ::
            match I.child ix n c with
            | Some m => index_cells fuel' ix m
            | None => []
            end) (I.children ix n)
    end.

  (** The values stored in the full index of every slot from number [s] on. *)
  Fixpoint slot_values (db : D.t) (s : nat) (sl : list (positive * list nat)) : list V.t :=
    match sl with
    | [] => []
    | (_, perm) :: rest =>
        let ix := D.index (N.of_nat s) false db in
        flat_map (fun c => match c with
            | Val v => [v]
            | Id _ => []
            end) (index_cells (length perm) ix (I.root ix)) ++
          slot_values db (S s) rest
    end.

  (** The universe pairs each relation with every tuple of its arity over the distinct active
      values. *)
  Definition universe (p : program V.t) (db : D.t) : list (positive * list (cell V.t)) :=
    let vs := distinct_values V.eqb (program_literals p ++ slot_values db 0 (D.slots db)) in
    flat_map (fun fa => map (fun k => (fst fa, k)) (value_tuples (snd fa) vs))
      (relation_arities (decls V.t p) []).

  Definition active_value (p : program V.t) (db : D.t) (v : V.t) : Prop :=
    In (Lit v) (program_terms p) \/
    exists s u, N.to_nat s < length (D.slots db) /\ I.mem (D.index s false db) u /\
      In (Val v) u.

  Definition herbrand (p : program V.t) (db : D.t) : nat := length (universe p db).

  Lemma herbrand_spec : forall p db, herbrand p db = length (universe p db).
  Proof.
    reflexivity.
  Qed.

  (** A binding can add only the variable that its term names. *)
  Lemma run_binds_scope : forall g (t : term V.t) s g',
    binds g t s g' -> forall x u, g' x = Some u -> g x = Some u \/ t = Var x.
  Proof.
    intros g t s g' Hbind. destruct Hbind as [y s Hsort|y s Hnone|v];
      intros x u H; try (left; exact H).
    unfold ctx_set in H. destruct (Pos.eqb y x) eqn:Hyx.
    - apply Pos.eqb_eq in Hyx. subst x. right. reflexivity.
    - left. exact H.
  Qed.

  (** Binding arguments adds only variables appearing among those arguments. *)
  Lemma run_binds_list_scope : forall g ts ss g',
    @binds_list V.t g ts ss g' -> forall x u,
    g' x = Some u -> g x = Some u \/ In (Var x) ts.
  Proof.
    intros g ts ss g' Hbind. induction Hbind as [g|g g1 g2 t ts s ss Hhead Htail IH];
      intros x u Hsort.
    - left. exact Hsort.
    - destruct (IH x u Hsort) as [Hbound|Hin].
      + destruct (run_binds_scope g t s g1 Hhead x u Hbound) as [Hold|Heq].
        * left. exact Hold.
        * right. left. exact Heq.
      + right. right. exact Hin.
  Qed.

  (** Binding a result adds only its result variable. *)
  Lemma run_binds_result_scope : forall g out res g',
    @binds_result V.t g out res g' -> forall x u,
    g' x = Some u -> g x = Some u \/ In (Var x) (option_list res).
  Proof.
    intros g out [t|] g' Hbind; destruct out;
      cbn [binds_result out_sort] in Hbind; try contradiction;
      intros x u Hsort.
    - destruct (run_binds_scope g t SId g' Hbind x u Hsort) as [Hold|Heq];
        [left; exact Hold|right; left; exact Heq].
    - destruct (run_binds_scope g t SVal g' Hbind x u Hsort) as [Hold|Heq];
        [left; exact Hold|right; left; exact Heq].
    - subst g'. left. exact Hsort.
  Qed.

  (** Every variable added by a query occurs in one of that query's atoms. *)
  Lemma run_query_scope : forall sorts kinds g q g',
    @query_ok V.t sorts kinds g q g' -> forall x s,
    g' x = Some s -> g x = Some s \/
      exists a, In a q /\ In (Var x) (atom_terms a).
  Proof.
    intros sorts kinds g q g' Hquery.
    induction Hquery as
      [g|g g1 g2 g3 f args res ss out rest Hsort Hkind Hreads Hargs Hres Hrest IH|
       g g1 op args res rest Hargs Hres Hrest IH]; intros x s Hbound.
    - left. exact Hbound.
    - destruct (IH x s Hbound) as [Hnew|[a [Hin Hvar]]].
      + destruct (run_binds_result_scope g1 out res g2 Hres x s Hnew) as [Harg|Hvar].
        * destruct (run_binds_list_scope g args ss g1 Hargs x s Harg) as [Hold|Hvar].
          -- left. exact Hold.
          -- right. exists (Fun V.t f args res). split; [left; reflexivity|].
             cbn [atom_terms]. apply in_or_app. left. exact Hvar.
        * right. exists (Fun V.t f args res). split; [left; reflexivity|].
          cbn [atom_terms]. apply in_or_app. right. exact Hvar.
      + right. exists a. split; [right; exact Hin|exact Hvar].
    - destruct (IH x s Hbound) as [Hold|[a [Hin Hvar]]].
      + left. exact Hold.
      + right. exists a. split; [right; exact Hin|exact Hvar].
  Qed.

  (** The variable list of an atom is the concatenation of its term variable lists. *)
  Lemma run_atom_vars_terms : forall a : atom V.t,
    atom_vars a = flat_map term_vars (atom_terms a).
  Proof.
    intros [f args res|f args res]; cbn [atom_vars atom_terms]; rewrite flat_map_app.
    - reflexivity.
    - cbn. now rewrite app_nil_r.
  Qed.

  (** A typed term gives a context binding for each variable that it reads. *)
  Lemma run_has_scope : forall g (t : term V.t) s x,
    has g t s -> In x (term_vars t) -> exists u, g x = Some u.
  Proof.
    intros g [y|v] s x Hhas Hin; cbn [has term_vars] in *.
    - destruct Hin as [<-|Hin]; [exists s; exact Hhas|contradiction].
    - contradiction.
  Qed.

  (** A list of typed arguments reads only variables bound in its context. *)
  Lemma run_has_list_scope : forall g ts ss,
    Forall2 (@has V.t g) ts ss -> forall x,
    In x (flat_map term_vars ts) -> exists u, g x = Some u.
  Proof.
    intros g ts ss Htyped. induction Htyped as [|t s ts ss Hhead Htail IH]; intros x Hin.
    - contradiction.
    - cbn [flat_map] in Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
      + eapply run_has_scope; eassumption.
      + apply IH. exact Hin.
  Qed.

  (** A sorted action reads only variables already bound in its starting context. *)
  Lemma run_action_scope : forall sorts kinds g a rest,
    @actions_ok V.t sorts kinds g (a :: rest) -> forall x,
    In x (flat_map term_vars (action_terms a)) -> exists u, g x = Some u.
  Proof.
    intros sorts kinds g [y f args|f args res|t u|y op args] rest Hok x Hin;
      cbn [actions_ok action_terms] in Hok, Hin.
    - destruct Hok as [ss [Hsort [Hkind [Hargs Hrest]]]].
      eapply run_has_list_scope; eassumption.
    - destruct Hok as [ss [out [Hsort [Hkind [Hargs [Hres Hrest]]]]]].
      rewrite flat_map_app in Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
      + eapply run_has_list_scope; eassumption.
      + destruct res as [t|]; [|contradiction].
        cbn [option_list flat_map] in Hin. rewrite app_nil_r in Hin.
        destruct out; cbn [has_result out_sort] in Hres; try contradiction;
          eapply run_has_scope; eassumption.
    - destruct Hok as [Ht [Hu Hrest]]. cbn [flat_map] in Hin.
      rewrite app_nil_r in Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
      + eapply run_has_scope; [exact Ht|exact Hin].
      + eapply run_has_scope; [exact Hu|exact Hin].
    - destruct Hok as [Hargs Hrest]. apply in_flat_map in Hin.
      destruct Hin as [t [Hterm Hvar]]. rewrite Forall_forall in Hargs.
      eapply run_has_scope; [apply Hargs; exact Hterm|exact Hvar].
  Qed.

  (** An action prefix makes available only its explicit bindings. *)
  Lemma run_actions_prefix_scope : forall sorts kinds pre g a rest x,
    @actions_ok V.t sorts kinds g (pre ++ a :: rest) ->
    In x (flat_map term_vars (action_terms a)) ->
    (exists u, g x = Some u) \/ In x (flat_map action_binds pre).
  Proof.
    intros sorts kinds pre. induction pre as [|h pre IH]; intros g a rest x Hok Hin.
    - left. eapply run_action_scope; eassumption.
    - destruct h as [y f args|f args res|t u|y op args];
        cbn [app actions_ok flat_map action_binds] in Hok |- *.
      + destruct Hok as [ss [Hsort [Hkind [Hargs Hrest]]]].
        destruct (IH _ _ _ _ Hrest Hin) as [[s Hbound]|Hbound].
        * unfold ctx_set in Hbound. destruct (Pos.eqb y x) eqn:Heq.
          -- apply Pos.eqb_eq in Heq. right. left. exact Heq.
          -- left. exists s. exact Hbound.
        * right. right. exact Hbound.
      + destruct Hok as [ss [out [Hsort [Hkind [Hargs [Hres Hrest]]]]]].
        exact (IH _ _ _ _ Hrest Hin).
      + destruct Hok as [Ht [Hu Hrest]]. exact (IH _ _ _ _ Hrest Hin).
      + destruct Hok as [Hargs Hrest].
        destruct (IH _ _ _ _ Hrest Hin) as [[s Hbound]|Hbound].
        * unfold ctx_set in Hbound. destruct (Pos.eqb y x) eqn:Heq.
          -- apply Pos.eqb_eq in Heq. right. left. exact Heq.
          -- left. exists s. exact Hbound.
        * right. right. exact Hbound.
  Qed.

  (** Checked actions read only variables bound by the query or earlier actions. *)
  Lemma check_plan_scope : forall p cp r pre a rest x, plans_ok p cp ->
    In r (rules V.t p) -> actions V.t r = pre ++ a :: rest ->
    In x (flat_map term_vars (action_terms a)) ->
    In x (flat_map atom_vars (query V.t r) ++ flat_map action_binds pre).
  Proof.
    intros p cp r pre a rest x Hchecked Hrule Hacts Hvar.
    unfold plans_ok, check_plan in Hchecked. apply andb_true_iff in Hchecked.
    pose proof (proj1 (check_program_spec V.t p) (proj1 Hchecked)) as Hprogram.
    unfold program_ok in Hprogram. rewrite Forall_forall in Hprogram.
    destruct (Hprogram r Hrule) as [g [Hquery Hactions]].
    rewrite Hacts in Hactions.
    destruct (run_actions_prefix_scope _ _ pre g a rest x Hactions Hvar)
      as [[s Hbound]|Hbound]; apply in_or_app.
    - left. destruct (run_query_scope _ _ _ _ _ Hquery x s Hbound)
        as [Hempty|[b [Hatom Hterm]]]; [discriminate|].
      apply in_flat_map. exists b. split; [exact Hatom|].
      rewrite run_atom_vars_terms. apply in_flat_map. exists (Var x).
      split; [exact Hterm|left; reflexivity].
    - right. exact Hbound.
  Qed.

  (** A declaration found by name has the same sorts and kind as both program lookups. *)
  Lemma run_find_decl_fields : forall ds f d,
    find (fun d => Pos.eqb (name d) f) ds = Some d ->
    lookup_sorts ds f = Some (arg_sorts d) /\ lookup_kind ds f = Some (out d).
  Proof.
    intros ds. induction ds as [|h ds IH]; intros f d Hfind; [discriminate|].
    cbn [find lookup_sorts lookup_kind] in *.
    destruct (Pos.eqb (name h) f) eqn:Heq.
    - injection Hfind as <-. split; reflexivity.
    - apply IH. exact Hfind.
  Qed.

  (** A successful sort lookup names the first matching declaration. *)
  Lemma run_lookup_sorts_decl : forall ds f ss,
    lookup_sorts ds f = Some ss ->
    exists d, find (fun d => Pos.eqb (name d) f) ds = Some d /\ arg_sorts d = ss.
  Proof.
    intros ds. induction ds as [|h ds IH]; intros f ss Hsort; [discriminate|].
    cbn [lookup_sorts find] in *. destruct (Pos.eqb (name h) f) eqn:Heq.
    - exists h. split; [reflexivity|]. injection Hsort as Hsort. exact Hsort.
    - apply IH. exact Hsort.
  Qed.

  (** * Finite universe enumeration *)

  (** Mapping an injective function preserves absence of duplicates. *)
  Lemma run_map_nodup : forall (A B : Type) (f : A -> B) xs,
    (forall x y, f x = f y -> x = y) -> NoDup xs -> NoDup (map f xs).
  Proof.
    intros A B f xs Hinjective Hdistinct.
    induction Hdistinct as [|x xs Hfresh Htail IH]; cbn [map]; constructor.
    - intro Hin. apply in_map_iff in Hin as [y [Heq Hy]].
      apply Hinjective in Heq. subst y. contradiction.
    - exact IH.
  Qed.

  (** Value equality tests recognize list membership. *)
  Lemma run_value_seen : forall (v : V.t) vs, existsb (V.eqb v) vs = true <-> In v vs.
  Proof.
    intros v vs. split.
    - intro Hseen. apply existsb_exists in Hseen as [w [Hin Heq]].
      destruct (V.eqb_spec v w) as [->|Hdifferent]; [exact Hin|discriminate].
    - intro Hin. apply existsb_exists. exists v. split; [exact Hin|].
      destruct (V.eqb_spec v v); [reflexivity|contradiction].
  Qed.

  (** One distinct-value insertion adds exactly its supplied value. *)
  Lemma run_distinct_step_member : forall (vs : list V.t) v w,
    In w (if existsb (V.eqb v) vs then vs else v :: vs) <-> w = v \/ In w vs.
  Proof.
    intros vs v w. destruct (existsb (V.eqb v) vs) eqn:Hseen.
    - apply run_value_seen in Hseen. split; [now right|].
      intros [->|Hin]; assumption.
    - cbn [In]. intuition congruence.
  Qed.

  (** The distinct-value fold retains exactly its input and accumulator members. *)
  Lemma run_distinct_fold_member : forall vs acc (v : V.t),
    In v (fold_left (fun acc w => if existsb (V.eqb w) acc then acc else w :: acc) vs acc)
      <-> In v vs \/ In v acc.
  Proof.
    induction vs as [|w vs IH]; intros acc v; cbn [fold_left].
    - cbn [In]. tauto.
    - rewrite IH, run_distinct_step_member. cbn [In]. intuition congruence.
  Qed.

  (** The distinct-value fold preserves a duplicate-free accumulator. *)
  Lemma run_distinct_fold_nodup : forall vs acc,
    NoDup acc ->
    NoDup (fold_left (fun acc (v : V.t) =>
      if existsb (V.eqb v) acc then acc else v :: acc) vs acc).
  Proof.
    induction vs as [|v vs IH]; intros acc Hdistinct; cbn [fold_left]; [exact Hdistinct|].
    apply IH. destruct (existsb (V.eqb v) acc) eqn:Hseen; [exact Hdistinct|].
    constructor; [|exact Hdistinct]. intro Hin.
    pose proof (proj2 (run_value_seen v acc) Hin) as Htrue. congruence.
  Qed.

  (** Distinct values have precisely the original membership. *)
  Lemma run_distinct_values_member : forall (vs : list V.t) v,
    In v (distinct_values V.eqb vs) <-> In v vs.
  Proof.
    intros vs v. unfold distinct_values. rewrite run_distinct_fold_member. cbn [In]. tauto.
  Qed.

  (** Deduplication succeeds independently of where the values were collected. *)
  Lemma run_distinct_values_nodup : forall vs : list V.t, NoDup (distinct_values V.eqb vs).
  Proof.
    intro vs. unfold distinct_values. apply run_distinct_fold_nodup. constructor.
  Qed.

  (** Different value prefixes keep duplicate-free tuple families disjoint. *)
  Lemma run_value_prefixes_nodup : forall (vs : list V.t) ks,
    NoDup vs -> NoDup ks ->
    NoDup (flat_map (fun v => map (fun k => Val v :: k) ks) vs).
  Proof.
    intros vs ks Hvalues Htuples. induction Hvalues as [|v vs Hfresh Htail IH];
      cbn [flat_map]; [constructor|].
    apply NoDup_app; [|exact IH|].
    - apply run_map_nodup; [intros a b Heq; now injection Heq|exact Htuples].
    - intros key Hhere Hthere. apply in_map_iff in Hhere as [k [Heq Hk]].
      apply in_flat_map in Hthere as [w [Hw Hthere]].
      apply in_map_iff in Hthere as [tail [Hother Htailkey]].
      assert (v = w) by congruence. subst w. contradiction.
  Qed.

  (** Cartesian tuples over distinct values are duplicate free at every width. *)
  Lemma run_value_tuples_nodup : forall n (vs : list V.t),
    NoDup vs -> NoDup (value_tuples n vs).
  Proof.
    induction n as [|n IH]; intros vs Hvalues; cbn [value_tuples].
    - constructor; [intro Hin; contradiction|constructor].
    - apply run_value_prefixes_nodup; [exact Hvalues|now apply IH].
  Qed.

  (** Cartesian enumeration gives exactly the tuples of its width over the supplied values. *)
  Lemma run_value_tuples_member : forall n (vs : list V.t) k,
    In k (value_tuples n vs) <-> length k = n /\
      Forall (fun c => exists v, c = Val v /\ In v vs) k.
  Proof.
    induction n as [|n IH]; intros vs k; split.
    - cbn [value_tuples] in *. intros [<-|Hbad]; [split; [reflexivity|constructor]|contradiction].
    - intros [Hlength Hvalues]. destruct k; [now left|discriminate].
    - intro Hin. cbn [value_tuples] in Hin.
      apply in_flat_map in Hin as [v [Hv Hin]].
      apply in_map_iff in Hin as [tail [<- Htail]].
      apply IH in Htail as [Hlength Hvalues]. split; [cbn; now rewrite Hlength|].
      constructor; [exists v; auto|exact Hvalues].
    - intros [Hlength Hvalues]. destruct k as [|c k]; [discriminate|].
      inversion Hvalues as [|c' k' Hhead Htail]; subst c' k'.
      destruct Hhead as [v [-> Hv]]. cbn [value_tuples].
      apply in_flat_map. exists v. split; [exact Hv|]. apply in_map.
      apply IH. split; [now injection Hlength|exact Htail].
  Qed.

  (** Positive-name equality tests recognize the seen-name list. *)
  Lemma run_positive_seen : forall f seen, existsb (Pos.eqb f) seen = true <-> In f seen.
  Proof.
    intros f seen. split.
    - intro Hseen. apply existsb_exists in Hseen as [g [Hin Heq]].
      apply Pos.eqb_eq in Heq. now subst g.
    - intro Hin. apply existsb_exists. exists f. split; [exact Hin|apply Pos.eqb_refl].
  Qed.

  (** An emitted relation arity comes from the first unseen declaration of that name. *)
  Lemma run_relation_arities_sound : forall ds seen f n,
    In (f, n) (relation_arities ds seen) -> ~ In f seen /\
    exists d, find (fun d => Pos.eqb (name d) f) ds = Some d /\
      out d = ORel /\ length (arg_sorts d) = n.
  Proof.
    induction ds as [|[g ss kindout] ds IH]; intros seen f n Hin; [contradiction|].
    cbn [relation_arities] in Hin. destruct (existsb (Pos.eqb g) seen) eqn:Hseen.
    - destruct (IH seen f n Hin) as [Hfresh [d [Hfind [Hout Hwidth]]]].
      split; [exact Hfresh|]. exists d. split; [|auto].
      cbn [find name]. assert (Hdifferent : Pos.eqb g f = false).
      { apply Pos.eqb_neq. intro Heq. subst f. apply Hfresh. now apply run_positive_seen. }
      now rewrite Hdifferent.
    - destruct kindout; [destruct Hin as [Heq|Hin]| |].
      { injection Heq as <- <-. split.
        - intro Hmem. apply (proj2 (run_positive_seen g seen)) in Hmem. congruence.
        - exists (Decl g ss ORel). cbn [find name out arg_sorts].
          rewrite Pos.eqb_refl. auto. }
      all: destruct (IH (g :: seen) f n Hin) as [Hfresh [d [Hfind [Hout Hwidth]]]].
      all: split; [intro Hmem; apply Hfresh; now right|].
      all: exists d; split; [|auto].
      all: cbn [find name]; assert (Hdifferent : Pos.eqb g f = false).
      all: try (apply Pos.eqb_neq; intro Heq; subst f; apply Hfresh; now left).
      all: now rewrite Hdifferent.
  Qed.

  (** A first relational declaration is emitted whenever its name has not been seen. *)
  Lemma run_relation_arities_complete : forall ds seen f d,
    ~ In f seen -> find (fun d => Pos.eqb (name d) f) ds = Some d -> out d = ORel ->
    In (f, length (arg_sorts d)) (relation_arities ds seen).
  Proof.
    induction ds as [|[g ss kindout] ds IH]; intros seen f d Hfresh Hfind Hout;
      [discriminate|].
    cbn [find name] in Hfind. destruct (Pos.eqb g f) eqn:Hname.
    - apply Pos.eqb_eq in Hname. subst g. injection Hfind as <-.
      cbn [out] in Hout. subst kindout. cbn [relation_arities arg_sorts].
      destruct (existsb (Pos.eqb f) seen) eqn:Hseen; [|now left].
      exfalso. apply Hfresh. now apply run_positive_seen.
    - cbn [relation_arities]. destruct (existsb (Pos.eqb g) seen).
      + eapply IH; eassumption.
      + assert (Hnew : ~ In f (g :: seen)).
        { intros [Heq|Hin]; [subst g; rewrite Pos.eqb_refl in Hname; discriminate|contradiction]. }
        pose proof (IH (g :: seen) f d Hnew Hfind Hout) as Htail.
        destruct kindout; [now right|exact Htail|exact Htail].
  Qed.

  (** No relation name is emitted twice, even with malformed or repeated declarations. *)
  Lemma run_relation_arities_nodup : forall ds seen,
    NoDup (map fst (relation_arities ds seen)).
  Proof.
    induction ds as [|[f ss kindout] ds IH]; intro seen; cbn [relation_arities];
      [constructor|].
    destruct (existsb (Pos.eqb f) seen); [apply IH|].
    destruct kindout; try apply IH. cbn [map fst]. constructor; [|apply IH].
    intro Hin. apply in_map_iff in Hin as [[g n] [Heq Hin]]. cbn [fst] in Heq. subst g.
    destruct (run_relation_arities_sound ds (f :: seen) f n Hin) as [Hfresh Hdecl].
    apply Hfresh. now left.
  Qed.

  (** Distinct function names keep the Cartesian tuple families disjoint. *)
  Lemma run_relation_tuples_nodup : forall (arities : list (positive * nat)) (vs : list V.t),
    NoDup (map fst arities) -> NoDup vs ->
    NoDup (flat_map (fun fa => map (fun k => (fst fa, k))
      (value_tuples (snd fa) vs)) arities).
  Proof.
    intros arities vs. induction arities as [|[f n] rest IH]; intros Hnames Hvalues;
      cbn [flat_map]; [constructor|].
    inversion Hnames as [|f' names Hfresh Htail]; subst f' names.
    apply NoDup_app; [|now apply IH|].
    - apply run_map_nodup; [intros a b Heq; now injection Heq|].
      now apply run_value_tuples_nodup.
    - intros row Hhere Hthere. apply in_map_iff in Hhere as [k [Heq Hk]].
      apply in_flat_map in Hthere as [[g width] [Hin Hthere]].
      apply in_map_iff in Hthere as [key [Hother Hkey]]. cbn [fst snd] in *.
      assert (f = g) by congruence. subst g. apply Hfresh.
      apply in_map_iff. exists (f, width). split; [reflexivity|exact Hin].
  Qed.

  (** Universe deduplication needs no database or program well-formedness assumption. *)
  Lemma run_universe_nodup : forall p db, NoDup (universe p db).
  Proof.
    intros p db. unfold universe. apply run_relation_tuples_nodup.
    - apply run_relation_arities_nodup.
    - apply run_distinct_values_nodup.
  Qed.

  (** Every collected index edge lies in a member suffix below the current prefix. *)
  Lemma run_index_cells_sound : forall fuel a ix n pre c,
    I.wf a ix -> I.node ix n pre -> In c (index_cells fuel ix n) ->
    exists suffix, I.mem ix (pre ++ suffix) /\ In c suffix.
  Proof.
    induction fuel as [|fuel IH]; intros a ix n pre c Hwf Hnode Hin; [contradiction|].
    cbn [index_cells] in Hin. apply in_flat_map in Hin as [edge [Hedge Hin]].
    destruct (proj1 (proj1 (I.children_spec a ix n pre edge Hwf Hnode)) Hedge)
      as [next Hchild].
    rewrite Hchild in Hin.
    pose proof (proj1 (proj1 (I.child_spec a ix n pre edge Hwf Hnode) next) Hchild)
      as Hnext.
    destruct Hin as [<-|Hin].
    - assert (Hnonempty : pre ++ [edge] <> []).
      { intro Heq. apply (f_equal (@length (cell V.t))) in Heq.
        rewrite length_app in Heq. cbn [length] in Heq. lia. }
      destruct (I.node_live a ix next (pre ++ [edge]) Hwf Hnext Hnonempty)
        as [suffix Hmember].
      exists (edge :: suffix). split; [|now left].
      rewrite <- app_assoc in Hmember. exact Hmember.
    - destruct (IH a ix next (pre ++ [edge]) c Hwf Hnext Hin)
        as [suffix [Hmember Hinside]].
      exists (edge :: suffix). split; [|now right].
      rewrite <- app_assoc in Hmember. exact Hmember.
  Qed.

  (** Walking a member's length collects every cell of that member suffix. *)
  Lemma run_index_cells_complete : forall a ix n pre suffix c,
    I.wf a ix -> I.node ix n pre -> I.mem ix (pre ++ suffix) -> In c suffix ->
    In c (index_cells (length suffix) ix n).
  Proof.
    intros a ix n pre suffix c Hwf. revert n pre.
    induction suffix as [|edge suffix IH]; intros n pre Hnode Hmember Hin;
      [contradiction|].
    cbn [length index_cells]. destruct (I.child ix n edge) as [next|] eqn:Hchild.
    - apply in_flat_map. exists edge. split.
      + apply (proj2 (proj1 (I.children_spec a ix n pre edge Hwf Hnode))).
        exists next. exact Hchild.
      + rewrite Hchild. destruct Hin as [<-|Hin]; [now left|]. right.
        apply (IH next (pre ++ [edge])).
        * apply (proj1 (proj1 (I.child_spec a ix n pre edge Hwf Hnode) next)).
          exact Hchild.
        * rewrite <- app_assoc. exact Hmember.
        * exact Hin.
    - exfalso. apply (proj1 (proj2 (I.child_spec a ix n pre edge Hwf Hnode)) Hchild).
      exists suffix. exact Hmember.
  Qed.

  (** At its declared width, root traversal collects exactly the cells of stored members. *)
  Lemma run_index_cells_member : forall a ix c, I.wf a ix ->
    (In c (index_cells a ix (I.root ix)) <-> exists u, I.mem ix u /\ In c u).
  Proof.
    intros a ix c Hwf. split.
    - intro Hin. apply (run_index_cells_sound a a ix (I.root ix) [] c Hwf
        (I.node_root a ix Hwf)) in Hin. exact Hin.
    - intros [u [Hmember Hin]].
      rewrite <- (I.mem_arity a ix u Hwf Hmember).
      eapply run_index_cells_complete with (pre := []) (a := a).
      + exact Hwf.
      + apply I.node_root with a. exact Hwf.
      + exact Hmember.
      + exact Hin.
  Qed.

  (** Selecting value cells changes only their constructor wrapper. *)
  Lemma run_cell_values_member : forall (cells : list (cell V.t)) v,
    In v (flat_map (fun c => match c with Val w => [w] | Id _ => [] end) cells) <->
    In (Val v) cells.
  Proof.
    induction cells as [|[i|w] cells IH]; intro v; cbn [flat_map app In].
    - tauto.
    - rewrite IH. intuition discriminate.
    - rewrite IH. intuition congruence.
  Qed.

  (** Slot traversal records values at precisely their original numbered slot. *)
  Lemma run_slot_values_member : forall sl db start v,
    In v (slot_values db start sl) <-> exists j f perm,
      nth_error sl j = Some (f, perm) /\
      In (Val v) (index_cells (length perm) (D.index (N.of_nat (start + j)) false db)
        (I.root (D.index (N.of_nat (start + j)) false db))).
  Proof.
    induction sl as [|[head positions] sl IH]; intros db start v.
    - cbn [slot_values]. split; [contradiction|].
      intros [j [f [perm [Hnth Hin]]]]. destruct j; discriminate.
    - cbn [slot_values]. rewrite in_app_iff, run_cell_values_member, IH. split.
      + intros [Hin|[j [f [perm [Hnth Hin]]]]].
        * exists 0, head, positions. split; [reflexivity|]. now rewrite Nat.add_0_r.
        * exists (S j), f, perm. split; [exact Hnth|].
          replace (start + S j) with (S start + j) by lia. exact Hin.
      + intros [j [f [perm [Hnth Hin]]]]. destruct j as [|j].
        * cbn [nth_error] in Hnth. injection Hnth as <- <-. left.
          now rewrite Nat.add_0_r in Hin.
        * right. exists j, f, perm. split; [exact Hnth|].
          replace (S start + j) with (start + S j) by lia. exact Hin.
  Qed.

  (** Full-slot traversal finds exactly the values mentioned by the active-value definition. *)
  Lemma run_slot_values_active : forall db v, D.wf db ->
    (In v (slot_values db 0 (D.slots db)) <-> exists s u,
      N.to_nat s < length (D.slots db) /\ I.mem (D.index s false db) u /\ In (Val v) u).
  Proof.
    intros db v Hwf. rewrite run_slot_values_member. split.
    - intros [j [f [perm [Hnth Hin]]]]. cbn [Nat.add] in Hin.
      assert (Hslot : D.slot_of db (N.of_nat j) = Some (f, perm)).
      { unfold D.slot_of. now rewrite Nat2N.id. }
      pose proof (D.index_wf db (N.of_nat j) false f perm Hwf Hslot) as Hindex.
      apply (proj1 (run_index_cells_member (length perm) _ (Val v) Hindex)) in Hin.
      destruct Hin as [u [Hmember Hinside]]. exists (N.of_nat j), u.
      split; [|auto]. rewrite Nat2N.id. apply nth_error_Some. now rewrite Hnth.
    - intros [s [u [Hbound [Hmember Hin]]]].
      destruct (nth_error (D.slots db) (N.to_nat s)) as [[f perm]|] eqn:Hnth.
      + exists (N.to_nat s), f, perm. split; [exact Hnth|].
        cbn [Nat.add]. rewrite N2Nat.id.
        assert (Hslot : D.slot_of db s = Some (f, perm)) by exact Hnth.
        pose proof (D.index_wf db s false f perm Hwf Hslot) as Hindex.
        apply (proj2 (run_index_cells_member (length perm) _ (Val v) Hindex)).
        exists u. auto.
      + apply nth_error_None in Hnth. lia.
  Qed.

  (** Program literal collection retains exactly literal occurrences in program terms. *)
  Lemma run_program_literals_member : forall p (v : V.t),
    In v (program_literals p) <-> In (Lit v) (program_terms p).
  Proof.
    intros p v. unfold program_literals. split.
    - intro Hin. apply in_flat_map in Hin as [[x|w] [Hterm Hin]]; [contradiction|].
      destruct Hin as [<-|Hbad]; [exact Hterm|contradiction].
    - intro Hin. apply in_flat_map. exists (Lit v). split; [exact Hin|now left].
  Qed.

  (** Distinct active-value enumeration agrees with the public literal-or-index predicate. *)
  Lemma run_active_values_member : forall p db v, D.wf db ->
    (In v (distinct_values V.eqb (program_literals p ++ slot_values db 0 (D.slots db))) <->
      active_value p db v).
  Proof.
    intros p db v Hwf. unfold active_value.
    rewrite run_distinct_values_member, in_app_iff, run_program_literals_member.
    now rewrite run_slot_values_active by exact Hwf.
  Qed.

  (** Universe membership uses first declarations and exactly the active values. *)
  Lemma run_universe_member : forall p db f k, D.wf db ->
    (In (f, k) (universe p db) <->
      program_kind p f = Some ORel /\
      (exists d, find (fun d => Pos.eqb (name d) f) (decls V.t p) = Some d /\
        length k = length (arg_sorts d)) /\
      Forall (fun c => exists v, c = Val v /\ active_value p db v) k).
  Proof.
    intros p db f k Hwf. unfold universe. split.
    - intro Hin. apply in_flat_map in Hin as [[g n] [Harity Hin]].
      apply in_map_iff in Hin as [key [Heq Htuple]]. cbn [fst snd] in Heq, Htuple.
      injection Heq as Hfunction Hkey. subst g key.
      destruct (run_relation_arities_sound (decls V.t p) [] f n Harity)
        as [Hfresh [d [Hfind [Hout Hwidth]]]].
      destruct (run_find_decl_fields (decls V.t p) f d Hfind) as [Hsort Hkind].
      rewrite Hout in Hkind. apply run_value_tuples_member in Htuple as [Hlength Hvalues].
      split; [exact Hkind|]. split.
      + exists d. split; [exact Hfind|]. now rewrite Hlength, Hwidth.
      + eapply Forall_impl; [|exact Hvalues]. intros c [v [Hcell Hvalue]].
        exists v. split; [exact Hcell|]. now apply (proj1 (run_active_values_member p db v Hwf)).
    - intros [Hkind [[d [Hfind Hlength]] Hvalues]].
      destruct (run_find_decl_fields (decls V.t p) f d Hfind) as [Hsort Hdeclkind].
      change (program_kind p f = Some (out d)) in Hdeclkind.
      assert (Hout : out d = ORel) by congruence.
      apply in_flat_map. exists (f, length (arg_sorts d)). split.
      + apply run_relation_arities_complete; [intro Hbad; contradiction|exact Hfind|exact Hout].
      + apply in_map. apply run_value_tuples_member. split; [exact Hlength|].
        eapply Forall_impl; [|exact Hvalues]. intros c [v [Hcell Hvalue]].
        exists v. split; [exact Hcell|]. now apply (proj2 (run_active_values_member p db v Hwf)).
  Qed.

  Lemma universe_spec : forall p db, D.wf db -> relational_fragment p = true ->
    prim_free p = true -> no_ids db ->
    NoDup (universe p db) /\
    forall f k, In (f, k) (universe p db) <->
      program_kind p f = Some ORel /\
      (exists d, find (fun d => Pos.eqb (name d) f) (decls V.t p) = Some d /\
        length k = length (arg_sorts d)) /\
      Forall (fun c => exists v, c = Val v /\ active_value p db v) k.
  Proof.
    intros p db Hwf _ _ _. split; [apply run_universe_nodup|].
    intros f k. now apply run_universe_member.
  Qed.

  (** Every sorted action that writes a row has the declared number of arguments. *)
  Lemma run_actions_arities : forall sorts kinds acts g a,
    @actions_ok V.t sorts kinds g acts -> In a acts ->
    match a with
    | Make _ f args | Put f args _ => exists ss, sorts f = Some ss /\ length args = length ss
    | _ => True
    end.
  Proof.
    intros sorts kinds acts. induction acts as [|h acts IH]; intros g a Hok Hin;
      [contradiction|].
    destruct h as [x f args|f args res|t u|x op args]; cbn [actions_ok] in Hok.
    - destruct Hok as [ss [Hsort [Hkind [Hargs Hrest]]]].
      destruct Hin as [<-|Hin].
      + exists ss. split; [exact Hsort|]. eapply Forall2_length. exact Hargs.
      + eapply IH; eassumption.
    - destruct Hok as [ss [out [Hsort [Hkind [Hargs [Hres Hrest]]]]]].
      destruct Hin as [<-|Hin].
      + exists ss. split; [exact Hsort|]. eapply Forall2_length. exact Hargs.
      + eapply IH; eassumption.
    - destruct Hok as [Ht [Hu Hrest]]. destruct Hin as [<-|Hin]; [exact I|].
      eapply IH; eassumption.
    - destruct Hok as [Hargs Hrest]. destruct Hin as [<-|Hin]; [exact I|].
      eapply IH; eassumption.
  Qed.

  (** Checked row-writing actions have their declared argument count. *)
  Lemma check_plan_arities : forall p cp r a, plans_ok p cp ->
    In r (rules V.t p) -> In a (actions V.t r) ->
    match a with
    | Make _ f args | Put f args _ =>
      exists d, find (fun d => Pos.eqb (name d) f) (decls V.t p) = Some d /\
        length args = length (arg_sorts d)
    | _ => True
    end.
  Proof.
    intros p cp r a Hchecked Hrule Haction.
    unfold plans_ok, check_plan in Hchecked. apply andb_true_iff in Hchecked.
    pose proof (proj1 (check_program_spec V.t p) (proj1 Hchecked)) as Hprogram.
    unfold program_ok in Hprogram. rewrite Forall_forall in Hprogram.
    destruct (Hprogram r Hrule) as [g [Hquery Hactions]].
    pose proof (run_actions_arities _ _ _ g a Hactions Haction) as Harity.
    destruct a as [x f args|f args res|t u|x op args]; try exact I.
    all: destruct Harity as [ss [Hsort Hlength]].
    all: destruct (run_lookup_sorts_decl _ _ _ Hsort) as [d [Hfind Hargs]].
    all: exists d; split; [exact Hfind|now rewrite Hargs].
  Qed.

  (** Declaration widths preserve existing entries and otherwise use the first declaration. *)
  Lemma decl_widths_get : forall ds t f,
    trie_get f (decl_widths ds t) =
      match trie_get f t with
      | Some width => Some width
      | None =>
          match find (fun d => Pos.eqb (name d) f) ds with
          | Some d => Some (length (arg_sorts d) + match out d with ORel => 0 | _ => 1 end)
          | None => None
          end
      end.
  Proof.
    intros ds. induction ds as [|[h ss o] ds IH]; intros t f.
    - cbn [decl_widths find]. destruct (trie_get f t); reflexivity.
    - cbn [decl_widths find name arg_sorts out].
      destruct (Pos.eqb_spec h f) as [->|Hneq].
      + destruct (trie_get f t) as [width|] eqn:Hget; rewrite IH.
        * now rewrite Hget.
        * rewrite PTrie.get_set_same. destruct o; cbn [arg_sorts out];
            now rewrite ?Nat.add_0_r, ?Nat.add_1_r.
      + destruct (trie_get h t) as [width|] eqn:Hget; rewrite IH.
        * reflexivity.
        * rewrite PTrie.get_set_other by congruence. reflexivity.
  Qed.

  (** An absent entry after an insertion was absent before it and has a different key. *)
  Lemma run_get_set_none : forall (t : ptrie unit) k x,
    trie_get x (PTrieCode.set k tt t) = None -> trie_get x t = None /\ x <> k.
  Proof.
    intros t k x Hnone. destruct (Pos.eq_dec x k) as [->|Hneq].
    - rewrite PTrie.get_set_same in Hnone. discriminate.
    - rewrite PTrie.get_set_other in Hnone by congruence. split; assumption.
  Qed.

  (** An accepted permutation has distinct in-range positions that were initially unseen. *)
  Lemma perm_ok_sound : forall perm width seen,
    perm_ok width perm seen = true ->
    NoDup perm /\ Forall (fun i => i < width) perm /\
      forall i, In i perm -> trie_get (nat_code i) seen = None.
  Proof.
    intros perm. induction perm as [|i perm IH]; intros width seen Hok.
    - split; [constructor|]. split; [constructor|]. intros j Hin. contradiction.
    - cbn [perm_ok] in Hok. destruct (trie_get (nat_code i) seen) eqn:Hget;
        [discriminate|].
      destruct (Nat.leb (S i) width) eqn:Hbound; [|discriminate].
      destruct (IH _ _ Hok) as [Hnodup [Hrange Hfresh]].
      split.
      + constructor; [|exact Hnodup]. intro Hin.
        pose proof (Hfresh i Hin) as Hnone. rewrite PTrie.get_set_same in Hnone.
        discriminate.
      + split.
        * constructor; [now apply Nat.leb_le in Hbound|exact Hrange].
        * intros j [<-|Hin]; [exact Hget|].
          destruct (run_get_set_none _ _ _ (Hfresh j Hin)) as [Hnone Hneq]. exact Hnone.
  Qed.

  (** Every slot traversed successfully has a declared width and an accepted permutation. *)
  Lemma slot_table_member : forall sl widths next table result f perm,
    slot_table widths sl next table = Some result -> In (f, perm) sl ->
    exists width, trie_get f widths = Some width /\ perm_ok width perm Empty = true.
  Proof.
    intros sl. induction sl as [|[g ps] sl IH];
      intros widths next table result f perm Htable Hin; [contradiction|].
    cbn [slot_table] in Htable. destruct (trie_get g widths) as [width|] eqn:Hwidth;
      [|discriminate].
    destruct (perm_ok width ps Empty) eqn:Hperm; [|discriminate].
    destruct Hin as [Heq|Hin].
    - injection Heq as <- <-. exists width. split; assumption.
    - destruct (trie_get (slot_code g ps) table); eapply IH; eassumption.
  Qed.

  (** Each accepted slot contains distinct positions within its declared row width. *)
  Lemma check_plan_slots : forall p cp f perm, plans_ok p cp ->
    In (f, perm) (Syntax.slots V.t cp) ->
    exists d, find (fun d => Pos.eqb (name d) f) (decls V.t p) = Some d /\
      NoDup perm /\ Forall (fun i => i <
        length (arg_sorts d) + match out d with ORel => 0 | _ => 1 end) perm.
  Proof.
    intros [ds rs] [sl naive semi] f perm Hchecked Hin.
    unfold plans_ok, check_plan, check_shape, check_shape_with in Hchecked.
    apply andb_true_iff in Hchecked. destruct Hchecked as [Hprogram Hshape].
    cbn [decls Syntax.slots] in *.
    destruct (slot_table (decl_widths ds Empty) sl 0 Empty) as [table|] eqn:Htable;
      [|discriminate].
    destruct (slot_table_member sl _ _ _ _ f perm Htable Hin) as [width [Hwidth Hperm]].
    rewrite decl_widths_get, PTrie.get_empty in Hwidth.
    destruct (find (fun d => Pos.eqb (name d) f) ds) as [d|] eqn:Hfind;
      [|discriminate].
    injection Hwidth as <-. exists d. split; [reflexivity|].
    destruct (perm_ok_sound perm _ _ Hperm) as [Hnodup [Hrange Hfresh]].
    split; assumption.
  Qed.

  (** Every accepted compiled plan belongs to a well-sorted program. *)
  Lemma plans_ok_sorted : forall p cp, plans_ok p cp -> program_ok p.
  Proof.
    intros p cp Hchecked. unfold plans_ok, check_plan in Hchecked.
    apply (proj1 (check_program_spec V.t p)).
    apply andb_true_iff in Hchecked. exact (proj1 Hchecked).
  Qed.

  (** The unary slot-position code preserves its natural argument. *)
  Lemma planner_nat_code_inj : forall n m, nat_code n = nat_code m -> n = m.
  Proof.
    induction n as [| n IH]; intros [| m] Hcode; cbn [nat_code] in Hcode;
      try discriminate Hcode.
    - reflexivity.
    - injection Hcode as Htail. f_equal. now apply IH.
  Qed.

  (** The code of a permutation preserves all its positions. *)
  Lemma planner_perm_code_inj : forall xs ys,
    list_code nat_code xs = list_code nat_code ys -> xs = ys.
  Proof.
    induction xs as [| x xs IH]; intros [| y ys] Hcode; cbn [list_code] in Hcode.
    - reflexivity.
    - destruct (nat_code y); cbn [glue] in Hcode; discriminate Hcode.
    - destruct (nat_code x); cbn [glue] in Hcode; discriminate Hcode.
    - destruct (glue_inj _ _ _ _ Hcode) as [Hhead Htail].
      f_equal.
      + now apply planner_nat_code_inj.
      + now apply IH.
  Qed.

  (** Equal slot keys identify the function and permutation. *)
  Lemma planner_slot_code_inj : forall f perm g other,
    slot_code f perm = slot_code g other -> f = g /\ perm = other.
  Proof.
    intros f perm g other Hcode.
    unfold slot_code in Hcode.
    destruct (glue_inj _ _ _ _ Hcode) as [Hname Hperm].
    split; [exact Hname | now apply planner_perm_code_inj].
  Qed.

  Definition planner_rows (st : slot_state) : list (positive * list nat) :=
    match st with
    | SlotState _ _ rows => rows
    end.

  (** Every registered slot key witnesses its exact row in the reversed slot list. *)
  Definition planner_slots_present (st : slot_state) : Prop :=
    match st with
    | SlotState table _ rows =>
        forall f perm s, trie_get (slot_code f perm) table = Some s -> In (f, perm) rows
    end.

  (** Registering a slot retains every previously registered row. *)
  Lemma add_slot_rows : forall f perm st,
    incl (planner_rows st) (planner_rows (snd (add_slot f perm st))).
  Proof.
    intros f perm [table next rows] x Hin.
    cbn [add_slot planner_rows].
    destruct (trie_get (slot_code f perm) table); cbn; auto.
  Qed.

  (** Registering a slot retains the table invariant and makes that slot present. *)
  Lemma add_slot_present : forall f perm st, planner_slots_present st ->
    planner_slots_present (snd (add_slot f perm st)) /\
    In (f, perm) (planner_rows (snd (add_slot f perm st))).
  Proof.
    intros f perm [table next rows] Hpresent.
    cbn [add_slot].
    destruct (trie_get (slot_code f perm) table) as [s |] eqn:Hget.
    - split; [exact Hpresent | now apply (Hpresent f perm s)].
    - split; [| now left].
      intros g other s Hlookup.
      destruct (Pos.eq_dec (slot_code g other) (slot_code f perm)) as [Hsame | Hother].
      + destruct (planner_slot_code_inj _ _ _ _ Hsame) as [-> ->]. now left.
      + rewrite PTrie.get_set_other in Hlookup by exact Hother.
        right. now apply (Hpresent g other s).
  Qed.

  (** Full-slot registration retains the slots it receives. *)
  Lemma full_slots_rows : forall ds seen st,
    incl (planner_rows st) (planner_rows (full_slots ds seen st)).
  Proof.
    induction ds as [| [f ss out] rest IH]; intros seen st x Hin.
    - exact Hin.
    - cbn [full_slots].
      destruct (trie_get f seen) as [u |].
      + now apply IH.
      + destruct out; apply IH; try exact Hin.
        now apply add_slot_rows.
  Qed.

  (** An unseen identifier declaration gets its full slot from its first occurrence. *)
  Lemma full_slots_complete : forall ds seen st f ss,
    planner_slots_present st -> trie_get f seen = None ->
    lookup_kind ds f = Some OId -> lookup_sorts ds f = Some ss ->
    In (f, count_from 0 (S (length ss))) (planner_rows (full_slots ds seen st)).
  Proof.
    induction ds as [| [g sorts o] rest IH]; intros seen st f ss
      Hpresent Hunseen Hkind Hsorts; cbn [lookup_kind lookup_sorts name arg_sorts Syntax.out]
      in Hkind, Hsorts.
    - discriminate Hkind.
    - destruct (Pos.eqb_spec g f) as [Hname | Hname].
      + subst g. injection Hkind as ->. injection Hsorts as ->.
        cbn [full_slots]. rewrite Hunseen.
        apply full_slots_rows.
        exact (proj2 (add_slot_present _ _ _ Hpresent)).
      + cbn [full_slots].
        destruct (trie_get g seen) as [u |] eqn:Hseen.
        * eapply IH; eassumption.
        * assert (Hunseen' : trie_get f (PTrieCode.set g tt seen) = None).
          { rewrite PTrie.get_set_other by congruence. exact Hunseen. }
          destruct o; eapply IH; try eassumption.
          exact (proj1 (add_slot_present _ _ _ Hpresent)).
  Qed.

  (** Planning query atoms only adds slots. *)
  Lemma plan_atoms_rows : forall (base : nat) (q : list (atom V.t)) ai lay st outs post
      lay' st' outs' post',
    plan_atoms base q ai lay st outs post = (lay', st', outs', post') ->
    incl (planner_rows st) (planner_rows st').
  Proof.
    intros base q. induction q as [| a rest IH]; intros ai lay st outs post
      lay' st' outs' post' Hplan x Hin.
    - cbn [plan_atoms] in Hplan. inversion Hplan; subst. exact Hin.
    - destruct a as [f args res | f args res]; cbn [plan_atoms] in Hplan.
      + destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[next pairs] lits] copied] eqn:Hplaced.
        destruct (add_slot f (map snd (sort_pairs pairs)) st)
          as [slot nextst] eqn:Hslot.
        eapply IH; [exact Hplan |].
        pose proof (add_slot_rows f (map snd (sort_pairs pairs)) st x Hin) as Hkeep.
        rewrite Hslot in Hkeep. exact Hkeep.
      + eapply IH; eassumption.
  Qed.

  (** Planning one rule retains the slots already registered. *)
  Lemma plan_rule_rows : forall i (r : rule V.t) st st' c cs,
    plan_rule i r st = (st', c, cs) -> incl (planner_rows st) (planner_rows st').
  Proof.
    intros i [q acts] st st' c cs Hplan.
    cbn [plan_rule] in Hplan.
    destruct (plan_atoms (query_copies q 0) q 0
        (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay nextst] outs] post] eqn:Hatoms.
    destruct lay as [names nc nm fresh cn mn].
    inversion Hplan; subst.
    eapply plan_atoms_rows. exact Hatoms.
  Qed.

  (** Planning later rules retains the full slots from the declarations. *)
  Lemma plan_rules_rows : forall (rs : list (rule V.t)) i st naive semi st' naive' semi',
    plan_rules rs i st naive semi = (st', naive', semi') ->
    incl (planner_rows st) (planner_rows st').
  Proof.
    induction rs as [| r rest IH]; intros i st naive semi st' naive' semi'
      Hplan x Hin.
    - cbn [plan_rules] in Hplan. inversion Hplan; subst. exact Hin.
    - cbn [plan_rules] in Hplan.
      destruct (plan_rule i r st) as [[nextst c] cs] eqn:Hrule.
      eapply IH; [exact Hplan |].
      eapply plan_rule_rows; eassumption.
  Qed.

  (** The executable position counter is the standard interval enumeration. *)
  Lemma count_from_seq : forall len start, count_from start len = seq start len.
  Proof.
    induction len as [| len IH]; intro start; cbn [count_from seq].
    - reflexivity.
    - now rewrite IH.
  Qed.

  Lemma plan_full_slots : forall p f ss, program_kind p f = Some OId ->
    program_sorts p f = Some ss ->
    In (f, seq 0 (S (length ss))) (Syntax.slots V.t (plan p)).
  Proof.
    intros [ds rs] f ss Hkind Hsorts.
    unfold plan, plan_program.
    destruct (plan_rules rs 0%N (full_slots ds Empty (SlotState Empty 0%N [])) [] [])
      as [[[table next rows] naive] semi] eqn:Hrules.
    cbn [Syntax.slots]. rewrite rev_append_rev, app_nil_r.
    apply (proj1 (in_rev rows (f, seq 0 (S (length ss))))).
    pose proof (plan_rules_rows _ _ _ _ _ _ _ _ Hrules) as Hkeep.
    apply Hkeep.
    rewrite <- count_from_seq.
    eapply full_slots_complete.
    - intros g perm s Hget. rewrite PTrie.get_empty in Hget. discriminate Hget.
    - apply PTrie.get_empty.
    - exact Hkind.
    - exact Hsorts.
  Qed.


  (** Distinct in-range positions pass the permutation checker when initially unseen. *)
  Lemma perm_ok_complete : forall perm width seen,
    NoDup perm -> Forall (fun i => i < width) perm ->
    (forall i, In i perm -> trie_get (nat_code i) seen = None) ->
    perm_ok width perm seen = true.
  Proof.
    intros perm. induction perm as [|i perm IH]; intros width seen Hnodup Hrange Hfresh;
      [reflexivity|].
    inversion Hnodup as [|? ? Hnot Htail]; subst.
    inversion Hrange as [|? ? Hbound Hranges]; subst.
    cbn [perm_ok]. rewrite Hfresh by (left; reflexivity).
    assert (Hboundb : Nat.leb (S i) width = true) by (apply Nat.leb_le; exact Hbound).
    rewrite Hboundb. apply IH; [exact Htail|exact Hranges|].
    intros j Hin. rewrite PTrie.get_set_other.
    - apply Hfresh. right. exact Hin.
    - intro Heq. apply planner_nat_code_inj in Heq. subst j. contradiction.
  Qed.

  (** The full declaration-order permutation passes its width check. *)
  Lemma planner_full_perm_ok : forall width,
    perm_ok width (count_from 0 width) Empty = true.
  Proof.
    intro width. rewrite count_from_seq. apply perm_ok_complete.
    - apply seq_NoDup.
    - rewrite Forall_forall. intros i Hin. apply in_seq in Hin. lia.
    - intros i Hin. apply PTrie.get_empty.
  Qed.

  (** A nonempty increasing bounded column passes its checker. *)
  Lemma column_ok_complete : forall lv n prev,
    StronglySorted lt lv -> Forall (fun i => i < n) lv ->
    (match prev with None => lv <> [] | Some k => Forall (fun i => k < i) lv end) ->
    column_ok n lv prev = true.
  Proof.
    intros lv. induction lv as [|l lv IH]; intros n prev Hsorted Hrange Hprev.
    - destruct prev; [reflexivity|exfalso; apply Hprev; reflexivity].
    - inversion Hsorted as [|? ? Htail Hgreater]; subst.
      inversion Hrange as [|? ? Hbound Hranges]; subst.
      assert (Hboundb : Nat.leb (S l) n = true) by (apply Nat.leb_le; exact Hbound).
      destruct prev as [k|]; cbn [column_ok].
      + inversion Hprev as [|? ? Hlower Hlowers]; subst.
        assert (Hlowerb : Nat.leb (S k) l = true) by (apply Nat.leb_le; exact Hlower).
        rewrite Hlowerb, Hboundb. apply IH; assumption.
      + rewrite Hboundb. apply IH; assumption.
  Qed.

  (** Insertion rearranges its input without losing either coordinate. *)
  Lemma planner_insert_pair_perm : forall j pos l,
    Permutation ((j, pos) :: l) (insert_pair j pos l).
  Proof.
    intros j pos l. induction l as [|[k q] l IH]; cbn [insert_pair].
    - apply Permutation_refl.
    - destruct (Nat.leb j k).
      + apply Permutation_refl.
      + eapply Permutation_trans; [apply perm_swap|]. apply perm_skip. exact IH.
  Qed.

  (** Sorting pairs rearranges the input without changing its elements. *)
  Lemma planner_sort_pairs_perm : forall l, Permutation l (sort_pairs l).
  Proof.
    intros l. induction l as [|[j pos] l IH]; cbn [sort_pairs].
    - apply Permutation_refl.
    - eapply Permutation_trans; [apply perm_skip; exact IH|].
      apply planner_insert_pair_perm.
  Qed.

  (** Inserting a fresh first coordinate preserves the strict ordering of pairs. *)
  Lemma planner_insert_pair_sorted : forall l j pos,
    StronglySorted (fun a b : nat * nat => fst a < fst b) l ->
    ~ In j (map fst l) ->
    StronglySorted (fun a b : nat * nat => fst a < fst b) (insert_pair j pos l).
  Proof.
    intros l. induction l as [|[k q] l IH]; intros j pos Hsorted Hfresh.
    - cbn [insert_pair]. constructor; constructor.
    - inversion Hsorted as [|? ? Htail Hgreater]; subst.
      cbn [insert_pair]. destruct (Nat.leb j k) eqn:Hcompare.
      + constructor; [exact Hsorted|]. constructor.
        * cbn. apply Nat.leb_le in Hcompare. assert (j <> k).
          { intro Heq. apply Hfresh. cbn. left. symmetry. exact Heq. }
          lia.
        * rewrite Forall_forall in *. intros [m r] Hin. cbn.
          specialize (Hgreater (m, r) Hin). cbn in Hgreater.
          apply Nat.leb_le in Hcompare. lia.
      + constructor.
        * apply IH; [exact Htail|]. intro Hin. apply Hfresh. right. exact Hin.
        * eapply Permutation_Forall; [apply planner_insert_pair_perm|].
          constructor; [cbn; now apply Nat.leb_gt in Hcompare|exact Hgreater].
  Qed.

  (** Sorting distinct first coordinates produces a strictly increasing pair list. *)
  Lemma planner_sort_pairs_sorted : forall l,
    NoDup (map fst l) ->
    StronglySorted (fun a b : nat * nat => fst a < fst b) (sort_pairs l).
  Proof.
    intros l. induction l as [|[j pos] l IH]; intro Hnodup.
    - constructor.
    - cbn [map] in Hnodup. inversion Hnodup as [|? ? Hfresh Htail]; subst.
      cbn [sort_pairs]. apply planner_insert_pair_sorted; [apply IH; exact Htail|].
      intro Hin. apply Hfresh. eapply Permutation_in; [|exact Hin].
      apply Permutation_sym. apply Permutation_map. apply planner_sort_pairs_perm.
  Qed.

  (** Projecting ordered pairs preserves their first-coordinate ordering. *)
  Lemma planner_pair_column_sorted : forall l,
    StronglySorted (fun a b : nat * nat => fst a < fst b) l ->
    StronglySorted lt (map fst l).
  Proof.
    intros l Hsorted. induction Hsorted as [|[j pos] l Htail IH Hgreater].
    - constructor.
    - cbn [map]. constructor; [exact IH|].
      rewrite Forall_map. exact Hgreater.
  Qed.

  (** Sorting preserves every distinct projection of the pair list. *)
  Lemma planner_sort_pairs_nodup : forall (f : nat * nat -> nat) l,
    NoDup (map f l) -> NoDup (map f (sort_pairs l)).
  Proof.
    intros f l Hnodup. eapply Permutation_NoDup; [|exact Hnodup].
    apply Permutation_map. apply planner_sort_pairs_perm.
  Qed.

  (** Sorting preserves every elementwise property of its pairs. *)
  Lemma planner_sort_pairs_forall : forall (P : nat * nat -> Prop) l,
    Forall P l -> Forall P (sort_pairs l).
  Proof.
    intros P l Hall. eapply Permutation_Forall; [apply planner_sort_pairs_perm|exact Hall].
  Qed.

  (** Sorting leaves the pair count unchanged. *)
  Lemma planner_sort_pairs_length : forall l, length (sort_pairs l) = length l.
  Proof.
    intro l. symmetry. apply Permutation_length. apply planner_sort_pairs_perm.
  Qed.

  (** Sorting a nonempty bounded set of first coordinates produces an accepted column. *)
  Lemma planner_sorted_column_ok : forall pairs n,
    pairs <> [] -> NoDup (map fst pairs) -> Forall (fun p => fst p < n) pairs ->
    column_ok n (map fst (sort_pairs pairs)) None = true.
  Proof.
    intros pairs n Hnonempty Hnodup Hrange. apply column_ok_complete.
    - apply planner_pair_column_sorted. apply planner_sort_pairs_sorted. exact Hnodup.
    - rewrite Forall_map. apply planner_sort_pairs_forall. exact Hrange.
    - intro Hempty. apply (f_equal (@length nat)) in Hempty.
      rewrite length_map, planner_sort_pairs_length in Hempty.
      destruct pairs; [contradiction|discriminate].
  Qed.

  (** Sorting bounded distinct positions produces an accepted slot permutation. *)
  Lemma planner_sorted_perm_ok : forall pairs width,
    NoDup (map snd pairs) -> Forall (fun p => snd p < width) pairs ->
    perm_ok width (map snd (sort_pairs pairs)) Empty = true.
  Proof.
    intros pairs width Hnodup Hrange. apply perm_ok_complete.
    - apply planner_sort_pairs_nodup. exact Hnodup.
    - rewrite Forall_map. apply planner_sort_pairs_forall. exact Hrange.
    - intros i Hin. apply PTrie.get_empty.
  Qed.

  (** Appending one row keeps every old position and adds only the final position. *)
  Lemma planner_nth_error_snoc : forall (A : Type) (xs : list A) x i y,
    nth_error (xs ++ [x]) i = Some y <->
      nth_error xs i = Some y \/ i = length xs /\ y = x.
  Proof.
    intros A xs. induction xs as [| a xs IH]; intros x [| i] y; cbn.
    - split.
      + intro H. injection H as <-. now right.
      + intros [H | [_ ->]]; [discriminate H | reflexivity].
    - rewrite nth_error_nil. split; [discriminate |].
      intros [H | [H _]]; discriminate H.
    - split; [now left | intros [H | [H _]]; [exact H | discriminate H]].
    - rewrite IH. split.
      + intros [H | [H ->]]; [now left | right; split; [now f_equal | reflexivity]].
      + intros [H | [H ->]]; [now left | right; split; [now injection H | reflexivity]].
  Qed.

  (** The next slot number is the length of the forward rows, whose positions match the trie. *)
  Definition planner_state_exact (st : slot_state) : Prop :=
    match st with
    | SlotState table next rows =>
        next = N.of_nat (length rows) /\
        forall f perm s, trie_get (slot_code f perm) table = Some s <->
          nth_error (rev rows) (N.to_nat s) = Some (f, perm)
    end.

  (** The empty planner state numbers no slot. *)
  Lemma planner_state_empty : planner_state_exact (SlotState Empty 0%N []).
  Proof.
    split; [reflexivity |].
    intros f perm s. rewrite PTrie.get_empty.
    destruct (N.to_nat s); cbn; split; discriminate.
  Qed.

  (** Adding a slot preserves the exact forward numbering of all slots. *)
  Lemma add_slot_exact : forall f perm st, planner_state_exact st ->
    planner_state_exact (snd (add_slot f perm st)).
  Proof.
    intros f perm [table next rows] [Hnext Htable].
    cbn [add_slot].
    destruct (trie_get (slot_code f perm) table) as [found |] eqn:Hfind.
    - split; assumption.
    - split.
      + cbn [length]. rewrite Hnext, Nat2N.inj_succ. reflexivity.
      + intros g other s.
        cbn [rev]. rewrite planner_nth_error_snoc, length_rev.
        destruct (Pos.eq_dec (slot_code g other) (slot_code f perm)) as [Hsame | Hother].
        * destruct (planner_slot_code_inj _ _ _ _ Hsame) as [-> ->].
          rewrite PTrie.get_set_same. split.
          -- intro Heq. injection Heq as <-. right. split; [| reflexivity].
             rewrite Hnext, Nat2N.id. reflexivity.
          -- intros [Hold | [Hindex _]].
             ++ apply Htable in Hold. rewrite Hfind in Hold. discriminate Hold.
             ++ f_equal. apply N2Nat.inj. rewrite Hnext, Nat2N.id. symmetry. exact Hindex.
        * rewrite PTrie.get_set_other by exact Hother.
          rewrite Htable. split; [now left |].
          intros [Hold | [_ Hrow]]; [exact Hold |].
          injection Hrow as -> ->. exfalso. apply Hother. reflexivity.
  Qed.

  (** Registering identifier declarations preserves exact slot numbering. *)
  Lemma full_slots_exact : forall ds seen st, planner_state_exact st ->
    planner_state_exact (full_slots ds seen st).
  Proof.
    induction ds as [| [f ss o] rest IH]; intros seen st Hstate.
    - exact Hstate.
    - cbn [full_slots]. destruct (trie_get f seen) as [u |].
      + now apply IH.
      + destruct o; apply IH; try exact Hstate. now apply add_slot_exact.
  Qed.

  (** Planning query atoms preserves exact slot numbering. *)
  Lemma plan_atoms_exact : forall base (q : list (atom V.t)) ai lay st outs post
      lay' st' outs' post',
    planner_state_exact st ->
    plan_atoms base q ai lay st outs post = (lay', st', outs', post') ->
    planner_state_exact st'.
  Proof.
    intros base q. induction q as [| a rest IH]; intros ai lay st outs post
      lay' st' outs' post' Hstate Hplan.
    - cbn [plan_atoms] in Hplan. inversion Hplan; subst. exact Hstate.
    - destruct a as [f args res | f args res]; cbn [plan_atoms] in Hplan.
      + destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[next pairs] lits] copied] eqn:Hplaced.
        destruct (add_slot f (map snd (sort_pairs pairs)) st)
          as [slot nextst] eqn:Hslot.
        eapply IH; [| exact Hplan].
        pose proof (add_slot_exact f (map snd (sort_pairs pairs)) st Hstate) as Hkeep.
        rewrite Hslot in Hkeep. exact Hkeep.
      + eapply IH; eassumption.
  Qed.

  (** Planning a rule preserves exact slot numbering. *)
  Lemma plan_rule_exact : forall i (r : rule V.t) st st' c cs,
    planner_state_exact st -> plan_rule i r st = (st', c, cs) -> planner_state_exact st'.
  Proof.
    intros i [q acts] st st' c cs Hstate Hplan.
    cbn [plan_rule] in Hplan.
    destruct (plan_atoms (query_copies q 0) q 0
        (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay nextst] outs] post] eqn:Hatoms.
    destruct lay as [names nc nm fresh cn mn]. inversion Hplan; subst.
    eapply plan_atoms_exact; eassumption.
  Qed.

  (** Planning all rules preserves exact slot numbering. *)
  Lemma plan_rules_exact : forall (rs : list (rule V.t)) i st naive semi st' naive' semi',
    planner_state_exact st -> plan_rules rs i st naive semi = (st', naive', semi') ->
    planner_state_exact st'.
  Proof.
    induction rs as [| r rest IH]; intros i st naive semi st' naive' semi' Hstate Hplan.
    - cbn [plan_rules] in Hplan. inversion Hplan; subst. exact Hstate.
    - cbn [plan_rules] in Hplan.
      destruct (plan_rule i r st) as [[nextst c] cs] eqn:Hrule.
      eapply IH; [| exact Hplan]. eapply plan_rule_exact; eassumption.
  Qed.

  (** A trie assigning one number per slot makes all forward rows distinct. *)
  Lemma planner_rows_nodup : forall table next rows,
    planner_state_exact (SlotState table next rows) -> NoDup (rev rows).
  Proof.
    intros table next rows [_ Htable]. apply NoDup_nth_error.
    intros i j Hibound Hsame.
    destruct (nth_error (rev rows) i) as [[f perm] |] eqn:Hrow.
    - assert (Hi : trie_get (slot_code f perm) table = Some (N.of_nat i)).
      { apply Htable. now rewrite Nat2N.id. }
      assert (Hj : trie_get (slot_code f perm) table = Some (N.of_nat j)).
      { apply Htable. rewrite Nat2N.id. symmetry. exact Hsame. }
      assert (Hij : N.of_nat i = N.of_nat j) by congruence.
      now apply Nat2N.inj.
    - apply nth_error_None in Hrow. exfalso.
      exact (Nat.lt_irrefl i (Nat.lt_le_trans _ _ _ Hibound Hrow)).
  Qed.

  (** A completed slot scan retains every entry already in its table. *)
  Lemma slot_table_keeps : forall widths sl next table table',
    slot_table widths sl next table = Some table' ->
    forall key value, trie_get key table = Some value -> trie_get key table' = Some value.
  Proof.
    intros widths sl. induction sl as [| [f perm] rest IH]; intros next table table' Hscan
      key value Hget.
    - cbn [slot_table] in Hscan. inversion Hscan; subst. exact Hget.
    - cbn [slot_table] in Hscan.
      destruct (trie_get f widths) as [width |]; [| discriminate Hscan].
      destruct (perm_ok width perm Empty); [| discriminate Hscan].
      destruct (trie_get (slot_code f perm) table) as [entry |] eqn:Hentry.
      + eapply IH; eassumption.
      + eapply IH; [exact Hscan |].
        rewrite PTrie.get_set_other; [exact Hget |].
        intro Heq. subst key. rewrite Hentry in Hget. discriminate Hget.
  Qed.

  (** A list of valid slot declarations always produces a checked table. *)
  Lemma slot_table_complete : forall widths sl next table,
    Forall (fun fp => exists width, trie_get (fst fp) widths = Some width /\
      perm_ok width (snd fp) Empty = true) sl ->
    exists table', slot_table widths sl next table = Some table'.
  Proof.
    intros widths sl. induction sl as [| [f perm] rest IH]; intros next table Hvalid.
    - exists table. reflexivity.
    - inversion Hvalid as [| fp remaining Hhead Htail]; subst.
      destruct Hhead as [width [Hwidth Hperm]]. cbn in Hwidth, Hperm.
      cbn [slot_table]. rewrite Hwidth, Hperm.
      destruct (trie_get (slot_code f perm) table); now apply IH.
  Qed.

  (** A checked scan numbers distinct rows from its starting index. *)
  Lemma slot_table_numbers : forall widths sl next table table',
    NoDup sl ->
    (forall f perm, In (f, perm) sl -> trie_get (slot_code f perm) table = None) ->
    slot_table widths sl next table = Some table' ->
    forall i f perm, nth_error sl i = Some (f, perm) ->
      trie_get (slot_code f perm) table' = Some ((next + N.of_nat i)%N, (f, perm)).
  Proof.
    intros widths sl. induction sl as [| [g other] rest IH]; intros next table table'
      Hdistinct Hfresh Hscan i f perm Hrow.
    - destruct i; discriminate Hrow.
    - inversion Hdistinct as [| fp remaining Habsent Htail]; subst.
      cbn [slot_table] in Hscan.
      destruct (trie_get g widths) as [width |]; [| discriminate Hscan].
      destruct (perm_ok width other Empty); [| discriminate Hscan].
      rewrite (Hfresh g other (or_introl eq_refl)) in Hscan.
      destruct i as [| i].
      + cbn in Hrow. injection Hrow as -> ->.
        rewrite N.add_0_r.
        eapply slot_table_keeps; [exact Hscan | apply PTrie.get_set_same].
      + cbn in Hrow.
        assert (Hnew : forall h ps, In (h, ps) rest ->
            trie_get (slot_code h ps)
              (PTrieCode.set (slot_code g other) (next, (g, other)) table) = None).
        { intros h ps Hin. rewrite PTrie.get_set_other.
          - apply Hfresh. now right.
          - intro Heq. destruct (planner_slot_code_inj _ _ _ _ Heq) as [-> ->].
            exact (Habsent Hin). }
        specialize (IH (N.succ next) _ _ Htail Hnew Hscan i f perm Hrow).
        rewrite Nat2N.inj_succ, N.add_succ_r, <- N.add_succ_l. exact IH.
  Qed.

  (** The checking table reconstructs the numbers in a valid planner state. *)
  Lemma planner_slot_table : forall widths table next rows,
    planner_state_exact (SlotState table next rows) ->
    Forall (fun fp => exists width, trie_get (fst fp) widths = Some width /\
      perm_ok width (snd fp) Empty = true) (rev rows) ->
    exists checked, slot_table widths (rev rows) 0%N Empty = Some checked /\
      forall f perm s, trie_get (slot_code f perm) table = Some s ->
        trie_get (slot_code f perm) checked = Some (s, (f, perm)).
  Proof.
    intros widths table next rows Hstate Hvalid.
    destruct (slot_table_complete widths (rev rows) 0%N Empty Hvalid) as [checked Hscan].
    exists checked. split; [exact Hscan |].
    intros f perm s Hget.
    pose proof (planner_rows_nodup table next rows Hstate) as Hdistinct.
    destruct Hstate as [_ Hexact].
    assert (Hfresh : forall g ps, In (g, ps) (rev rows) ->
        trie_get (slot_code g ps) (@Empty (N * (positive * list nat))) = None).
    { intros. apply PTrie.get_empty. }
    pose proof (slot_table_numbers widths (rev rows) 0%N Empty checked Hdistinct
      Hfresh Hscan (N.to_nat s) f perm (proj1 (Hexact f perm s) Hget)) as Hnumber.
    rewrite N.add_0_l, N2Nat.id in Hnumber. exact Hnumber.
  Qed.

  (** The executable natural-to-binary counter agrees with the standard conversion. *)
  Lemma planner_nat_n_spec : forall n, nat_n n = N.of_nat n.
  Proof.
    induction n as [|n IH]; cbn [nat_n].
    - reflexivity.
    - now rewrite IH, Nat2N.inj_succ.
  Qed.

  (** Positive keys used by column tables distinguish natural column indexes. *)
  Lemma planner_column_key_inj : forall i j,
    N.succ_pos (nat_n i) = N.succ_pos (nat_n j) -> i = j.
  Proof.
    intros i j Heq.
    assert (Hnext : N.succ (nat_n i) = N.succ (nat_n j)).
    { rewrite <- !N.succ_pos_spec. now rewrite Heq. }
    apply N.succ_inj in Hnext. rewrite !planner_nat_n_spec in Hnext.
    now apply Nat2N.inj in Hnext.
  Qed.

  (** The columns of literals are listed in atom order and then literal order. *)
  Definition planner_literal_indices (atoms : list (atom_plan V.t)) : list nat :=
    flat_map (fun a => match a with AtomPlan _ _ lits => map fst lits end) atoms.

  (** Distinct concatenated lists have disjoint members. *)
  Lemma planner_nodup_disjoint : forall (xs ys : list nat),
    NoDup (xs ++ ys) -> forall x, In x xs -> ~ In x ys.
  Proof.
    induction xs as [|a xs IH]; intros ys Hnodup x Hin.
    - contradiction.
    - cbn [app] in Hnodup. inversion Hnodup as [|? ? Hnot Htail]; subst.
      destruct Hin as [<-|Hin].
      + intro Hiny. apply Hnot. apply in_or_app. right. exact Hiny.
      + eapply IH; eassumption.
  Qed.

  (** Consuming a literal block preserves every index outside that block. *)
  Lemma planner_layout_literal_prefix : forall (lits : list (nat * V.t)) srcs cols allowed,
    NoDup (map fst lits) ->
    (forall j, In j (map fst lits) ->
      trie_get (N.succ_pos (nat_n j)) allowed = Some tt) ->
    (forall next,
      (forall j, ~ In j (map fst lits) ->
        trie_get (N.succ_pos (nat_n j)) next = trie_get (N.succ_pos (nat_n j)) allowed) ->
      layout_literals srcs cols next = true) ->
    layout_literals (literal_sources lits srcs) (literal_cols lits cols) allowed = true.
  Proof.
    induction lits as [|[j v] lits IH]; intros srcs cols allowed Hnodup Hallowed Htail.
    - cbn [literal_sources literal_cols]. apply Htail. intros k _. reflexivity.
    - cbn [map] in Hnodup. inversion Hnodup as [|? ? Hnot Hrest]; subst.
      cbn [literal_sources literal_cols layout_literals].
      rewrite (Hallowed j (or_introl eq_refl)). apply IH.
      + exact Hrest.
      + intros k Hin. rewrite PTrie.get_remove_other.
        * apply Hallowed. right. exact Hin.
        * intro Heq. apply planner_column_key_inj in Heq. subst k. contradiction.
      + intros next Hkeeps. apply Htail. intros k Houtside.
        rewrite Hkeeps.
        * apply PTrie.get_remove_other. intro Heq.
          apply planner_column_key_inj in Heq. subst k. apply Houtside. left. reflexivity.
        * intro Hin. apply Houtside. right. exact Hin.
  Qed.

  (** Distinct eligible literal columns pass the layout guard in a planned source list. *)
  Lemma layout_literals_plans : forall (atoms : list (atom_plan V.t)) pivot allowed,
    NoDup (planner_literal_indices atoms) ->
    (forall j, In j (planner_literal_indices atoms) ->
      trie_get (N.succ_pos (nat_n j)) allowed = Some tt) ->
    layout_literals (plan_srcs atoms pivot) (plan_cols atoms) allowed = true.
  Proof.
    induction atoms as [|[slot col lits] atoms IH]; intros pivot allowed Hnodup Hallowed.
    - reflexivity.
    - change (NoDup (map fst lits ++ planner_literal_indices atoms)) in Hnodup.
      cbn [plan_srcs plan_cols].
      assert (Hbody : layout_literals
          (literal_sources lits (plan_srcs atoms (pivot_next pivot)))
          (literal_cols lits (plan_cols atoms)) allowed = true).
      {
        apply planner_layout_literal_prefix.
        - eapply NoDup_app_remove_r. exact Hnodup.
        - intros j Hin. apply Hallowed. apply in_or_app. left. exact Hin.
        - intros next Hkeeps. apply IH.
          + eapply NoDup_app_remove_l. exact Hnodup.
          + intros j Hin. rewrite Hkeeps.
            * apply Hallowed. apply in_or_app. right. exact Hin.
            * intro Hinlit. exact (planner_nodup_disjoint _ _ Hnodup j Hinlit Hin).
      }
      destruct pivot as [[|n]|]; exact Hbody.
  Qed.

  (** The variable maximum bounds both inputs. *)
  Lemma planner_pos_max_bounds : forall x y,
    (x <= pos_max x y /\ y <= pos_max x y)%positive.
  Proof.
    intros x y. unfold pos_max. destruct (Pos.compare x y) eqn:Hcompare.
    - apply Pos.compare_eq_iff in Hcompare. subst y. split; apply Pos.le_refl.
    - apply Pos.compare_lt_iff in Hcompare. split.
      + apply Pos.lt_le_incl. exact Hcompare.
      + apply Pos.le_refl.
    - apply Pos.compare_gt_iff in Hcompare. split.
      + apply Pos.le_refl.
      + apply Pos.lt_le_incl. exact Hcompare.
  Qed.

  (** Scanning one term never decreases the running maximum. *)
  Lemma planner_term_max_seed : forall (t : term V.t) m,
    (m <= term_max t m)%positive.
  Proof.
    intros [x|v] m; cbn [term_max].
    - exact (proj2 (planner_pos_max_bounds x m)).
    - apply Pos.le_refl.
  Qed.

  (** Scanning terms never decreases the running maximum. *)
  Lemma planner_terms_max_seed : forall (ts : list (term V.t)) m,
    (m <= terms_max ts m)%positive.
  Proof.
    induction ts as [|t rest IH]; intro m; cbn [terms_max].
    - apply Pos.le_refl.
    - eapply Pos.le_trans.
      + apply planner_term_max_seed.
      + apply IH.
  Qed.

  (** Every variable encountered by the term scan is bounded by its final maximum. *)
  Lemma planner_terms_max_member : forall (ts : list (term V.t)) m x,
    In (Var x) ts -> (x <= terms_max ts m)%positive.
  Proof.
    induction ts as [|t rest IH]; intros m x Hin; cbn [terms_max] in *.
    - contradiction.
    - destruct Hin as [Heq|Hin].
      + subst t. eapply Pos.le_trans.
        * exact (proj1 (planner_pos_max_bounds x m)).
        * apply planner_terms_max_seed.
      + exact (IH (term_max t m) x Hin).
  Qed.

  (** Scanning a query never decreases the running maximum. *)
  Lemma planner_query_max_seed : forall (q : list (atom V.t)) m,
    (m <= query_max q m)%positive.
  Proof.
    induction q as [|a rest IH]; intro m; cbn [query_max].
    - apply Pos.le_refl.
    - destruct a as [f args res|p args res]; eapply Pos.le_trans.
      + apply planner_terms_max_seed.
      + apply IH.
      + apply planner_terms_max_seed.
      + apply IH.
  Qed.

  (** The query maximum bounds every real query variable. *)
  Lemma planner_query_max_member : forall (q : list (atom V.t)) m x,
    In (Var x) (flat_map atom_terms q) -> (x <= query_max q m)%positive.
  Proof.
    induction q as [|a rest IH]; intros m x Hin; cbn [flat_map] in Hin.
    - contradiction.
    - apply in_app_iff in Hin. destruct a as [f args res|p args res];
        cbn [query_max]; destruct Hin as [Hin|Hin].
      + eapply Pos.le_trans.
        * apply planner_terms_max_member. exact Hin.
        * apply planner_query_max_seed.
      + apply IH. exact Hin.
      + eapply Pos.le_trans.
        * apply (planner_terms_max_member (res :: args) m x). cbn [atom_terms] in Hin.
          apply in_app_iff in Hin. destruct Hin as [Hin|[Heq|[]]].
          -- right. exact Hin.
          -- left. exact Heq.
        * apply planner_query_max_seed.
      + apply IH. exact Hin.
  Qed.

  (** The duplicate counter adds the same number at every initial offset. *)
  Lemma planner_term_copies_acc : forall (ts : list (term V.t)) seen n,
    term_copies seen ts n = n + term_copies seen ts 0.
  Proof.
    induction ts as [|t rest IH]; intros seen n; cbn [term_copies].
    - now rewrite Nat.add_0_r.
    - destruct t as [x|v]; cbn [term_copies].
      + destruct (trie_get x seen).
        * rewrite (IH seen (S n)), (IH seen 1). lia.
        * apply IH.
      + apply IH.
  Qed.

  (** The query duplicate counter adds the same number at every initial offset. *)
  Lemma planner_query_copies_acc : forall (q : list (atom V.t)) n,
    query_copies q n = n + query_copies q 0.
  Proof.
    induction q as [|a rest IH]; intro n; cbn [query_copies].
    - now rewrite Nat.add_0_r.
    - destruct a as [f args res|p args res]; cbn [query_copies].
      + rewrite (IH (term_copies Empty (args ++ option_list res) n)),
          (IH (term_copies Empty (args ++ option_list res) 0)),
          planner_term_copies_acc. lia.
      + apply IH.
  Qed.

  (** Placing terms allocates exactly the copies counted by the preliminary scan. *)
  Lemma planner_place_copies : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn pairs lits copied,
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn)
        pairs lits copied with
    | (VarLayout _ nc' _ _ _ _, _, _, _) => nc' = term_copies seen ts nc
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
        pairs lits copied; cbn [place_terms term_copies].
    - reflexivity.
    - destruct t as [x|v]; cbn [place_terms term_copies].
      + destruct (trie_get x seen).
        * apply IH.
        * destruct (trie_get x names); apply IH.
      + apply IH.
  Qed.

  (** Placing terms preserves the correspondence between layout counters and name lists. *)
  Lemma planner_place_lengths : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn pairs lits copied,
    nc = length cn -> nm = length mn ->
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn)
        pairs lits copied with
    | (VarLayout _ nc' nm' _ cn' mn', _, _, _) =>
        nc' = length cn' /\ nm' = length mn'
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
        pairs lits copied Hcn Hmn; cbn [place_terms].
    - split; assumption.
    - destruct t as [x|v]; cbn [place_terms].
      + destruct (trie_get x seen).
        * apply IH; cbn; congruence.
        * destruct (trie_get x names); apply IH; cbn; congruence.
      + apply IH; cbn; congruence.
  Qed.

  (** Planning atoms allocates exactly the copies counted by the preliminary scan. *)
  Lemma planner_atoms_copies : forall (q : list (atom V.t)) base ai
      names nc nm fresh cn mn st outs post,
    match plan_atoms base q ai (VarLayout names nc nm fresh cn mn) st outs post with
    | (VarLayout _ nc' _ _ _ _, _, _, _) => nc' = query_copies q nc
    end.
  Proof.
    induction q as [|a rest IH]; intros base ai names nc nm fresh cn mn st outs post;
      cbn [plan_atoms query_copies].
    - reflexivity.
    - destruct a as [f args res|p args res]; cbn [plan_atoms query_copies].
      + pose proof (planner_place_copies (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn [] [] false) as Hcopies.
        destruct (place_terms base (args ++ option_list res) 0 Empty
          (VarLayout names nc nm fresh cn mn) [] [] false)
          as [[[lay pairs] lits] copied].
        destruct lay as [names' nc' nm' fresh' cn' mn']; cbn in Hcopies.
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        rewrite <- Hcopies. apply IH.
      + apply IH.
  Qed.

  (** Planning atoms preserves the correspondence between counters and name lists. *)
  Lemma planner_atoms_lengths : forall (q : list (atom V.t)) base ai
      names nc nm fresh cn mn st outs post,
    nc = length cn -> nm = length mn ->
    match plan_atoms base q ai (VarLayout names nc nm fresh cn mn) st outs post with
    | (VarLayout _ nc' nm' _ cn' mn', _, _, _) =>
        nc' = length cn' /\ nm' = length mn'
    end.
  Proof.
    induction q as [|a rest IH]; intros base ai names nc nm fresh cn mn st outs post
      Hcn Hmn; cbn [plan_atoms].
    - split; assumption.
    - destruct a as [f args res|p args res]; cbn [plan_atoms].
      + pose proof (planner_place_lengths (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn [] [] false Hcn Hmn) as Hlengths.
        destruct (place_terms base (args ++ option_list res) 0 Empty
          (VarLayout names nc nm fresh cn mn) [] [] false)
          as [[[lay pairs] lits] copied].
        destruct lay as [names' nc' nm' fresh' cn' mn']; cbn in Hlengths.
        destruct Hlengths as [Hcn' Hmn'].
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        apply IH; assumption.
      + apply IH; assumption.
  Qed.

  (** Distinct unbound names can be numbered without changing existing bindings. *)
  Lemma planner_var_table_complete : forall vars j (t : ptrie N), NoDup vars ->
    (forall x, In x vars -> trie_get x t = None) ->
    exists result, var_table vars j t = Some result /\
      (forall x k, trie_get x t = Some k -> trie_get x result = Some k) /\
      (forall n x, nth_error vars n = Some x ->
        trie_get x result = Some (j + N.of_nat n)%N).
  Proof.
    induction vars as [|x rest IH]; intros j t Hnodup Hnone.
    - exists t. split; [reflexivity|]. split; [auto|].
      intros [|n] y Hnth; discriminate.
    - inversion Hnodup as [|x' rest' Hnot Hrest]; subst x' rest'.
      assert (Hnone' : forall y, In y rest ->
          trie_get y (PTrieCode.set x j t) = None).
      {
        intros y Hin. rewrite PTrie.get_set_other.
        - apply Hnone. now right.
        - intro Heq. subst y. contradiction.
      }
      destruct (IH (N.succ j) (PTrieCode.set x j t) Hrest Hnone')
        as [result [Htable [Hpreserve Hlookup]]].
      exists result. split.
      + cbn [var_table]. rewrite (Hnone x (or_introl eq_refl)). exact Htable.
      + split.
        * intros y k Hold. apply Hpreserve. rewrite PTrie.get_set_other.
          -- exact Hold.
          -- intro Heq. subst y. rewrite (Hnone x (or_introl eq_refl)) in Hold.
             discriminate.
        * intros [|n] y Hnth; cbn [nth_error] in Hnth.
          -- injection Hnth as <-. rewrite N.add_0_r. apply Hpreserve.
             apply PTrie.get_set_same.
          -- replace (j + N.of_nat (S n))%N with (N.succ j + N.of_nat n)%N
               by (rewrite Nat2N.inj_succ; lia).
             exact (Hlookup n y Hnth).
  Qed.

  (** Numbering distinct names from an empty table recovers their list positions. *)
  Lemma planner_var_table_empty : forall vars, NoDup vars ->
    exists names, var_table vars 0 Empty = Some names /\
      forall n x, nth_error vars n = Some x -> trie_get x names = Some (N.of_nat n).
  Proof.
    intros vars Hnodup.
    destruct (planner_var_table_complete vars 0 Empty Hnodup)
      as [names [Htable [_ Hlookup]]].
    - intros x _. apply PTrie.get_empty.
    - exists names. split; [exact Htable|]. intros n x Hnth.
      exact (Hlookup n x Hnth).
  Qed.

  (** Generated names are distinct; copies and unregistered main names are fresh. *)
  Definition planner_names_ok (bound : positive) (lay : var_layout) : Prop :=
    match lay with
    | VarLayout names _ _ fresh cn mn =>
        (bound < fresh)%positive /\ NoDup (cn ++ mn) /\
        Forall (fun x => (x < fresh)%positive) (cn ++ mn) /\
        Forall (fun x => (bound < x)%positive) cn /\
        (forall x, In x mn -> trie_get x names = None -> (bound < x)%positive)
    end.

  (** A newly generated copy name is distinct from all earlier names. *)
  Lemma planner_names_copy : forall bound names nc nm fresh cn mn,
    planner_names_ok bound (VarLayout names nc nm fresh cn mn) ->
    planner_names_ok bound
      (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn).
  Proof.
    intros bound names nc nm fresh cn mn [Hbound [Hnodup [Hbelow [Hcopies Hmain]]]].
    cbn [planner_names_ok]. split; [lia|]. split.
    - constructor; [|exact Hnodup]. intro Hin.
      apply Forall_forall with (x := fresh) in Hbelow; [lia|exact Hin].
    - split.
      + constructor; [lia|]. apply Forall_forall. intros x Hin.
        apply Forall_forall with (x := x) in Hbelow; [lia|exact Hin].
      + split; [constructor; assumption|exact Hmain].
  Qed.

  (** A newly generated literal name is distinct from all earlier names. *)
  Lemma planner_names_literal : forall bound names nc nm fresh cn mn,
    planner_names_ok bound (VarLayout names nc nm fresh cn mn) ->
    planner_names_ok bound
      (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)).
  Proof.
    intros bound names nc nm fresh cn mn [Hbound [Hnodup [Hbelow [Hcopies Hmain]]]].
    cbn [planner_names_ok]. split; [lia|]. split.
    - apply (proj2 (NoDup_Add (Add_app fresh cn mn))). split; [exact Hnodup|].
      intro Hin. apply Forall_forall with (x := fresh) in Hbelow; [lia|exact Hin].
    - split.
      + apply Forall_forall. intros x Hin. apply in_app_iff in Hin.
        destruct Hin as [Hin|[Heq|Hin]].
        * apply Forall_forall with (x := x) in Hbelow; [lia|apply in_app_iff; auto].
        * subst x. lia.
        * apply Forall_forall with (x := x) in Hbelow; [lia|apply in_app_iff; auto].
      + split; [exact Hcopies|]. intros x [Heq|Hin] Hnone.
        * subst x. exact Hbound.
        * exact (Hmain x Hin Hnone).
  Qed.

  (** A previously unregistered real name cannot be an existing fresh or real name. *)
  Lemma planner_names_real : forall bound names nc nm fresh cn mn x j,
    planner_names_ok bound (VarLayout names nc nm fresh cn mn) ->
    (x <= bound)%positive -> trie_get x names = None ->
    planner_names_ok bound
      (VarLayout (PTrieCode.set x j names) nc (S nm) fresh cn (x :: mn)).
  Proof.
    intros bound names nc nm fresh cn mn x j
      [Hbound [Hnodup [Hbelow [Hcopies Hmain]]]] Hx Hnone.
    cbn [planner_names_ok]. split; [exact Hbound|]. split.
    - apply (proj2 (NoDup_Add (Add_app x cn mn))). split; [exact Hnodup|].
      intro Hin. apply in_app_iff in Hin. destruct Hin as [Hin|Hin].
      + apply Forall_forall with (x := x) in Hcopies; [lia|exact Hin].
      + specialize (Hmain x Hin Hnone). lia.
    - split.
      + apply Forall_forall. intros y Hin. apply in_app_iff in Hin.
        destruct Hin as [Hin|[Heq|Hin]].
        * apply Forall_forall with (x := y) in Hbelow; [exact Hbelow|apply in_app_iff; auto].
        * subst y. lia.
        * apply Forall_forall with (x := y) in Hbelow; [exact Hbelow|apply in_app_iff; auto].
      + split; [exact Hcopies|]. intros y [Heq|Hin] Hmissing.
        * subst y. rewrite PTrie.get_set_same in Hmissing. discriminate.
        * destruct (Pos.eq_dec x y) as [Heq|Hneq].
          -- subst y. rewrite PTrie.get_set_same in Hmissing. discriminate.
          -- rewrite PTrie.get_set_other in Hmissing by congruence.
             exact (Hmain y Hin Hmissing).
  Qed.

  (** Placing bounded query variables preserves distinct and fresh layout names. *)
  Lemma planner_place_names : forall (ts : list (term V.t)) bound base pos seen lay
      pairs lits copied,
    planner_names_ok bound lay ->
    (forall x, In (Var x) ts -> (x <= bound)%positive) ->
    match place_terms base ts pos seen lay pairs lits copied with
    | (lay', _, _, _) => planner_names_ok bound lay'
    end.
  Proof.
    induction ts as [|t rest IH]; intros bound base pos seen lay pairs lits copied
      Hnames Hbound; cbn [place_terms].
    - exact Hnames.
    - destruct lay as [names nc nm fresh cn mn].
      destruct t as [x|v]; cbn [place_terms].
      + destruct (trie_get x seen).
        * apply IH.
          -- apply planner_names_copy. exact Hnames.
          -- intros y Hin. apply Hbound. now right.
        * destruct (trie_get x names) eqn:Hname.
          -- apply IH; [exact Hnames|]. intros y Hin. apply Hbound. now right.
          -- apply IH.
             ++ apply planner_names_real; [exact Hnames|apply Hbound; now left|exact Hname].
             ++ intros y Hin. apply Hbound. now right.
      + apply IH.
        * apply planner_names_literal. exact Hnames.
        * intros y Hin. apply Hbound. now right.
  Qed.

  (** Planning atoms preserves distinct and fresh layout names. *)
  Lemma planner_atoms_names : forall (q : list (atom V.t)) bound base ai lay st outs post,
    planner_names_ok bound lay ->
    (forall x, In (Var x) (flat_map atom_terms q) -> (x <= bound)%positive) ->
    match plan_atoms base q ai lay st outs post with
    | (lay', _, _, _) => planner_names_ok bound lay'
    end.
  Proof.
    induction q as [|a rest IH]; intros bound base ai lay st outs post Hnames Hbound;
      cbn [plan_atoms].
    - exact Hnames.
    - destruct a as [f args res|p args res]; cbn [plan_atoms].
      + assert (Hterms : forall x, In (Var x) (args ++ option_list res) ->
            (x <= bound)%positive).
        { intros x Hin. apply Hbound. apply in_app_iff. now left. }
        pose proof (planner_place_names (args ++ option_list res) bound base 0 Empty
          lay [] [] false Hnames Hterms) as Hplaced.
        destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[lay' pairs] lits] copied].
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        apply IH; [exact Hplaced|]. intros x Hin. apply Hbound.
        apply in_app_iff. now right.
      + apply IH; [exact Hnames|]. intros x Hin. apply Hbound.
        apply in_app_iff. now right.
  Qed.

  (** A fresh initial layout satisfies the name invariant. *)
  Lemma planner_names_initial : forall bound,
    planner_names_ok bound (VarLayout Empty 0 0 (Pos.succ bound) [] []).
  Proof.
    intro bound. cbn [planner_names_ok]. split; [lia|].
    split; [constructor|]. split; [constructor|]. split; [constructor|].
    intros x Hin. contradiction.
  Qed.

  (** A rule's variable list has the declared length and no duplicate name. *)
  Lemma planner_rule_variables : forall i r st st' c cs,
    plan_rule i r st = (st', c, cs) ->
    length (var_of V.t c) = nvars (join V.t c) /\ NoDup (var_of V.t c) /\
    Forall (fun x => (query_max (query V.t r) 1%positive < x)%positive)
      (firstn (query_copies (query V.t r) 0) (var_of V.t c)).
  Proof.
    intros i [q acts] st st' c cs Hplan. unfold plan_rule in Hplan.
    pose proof (planner_atoms_copies q (query_copies q 0) 0 Empty 0 0
      (Pos.succ (query_max q 1%positive)) [] [] st [] []) as Hcopies.
    pose proof (planner_atoms_lengths q (query_copies q 0) 0 Empty 0 0
      (Pos.succ (query_max q 1%positive)) [] [] st [] [] eq_refl eq_refl) as Hlengths.
    pose proof (planner_atoms_names q (query_max q 1%positive) (query_copies q 0) 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []
      (planner_names_initial (query_max q 1%positive))) as Hnames.
    specialize (Hnames (fun x Hin => planner_query_max_member q 1%positive x Hin)).
    destruct (plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay state] atoms] post].
    destruct lay as [names nc nm fresh cn mn].
    injection Hplan as <- <- <-. cbn [var_of join nvars query] in *.
    destruct Hlengths as [Hcn Hmn].
    destruct Hnames as [Hfresh [Hnodup [Hbelow [Hcopy _]]]].
    rewrite !rev_append_rev, app_nil_r. split.
    - rewrite length_app, !length_rev. lia.
    - split.
      + eapply Permutation_NoDup; [|exact Hnodup].
        apply Permutation_app; apply Permutation_rev.
      + replace (query_copies q 0) with (length (rev cn)) by (rewrite length_rev; lia).
        rewrite firstn_app, firstn_all, Nat.sub_diag. cbn [firstn].
        rewrite app_nil_r. apply Forall_rev. exact Hcopy.
  Qed.

  (** Every generated rule plan admits the variable-name lookup table. *)
  Lemma planner_rule_var_table : forall i r st st' c cs,
    plan_rule i r st = (st', c, cs) ->
    exists names, var_table (var_of V.t c) 0 Empty = Some names /\
      forall n x, nth_error (var_of V.t c) n = Some x ->
        trie_get x names = Some (N.of_nat n).
  Proof.
    intros i r st st' c cs Hplan.
    destruct (planner_rule_variables i r st st' c cs Hplan) as [_ [Hnodup _]].
    apply planner_var_table_empty. exact Hnodup.
  Qed.

  (** A sufficiently long fresh copy prefix passes the first layout guard. *)
  Lemma planner_layout_fresh_complete : forall vars bound copies j allowed,
    copies <= length vars ->
    Forall (fun x => (bound < x)%positive) (firstn copies vars) ->
    exists result, layout_fresh bound copies vars j allowed = Some result.
  Proof.
    induction vars as [|x rest IH]; intros bound copies j allowed Hlength Hfresh.
    - destruct copies; [exists allowed; reflexivity|cbn in Hlength; lia].
    - destruct copies as [|copies]; cbn [layout_fresh].
      + apply IH; [lia|constructor].
      + cbn [firstn] in Hfresh. inversion Hfresh as [|x' rest' Hx Hrest]; subst x' rest'.
        assert (Htest : Pos.ltb bound x = true) by (apply Pos.ltb_lt; exact Hx).
        rewrite Htest. apply IH; [cbn in Hlength; lia|exact Hrest].
  Qed.

  (** Every registered real variable names its position among the main variables. *)
  Definition planner_main_positions (base : nat) (lay : var_layout) : Prop :=
    match lay with
    | VarLayout names _ nm _ _ mn =>
        nm = length mn /\
        forall x j, trie_get x names = Some j ->
          exists k, j = base + k /\ nth_error (rev mn) k = Some x
    end.

  (** Adding a fresh unnamed main position preserves every registered position. *)
  Lemma planner_main_literal : forall base names nc nm fresh cn mn,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    planner_main_positions base
      (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)).
  Proof.
    intros base names nc nm fresh cn mn [Hlength Hpositions].
    cbn [planner_main_positions]. split; [cbn; congruence|].
    intros x j Hget. destruct (Hpositions x j Hget) as [k [Hj Hnth]].
    exists k. split; [exact Hj|]. cbn [rev]. rewrite nth_error_app1; [exact Hnth|].
    apply nth_error_Some. rewrite Hnth. discriminate.
  Qed.

  (** Registering a new real variable places it after the existing main positions. *)
  Lemma planner_main_real : forall base names nc nm fresh cn mn x,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    trie_get x names = None ->
    planner_main_positions base
      (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn)).
  Proof.
    intros base names nc nm fresh cn mn x [Hlength Hpositions] Hnone.
    cbn [planner_main_positions]. split; [cbn; congruence|].
    intros y j Hget. destruct (Pos.eq_dec x y) as [Heq|Hneq].
    - subst y. rewrite PTrie.get_set_same in Hget. injection Hget as <-.
      exists nm. split; [reflexivity|]. cbn [rev].
      rewrite nth_error_app2; [|rewrite length_rev; lia].
      rewrite length_rev, <- Hlength, Nat.sub_diag. reflexivity.
    - rewrite PTrie.get_set_other in Hget by congruence.
      destruct (Hpositions y j Hget) as [k [Hj Hnth]].
      exists k. split; [exact Hj|]. cbn [rev]. rewrite nth_error_app1; [exact Hnth|].
      apply nth_error_Some. rewrite Hnth. discriminate.
  Qed.

  (** Placing terms preserves the positions assigned to real variables. *)
  Lemma planner_place_positions : forall (ts : list (term V.t)) base pos seen lay
      pairs lits copied,
    planner_main_positions base lay ->
    match place_terms base ts pos seen lay pairs lits copied with
    | (lay', _, _, _) => planner_main_positions base lay'
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen lay pairs lits copied Hpositions;
      cbn [place_terms].
    - exact Hpositions.
    - destruct lay as [names nc nm fresh cn mn]. destruct t as [x|v]; cbn [place_terms].
      + destruct (trie_get x seen).
        * apply IH. exact Hpositions.
        * destruct (trie_get x names) eqn:Hget.
          -- apply IH. exact Hpositions.
          -- apply IH. apply planner_main_real; assumption.
      + apply IH. apply planner_main_literal. exact Hpositions.
  Qed.

  (** Planning atoms preserves the positions assigned to real variables. *)
  Lemma planner_atoms_positions : forall (q : list (atom V.t)) base ai lay st outs post,
    planner_main_positions base lay ->
    match plan_atoms base q ai lay st outs post with
    | (lay', _, _, _) => planner_main_positions base lay'
    end.
  Proof.
    induction q as [|a rest IH]; intros base ai lay st outs post Hpositions;
      cbn [plan_atoms].
    - exact Hpositions.
    - destruct a as [f args res|p args res]; cbn [plan_atoms].
      + pose proof (planner_place_positions (args ++ option_list res) base 0 Empty
          lay [] [] false Hpositions) as Hplaced.
        destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[lay' pairs] lits] copied].
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        apply IH. exact Hplaced.
      + apply IH. exact Hpositions.
  Qed.

  (** Placing more terms preserves every previously registered variable. *)
  Lemma planner_place_registered : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn pairs lits copied x j,
    trie_get x names = Some j ->
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn)
        pairs lits copied with
    | (VarLayout names' _ _ _ _ _, _, _, _) => trie_get x names' = Some j
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
      pairs lits copied x j Hget; cbn [place_terms].
    - exact Hget.
    - destruct t as [y|v]; cbn [place_terms].
      + destruct (trie_get y seen).
        * apply IH. exact Hget.
        * destruct (trie_get y names) eqn:Hy.
          -- apply IH. exact Hget.
          -- apply IH. rewrite PTrie.get_set_other; [exact Hget|].
             intro Heq. subst y. congruence.
      + apply IH. exact Hget.
  Qed.

  (** Planning more atoms preserves every previously registered variable. *)
  Lemma planner_atoms_registered : forall (q : list (atom V.t)) base ai
      names nc nm fresh cn mn st outs post x j,
    trie_get x names = Some j ->
    match plan_atoms base q ai (VarLayout names nc nm fresh cn mn) st outs post with
    | (VarLayout names' _ _ _ _ _, _, _, _) => trie_get x names' = Some j
    end.
  Proof.
    induction q as [|a rest IH]; intros base ai names nc nm fresh cn mn st outs post
      x j Hget; cbn [plan_atoms].
    - exact Hget.
    - destruct a as [f args res|p args res]; cbn [plan_atoms].
      + pose proof (planner_place_registered (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn [] [] false x j Hget) as Hplaced.
        destruct (place_terms base (args ++ option_list res) 0 Empty
          (VarLayout names nc nm fresh cn mn) [] [] false)
          as [[[lay pairs] lits] copied].
        destruct lay as [names' nc' nm' fresh' cn' mn']; cbn in Hplaced.
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        apply IH. exact Hplaced.
      + apply IH. exact Hget.
  Qed.

  (** Placement accumulators prepend precisely the new reversed positions and literals. *)
  Lemma planner_place_acc : forall (ts : list (term V.t)) base pos seen lay copied
      pairs lits,
    place_terms base ts pos seen lay pairs lits copied =
    let '(lay', newpairs, newlits, copied') :=
      place_terms base ts pos seen lay [] [] copied in
    (lay', newpairs ++ pairs, newlits ++ lits, copied').
  Proof.
    induction ts as [|t rest IH]; intros base pos seen lay copied pairs lits.
    - reflexivity.
    - destruct lay as [names nc nm fresh cn mn]. destruct t as [x|v];
        cbn [place_terms].
      + destruct (trie_get x seen).
        * rewrite (IH base (S pos) seen
            (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) true
            ((nc, pos) :: pairs) lits).
          rewrite (IH base (S pos) seen
            (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) true
            [(nc, pos)] []).
          destruct (place_terms base rest (S pos) seen
            (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) [] [] true)
            as [[[lay' ps] ls] cp]. cbn. rewrite app_nil_r, <- app_assoc. reflexivity.
        * destruct (trie_get x names) as [j|].
          -- rewrite (IH base (S pos) (PTrieCode.set x tt seen)
               (VarLayout names nc nm fresh cn mn) copied ((j, pos) :: pairs) lits).
             rewrite (IH base (S pos) (PTrieCode.set x tt seen)
               (VarLayout names nc nm fresh cn mn) copied [(j, pos)] []).
             destruct (place_terms base rest (S pos) (PTrieCode.set x tt seen)
               (VarLayout names nc nm fresh cn mn) [] [] copied)
               as [[[lay' ps] ls] cp]. cbn. rewrite app_nil_r, <- app_assoc. reflexivity.
          -- rewrite (IH base (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               copied ((base + nm, pos) :: pairs) lits).
             rewrite (IH base (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               copied [(base + nm, pos)] []).
             destruct (place_terms base rest (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               [] [] copied) as [[[lay' ps] ls] cp].
             cbn. rewrite app_nil_r, <- app_assoc. reflexivity.
      + rewrite (IH base (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) copied
          ((base + nm, pos) :: pairs) ((base + nm, v) :: lits)).
        rewrite (IH base (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) copied
          [(base + nm, pos)] [(base + nm, v)]).
        destruct (place_terms base rest (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) [] [] copied)
          as [[[lay' ps] ls] cp]. cbn. rewrite <- !app_assoc. reflexivity.
  Qed.

  (** The checker builds the inverse of the reversed position list. *)
  Fixpoint planner_inverse (pairs : list (nat * nat)) (inv : ptrie nat) : ptrie nat :=
    match pairs with
    | [] => inv
    | (j, pos) :: rest => PTrieCode.set (N.succ_pos (nat_n j)) pos (planner_inverse rest inv)
    end.

  (** Appending positions first applies the right list to the inverse table. *)
  Lemma planner_inverse_app : forall xs ys inv,
    planner_inverse (xs ++ ys) inv = planner_inverse xs (planner_inverse ys inv).
  Proof.
    induction xs as [|[j pos] rest IH]; intros ys inv; cbn [app planner_inverse].
    - reflexivity.
    - rewrite IH. reflexivity.
  Qed.

  (** Value equality accepts identical literals. *)
  Lemma planner_value_refl : forall v, V.eqb v v = true.
  Proof.
    intro v. destruct (V.eqb_spec v v); [reflexivity|contradiction].
  Qed.

  (** Checking placed terms reconstructs their inverse position table and consumes literals. *)
  Lemma planner_place_check : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn copied checknames inv srcs cols,
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn) [] [] copied with
    | (VarLayout names' nc' _ _ _ _, pairs, lits, copied') =>
        (forall x j, trie_get x names' = Some j ->
          trie_get x checknames = Some (nat_n j)) ->
        check_terms V.eqb checknames ts pos seen (nat_n nc) inv
          (literal_sources (rev lits) srcs) (literal_cols (rev lits) cols) copied =
        Some (nat_n nc', planner_inverse pairs inv, srcs, cols, copied')
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
      copied checknames inv srcs cols.
    - cbn [place_terms check_terms planner_inverse]. intros _. reflexivity.
    - destruct t as [x|v]; cbn [place_terms].
      + destruct (trie_get x seen) eqn:Hseen.
        * rewrite (planner_place_acc rest base (S pos) seen
            (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) true
            [(nc, pos)] []).
          destruct (place_terms base rest (S pos) seen
            (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) [] [] true)
            as [[[lay pairs] lits] copied'] eqn:Hrest.
          destruct lay as [names' nc' nm' fresh' cn' mn']. intro Hmap.
          rewrite app_nil_r. cbn [check_terms]. rewrite Hseen, planner_inverse_app.
          cbn [planner_inverse].
          pose proof (IH base (S pos) seen names (S nc) nm (Pos.succ fresh)
            (fresh :: cn) mn true checknames (PTrieCode.set (N.succ_pos (nat_n nc)) pos inv)
            srcs cols) as Hcheck.
          rewrite Hrest in Hcheck. exact (Hcheck Hmap).
        * destruct (trie_get x names) as [j|] eqn:Hname.
          -- rewrite (planner_place_acc rest base (S pos) (PTrieCode.set x tt seen)
               (VarLayout names nc nm fresh cn mn) copied [(j, pos)] []).
             destruct (place_terms base rest (S pos) (PTrieCode.set x tt seen)
               (VarLayout names nc nm fresh cn mn) [] [] copied)
               as [[[lay pairs] lits] copied'] eqn:Hrest.
             destruct lay as [names' nc' nm' fresh' cn' mn']. intro Hmap.
             pose proof (planner_place_registered rest base (S pos) (PTrieCode.set x tt seen)
               names nc nm fresh cn mn [] [] copied x j Hname) as Hregistered.
             rewrite Hrest in Hregistered.
             rewrite app_nil_r. cbn [check_terms]. rewrite Hseen, (Hmap x j Hregistered).
             rewrite planner_inverse_app. cbn [planner_inverse].
             pose proof (IH base (S pos) (PTrieCode.set x tt seen) names nc nm fresh cn mn
               copied checknames (PTrieCode.set (N.succ_pos (nat_n j)) pos inv) srcs cols)
               as Hcheck.
             rewrite Hrest in Hcheck. exact (Hcheck Hmap).
          -- rewrite (planner_place_acc rest base (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               copied [(base + nm, pos)] []).
             destruct (place_terms base rest (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               [] [] copied) as [[[lay pairs] lits] copied'] eqn:Hrest.
             destruct lay as [names' nc' nm' fresh' cn' mn']. intro Hmap.
             assert (Hinitial : trie_get x (PTrieCode.set x (base + nm) names) =
                 Some (base + nm)) by apply PTrie.get_set_same.
             pose proof (planner_place_registered rest base (S pos) (PTrieCode.set x tt seen)
               (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn)
               [] [] copied x (base + nm) Hinitial) as Hregistered.
             rewrite Hrest in Hregistered.
             rewrite app_nil_r. cbn [check_terms].
             rewrite Hseen, (Hmap x (base + nm) Hregistered), planner_inverse_app.
             cbn [planner_inverse].
             pose proof (IH base (S pos) (PTrieCode.set x tt seen)
               (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn) copied
               checknames (PTrieCode.set (N.succ_pos (nat_n (base + nm))) pos inv) srcs cols)
               as Hcheck.
             rewrite Hrest in Hcheck. exact (Hcheck Hmap).
      + rewrite (planner_place_acc rest base (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) copied
          [(base + nm, pos)] [(base + nm, v)]).
        destruct (place_terms base rest (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) [] [] copied)
          as [[[lay pairs] lits] copied'] eqn:Hrest.
        destruct lay as [names' nc' nm' fresh' cn' mn']. intro Hmap.
        rewrite rev_app_distr. cbn [rev app literal_sources literal_cols check_terms].
        rewrite planner_value_refl, planner_inverse_app. cbn [planner_inverse].
        pose proof (IH base (S pos) seen names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)
          copied checknames (PTrieCode.set (N.succ_pos (nat_n (base + nm))) pos inv) srcs cols)
          as Hcheck.
        rewrite Hrest in Hcheck. exact (Hcheck Hmap).
  Qed.

  (** A registered main position lies in the main interval and names only one variable. *)
  Lemma planner_registered_range : forall base names nc nm fresh cn mn x j,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    trie_get x names = Some j -> base <= j /\ j < base + nm.
  Proof.
    intros base names nc nm fresh cn mn x j [Hlength Hpositions] Hget.
    destruct (Hpositions x j Hget) as [k [Hj Hnth]].
    assert (Hk : k < length (rev mn)) by (apply nth_error_Some; rewrite Hnth; discriminate).
    rewrite length_rev in Hk. lia.
  Qed.

  (** Distinct registered names have distinct main positions. *)
  Lemma planner_registered_injective : forall base names nc nm fresh cn mn x y j,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    trie_get x names = Some j -> trie_get y names = Some j -> x = y.
  Proof.
    intros base names nc nm fresh cn mn x y j [_ Hpositions] Hx Hy.
    destruct (Hpositions x j Hx) as [kx [Hxindex Hxnth]].
    destruct (Hpositions y j Hy) as [ky [Hyindex Hynth]].
    assert (Heq : kx = ky) by lia. subst ky. congruence.
  Qed.

  (** Already placed pairs use earlier copies or main positions. A real position can occur
      only after its variable has been seen in this atom. *)
  Definition planner_pairs_ok (base : nat) (seen : ptrie unit) (lay : var_layout)
      (pairs : list (nat * nat)) : Prop :=
    match lay with
    | VarLayout names nc nm _ _ _ =>
        NoDup (map fst pairs) /\
        Forall (fun jp => fst jp < base + nm /\ (fst jp < nc \/ base <= fst jp)) pairs /\
        (forall x j, trie_get x names = Some j -> In j (map fst pairs) ->
          exists u, trie_get x seen = Some u)
    end.

  (** Empty positions satisfy the atom-local pairing invariant. *)
  Lemma planner_pairs_empty : forall base seen lay, planner_pairs_ok base seen lay [].
  Proof.
    intros base seen [names nc nm fresh cn mn]. cbn [planner_pairs_ok].
    split; [constructor|]. split; [constructor|]. intros x j Hget Hin. contradiction.
  Qed.

  (** A new copy index is below the main interval and above every earlier copy. *)
  Lemma planner_pairs_copy : forall base seen names nc nm fresh cn mn pairs pos,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    planner_pairs_ok base seen (VarLayout names nc nm fresh cn mn) pairs -> nc < base ->
    planner_pairs_ok base seen
      (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) ((nc, pos) :: pairs).
  Proof.
    intros base seen names nc nm fresh cn mn pairs pos Hmain
      [Hnodup [Hbounds Hseen]] Hcopy. cbn [planner_pairs_ok]. split.
    - constructor; [|exact Hnodup]. intro Hin.
      apply in_map_iff in Hin as [[j p] [Heq Hin]]. cbn in Heq. subst j.
      apply Forall_forall with (x := (nc, p)) in Hbounds; [cbn in Hbounds; lia|exact Hin].
    - split.
      + constructor; [cbn; lia|]. apply Forall_forall. intros [j p] Hin.
        apply Forall_forall with (x := (j, p)) in Hbounds; [cbn in *; lia|exact Hin].
      + intros x j Hget [Heq|Hin].
        * pose proof (planner_registered_range base names nc nm fresh cn mn x j Hmain Hget).
          cbn in Heq. lia.
        * exact (Hseen x j Hget Hin).
  Qed.

  (** A new literal index comes after every existing main position. *)
  Lemma planner_pairs_literal : forall base seen names nc nm fresh cn mn pairs pos,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    planner_pairs_ok base seen (VarLayout names nc nm fresh cn mn) pairs ->
    planner_pairs_ok base seen
      (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn))
      ((base + nm, pos) :: pairs).
  Proof.
    intros base seen names nc nm fresh cn mn pairs pos Hmain [Hnodup [Hbounds Hseen]].
    cbn [planner_pairs_ok]. split.
    - constructor; [|exact Hnodup]. intro Hin.
      apply in_map_iff in Hin as [[j p] [Heq Hin]]. cbn in Heq. subst j.
      apply Forall_forall with (x := (base + nm, p)) in Hbounds;
        [cbn in Hbounds; lia|exact Hin].
    - split.
      + constructor; [cbn; lia|]. apply Forall_forall. intros [j p] Hin.
        apply Forall_forall with (x := (j, p)) in Hbounds; [cbn in *; lia|exact Hin].
      + intros x j Hget [Heq|Hin].
        * pose proof (planner_registered_range base names nc nm fresh cn mn x j Hmain Hget).
          cbn in Heq. lia.
        * exact (Hseen x j Hget Hin).
  Qed.

  (** A first atom-local occurrence may reuse its existing global main position. *)
  Lemma planner_pairs_reuse : forall base seen names nc nm fresh cn mn pairs pos x j,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    planner_pairs_ok base seen (VarLayout names nc nm fresh cn mn) pairs ->
    trie_get x seen = None -> trie_get x names = Some j ->
    planner_pairs_ok base (PTrieCode.set x tt seen)
      (VarLayout names nc nm fresh cn mn) ((j, pos) :: pairs).
  Proof.
    intros base seen names nc nm fresh cn mn pairs pos x j Hmain
      [Hnodup [Hbounds Hseen]] Hmissing Hget. cbn [planner_pairs_ok]. split.
    - constructor; [|exact Hnodup]. intro Hin.
      destruct (Hseen x j Hget Hin) as [u Hu]. congruence.
    - split.
      + constructor; [|exact Hbounds]. cbn.
        pose proof (planner_registered_range base names nc nm fresh cn mn x j Hmain Hget).
        lia.
      + intros y k Hy [Heq|Hin].
        * cbn in Heq. subst k.
          pose proof (planner_registered_injective base names nc nm fresh cn mn x y j
            Hmain Hget Hy) as Hxy. subst y.
          exists tt. apply PTrie.get_set_same.
        * destruct (Pos.eq_dec x y) as [Heq|Hneq].
          -- subst y. exists tt. apply PTrie.get_set_same.
          -- destruct (Hseen y k Hy Hin) as [u Hu]. exists u.
             rewrite PTrie.get_set_other by congruence. exact Hu.
  Qed.

  (** A new real variable receives a new main index and becomes seen in its atom. *)
  Lemma planner_pairs_real : forall base seen names nc nm fresh cn mn pairs pos x,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    planner_pairs_ok base seen (VarLayout names nc nm fresh cn mn) pairs ->
    trie_get x names = None ->
    planner_pairs_ok base (PTrieCode.set x tt seen)
      (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
      ((base + nm, pos) :: pairs).
  Proof.
    intros base seen names nc nm fresh cn mn pairs pos x Hmain
      [Hnodup [Hbounds Hseen]] Hmissing. cbn [planner_pairs_ok]. split.
    - constructor; [|exact Hnodup]. intro Hin.
      apply in_map_iff in Hin as [[j p] [Heq Hin]]. cbn in Heq. subst j.
      apply Forall_forall with (x := (base + nm, p)) in Hbounds;
        [cbn in Hbounds; lia|exact Hin].
    - split.
      + constructor; [cbn; lia|]. apply Forall_forall. intros [j p] Hin.
        apply Forall_forall with (x := (j, p)) in Hbounds; [cbn in *; lia|exact Hin].
      + intros y k Hy Hin. destruct (Pos.eq_dec x y) as [Heq|Hneq].
        * subst y. exists tt. apply PTrie.get_set_same.
        * rewrite PTrie.get_set_other in Hy by congruence.
          destruct Hin as [Heq|Hin].
          -- pose proof (planner_registered_range base names nc nm fresh cn mn y k Hmain Hy).
             cbn in Heq. lia.
          -- destruct (Hseen y k Hy Hin) as [u Hu]. exists u.
             rewrite PTrie.get_set_other by congruence. exact Hu.
  Qed.

  (** A bounded copy budget makes every atom position use a distinct join index. *)
  Lemma planner_place_pairs : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn pairs lits copied,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    planner_pairs_ok base seen (VarLayout names nc nm fresh cn mn) pairs ->
    term_copies seen ts nc <= base ->
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn)
        pairs lits copied with
    | (lay', pairs', _, _) =>
        NoDup (map fst pairs') /\
        match lay' with
        | VarLayout _ _ nm' _ _ _ => Forall (fun jp => fst jp < base + nm') pairs'
        end
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
      pairs lits copied Hmain Hpairs Hbudget; cbn [place_terms].
    - destruct Hpairs as [Hnodup [Hbounds _]]. split; [exact Hnodup|].
      apply Forall_forall. intros [j p] Hin.
      apply Forall_forall with (x := (j, p)) in Hbounds; [exact (proj1 Hbounds)|exact Hin].
    - destruct t as [x|v]; cbn [place_terms term_copies] in *.
      + destruct (trie_get x seen) eqn:Hseen.
        * apply IH.
          -- exact Hmain.
          -- apply planner_pairs_copy; [exact Hmain|exact Hpairs|].
             pose proof (planner_term_copies_acc rest seen (S nc)). lia.
          -- exact Hbudget.
        * destruct (trie_get x names) as [j|] eqn:Hget.
          -- apply IH; [exact Hmain| |exact Hbudget].
             apply planner_pairs_reuse; assumption.
          -- apply IH; [apply planner_main_real; assumption| |exact Hbudget].
             apply planner_pairs_real; assumption.
      + apply IH; [apply planner_main_literal; exact Hmain| |exact Hbudget].
        apply planner_pairs_literal; assumption.
  Qed.

  (** The indices allocated so far consist of a copy prefix and a main interval. *)
  Definition planner_used (base : nat) (lay : var_layout) (j : nat) : Prop :=
    match lay with
    | VarLayout _ nc nm _ _ _ => j < nc \/ (base <= j /\ j < base + nm)
    end.

  (** The new positions cover exactly the indices added by a term-placement pass. *)
  Lemma planner_place_coverage : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn copied,
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn) [] [] copied with
    | (lay', pairs, _, _) => forall j,
        planner_used base lay' j <->
        planner_used base (VarLayout names nc nm fresh cn mn) j \/ In j (map fst pairs)
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
      copied Hmain.
    - cbn [place_terms map In]. intro j. tauto.
    - destruct t as [x|v]; cbn [place_terms].
      + destruct (trie_get x seen) eqn:Hseen.
        * rewrite (planner_place_acc rest base (S pos) seen
            (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) true
            [(nc, pos)] []).
          pose proof (IH base (S pos) seen names (S nc) nm (Pos.succ fresh)
            (fresh :: cn) mn true Hmain) as Hcoverage.
          destruct (place_terms base rest (S pos) seen
            (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn) [] [] true)
            as [[[lay pairs] lits] copied'].
          intro j. rewrite Hcoverage, map_app, in_app_iff.
          cbn [planner_used map In fst]. intuition lia.
        * destruct (trie_get x names) as [k|] eqn:Hname.
          -- rewrite (planner_place_acc rest base (S pos) (PTrieCode.set x tt seen)
               (VarLayout names nc nm fresh cn mn) copied [(k, pos)] []).
             pose proof (IH base (S pos) (PTrieCode.set x tt seen) names nc nm fresh cn mn
               copied Hmain) as Hcoverage.
             destruct (place_terms base rest (S pos) (PTrieCode.set x tt seen)
               (VarLayout names nc nm fresh cn mn) [] [] copied)
               as [[[lay pairs] lits] copied'].
             intro j. rewrite Hcoverage, map_app, in_app_iff.
             pose proof (planner_registered_range base names nc nm fresh cn mn x k Hmain Hname).
             cbn [planner_used map In fst]. intuition lia.
          -- rewrite (planner_place_acc rest base (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               copied [(base + nm, pos)] []).
             pose proof (IH base (S pos) (PTrieCode.set x tt seen)
               (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn) copied
               (planner_main_real base names nc nm fresh cn mn x Hmain Hname)) as Hcoverage.
             destruct (place_terms base rest (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               [] [] copied) as [[[lay pairs] lits] copied'].
             intro j. rewrite Hcoverage, map_app, in_app_iff.
             cbn [planner_used map In fst]. intuition lia.
      + rewrite (planner_place_acc rest base (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) copied
          [(base + nm, pos)] [(base + nm, v)]).
        pose proof (IH base (S pos) seen names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)
          copied (planner_main_literal base names nc nm fresh cn mn Hmain)) as Hcoverage.
        destruct (place_terms base rest (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) [] [] copied)
          as [[[lay pairs] lits] copied'].
        intro j. rewrite Hcoverage, map_app, in_app_iff.
        cbn [planner_used map In fst]. intuition lia.
  Qed.

  (** Later placement preserves every earlier main-name position. *)
  Lemma planner_place_main_entry : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn pairs lits copied k x,
    nth_error (rev mn) k = Some x ->
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn)
        pairs lits copied with
    | (VarLayout _ _ _ _ _ mn', _, _, _) => nth_error (rev mn') k = Some x
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
      pairs lits copied k x Hnth; cbn [place_terms].
    - exact Hnth.
    - destruct t as [y|v]; cbn [place_terms].
      + destruct (trie_get y seen).
        * apply IH. exact Hnth.
        * destruct (trie_get y names).
          -- apply IH. exact Hnth.
          -- apply IH. cbn [rev]. rewrite nth_error_app1; [exact Hnth|].
             apply nth_error_Some. rewrite Hnth. discriminate.
      + apply IH. cbn [rev]. rewrite nth_error_app1; [exact Hnth|].
        apply nth_error_Some. rewrite Hnth. discriminate.
  Qed.

  (** Later placement never decreases the number of main indices. *)
  Lemma planner_place_mains : forall (ts : list (term V.t)) base pos seen
      names nc nm fresh cn mn pairs lits copied,
    match place_terms base ts pos seen (VarLayout names nc nm fresh cn mn)
        pairs lits copied with
    | (VarLayout _ _ nm' _ _ _, _, _, _) => nm <= nm'
    end.
  Proof.
    induction ts as [|t rest IH]; intros base pos seen names nc nm fresh cn mn
      pairs lits copied; cbn [place_terms].
    - lia.
    - destruct t as [x|v]; cbn [place_terms].
      + destruct (trie_get x seen).
        * apply IH.
        * destruct (trie_get x names).
          -- apply IH.
          -- pose proof (IH base (S pos) (PTrieCode.set x tt seen)
               (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn)
               ((base + nm, pos) :: pairs) lits copied) as Hmains.
             destruct (place_terms base rest (S pos) (PTrieCode.set x tt seen)
               (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
               ((base + nm, pos) :: pairs) lits copied)
               as [[[lay' ps] ls] cp]. destruct lay'. cbn in Hmains. lia.
      + pose proof (IH base (S pos) seen names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)
          ((base + nm, pos) :: pairs) ((base + nm, v) :: lits) copied) as Hmains.
        destruct (place_terms base rest (S pos) seen
          (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn))
          ((base + nm, pos) :: pairs) ((base + nm, v) :: lits) copied)
          as [[[lay' ps] ls] cp]. destruct lay'. cbn in Hmains. lia.
  Qed.

  (** Every positive trie key encodes a natural-number column. *)
  Lemma planner_column_key_surj : forall k,
    exists j, k = N.succ_pos (nat_n j).
  Proof.
    intro k. exists (N.to_nat (Pos.pred_N k)).
    rewrite planner_nat_n_spec, N2Nat.id.
    assert (Hkey : Npos k = Npos (N.succ_pos (Pos.pred_N k))).
    { rewrite N.succ_pos_spec, N.succ_pos_pred. reflexivity. }
    now injection Hkey.
  Qed.

  (** Distinct pair indices keep every position visible in their inverse trie. *)
  Lemma planner_inverse_member : forall pairs inv j pos,
    NoDup (map fst pairs) -> In (j, pos) pairs ->
    trie_get (N.succ_pos (nat_n j)) (planner_inverse pairs inv) = Some pos.
  Proof.
    intros pairs. induction pairs as [|[k q] pairs IH]; intros inv j pos Hnodup Hin;
      [contradiction|].
    cbn [map fst] in Hnodup. inversion Hnodup as [|? ? Hfresh Htail]; subst.
    cbn [planner_inverse]. destruct Hin as [Heq|Hin].
    - injection Heq as <- <-. apply PTrie.get_set_same.
    - rewrite PTrie.get_set_other.
      + apply IH; assumption.
      + intro Heq. apply planner_column_key_inj in Heq. subst j.
        apply Hfresh. apply in_map_iff. exists (k, pos). split; [reflexivity|exact Hin].
  Qed.

  (** The used-key list exposes the finite domain of the checker's unit trie. *)
  Definition planner_used_keys (used : ptrie unit) : list positive :=
    map fst (PTrie.elements used).

  (** A used key occurs exactly when its trie lookup returns the unique unit value. *)
  Lemma planner_used_keys_spec : forall used k,
    In k (planner_used_keys used) <-> trie_get k used = Some tt.
  Proof.
    intros used k. unfold planner_used_keys. split.
    - intro Hin. apply in_map_iff in Hin as [[p []] [Heq Hin]]. cbn in Heq. subst p.
      apply (proj1 (PTrie.elements_spec unit used k tt)). exact Hin.
    - intro Hget. apply in_map_iff. exists (k, tt). split; [reflexivity|].
      apply (proj2 (PTrie.elements_spec unit used k tt)). exact Hget.
  Qed.

  (** A trie lists every used key once. *)
  Lemma planner_used_keys_nodup : forall used, NoDup (planner_used_keys used).
  Proof.
    intro used. apply PTrie.elements_nodup.
  Qed.

  (** Inserting an already used key leaves the trie unchanged. *)
  Lemma planner_used_set_old : forall used k,
    trie_get k used = Some tt -> PTrieCode.set k tt used = used.
  Proof.
    intros used k Hget. apply PTrie.ext. intro q.
    destruct (Pos.eq_dec k q) as [->|Hneq].
    - rewrite PTrie.get_set_same. symmetry. exact Hget.
    - rewrite PTrie.get_set_other by congruence. reflexivity.
  Qed.

  (** Inserting a key adds exactly that key to the used-key predicate. *)
  Lemma planner_used_set_keys : forall used k q,
    In q (planner_used_keys (PTrieCode.set k tt used)) <->
      k = q \/ In q (planner_used_keys used).
  Proof.
    intros used k q. rewrite !planner_used_keys_spec.
    destruct (Pos.eq_dec k q) as [->|Hneq].
    - rewrite PTrie.get_set_same. tauto.
    - rewrite PTrie.get_set_other by congruence. tauto.
  Qed.

  (** The checker count is the cardinality of its used-key trie. *)
  Definition planner_used_count (used : ptrie unit) (count : N) : Prop :=
    count = N.of_nat (length (planner_used_keys used)).

  (** An empty used-key trie has zero cardinality. *)
  Lemma planner_used_count_empty : planner_used_count Empty 0%N.
  Proof.
    reflexivity.
  Qed.

  (** Insertion increases the count precisely when its key was previously absent. *)
  Lemma planner_used_count_set : forall used count k,
    planner_used_count used count ->
    planner_used_count (PTrieCode.set k tt used)
      (match trie_get k used with Some _ => count | None => N.succ count end).
  Proof.
    intros used count k Hcount. destruct (trie_get k used) as [[]|] eqn:Hget.
    - rewrite (planner_used_set_old used k Hget). exact Hcount.
    - assert (Hperm : Permutation (k :: planner_used_keys used)
        (planner_used_keys (PTrieCode.set k tt used))).
      { apply NoDup_Permutation.
        - constructor; [|apply planner_used_keys_nodup]. intro Hin.
          apply planner_used_keys_spec in Hin. congruence.
        - apply planner_used_keys_nodup.
        - intro q. cbn. symmetry. apply planner_used_set_keys. }
      pose proof (Permutation_length Hperm) as Hlength. cbn [length] in Hlength.
      unfold planner_used_count in *. rewrite <- Hlength, Nat2N.inj_succ, <- Hcount.
      reflexivity.
  Qed.

  (** Inserting a column key adds precisely that column to the lookup predicate. *)
  Lemma planner_used_set_column : forall used j k,
    trie_get (N.succ_pos (nat_n k))
      (PTrieCode.set (N.succ_pos (nat_n j)) tt used) = Some tt <->
      j = k \/ trie_get (N.succ_pos (nat_n k)) used = Some tt.
  Proof.
    intros used j k. rewrite <- !planner_used_keys_spec, planner_used_set_keys.
    split.
    - intros [Heq|Hin]; [left; apply planner_column_key_inj; exact Heq|right; exact Hin].
    - intros [->|Hin]; [left; reflexivity|right; exact Hin].
  Qed.

  (** Reading a pair list through its inverse emits the positions and records its columns. *)
  Lemma planner_column_perm_pairs : forall pairs inv used count,
    (forall j pos, In (j, pos) pairs -> trie_get (N.succ_pos (nat_n j)) inv = Some pos) ->
    planner_used_count used count ->
    exists used' count',
      column_perm inv (map fst pairs) used count = Some (map snd pairs, used', count') /\
      planner_used_count used' count' /\
      forall k, trie_get (N.succ_pos (nat_n k)) used' = Some tt <->
        trie_get (N.succ_pos (nat_n k)) used = Some tt \/ In k (map fst pairs).
  Proof.
    intros pairs. induction pairs as [|[j pos] pairs IH]; intros inv used count Hlookup Hcount.
    - exists used, count. split; [reflexivity|]. split; [exact Hcount|].
      intro k. cbn. tauto.
    - assert (Hhead : trie_get (N.succ_pos (nat_n j)) inv = Some pos).
      { apply Hlookup. left. reflexivity. }
      assert (Htail : forall k q, In (k, q) pairs ->
        trie_get (N.succ_pos (nat_n k)) inv = Some q).
      { intros k q Hin. apply Hlookup. right. exact Hin. }
      pose proof (planner_used_count_set used count (N.succ_pos (nat_n j)) Hcount) as Hnext.
      destruct (IH inv (PTrieCode.set (N.succ_pos (nat_n j)) tt used)
        (match trie_get (N.succ_pos (nat_n j)) used with
         | Some _ => count
         | None => N.succ count
         end) Htail Hnext) as [used' [count' [Hread [Hcount' Hused]]]].
      exists used', count'. split.
      + cbn [column_perm map fst snd]. rewrite Hhead, Hread. reflexivity.
      + split; [exact Hcount'|]. intro k. rewrite Hused, planner_used_set_column.
        cbn [map fst In]. tauto.
  Qed.

  (** Sorting preserves the column membership of a pair list. *)
  Lemma planner_sorted_column_member : forall pairs k,
    In k (map fst (sort_pairs pairs)) <-> In k (map fst pairs).
  Proof.
    intros pairs k. split; intro Hin.
    - eapply Permutation_in; [|exact Hin].
      apply Permutation_sym. apply Permutation_map. apply planner_sort_pairs_perm.
    - eapply Permutation_in; [|exact Hin].
      apply Permutation_map. apply planner_sort_pairs_perm.
  Qed.

  (** A generated inverse and sorted column recover the exact sorted slot permutation. *)
  Lemma planner_column_perm_sorted : forall pairs used count,
    NoDup (map fst pairs) -> planner_used_count used count ->
    exists used' count',
      column_perm (planner_inverse pairs Empty) (map fst (sort_pairs pairs)) used count =
        Some (map snd (sort_pairs pairs), used', count') /\
      planner_used_count used' count' /\
      forall k, trie_get (N.succ_pos (nat_n k)) used' = Some tt <->
        trie_get (N.succ_pos (nat_n k)) used = Some tt \/ In k (map fst pairs).
  Proof.
    intros pairs used count Hnodup Hcount.
    assert (Hlookup : forall j pos, In (j, pos) (sort_pairs pairs) ->
      trie_get (N.succ_pos (nat_n j)) (planner_inverse pairs Empty) = Some pos).
    { intros j pos Hin. apply planner_inverse_member; [exact Hnodup|].
      eapply Permutation_in; [|exact Hin].
      apply Permutation_sym. apply planner_sort_pairs_perm. }
    destruct (planner_column_perm_pairs (sort_pairs pairs) _ _ _ Hlookup Hcount)
      as [used' [count' [Hread [Hcount' Hused]]]].
    exists used', count'. split; [exact Hread|]. split; [exact Hcount'|].
    intro k. rewrite Hused, planner_sorted_column_member. reflexivity.
  Qed.

  (** Distinct column numbers remain distinct after encoding as trie keys. *)
  Lemma planner_column_keys_nodup : forall js,
    NoDup js -> NoDup (map (fun j => N.succ_pos (nat_n j)) js).
  Proof.
    intros js Hnodup. induction Hnodup as [|j js Hfresh Htail IH]; cbn [map].
    - constructor.
    - constructor; [|exact IH]. intro Hin.
      apply in_map_iff in Hin as [k [Heq Hin]]. apply planner_column_key_inj in Heq.
      subst k. contradiction.
  Qed.

  (** A column occurs among encoded keys exactly when its number occurs in their source. *)
  Lemma planner_column_keys_member : forall js j,
    In (N.succ_pos (nat_n j)) (map (fun k => N.succ_pos (nat_n k)) js) <-> In j js.
  Proof.
    intros js j. split.
    - intro Hin. apply in_map_iff in Hin as [k [Heq Hin]].
      apply planner_column_key_inj in Heq. now subst k.
    - intro Hin. apply in_map_iff. exists j. split; [reflexivity|exact Hin].
  Qed.

  (** Disjoint copy and main intervals contain exactly their combined number of indices. *)
  Lemma planner_used_range_count : forall used count base nc nm,
    planner_used_count used count -> nc <= base ->
    (forall j, trie_get (N.succ_pos (nat_n j)) used = Some tt <->
      j < nc \/ (base <= j /\ j < base + nm)) ->
    count = N.of_nat (nc + nm).
  Proof.
    intros used count base nc nm Hcount Hdisjoint Hrange.
    assert (Hnodup : NoDup (seq 0 nc ++ seq base nm)).
    { apply NoDup_app; try apply seq_NoDup.
      intros j Hcopy Hmain. apply in_seq in Hcopy. apply in_seq in Hmain. lia. }
    assert (Hperm : Permutation (planner_used_keys used)
      (map (fun j => N.succ_pos (nat_n j)) (seq 0 nc ++ seq base nm))).
    { apply NoDup_Permutation.
      - apply planner_used_keys_nodup.
      - apply planner_column_keys_nodup. exact Hnodup.
      - intro key. destruct (planner_column_key_surj key) as [j ->].
        rewrite planner_used_keys_spec, Hrange, planner_column_keys_member,
          in_app_iff, !in_seq. lia. }
    pose proof (Permutation_length Hperm) as Hlength.
    rewrite length_map, length_app, !length_seq in Hlength.
    unfold planner_used_count in Hcount. now rewrite Hlength in Hcount.
  Qed.

  (** Placing terms appends their reversed positions to the existing reversed positions. *)
  Lemma planner_place_positions_result : forall base (ts : list (term V.t)) pos seen lay
      pairs lits copied lay' pairs' lits' copied',
    place_terms base ts pos seen lay pairs lits copied = (lay', pairs', lits', copied') ->
    map snd pairs' = rev (seq pos (length ts)) ++ map snd pairs.
  Proof.
    intros base ts. induction ts as [| t rest IH]; intros pos seen lay pairs lits copied
      lay' pairs' lits' copied' Hplaced.
    - cbn [place_terms] in Hplaced. inversion Hplaced; subst. reflexivity.
    - destruct lay as [names nc nm fresh cn mn]. destruct t as [x | v];
        cbn [place_terms] in Hplaced.
      + destruct (trie_get x seen) as [u |]; [| destruct (trie_get x names) as [j |]].
        all: etransitivity; [eapply IH; exact Hplaced |];
          cbn [seq rev map length]; rewrite <- app_assoc; reflexivity.
      + etransitivity; [eapply IH; exact Hplaced |].
        cbn [seq rev map length]. rewrite <- app_assoc. reflexivity.
  Qed.

  (** Every placed term contributes its original position to the reversed pair list. *)
  Lemma planner_place_positions_list : forall base (ts : list (term V.t)) pos seen lay
      pairs lits copied,
    let '(_, pairs', _, _) := place_terms base ts pos seen lay pairs lits copied in
    map snd pairs' = rev (seq pos (length ts)) ++ map snd pairs.
  Proof.
    intros base ts pos seen lay pairs lits copied.
    destruct (place_terms base ts pos seen lay pairs lits copied)
      as [[[lay' pairs'] lits'] copied'] eqn:Hplaced.
    eapply planner_place_positions_result. exact Hplaced.
  Qed.

  (** The sorted permutation of one placed atom uses each of its positions once. *)
  Lemma planner_place_perm_ok : forall base (ts : list (term V.t)) lay
      lay' pairs lits copied,
    place_terms base ts 0 Empty lay [] [] false = (lay', pairs, lits, copied) ->
    perm_ok (length ts) (map snd (sort_pairs pairs)) Empty = true.
  Proof.
    intros base ts lay lay' pairs lits copied Hplaced.
    pose proof (planner_place_positions_list base ts 0 Empty lay [] [] false) as Hpositions.
    rewrite Hplaced in Hpositions. cbn in Hpositions. rewrite app_nil_r in Hpositions.
    apply planner_sorted_perm_ok.
    - rewrite Hpositions. apply NoDup_rev. apply seq_NoDup.
    - apply (proj1 (@Forall_map (nat * nat) nat (@snd nat nat)
        (fun i => i < length ts) pairs)).
      rewrite Hpositions. apply Forall_rev.
      rewrite Forall_forall. intros i Hin. apply in_seq in Hin. lia.
  Qed.

  (** The first declaration determines the width used by the slot checker. *)
  Lemma planner_decl_width : forall ds f ss o,
    lookup_sorts ds f = Some ss -> lookup_kind ds f = Some o ->
    trie_get f (decl_widths ds Empty) =
      Some (length ss + match o with ORel => 0 | _ => 1 end).
  Proof.
    intros ds f ss o Hsort Hkind.
    destruct (run_lookup_sorts_decl ds f ss Hsort) as [d [Hfind Hargs]].
    destruct (run_find_decl_fields ds f d Hfind) as [_ Hout].
    assert (Hkindout : out d = o) by congruence.
    rewrite decl_widths_get, PTrie.get_empty, Hfind, Hargs, Hkindout. reflexivity.
  Qed.

  (** Binding arguments preserves their declared argument count. *)
  Lemma planner_binds_length : forall g ts ss g',
    @binds_list V.t g ts ss g' -> length ts = length ss.
  Proof.
    intros g ts ss g' Hbind. induction Hbind; cbn; congruence.
  Qed.

  (** A well-sorted result occupies exactly the output position of its declared kind. *)
  Lemma planner_result_length : forall g o res g', @binds_result V.t g o res g' ->
    length (option_list res) = match o with ORel => 0 | _ => 1 end.
  Proof.
    intros g o [t |] g' Hresult; destruct o; cbn [binds_result out_sort] in Hresult;
      try contradiction; reflexivity.
  Qed.

  Definition planner_slot_valid (widths : ptrie nat) (fp : positive * list nat) : Prop :=
    exists width, trie_get (fst fp) widths = Some width /\
      perm_ok width (snd fp) Empty = true.

  (** Adding a row with an elementwise property preserves that property of all rows. *)
  Lemma add_slot_property : forall (P : positive * list nat -> Prop) f perm st,
    Forall P (planner_rows st) -> P (f, perm) ->
    Forall P (planner_rows (snd (add_slot f perm st))).
  Proof.
    intros P f perm [table next rows] Hrows Hnew. cbn [add_slot].
    destruct (trie_get (slot_code f perm) table); cbn; [exact Hrows |].
    constructor; assumption.
  Qed.

  (** Full-slot registration needs the property only for unseen first declarations. *)
  Lemma full_slots_property : forall (P : positive * list nat -> Prop) ds seen st,
    Forall P (planner_rows st) ->
    (forall f ss, trie_get f seen = None -> lookup_kind ds f = Some OId ->
      lookup_sorts ds f = Some ss -> P (f, count_from 0 (S (length ss)))) ->
    Forall P (planner_rows (full_slots ds seen st)).
  Proof.
    intros P ds. induction ds as [| [g sorts o] rest IH]; intros seen st Hrows Hdecl.
    - exact Hrows.
    - cbn [full_slots]. destruct (trie_get g seen) as [u |] eqn:Hseen.
      + apply IH; [exact Hrows |].
        intros f ss Hunseen Hkind Hsorts.
        destruct (Pos.eqb g f) eqn:Hgf.
        * apply Pos.eqb_eq in Hgf. subst g. rewrite Hseen in Hunseen. discriminate Hunseen.
        * apply Hdecl; [exact Hunseen | |];
            cbn [lookup_kind lookup_sorts name arg_sorts out]; rewrite Hgf; assumption.
      + assert (Hnext : forall f ss, trie_get f (PTrieCode.set g tt seen) = None ->
            lookup_kind rest f = Some OId -> lookup_sorts rest f = Some ss ->
            P (f, count_from 0 (S (length ss)))).
        { intros f ss Hunseen Hkind Hsorts.
          destruct (run_get_set_none seen g f Hunseen) as [Hold Hneq].
          assert (Hgf : Pos.eqb g f = false) by (apply Pos.eqb_neq; congruence).
          apply Hdecl; [exact Hold | |];
            cbn [lookup_kind lookup_sorts name arg_sorts out]; rewrite Hgf; assumption. }
        destruct o; apply IH; try exact Hnext; try exact Hrows.
        apply add_slot_property; [exact Hrows |].
        apply Hdecl; [exact Hseen | |];
          cbn [lookup_kind lookup_sorts name arg_sorts out]; now rewrite Pos.eqb_refl.
  Qed.

  (** The initial full slots all use their declared widths. *)
  Lemma planner_full_slots_valid : forall ds,
    Forall (planner_slot_valid (decl_widths ds Empty))
      (planner_rows (full_slots ds Empty (SlotState Empty 0%N []))).
  Proof.
    intro ds. apply full_slots_property; [constructor |].
    intros f ss Hunseen Hkind Hsorts.
    exists (S (length ss)). split.
    - cbn [fst]. rewrite (planner_decl_width ds f ss OId Hsorts Hkind).
      cbn. now rewrite Nat.add_1_r.
    - apply planner_full_perm_ok.
  Qed.

  (** A typed function atom adds a valid permutation of its declared tuple. *)
  Lemma planner_fun_slot_valid : forall p g g1 g2 f args res ss o base lay
      lay' pairs lits copied,
    program_sorts p f = Some ss -> program_kind p f = Some o ->
    @binds_list V.t g args ss g1 -> binds_result g1 o res g2 ->
    place_terms base (args ++ option_list res) 0 Empty lay [] [] false =
      (lay', pairs, lits, copied) ->
    planner_slot_valid (decl_widths (decls V.t p) Empty) (f, map snd (sort_pairs pairs)).
  Proof.
    intros p g g1 g2 f args res ss o base lay lay' pairs lits copied
      Hsort Hkind Hargs Hres Hplaced.
    exists (length (args ++ option_list res)). split.
    - cbn [fst]. rewrite (planner_decl_width _ _ _ _ Hsort Hkind), length_app,
        (planner_binds_length _ _ _ _ Hargs), (planner_result_length _ _ _ _ Hres).
      reflexivity.
    - eapply planner_place_perm_ok. exact Hplaced.
  Qed.

  (** Planning a well-sorted query preserves validity of the accumulated slots. *)
  Lemma plan_atoms_slots_valid : forall p g q g',
    @query_ok V.t (program_sorts p) (program_kind p) g q g' ->
    forall base ai lay st outs post lay' st' outs' post',
    Forall (planner_slot_valid (decl_widths (decls V.t p) Empty)) (planner_rows st) ->
    plan_atoms base q ai lay st outs post = (lay', st', outs', post') ->
    Forall (planner_slot_valid (decl_widths (decls V.t p) Empty)) (planner_rows st').
  Proof.
    intros p g q g' Hquery.
    induction Hquery as
      [g | g g1 g2 g3 f args res ss o rest Hsort Hkind Hreads Hargs Hres Hrest IH |
       g g1 op args res rest Hargs Hres Hrest IH];
      intros base ai lay st outs post lay' st' outs' post' Hvalid Hplan.
    - cbn [plan_atoms] in Hplan. inversion Hplan; subst. exact Hvalid.
    - cbn [plan_atoms] in Hplan.
      destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
        as [[[next pairs] lits] copied] eqn:Hplaced.
      destruct (add_slot f (map snd (sort_pairs pairs)) st)
        as [slot nextst] eqn:Hslot.
      eapply IH; [| exact Hplan].
      pose proof (add_slot_property
        (planner_slot_valid (decl_widths (decls V.t p) Empty)) f
        (map snd (sort_pairs pairs)) st Hvalid) as Hkeep.
      rewrite Hslot in Hkeep. apply Hkeep.
      eapply planner_fun_slot_valid; eassumption.
    - cbn [plan_atoms] in Hplan. eapply IH; eassumption.
  Qed.

  (** Planning a well-sorted rule preserves validity of the accumulated slots. *)
  Lemma plan_rule_slots_valid : forall p i r st st' c cs,
    @rule_ok V.t (program_sorts p) (program_kind p) r ->
    Forall (planner_slot_valid (decl_widths (decls V.t p) Empty)) (planner_rows st) ->
    plan_rule i r st = (st', c, cs) ->
    Forall (planner_slot_valid (decl_widths (decls V.t p) Empty)) (planner_rows st').
  Proof.
    intros p i [q acts] st st' c cs [g [Hquery Hactions]] Hvalid Hplan.
    cbn [query] in Hquery. cbn [plan_rule] in Hplan.
    destruct (plan_atoms (query_copies q 0) q 0
        (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay nextst] outs] post] eqn:Hatoms.
    destruct lay as [names nc nm fresh cn mn]. inversion Hplan; subst.
    eapply plan_atoms_slots_valid; eassumption.
  Qed.

  (** Planning sorted rules keeps every accumulated slot within its declared width. *)
  Lemma plan_rules_slots_valid : forall p rs i st naive semi st' naive' semi',
    Forall (@rule_ok V.t (program_sorts p) (program_kind p)) rs ->
    Forall (planner_slot_valid (decl_widths (decls V.t p) Empty)) (planner_rows st) ->
    plan_rules rs i st naive semi = (st', naive', semi') ->
    Forall (planner_slot_valid (decl_widths (decls V.t p) Empty)) (planner_rows st').
  Proof.
    intros p rs. induction rs as [| r rest IH]; intros i st naive semi st' naive' semi'
      Hsorted Hvalid Hplan.
    - cbn [plan_rules] in Hplan. inversion Hplan; subst. exact Hvalid.
    - inversion Hsorted as [| r' rest' Hrule Hrules]; subst.
      cbn [plan_rules] in Hplan.
      destruct (plan_rule i r st) as [[nextst c] cs] eqn:Hstep.
      eapply IH; [exact Hrules | | exact Hplan].
      eapply plan_rule_slots_valid; eassumption.
  Qed.

  (** All slots emitted by a sorted program pass the slot-table scan. *)
  Lemma planner_program_slot_table : forall p, program_ok p ->
    exists checked,
      slot_table (decl_widths (decls V.t p) Empty) (Syntax.slots V.t (plan p))
        0%N Empty = Some checked.
  Proof.
    intros [ds rs] Hsorted. unfold plan, plan_program.
    destruct (plan_rules rs 0%N (full_slots ds Empty (SlotState Empty 0%N [])) [] [])
      as [[[table next rows] naive] semi] eqn:Hrules.
    cbn [Syntax.slots decls]. rewrite rev_append_rev, app_nil_r.
    apply slot_table_complete. apply Forall_rev.
    exact (plan_rules_slots_valid (Program V.t ds rs) rs 0%N
      (full_slots ds Empty (SlotState Empty 0%N [])) [] [] (SlotState table next rows)
      naive semi Hsorted (planner_full_slots_valid ds) Hrules).
  Qed.

  (** Every sorted function atom reads an argument or an output column. *)
  Lemma planner_query_reads : forall sorts kinds g q g',
    @query_ok V.t sorts kinds g q g' ->
    Forall (fun a => match a with
      | Fun _ _ args res => args ++ option_list res <> []
      | Prim _ _ _ _ => True
      end) q.
  Proof.
    intros sorts kinds g q g' Hquery.
    induction Hquery as
      [g | g g1 g2 g3 f args res ss o rest Hsort Hkind Hreads Hargs Hres Hrest IH |
       g g1 op args res rest Hargs Hres Hrest IH].
    - constructor.
    - constructor; [| exact IH]. intro Hempty. apply app_eq_nil in Hempty.
      destruct Hempty as [Hargsempty Hresempty].
      assert (Hsortsempty : ss = []).
      { apply length_zero_iff_nil.
        rewrite <- (planner_binds_length _ _ _ _ Hargs), Hargsempty. reflexivity. }
      destruct res as [t |]; [discriminate Hresempty |].
      destruct o; cbn [binds_result out_sort] in Hres; try contradiction.
      destruct Hreads as [Hnonempty | Hnotrel].
      + exact (Hnonempty Hsortsempty).
      + apply Hnotrel. reflexivity.
    - constructor; [exact I | exact IH].
  Qed.

  Definition planner_table (st : slot_state) : ptrie N :=
    match st with
    | SlotState table _ _ => table
    end.

  (** Adding a slot leaves every earlier slot number unchanged. *)
  Lemma add_slot_lookup : forall f perm st key s,
    trie_get key (planner_table st) = Some s ->
    trie_get key (planner_table (snd (add_slot f perm st))) = Some s.
  Proof.
    intros f perm [table next rows] key s Hget. cbn [add_slot planner_table] in *.
    destruct (trie_get (slot_code f perm) table) as [found |] eqn:Hfind.
    - exact Hget.
    - change (trie_get key (PTrieCode.set (slot_code f perm) next table) = Some s).
      rewrite PTrie.get_set_other; [exact Hget |].
      intro Heq. subst key. rewrite Hfind in Hget. discriminate Hget.
  Qed.

  (** The number returned when registering a slot is its stored number. *)
  Lemma add_slot_number : forall f perm st s st', add_slot f perm st = (s, st') ->
    trie_get (slot_code f perm) (planner_table st') = Some s.
  Proof.
    intros f perm [table next rows] s st' Hslot. cbn [add_slot] in Hslot.
    destruct (trie_get (slot_code f perm) table) as [found |] eqn:Hfind;
      inversion Hslot; subst; cbn [planner_table].
    - exact Hfind.
    - apply PTrie.get_set_same.
  Qed.

  (** Later full slots preserve the numbers of all earlier slots. *)
  Lemma full_slots_lookup : forall ds seen st key s,
    trie_get key (planner_table st) = Some s ->
    trie_get key (planner_table (full_slots ds seen st)) = Some s.
  Proof.
    induction ds as [| [f ss o] rest IH]; intros seen st key s Hget.
    - exact Hget.
    - cbn [full_slots]. destruct (trie_get f seen) as [u |].
      + now apply IH.
      + destruct o; apply IH; try exact Hget. now apply add_slot_lookup.
  Qed.

  (** Query planning preserves every slot number that was available before it. *)
  Lemma plan_atoms_lookup : forall base (q : list (atom V.t)) ai lay st outs post
      lay' st' outs' post',
    plan_atoms base q ai lay st outs post = (lay', st', outs', post') ->
    forall key s, trie_get key (planner_table st) = Some s ->
      trie_get key (planner_table st') = Some s.
  Proof.
    intros base q. induction q as [| a rest IH]; intros ai lay st outs post
      lay' st' outs' post' Hplan key s Hget.
    - cbn [plan_atoms] in Hplan. inversion Hplan; subst. exact Hget.
    - destruct a as [f args res | f args res]; cbn [plan_atoms] in Hplan.
      + destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[next pairs] lits] copied] eqn:Hplaced.
        destruct (add_slot f (map snd (sort_pairs pairs)) st)
          as [slot nextst] eqn:Hslot.
        eapply IH; [exact Hplan |].
        pose proof (add_slot_lookup f (map snd (sort_pairs pairs)) st key s Hget) as Hkeep.
        rewrite Hslot in Hkeep. exact Hkeep.
      + eapply IH; eassumption.
  Qed.

  (** Planning one later rule preserves all earlier slot numbers. *)
  Lemma plan_rule_lookup : forall i (r : rule V.t) st st' c cs,
    plan_rule i r st = (st', c, cs) ->
    forall key s, trie_get key (planner_table st) = Some s ->
      trie_get key (planner_table st') = Some s.
  Proof.
    intros i [q acts] st st' c cs Hplan key s Hget.
    cbn [plan_rule] in Hplan.
    destruct (plan_atoms (query_copies q 0) q 0
        (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay nextst] outs] post] eqn:Hatoms.
    destruct lay as [names nc nm fresh cn mn]. inversion Hplan; subst.
    eapply plan_atoms_lookup; eassumption.
  Qed.

  (** Planning all later rules preserves the slot identities of earlier plans. *)
  Lemma plan_rules_lookup : forall (rs : list (rule V.t)) i st naive semi st' naive' semi',
    plan_rules rs i st naive semi = (st', naive', semi') ->
    forall key s, trie_get key (planner_table st) = Some s ->
      trie_get key (planner_table st') = Some s.
  Proof.
    induction rs as [| r rest IH]; intros i st naive semi st' naive' semi' Hplan key s Hget.
    - cbn [plan_rules] in Hplan. inversion Hplan; subst. exact Hget.
    - cbn [plan_rules] in Hplan.
      destruct (plan_rule i r st) as [[nextst c] cs] eqn:Hrule.
      eapply IH; [exact Hplan |]. eapply plan_rule_lookup; eassumption.
  Qed.

  (** Comparing a permutation with itself succeeds. *)
  Lemma planner_nats_eqb_refl : forall ns, nats_eqb ns ns = true.
  Proof.
    induction ns as [| n ns IH]; [reflexivity |].
    cbn [nats_eqb]. rewrite Nat.eqb_refl. exact IH.
  Qed.

  (** An exact checked-table entry satisfies the slot matching test. *)
  Lemma slot_matches_complete : forall checked f perm s,
    trie_get (slot_code f perm) checked = Some (s, (f, perm)) ->
    slot_matches checked f perm s = true.
  Proof.
    intros checked f perm s Hget. unfold slot_matches.
    rewrite Hget, N.eqb_refl, Pos.eqb_refl. apply planner_nats_eqb_refl.
  Qed.

  (** Extending a checking table preserves every slot match already established. *)
  Lemma slot_matches_scan : forall widths sl next checked checked' f perm s,
    slot_table widths sl next checked = Some checked' ->
    slot_matches checked f perm s = true -> slot_matches checked' f perm s = true.
  Proof.
    intros widths sl next checked checked' f perm s Hscan Hmatch.
    unfold slot_matches in *.
    destruct (trie_get (slot_code f perm) checked) as [[number [g other]] |] eqn:Hget;
      [| discriminate Hmatch].
    rewrite (slot_table_keeps _ _ _ _ _ Hscan _ _ Hget). exact Hmatch.
  Qed.


  (** Each planned function atom contributes exactly one join source. *)
  Lemma planner_atoms_length : forall base (q : list (atom V.t)) ai lay st outs post,
    let '(_, _, outs', _) := plan_atoms base q ai lay st outs post in
    length outs' = fun_count q + length outs.
  Proof.
    intros base q. induction q as [|a rest IH]; intros ai lay st outs post.
    - reflexivity.
    - destruct a as [f args res|p args res]; cbn [plan_atoms fun_count].
      + destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[lay' pairs] lits] copied].
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        specialize (IH (S ai) lay' st'
          (AtomPlan s (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
          (if copied then ai :: post else post)).
        destruct (plan_atoms base rest (S ai) lay' st'
          (AtomPlan s (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
          (if copied then ai :: post else post)) as [[[final state] result] posts].
        cbn [length] in *. lia.
      + apply IH.
  Qed.


  (** Semi-naive generation emits one plan for each requested pivot. *)
  Lemma planner_semis_length : forall i j vars post atoms m todo,
    length (@semi_plans V.t i j vars post atoms m todo) = length todo.
  Proof.
    intros i j vars post atoms m todo. revert m.
    induction todo as [|a rest IH]; intro m; cbn [semi_plans length]; [reflexivity|].
    now rewrite IH.
  Qed.

  (** A rule supplies precisely the number of semi-naive plans checked for it. *)
  Lemma planner_rule_semis_length : forall i r st st' c cs,
    @plan_rule V.t i r st = (st', c, cs) -> length cs = fun_count (query V.t r).
  Proof.
    intros i [q acts] st st' c cs Hplan. cbn [plan_rule] in Hplan.
    pose proof (planner_atoms_length (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []) as Hlength.
    destruct (plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay nextst] outs] post].
    destruct lay as [names nc nm fresh cn mn]. inversion Hplan; subst c cs st'.
    rewrite planner_semis_length, rev_append_rev, app_nil_r, length_rev.
    cbn [length query] in *. lia.
  Qed.

  (** Rule-list planning appends its reverse-order results to the supplied accumulators. *)
  Lemma planner_rules_accumulators : forall (rs : list (rule V.t)) i st naive semi,
    plan_rules rs i st naive semi =
      let '(st', nv, sn) := plan_rules rs i st [] [] in
      (st', nv ++ naive, sn ++ semi).
  Proof.
    induction rs as [|r rest IH]; intros i st naive semi; cbn [plan_rules].
    - reflexivity.
    - destruct (plan_rule i r st) as [[nextst c] cs].
      rewrite (IH (N.succ i) nextst (c :: naive) (rev_append cs semi)).
      rewrite (IH (N.succ i) nextst [c] (rev_append cs [])).
      destruct (plan_rules rest (N.succ i) nextst [] []) as [[final nv] sn].
      rewrite !rev_append_rev, app_nil_r, <- !app_assoc. reflexivity.
  Qed.

  (** The semi-naive checker consumes exactly a verified prefix. *)
  Lemma planner_check_semis_append : forall eqb table i r cs tail,
    Forall (fun c => @check_cplan V.t eqb true table i r c = true) cs ->
    check_semis eqb table i r (length cs) (cs ++ tail) = Some tail.
  Proof.
    intros eqb table i r cs tail Hchecked. induction Hchecked as [|c rest Hc Hrest IH].
    - reflexivity.
    - cbn [length app check_semis]. now rewrite Hc.
  Qed.

  (** Per-rule checker correctness composes through the reversed plan accumulators. *)
  Lemma planner_rules_checked : forall eqb table (rs : list (rule V.t)) i st st' nv sn,
    planner_state_exact st ->
    (forall r s j s' c cs, In r rs -> planner_state_exact s ->
      plan_rule j r s = (s', c, cs) ->
      (forall f perm slot, trie_get (slot_code f perm) (planner_table s') = Some slot ->
        slot_matches table f perm slot = true) ->
      check_cplan eqb false table j r c = true /\
      Forall (fun c' => check_cplan eqb true table j r c' = true) cs) ->
    plan_rules rs i st [] [] = (st', nv, sn) ->
    (forall f perm slot, trie_get (slot_code f perm) (planner_table st') = Some slot ->
      slot_matches table f perm slot = true) ->
    check_rule_plans eqb table rs i (rev nv) (rev sn) = true.
  Proof.
    intros eqb table rs. induction rs as [|[q acts] rest IH];
      intros i st st' nv sn Hstate Hrules Hplan Hslots.
    - cbn [plan_rules] in Hplan. inversion Hplan; subst. reflexivity.
    - cbn [plan_rules] in Hplan.
      destruct (plan_rule i (Rule V.t q acts) st) as [[nextst c] cs] eqn:Hrule.
      assert (Hnext : planner_state_exact nextst) by (eapply plan_rule_exact; eassumption).
      assert (Hheadslots : forall f perm slot,
          trie_get (slot_code f perm) (planner_table nextst) = Some slot ->
          slot_matches table f perm slot = true).
      { intros f perm slot Hget. apply Hslots.
        eapply plan_rules_lookup; [exact Hplan|exact Hget]. }
      destruct (Hrules (Rule V.t q acts) st i nextst c cs (or_introl eq_refl)
        Hstate Hrule Hheadslots) as [Hnaive Hsemis].
      rewrite planner_rules_accumulators in Hplan.
      destruct (plan_rules rest (N.succ i) nextst [] []) as [[final nr] sr] eqn:Hrest.
      inversion Hplan; subst st' nv sn.
      rewrite !rev_app_distr, rev_append_rev, app_nil_r, rev_involutive.
      cbn [rev app check_rule_plans]. rewrite Hnaive.
      pose proof (planner_rule_semis_length i (Rule V.t q acts) st nextst c cs Hrule)
        as Hlength. cbn [query] in Hlength. rewrite <- Hlength.
      rewrite planner_check_semis_append by exact Hsemis.
      eapply IH; [exact Hnext| |exact Hrest|exact Hslots].
      intros r s j s' c' cs' Hin Hs Hr Ht. eapply Hrules;
        [now right|exact Hs|exact Hr|exact Ht].
  Qed.

  (** A well-laid-out atom passes checking and adds its columns to the used-key trie. *)
  Lemma planner_check_atom_from_parts : forall newok checknames n table f ts copy used count
      src s pairs srcTail colsTail copy' remainingSrc remainingCols copied,
    pairs <> [] -> NoDup (map fst pairs) -> Forall (fun p => fst p < n) pairs ->
    length pairs = length ts -> source_slot newok src = Some s ->
    slot_matches table f (map snd (sort_pairs pairs)) s = true ->
    planner_used_count used count ->
    check_terms V.eqb checknames ts 0 Empty copy Empty srcTail colsTail false =
      Some (copy', planner_inverse pairs Empty, remainingSrc, remainingCols, copied) ->
    exists used' count',
      check_atom V.eqb newok checknames n table f ts copy used count
        (src :: srcTail) (map fst (sort_pairs pairs) :: colsTail) =
        Some (copy', used', count', remainingSrc, remainingCols, copied) /\
      planner_used_count used' count' /\
      forall k, trie_get (N.succ_pos (nat_n k)) used' = Some tt <->
        trie_get (N.succ_pos (nat_n k)) used = Some tt \/ In k (map fst pairs).
  Proof.
    intros newok checknames n table f ts copy used count src s pairs srcTail colsTail
      copy' remainingSrc remainingCols copied Hnonempty Hnodup Hrange Hlength
      Hsource Hslot Hcount Hterms.
    pose proof (planner_sorted_column_ok pairs n Hnonempty Hnodup Hrange) as Hcolumn.
    destruct (planner_column_perm_sorted pairs used count Hnodup Hcount)
      as [used' [count' [Hread [Hcount' Hused]]]].
    exists used', count'. split.
    - cbn [check_atom]. rewrite Hsource, Hcolumn, length_map,
        planner_sort_pairs_length, Hlength, Nat.eqb_refl, Hterms, Hread, Hslot.
      reflexivity.
    - split; [exact Hcount'|exact Hused].
  Qed.

  (** A completed name table agrees with every real variable registered by the planner. *)
  Lemma planner_final_names : forall base names nc nm fresh cn mn,
    base = length cn -> NoDup (cn ++ mn) ->
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    exists checknames,
      var_table (rev_append cn (rev_append mn [])) 0 Empty = Some checknames /\
      forall x j, trie_get x names = Some j -> trie_get x checknames = Some (nat_n j).
  Proof.
    intros base names nc nm fresh cn mn Hbase Hnodup [Hlength Hpositions].
    assert (Hvars : NoDup (rev_append cn (rev_append mn []))).
    { rewrite !rev_append_rev, app_nil_r.
      eapply Permutation_NoDup; [|exact Hnodup].
      apply Permutation_app; apply Permutation_rev. }
    destruct (planner_var_table_empty _ Hvars) as [checknames [Htable Hlookup]].
    exists checknames. split; [exact Htable|]. intros x j Hget.
    destruct (Hpositions x j Hget) as [k [Hindex Hnth]].
    rewrite planner_nat_n_spec. apply Hlookup.
    rewrite !rev_append_rev, app_nil_r.
    rewrite nth_error_app2 by (rewrite length_rev; lia).
    replace (j - length (rev cn)) with k by (rewrite length_rev; lia).
    exact Hnth.
  Qed.

  (** Literal indices are distinct fresh main positions allocated after the starting floor. *)
  Definition planner_literals_ok (bound : positive) (base floor : nat) (lay : var_layout)
      (lits : list (nat * V.t)) : Prop :=
    match lay with
    | VarLayout _ _ nm fresh _ mn =>
        (bound < fresh)%positive /\ floor <= nm /\ nm = length mn /\
        NoDup (map fst lits) /\ forall j v, In (j, v) lits ->
          exists k x, j = base + k /\ floor <= k /\ k < nm /\ (bound < x)%positive /\
            nth_error (rev mn) k = Some x
    end.

  (** Changing non-main fields preserves every earlier literal position. *)
  Lemma planner_literals_reframe : forall bound base floor names nc nm fresh cn mn lits
      names' nc' fresh' cn',
    planner_literals_ok bound base floor (VarLayout names nc nm fresh cn mn) lits ->
    (bound < fresh')%positive ->
    planner_literals_ok bound base floor (VarLayout names' nc' nm fresh' cn' mn) lits.
  Proof.
    intros bound base floor names nc nm fresh cn mn lits names' nc' fresh' cn'
      [_ Hrest] Hfresh. split; assumption.
  Qed.

  (** Adding a main position preserves every earlier literal position. *)
  Lemma planner_literals_main : forall bound base floor names nc nm fresh cn mn lits
      names' nc' fresh' cn' x,
    planner_literals_ok bound base floor (VarLayout names nc nm fresh cn mn) lits ->
    (bound < fresh')%positive ->
    planner_literals_ok bound base floor
      (VarLayout names' nc' (S nm) fresh' cn' (x :: mn)) lits.
  Proof.
    intros bound base floor names nc nm fresh cn mn lits names' nc' fresh' cn' x
      [Hfresh [Hfloor [Hlength [Hnodup Hpositions]]]] Hfresh'.
    cbn [planner_literals_ok]. split; [exact Hfresh'|]. split; [lia|].
    split; [cbn; congruence|]. split; [exact Hnodup|].
    intros j v Hin. destruct (Hpositions j v Hin) as [k [y [Hj [Hlower [Hupper [Hy Hnth]]]]]].
    exists k, y. split; [exact Hj|]. split; [exact Hlower|]. split; [lia|].
    split; [exact Hy|]. cbn [rev]. rewrite nth_error_app1; [exact Hnth|].
    rewrite length_rev. lia.
  Qed.

  (** Allocating a literal adds its fresh name at its new main index. *)
  Lemma planner_literals_add : forall bound base floor names nc nm fresh cn mn lits v,
    planner_literals_ok bound base floor (VarLayout names nc nm fresh cn mn) lits ->
    planner_literals_ok bound base floor
      (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)) ((base + nm, v) :: lits).
  Proof.
    intros bound base floor names nc nm fresh cn mn lits v Hlits.
    destruct Hlits as [Hfresh [Hfloor [Hlength [Hnodup Hpositions]]]].
    cbn [planner_literals_ok]. split; [lia|]. split; [lia|]. split; [cbn; congruence|].
    split.
    - constructor; [|exact Hnodup]. intro Hin. apply in_map_iff in Hin as [[j w] [Heq Hin]].
      cbn in Heq. destruct (Hpositions j w Hin) as [k [x [Hj [_ [Hupper _]]]]]. lia.
    - intros j w [Heq|Hin].
      + injection Heq as <- <-. exists nm, fresh.
        split; [reflexivity|]. split; [exact Hfloor|]. split; [lia|].
        split; [exact Hfresh|]. cbn [rev]. rewrite nth_error_app2.
        * rewrite length_rev, <- Hlength, Nat.sub_diag. reflexivity.
        * rewrite length_rev. lia.
      + destruct (Hpositions j w Hin) as [k [x [Hj [Hlower [Hupper [Hx Hnth]]]]]].
        exists k, x. split; [exact Hj|]. split; [exact Hlower|]. split; [lia|].
        split; [exact Hx|]. cbn [rev]. rewrite nth_error_app1; [exact Hnth|].
        rewrite length_rev. lia.
  Qed.

  (** Term placement preserves the exact fresh positions of its literal sources. *)
  Lemma planner_place_literals : forall (ts : list (term V.t)) bound base floor pos seen
      lay pairs lits copied,
    planner_literals_ok bound base floor lay lits ->
    match place_terms base ts pos seen lay pairs lits copied with
    | (lay', _, lits', _) => planner_literals_ok bound base floor lay' lits'
    end.
  Proof.
    induction ts as [|t rest IH]; intros bound base floor pos seen lay pairs lits copied Hlits;
      cbn [place_terms].
    - exact Hlits.
    - destruct lay as [names nc nm fresh cn mn].
      assert (Hfresh : (bound < fresh)%positive) by exact (proj1 Hlits).
      destruct t as [x|v]; cbn [place_terms].
      + destruct (trie_get x seen).
        * apply IH. eapply planner_literals_reframe; [exact Hlits|lia].
        * destruct (trie_get x names).
          -- apply IH. exact Hlits.
          -- apply IH. eapply planner_literals_main; [exact Hlits|exact Hfresh].
      + apply IH. apply planner_literals_add. exact Hlits.
  Qed.

  (** Before an atom is placed, its empty literal list uses no main positions. *)
  Lemma planner_literals_initial : forall bound base names nc nm fresh cn mn,
    nm = length mn -> (bound < fresh)%positive ->
    planner_literals_ok bound base nm (VarLayout names nc nm fresh cn mn) [].
  Proof.
    intros bound base names nc nm fresh cn mn Hlength Hfresh.
    cbn [planner_literals_ok]. split; [exact Hfresh|]. split; [lia|].
    split; [exact Hlength|]. split; [constructor|]. intros j v Hin. contradiction.
  Qed.

  (** Reordering literal sources preserves their distinct fresh positions. *)
  Lemma planner_literals_permutation : forall bound base floor lay lits lits',
    Permutation lits lits' -> planner_literals_ok bound base floor lay lits ->
    planner_literals_ok bound base floor lay lits'.
  Proof.
    intros bound base floor [names nc nm fresh cn mn] lits lits' Hperm
      [Hfresh [Hfloor [Hlength [Hnodup Hpositions]]]].
    cbn [planner_literals_ok]. split; [exact Hfresh|]. split; [exact Hfloor|].
    split; [exact Hlength|]. split.
    - eapply Permutation_NoDup; [apply Permutation_map; exact Hperm|exact Hnodup].
    - intros j v Hin. apply (Hpositions j v).
      eapply Permutation_in; [apply Permutation_sym; exact Hperm|].
      exact Hin.
  Qed.

  (** The literal positions of the planned atoms retain their associated values. *)
  Definition planner_atom_literals (atoms : list (atom_plan V.t)) : list (nat * V.t) :=
    flat_map (fun atom => match atom with AtomPlan _ _ lits => lits end) atoms.

  (** Forgetting literal values yields the guard's literal-index enumeration. *)
  Lemma planner_atom_literal_indices : forall atoms,
    map fst (planner_atom_literals atoms) = planner_literal_indices atoms.
  Proof.
    induction atoms as [|[s col lits] rest IH];
      cbn [planner_atom_literals planner_literal_indices flat_map].
    - reflexivity.
    - unfold planner_atom_literals, planner_literal_indices in IH. rewrite map_app, IH. reflexivity.
  Qed.

  (** Planning all atoms maintains distinct fresh positions for all literal sources. *)
  Lemma planner_atoms_literals : forall (q : list (atom V.t)) bound base ai lay st outs post,
    planner_literals_ok bound base 0 lay (planner_atom_literals outs) ->
    match plan_atoms base q ai lay st outs post with
    | (lay', _, outs', _) => planner_literals_ok bound base 0 lay' (planner_atom_literals outs')
    end.
  Proof.
    induction q as [|a rest IH]; intros bound base ai lay st outs post Hlits;
      cbn [plan_atoms].
    - exact Hlits.
    - destruct a as [f args res|p args res]; cbn [plan_atoms].
      + pose proof (planner_place_literals (args ++ option_list res) bound base 0 0 Empty
          lay [] (planner_atom_literals outs) false Hlits) as Hplaced.
        rewrite planner_place_acc in Hplaced.
        destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[lay' pairs] lits] copied].
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        apply IH. cbn [planner_atom_literals flat_map].
        eapply planner_literals_permutation; [|exact Hplaced].
        rewrite rev_append_rev, app_nil_r.
        apply Permutation_app; [apply Permutation_rev|reflexivity].
      + apply IH. exact Hlits.
  Qed.

  (** Reversing the atom list only reorders its literal sources. *)
  Lemma planner_atom_literals_rev : forall atoms,
    Permutation (planner_atom_literals atoms) (planner_atom_literals (rev atoms)).
  Proof.
    intro atoms. unfold planner_atom_literals. apply Permutation_flat_map.
    apply Permutation_rev.
  Qed.

  (** Building the fresh-index table preserves its previous entries. *)
  Lemma planner_layout_fresh_preserves : forall vars bound copies j allowed result,
    layout_fresh bound copies vars j allowed = Some result ->
    forall key, trie_get key allowed = Some tt -> trie_get key result = Some tt.
  Proof.
    induction vars as [|x rest IH]; intros bound copies j allowed result Htable key Hget.
    - destruct copies; cbn [layout_fresh] in Htable;
        [injection Htable as <-; exact Hget|discriminate].
    - destruct copies as [|copies]; cbn [layout_fresh] in Htable.
      + destruct (Pos.ltb bound x).
        * eapply IH; [exact Htable|].
          destruct (Pos.eq_dec key (N.succ_pos j)) as [Heq|Hneq].
          -- subst key. apply PTrie.get_set_same.
          -- rewrite PTrie.get_set_other by exact Hneq. exact Hget.
        * eapply IH; eauto.
      + destruct (Pos.ltb bound x); [eapply IH; eauto|discriminate].
  Qed.

  (** A fresh noncopy name gives an available literal index. *)
  Lemma planner_layout_fresh_member : forall vars bound copies j allowed result n x,
    layout_fresh bound copies vars j allowed = Some result ->
    nth_error vars n = Some x -> copies <= n -> (bound < x)%positive ->
    trie_get (N.succ_pos (j + N.of_nat n)%N) result = Some tt.
  Proof.
    induction vars as [|y rest IH]; intros bound copies j allowed result n x
      Htable Hnth Hcopy Hfresh; [destruct n; discriminate|].
    destruct copies as [|copies]; cbn [layout_fresh] in Htable.
    - destruct n as [|n].
      + cbn [nth_error] in Hnth. injection Hnth as <-.
        assert (Htest : Pos.ltb bound y = true) by (apply Pos.ltb_lt; exact Hfresh).
        rewrite Htest in Htable. rewrite N.add_0_r.
        eapply planner_layout_fresh_preserves; [exact Htable|apply PTrie.get_set_same].
      + cbn [nth_error] in Hnth.
        replace (j + N.of_nat (S n))%N with (N.succ j + N.of_nat n)%N
          by (rewrite Nat2N.inj_succ; lia).
        eapply IH; [exact Htable|exact Hnth|lia|exact Hfresh].
    - destruct n as [|n]; [lia|]. cbn [nth_error] in Hnth.
      destruct (Pos.ltb bound y); [|discriminate].
      replace (j + N.of_nat (S n))%N with (N.succ j + N.of_nat n)%N
        by (rewrite Nat2N.inj_succ; lia).
      eapply IH; [exact Htable|exact Hnth|lia|exact Hfresh].
  Qed.

  (** Every generated query layout keeps copies, literals and real variables separate. *)
  Lemma planner_generated_layout : forall (q : list (atom V.t)) st names nc nm fresh cn mn
      st' outs post,
    plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [] =
      (VarLayout names nc nm fresh cn mn, st', outs, post) ->
    forall pivot, layout_ok q (rev_append cn (rev_append mn []))
      (plan_srcs (rev_append outs []) pivot) (plan_cols (rev_append outs [])) = true.
  Proof.
    intros q st names nc nm fresh cn mn st' outs post Hplan pivot.
    pose proof (planner_atoms_copies q (query_copies q 0) 0 Empty 0 0
      (Pos.succ (query_max q 1%positive)) [] [] st [] []) as Hcopies.
    pose proof (planner_atoms_lengths q (query_copies q 0) 0 Empty 0 0
      (Pos.succ (query_max q 1%positive)) [] [] st [] [] eq_refl eq_refl) as Hlengths.
    pose proof (planner_atoms_names q (query_max q 1%positive) (query_copies q 0) 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []
      (planner_names_initial (query_max q 1%positive))) as Hnames.
    specialize (Hnames (fun x Hin => planner_query_max_member q 1%positive x Hin)).
    assert (Hinitial : planner_literals_ok (query_max q 1%positive) (query_copies q 0) 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) []).
    { apply planner_literals_initial; [reflexivity|lia]. }
    pose proof (planner_atoms_literals q (query_max q 1%positive) (query_copies q 0) 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [] Hinitial)
      as Hlits.
    rewrite Hplan in Hcopies, Hlengths, Hnames, Hlits.
    cbn in Hcopies, Hlengths.
    destruct Hlengths as [Hcn Hmn].
    destruct Hnames as [Hfresh [Hnodup [Hbelow [Hcopy _]]]].
    pose proof (planner_literals_permutation (query_max q 1%positive) (query_copies q 0) 0
      (VarLayout names nc nm fresh cn mn) (planner_atom_literals outs)
      (planner_atom_literals (rev outs)) (planner_atom_literals_rev outs) Hlits) as Hrevlits.
    destruct Hrevlits as [_ [_ [_ [Hliteral_nodup Hliteral_position]]]].
    rewrite !rev_append_rev, !app_nil_r. unfold layout_ok.
    destruct (planner_layout_fresh_complete (rev cn ++ rev mn) (query_max q 1%positive)
      (query_copies q 0) 0 Empty) as [allowed Hallowed].
    - rewrite length_app, !length_rev. lia.
    - replace (query_copies q 0) with (length (rev cn)) by (rewrite length_rev; lia).
      rewrite firstn_app, firstn_all, Nat.sub_diag. cbn [firstn]. rewrite app_nil_r.
      apply Forall_rev. exact Hcopy.
    - rewrite Hallowed. apply layout_literals_plans.
      + rewrite <- planner_atom_literal_indices. exact Hliteral_nodup.
      + intros j Hin. rewrite <- planner_atom_literal_indices in Hin.
        apply in_map_iff in Hin as [[j' v] [Heq Hin]]. cbn in Heq. subst j'.
        destruct (Hliteral_position j v Hin) as [k [x [Hj [_ [Hk [Hx Hnth]]]]]].
        assert (Hvar : nth_error (rev cn ++ rev mn) j = Some x).
        { rewrite nth_error_app2; [|rewrite length_rev; lia].
          replace (j - length (rev cn)) with k by (rewrite length_rev; lia). exact Hnth. }
        rewrite planner_nat_n_spec.
        exact (planner_layout_fresh_member (rev cn ++ rev mn) (query_max q 1%positive)
          (query_copies q 0) 0 Empty allowed j x Hallowed Hvar ltac:(lia) Hx).
  Qed.
  (** An initial atom accumulator only appends to the reversed generated atoms. *)
  Lemma planner_atoms_out_acc : forall (q : list (atom V.t)) base ai lay st outs post,
    plan_atoms base q ai lay st outs post =
    let '(lay', st', newouts, post') := plan_atoms base q ai lay st [] post in
    (lay', st', newouts ++ outs, post').
  Proof.
    induction q as [|a rest IH]; intros base ai lay st outs post.
    - reflexivity.
    - destruct a as [f args res|p args res]; cbn [plan_atoms].
      + destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
          as [[[lay' pairs] lits] copied].
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        rewrite (IH base (S ai) lay' st'
          (AtomPlan s (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
          (if copied then ai :: post else post)).
        rewrite (IH base (S ai) lay' st'
          [AtomPlan s (map fst (sort_pairs pairs)) (rev_append lits [])]
          (if copied then ai :: post else post)).
        destruct (plan_atoms base rest (S ai) lay' st' []
          (if copied then ai :: post else post)) as [[[lastlay lastst] atoms] lastpost].
        cbn. rewrite <- app_assoc. reflexivity.
      + apply IH.
  Qed.

  (** Later atoms never decrease the number of allocated main indices. *)
  Lemma planner_atoms_mains : forall (q : list (atom V.t)) base ai
      names nc nm fresh cn mn st outs post,
    match plan_atoms base q ai (VarLayout names nc nm fresh cn mn) st outs post with
    | (VarLayout _ _ nm' _ _ _, _, _, _) => nm <= nm'
    end.
  Proof.
    induction q as [|a rest IH]; intros base ai names nc nm fresh cn mn st outs post;
      cbn [plan_atoms].
    - lia.
    - destruct a as [f args res|p args res]; cbn [plan_atoms].
      + pose proof (planner_place_mains (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn [] [] false) as Hplaced.
        destruct (place_terms base (args ++ option_list res) 0 Empty
          (VarLayout names nc nm fresh cn mn) [] [] false)
          as [[[lay pairs] lits] copied].
        destruct lay as [names' nc' nm' fresh' cn' mn']; cbn in Hplaced.
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'].
        pose proof (IH base (S ai) names' nc' nm' fresh' cn' mn' st'
          (AtomPlan s (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
          (if copied then ai :: post else post)) as Hrest.
        destruct (plan_atoms base rest (S ai) (VarLayout names' nc' nm' fresh' cn' mn') st'
          (AtomPlan s (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
          (if copied then ai :: post else post)) as [[[lastlay lastst] atoms] lastpost].
        destruct lastlay. cbn in Hrest. lia.
      + apply IH.
  Qed.

  (** A naive plan has no pivot, and a semi-naive plan permits its chosen new source. *)
  Lemma planner_pivot_source : forall newok s pivot,
    (newok = false -> pivot = None) -> source_slot newok (@pivot_source V.t s pivot) = Some s.
  Proof.
    intros newok s [pivot|] Hpivot; [destruct pivot|];
      destruct newok; cbn [pivot_source source_slot]; try reflexivity.
    specialize (Hpivot eq_refl). discriminate.
  Qed.

  (** Moving past an atom preserves the absence of a pivot in a naive plan. *)
  Lemma planner_pivot_tail : forall newok pivot,
    (newok = false -> pivot = None) -> (newok = false -> pivot_next pivot = None).
  Proof.
    intros newok pivot Hpivot Hfalse. rewrite (Hpivot Hfalse). reflexivity.
  Qed.

  (** An empty name table has no registered main positions. *)
  Lemma planner_main_initial : forall base fresh,
    planner_main_positions base (VarLayout Empty 0 0 fresh [] []).
  Proof.
    intros base fresh. split; [reflexivity|]. intros x j Hget.
    rewrite PTrie.get_empty in Hget. discriminate.
  Qed.

  (** A generated query passes checking against its final names and slot identities. *)
  Lemma planner_query_checked : forall (q : list (atom V.t)) base ai names nc nm fresh cn mn
      st post newok pivot checknames n table used count,
    Forall (fun a => match a with
      | Fun _ _ args res => args ++ option_list res <> []
      | Prim _ _ _ _ => True
      end) q ->
    planner_main_positions base (VarLayout names nc nm fresh cn mn) ->
    query_copies q nc <= base -> planner_used_count used count ->
    (forall j, trie_get (N.succ_pos (nat_n j)) used = Some tt <->
      planner_used base (VarLayout names nc nm fresh cn mn) j) ->
    (newok = false -> pivot = None) ->
    match plan_atoms base q ai (VarLayout names nc nm fresh cn mn) st [] post with
    | (VarLayout names' nc' nm' _ _ _, st', atoms, post') =>
        base + nm' <= n ->
        (forall x j, trie_get x names' = Some j ->
          trie_get x checknames = Some (nat_n j)) ->
        (forall f perm s, trie_get (slot_code f perm) (planner_table st') = Some s ->
          slot_matches table f perm s = true) ->
        check_query V.eqb newok checknames n table q ai (nat_n nc) used count
          (plan_srcs (rev_append atoms []) pivot) (plan_cols (rev_append atoms [])) post =
        Some (nat_n (nc' + nm'), [], [], post')
    end.
  Proof.
    induction q as [|a rest IH]; intros base ai names nc nm fresh cn mn st post
      newok pivot checknames n table used count Hreads Hmain Hbudget Hcount Hused Hpivot.
    - cbn [plan_atoms query_copies] in *. intros Hn Hnames Hslots.
      assert (Htotal : count = N.of_nat (nc + nm)).
      { apply (planner_used_range_count used count base nc nm Hcount Hbudget). exact Hused. }
      cbn [rev_append plan_srcs plan_cols check_query]. rewrite Htotal, planner_nat_n_spec.
      reflexivity.
    - inversion Hreads as [|a' rest' Hhead Htail]; subst a' rest'.
      destruct a as [f args res|p args res]; cbn [plan_atoms query_copies] in *.
      + pose proof (planner_place_copies (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn [] [] false) as Hcopies.
        pose proof (planner_place_positions (args ++ option_list res) base 0 Empty
          (VarLayout names nc nm fresh cn mn) [] [] false Hmain) as Hpositions.
        pose proof (planner_place_coverage (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn false Hmain) as Hcoverage.
        assert (Hcopy_budget : term_copies Empty (args ++ option_list res) nc <= base).
        { pose proof (planner_query_copies_acc rest
            (term_copies Empty (args ++ option_list res) nc)).
          lia. }
        pose proof (planner_place_pairs (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn [] [] false Hmain (planner_pairs_empty base Empty _)
          Hcopy_budget) as Hpairs.
        destruct (place_terms base (args ++ option_list res) 0 Empty
          (VarLayout names nc nm fresh cn mn) [] [] false)
          as [[[lay pairs] lits] copied] eqn:Hplaced.
        destruct lay as [nextnames nextnc nextnm nextfresh nextcn nextmn].
        destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s nextst] eqn:Hslot.
        rewrite planner_atoms_out_acc.
        destruct (plan_atoms base rest (S ai)
          (VarLayout nextnames nextnc nextnm nextfresh nextcn nextmn) nextst []
          (if copied then ai :: post else post))
          as [[[lastlay lastst] atoms] lastpost] eqn:Hrest.
        destruct lastlay as [lastnames lastnc lastnm lastfresh lastcn lastmn].
        intros Hn Hnames Hslots.
        assert (Hnext_names : forall x j, trie_get x nextnames = Some j ->
            trie_get x checknames = Some (nat_n j)).
        { intros x j Hget.
          pose proof (planner_atoms_registered rest base (S ai) nextnames nextnc nextnm
            nextfresh nextcn nextmn nextst [] (if copied then ai :: post else post)
            x j Hget) as Hregistered.
          rewrite Hrest in Hregistered. apply Hnames. exact Hregistered. }
        assert (Hnext_mains : nextnm <= lastnm).
        { pose proof (planner_atoms_mains rest base (S ai) nextnames nextnc nextnm nextfresh
            nextcn nextmn nextst [] (if copied then ai :: post else post)) as Hmains.
          rewrite Hrest in Hmains. exact Hmains. }
        assert (Hpair_length : length pairs = length (args ++ option_list res)).
        { pose proof (planner_place_positions_list base (args ++ option_list res) 0 Empty
            (VarLayout names nc nm fresh cn mn) [] [] false) as Hlist.
          rewrite Hplaced in Hlist. cbn in Hlist.
          apply (f_equal (@length nat)) in Hlist.
          rewrite length_map, length_app, length_rev, length_seq in Hlist. cbn in Hlist. lia. }
        destruct Hpairs as [Hpair_nodup Hpair_bound].
        assert (Hpair_nonempty : pairs <> []).
        { intro Heq. subst pairs. cbn in Hpair_length. apply Hhead.
          apply length_zero_iff_nil. lia. }
        assert (Hpair_n : Forall (fun pair => fst pair < n) pairs).
        { apply Forall_forall. intros pair Hin.
          apply Forall_forall with (x := pair) in Hpair_bound; [lia|exact Hin]. }
        assert (Hmatch : slot_matches table f (map snd (sort_pairs pairs)) s = true).
        { apply Hslots. eapply plan_atoms_lookup; [exact Hrest|].
          eapply add_slot_number. exact Hslot. }
        pose proof (planner_place_check (args ++ option_list res) base 0 Empty
          names nc nm fresh cn mn false checknames Empty
          (plan_srcs (rev_append atoms []) (pivot_next pivot))
          (plan_cols (rev_append atoms []))) as Hterms.
        rewrite Hplaced in Hterms. specialize (Hterms Hnext_names).
        destruct (planner_check_atom_from_parts newok checknames n table f
          (args ++ option_list res) (nat_n nc) used count (pivot_source s pivot) s pairs
          (literal_sources (rev lits) (plan_srcs (rev_append atoms []) (pivot_next pivot)))
          (literal_cols (rev lits) (plan_cols (rev_append atoms []))) (nat_n nextnc)
          (plan_srcs (rev_append atoms []) (pivot_next pivot))
          (plan_cols (rev_append atoms [])) copied Hpair_nonempty Hpair_nodup Hpair_n
          Hpair_length (planner_pivot_source newok s pivot Hpivot) Hmatch Hcount Hterms)
          as [used' [count' [Hatom [Hcount' Hused']]]].
        assert (Hnext_used : forall j, trie_get (N.succ_pos (nat_n j)) used' = Some tt <->
            planner_used base (VarLayout nextnames nextnc nextnm nextfresh nextcn nextmn) j).
        { intro j. rewrite Hused', Hused, Hcoverage. reflexivity. }
        pose proof (IH base (S ai) nextnames nextnc nextnm nextfresh nextcn nextmn nextst
          (if copied then ai :: post else post) newok (pivot_next pivot) checknames n table
          used' count' Htail Hpositions ltac:(rewrite Hcopies; exact Hbudget) Hcount'
          Hnext_used (planner_pivot_tail newok pivot Hpivot)) as Hchecked.
        rewrite Hrest in Hchecked. specialize (Hchecked Hn Hnames Hslots).
        rewrite !rev_append_rev, !app_nil_r, rev_app_distr.
        cbn [rev app plan_srcs plan_cols]. cbn [check_query].
        rewrite !rev_append_rev, !app_nil_r in Hatom, Hchecked.
        rewrite Hatom. exact Hchecked.
      + exact (IH base (S ai) names nc nm fresh cn mn st (ai :: post) newok pivot checknames
          n table used count Htail Hmain Hbudget Hcount Hused Hpivot).
  Qed.

  (** A finished rule layout has the counted copies and distinct position-correct names. *)
  Lemma planner_rule_layout : forall (q : list (atom V.t)) st names nc nm fresh cn mn
      st' atoms post,
    plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [] =
      (VarLayout names nc nm fresh cn mn, st', atoms, post) ->
    nc = query_copies q 0 /\ nm = length mn /\ query_copies q 0 = length cn /\
    NoDup (cn ++ mn) /\
    planner_main_positions (query_copies q 0) (VarLayout names nc nm fresh cn mn).
  Proof.
    intros q st names nc nm fresh cn mn st' atoms post Hplan.
    pose proof (planner_atoms_copies q (query_copies q 0) 0 Empty 0 0
      (Pos.succ (query_max q 1%positive)) [] [] st [] []) as Hcopies.
    pose proof (planner_atoms_lengths q (query_copies q 0) 0 Empty 0 0
      (Pos.succ (query_max q 1%positive)) [] [] st [] [] eq_refl eq_refl) as Hlengths.
    pose proof (planner_atoms_names q (query_max q 1%positive) (query_copies q 0) 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []
      (planner_names_initial (query_max q 1%positive))
      (fun x Hin => planner_query_max_member q 1%positive x Hin)) as Hnames.
    pose proof (planner_atoms_positions q (query_copies q 0) 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []
      (planner_main_initial (query_copies q 0) (Pos.succ (query_max q 1%positive))))
      as Hpositions.
    rewrite Hplan in Hcopies, Hlengths, Hnames, Hpositions.
    cbn in Hcopies, Hlengths.
    destruct Hlengths as [Hcn Hmn]. destruct Hnames as [_ [Hnodup _]].
    split; [exact Hcopies |]. split; [exact Hmn |]. split; [lia |].
    split; assumption.
  Qed.

  (** With no allocated indices, the empty used-key trie represents the layout exactly. *)
  Lemma planner_initial_used : forall base fresh j,
    trie_get (N.succ_pos (nat_n j)) (@Empty unit) = Some tt <->
    planner_used base (VarLayout Empty 0 0 fresh [] []) j.
  Proof.
    intros base fresh j. rewrite PTrie.get_empty. cbn [planner_used].
    split; [discriminate | lia].
  Qed.

  (** The checker accepts every allowed pivot of a generated rule layout. *)
  Lemma planner_cplan_checked : forall (q : list (atom V.t)) acts st names nc nm fresh cn mn
      st' atoms post table i newok pivot,
    Forall (fun a => match a with
      | Fun _ _ args res => args ++ option_list res <> []
      | Prim _ _ _ _ => True
      end) q ->
    plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [] =
      (VarLayout names nc nm fresh cn mn, st', atoms, post) ->
    (forall f perm slot, trie_get (slot_code f perm) (planner_table st') = Some slot ->
      slot_matches table f perm slot = true) ->
    (newok = false -> pivot = None) ->
    check_cplan V.eqb newok table i (Rule V.t q acts)
      (CPlan V.t i (JPlan (query_copies q 0 + nm) (plan_cols (rev_append atoms [])))
        (plan_srcs (rev_append atoms []) pivot) (rev_append cn (rev_append mn []))
        (rev_append post [])) = true.
  Proof.
    intros q acts st names nc nm fresh cn mn st' atoms post table i newok pivot
      Hreads Hplan Hslots Hpivot.
    destruct (planner_rule_layout q st names nc nm fresh cn mn st' atoms post Hplan)
      as [Hcopies [Hmn [Hbase [Hdistinct Hpositions]]]].
    destruct (planner_final_names (query_copies q 0) names nc nm fresh cn mn
      Hbase Hdistinct Hpositions) as [checknames [Htable Hnames]].
    assert (Hlength : length (rev_append cn (rev_append mn [])) = query_copies q 0 + nm).
    { rewrite !rev_append_rev, app_nil_r, length_app, !length_rev. lia. }
    pose proof (planner_query_checked q (query_copies q 0) 0 Empty 0 0
      (Pos.succ (query_max q 1%positive)) [] [] st [] newok pivot checknames
      (query_copies q 0 + nm) table Empty 0%N Hreads
      (planner_main_initial (query_copies q 0) (Pos.succ (query_max q 1%positive)))
      (Nat.le_refl _) planner_used_count_empty
      (planner_initial_used (query_copies q 0) (Pos.succ (query_max q 1%positive))) Hpivot)
      as Hquery.
    rewrite Hplan in Hquery. specialize (Hquery (Nat.le_refl _) Hnames Hslots).
    rewrite Hcopies in Hquery.
    cbn [check_cplan]. rewrite N.eqb_refl, Hlength, Nat.eqb_refl, Htable.
    rewrite (planner_generated_layout q st names nc nm fresh cn mn st' atoms post Hplan pivot).
    cbn [nat_n] in Hquery.
    rewrite Hquery, N.eqb_refl. apply planner_nats_eqb_refl.
  Qed.

  (** A checker-valid pivot family gives all of a rule's semi-naive plans. *)
  Lemma planner_semis_checked : forall table i (r : rule V.t) j vars post atoms todo m,
    (forall pivot, check_cplan V.eqb true table i r
      (CPlan V.t i j (plan_srcs atoms (Some pivot)) vars post) = true) ->
    Forall (fun c => check_cplan V.eqb true table i r c = true)
      (semi_plans i j vars post atoms m todo).
  Proof.
    intros table i r j vars post atoms todo. induction todo as [| a rest IH]; intros m Hchecked.
    - constructor.
    - cbn [semi_plans]. constructor; [apply Hchecked | now apply IH].
  Qed.

  (** A sorted rule produces checked naive and semi-naive plans in any containing slot table. *)
  Lemma planner_rule_checked : forall (p : program V.t) table i r st st' c cs,
    @rule_ok V.t (program_sorts p) (program_kind p) r -> planner_state_exact st ->
    plan_rule i r st = (st', c, cs) ->
    (forall f perm slot, trie_get (slot_code f perm) (planner_table st') = Some slot ->
      slot_matches table f perm slot = true) ->
    check_cplan V.eqb false table i r c = true /\
      Forall (fun c' => check_cplan V.eqb true table i r c' = true) cs.
  Proof.
    intros p table i [q acts] st st' c cs [g [Hquery Hactions]] Hstate Hrule Hslots.
    cbn [query] in Hquery.
    pose proof (planner_query_reads _ _ _ _ _ Hquery) as Hreads.
    cbn [plan_rule] in Hrule.
    destruct (plan_atoms (query_copies q 0) q 0
        (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay nextst] atoms] post] eqn:Hatoms.
    destruct lay as [names nc nm fresh cn mn]. inversion Hrule; subst st' c cs.
    split.
    - eapply planner_cplan_checked; [exact Hreads | exact Hatoms | exact Hslots |].
      intros. reflexivity.
    - apply planner_semis_checked. intro pivot.
      eapply planner_cplan_checked; [exact Hreads | exact Hatoms | exact Hslots |].
      discriminate.
  Qed.

  Lemma plan_passes_shape : forall p, program_ok p -> check_shape p (plan p) = true.
  Proof.
    intros [ds rs] Hprogram.
    unfold check_shape, check_shape_with, plan, plan_program.
    destruct (plan_rules rs 0%N (full_slots ds Empty (SlotState Empty 0%N [])) [] [])
      as [[[stored next rows] nv] sn] eqn:Hrules.
    assert (Hinitial : planner_state_exact (full_slots ds Empty (SlotState Empty 0%N []))).
    { apply full_slots_exact. exact planner_state_empty. }
    assert (Hfinal : planner_state_exact (SlotState stored next rows)).
    { eapply plan_rules_exact; [exact Hinitial|exact Hrules]. }
    assert (Hvalid : Forall (planner_slot_valid (decl_widths ds Empty)) rows).
    { exact (plan_rules_slots_valid (Program V.t ds rs) rs 0%N
        (full_slots ds Empty (SlotState Empty 0%N [])) [] [] (SlotState stored next rows)
        nv sn Hprogram (planner_full_slots_valid ds) Hrules). }
    assert (Hvalidrev : Forall (planner_slot_valid (decl_widths ds Empty)) (rev rows)).
    { apply Forall_rev. exact Hvalid. }
    destruct (planner_slot_table (decl_widths ds Empty) stored next rows Hfinal
      Hvalidrev) as [checked [Hscan Hnumbers]].
    rewrite !rev_append_rev, !app_nil_r, Hscan, check_rule_plans_at_agrees.
    eapply planner_rules_checked; [exact Hinitial| |exact Hrules|].
    - intros r s j s' c cs Hin Hstate Hrule Hslots.
      eapply (planner_rule_checked (Program V.t ds rs));
        [|exact Hstate|exact Hrule|exact Hslots].
      exact ((proj1 (Forall_forall _ _)) Hprogram r Hin).
    - intros f perm slot Hget. apply slot_matches_complete. apply Hnumbers. exact Hget.
  Qed.

  Lemma plan_checked : forall p, program_ok p -> plans_ok p (plan p).
  Proof.
    intros p Hprogram. unfold plans_ok, check_plan.
    rewrite (proj2 (check_program_spec V.t p) Hprogram), (plan_passes_shape p Hprogram).
    reflexivity.
  Qed.

  Lemma load_spec : forall p cp,
    load p cp = D.init (decls V.t p) (Syntax.slots V.t cp).
  Proof.
    reflexivity.
  Qed.

  (** Binary-fuel iteration preserves continuing invariants and stopping postconditions. *)
  Lemma run_loopN_invariant : forall S R (step : S -> S + R) (P : S -> Prop)
      (Q : R -> Prop) fuel start,
    (forall s next, P s -> step s = inl next -> P next) ->
    (forall s result, P s -> step s = inr result -> Q result) -> P start ->
    match loopN step fuel start with inl s => P s | inr r => Q r end.
  Proof.
    intros S R step P Q fuel start Hgo Hstop Hinitial.
    assert (Hacc : forall fs (H : Acc loopN_lt fs), P (snd fs) ->
      match loop loopN_lt (loopN_step step) fs H with
      | inl s => P s | inr r => Q r end).
    { intros fs H. induction H as [[n s] Hsmaller IH] using Acc_ind_dep.
      cbn [snd]. intro Hstate. destruct n as [|p].
      - cbn [loop loopN_step]. exact Hstate.
      - cbn [loop loopN_step Acc_inv]. destruct (step s) as [next|result] eqn:Hstep.
        + apply IH. cbn [snd]. eapply Hgo; eassumption.
        + eapply Hstop; eassumption. }
    unfold loopN. apply Hacc. exact Hinitial.
  Qed.

  Definition trace (p : program V.t) (cp : compiled V.t) (lim : limits) (db : D.t)
      : list (bool * D.t) :=
    driver_trace (driver p cp lim) (N.to_nat (max_iter lim)) (false, db).
  Definition job_rule (p : program V.t) (c : cplan V.t) : rule V.t :=
    nth (N.to_nat (rule_ix V.t c)) (rules V.t p) (Rule V.t [] []).
  Definition query_vars (r : rule V.t) : list positive := flat_map atom_vars (query V.t r).
  Fixpoint apply_jobs (p : program V.t) (js : list (cplan V.t * list (cell V.t)))
      (db : D.t) : D.t :=
    match js with
    | [] => db
    | (c, b) :: rest =>
        apply_jobs p rest
          (apply (actions V.t (job_rule p c)) (fun x => trie_get x (bind_trie c b)) db)
    end.
  Definition env_allocated (db : D.t) (s : Model.env (V := V.t)) : Prop :=
    forall x i, s x = Some (Id i) -> D.allocated db i.
  Definition agrees (s t : Model.env (V := V.t)) (xs : list positive) : Prop :=
    forall x, In x xs -> s x = t x.
  Definition extends (db : D.t) (M : model (V := V.t))
      (nu nu' : positive -> carrier M) : Prop :=
    forall i, D.allocated db i -> nu' i = nu i.
  Definition derived (p : program V.t) (initial current : D.t) : Prop :=
    forall f k o, row (D.view current) f k o -> derives V.prim p (D.view initial) f k.
  Definition grows_upto (db db' : D.t) : Prop :=
    (forall i j, same (D.view db) i j -> same (D.view db') i j) /\
    (forall f k o, row (D.view db) f k o -> exists k' o',
      row (D.view db') f k' o' /\ Forall2 (cell_rel (same (D.view db'))) k k' /\
      D.out_le db' f (option_map (D.canon db') o) o').
  (** Two identifiers that occur in rows and are equal in the view are identical. *)
  Definition row_ids_unique (w : Model.view (V := V.t)) : Prop :=
    forall f k o f' k' o' i j, row w f k o -> row w f' k' o' ->
      In (Id i) (k ++ option_list o) -> In (Id j) (k' ++ option_list o') ->
      same w i j -> i = j.

  (** Every accepted plan carries the rule index used for checking it. *)
  Lemma run_check_cplan_index : forall newok table i r c,
    check_cplan V.eqb newok table i r c = true -> rule_ix V.t c = i.
  Proof.
    intros newok table i [q acts] [ix [n cols] srcs vars post] Hcheck.
    cbn [check_cplan rule_ix] in *.
    destruct (N.eqb ix i) eqn:Hindex; [now apply N.eqb_eq|discriminate].
  Qed.

  (** A successful semi-naive scan consumes exactly a prefix of accepted plans. *)
  Lemma run_check_semis_split : forall k table i r cs tail,
    check_semis V.eqb table i r k cs = Some tail ->
    exists prefix, cs = prefix ++ tail /\
      Forall (fun c => check_cplan V.eqb true table i r c = true) prefix.
  Proof.
    induction k as [|k IH]; intros table i r cs tail Hcheck.
    - cbn [check_semis] in Hcheck. inversion Hcheck; subst tail.
      exists []. split; [reflexivity|constructor].
    - destruct cs as [|c cs]; cbn [check_semis] in Hcheck; [discriminate|].
      destruct (check_cplan V.eqb true table i r c) eqn:Hplan; [|discriminate].
      destruct (IH table i r cs tail Hcheck) as [prefix [Hprefix Hall]].
      exists (c :: prefix). split; [cbn; now rewrite Hprefix|].
      constructor; assumption.
  Qed.

  (** Every plan accepted with a rule list is checked against its indexed rule. *)
  Lemma run_check_rule_plans_member : forall rs table i naive semi,
    check_rule_plans V.eqb table rs i naive semi = true ->
    forall c, In c (naive ++ semi) -> exists k r newok,
      nth_error rs k = Some r /\ N.to_nat (rule_ix V.t c) = N.to_nat i + k /\
      check_cplan V.eqb newok table (rule_ix V.t c) r c = true.
  Proof.
    induction rs as [|[q acts] rs IH]; intros table i naive semi Hcheck c Hin.
    - destruct naive as [|d naive]; cbn [check_rule_plans] in Hcheck; [|discriminate].
      destruct semi; [contradiction|discriminate].
    - destruct naive as [|d naive]; cbn [check_rule_plans] in Hcheck; [discriminate|].
      destruct (check_cplan V.eqb false table i (Rule V.t q acts) d)
        eqn:Hplan; [|discriminate].
      destruct (check_semis V.eqb table i (Rule V.t q acts) (fun_count q) semi)
        as [tail|] eqn:Hsemis; [|discriminate].
      destruct (run_check_semis_split (fun_count q) table i (Rule V.t q acts)
        semi tail Hsemis) as [prefix [Hprefix Hall]].
      assert (Hhere : forall newok,
          check_cplan V.eqb newok table i (Rule V.t q acts) c = true ->
          exists k r newok,
            nth_error (Rule V.t q acts :: rs) k = Some r /\
            N.to_nat (rule_ix V.t c) = N.to_nat i + k /\
            check_cplan V.eqb newok table (rule_ix V.t c) r c = true).
      { intros newok Hc. pose proof (run_check_cplan_index newok table i
          (Rule V.t q acts) c Hc) as Hindex.
        exists 0, (Rule V.t q acts), newok. split; [reflexivity|].
        rewrite Hindex. split; [lia|exact Hc]. }
      assert (Hlater : In c (naive ++ tail) -> exists k r newok,
          nth_error (Rule V.t q acts :: rs) k = Some r /\
          N.to_nat (rule_ix V.t c) = N.to_nat i + k /\
          check_cplan V.eqb newok table (rule_ix V.t c) r c = true).
      { intro Htail. destruct (IH table (N.succ i) naive tail Hcheck c Htail)
          as [k [r [newok [Hnth [Hindex Hc]]]]].
        exists (S k), r, newok. split; [exact Hnth|].
        split; [rewrite N2Nat.inj_succ in Hindex; lia|exact Hc]. }
      apply in_app_or in Hin. destruct Hin as [[Heq|Hin]|Hin].
      + subst c. now apply (Hhere false).
      + apply Hlater. apply in_or_app. now left.
      + rewrite Hprefix in Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
        * apply (Hhere true). now apply Forall_forall with (x := c) in Hall.
        * apply Hlater. apply in_or_app. now right.
  Qed.

  (** A checked compiled plan has a valid slot table and an accepted indexed rule. *)
  Lemma run_plan_member : forall p cp c, plans_ok p cp -> In c (all_plans cp) ->
    exists table newok r,
      slot_table (decl_widths (decls V.t p) Empty) (Syntax.slots V.t cp) 0 Empty =
        Some table /\
      nth_error (rules V.t p) (N.to_nat (rule_ix V.t c)) = Some r /\
      check_cplan V.eqb newok table (rule_ix V.t c) r c = true.
  Proof.
    intros [ds rs] [sl naive semi] c Hplan Hin.
    unfold plans_ok, check_plan in Hplan. apply andb_true_iff in Hplan.
    destruct Hplan as [_ Hshape]. unfold check_shape, check_shape_with in Hshape.
    destruct (slot_table (decl_widths ds Empty) sl 0 Empty)
      as [table|] eqn:Htable; [|discriminate].
    rewrite check_rule_plans_at_agrees in Hshape.
    destruct (run_check_rule_plans_member rs table 0 naive semi Hshape c Hin)
      as [k [r [newok [Hnth [Hindex Hc]]]]].
    cbn in Hindex. exists table, newok, r. split; [exact Htable|].
    split; [now rewrite Hindex|exact Hc].
  Qed.

  (** A checked plan names a rule of its program. *)
  Lemma job_rule_spec : forall p cp c, plans_ok p cp -> In c (all_plans cp) ->
    nth_error (rules V.t p) (N.to_nat (rule_ix V.t c)) = Some (job_rule p c).
  Proof.
    intros p cp c Hplan Hin.
    destruct (run_plan_member p cp c Hplan Hin) as [table [newok [r [_ [Hnth _]]]]].
    unfold job_rule. erewrite nth_error_nth; [exact Hnth|exact Hnth].
  Qed.

  (** Repeated variables consume copy positions in their order within one atom. *)
  Fixpoint run_term_duplicates (seen : ptrie unit) (ts : list (term V.t)) : list positive :=
    match ts with
    | [] => []
    | Lit _ :: rest => run_term_duplicates seen rest
    | Var x :: rest =>
        match trie_get x seen with
        | Some _ => x :: run_term_duplicates seen rest
        | None => run_term_duplicates (PTrieCode.set x tt seen) rest
        end
    end.

  (** Function atoms consume consecutive pieces of the shared copy prefix. *)
  Fixpoint run_query_duplicates (q : list (atom V.t)) : list positive :=
    match q with
    | [] => []
    | Prim _ _ _ _ :: rest => run_query_duplicates rest
    | Fun _ _ args res :: rest =>
        run_term_duplicates Empty (args ++ option_list res) ++ run_query_duplicates rest
    end.

  (** The exact post list contains primitives and function atoms with repeated variables. *)
  Fixpoint run_query_post (q : list (atom V.t)) (ai : nat) : list nat :=
    match q with
    | [] => []
    | Prim _ _ _ _ :: rest => ai :: run_query_post rest (S ai)
    | Fun _ _ args res :: rest =>
        match run_term_duplicates Empty (args ++ option_list res) with
        | [] => run_query_post rest (S ai)
        | _ :: _ => ai :: run_query_post rest (S ai)
        end
    end.

  (** Counting repeated variables is the length of their explicit enumeration. *)
  Lemma run_term_duplicates_count : forall ts seen n,
    term_copies seen ts n = length (run_term_duplicates seen ts) + n.
  Proof.
    induction ts as [|[x|v] rest IH]; intros seen n; cbn [term_copies run_term_duplicates].
    - reflexivity.
    - destruct (trie_get x seen); rewrite IH; cbn [length]; lia.
    - apply IH.
  Qed.

  (** The planner's copy budget is the total repeated-variable count. *)
  Lemma run_query_duplicates_count : forall q n,
    query_copies q n = length (run_query_duplicates q) + n.
  Proof.
    induction q as [|[f args res|p args res] rest IH]; intro n;
      cbn [query_copies run_query_duplicates].
    - reflexivity.
    - rewrite IH, run_term_duplicates_count, length_app. lia.
    - apply IH.
  Qed.

  (** Equal concrete cells pass the post filter's equality test. *)
  Lemma run_cell_eqb_refl : forall c : cell V.t, cell_eqb V.eqb c c = true.
  Proof.
    intros [i|v]; cbn [cell_eqb]; [apply Pos.eqb_refl|apply planner_value_refl].
  Qed.

  (** The concrete-cell equality test reflects actual equality. *)
  Lemma run_cell_eqb_spec : forall a b : cell V.t,
    reflect (a = b) (cell_eqb V.eqb a b).
  Proof.
    intros [i|v] [j|w]; cbn [cell_eqb].
    - destruct (Pos.eqb_spec i j); constructor; congruence.
    - constructor; discriminate.
    - constructor; discriminate.
    - destruct (V.eqb_spec v w); constructor; congruence.
  Qed.

  (** Correct copy cells consume precisely the names assigned to the repeated variables. *)
  Lemma run_copies_ok_complete : forall ts seen t names tail,
    Forall2 (fun z x => exists c, trie_get z t = Some c /\ trie_get x t = Some c)
      names (run_term_duplicates seen ts) ->
    copies_ok V.eqb t seen ts (names ++ tail) = Some tail.
  Proof.
    induction ts as [|[x|v] rest IH]; intros seen t names tail Hcopies;
      cbn [run_term_duplicates] in Hcopies; cbn [copies_ok].
    - inversion Hcopies; subst. reflexivity.
    - destruct (trie_get x seen) as [u|] eqn:Hseen.
      + inversion Hcopies as [|z x' names' xs [c [Hz Hx]] Hrest]; subst.
        cbn [app]. rewrite Hz, Hx, run_cell_eqb_refl. now apply IH.
      + now apply IH.
    - now apply IH.
  Qed.

  (** A successful term check marks an atom exactly when it encounters a repeated variable. *)
  Lemma run_check_terms_copied : forall ts names pos seen copy inv srcs cols copied
      copy' inv' srcs' cols' copied',
    check_terms V.eqb names ts pos seen copy inv srcs cols copied =
      Some (copy', inv', srcs', cols', copied') ->
    copied' = match run_term_duplicates seen ts with [] => copied | _ :: _ => true end.
  Proof.
    induction ts as [|[x|v] rest IH]; intros names pos seen copy inv srcs cols copied
      copy' inv' srcs' cols' copied' Hcheck; cbn [check_terms] in Hcheck.
    - inversion Hcheck. reflexivity.
    - cbn [run_term_duplicates]. destruct (trie_get x seen) as [u|] eqn:Hseen.
      + specialize (IH _ _ _ _ _ _ _ _ _ _ _ _ _ Hcheck).
        destruct (run_term_duplicates seen rest); exact IH.
      + destruct (trie_get x names) as [j|]; [|discriminate Hcheck].
        eapply IH. exact Hcheck.
    - destruct srcs as [|[s|s|[i|w]] srcs]; try discriminate Hcheck.
      destruct cols as [|col cols]; [discriminate Hcheck|].
      destruct col as [|j col]; [discriminate Hcheck|].
      destruct col; [|discriminate Hcheck].
      destruct (V.eqb w v); [|discriminate Hcheck].
      eapply IH. exact Hcheck.
  Qed.

  (** An accepted atom reports whether its term list needs a copy comparison. *)
  Lemma run_check_atom_copied : forall newok names n table f ts copy used count srcs cols
      copy' used' count' srcs' cols' copied,
    check_atom V.eqb newok names n table f ts copy used count srcs cols =
      Some (copy', used', count', srcs', cols', copied) ->
    copied = match run_term_duplicates Empty ts with [] => false | _ :: _ => true end.
  Proof.
    intros newok names n table f ts copy used count srcs cols copy' used' count' srcs'
      cols' copied Hcheck. unfold check_atom in Hcheck.
    destruct srcs as [|src srcs]; [discriminate Hcheck|].
    destruct cols as [|col cols]; [discriminate Hcheck|].
    destruct (source_slot newok src) as [s|]; [|discriminate Hcheck].
    destruct (column_ok n col None); [|discriminate Hcheck].
    destruct (Nat.eqb (length col) (length ts)); [|discriminate Hcheck].
    destruct (check_terms V.eqb names ts 0 Empty copy Empty srcs cols false)
      as [[[[[next inv] remainingSrc] remainingCols] flag]|] eqn:Hterms;
      [|discriminate Hcheck].
    destruct (column_perm inv col used count) as [[[perm seen] total]|];
      [|discriminate Hcheck].
    destruct (slot_matches table f perm s); [|discriminate Hcheck].
    inversion Hcheck; subst. eapply run_check_terms_copied. exact Hterms.
  Qed.

  (** Successful query checking reconstructs the exact forward post list in reverse order. *)
  Lemma run_check_query_post : forall q newok names n table ai copy used count srcs cols post
      count' srcs' cols' post',
    check_query V.eqb newok names n table q ai copy used count srcs cols post =
      Some (count', srcs', cols', post') ->
    post' = rev (run_query_post q ai) ++ post.
  Proof.
    induction q as [|[f args res|p args res] rest IH];
      intros newok names n table ai copy used count srcs cols post count' srcs' cols' post'
      Hcheck; cbn [check_query] in Hcheck.
    - inversion Hcheck; reflexivity.
    - destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
        copy used count srcs cols) as [[[[[[next seen] total] remainingSrc] remainingCols]
        copied]|] eqn:Hatom; [|discriminate Hcheck].
      pose proof (run_check_atom_copied _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hatom) as Hcopied.
      specialize (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hcheck).
      cbn [run_query_post]. destruct (run_term_duplicates Empty (args ++ option_list res));
        subst copied; cbn in IH; rewrite IH; [reflexivity|].
      cbn [rev]. rewrite <- app_assoc. reflexivity.
    - specialize (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ Hcheck).
      rewrite IH. cbn [run_query_post rev]. rewrite <- app_assoc. reflexivity.
  Qed.

  (** Trie value lookup is exactly the concrete meaning of a value term. *)
  Lemma run_trie_term_spec : forall (t : ptrie (cell V.t)) term v,
    trie_term t term = Some v <->
    term_value (fun x => trie_get x t) term (Val v).
  Proof.
    intros t [x|w] v; cbn [trie_term term_value].
    - destruct (trie_get x t) as [[i|w]|]; split; intros H; congruence.
    - split; intros H; congruence.
  Qed.

  (** A list of literal value cells has those exact primitive values. *)
  Lemma run_values_map : forall vs : list V.t, values (map Val vs) vs.
  Proof.
    induction vs; cbn [map]; constructor; auto.
  Qed.

  (** Successful trie evaluation supplies every argument term witness. *)
  Lemma run_trie_terms_sound : forall (ts : list (term V.t)) t vs, trie_terms t ts = Some vs ->
    terms_value (fun x => trie_get x t) ts (map Val vs).
  Proof.
    induction ts as [|term rest IH]; intros t vs Heval; cbn [trie_terms] in Heval.
    - inversion Heval. constructor.
    - destruct (trie_term t term) as [v|] eqn:Hterm; [|discriminate Heval].
      destruct (trie_terms t rest) as [tail|] eqn:Htail; [|discriminate Heval].
      inversion Heval; subst vs. cbn [map]. constructor.
      + apply run_trie_term_spec. exact Hterm.
      + now apply IH.
  Qed.

  (** Value term witnesses determine the executable primitive argument list. *)
  Lemma run_trie_terms_complete : forall (ts : list (term V.t)) cs t vs,
    terms_value (fun x => trie_get x t) ts cs -> values cs vs -> trie_terms t ts = Some vs.
  Proof.
    intros ts cs t vs Hterms. revert vs.
    induction Hterms as [|term c rest cells Hterm Hterms IH]; intros vs Hvalues.
    - inversion Hvalues; reflexivity.
    - inversion Hvalues as [|c' v cells' values' Hcell Htail]; subst c' cells' vs c.
      cbn [trie_terms]. rewrite (proj2 (run_trie_term_spec t term v) Hterm), (IH _ Htail).
      reflexivity.
  Qed.

  (** Primitive post checking decides the corresponding concrete query atom. *)
  Lemma run_prim_holds_spec : forall w t p args res,
    prim_holds V.prim V.eqb t p args res = true <->
    atom_holds V.prim w (fun x => trie_get x t) (Prim V.t p args res).
  Proof.
    intros w t p args res. split.
    - unfold prim_holds. destruct (trie_terms t args) as [vs|] eqn:Hargs;
        [|discriminate].
      destruct (V.prim p vs) as [v|] eqn:Hprim; [|discriminate].
      destruct (trie_term t res) as [value|] eqn:Hres; [|discriminate].
      intro Heq. destruct (V.eqb_spec value v) as [->|Hneq]; [|discriminate Heq].
      exists (map Val vs), vs, v. split; [now apply run_trie_terms_sound|].
      split; [apply run_values_map|]. split; [exact Hprim|].
      apply run_trie_term_spec. exact Hres.
    - intros [cells [vs [v [Hargs [Hvalues [Hprim Hres]]]]]].
      unfold prim_holds.
      rewrite (run_trie_terms_complete args cells t vs Hargs Hvalues), Hprim.
      rewrite (proj2 (run_trie_term_spec t res v) Hres). apply planner_value_refl.
  Qed.

  (** The exact query post list succeeds when primitives and assigned copy values agree. *)
  Lemma run_keep_query_complete : forall q whole ai t names extra,
    (forall j a, nth_error q j = Some a -> nth_error whole (ai + j) = Some a) ->
    Forall (fun a => match a with
      | Prim _ p args res => prim_holds V.prim V.eqb t p args res = true
      | Fun _ _ _ _ => True
      end) q ->
    Forall2 (fun z x => exists c, trie_get z t = Some c /\ trie_get x t = Some c)
      names (run_query_duplicates q) ->
    keep_post V.prim V.eqb whole t (run_query_post q ai) (names ++ extra) = true.
  Proof.
    induction q as [|a rest IH]; intros whole ai t names extra Hindex Hprims Hcopies.
    - reflexivity.
    - inversion Hprims as [|a' rest' Hhead Htail]; subst a' rest'.
      assert (Hhere : nth_error whole ai = Some a).
      { replace ai with (ai + 0) at 1 by lia. apply Hindex. reflexivity. }
      assert (Hnext : forall j a', nth_error rest j = Some a' ->
          nth_error whole (S ai + j) = Some a').
      { intros j a' Hget. replace (S ai + j) with (ai + S j) by lia.
        apply Hindex. exact Hget. }
      destruct a as [f args res|p args res]; cbn [run_query_duplicates] in Hcopies.
      + apply Forall2_app_inv_r in Hcopies.
        destruct Hcopies as [local [later [Hlocal [Hlater ->]]]].
        cbn [run_query_post].
        destruct (run_term_duplicates Empty (args ++ option_list res)) as [|x xs] eqn:Hdups.
        * inversion Hlocal; subst local. cbn [app].
          eapply IH; eassumption.
        * cbn [keep_post]. rewrite Hhere, <- app_assoc.
          assert (Hconsume : copies_ok V.eqb t Empty (args ++ option_list res)
              (local ++ (later ++ extra)) = Some (later ++ extra)).
          { apply run_copies_ok_complete. now rewrite Hdups. }
          rewrite Hconsume. eapply IH; eassumption.
      + cbn [run_query_post keep_post]. rewrite Hhere, Hhead.
        eapply IH; eassumption.
  Qed.

  (** A correct copy prefix suffices for the complete post filter of a query. *)
  Lemma run_keep_post_complete : forall q t vars,
    Forall (fun a => match a with
      | Prim _ p args res => prim_holds V.prim V.eqb t p args res = true
      | Fun _ _ _ _ => True
      end) q ->
    Forall2 (fun z x => exists c, trie_get z t = Some c /\ trie_get x t = Some c)
      (firstn (query_copies q 0) vars) (run_query_duplicates q) ->
    keep_post V.prim V.eqb q t (run_query_post q 0) vars = true.
  Proof.
    intros q t vars Hprim Hcopy.
    pose proof (run_keep_query_complete q q 0 t (firstn (query_copies q 0) vars)
      (skipn (query_copies q 0) vars) (fun j a Hget => Hget) Hprim Hcopy) as Hkeep.
    rewrite firstn_skipn in Hkeep. exact Hkeep.
  Qed.

  (** A successful copy scan consumes exactly a prefix with matching concrete values. *)
  Lemma run_copies_ok_sound : forall ts seen t vars tail,
    copies_ok V.eqb t seen ts vars = Some tail ->
    exists names, vars = names ++ tail /\
      Forall2 (fun z x => exists c, trie_get z t = Some c /\ trie_get x t = Some c)
        names (run_term_duplicates seen ts).
  Proof.
    induction ts as [|[x|v] rest IH]; intros seen t vars tail Hcopy;
      cbn [copies_ok] in Hcopy; cbn [run_term_duplicates].
    - inversion Hcopy; subst vars. exists []. split; [reflexivity|constructor].
    - destruct (trie_get x seen) as [u|] eqn:Hseen.
      + destruct vars as [|z vars]; [discriminate Hcopy|].
        destruct (trie_get z t) as [c|] eqn:Hz; [|discriminate Hcopy].
        destruct (trie_get x t) as [d|] eqn:Hx; [|discriminate Hcopy].
        destruct (cell_eqb V.eqb c d) eqn:Heq; [|discriminate Hcopy].
        assert (Hsame : c = d).
        { destruct (run_cell_eqb_spec c d); [assumption|discriminate Heq]. }
        subst d. destruct (IH seen t vars tail Hcopy) as [names [Hvars Hnames]].
        exists (z :: names). split; [cbn [app]; now rewrite Hvars|].
        constructor; [exists c; auto|exact Hnames].
      + eapply IH. exact Hcopy.
    - eapply IH. exact Hcopy.
  Qed.

  (** Successful checking of the exact post list proves its primitive and copy conditions. *)
  Lemma run_keep_query_sound : forall q whole ai t vars,
    (forall j a, nth_error q j = Some a -> nth_error whole (ai + j) = Some a) ->
    keep_post V.prim V.eqb whole t (run_query_post q ai) vars = true ->
    Forall (fun a => match a with
      | Prim _ p args res => prim_holds V.prim V.eqb t p args res = true
      | Fun _ _ _ _ => True
      end) q /\
    exists names extra, vars = names ++ extra /\
      Forall2 (fun z x => exists c, trie_get z t = Some c /\ trie_get x t = Some c)
        names (run_query_duplicates q).
  Proof.
    induction q as [|a rest IH]; intros whole ai t vars Hindex Hkeep.
    - split; [constructor|]. exists [], vars. split; [reflexivity|constructor].
    - assert (Hhere : nth_error whole ai = Some a).
      { replace ai with (ai + 0) at 1 by lia. apply Hindex. reflexivity. }
      assert (Hnext : forall j a', nth_error rest j = Some a' ->
          nth_error whole (S ai + j) = Some a').
      { intros j a' Hget. replace (S ai + j) with (ai + S j) by lia.
        apply Hindex. exact Hget. }
      destruct a as [f args res|p args res]; cbn [run_query_post] in Hkeep.
      + destruct (run_term_duplicates Empty (args ++ option_list res)) as [|x xs] eqn:Hdups.
        * destruct (IH whole (S ai) t vars Hnext Hkeep)
            as [Hprim [names [extra [Hvars Hnames]]]].
          split; [constructor; [exact I|exact Hprim]|].
          exists names, extra. split; [exact Hvars|].
          cbn [run_query_duplicates]. rewrite Hdups. exact Hnames.
        * cbn [keep_post] in Hkeep. rewrite Hhere in Hkeep.
          destruct (copies_ok V.eqb t Empty (args ++ option_list res) vars)
            as [later|] eqn:Hcopy; [|discriminate Hkeep].
          destruct (IH whole (S ai) t later Hnext Hkeep)
            as [Hprim [names [extra [Hlater Hnames]]]].
          destruct (run_copies_ok_sound _ _ _ _ _ Hcopy) as [local [Hvars Hlocal]].
          split; [constructor; [exact I|exact Hprim]|].
          exists (local ++ names), extra. split.
          -- rewrite Hvars, Hlater, app_assoc. reflexivity.
          -- cbn [run_query_duplicates]. now apply Forall2_app.
      + cbn [keep_post] in Hkeep. rewrite Hhere in Hkeep.
        destruct (prim_holds V.prim V.eqb t p args res) eqn:Hprim; [|discriminate Hkeep].
        destruct (IH whole (S ai) t vars Hnext Hkeep) as [Htail Hcopies].
        split; [constructor; assumption|exact Hcopies].
  Qed.

  (** The first counted copy names are exactly the successful query's compared copies. *)
  Lemma run_keep_post_sound : forall q t vars,
    keep_post V.prim V.eqb q t (run_query_post q 0) vars = true ->
    Forall (fun a => match a with
      | Prim _ p args res => prim_holds V.prim V.eqb t p args res = true
      | Fun _ _ _ _ => True
      end) q /\
    Forall2 (fun z x => exists c, trie_get z t = Some c /\ trie_get x t = Some c)
      (firstn (query_copies q 0) vars) (run_query_duplicates q).
  Proof.
    intros q t vars Hkeep.
    destruct (run_keep_query_sound q q 0 t vars (fun j a Hget => Hget) Hkeep)
      as [Hprim [names [extra [-> Hcopies]]]].
    split; [exact Hprim|].
    assert (Hlength : length names = length (run_query_duplicates q)).
    { eapply Forall2_length. exact Hcopies. }
    rewrite run_query_duplicates_count, Nat.add_0_r, <- Hlength.
    rewrite firstn_app, firstn_all, Nat.sub_diag. cbn [firstn].
    rewrite app_nil_r. exact Hcopies.
  Qed.

  (** The list equality test accepts only equal lists. *)
  Lemma run_nats_eqb_sound : forall xs ys, nats_eqb xs ys = true -> xs = ys.
  Proof.
    induction xs as [|x xs IH]; intros [|y ys] Hcheck; cbn [nats_eqb] in Hcheck;
      try discriminate; [reflexivity|].
    destruct (Nat.eqb x y) eqn:Hhead; [|discriminate].
    apply Nat.eqb_eq in Hhead. subst y. f_equal. now apply IH.
  Qed.

  (** A successful variable scan starts with every scanned name unbound. *)
  Lemma run_var_table_fresh : forall vars j t names,
    var_table vars j t = Some names ->
    forall x, In x vars -> trie_get x t = None.
  Proof.
    induction vars as [|y vars IH]; intros j t names Hscan x Hin; [contradiction|].
    cbn [var_table] in Hscan.
    destruct (trie_get y t) eqn:Hfirst; [discriminate|].
    destruct Hin as [Heq|Hin]; [subst x; exact Hfirst|].
    pose proof (IH (N.succ j) (PTrieCode.set y j t) names Hscan x Hin) as Hnone.
    destruct (Pos.eq_dec y x) as [Heq|Hneq].
    - subst x. rewrite PTrie.get_set_same in Hnone. discriminate.
    - rewrite PTrie.get_set_other in Hnone by congruence. exact Hnone.
  Qed.

  (** A successful variable scan contains no repeated name. *)
  Lemma run_var_table_nodup : forall vars j t names,
    var_table vars j t = Some names -> NoDup vars.
  Proof.
    induction vars as [|x vars IH]; intros j t names Hscan; [constructor|].
    cbn [var_table] in Hscan. destruct (trie_get x t); [discriminate|].
    constructor.
    - intro Hin. pose proof (run_var_table_fresh vars (N.succ j)
        (PTrieCode.set x j t) names Hscan x Hin) as Hnone.
      rewrite PTrie.get_set_same in Hnone. discriminate.
    - exact (IH (N.succ j) (PTrieCode.set x j t) names Hscan).
  Qed.

  (** Every resulting variable-table entry was present or names its scanned position. *)
  Lemma run_var_table_origin : forall vars j t names,
    var_table vars j t = Some names -> forall x k,
    trie_get x names = Some k -> trie_get x t = Some k \/
      exists pos, nth_error vars pos = Some x /\ k = (j + N.of_nat pos)%N.
  Proof.
    induction vars as [|y vars IH]; intros j t names Hscan x k Hget.
    - cbn [var_table] in Hscan. inversion Hscan; subst names. now left.
    - cbn [var_table] in Hscan. destruct (trie_get y t); [discriminate|].
      destruct (IH (N.succ j) (PTrieCode.set y j t) names Hscan x k Hget)
        as [Hold|[pos [Hnth Hindex]]].
      + destruct (Pos.eq_dec y x) as [Heq|Hneq].
        * subst x. rewrite PTrie.get_set_same in Hold. injection Hold as <-.
          right. exists 0. split; [reflexivity|now rewrite N.add_0_r].
        * left. rewrite PTrie.get_set_other in Hold by congruence. exact Hold.
      + right. exists (S pos). split; [exact Hnth|].
        rewrite Hindex, Nat2N.inj_succ. lia.
  Qed.

  (** A checked variable table gives exactly the positions in its distinct name list. *)
  Lemma run_var_table_spec : forall vars names,
    var_table vars 0 Empty = Some names -> NoDup vars /\
      forall x j, trie_get x names = Some j <-> nth_error vars (N.to_nat j) = Some x.
  Proof.
    intros vars names Hscan.
    pose proof (run_var_table_nodup vars 0 Empty names Hscan) as Hnodup.
    split; [exact Hnodup|].
    destruct (planner_var_table_empty vars Hnodup) as [other [Hother Hlookup]].
    rewrite Hscan in Hother. injection Hother as <-.
    intros x j. split.
    - intro Hget. destruct (run_var_table_origin vars 0 Empty names Hscan x j Hget)
        as [Hempty|[pos [Hnth Hindex]]].
      + rewrite PTrie.get_empty in Hempty. discriminate.
      + rewrite Hindex, N.add_0_l, Nat2N.id. exact Hnth.
    - intro Hnth. specialize (Hlookup (N.to_nat j) x Hnth).
      now rewrite N2Nat.id in Hlookup.
  Qed.

  (** An accepted plan exposes its checked names, columns, count and exact post list. *)
  Lemma run_check_cplan_parts : forall newok table i r c,
    check_cplan V.eqb newok table i r c = true ->
    rule_ix V.t c = i /\ length (var_of V.t c) = nvars (join V.t c) /\
    exists names expected,
      var_table (var_of V.t c) 0 Empty = Some names /\
      layout_ok (query V.t r) (var_of V.t c) (sources V.t c) (cols (join V.t c)) = true /\
      check_query V.eqb newok names (nvars (join V.t c)) table (query V.t r)
        0 0 Empty 0 (sources V.t c) (cols (join V.t c)) [] =
        Some (nat_n (nvars (join V.t c)), [], [], expected) /\
      post V.t c = rev_append expected [].
  Proof.
    intros newok table i [q acts] [ix [n columns] srcs vars post] Hcheck.
    cbn [check_cplan] in Hcheck.
    destruct (N.eqb ix i) eqn:Hindex; [|discriminate].
    destruct (Nat.eqb (length vars) n) eqn:Hlength; [|discriminate].
    destruct (var_table vars 0 Empty) as [names|] eqn:Hnames; [|discriminate].
    destruct (layout_ok q vars srcs columns) eqn:Hlayout; [|discriminate].
    destruct (check_query V.eqb newok names n table q 0 0 Empty 0 srcs columns [])
      as [[[[count remaining_srcs] remaining_cols] expected]|] eqn:Hquery;
      [|discriminate].
    destruct remaining_srcs; [|discriminate]. destruct remaining_cols; [|discriminate].
    destruct (N.eqb count (nat_n n)) eqn:Hcount; [|discriminate].
    apply N.eqb_eq in Hindex. apply Nat.eqb_eq in Hlength.
    apply N.eqb_eq in Hcount. subst count.
    apply run_nats_eqb_sound in Hcheck.
    split; [exact Hindex|]. split; [exact Hlength|]. exists names, expected.
    split; [exact Hnames|]. split; [exact Hlayout|]. split; [exact Hquery|].
    symmetry. exact Hcheck.
  Qed.

  (** A matched slot test contains exactly the requested number and slot contents. *)
  Lemma run_slot_matches_sound : forall table f perm s,
    slot_matches table f perm s = true ->
    trie_get (slot_code f perm) table = Some (s, (f, perm)).
  Proof.
    intros table f perm s Hmatch. unfold slot_matches in Hmatch.
    destruct (trie_get (slot_code f perm) table) as [[s' [f' perm']]|] eqn:Hget;
      [|discriminate].
    destruct (N.eqb s' s) eqn:Hnumber; [|discriminate].
    destruct (Pos.eqb f' f) eqn:Hfunction; [|discriminate].
    apply N.eqb_eq in Hnumber. apply Pos.eqb_eq in Hfunction.
    apply run_nats_eqb_sound in Hmatch. now subst.
  Qed.

  (** Every checked slot-table entry was present or came from its numbered source row. *)
  Lemma run_slot_table_origin : forall sl widths next table checked,
    slot_table widths sl next table = Some checked -> forall key s fp,
    trie_get key checked = Some (s, fp) -> trie_get key table = Some (s, fp) \/
      exists pos, nth_error sl pos = Some fp /\ N.to_nat s = N.to_nat next + pos.
  Proof.
    induction sl as [|[f perm] sl IH]; intros widths next table checked Hscan key s fp Hget.
    - cbn [slot_table] in Hscan. inversion Hscan; subst checked. now left.
    - cbn [slot_table] in Hscan.
      destruct (trie_get f widths) as [width|]; [|discriminate].
      destruct (perm_ok width perm Empty); [|discriminate].
      destruct (trie_get (slot_code f perm) table).
      + destruct (IH widths (N.succ next) table checked Hscan key s fp Hget)
          as [Hold|[pos [Hnth Hindex]]]; [now left|].
        right. exists (S pos). split; [exact Hnth|].
        rewrite N2Nat.inj_succ in Hindex. lia.
      + destruct (IH widths (N.succ next)
          (PTrieCode.set (slot_code f perm) (next, (f, perm)) table)
          checked Hscan key s fp Hget) as [Hold|[pos [Hnth Hindex]]].
        * destruct (Pos.eq_dec (slot_code f perm) key) as [Heq|Hneq].
          -- subst key. rewrite PTrie.get_set_same in Hold.
             injection Hold as <- <-. right. exists 0. split; [reflexivity|lia].
          -- left. rewrite PTrie.get_set_other in Hold by congruence. exact Hold.
        * right. exists (S pos). split; [exact Hnth|].
          rewrite N2Nat.inj_succ in Hindex. lia.
  Qed.

  (** A slot accepted from an empty table names that slot in the original list. *)
  Lemma run_slot_matches_index : forall widths sl table f perm s,
    slot_table widths sl 0 Empty = Some table -> slot_matches table f perm s = true ->
    nth_error sl (N.to_nat s) = Some (f, perm).
  Proof.
    intros widths sl table f perm s Hscan Hmatch.
    pose proof (run_slot_matches_sound table f perm s Hmatch) as Hget.
    destruct (run_slot_table_origin sl widths 0 Empty table Hscan
      (slot_code f perm) s (f, perm) Hget) as [Hempty|[pos [Hnth Hindex]]].
    - rewrite PTrie.get_empty in Hempty. discriminate.
    - cbn in Hindex. now rewrite Hindex.
  Qed.

  (** An accepted column is ordered, bounded and nonempty at its initial check. *)
  Lemma run_column_ok_sound : forall lv n prev,
    column_ok n lv prev = true -> StronglySorted lt lv /\
      Forall (fun j => j < n) lv /\
      match prev with Some k => Forall (fun j => k < j) lv | None => lv <> [] end.
  Proof.
    induction lv as [|j lv IH]; intros n prev Hcheck.
    - destruct prev; cbn [column_ok] in Hcheck; [|discriminate].
      split; [constructor|]. split; constructor.
    - cbn [column_ok] in Hcheck.
      destruct (match prev with Some k => Nat.leb (S k) j | None => true end)
        eqn:Habove; [|discriminate].
      destruct (Nat.leb (S j) n) eqn:Hbound; [|discriminate].
      apply Nat.leb_le in Hbound.
      destruct (IH n (Some j) Hcheck) as [Hsorted [Hbounds Hafter]].
      split; [constructor; assumption|]. split; [constructor; [lia|exact Hbounds]|].
      destruct prev as [k|]; [|discriminate].
      apply Nat.leb_le in Habove. constructor; [lia|].
      apply Forall_forall. intros i Hin.
      apply Forall_forall with (x := i) in Hafter; [lia|exact Hin].
  Qed.

  (** Reading a column preserves its length, exact lookups and used-key cardinality. *)
  Lemma run_column_perm_sound : forall lv inv used count perm used' count',
    column_perm inv lv used count = Some (perm, used', count') ->
    length perm = length lv /\
    Forall2 (fun j pos => trie_get (N.succ_pos (nat_n j)) inv = Some pos) lv perm /\
    (planner_used_count used count -> planner_used_count used' count') /\
    forall j, trie_get (N.succ_pos (nat_n j)) used' = Some tt <->
      trie_get (N.succ_pos (nat_n j)) used = Some tt \/ In j lv.
  Proof.
    induction lv as [|l lv IH]; intros inv used count perm used' count' Hscan.
    - cbn [column_perm] in Hscan. inversion Hscan; subst.
      split; [reflexivity|]. split; [constructor|]. split; [auto|].
      intro j. cbn [In]. tauto.
    - cbn [column_perm] in Hscan.
      destruct (trie_get (N.succ_pos (nat_n l)) inv) as [pos|] eqn:Hpos;
        [|discriminate].
      destruct (column_perm inv lv (PTrieCode.set (N.succ_pos (nat_n l)) tt used)
        (match trie_get (N.succ_pos (nat_n l)) used with
         | Some _ => count | None => N.succ count end))
        as [[[tail used''] count'']|] eqn:Htail; [|discriminate].
      inversion Hscan; subst perm used'' count''.
      destruct (IH inv (PTrieCode.set (N.succ_pos (nat_n l)) tt used)
        (match trie_get (N.succ_pos (nat_n l)) used with
         | Some _ => count | None => N.succ count end) tail used' count' Htail)
        as [Hlength [Hlookups [Hcount Hused]]].
      split; [cbn; now rewrite Hlength|]. split; [constructor; assumption|].
      split.
      + intro Hbefore. apply Hcount. now apply planner_used_count_set.
      + intro j. rewrite Hused, planner_used_set_column. cbn [In]. tauto.
  Qed.

  (** A successful term scan leaves a suffix of its original column list. *)
  Lemma run_check_terms_tail_columns : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') -> incl columns' columns.
  Proof.
    induction ts as [|t ts IH]; intros names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' Hscan.
    - cbn [check_terms] in Hscan. inversion Hscan; subst. apply incl_refl.
    - destruct t as [x|v]; cbn [check_terms] in Hscan.
      + destruct (trie_get x seen).
        * eapply IH. exact Hscan.
        * destruct (trie_get x names); [eapply IH; exact Hscan|discriminate].
      + destruct srcs as [|src srcs]; [discriminate|].
        destruct src as [s|s|cell]; try discriminate.
        destruct cell as [i|w]; [discriminate|].
        destruct columns as [|lv columns]; [discriminate|].
        destruct lv as [|l lv]; [discriminate|]. destruct lv; [|discriminate].
        destruct (V.eqb w v); [|discriminate].
        intros col Hin. right. eapply IH; eassumption.
  Qed.

  (** A successful atom check exposes its checked source, terms and inverse permutation. *)
  Lemma run_check_atom_parts : forall newok names n table f ts copy used count srcs columns
      copy' used' count' srcs' columns' copied,
    check_atom V.eqb newok names n table f ts copy used count srcs columns =
      Some (copy', used', count', srcs', columns', copied) ->
    exists src src_tail lv col_tail s inv perm,
      srcs = src :: src_tail /\ columns = lv :: col_tail /\
      source_slot newok src = Some s /\ column_ok n lv None = true /\
      length lv = length ts /\
      check_terms V.eqb names ts 0 Empty copy Empty src_tail col_tail false =
        Some (copy', inv, srcs', columns', copied) /\
      column_perm inv lv used count = Some (perm, used', count') /\
      slot_matches table f perm s = true.
  Proof.
    intros newok names n table f ts copy used count [|src src_tail] [|lv col_tail]
      copy' used' count' srcs' columns' copied Hcheck; try discriminate.
    cbn [check_atom] in Hcheck.
    destruct (source_slot newok src) as [s|] eqn:Hsource; [|discriminate].
    destruct (column_ok n lv None) eqn:Hcolumn; [|discriminate].
    destruct (Nat.eqb (length lv) (length ts)) eqn:Hlength; [|discriminate].
    destruct (check_terms V.eqb names ts 0 Empty copy Empty src_tail col_tail false)
      as [[[[[nextcopy inv] nextsrcs] nextcols] nextcopied]|] eqn:Hterms;
      [|discriminate].
    destruct (column_perm inv lv used count) as [[[perm nextused] nextcount]|]
      eqn:Hperm; [|discriminate].
    destruct (slot_matches table f perm s) eqn:Hslot; [|discriminate].
    inversion Hcheck; subst nextcopy nextused nextcount nextsrcs nextcols nextcopied.
    apply Nat.eqb_eq in Hlength.
    exists src, src_tail, lv, col_tail, s, inv, perm.
    repeat split; assumption || reflexivity.
  Qed.

  (** Query checking records only bounded columns of its input, with an exact used count. *)
  Lemma run_check_query_used : forall q newok names n table ai copy used count srcs columns
      post finalcount srcs' columns' expected,
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (finalcount, srcs', columns', expected) ->
    planner_used_count used count ->
    (forall j, trie_get (N.succ_pos (nat_n j)) used = Some tt -> j < n) ->
    exists finalused, planner_used_count finalused finalcount /\
      (forall j, trie_get (N.succ_pos (nat_n j)) finalused = Some tt -> j < n) /\
      forall j, trie_get (N.succ_pos (nat_n j)) finalused = Some tt ->
        trie_get (N.succ_pos (nat_n j)) used = Some tt \/
        exists lv, In lv columns /\ In j lv.
  Proof.
    induction q as [|a q IH]; intros newok names n table ai copy used count srcs columns
      post finalcount srcs' columns' expected Hcheck Hcount Hwithin.
    - cbn [check_query] in Hcheck. inversion Hcheck; subst.
      exists used. split; [exact Hcount|]. split; [exact Hwithin|]. intros j Hj. now left.
    - destruct a as [f args res|p args res]; cbn [check_query] in Hcheck.
      + destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
          copy used count srcs columns)
          as [[[[[[nextcopy nextused] nextcount] nextsrcs] nextcols] copied]|]
          eqn:Hatom; [|discriminate].
        destruct (run_check_atom_parts newok names n table f (args ++ option_list res)
          copy used count srcs columns nextcopy nextused nextcount nextsrcs nextcols
          copied Hatom) as [src [src_tail [lv [col_tail [s [inv [perm
          [Hsrcs [Hcols [Hsource [Hcolumn [Hlength [Hterms [Hperm Hslot]]]]]]]]]]]]]].
        subst srcs columns.
        destruct (run_column_ok_sound lv n None Hcolumn) as [_ [Hbounds _]].
        destruct (run_column_perm_sound lv inv used count perm nextused nextcount Hperm)
          as [_ [_ [Hnextcount Hnextused]]].
        assert (Hnextwithin : forall j,
            trie_get (N.succ_pos (nat_n j)) nextused = Some tt -> j < n).
        { intros j Hj. apply Hnextused in Hj. destruct Hj as [Hj|Hin].
          - exact (Hwithin j Hj).
          - now apply Forall_forall with (x := j) in Hbounds. }
        destruct (IH newok names n table (S ai) nextcopy nextused nextcount
          nextsrcs nextcols (if copied then ai :: post else post)
          finalcount srcs' columns' expected Hcheck (Hnextcount Hcount) Hnextwithin)
          as [finalused [Hfinalcount [Hfinalwithin Hfinalcols]]].
        exists finalused. split; [exact Hfinalcount|]. split; [exact Hfinalwithin|].
        intros j Hj. destruct (Hfinalcols j Hj) as [Hj'|[col [Hcol Hin]]].
        * apply Hnextused in Hj'. destruct Hj' as [Hj'|Hin]; [now left|].
          right. exists lv. split; [now left|exact Hin].
        * right. exists col. split; [right|exact Hin].
          eapply run_check_terms_tail_columns; eassumption.
      + eapply IH; eassumption.
  Qed.

  (** An exact count equal to the bounded range's size forces every index to be present. *)
  Lemma run_used_count_full : forall used n,
    planner_used_count used (nat_n n) ->
    (forall j, trie_get (N.succ_pos (nat_n j)) used = Some tt -> j < n) ->
    forall j, j < n -> trie_get (N.succ_pos (nat_n j)) used = Some tt.
  Proof.
    intros used n Hcount Hwithin.
    assert (Hlength : n = length (planner_used_keys used)).
    { unfold planner_used_count in Hcount. rewrite planner_nat_n_spec in Hcount.
      now apply Nat2N.inj in Hcount. }
    assert (Hsubset : incl (planner_used_keys used)
        (map (fun j => N.succ_pos (nat_n j)) (seq 0 n))).
    { intros key Hin. destruct (planner_column_key_surj key) as [j ->].
      apply planner_used_keys_spec in Hin. apply in_map_iff. exists j.
      split; [reflexivity|]. apply in_seq. split; [lia|now apply Hwithin]. }
    assert (Hcover : incl (map (fun j => N.succ_pos (nat_n j)) (seq 0 n))
        (planner_used_keys used)).
    { apply NoDup_length_incl; [apply planner_used_keys_nodup| |exact Hsubset].
      rewrite length_map, length_seq. lia. }
    intros j Hbound. apply planner_used_keys_spec. apply Hcover.
    apply in_map_iff. exists j. split; [reflexivity|]. apply in_seq. lia.
  Qed.

  (** Constant sources remember the join index at which they supply their cell. *)
  Fixpoint run_literal_entries (srcs : list (source V.t)) (cols : list (list nat))
      : list (nat * cell V.t) :=
    match srcs, cols with
    | Const _ c :: rest, [j] :: tail => (j, c) :: run_literal_entries rest tail
    | _ :: rest, _ :: tail => run_literal_entries rest tail
    | _, _ => []
    end.

  (** Removing a key cannot create an entry and leaves the removed key absent. *)
  Lemma run_remove_some : forall A (t : ptrie A) key other value,
    trie_get other (PTrieCode.remove key t) = Some value ->
    other <> key /\ trie_get other t = Some value.
  Proof.
    intros A t key other value Hget.
    destruct (Pos.eq_dec other key) as [Heq|Hneq].
    - subst other. rewrite PTrie.get_remove_same in Hget. discriminate.
    - split; [exact Hneq|]. rewrite PTrie.get_remove_other in Hget by exact Hneq.
      exact Hget.
  Qed.

  (** The literal guard accepts only distinct indices present in its available-key table. *)
  Lemma run_layout_literals_sound : forall srcs cols allowed,
    layout_literals srcs cols allowed = true ->
    NoDup (map fst (run_literal_entries srcs cols)) /\
    forall j c, In (j, c) (run_literal_entries srcs cols) ->
      trie_get (N.succ_pos (nat_n j)) allowed = Some tt.
  Proof.
    induction srcs as [|src srcs IH]; intros cols allowed Hcheck.
    - destruct cols; cbn [layout_literals] in Hcheck; [|discriminate].
      split; [constructor|]. intros j c Hin. contradiction.
    - destruct cols as [|col cols]; [destruct src; discriminate|].
      destruct src as [s|s|c].
      + exact (IH cols allowed Hcheck).
      + exact (IH cols allowed Hcheck).
      + destruct col as [|j [|k col]]; cbn [layout_literals] in Hcheck;
          try discriminate.
        destruct (trie_get (N.succ_pos (nat_n j)) allowed) as [[]|] eqn:Hallowed;
          [|discriminate].
        destruct (IH cols (PTrieCode.remove (N.succ_pos (nat_n j)) allowed) Hcheck)
          as [Hdistinct Hmembers].
        cbn [run_literal_entries map]. split.
        * constructor; [|exact Hdistinct]. intro Hin.
          apply in_map_iff in Hin as [[k d] [Heq Hin]]. cbn in Heq. subst k.
          pose proof (Hmembers j d Hin) as Hget. rewrite PTrie.get_remove_same in Hget.
          discriminate.
        * intros k d [Heq|Hin].
          -- injection Heq as <- <-. exact Hallowed.
          -- exact (proj2 (run_remove_some unit allowed (N.succ_pos (nat_n j))
               (N.succ_pos (nat_n k)) tt (Hmembers k d Hin))).
  Qed.

  (** The fresh-layout scan certifies its copy prefix and records only fresh later names. *)
  Lemma run_layout_fresh_sound : forall vars bound copies j allowed result,
    layout_fresh bound copies vars j allowed = Some result ->
    copies <= length vars /\ Forall (fun x => (bound < x)%positive) (firstn copies vars) /\
    forall key, trie_get key result = Some tt -> trie_get key allowed = Some tt \/
      exists k x, copies <= k /\ nth_error vars k = Some x /\ (bound < x)%positive /\
        key = N.succ_pos (j + N.of_nat k)%N.
  Proof.
    induction vars as [|x rest IH]; intros bound copies j allowed result Htable.
    - destruct copies; cbn [layout_fresh] in Htable; [|discriminate].
      injection Htable as <-. split; [lia|]. split; [constructor|].
      intros key Hget. left. exact Hget.
    - destruct copies as [|copies]; cbn [layout_fresh] in Htable.
      + destruct (Pos.ltb bound x) eqn:Hfresh.
        * destruct (IH bound 0 (N.succ j) (PTrieCode.set (N.succ_pos j) tt allowed)
            result Htable) as [Hlength [Hprefix Hentries]].
          split; [lia|]. split; [constructor|]. intros key Hget.
          destruct (Hentries key Hget) as [Hold|[k [y [Hcopy [Hnth [Hy Hkey]]]]]].
          -- destruct (Pos.eq_dec key (N.succ_pos j)) as [Heq|Hneq].
             ++ right. exists 0, x. split; [lia|]. split; [reflexivity|].
                split; [now apply Pos.ltb_lt in Hfresh|]. now rewrite N.add_0_r.
             ++ left. rewrite PTrie.get_set_other in Hold by exact Hneq. exact Hold.
          -- right. exists (S k), y. split; [lia|]. split; [exact Hnth|].
             split; [exact Hy|]. rewrite Nat2N.inj_succ. replace (j + N.succ (N.of_nat k))%N
               with (N.succ j + N.of_nat k)%N by lia. exact Hkey.
        * destruct (IH bound 0 (N.succ j) allowed result Htable)
            as [Hlength [Hprefix Hentries]].
          split; [lia|]. split; [constructor|]. intros key Hget.
          destruct (Hentries key Hget) as [Hold|[k [y [Hcopy [Hnth [Hy Hkey]]]]]].
          -- left. exact Hold.
          -- right. exists (S k), y. split; [lia|]. split; [exact Hnth|].
             split; [exact Hy|]. rewrite Nat2N.inj_succ. replace (j + N.succ (N.of_nat k))%N
               with (N.succ j + N.of_nat k)%N by lia. exact Hkey.
      + destruct (Pos.ltb bound x) eqn:Hfresh; [|discriminate].
        destruct (IH bound copies (N.succ j) allowed result Htable)
          as [Hlength [Hprefix Hentries]].
        split; [cbn; lia|]. split.
        * cbn [firstn]. constructor; [now apply Pos.ltb_lt in Hfresh|exact Hprefix].
        * intros key Hget.
          destruct (Hentries key Hget) as [Hold|[k [y [Hcopy [Hnth [Hy Hkey]]]]]].
          -- left. exact Hold.
          -- right. exists (S k), y. split; [lia|]. split; [exact Hnth|].
             split; [exact Hy|]. rewrite Nat2N.inj_succ. replace (j + N.succ (N.of_nat k))%N
               with (N.succ j + N.of_nat k)%N by lia. exact Hkey.
  Qed.

  (** Accepted layouts give fresh copy names and distinct fresh noncopy literal positions. *)
  Lemma run_layout_ok_sound : forall q vars srcs cols,
    layout_ok q vars srcs cols = true ->
    query_copies q 0 <= length vars /\
    Forall (fun x => (query_max q 1%positive < x)%positive)
      (firstn (query_copies q 0) vars) /\
    NoDup (map fst (run_literal_entries srcs cols)) /\
    forall j c, In (j, c) (run_literal_entries srcs cols) -> exists x,
      query_copies q 0 <= j /\ nth_error vars j = Some x /\
      (query_max q 1%positive < x)%positive.
  Proof.
    intros q vars srcs cols Hcheck. unfold layout_ok in Hcheck.
    destruct (layout_fresh (query_max q 1%positive) (query_copies q 0) vars 0 Empty)
      as [allowed|] eqn:Hfresh; [|discriminate].
    destruct (run_layout_fresh_sound vars (query_max q 1%positive) (query_copies q 0)
      0 Empty allowed Hfresh) as [Hlength [Hprefix Hentries]].
    destruct (run_layout_literals_sound srcs cols allowed Hcheck) as [Hdistinct Hliterals].
    split; [exact Hlength|]. split; [exact Hprefix|]. split; [exact Hdistinct|].
    intros j c Hin. destruct (Hentries _ (Hliterals j c Hin)) as [Hempty|Hentry].
    - rewrite PTrie.get_empty in Hempty. discriminate.
    - destruct Hentry as [k [x [Hcopy [Hnth [Hx Hkey]]]]].
      change (N.succ_pos (nat_n j) = N.succ_pos (N.of_nat k)) in Hkey.
      rewrite <- planner_nat_n_spec in Hkey. apply planner_column_key_inj in Hkey.
      subst k. exists x. repeat split; assumption.
  Qed.

  (** Literal guards give one bounded column for each constant source. *)
  Lemma run_layout_literals_columns : forall (srcs : list (source V.t)) cols allowed n,
    layout_literals srcs cols allowed = true ->
    (forall j, trie_get (N.succ_pos (nat_n j)) allowed = Some tt -> j < n) ->
    Forall2 (fun src lv => match src with
      | Const _ _ => exists j, lv = [j] /\ j < n
      | _ => True
      end) srcs cols.
  Proof.
    induction srcs as [|src srcs IH]; intros cols allowed n Hcheck Hbound.
    - destruct cols; [constructor|discriminate].
    - destruct cols as [|col cols]; [destruct src; discriminate|].
      destruct src as [s|s|c].
      + constructor; [exact I|]. eapply IH; eassumption.
      + constructor; [exact I|]. eapply IH; eassumption.
      + destruct col as [|j [|k col]]; cbn [layout_literals] in Hcheck;
          try discriminate.
        destruct (trie_get (N.succ_pos (nat_n j)) allowed) as [[]|] eqn:Hallowed;
          [|discriminate].
        constructor.
        * exists j. split; [reflexivity|]. now apply Hbound.
        * eapply IH; [exact Hcheck|]. intros k Hget. apply Hbound.
          exact (proj2 (run_remove_some unit allowed (N.succ_pos (nat_n j))
            (N.succ_pos (nat_n k)) tt Hget)).
  Qed.

  (** The complete layout guard supplies well-formed constant-source columns. *)
  Lemma run_layout_columns : forall (q : list (atom V.t)) vars srcs cols,
    layout_ok q vars srcs cols = true ->
    Forall2 (fun src lv => match src with
      | Const _ _ => exists j, lv = [j] /\ j < length vars
      | _ => True
      end) srcs cols.
  Proof.
    intros q vars srcs cols Hcheck. unfold layout_ok in Hcheck.
    destruct (layout_fresh (query_max q 1%positive) (query_copies q 0) vars 0 Empty)
      as [allowed|] eqn:Hfresh; [|discriminate].
    apply (run_layout_literals_columns srcs cols allowed (length vars) Hcheck).
    intros j Hget.
    destruct (run_layout_fresh_sound vars (query_max q 1%positive) (query_copies q 0)
      0 Empty allowed Hfresh) as [_ [_ Hentries]].
    destruct (Hentries _ Hget) as [Hempty|[k [x [_ [Hnth [_ Hkey]]]]]].
    - rewrite PTrie.get_empty in Hempty. discriminate.
    - change (N.succ_pos (nat_n j) = N.succ_pos (N.of_nat k)) in Hkey.
      rewrite <- planner_nat_n_spec in Hkey. apply planner_column_key_inj in Hkey. subst k.
      apply nth_error_Some. rewrite Hnth. discriminate.
  Qed.

  (** A source column has valid join shape, a matching index arity and safe constants. *)
  Definition run_source_column (db : D.t) (n : nat) (src : source V.t)
      (lv : list nat) : Prop :=
    lv <> [] /\ StronglySorted lt lv /\ Forall (fun j => j < n) lv /\
    I.wf (length lv) (source_index db src) /\
    match src with Const _ c => exists v, c = Val v | _ => True end.

  (** A checked slot source has the arity of its registered permutation. *)
  Lemma run_source_index_wf : forall db widths sl table newok src s f perm,
    D.wf db -> D.slots db = sl -> slot_table widths sl 0 Empty = Some table ->
    source_slot newok src = Some s -> slot_matches table f perm s = true ->
    I.wf (length perm) (source_index db src).
  Proof.
    intros db widths sl table newok src s f perm Hwf Hslots Htable Hsource Hmatch.
    assert (Hslot : D.slot_of db s = Some (f, perm)).
    { unfold D.slot_of. rewrite Hslots. now apply (run_slot_matches_index widths sl table). }
    destruct src as [s'|s'|c]; cbn [source_slot source_index] in *; try discriminate.
    - injection Hsource as <-. now apply (D.index_wf db s' false f perm).
    - destruct newok; [|discriminate]. injection Hsource as <-.
      now apply (D.index_wf db s' true f perm).
  Qed.

  (** A term scan consumes well-formed singleton value sources and preserves its tail. *)
  Lemma run_check_terms_columns : forall ts db n names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    Forall2 (fun src lv => match src with
      | Const _ _ => exists j, lv = [j] /\ j < n | _ => True end) srcs columns ->
    Forall2 (fun src lv => match src with
      | Const _ _ => exists j, lv = [j] /\ j < n | _ => True end) srcs' columns' /\
    (Forall2 (run_source_column db n) srcs' columns' ->
      Forall2 (run_source_column db n) srcs columns).
  Proof.
    induction ts as [|t ts IH]; intros db n names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' Hscan Hlayout.
    - cbn [check_terms] in Hscan. inversion Hscan; subst. split; [exact Hlayout|auto].
    - destruct t as [x|v]; cbn [check_terms] in Hscan.
      + destruct (trie_get x seen).
        * eapply IH; eassumption.
        * destruct (trie_get x names); [eapply IH; eassumption|discriminate].
      + destruct srcs as [|src srcs]; [discriminate|].
        destruct src as [s|s|cell]; try discriminate.
        destruct cell as [i|w]; [discriminate|].
        destruct columns as [|lv columns]; [discriminate|].
        destruct lv as [|l lv]; [discriminate|]. destruct lv; [|discriminate].
        destruct (V.eqb w v); [|discriminate].
        inversion Hlayout as [|src lv src_tail col_tail Hhead Htail]; subst.
        destruct Hhead as [j [Heq Hbound]]. inversion Heq; subst j.
        destruct (IH db n names (S pos) seen copy
          (PTrieCode.set (N.succ_pos (nat_n l)) pos inv) srcs columns copied
          copy' inv' srcs' columns' copied' Hscan Htail) as [Hremaining Hextend].
        split; [exact Hremaining|]. intro Hcolumns. constructor; [|now apply Hextend].
        unfold run_source_column. split; [discriminate|].
        split; [constructor; constructor|].
        split; [constructor; [exact Hbound|constructor]|].
        split.
        * cbn [source_index]. apply I.wf_insert; [apply I.wf_empty|reflexivity].
        * exists w. reflexivity.
  Qed.

  (** Every source consumed by an accepted query has a valid join column. *)
  Lemma run_check_query_columns : forall q db widths sl table newok names n ai copy used
      count srcs columns post finalcount expected,
    D.wf db -> D.slots db = sl -> slot_table widths sl 0 Empty = Some table ->
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (finalcount, [], [], expected) ->
    Forall2 (fun src lv => match src with
      | Const _ _ => exists j, lv = [j] /\ j < n | _ => True end) srcs columns ->
    Forall2 (run_source_column db n) srcs columns.
  Proof.
    induction q as [|a q IH]; intros db widths sl table newok names n ai copy used
      count srcs columns post finalcount expected Hwf Hslots Htable Hcheck Hlayout.
    - cbn [check_query] in Hcheck. inversion Hcheck; subst. constructor.
    - destruct a as [f args res|p args res]; cbn [check_query] in Hcheck.
      + destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
          copy used count srcs columns)
          as [[[[[[nextcopy nextused] nextcount] nextsrcs] nextcols] copied]|]
          eqn:Hatom; [|discriminate].
        destruct (run_check_atom_parts newok names n table f (args ++ option_list res)
          copy used count srcs columns nextcopy nextused nextcount nextsrcs nextcols
          copied Hatom) as [src [src_tail [lv [col_tail [s [inv [perm
          [Hsrcs [Hcols [Hsource [Hcolumn [Hlength [Hterms [Hperm Hslot]]]]]]]]]]]]]].
        subst srcs columns.
        inversion Hlayout as [|src' lv' src_tail' col_tail' Hhead Htail];
          subst src' lv' src_tail' col_tail'.
        destruct (run_check_terms_columns (args ++ option_list res) db n names 0 Empty
          copy Empty src_tail col_tail false nextcopy inv nextsrcs nextcols copied
          Hterms Htail) as [Hremaining Hextend].
        constructor.
        * destruct (run_column_ok_sound lv n None Hcolumn)
            as [Hsorted [Hbounds Hnonempty]].
          destruct (run_column_perm_sound lv inv used count perm nextused nextcount Hperm)
            as [Hperm_length _].
          unfold run_source_column.
          split; [exact Hnonempty|]. split; [exact Hsorted|]. split; [exact Hbounds|].
          split.
          -- rewrite <- Hperm_length.
             exact (run_source_index_wf db widths sl table newok src s f perm
               Hwf Hslots Htable Hsource Hslot).
          -- destruct src; try exact I. discriminate Hsource.
        * apply Hextend. eapply IH; eassumption.
      + eapply IH; eassumption.
  Qed.

  (** A checked plan supplies valid source columns against a loaded database. *)
  Lemma run_check_cplan_columns : forall p cp db table newok r c,
    D.wf db -> loaded p cp db ->
    slot_table (decl_widths (decls V.t p) Empty) (Syntax.slots V.t cp) 0 Empty =
      Some table ->
    check_cplan V.eqb newok table (rule_ix V.t c) r c = true ->
    Forall2 (run_source_column db (nvars (join V.t c))) (sources V.t c)
      (cols (join V.t c)).
  Proof.
    intros p cp db table newok r c Hwf Hloaded Htable Hcheck.
    destruct (run_check_cplan_parts newok table (rule_ix V.t c) r c Hcheck)
      as [_ [Hlength [names [expected [Hnames [Hlayout [Hquery Hpost]]]]]]].
    pose proof (run_layout_columns (query V.t r) (var_of V.t c) (sources V.t c)
      (cols (join V.t c)) Hlayout) as Hcolumns.
    rewrite Hlength in Hcolumns.
    destruct Hloaded as [_ [Hslots _]].
    eapply run_check_query_columns; eassumption.
  Qed.

  (** An accepted plan meets every well-formedness premise of the join interface. *)
  Lemma run_check_cplan_wf : forall p cp db table newok r c,
    D.wf db -> loaded p cp db ->
    slot_table (decl_widths (decls V.t p) Empty) (Syntax.slots V.t cp) 0 Empty =
      Some table ->
    check_cplan V.eqb newok table (rule_ix V.t c) r c = true ->
    J.wf_plan (join V.t c) (map (source_index db) (sources V.t c)).
  Proof.
    intros p cp db table newok r c Hwf Hloaded Htable Hcheck.
    pose proof (run_check_cplan_columns p cp db table newok r c Hwf Hloaded Htable Hcheck)
      as Hcolumns.
    destruct (run_check_cplan_parts newok table (rule_ix V.t c) r c Hcheck)
      as [_ [Hlength [names [expected [Hnames [Hlayout [Hquery Hpost]]]]]]].
    unfold J.wf_plan. split.
    - rewrite length_map. symmetry. now apply Forall2_length in Hcolumns.
    - split.
      + clear -Hcolumns. induction Hcolumns as [|src lv srcs lvs Hhead Htail IH].
        * constructor.
        * cbn [map]. constructor; [|exact IH].
          destruct Hhead as [Hnonempty [Hsorted [Hbounds [Hindex _]]]].
          repeat split; assumption.
      + destruct (run_check_query_used (query V.t r) newok names (nvars (join V.t c))
          table 0 0 Empty 0 (sources V.t c) (cols (join V.t c)) []
          (nat_n (nvars (join V.t c))) [] [] expected Hquery planner_used_count_empty)
          as [used [Hcount [Hwithin Hcover]]].
        * intros j Hempty. rewrite PTrie.get_empty in Hempty. discriminate.
        * intros j Hbound.
          destruct (Hcover j (run_used_count_full used (nvars (join V.t c))
            Hcount Hwithin j Hbound)) as [Hempty|Hcolumn].
          -- rewrite PTrie.get_empty in Hempty. discriminate.
          -- exact Hcolumn.
  Qed.

  (** Every compiled plan accepted for a loaded database is a well-formed join. *)
  Lemma run_plan_join_wf : forall p cp db c, plans_ok p cp -> D.wf db ->
    loaded p cp db -> In c (all_plans cp) ->
    J.wf_plan (join V.t c) (map (source_index db) (sources V.t c)).
  Proof.
    intros p cp db c Hplan Hwf Hloaded Hin.
    destruct (run_plan_member p cp c Hplan Hin)
      as [table [newok [r [Htable [Hrule Hcheck]]]]].
    eapply run_check_cplan_wf; eassumption.
  Qed.

  (** A binding-environment result occurs in the binding's cell list. *)
  Lemma run_binding_env_member : forall vars (b : list (cell V.t)) x c,
    binding_env vars b x = Some c -> In c b.
  Proof.
    induction vars as [|v vars IH]; intros [|d b] x c Hget; try discriminate.
    cbn [binding_env] in Hget. destruct (Pos.eqb x v).
    - injection Hget as <-. now left.
    - right. eapply IH. exact Hget.
  Qed.

  (** A permutation only selects cells already present in its tuple. *)
  Lemma run_permute_member : forall perm u c, In c (D.permute perm u) -> In c u.
  Proof.
    intros perm u c Hin. unfold D.permute in Hin. apply in_flat_map in Hin.
    destruct Hin as [pos [_ Hin]].
    destruct (nth_error u pos) as [d|] eqn:Hnth; cbn [option_list In] in Hin;
      [|contradiction].
    destruct Hin as [Heq|Hin]; [subst d|contradiction]. now apply nth_error_In in Hnth.
  Qed.

  (** A successful projection contains every cell at a selected position. *)
  Lemma run_project_selected : forall lv b u,
    J.project lv b = Some u -> forall j c,
    In j lv -> nth_error b j = Some c -> In c u.
  Proof.
    induction lv as [|l lv IH]; intros b u Hproject j c Hin Hnth; [contradiction|].
    change (match nth_error b l, J.project lv b with
      | Some d, Some ds => Some (d :: ds) | _, _ => None end = Some u) in Hproject.
    destruct (nth_error b l) as [d|] eqn:Hhead; [|discriminate].
    destruct (J.project lv b) as [ds|] eqn:Htail; [|discriminate].
    injection Hproject as <-. destruct Hin as [Heq|Hin].
    - subst j. rewrite Hhead in Hnth. injection Hnth as <-. now left.
    - right. eapply IH; eassumption.
  Qed.

  (** Slot tuples and value constants contain only allocated identifiers. *)
  Lemma run_source_mem_allocated : forall db src u i, D.wf db ->
    (match src with Const _ c => exists v, c = Val v | _ => True end) ->
    I.mem (source_index db src) u -> In (Id i) u -> D.allocated db i.
  Proof.
    intros db [s|s|c] u i Hwf Hsafe Hmem Hin; cbn [source_index] in Hmem.
    - destruct (D.index_all db s false u Hwf Hmem)
        as [f [perm [k [o [Hslot [Hrow Heq]]]]]].
      subst u. eapply D.row_allocated; [exact Hwf|exact Hrow|].
      now apply run_permute_member in Hin.
    - destruct (D.index_all db s true u Hwf Hmem)
        as [f [perm [k [o [Hslot [Hrow Heq]]]]]].
      subst u. eapply D.row_allocated; [exact Hwf|exact Hrow|].
      now apply run_permute_member in Hin.
    - destruct Hsafe as [v ->].
      apply (proj1 (I.mem_insert 1 [Val v] I.empty u (I.wf_empty 1) eq_refl)) in Hmem.
      destruct Hmem as [->|Hempty].
      + cbn [In] in Hin. destruct Hin as [Heq|Hin]; [discriminate|contradiction].
      + exfalso. exact (I.mem_empty u Hempty).
  Qed.

  (** A joined source column allocates every identifier at one of its positions. *)
  Lemma run_source_columns_allocated : forall db n srcs columns b,
    D.wf db -> Forall2 (run_source_column db n) srcs columns ->
    Forall2 (fun lv ix => exists u, J.project lv b = Some u /\ I.mem ix u)
      columns (map (source_index db) srcs) ->
    forall lv j i, In lv columns -> In j lv -> nth_error b j = Some (Id i) ->
      D.allocated db i.
  Proof.
    intros db n srcs columns b Hwf Hcolumns.
    induction Hcolumns as [|src col srcs columns Hhead Htail IH];
      intros Hanswer lv j i Hcol Hj Hnth; [contradiction|].
    cbn [map] in Hanswer.
    inversion Hanswer as [|lv' ix columns' ixs Hsource Hrest]; subst.
    destruct Hcol as [Heq|Hcol].
    - subst lv. destruct Hsource as [u [Hproject Hmem]].
      destruct Hhead as [_ [_ [_ [_ Hsafe]]]].
      eapply run_source_mem_allocated; [exact Hwf|exact Hsafe|exact Hmem|].
      eapply run_project_selected; eassumption.
    - eapply IH; eassumption.
  Qed.

  (** Every identifier bound by an accepted plan is allocated in its loaded database. *)
  Lemma run_plan_bindings_allocated : forall p cp db c b,
    plans_ok p cp -> D.wf db -> loaded p cp db -> In c (all_plans cp) ->
    In b (bindings cp c db) -> env_allocated db (env_of c b).
  Proof.
    intros p cp db c b Hplan Hwf Hloaded Hin Hbinding.
    destruct (run_plan_member p cp c Hplan Hin)
      as [table [newok [r [Htable [Hrule Hcheck]]]]].
    pose proof (run_check_cplan_columns p cp db table newok r c Hwf Hloaded Htable Hcheck)
      as Hcolumns.
    pose proof (run_check_cplan_wf p cp db table newok r c Hwf Hloaded Htable Hcheck)
      as Hjoin.
    destruct (J.run_sound (join V.t c) (map (source_index db) (sources V.t c)) b
      Hjoin Hbinding) as [Hlength Hanswer].
    destruct Hjoin as [_ [_ Hcover]]. intros x i Henv.
    apply run_binding_env_member in Henv.
    apply In_nth_error in Henv. destruct Henv as [j Hnth].
    assert (Hbound : j < nvars (join V.t c)).
    { rewrite <- Hlength. apply nth_error_Some. rewrite Hnth. discriminate. }
    destruct (Hcover j Hbound) as [lv [Hcol Hj]].
    eapply run_source_columns_allocated; eassumption.
  Qed.

  (** The variables collected from a term list are exactly its variable terms. *)
  Lemma run_term_vars_member : forall (ts : list (term V.t)) x,
    In x (flat_map term_vars ts) <-> In (Var x) ts.
  Proof.
    intros ts x. split.
    - intro Hin. apply in_flat_map in Hin. destruct Hin as [t [Hterm Hvar]].
      destruct t as [y|v]; cbn [term_vars In] in Hvar; [|contradiction].
      destruct Hvar as [Heq|Hvar]; [now subst y|contradiction].
    - intro Hin. apply in_flat_map. exists (Var x). split; [exact Hin|now left].
  Qed.

  (** A function atom binds only variables already bound or present among its terms. *)
  Lemma run_binds_atom_scope : forall g g1 g2 args ss out res,
    @binds_list V.t g args ss g1 -> binds_result g1 out res g2 ->
    forall x u, g2 x = Some u -> g x = Some u \/ In (Var x) (args ++ option_list res).
  Proof.
    intros g g1 g2 args ss out res Hargs Hres x u Hbound.
    destruct (run_binds_result_scope g1 out res g2 Hres x u Hbound) as [Hargsbound|Hin].
    - destruct (run_binds_list_scope g args ss g1 Hargs x u Hargsbound) as [Hold|Hin].
      + now left.
      + right. apply in_or_app. now left.
    - right. apply in_or_app. now right.
  Qed.

  (** Every query variable is initially bound or appears in a function atom. *)
  Lemma run_query_vars_fun_context : forall sorts kinds g q g',
    @query_ok V.t sorts kinds g q g' -> forall x,
    In x (flat_map atom_vars q) -> (exists u, g x = Some u) \/
      exists f args res, In (Fun V.t f args res) q /\ In (Var x) (args ++ option_list res).
  Proof.
    intros sorts kinds g q g' Hquery.
    induction Hquery as [g|g g1 g2 g3 f args res ss out rest Hsort Hkind Hreads
      Hargs Hres Hrest IH|g g1 p args res rest Hargs Hres Hrest IH]; intros x Hin.
    - contradiction.
    - cbn [flat_map] in Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
      + cbn [atom_vars] in Hin. rewrite <- flat_map_app in Hin.
        apply run_term_vars_member in Hin. right. exists f, args, res.
        split; [now left|exact Hin].
      + destruct (IH x Hin) as [[u Hbound]|[f' [args' [res' [Hatom Hvar]]]]].
        * destruct (run_binds_atom_scope g g1 g2 args ss out res Hargs Hres x u Hbound)
            as [Hold|Hvar].
          -- left. now exists u.
          -- right. exists f, args, res. split; [now left|exact Hvar].
        * right. exists f', args', res'. split; [now right|exact Hvar].
    - cbn [flat_map] in Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
      + left. cbn [atom_vars] in Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
        * apply in_flat_map in Hin. destruct Hin as [t [Hterm Hvar]].
          apply Forall_forall with (x := t) in Hargs; [|exact Hterm].
          exact (run_has_scope g t SVal x Hargs Hvar).
        * exact (run_has_scope g res SVal x Hres Hin).
      + destruct (IH x Hin) as [Hbound|[f [args' [res' [Hatom Hvar]]]]].
        * now left.
        * right. exists f, args', res'. split; [now right|exact Hvar].
  Qed.

  (** Every variable of a well-sorted closed query appears in a function atom. *)
  Lemma run_query_vars_fun : forall sorts kinds q g,
    @query_ok V.t sorts kinds ctx_empty q g -> forall x,
    In x (flat_map atom_vars q) -> exists f args res,
      In (Fun V.t f args res) q /\ In (Var x) (args ++ option_list res).
  Proof.
    intros sorts kinds q g Hquery x Hin.
    destruct (run_query_vars_fun_context sorts kinds ctx_empty q g Hquery x Hin)
      as [[u Hempty]|Hfunction]; [discriminate|exact Hfunction].
  Qed.

  (** Every checked variable term was already seen or has a registered name. *)
  Lemma run_check_terms_names : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') -> forall x,
    In (Var x) ts -> trie_get x seen = Some tt \/ exists j, trie_get x names = Some j.
  Proof.
    induction ts as [|t ts IH]; intros names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' Hscan x Hin; [contradiction|].
    destruct t as [y|v]; cbn [check_terms] in Hscan.
    - destruct (trie_get y seen) as [[]|] eqn:Hseen.
      + destruct Hin as [Heq|Hin].
        * injection Heq as <-. now left.
        * eapply IH; eassumption.
      + destruct (trie_get y names) as [j|] eqn:Hname; [|discriminate].
        destruct Hin as [Heq|Hin].
        * injection Heq as <-. right. now exists j.
        * destruct (IH names (S pos) (PTrieCode.set y tt seen) copy
            (PTrieCode.set (N.succ_pos j) pos inv) srcs columns copied
            copy' inv' srcs' columns' copied' Hscan x Hin) as [Hold|Hregistered].
          -- destruct (Pos.eq_dec y x) as [Heq|Hneq].
             ++ subst x. right. now exists j.
             ++ left. rewrite PTrie.get_set_other in Hold by congruence. exact Hold.
          -- now right.
    - destruct Hin as [Heq|Hin]; [discriminate|].
      destruct srcs as [|src srcs]; [discriminate|].
      destruct src as [s|s|cell]; try discriminate.
      destruct cell as [i|w]; [discriminate|].
      destruct columns as [|lv columns]; [discriminate|].
      destruct lv as [|l lv]; [discriminate|]. destruct lv; [|discriminate].
      destruct (V.eqb w v); [eapply IH; eassumption|discriminate].
  Qed.

  (** Every variable of a checked function atom has a registered plan name. *)
  Lemma run_check_query_names : forall q newok names n table ai copy used count srcs columns
      post finalcount srcs' columns' expected,
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (finalcount, srcs', columns', expected) -> forall f args res x,
    In (Fun V.t f args res) q -> In (Var x) (args ++ option_list res) ->
    exists j, trie_get x names = Some j.
  Proof.
    induction q as [|a q IH]; intros newok names n table ai copy used count srcs columns
      post finalcount srcs' columns' expected Hcheck f args res x Hin Hvar;
      [contradiction|].
    destruct a as [g ts output|p ts result]; cbn [check_query] in Hcheck.
    - destruct (check_atom V.eqb newok names n table g (ts ++ option_list output)
        copy used count srcs columns)
        as [[[[[[nextcopy nextused] nextcount] nextsrcs] nextcols] copied]|]
        eqn:Hatom; [|discriminate].
      destruct Hin as [Heq|Hin].
      + injection Heq as <- <- <-.
        destruct (run_check_atom_parts newok names n table g (ts ++ option_list output)
          copy used count srcs columns nextcopy nextused nextcount nextsrcs nextcols
          copied Hatom) as [src [src_tail [lv [col_tail [s [inv [perm
          [Hsrcs [Hcols [Hsource [Hcolumn [Hlength [Hterms [Hperm Hslot]]]]]]]]]]]]]].
        destruct (run_check_terms_names (ts ++ option_list output) names 0 Empty copy Empty
          src_tail col_tail false nextcopy inv nextsrcs nextcols copied Hterms x Hvar)
          as [Hempty|Hname].
        * rewrite PTrie.get_empty in Hempty. discriminate.
        * exact Hname.
      + eapply IH; eassumption.
    - destruct Hin as [Heq|Hin]; [discriminate|]. eapply IH; eassumption.
  Qed.

  (** Every listed source rule has a corresponding accepted naive plan. *)
  Lemma run_check_rule_naive_member : forall rs table i nv sn r,
    check_rule_plans V.eqb table rs i nv sn = true -> In r rs ->
    exists c k, In c nv /\ nth_error rs k = Some r /\
      N.to_nat (rule_ix V.t c) = N.to_nat i + k /\
      check_cplan V.eqb false table (rule_ix V.t c) r c = true.
  Proof.
    induction rs as [|[q acts] rs IH]; intros table i nv sn r Hcheck Hin;
      [contradiction|].
    destruct nv as [|c nv]; cbn [check_rule_plans] in Hcheck; [discriminate|].
    destruct (check_cplan V.eqb false table i (Rule V.t q acts) c) eqn:Hplan;
      [|discriminate].
    destruct (check_semis V.eqb table i (Rule V.t q acts) (fun_count q) sn)
      as [tail|] eqn:Hsemi; [|discriminate].
    destruct Hin as [<-|Hin].
    - exists c, 0. split; [now left|]. split; [reflexivity|].
      rewrite (run_check_cplan_index false table i (Rule V.t q acts) c Hplan).
      split; [lia|exact Hplan].
    - destruct (IH table (N.succ i) nv tail r Hcheck Hin)
        as [d [k [Hmember [Hnth [Hindex Haccepted]]]]].
      exists d, (S k). split; [now right|]. split; [exact Hnth|].
      split; [rewrite N2Nat.inj_succ in Hindex; lia|exact Haccepted].
  Qed.

  (** A source rule of a checked program is represented by an accepted naive plan. *)
  Lemma run_rule_naive_member : forall p cp r, plans_ok p cp -> In r (rules V.t p) ->
    exists table c, In c (naive V.t cp) /\
      slot_table (decl_widths (decls V.t p) Empty) (Syntax.slots V.t cp) 0 Empty =
        Some table /\
      nth_error (rules V.t p) (N.to_nat (rule_ix V.t c)) = Some r /\
      check_cplan V.eqb false table (rule_ix V.t c) r c = true.
  Proof.
    intros [ds rs] [sl nv sn] r Hcheck Hin.
    unfold plans_ok, check_plan in Hcheck. apply andb_true_iff in Hcheck.
    destruct Hcheck as [_ Hshape]. unfold check_shape, check_shape_with in Hshape.
    destruct (slot_table (decl_widths ds Empty) sl 0 Empty)
      as [table|] eqn:Htable; [|discriminate].
    rewrite check_rule_plans_at_agrees in Hshape.
    destruct (run_check_rule_naive_member rs table 0 nv sn r Hshape Hin)
      as [c [k [Hmember [Hnth [Hindex Hplan]]]]].
    exists table, c. split; [exact Hmember|]. split; [exact Htable|].
    split; [rewrite Hindex; exact Hnth|exact Hplan].
  Qed.

  (** A total cell reader keeps every environment binding and fills unused names arbitrarily. *)
  Definition run_env_cell (s : Model.env (V := V.t)) (x : positive) : cell V.t :=
    match s x with Some c => c | None => Id 1%positive end.

  (** Distinct literal entries give a partial assignment at their join positions. *)
  Fixpoint run_literal_value (j : nat) (entries : list (nat * cell V.t)) : option (cell V.t) :=
    match entries with
    | [] => None
    | (k, c) :: rest => if Nat.eqb j k then Some c else run_literal_value j rest
    end.

  (** Every value found in the literal assignment comes from its indexed entry. *)
  Lemma run_literal_value_sound : forall entries j c,
    run_literal_value j entries = Some c -> In (j, c) entries.
  Proof.
    induction entries as [|[k d] rest IH]; intros j c Hvalue; cbn [run_literal_value] in Hvalue.
    - discriminate.
    - destruct (Nat.eqb_spec j k) as [Heq|Hneq].
      + subst k. injection Hvalue as <-. now left.
      + right. now apply IH.
  Qed.

  (** A literal entry is found when each index occurs once. *)
  Lemma run_literal_value_complete : forall entries j c,
    NoDup (map fst entries) -> In (j, c) entries -> run_literal_value j entries = Some c.
  Proof.
    induction entries as [|[k d] rest IH]; intros j c Hdistinct Hin; [contradiction|].
    cbn [map] in Hdistinct. inversion Hdistinct as [|? ? Hnot Htail]; subst.
    cbn [run_literal_value]. destruct Hin as [Heq|Hin].
    - injection Heq as <- <-. now rewrite Nat.eqb_refl.
    - destruct (Nat.eqb_spec j k) as [Heq|Hneq].
      + subst k. exfalso. apply Hnot. apply in_map_iff. exists (j, c). split; auto.
      + now apply IH.
  Qed.

  (** Copy indices, literal indices and named real indices receive their matching cells. *)
  Definition run_binding_cell (s : Model.env (V := V.t)) (vars copies : list positive)
      (literals : list (nat * cell V.t)) (j : nat) : cell V.t :=
    if Nat.ltb j (length copies) then run_env_cell s (nth j copies 1%positive)
    else match run_literal_value j literals with
      | Some c => c
      | None => run_env_cell s (nth j vars 1%positive)
      end.

  Definition run_make_binding (s : Model.env (V := V.t)) (vars copies : list positive)
      (literals : list (nat * cell V.t)) : list (cell V.t) :=
    map (run_binding_cell s vars copies literals) (seq 0 (length vars)).

  (** Tabulating the assignment gives its designated cell at every plan index. *)
  Lemma run_make_binding_nth : forall s vars copies literals j,
    j < length vars -> nth_error (run_make_binding s vars copies literals) j =
      Some (run_binding_cell s vars copies literals j).
  Proof.
    intros s vars copies literals j Hbound. unfold run_make_binding.
    rewrite nth_error_map, nth_error_seq.
    assert (Htest : Nat.ltb j (length vars) = true) by (apply Nat.ltb_lt; exact Hbound).
    now rewrite Htest.
  Qed.

  (** A fresh copy prefix cannot contain a real name bounded by the query maximum. *)
  Lemma run_real_after_copies : forall vars bound copies j x,
    Forall (fun y => (bound < y)%positive) (firstn copies vars) ->
    nth_error vars j = Some x -> (x <= bound)%positive -> copies <= j.
  Proof.
    intros vars bound copies j x Hprefix Hnth Hbound.
    destruct (Nat.lt_ge_cases j copies) as [Hbefore|Hafter]; [|exact Hafter].
    assert (Htest : Nat.ltb j copies = true) by (apply Nat.ltb_lt; exact Hbefore).
    assert (Hin : In x (firstn copies vars)).
    { apply nth_error_In with (n := j). now rewrite nth_error_firstn, Htest. }
    apply Forall_forall with (x := x) in Hprefix; [lia|exact Hin].
  Qed.

  (** Every separated layout admits an assignment respecting copies, real names and literals. *)
  Lemma run_make_binding_spec : forall s vars copies literals bound,
    length copies <= length vars ->
    Forall (fun x => (bound < x)%positive) (firstn (length copies) vars) ->
    NoDup (map fst literals) ->
    (forall j c, In (j, c) literals -> exists x,
      length copies <= j /\ nth_error vars j = Some x /\ (bound < x)%positive) ->
    let b := run_make_binding s vars copies literals in
    length b = length vars /\
    (forall j x, nth_error copies j = Some x -> nth_error b j = Some (run_env_cell s x)) /\
    (forall j x, nth_error vars j = Some x -> (x <= bound)%positive ->
      nth_error b j = Some (run_env_cell s x)) /\
    (forall j c, In (j, c) literals -> nth_error b j = Some c).
  Proof.
    intros s vars copies literals bound Hlength Hprefix Hdistinct Hliteral.
    cbn zeta. split.
    - unfold run_make_binding. now rewrite length_map, length_seq.
    - split.
      + intros j x Hnth. assert (Hj : j < length copies).
        { apply nth_error_Some. rewrite Hnth. discriminate. }
        rewrite run_make_binding_nth by lia. unfold run_binding_cell.
        assert (Htest : Nat.ltb j (length copies) = true) by (apply Nat.ltb_lt; exact Hj).
        rewrite Htest. now rewrite (@nth_error_nth positive copies j x 1%positive Hnth).
      + split.
        * intros j x Hnth Hbound. assert (Hj : j < length vars).
          { apply nth_error_Some. rewrite Hnth. discriminate. }
          assert (Hafter : length copies <= j).
          { eapply run_real_after_copies; eassumption. }
          rewrite run_make_binding_nth by exact Hj. unfold run_binding_cell.
          assert (Htest : Nat.ltb j (length copies) = false) by (apply Nat.ltb_ge; exact Hafter).
          rewrite Htest. destruct (run_literal_value j literals) as [c|] eqn:Hvalue.
          -- apply run_literal_value_sound in Hvalue.
             destruct (Hliteral j c Hvalue) as [y [_ [Hy Hfresh]]].
             rewrite Hnth in Hy. injection Hy as <-. lia.
          -- now rewrite (@nth_error_nth positive vars j x 1%positive Hnth).
        * intros j c Hin. destruct (Hliteral j c Hin) as [x [Hafter [Hnth Hfresh]]].
          assert (Hj : j < length vars).
          { apply nth_error_Some. rewrite Hnth. discriminate. }
          rewrite run_make_binding_nth by exact Hj. unfold run_binding_cell.
          assert (Htest : Nat.ltb j (length copies) = false) by (apply Nat.ltb_ge; exact Hafter).
          rewrite Htest, (run_literal_value_complete literals j c Hdistinct Hin). reflexivity.
  Qed.

  (** A source family is satisfied when every projected binding is indexed at that source. *)
  Definition run_sources_satisfied (db : D.t) (b : list (cell V.t))
      (srcs : list (source V.t)) (cols : list (list nat)) : Prop :=
    Forall2 (fun src lv => exists u, J.project lv b = Some u /\
      I.mem (source_index db src) u) srcs cols.

  (** An inverse-table entry points at the same cell in the binding and the atom tuple. *)
  Definition run_inverse_agrees (b tuple : list (cell V.t)) (inv : ptrie nat) : Prop :=
    forall j pos, trie_get (N.succ_pos j) inv = Some pos -> exists c,
      nth_error b (N.to_nat j) = Some c /\ nth_error tuple pos = Some c.

  (** Binary column keys preserve their numeric index. *)
  Lemma run_succ_pos_inj : forall j k, N.succ_pos j = N.succ_pos k -> j = k.
  Proof.
    intros j k Heq. apply N.succ_inj.
    rewrite <- !N.succ_pos_spec. now rewrite Heq.
  Qed.

  (** Adding a correct inverse entry preserves the cell agreement of every entry. *)
  Lemma run_inverse_agrees_set : forall b tuple inv j pos c,
    run_inverse_agrees b tuple inv -> nth_error b (N.to_nat j) = Some c ->
    nth_error tuple pos = Some c ->
    run_inverse_agrees b tuple (PTrieCode.set (N.succ_pos j) pos inv).
  Proof.
    intros b tuple inv j pos c Hinverse Hbinding Htuple k p Hget.
    destruct (Pos.eq_dec (N.succ_pos k) (N.succ_pos j)) as [Heq|Hneq].
    - apply run_succ_pos_inj in Heq. subst k.
      rewrite PTrie.get_set_same in Hget. injection Hget as <-.
      exists c. split; assumption.
    - rewrite PTrie.get_set_other in Hget by exact Hneq. now apply Hinverse.
  Qed.

  (** Pointwise term interpretation records each term at its original tuple position. *)
  Definition run_terms_at (s : Model.env (V := V.t)) (ts : list (term V.t))
      (tuple : list (cell V.t)) (pos : nat) : Prop :=
    forall k t, nth_error ts k = Some t -> exists c,
      nth_error tuple (pos + k) = Some c /\ term_value s t c.

  (** Consuming a term leaves the interpretation of its suffix at the next tuple position. *)
  Lemma run_terms_at_cons : forall s t ts tuple pos,
    run_terms_at s (t :: ts) tuple pos -> exists c,
      nth_error tuple pos = Some c /\ term_value s t c /\
      run_terms_at s ts tuple (S pos).
  Proof.
    intros s t ts tuple pos Hterms.
    destruct (Hterms 0 t eq_refl) as [c [Hnth Hvalue]]. rewrite Nat.add_0_r in Hnth.
    exists c. split; [exact Hnth|]. split; [exact Hvalue|]. intros k u Hterm.
    destruct (Hterms (S k) u Hterm) as [d [Hd Hvalue']]. exists d.
    replace (S pos + k) with (pos + S k) by lia. split; assumption.
  Qed.

  (** A known environment cell is returned by its total reader. *)
  Lemma run_env_cell_some : forall s x c, s x = Some c -> run_env_cell s x = c.
  Proof.
    intros s x c Hvalue. unfold run_env_cell. now rewrite Hvalue.
  Qed.

  (** A binding at a constant column satisfies its singleton source index. *)
  Lemma run_constant_satisfied : forall db b j c,
    nth_error b j = Some c -> exists u, J.project [j] b = Some u /\
      I.mem (source_index db (Const V.t c)) u.
  Proof.
    intros db b j c Hnth. exists [c]. split.
    - cbn [J.project project_cells fold_right]. now rewrite Hnth.
    - unfold source_index. apply (proj2 (I.mem_insert 1 [c] I.empty [c]
        (I.wf_empty 1) eq_refl)). now left.
  Qed.

  (** Checked terms build a correct inverse and consume only satisfied literal sources. *)
  Lemma run_check_terms_answer : forall ts names pos seen copy inv srcs cols copied
      copy' inv' srcs' cols' copied' s b tuple db,
    check_terms V.eqb names ts pos seen copy inv srcs cols copied =
      Some (copy', inv', srcs', cols', copied') ->
    run_terms_at s ts tuple pos ->
    (forall x j, In (Var x) ts -> trie_get x names = Some j ->
      nth_error b (N.to_nat j) = Some (run_env_cell s x)) ->
    (forall k x, nth_error (run_term_duplicates seen ts) k = Some x ->
      nth_error b (N.to_nat copy + k) = Some (run_env_cell s x)) ->
    (forall j c, In (j, c) (run_literal_entries srcs cols) -> nth_error b j = Some c) ->
    run_inverse_agrees b tuple inv ->
    run_inverse_agrees b tuple inv' /\
    copy' = (copy + N.of_nat (length (run_term_duplicates seen ts)))%N /\
    (run_sources_satisfied db b srcs' cols' -> run_sources_satisfied db b srcs cols) /\
    incl (run_literal_entries srcs' cols') (run_literal_entries srcs cols).
  Proof.
    induction ts as [|t rest IH]; intros names pos seen copy inv srcs cols copied
      copy' inv' srcs' cols' copied' s b tuple db Hcheck Hterms Hnames Hcopies Hliterals
      Hinverse; cbn [check_terms] in Hcheck.
    - injection Hcheck as <- <- <- <- <-.
      split; [exact Hinverse|]. split; [now rewrite N.add_0_r|].
      split; [auto|apply incl_refl].
    - destruct (run_terms_at_cons s t rest tuple pos Hterms)
        as [c [Htuple [Hvalue Hrest]]].
      assert (Hnames_rest : forall x j, In (Var x) rest -> trie_get x names = Some j ->
          nth_error b (N.to_nat j) = Some (run_env_cell s x)).
      { intros x j Hin Hget. apply Hnames; [now right|exact Hget]. }
      destruct t as [x|v]; cbn [term_value] in Hvalue.
      + destruct (trie_get x seen) as [u|] eqn:Hseen.
        * cbn [run_term_duplicates] in Hcopies. rewrite Hseen in Hcopies.
          assert (Hcopy : nth_error b (N.to_nat copy) = Some c).
          { pose proof (Hcopies 0 x eq_refl) as Hcell. rewrite Nat.add_0_r in Hcell.
            now rewrite (run_env_cell_some s x c Hvalue) in Hcell. }
          assert (Hcopies_rest : forall k y,
              nth_error (run_term_duplicates seen rest) k = Some y ->
              nth_error b (N.to_nat (N.succ copy) + k) = Some (run_env_cell s y)).
          { intros k y Hnth. rewrite N2Nat.inj_succ.
            replace (S (N.to_nat copy) + k) with (N.to_nat copy + S k) by lia.
            exact (Hcopies (S k) y Hnth). }
          destruct (IH names (S pos) seen (N.succ copy)
            (PTrieCode.set (N.succ_pos copy) pos inv) srcs cols true
            copy' inv' srcs' cols' copied' s b tuple db Hcheck Hrest Hnames_rest
            Hcopies_rest Hliterals (run_inverse_agrees_set b tuple inv copy pos c
              Hinverse Hcopy Htuple)) as [Hinv [Hcount [Hsources Hremain]]].
          split; [exact Hinv|]. split.
          -- cbn [run_term_duplicates]. rewrite Hseen. cbn [length].
             rewrite Nat2N.inj_succ. lia.
          -- split; assumption.
        * destruct (trie_get x names) as [j|] eqn:Hname; [|discriminate].
          assert (Hreal : nth_error b (N.to_nat j) = Some c).
          { pose proof (Hnames x j (or_introl eq_refl) Hname) as Hcell.
            now rewrite (run_env_cell_some s x c Hvalue) in Hcell. }
          cbn [run_term_duplicates] in Hcopies. rewrite Hseen in Hcopies.
          destruct (IH names (S pos) (PTrieCode.set x tt seen) copy
            (PTrieCode.set (N.succ_pos j) pos inv) srcs cols copied
            copy' inv' srcs' cols' copied' s b tuple db Hcheck Hrest Hnames_rest Hcopies
            Hliterals (run_inverse_agrees_set b tuple inv j pos c Hinverse Hreal Htuple))
            as [Hinv [Hcount [Hsources Hremain]]].
          split; [exact Hinv|]. split.
          -- cbn [run_term_duplicates]. rewrite Hseen. exact Hcount.
          -- split; assumption.
      + subst c. destruct srcs as [|[slot|slot|[i|w]] srcs]; try discriminate.
        destruct cols as [|col cols]; [discriminate|].
        destruct col as [|j col]; [discriminate|]. destruct col; [|discriminate].
        destruct (V.eqb_spec w v) as [Heq|Hneq]; [subst w|discriminate].
        assert (Hliteral : nth_error b j = Some (Val v)).
        { apply Hliterals. now left. }
        assert (Hliteral_rest : forall k d,
            In (k, d) (run_literal_entries srcs cols) -> nth_error b k = Some d).
        { intros k d Hin. apply Hliterals. now right. }
        assert (Hliteral_index : nth_error b (N.to_nat (nat_n j)) = Some (Val v)).
        { rewrite planner_nat_n_spec, Nat2N.id. exact Hliteral. }
        destruct (IH names (S pos) seen copy
          (PTrieCode.set (N.succ_pos (nat_n j)) pos inv) srcs cols copied
          copy' inv' srcs' cols' copied' s b tuple db Hcheck Hrest Hnames_rest Hcopies
          Hliteral_rest (run_inverse_agrees_set b tuple inv (nat_n j) pos (Val v)
            Hinverse Hliteral_index Htuple)) as [Hinv [Hcount [Hsources Hremain]]].
        split; [exact Hinv|]. split; [exact Hcount|]. split.
        * intro Htail. constructor; [now apply run_constant_satisfied|now apply Hsources].
        * intros entry Hin. right. now apply Hremain.
  Qed.

  (** Reading a checked inverse projects exactly the slot's tuple permutation. *)
  Lemma run_column_perm_answer : forall lv inv used count perm used' count' b tuple,
    column_perm inv lv used count = Some (perm, used', count') ->
    run_inverse_agrees b tuple inv -> J.project lv b = Some (D.permute perm tuple).
  Proof.
    induction lv as [|j lv IH]; intros inv used count perm used' count' b tuple Hcheck Hinv.
    - cbn [column_perm] in Hcheck. injection Hcheck as <- <- <-. reflexivity.
    - cbn [column_perm] in Hcheck.
      destruct (trie_get (N.succ_pos (nat_n j)) inv) as [pos|] eqn:Hposition;
        [|discriminate].
      destruct (column_perm inv lv (PTrieCode.set (N.succ_pos (nat_n j)) tt used)
        (match trie_get (N.succ_pos (nat_n j)) used with
         | Some _ => count | None => N.succ count end))
        as [[[rest used''] count'']|] eqn:Htail; [|discriminate].
      injection Hcheck as <- <- <-.
      destruct (Hinv (nat_n j) pos Hposition) as [c [Hbinding Htuple]].
      rewrite planner_nat_n_spec, Nat2N.id in Hbinding.
      pose proof (IH _ _ _ _ _ _ _ _ Htail Hinv) as Hproject.
      change (match nth_error b j, J.project lv b with
        | Some d, Some ds => Some (d :: ds) | _, _ => None end =
        Some (option_list (nth_error tuple pos) ++ D.permute rest tuple)).
      rewrite Hbinding, Hproject, Htuple. reflexivity.
  Qed.

  (** Relational term interpretation provides every tuple cell at its corresponding position. *)
  Lemma run_terms_value_at : forall s ts cells,
    terms_value s ts cells -> run_terms_at s ts cells 0.
  Proof.
    intros s ts cells Hvalues. unfold terms_value in Hvalues.
    induction Hvalues as [|t c ts cells Hvalue Hvalues IH]; intros k u Hnth.
    - destruct k; discriminate.
    - destruct k as [|k].
      + cbn [nth_error] in Hnth. injection Hnth as <-. exists c. split; [reflexivity|].
        exact Hvalue.
      + destruct (IH k u Hnth) as [d [Hd Hvalue']]. exists d. split; assumption.
  Qed.

  (** A matching function atom interprets all of its argument and output positions together. *)
  Lemma run_fun_match_tuple : forall db s f args res,
    atom_holds V.prim (D.view db) s (Fun V.t f args res) -> exists k o,
      row (D.view db) f k o /\
      terms_value s (args ++ option_list res) (k ++ option_list o).
  Proof.
    intros db s f args res [k [o [Hargs [Hres Hrow]]]]. exists k, o.
    split; [exact Hrow|]. apply Forall2_app; [exact Hargs|].
    destruct res as [t|], o as [c|]; cbn [option_list] in *; try contradiction.
    - constructor; [exact Hres|constructor].
    - constructor.
  Qed.

  (** An accepted naive atom is satisfied by correct real, copy and literal binding cells. *)
  Lemma run_check_atom_answer : forall db names n table f args res copy used count srcs cols
      copy' used' count' srcs' cols' copied s b,
    D.wf db ->
    check_atom V.eqb false names n table f (args ++ option_list res) copy used count srcs cols =
      Some (copy', used', count', srcs', cols', copied) ->
    atom_holds V.prim (D.view db) s (Fun V.t f args res) ->
    (forall x j, In (Var x) (args ++ option_list res) -> trie_get x names = Some j ->
      nth_error b (N.to_nat j) = Some (run_env_cell s x)) ->
    (forall k x, nth_error (run_term_duplicates Empty (args ++ option_list res)) k = Some x ->
      nth_error b (N.to_nat copy + k) = Some (run_env_cell s x)) ->
    (forall j c, In (j, c) (run_literal_entries srcs cols) -> nth_error b j = Some c) ->
    (forall g perm slot, slot_matches table g perm slot = true ->
      D.slot_of db slot = Some (g, perm)) ->
    copy' = (copy + N.of_nat
      (length (run_term_duplicates Empty (args ++ option_list res))))%N /\
    incl (run_literal_entries srcs' cols') (run_literal_entries srcs cols) /\
    (run_sources_satisfied db b srcs' cols' -> run_sources_satisfied db b srcs cols).
  Proof.
    intros db names n table f args res copy used count srcs cols copy' used' count'
      srcs' cols' copied s b Hwf Hcheck Hmatch Hnames Hcopies Hliterals Hslots.
    destruct (run_fun_match_tuple db s f args res Hmatch) as [k [o [Hrow Hvalues]]].
    unfold check_atom in Hcheck.
    destruct srcs as [|src srcs]; [discriminate|].
    destruct cols as [|col cols]; [discriminate|].
    destruct src as [slot|slot|cell]; cbn [source_slot] in Hcheck; try discriminate.
    destruct (column_ok n col None) eqn:Hcol; [|discriminate].
    destruct (Nat.eqb (length col) (length (args ++ option_list res))) eqn:Hlength;
      [|discriminate].
    destruct (check_terms V.eqb names (args ++ option_list res) 0 Empty copy Empty
      srcs cols false) as [[[[[next inv] remainingSrc] remainingCols] flag]|] eqn:Hterms;
      [|discriminate].
    destruct (column_perm inv col used count) as [[[perm seen] total]|] eqn:Hperm;
      [|discriminate].
    destruct (slot_matches table f perm slot) eqn:Hslot; [|discriminate].
    injection Hcheck as <- <- <- <- <- <-.
    assert (Hempty : run_inverse_agrees b (k ++ option_list o) Empty).
    { intros j pos Hget. rewrite PTrie.get_empty in Hget. discriminate. }
    destruct (run_check_terms_answer (args ++ option_list res) names 0 Empty copy Empty
      srcs cols false next inv remainingSrc remainingCols flag s b (k ++ option_list o) db
      Hterms (run_terms_value_at s _ _ Hvalues) Hnames Hcopies Hliterals Hempty)
      as [Hinverse [Hcount [Hsources Hremain]]].
    split; [exact Hcount|]. split; [exact Hremain|]. intro Htail. constructor.
    - exists (D.permute perm (k ++ option_list o)). split.
      + eapply run_column_perm_answer; eassumption.
      + unfold source_index. eapply D.index_all_complete; [exact Hwf| |exact Hrow].
        now apply Hslots.
    - now apply Hsources.
  Qed.

  (** Checking a naive query preserves satisfaction when its binding agrees with each term. *)
  Lemma run_check_query_answer : forall q db names n table ai copy used count srcs cols post
      count' srcs' cols' post' s b,
    D.wf db ->
    check_query V.eqb false names n table q ai copy used count srcs cols post =
      Some (count', srcs', cols', post') ->
    matches V.prim (D.view db) q s ->
    (forall x j, In (Var x) (flat_map atom_terms q) -> trie_get x names = Some j ->
      nth_error b (N.to_nat j) = Some (run_env_cell s x)) ->
    (forall k x, nth_error (run_query_duplicates q) k = Some x ->
      nth_error b (N.to_nat copy + k) = Some (run_env_cell s x)) ->
    (forall j c, In (j, c) (run_literal_entries srcs cols) -> nth_error b j = Some c) ->
    (forall g perm slot, slot_matches table g perm slot = true ->
      D.slot_of db slot = Some (g, perm)) ->
    incl (run_literal_entries srcs' cols') (run_literal_entries srcs cols) /\
    (run_sources_satisfied db b srcs' cols' -> run_sources_satisfied db b srcs cols).
  Proof.
    induction q as [|a rest IH]; intros db names n table ai copy used count srcs cols post
      count' srcs' cols' post' s b Hwf Hcheck Hmatches Hnames Hcopies Hliterals Hslots.
    - cbn [check_query] in Hcheck. injection Hcheck as <- <- <- <-. split; [apply incl_refl|auto].
    - inversion Hmatches as [|a' rest' Hhead Htail]; subst a' rest'.
      assert (Hnames_rest : forall x j, In (Var x) (flat_map atom_terms rest) ->
          trie_get x names = Some j ->
          nth_error b (N.to_nat j) = Some (run_env_cell s x)).
      { intros x j Hin Hget. apply Hnames; [|exact Hget].
        cbn [flat_map]. apply in_or_app. now right. }
      destruct a as [f args res|p args res]; cbn [check_query] in Hcheck.
      + destruct (check_atom V.eqb false names n table f (args ++ option_list res)
          copy used count srcs cols) as [[[[[[next seen] total] remainingSrc]
          remainingCols] copied]|] eqn:Hatom; [|discriminate].
        assert (Hatom_names : forall x j, In (Var x) (args ++ option_list res) ->
            trie_get x names = Some j ->
            nth_error b (N.to_nat j) = Some (run_env_cell s x)).
        { intros x j Hin Hget. apply Hnames; [|exact Hget].
          cbn [flat_map atom_terms]. apply in_or_app. now left. }
        assert (Hatom_copies : forall k x,
            nth_error (run_term_duplicates Empty (args ++ option_list res)) k = Some x ->
            nth_error b (N.to_nat copy + k) = Some (run_env_cell s x)).
        { intros k x Hnth. apply Hcopies. cbn [run_query_duplicates].
          rewrite nth_error_app1; [exact Hnth|].
          apply nth_error_Some. rewrite Hnth. discriminate. }
        destruct (run_check_atom_answer db names n table f args res copy used count srcs cols
          next seen total remainingSrc remainingCols copied s b Hwf Hatom Hhead Hatom_names
          Hatom_copies Hliterals Hslots) as [Hnext [Hremain Hatom_answer]].
        assert (Hcopies_rest : forall k x, nth_error (run_query_duplicates rest) k = Some x ->
            nth_error b (N.to_nat next + k) = Some (run_env_cell s x)).
        { intros k x Hnth. rewrite Hnext, N2Nat.inj_add, Nat2N.id.
          replace (N.to_nat copy + length (run_term_duplicates Empty
              (args ++ option_list res)) + k) with
            (N.to_nat copy + (length (run_term_duplicates Empty
              (args ++ option_list res)) + k)) by lia.
          apply Hcopies. cbn [run_query_duplicates]. rewrite nth_error_app2 by lia.
          replace (length (run_term_duplicates Empty (args ++ option_list res)) + k -
            length (run_term_duplicates Empty (args ++ option_list res))) with k by lia.
          exact Hnth. }
        assert (Hliterals_rest : forall j c,
            In (j, c) (run_literal_entries remainingSrc remainingCols) ->
            nth_error b j = Some c).
        { intros j c Hin. apply Hliterals. now apply Hremain. }
        destruct (IH db names n table (S ai) next seen total remainingSrc remainingCols
          (if copied then ai :: post else post) count' srcs' cols' post' s b Hwf Hcheck
          Htail Hnames_rest Hcopies_rest Hliterals_rest Hslots) as [Hremaining Hanswer].
        split.
        * intros entry Hin. apply Hremain. now apply Hremaining.
        * intro Hfinal. apply Hatom_answer. now apply Hanswer.
      + exact (IH db names n table (S ai) copy used count srcs cols (ai :: post)
          count' srcs' cols' post' s b Hwf Hcheck Htail Hnames_rest Hcopies Hliterals Hslots).
  Qed.

  (** Satisfied source projections are exactly the join answer obligations in source order. *)
  Lemma run_sources_join_answer : forall db b j srcs,
    length b = nvars j -> run_sources_satisfied db b srcs (cols j) ->
    J.answer j (map (source_index db) srcs) b.
  Proof.
    intros db b j srcs Hlength Hsources. split; [exact Hlength|].
    induction Hsources; cbn [map]; [constructor|]. constructor; assumption.
  Qed.

  (** Binding a distinct variable list reads each name at its unique list position. *)
  Lemma run_binding_env_position : forall vars (cells : list (cell V.t)) j x,
    NoDup vars -> nth_error vars j = Some x ->
    binding_env vars cells x = nth_error cells j.
  Proof.
    induction vars as [|y vars IH]; intros cells j x Hdistinct Hnth;
      [destruct j; discriminate|].
    inversion Hdistinct as [|? ? Hnot Htail]; subst.
    destruct cells as [|c cells]; [destruct j; reflexivity|].
    destruct j as [|j].
    - cbn [nth_error] in Hnth. injection Hnth as <-. cbn [binding_env].
      now rewrite Pos.eqb_refl.
    - cbn [binding_env nth_error]. destruct (Pos.eqb_spec x y) as [Heq|Hneq].
      + subst x. exfalso. apply Hnot. now apply nth_error_In with (n := j).
      + now apply IH.
  Qed.

  (** The trie of a binding has exactly the list binding's environment. *)
  Lemma run_binding_trie_get : forall vars (b : list (cell V.t)) x,
    trie_get x (bind_cells vars b Empty) = binding_env vars b x.
  Proof.
    intros vars b x. rewrite bind_cells_get, PTrie.get_empty. reflexivity.
  Qed.

  (** Query variable membership is equivalent to a variable term occurrence. *)
  Lemma run_query_vars_member : forall (q : list (atom V.t)) x,
    In x (flat_map atom_vars q) <-> In (Var x) (flat_map atom_terms q).
  Proof.
    induction q as [|a q IH]; intro x; cbn [flat_map]; [tauto|].
    rewrite !in_app_iff, run_atom_vars_terms, run_term_vars_member, IH. reflexivity.
  Qed.

  (** Every variable occurrence in an interpreted term list has an environment value. *)
  Lemma run_terms_variable_bound : forall (s : Model.env (V := V.t)) ts cs,
    terms_value s ts cs -> forall x, In (Var x) ts -> exists c, s x = Some c.
  Proof.
    intros s ts cs Hterms. induction Hterms as [|t c ts cs Hvalue Hterms IH];
      intros x Hin; [contradiction|].
    destruct Hin as [Heq|Hin].
    - subst t. exists c. exact Hvalue.
    - now apply IH.
  Qed.

  (** Every variable of a true query atom has an environment value. *)
  Lemma run_atom_variable_bound : forall w s a,
    atom_holds V.prim w s a -> forall x, In (Var x) (atom_terms a) ->
    exists c, s x = Some c.
  Proof.
    intros w s [f args res|p args res] Hatom x Hin; cbn [atom_terms] in Hin;
      apply in_app_iff in Hin.
    - destruct Hatom as [k [o [Hargs [Hres Hrow]]]]. destruct Hin as [Hin|Hin].
      + eapply run_terms_variable_bound; eassumption.
      + destruct res as [t|]; [|contradiction]. cbn [option_list In] in Hin.
        destruct Hin as [Heq|[]]. subst t. destruct o as [c|]; [|contradiction].
        exists c. exact Hres.
    - destruct Hatom as [k [vs [v [Hargs [Hvalues [Hprim Hres]]]]]].
      destruct Hin as [Hin|Hin].
      + eapply run_terms_variable_bound; eassumption.
      + cbn [In] in Hin. destruct Hin as [Heq|[]]. subst res. exists (Val v). exact Hres.
  Qed.

  (** Every variable of a query match has an environment value. *)
  Lemma run_match_variable_bound : forall w s q,
    matches V.prim w q s -> forall x, In (Var x) (flat_map atom_terms q) ->
    exists c, s x = Some c.
  Proof.
    intros w s q Hmatch x Hin. apply in_flat_map in Hin as [a [Ha Hvar]].
    apply Forall_forall with (x := a) in Hmatch; [|exact Ha].
    eapply run_atom_variable_bound; eassumption.
  Qed.

  (** Duplicate variables are occurrences in the term list that produced them. *)
  Lemma run_term_duplicates_member : forall ts seen x,
    In x (run_term_duplicates seen ts) -> In (Var x) ts.
  Proof.
    induction ts as [|[y|v] ts IH]; intros seen x Hin; cbn [run_term_duplicates] in Hin;
      [contradiction| |].
    - destruct (trie_get y seen).
      + destruct Hin as [<-|Hin]; [now left|]. right. now apply IH with (seen := seen).
      + right. now apply IH with (seen := PTrieCode.set y tt seen).
    - right. now apply IH with (seen := seen).
  Qed.

  (** Every copy names a real variable occurring in its source query. *)
  Lemma run_query_duplicates_member : forall q x,
    In x (run_query_duplicates q) -> In (Var x) (flat_map atom_terms q).
  Proof.
    induction q as [|[f args res|p args res] q IH]; intros x Hin;
      cbn [run_query_duplicates] in Hin; [contradiction| |]; cbn [flat_map atom_terms].
    - apply in_app_iff in Hin. apply in_or_app. destruct Hin as [Hin|Hin].
      + left. now apply run_term_duplicates_member with (seen := Empty).
      + right. now apply IH.
    - apply in_or_app. right. now apply IH.
  Qed.

  (** Correctness at the real-name positions recovers the original matching environment. *)
  Lemma run_binding_agrees : forall w q s vars names b,
    matches V.prim w q s -> var_table vars 0 Empty = Some names ->
    (forall x, In (Var x) (flat_map atom_terms q) -> exists j, trie_get x names = Some j) ->
    (forall j x, nth_error vars j = Some x -> (x <= query_max q 1%positive)%positive ->
      nth_error b j = Some (run_env_cell s x)) ->
    forall x, In (Var x) (flat_map atom_terms q) -> binding_env vars b x = s x.
  Proof.
    intros w q s vars names b Hmatches Htable Hregistered Hreal x Hin.
    destruct (run_var_table_spec vars names Htable) as [Hdistinct Hindices].
    destruct (Hregistered x Hin) as [j Hget]. apply Hindices in Hget.
    rewrite (run_binding_env_position vars b (N.to_nat j) x Hdistinct Hget).
    rewrite (Hreal (N.to_nat j) x Hget (planner_query_max_member q 1%positive x Hin)).
    destruct (run_match_variable_bound w s q Hmatches x Hin) as [c Hvalue].
    rewrite (run_env_cell_some s x c Hvalue), Hvalue. reflexivity.
  Qed.

  (** Corresponding positions determine a list relation when its lengths agree. *)
  Lemma run_Forall2_positions : forall A B (P : A -> B -> Prop) xs ys,
    length xs = length ys ->
    (forall j x y, nth_error xs j = Some x -> nth_error ys j = Some y -> P x y) ->
    Forall2 P xs ys.
  Proof.
    intros A B P xs. induction xs as [|x xs IH]; intros [|y ys] Hlength Hpositions;
      try discriminate; [constructor|].
    constructor.
    - exact (Hpositions 0 x y eq_refl eq_refl).
    - apply IH; [cbn in Hlength; lia|]. intros j a b Ha Hb.
      exact (Hpositions (S j) a b Ha Hb).
  Qed.

  (** Correct copy cells and real cells make every copy-prefix comparison succeed. *)
  Lemma run_binding_copy_cells : forall w q s vars b,
    matches V.prim w q s -> NoDup vars -> query_copies q 0 <= length vars ->
    (forall x, In (Var x) (flat_map atom_terms q) -> binding_env vars b x = s x) ->
    (forall j x, nth_error (run_query_duplicates q) j = Some x ->
      nth_error b j = Some (run_env_cell s x)) ->
    Forall2 (fun z x => exists c,
      trie_get z (bind_cells vars b Empty) = Some c /\
      trie_get x (bind_cells vars b Empty) = Some c)
      (firstn (query_copies q 0) vars) (run_query_duplicates q).
  Proof.
    intros w q s vars b Hmatches Hdistinct Hlength Hagree Hcopies.
    apply run_Forall2_positions.
    - rewrite firstn_length_le by exact Hlength. rewrite run_query_duplicates_count. lia.
    - intros j z x Hz Hx. assert (Hj : j < query_copies q 0).
      { assert (Hbound : j < length (firstn (query_copies q 0) vars)).
        { apply nth_error_Some. rewrite Hz. discriminate. }
        rewrite firstn_length_le in Hbound by exact Hlength. exact Hbound. }
      assert (Htest : Nat.ltb j (query_copies q 0) = true) by (apply Nat.ltb_lt; exact Hj).
      rewrite nth_error_firstn, Htest in Hz.
      assert (Hin : In (Var x) (flat_map atom_terms q)).
      { apply run_query_duplicates_member. now apply nth_error_In with (n := j). }
      destruct (run_match_variable_bound w s q Hmatches x Hin) as [c Hvalue].
      exists c. rewrite !run_binding_trie_get. split.
      + rewrite (run_binding_env_position vars b j z Hdistinct Hz), (Hcopies j x Hx).
        now rewrite (run_env_cell_some s x c Hvalue).
      + rewrite (Hagree x Hin). exact Hvalue.
  Qed.

  (** Changing an environment on absent variables preserves interpreted terms. *)
  Lemma run_terms_value_agree : forall (s : Model.env (V := V.t)) t ts cs,
    terms_value s ts cs ->
    (forall x, In (Var x) ts -> t x = s x) -> terms_value t ts cs.
  Proof.
    intros s t ts cs Hvalues. induction Hvalues as [|term c ts cs Hterm Hvalues IH];
      intro Hagree; [constructor|].
    constructor.
    - destruct term as [x|v]; cbn [term_value] in *; [|exact Hterm].
      rewrite (Hagree x (or_introl eq_refl)). exact Hterm.
    - apply IH. intros x Hin. apply Hagree. now right.
  Qed.

  (** A primitive atom remains true when the trie agrees on all of its variables. *)
  Lemma run_primitive_agree : forall w s t p args res,
    atom_holds V.prim w s (Prim V.t p args res) ->
    (forall x, In (Var x) (args ++ [res]) -> trie_get x t = s x) ->
    prim_holds V.prim V.eqb t p args res = true.
  Proof.
    intros w s t p args res [cs [vs [v [Hargs [Hvalues [Hprim Hres]]]]]] Hagree.
    apply (proj2 (run_prim_holds_spec w t p args res)).
    exists cs, vs, v. split.
    - eapply run_terms_value_agree; [exact Hargs|]. intros x Hin.
      apply Hagree. apply in_or_app. now left.
    - split; [exact Hvalues|]. split; [exact Hprim|].
      destruct res as [x|value]; cbn [term_value] in *; [|exact Hres].
      rewrite (Hagree x); [exact Hres|]. apply in_or_app. right. now left.
  Qed.

  (** A matching environment recovered by a binding passes all primitive post checks. *)
  Lemma run_binding_primitive_checks : forall w q s vars b,
    matches V.prim w q s ->
    (forall x, In (Var x) (flat_map atom_terms q) -> binding_env vars b x = s x) ->
    Forall (fun a => match a with
      | Prim _ p args res => prim_holds V.prim V.eqb (bind_cells vars b Empty) p args res = true
      | Fun _ _ _ _ => True
      end) q.
  Proof.
    intros w q s vars b Hmatches Hagree. apply Forall_forall. intros a Hin.
    apply Forall_forall with (x := a) in Hmatches; [|exact Hin].
    destruct a as [f args res|p args res]; [exact I|].
    eapply run_primitive_agree; [exact Hmatches|]. intros x Hvar.
    rewrite run_binding_trie_get. apply Hagree. apply in_flat_map.
    exists (Prim V.t p args res). split; assumption.
  Qed.

  (** Every accepted layout admits cells for its copies, real variables and literal sources. *)
  Lemma run_layout_assignment : forall q vars srcs columns s,
    layout_ok q vars srcs columns = true ->
    let b := run_make_binding s vars (run_query_duplicates q)
      (run_literal_entries srcs columns) in
    length b = length vars /\
    (forall j x, nth_error (run_query_duplicates q) j = Some x ->
      nth_error b j = Some (run_env_cell s x)) /\
    (forall j x, nth_error vars j = Some x -> (x <= query_max q 1%positive)%positive ->
      nth_error b j = Some (run_env_cell s x)) /\
    (forall j c, In (j, c) (run_literal_entries srcs columns) -> nth_error b j = Some c).
  Proof.
    intros q vars srcs columns s Hlayout.
    destruct (run_layout_ok_sound q vars srcs columns Hlayout)
      as [Hlength [Hprefix [Hdistinct Hliteral]]].
    assert (Hcopies : length (run_query_duplicates q) = query_copies q 0).
    { rewrite run_query_duplicates_count. lia. }
    apply (run_make_binding_spec s vars (run_query_duplicates q)
      (run_literal_entries srcs columns) (query_max q 1%positive)).
    - now rewrite Hcopies.
    - now rewrite Hcopies.
    - exact Hdistinct.
    - intros j c Hin. destruct (Hliteral j c Hin) as [x [Hafter [Hnth Hfresh]]].
      exists x. rewrite Hcopies. repeat split; assumption.
  Qed.

  (** A scan step adds only its current position to the possible inverse-table values. *)
  Lemma run_inverse_origin_step : forall inv result key pos len,
    (forall k value, trie_get k result = Some value ->
      trie_get k (PTrieCode.set key pos inv) = Some value \/
        S pos <= value < S pos + len) ->
    forall k value, trie_get k result = Some value ->
      trie_get k inv = Some value \/ pos <= value < pos + S len.
  Proof.
    intros inv result key pos len Hlater k value Hget.
    destruct (Hlater k value Hget) as [Hset|Hrange]; [|right; lia].
    destruct (Pos.eq_dec k key) as [Heq|Hneq].
    - subst k. rewrite PTrie.get_set_same in Hset. injection Hset as <-. right. lia.
    - left. rewrite PTrie.get_set_other in Hset by exact Hneq. exact Hset.
  Qed.

  (** Every inverse entry comes from the initial table or a position actually scanned. *)
  Lemma run_check_terms_origin : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') -> forall key value,
    trie_get key inv' = Some value ->
      trie_get key inv = Some value \/ pos <= value < pos + length ts.
  Proof.
    induction ts as [|t ts IH]; intros names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' Hscan.
    - cbn [check_terms] in Hscan. inversion Hscan; subst. intros key value Hget. now left.
    - destruct t as [x|v]; cbn [check_terms] in Hscan; cbn [length].
      + destruct (trie_get x seen).
        * eapply run_inverse_origin_step. intros key value Hget. eapply IH; eassumption.
        * destruct (trie_get x names); [|discriminate].
          eapply run_inverse_origin_step. intros key value Hget. eapply IH; eassumption.
      + destruct srcs as [|[slot|slot|[i|w]] srcs]; try discriminate.
        destruct columns as [|[|j [|k column]] columns]; try discriminate.
        destruct (V.eqb w v); [|discriminate].
        eapply run_inverse_origin_step. intros key value Hget. eapply IH; eassumption.
  Qed.

  (** Scanning later positions cannot create a new entry at an earlier position. *)
  Lemma run_check_terms_before : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') -> forall key value,
    value < pos -> trie_get key inv' = Some value -> trie_get key inv = Some value.
  Proof.
    intros ts names pos seen copy inv srcs columns copied copy' inv' srcs' columns' copied'
      Hscan key value Hbefore Hget.
    destruct (run_check_terms_origin ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' Hscan key value Hget) as [Hold|Hrange];
      [exact Hold|lia].
  Qed.

  (** Inserting the current position preserves strict bounds for the next scan position. *)
  Lemma run_inverse_before_set : forall inv key pos,
    (forall k value, trie_get k inv = Some value -> value < pos) ->
    forall k value, trie_get k (PTrieCode.set key pos inv) = Some value -> value < S pos.
  Proof.
    intros inv key pos Hbefore k value Hget.
    destruct (Pos.eq_dec k key) as [Heq|Hneq].
    - subst k. rewrite PTrie.get_set_same in Hget. injection Hget as <-. lia.
    - rewrite PTrie.get_set_other in Hget by exact Hneq.
      specialize (Hbefore k value Hget). lia.
  Qed.

  (** Every tuple position is witnessed by an inverse entry reading that binding cell. *)
  Definition run_inverse_positions (b cells : list (cell V.t)) (inv : ptrie nat)
      (pos : nat) : Prop :=
    forall k c, nth_error cells k = Some c -> exists j,
      trie_get (N.succ_pos j) inv = Some (pos + k) /\
      nth_error b (N.to_nat j) = Some c.

  (** Removing a tuple head advances the position witnessed by its inverse. *)
  Lemma run_inverse_positions_tail : forall b c cells inv pos,
    run_inverse_positions b (c :: cells) inv pos ->
    run_inverse_positions b cells inv (S pos).
  Proof.
    intros b c cells inv pos Hpositions k d Hnth.
    destruct (Hpositions (S k) d Hnth) as [j [Hget Hbinding]].
    exists j. split; [|exact Hbinding].
    replace (S pos + k) with (pos + S k) by lia. exact Hget.
  Qed.

  (** A witnessed head position must read the key assigned at that scan step. *)
  Lemma run_check_terms_head_cell : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' idx b c cells,
    check_terms V.eqb names ts (S pos) seen copy
      (PTrieCode.set (N.succ_pos idx) pos inv) srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    (forall key value, trie_get key inv = Some value -> value < pos) ->
    run_inverse_positions b (c :: cells) inv' pos -> nth_error b (N.to_nat idx) = Some c.
  Proof.
    intros ts names pos seen copy inv srcs columns copied copy' inv' srcs' columns' copied'
      idx b c cells Hscan Hbefore Hpositions.
    destruct (Hpositions 0 c eq_refl) as [j [Hget Hbinding]]. rewrite Nat.add_0_r in Hget.
    pose proof (run_check_terms_before ts names (S pos) seen copy
      (PTrieCode.set (N.succ_pos idx) pos inv) srcs columns copied
      copy' inv' srcs' columns' copied' Hscan (N.succ_pos j) pos ltac:(lia) Hget) as Hset.
    assert (Hkey : N.succ_pos j = N.succ_pos idx).
    { destruct (Pos.eq_dec (N.succ_pos j) (N.succ_pos idx)) as [Heq|Hneq]; [exact Heq|].
      rewrite PTrie.get_set_other in Hset by exact Hneq.
      specialize (Hbefore (N.succ_pos j) pos Hset). lia. }
    apply run_succ_pos_inj in Hkey. now subst j.
  Qed.

  (** A successful term scan advances its copy counter by exactly its repeated variables. *)
  Lemma run_check_terms_count : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    copy' = (copy + N.of_nat (length (run_term_duplicates seen ts)))%N.
  Proof.
    induction ts as [|[x|v] ts IH]; intros names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' Hscan; cbn [check_terms] in Hscan.
    - inversion Hscan; subst. now rewrite N.add_0_r.
    - cbn [run_term_duplicates]. destruct (trie_get x seen) eqn:Hseen.
      + pose proof (IH names (S pos) seen (N.succ copy)
          (PTrieCode.set (N.succ_pos copy) pos inv) srcs columns true
          copy' inv' srcs' columns' copied' Hscan) as Hcount.
        cbn [length]. rewrite Nat2N.inj_succ. lia.
      + destruct (trie_get x names); [eapply IH; exact Hscan|discriminate].
    - destruct srcs as [|[slot|slot|[i|w]] srcs]; try discriminate.
      destruct columns as [|[|j [|k column]] columns]; try discriminate.
      destruct (V.eqb w v); [eapply IH; exact Hscan|discriminate].
  Qed.

  (** A distinct bounded permutation of full length visits every position. *)
  Lemma run_perm_covers : forall perm width,
    NoDup perm -> Forall (fun p => p < width) perm -> length perm = width ->
    forall p, p < width -> In p perm.
  Proof.
    intros perm width Hnodup Hfits Hlength.
    assert (Hsubset : incl perm (seq 0 width)).
    { intros p Hin. apply in_seq. split; [lia|].
      now apply Forall_forall with (x := p) in Hfits. }
    assert (Hcover : incl (seq 0 width) perm).
    { apply NoDup_length_incl; [exact Hnodup| |exact Hsubset].
      rewrite length_seq, Hlength. lia. }
    intros p Hbound. apply Hcover. apply in_seq. lia.
  Qed.

  (** Equal full projections pair the selected binding and tuple cells. *)
  Lemma run_project_permute_cells : forall perm lv b cells,
    length lv = length perm -> Forall (fun pos => pos < length cells) perm ->
    J.project lv b = Some (D.permute perm cells) ->
    Forall2 (fun j pos => exists c,
      nth_error b j = Some c /\ nth_error cells pos = Some c) lv perm.
  Proof.
    induction perm as [|pos perm IH]; intros [|j lv] b cells Hlength Hfits Hproject;
      cbn [length] in Hlength; try discriminate; [constructor|].
    inversion Hfits as [|p ps Hbound Htail]; subst p ps.
    assert (Hexists : nth_error cells pos <> None) by (now apply nth_error_Some).
    destruct (nth_error cells pos) as [c|] eqn:Hcell; [|contradiction].
    change (match nth_error b j, J.project lv b with
      | Some d, Some ds => Some (d :: ds) | _, _ => None end =
      Some (option_list (nth_error cells pos) ++ D.permute perm cells)) in Hproject.
    rewrite Hcell in Hproject. cbn [option_list app] in Hproject.
    destruct (nth_error b j) as [d|] eqn:Hbinding; [|discriminate].
    destruct (J.project lv b) as [ds|] eqn:Hrest; [|discriminate].
    injection Hproject as Heq Hds. subst d ds. constructor.
    - exists c. split; assumption.
    - apply IH; [lia|exact Htail|exact Hrest].
  Qed.

  (** A listed permutation position has its recorded inverse key and tuple cell. *)
  Lemma run_column_position : forall lv perm inv (b : list (cell V.t)) cells,
    Forall2 (fun j pos => trie_get (N.succ_pos (nat_n j)) inv = Some pos) lv perm ->
    Forall2 (fun j pos => exists c,
      nth_error b j = Some c /\ nth_error cells pos = Some c) lv perm ->
    forall pos c, In pos perm -> nth_error cells pos = Some c -> exists j,
      trie_get (N.succ_pos (nat_n j)) inv = Some pos /\ nth_error b j = Some c.
  Proof.
    intros lv perm inv b cells Hlookups.
    induction Hlookups as [|j p lv perm Hlookup Htail IH];
      intros Hvalues pos c Hin Hcell; [contradiction|].
    inversion Hvalues as [|j' p' lv' perm' Hvalue Hrest]; subst j' p' lv' perm'.
    destruct Hin as [Heq|Hin].
    - subst pos. destruct Hvalue as [d [Hbinding Hd]]. rewrite Hcell in Hd.
      injection Hd as <-. exists j. split; assumption.
    - eapply IH; eassumption.
  Qed.

  (** A complete checked permutation witnesses every original tuple position in its inverse. *)
  Lemma run_column_inverse_positions : forall lv inv used count perm used' count' b cells,
    column_perm inv lv used count = Some (perm, used', count') -> NoDup perm ->
    length cells = length lv ->
    (forall j pos, trie_get (N.succ_pos j) inv = Some pos -> pos < length cells) ->
    J.project lv b = Some (D.permute perm cells) -> run_inverse_positions b cells inv 0.
  Proof.
    intros lv inv used count perm used' count' b cells Hscan Hnodup Hlength Hrange Hproject.
    destruct (run_column_perm_sound lv inv used count perm used' count' Hscan)
      as [Hperm_length [Hlookups _]].
    assert (Hfits : Forall (fun pos => pos < length cells) perm).
    { clear -Hlookups Hrange.
      induction Hlookups as [|j pos lv perm Hlookup Htail IH].
      - constructor.
      - constructor; [eapply Hrange; exact Hlookup|exact IH]. }
    pose proof (run_project_permute_cells perm lv b cells ltac:(lia) Hfits Hproject)
      as Hvalues.
    intros pos c Hcell.
    assert (Hbound : pos < length cells).
    { apply nth_error_Some. rewrite Hcell. discriminate. }
    assert (Hin : In pos perm).
    { apply (run_perm_covers perm (length cells) Hnodup Hfits); lia. }
    destruct (run_column_position lv perm inv b cells Hlookups Hvalues pos c Hin Hcell)
      as [j [Hget Hbinding]].
    exists (nat_n j). split; [exact Hget|].
    now rewrite planner_nat_n_spec, Nat2N.id.
  Qed.


  (** Binding two argument segments composes their successive contexts. *)
  Lemma run_binds_list_app : forall g (args : list (term V.t)) ss g1,
    binds_list g args ss g1 -> forall rest tt g2,
    binds_list g1 rest tt g2 -> binds_list g (args ++ rest) (ss ++ tt) g2.
  Proof.
    intros g args ss g1 Hargs. induction Hargs as [g|g h g1 t ts ty tys Ht Hts IH];
      intros rest tt g2 Hrest; cbn [app].
    - exact Hrest.
    - econstructor; [exact Ht|now apply IH].
  Qed.

  (** Binding a typed optional result is binding its optional output-cell list. *)
  Lemma run_binds_result_list : forall g out (res : option (term V.t)) g'
      (o : option (cell V.t)),
    binds_result g out res g' -> option_map cell_sort o = out_sort out ->
    binds_list g (option_list res) (map cell_sort (option_list o)) g'.
  Proof.
    intros g out res g' o Hresult Hsort.
    destruct out as [| |m]; destruct res as [t|]; destruct o as [c|];
      cbn [binds_result out_sort option_map] in Hresult, Hsort;
      try contradiction; try discriminate.
    - subst g'. constructor.
    - injection Hsort as Hsort. cbn [option_list map]. rewrite Hsort.
      econstructor; [exact Hresult|constructor].
    - injection Hsort as Hsort. cbn [option_list map]. rewrite Hsort.
      econstructor; [exact Hresult|constructor].
  Qed.

  (** Function arguments and result bind exactly the row's concatenated cell sorts. *)
  Lemma run_binds_atom_row : forall g (args : list (term V.t)) ss g1 out res g2
      (k : list (cell V.t)) o,
    binds_list g args ss g1 -> binds_result g1 out res g2 ->
    map cell_sort k = ss -> option_map cell_sort o = out_sort out ->
    binds_list g (args ++ option_list res) (map cell_sort (k ++ option_list o)) g2.
  Proof.
    intros g args ss g1 out res g2 k o Hargs Hresult Hsort Hout.
    rewrite map_app, Hsort. eapply run_binds_list_app; [exact Hargs|].
    eapply run_binds_result_list; eassumption.
  Qed.

  (** A bound argument list and a row with its declared sorts have equal lengths. *)
  Lemma run_binds_row_length : forall g (args : list (term V.t)) ss g' (k : list (cell V.t)),
    binds_list g args ss g' -> map cell_sort k = ss -> length args = length k.
  Proof.
    intros g args ss g' k Hargs Hsort.
    pose proof (planner_binds_length _ _ _ _ Hargs) as Hlength.
    rewrite <- Hsort, length_map in Hlength. exact Hlength.
  Qed.

  (** A successful constant-source projection fixes its one binding cell. *)
  Lemma run_constant_source_cell : forall db b v j srcs columns,
    run_sources_satisfied db b (Const V.t (Val v) :: srcs) ([j] :: columns) ->
    nth_error b j = Some (Val v) /\ run_sources_satisfied db b srcs columns.
  Proof.
    intros db b v j srcs columns Hsources.
    inversion Hsources as [|src col rest cols Hhead Htail]; subst src col rest cols.
    destruct Hhead as [u [Hproject Hmem]].
    apply (proj1 (I.mem_insert 1 [Val v] I.empty u (I.wf_empty 1) eq_refl)) in Hmem.
    destruct Hmem as [Heq|Hempty]; [subst u|exfalso; exact (I.mem_empty u Hempty)].
    cbn [J.project project_cells fold_right] in Hproject.
    destruct (nth_error b j) as [c|] eqn:Hcell; [|discriminate].
    injection Hproject as <-. split; [reflexivity|exact Htail].
  Qed.

  (** Checked names read existing binding cells through the binding environment. *)
  Lemma run_checked_names_cells : forall vars names (b : list (cell V.t)),
    var_table vars 0 Empty = Some names -> length b = length vars ->
    forall x j, trie_get x names = Some j -> exists c,
      nth_error b (N.to_nat j) = Some c /\ binding_env vars b x = Some c.
  Proof.
    intros vars names b Htable Hlength x j Hget.
    destruct (run_var_table_spec vars names Htable) as [Hnodup Hindices].
    apply Hindices in Hget.
    assert (Hbound : N.to_nat j < length b).
    { rewrite Hlength. apply nth_error_Some. rewrite Hget. discriminate. }
    assert (Hexists : nth_error b (N.to_nat j) <> None) by (now apply nth_error_Some).
    destruct (nth_error b (N.to_nat j)) as [c|] eqn:Hcell; [|contradiction].
    exists c. split; [reflexivity|].
    rewrite (run_binding_env_position vars b (N.to_nat j) x Hnodup Hget). exact Hcell.
  Qed.

  (** A relation on two lists supplies the paired element at any right-hand position. *)
  Lemma run_Forall2_nth_right : forall A B (R : A -> B -> Prop) xs ys,
    Forall2 R xs ys -> forall j y, nth_error ys j = Some y ->
    exists x, nth_error xs j = Some x /\ R x y.
  Proof.
    intros A B R xs ys Hrelated.
    induction Hrelated as [|x y xs ys Hhead Htail IH]; intros [|j] z Hnth;
      try discriminate.
    - injection Hnth as <-. exists x. split; [reflexivity|exact Hhead].
    - apply IH. exact Hnth.
  Qed.

  (** Successful copy comparisons identify each copy-position cell with its variable. *)
  Lemma run_binding_copies_sound : forall vars (b : list (cell V.t)) copies,
    NoDup vars ->
    Forall2 (fun z x => exists c,
      trie_get z (bind_cells vars b Empty) = Some c /\
      trie_get x (bind_cells vars b Empty) = Some c)
      (firstn (length copies) vars) copies ->
    forall j x, nth_error copies j = Some x -> exists c,
      nth_error b j = Some c /\ binding_env vars b x = Some c.
  Proof.
    intros vars b copies Hnodup Hcopies j x Hnth.
    destruct (run_Forall2_nth_right _ _ _ _ _ Hcopies j x Hnth)
      as [z [Hz [c [Hzcell Hxcell]]]].
    assert (Hbound : j < length copies).
    { apply nth_error_Some. rewrite Hnth. discriminate. }
    assert (Htest : Nat.ltb j (length copies) = true) by (now apply Nat.ltb_lt).
    rewrite nth_error_firstn, Htest in Hz.
    rewrite !run_binding_trie_get in Hzcell, Hxcell.
    exists c. split; [|exact Hxcell].
    rewrite (run_binding_env_position vars b j z Hnodup Hz) in Hzcell. exact Hzcell.
  Qed.

  (** Complete inverse positions and checked copies interpret every scanned term. *)
  Lemma run_check_terms_values : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' s b cells db,
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    length ts = length cells ->
    (forall key value, trie_get key inv = Some value -> value < pos) ->
    run_inverse_positions b cells inv' pos ->
    (forall x j, trie_get x names = Some j -> exists c,
      nth_error b (N.to_nat j) = Some c /\ s x = Some c) ->
    (forall k x, nth_error (run_term_duplicates seen ts) k = Some x -> exists c,
      nth_error b (N.to_nat copy + k) = Some c /\ s x = Some c) ->
    run_sources_satisfied db b srcs columns ->
    terms_value s ts cells /\ run_sources_satisfied db b srcs' columns'.
  Proof.
    induction ts as [|t ts IH]; intros names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' s b cells db Hscan Hlength Hbefore Hpositions
      Hnames Hcopies Hsources.
    - destruct cells; [|discriminate]. cbn [check_terms] in Hscan.
      inversion Hscan; subst. split; [constructor|exact Hsources].
    - destruct cells as [|c cells]; [discriminate|].
      assert (Hrest_length : length ts = length cells) by (cbn in Hlength; lia).
      pose proof (run_inverse_positions_tail b c cells inv' pos Hpositions) as Hrest_positions.
      destruct t as [x|v]; cbn [check_terms] in Hscan.
      + destruct (trie_get x seen) eqn:Hseen.
        * pose proof (run_check_terms_head_cell ts names pos seen (N.succ copy) inv
            srcs columns true copy' inv' srcs' columns' copied' copy b c cells
            Hscan Hbefore Hpositions) as Hcell.
          cbn [run_term_duplicates] in Hcopies. rewrite Hseen in Hcopies.
          destruct (Hcopies 0 x eq_refl) as [d [Hd Hvalue]]. rewrite Nat.add_0_r in Hd.
          rewrite Hcell in Hd. injection Hd as <-.
          assert (Hrest_copies : forall k y,
              nth_error (run_term_duplicates seen ts) k = Some y -> exists d,
              nth_error b (N.to_nat (N.succ copy) + k) = Some d /\ s y = Some d).
          { intros k y Hnth. rewrite N2Nat.inj_succ.
            replace (S (N.to_nat copy) + k) with (N.to_nat copy + S k) by lia.
            exact (Hcopies (S k) y Hnth). }
          destruct (IH names (S pos) seen (N.succ copy)
            (PTrieCode.set (N.succ_pos copy) pos inv) srcs columns true
            copy' inv' srcs' columns' copied' s b cells db Hscan Hrest_length
            (run_inverse_before_set inv (N.succ_pos copy) pos Hbefore)
            Hrest_positions Hnames Hrest_copies Hsources) as [Hvalues Hremaining].
          split; [constructor; [exact Hvalue|exact Hvalues]|exact Hremaining].
        * destruct (trie_get x names) as [j|] eqn:Hname; [|discriminate].
          pose proof (run_check_terms_head_cell ts names pos (PTrieCode.set x tt seen)
            copy inv srcs columns copied copy' inv' srcs' columns' copied' j b c cells
            Hscan Hbefore Hpositions) as Hcell.
          destruct (Hnames x j Hname) as [d [Hd Hvalue]]. rewrite Hcell in Hd.
          injection Hd as <-. cbn [run_term_duplicates] in Hcopies. rewrite Hseen in Hcopies.
          destruct (IH names (S pos) (PTrieCode.set x tt seen) copy
            (PTrieCode.set (N.succ_pos j) pos inv) srcs columns copied
            copy' inv' srcs' columns' copied' s b cells db Hscan Hrest_length
            (run_inverse_before_set inv (N.succ_pos j) pos Hbefore)
            Hrest_positions Hnames Hcopies Hsources) as [Hvalues Hremaining].
          split; [constructor; [exact Hvalue|exact Hvalues]|exact Hremaining].
      + destruct srcs as [|[slot|slot|[i|w]] srcs]; try discriminate.
        destruct columns as [|[|j [|k column]] columns]; try discriminate.
        destruct (V.eqb_spec w v) as [Heq|Hneq]; [subst w|discriminate].
        pose proof (run_check_terms_head_cell ts names pos seen copy inv srcs columns
          copied copy' inv' srcs' columns' copied' (nat_n j) b c cells
          Hscan Hbefore Hpositions) as Hcell.
        rewrite planner_nat_n_spec, Nat2N.id in Hcell.
        destruct (run_constant_source_cell db b v j srcs columns Hsources)
          as [Hliteral Htail].
        rewrite Hliteral in Hcell. injection Hcell as <-.
        destruct (IH names (S pos) seen copy
          (PTrieCode.set (N.succ_pos (nat_n j)) pos inv) srcs columns copied
          copy' inv' srcs' columns' copied' s b cells db Hscan Hrest_length
          (run_inverse_before_set inv (N.succ_pos (nat_n j)) pos Hbefore)
          Hrest_positions Hnames Hcopies Htail) as [Hvalues Hremaining].
        split; [constructor; [reflexivity|exact Hvalues]|exact Hremaining].
  Qed.


  (** Matching a slot from a successful table gives a distinct permutation. *)
  Lemma run_slot_matches_nodup : forall widths sl table f perm slot,
    slot_table widths sl 0 Empty = Some table -> slot_matches table f perm slot = true ->
    NoDup perm.
  Proof.
    intros widths sl table f perm slot Htable Hmatch.
    pose proof (run_slot_matches_index widths sl table f perm slot Htable Hmatch) as Hnth.
    apply nth_error_In in Hnth.
    destruct (slot_table_member sl widths 0 Empty table f perm Htable Hnth)
      as [width [_ Hperm]].
    exact (proj1 (perm_ok_sound perm width Empty Hperm)).
  Qed.

  (** An indexed tuple at a known slot comes from a row of exactly that slot's function. *)
  Lemma run_index_row : forall db slot new f perm tuple,
    D.wf db -> D.slot_of db slot = Some (f, perm) ->
    I.mem (D.index slot new db) tuple -> exists k o,
      row (D.view db) f k o /\ tuple = D.permute perm (k ++ option_list o).
  Proof.
    intros db slot new f perm tuple Hwf Hslot Hmem.
    destruct (D.index_all db slot new tuple Hwf Hmem)
      as [g [other [k [o [Hfound [Hrow Htuple]]]]]].
    rewrite Hslot in Hfound. injection Hfound as <- <-. exists k, o. split; assumption.
  Qed.

  (** An accepted slot source returns a row projected through its checked permutation. *)
  Lemma run_source_row : forall db widths sl table newok src slot f perm tuple,
    D.wf db -> D.slots db = sl -> slot_table widths sl 0 Empty = Some table ->
    source_slot newok src = Some slot -> slot_matches table f perm slot = true ->
    I.mem (source_index db src) tuple -> exists k o,
      row (D.view db) f k o /\ tuple = D.permute perm (k ++ option_list o).
  Proof.
    intros db widths sl table newok src slot f perm tuple Hwf Hslots Htable Hsource Hmatch
      Hmem.
    assert (Hslot : D.slot_of db slot = Some (f, perm)).
    { unfold D.slot_of. rewrite Hslots.
      exact (run_slot_matches_index widths sl table f perm slot Htable Hmatch). }
    destruct src as [s|s|c]; cbn [source_slot source_index] in *; try discriminate.
    - injection Hsource as <-. eapply run_index_row; eassumption.
    - destruct newok; [|discriminate]. injection Hsource as <-.
      eapply run_index_row; eassumption.
  Qed.

  (** A loaded row has precisely the argument and output sorts selected by its program. *)
  Lemma run_loaded_row_sorts : forall p cp db f ss kindout k o,
    loaded p cp db -> program_sorts p f = Some ss -> program_kind p f = Some kindout ->
    row (D.view db) f k o -> map cell_sort k = ss /\ option_map cell_sort o = out_sort kindout.
  Proof.
    intros p cp db f ss kindout k o [Hkinds [_ Hsorted]] Hsort Hkind Hrow.
    destruct (Hsorted f k o Hrow) as [out [Hargs [Hout Hresult]]].
    rewrite Hkinds, Hkind in Hout. injection Hout as <-.
    split; [congruence|exact Hresult].
  Qed.

  (** The typing of a function atom binds exactly the cells and sorts of any loaded row. *)
  Lemma run_atom_row_bindings : forall p cp db f (args : list (term V.t)) res
      g g1 g2 ss kindout k o,
    loaded p cp db -> program_sorts p f = Some ss -> program_kind p f = Some kindout ->
    binds_list g args ss g1 -> binds_result g1 kindout res g2 -> row (D.view db) f k o ->
    binds_list g (args ++ option_list res) (map cell_sort (k ++ option_list o)) g2 /\
    length args = length k /\ length (args ++ option_list res) = length (k ++ option_list o).
  Proof.
    intros p cp db f args res g g1 g2 ss kindout k o Hloaded Hsort Hkind Hargs Hres Hrow.
    destruct (run_loaded_row_sorts p cp db f ss kindout k o Hloaded Hsort Hkind Hrow)
      as [Harg_sorts Hout_sort].
    pose proof (run_binds_atom_row g args ss g1 kindout res g2 k o Hargs Hres
      Harg_sorts Hout_sort) as Hbinds.
    split; [exact Hbinds|]. split.
    - exact (run_binds_row_length g args ss g1 k Hargs Harg_sorts).
    - pose proof (planner_binds_length _ _ _ _ Hbinds) as Hlength.
      now rewrite length_map in Hlength.
  Qed.

  (** An accepted atom exposes its row and witnesses every term's original tuple position. *)
  Lemma run_check_atom_tuple : forall db widths sl table newok names n f ts copy used count
      srcs columns copy' used' count' srcs' columns' copied b,
    D.wf db -> D.slots db = sl -> slot_table widths sl 0 Empty = Some table ->
    check_atom V.eqb newok names n table f ts copy used count srcs columns =
      Some (copy', used', count', srcs', columns', copied) ->
    run_sources_satisfied db b srcs columns ->
    (forall k o, row (D.view db) f k o -> length (k ++ option_list o) = length ts) ->
    exists k o inv before_srcs before_cols,
      row (D.view db) f k o /\
      check_terms V.eqb names ts 0 Empty copy Empty before_srcs before_cols false =
        Some (copy', inv, srcs', columns', copied) /\
      run_inverse_positions b (k ++ option_list o) inv 0 /\
      length ts = length (k ++ option_list o) /\
      run_sources_satisfied db b before_srcs before_cols.
  Proof.
    intros db widths sl table newok names n f ts copy used count srcs columns copy' used'
      count' srcs' columns' copied b Hwf Hslots Htable Hcheck Hsources Hwidth.
    destruct (run_check_atom_parts newok names n table f ts copy used count srcs columns
      copy' used' count' srcs' columns' copied Hcheck)
      as [src [src_tail [lv [col_tail [slot [inv [perm
        [Hsrcs [Hcols [Hsource [Hcolumn [Hlength [Hterms [Hperm Hmatch]]]]]]]]]]]]]].
    subst srcs columns.
    inversion Hsources as [|src' lv' src_tail' col_tail' Hhead Htail];
      subst src' lv' src_tail' col_tail'.
    destruct Hhead as [tuple [Hproject Hmem]].
    destruct (run_source_row db widths sl table newok src slot f perm tuple Hwf Hslots
      Htable Hsource Hmatch Hmem) as [k [o [Hrow Htuple]]].
    subst tuple.
    pose proof (Hwidth k o Hrow) as Hrow_length.
    assert (Hrange : forall j pos,
        trie_get (N.succ_pos j) inv = Some pos -> pos < length (k ++ option_list o)).
    { intros j pos Hget.
      destruct (run_check_terms_origin ts names 0 Empty copy Empty src_tail col_tail false
        copy' inv srcs' columns' copied Hterms (N.succ_pos j) pos Hget)
        as [Hempty|Hbound].
      - rewrite PTrie.get_empty in Hempty. discriminate.
      - rewrite Hrow_length. lia. }
    exists k, o, inv, src_tail, col_tail. split; [exact Hrow|]. split; [exact Hterms|].
    split.
    - eapply run_column_inverse_positions; [exact Hperm| |lia|exact Hrange|exact Hproject].
      exact (run_slot_matches_nodup widths sl table f perm slot Htable Hmatch).
    - split; [symmetry; exact Hrow_length|exact Htail].
  Qed.


  (** Binding a term preserves every previously bound context entry. *)
  Lemma run_binds_preserves : forall g (term : term V.t) ty g',
    binds g term ty g' -> forall x other, g x = Some other -> g' x = Some other.
  Proof.
    intros g term ty g' Hbind. destruct Hbind as [y ty Hget|y ty Hnone|v];
      intros x other Hold; try exact Hold.
    unfold ctx_set. destruct (Pos.eqb_spec y x) as [Heq|Hneq]; [subst x; congruence|].
    exact Hold.
  Qed.

  (** A bound variable is present in the resulting context at the requested sort. *)
  Lemma run_binds_var_bound : forall g x ty g',
    @binds V.t g (Var x) ty g' -> g' x = Some ty.
  Proof.
    intros g x ty g' Hbind. inversion Hbind; subst.
    - assumption.
    - unfold ctx_set. now rewrite Pos.eqb_refl.
  Qed.

  (** A term binding keeps an already sorted environment when its new cell has that sort. *)
  Lemma run_binds_env_value : forall g (term : term V.t) ty g' s c,
    binds g term ty g' -> env_sorted g s -> term_value s term c -> cell_sort c = ty ->
    env_sorted g' s.
  Proof.
    intros g term ty g' s c Hbind Henv Hvalue Hsort.
    destruct Hbind as [x ty Hget|x ty Hnone|v]; try exact Henv.
    intros y other Hctx. unfold ctx_set in Hctx.
    destruct (Pos.eqb_spec x y) as [Heq|Hneq].
    - subst y. injection Hctx as <-. exists c. split; assumption.
    - now apply Henv.
  Qed.

  (** A repeated variable cannot allocate a new context entry. *)
  Lemma run_binds_env_existing : forall g x ty g' (s : Model.env (V := V.t)),
    @binds V.t g (Var x) ty g' -> (exists other, g x = Some other) -> env_sorted g s ->
    env_sorted g' s.
  Proof.
    intros g x ty g' s Hbind [other Hbound] Henv. inversion Hbind; subst.
    - exact Henv.
    - congruence.
  Qed.

  (** A complete checked inverse gives a sorted environment for all newly bound term names. *)
  Lemma run_check_terms_sorted : forall ts cells g g' names pos seen copy inv srcs columns
      copied copy' inv' srcs' columns' copied' b s,
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    binds_list g ts (map cell_sort cells) g' ->
    (forall key value, trie_get key inv = Some value -> value < pos) ->
    run_inverse_positions b cells inv' pos ->
    (forall x j, trie_get x names = Some j -> exists c,
      nth_error b (N.to_nat j) = Some c /\ s x = Some c) ->
    (forall x, trie_get x seen = Some tt -> exists ty, g x = Some ty) ->
    env_sorted g s -> env_sorted g' s.
  Proof.
    induction ts as [|term rest IH]; intros cells g g' names pos seen copy inv srcs columns
      copied copy' inv' srcs' columns' copied' b s Hcheck Hbinds Hbefore Hpositions Hnames
      Hseen Henv.
    - inversion Hbinds; subst. exact Henv.
    - destruct cells as [|c cells]; [inversion Hbinds|].
      inversion Hbinds as [|g0 middle g2 term' rest' ty types Hhead Htail];
        subst g0 g2 term' rest' ty types.
      assert (Hseen_keep : forall x, trie_get x seen = Some tt ->
          exists ty, middle x = Some ty).
      { intros x Hget. destruct (Hseen x Hget) as [ty Hbound]. exists ty.
        eapply run_binds_preserves; eassumption. }
      pose proof (run_inverse_positions_tail b c cells inv' pos Hpositions) as Hpositions_tail.
      destruct term as [x|v]; cbn [check_terms] in Hcheck.
      + destruct (trie_get x seen) as [[]|] eqn:Hget.
        * eapply (IH cells middle g' names (S pos) seen (N.succ copy)
            (PTrieCode.set (N.succ_pos copy) pos inv) srcs columns true
            copy' inv' srcs' columns' copied' b s Hcheck Htail).
          -- now apply run_inverse_before_set.
          -- exact Hpositions_tail.
          -- exact Hnames.
          -- exact Hseen_keep.
          -- eapply run_binds_env_existing; [exact Hhead|now apply Hseen|exact Henv].
        * destruct (trie_get x names) as [j|] eqn:Hname; [|discriminate].
          pose proof (run_check_terms_head_cell rest names pos (PTrieCode.set x tt seen)
            copy inv srcs columns copied copy' inv' srcs' columns' copied' j b c cells
            Hcheck Hbefore Hpositions) as Hcell.
          destruct (Hnames x j Hname) as [d [Hbinding Hvalue]].
          rewrite Hcell in Hbinding. injection Hbinding as <-.
          eapply (IH cells middle g' names (S pos) (PTrieCode.set x tt seen) copy
            (PTrieCode.set (N.succ_pos j) pos inv) srcs columns copied
            copy' inv' srcs' columns' copied' b s Hcheck Htail).
          -- now apply run_inverse_before_set.
          -- exact Hpositions_tail.
          -- exact Hnames.
          -- intros y Hlookup. destruct (Pos.eq_dec y x) as [Heq|Hneq].
             ++ subst y. exists (cell_sort c). now apply run_binds_var_bound with (g := g).
             ++ rewrite PTrie.get_set_other in Hlookup by exact Hneq. now apply Hseen_keep.
          -- eapply run_binds_env_value; [exact Hhead|exact Henv|exact Hvalue|reflexivity].
      + destruct srcs as [|[slot|slot|[i|w]] srcs]; try discriminate.
        destruct columns as [|[|j [|k column]] columns]; try discriminate.
        destruct (V.eqb w v); [|discriminate].
        eapply (IH cells middle g' names (S pos) seen copy
          (PTrieCode.set (N.succ_pos (nat_n j)) pos inv) srcs columns copied
          copy' inv' srcs' columns' copied' b s Hcheck Htail).
        * now apply run_inverse_before_set.
        * exact Hpositions_tail.
        * exact Hnames.
        * exact Hseen_keep.
        * inversion Hhead; subst. exact Henv.
  Qed.

  (** Removing the literal prefix consumed by a term check preserves source satisfaction. *)
  Lemma run_check_terms_satisfied_tail : forall ts names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' db b,
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    run_sources_satisfied db b srcs columns -> run_sources_satisfied db b srcs' columns'.
  Proof.
    induction ts as [|[x|v] rest IH]; intros names pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied' db b Hcheck Hsources;
      cbn [check_terms] in Hcheck.
    - injection Hcheck as <- <- <- <- <-. exact Hsources.
    - destruct (trie_get x seen).
      + eapply IH; eassumption.
      + destruct (trie_get x names); [eapply IH; eassumption|discriminate].
    - destruct srcs as [|[slot|slot|[i|w]] srcs]; try discriminate.
      destruct columns as [|[|j [|k column]] columns]; try discriminate.
      destruct (V.eqb w v); [|discriminate].
      inversion Hsources as [|src lv restSrc restCols Hhead Htail]; subst.
      eapply IH; eassumption.
  Qed.

  (** A join answer satisfies the original sources paired with their columns. *)
  Lemma run_join_answer_sources : forall db b j srcs,
    J.answer j (map (source_index db) srcs) b ->
    run_sources_satisfied db b srcs (cols j).
  Proof.
    intros db b [n columns] srcs [_ Hanswer]. cbn [cols] in *.
    revert columns Hanswer. induction srcs as [|src srcs IH]; intros [|lv columns] Hanswer;
      inversion Hanswer as [|lv' ix columns' indexes Hhead Htail]; subst; [constructor|].
    constructor; [exact Hhead|now apply IH].
  Qed.

  (** Raw checked query bindings type every context produced by the query's function atoms. *)
  Lemma run_check_query_sorted : forall p cp db table,
    D.wf db -> loaded p cp db ->
    slot_table (decl_widths (decls V.t p) Empty) (Syntax.slots V.t cp) 0 Empty = Some table ->
    forall g q g', query_ok (program_sorts p) (program_kind p) g q g' ->
    forall newok names n ai copy used count srcs columns post
      finalcount srcs' columns' expected b s,
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (finalcount, srcs', columns', expected) ->
    run_sources_satisfied db b srcs columns ->
    (forall x j, trie_get x names = Some j -> exists c,
      nth_error b (N.to_nat j) = Some c /\ s x = Some c) ->
    env_sorted g s -> env_sorted g' s.
  Proof.
    intros p cp db table Hwf Hloaded Htable g q g' Htyped.
    induction Htyped as [g|g g1 g2 g3 f args res ss out rest Hsort Hkind Hread Hargs Hres
      Htyped IH|g g1 primitive args res rest Hargs Hres Htyped IH];
      intros newok names n ai copy used count srcs columns post finalcount srcs' columns'
      expected b s Hcheck Hsources Hnames Henv.
    - exact Henv.
    - cbn [check_query] in Hcheck.
      destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
        copy used count srcs columns) as [[[[[[nextcopy nextused] nextcount]
        nextsrcs] nextcols] copied]|] eqn:Hatom; [|discriminate].
      assert (Hwidth : forall k o, row (D.view db) f k o ->
          length (k ++ option_list o) = length (args ++ option_list res)).
      { intros k o Hrow.
        destruct (run_atom_row_bindings p cp db f args res g g1 g2 ss out k o
          Hloaded Hsort Hkind Hargs Hres Hrow) as [_ [_ Hlength]]. now symmetry. }
      destruct (run_check_atom_tuple db (decl_widths (decls V.t p) Empty)
        (Syntax.slots V.t cp) table newok names n f (args ++ option_list res)
        copy used count srcs columns nextcopy nextused nextcount nextsrcs nextcols copied b
        Hwf (proj1 (proj2 Hloaded)) Htable Hatom Hsources Hwidth)
        as [k [o [inv [before_srcs [before_cols [Hrow [Hterms [Hpositions
          [Hlength Hbefore]]]]]]]]].
      destruct (run_atom_row_bindings p cp db f args res g g1 g2 ss out k o
        Hloaded Hsort Hkind Hargs Hres Hrow) as [Hbinds _].
      assert (Hsorted : env_sorted g2 s).
      { eapply (run_check_terms_sorted (args ++ option_list res) (k ++ option_list o)
          g g2 names 0 Empty copy Empty before_srcs before_cols false nextcopy inv
          nextsrcs nextcols copied b s Hterms Hbinds).
        - intros key value Hget. rewrite PTrie.get_empty in Hget. discriminate.
        - exact Hpositions.
        - exact Hnames.
        - intros x Hget. rewrite PTrie.get_empty in Hget. discriminate.
        - exact Henv. }
      assert (Hremaining : run_sources_satisfied db b nextsrcs nextcols).
      { eapply run_check_terms_satisfied_tail; eassumption. }
      exact (IH newok names n (S ai) nextcopy nextused nextcount nextsrcs nextcols
        (if copied then ai :: post else post) finalcount srcs' columns' expected b s
        Hcheck Hremaining Hnames Hsorted).
    - exact (IH newok names n (S ai) copy used count srcs columns (ai :: post)
        finalcount srcs' columns' expected b s Hcheck Hsources Hnames Henv).
  Qed.

  (** Equal prefix lengths split pointwise interpretation at the same list boundary. *)
  Lemma run_terms_value_append_inv : forall (args : list (term V.t)) tail k output s,
    length args = length k -> terms_value s (args ++ tail) (k ++ output) ->
    terms_value s args k /\ terms_value s tail output.
  Proof.
    induction args as [|t args IH]; intros tail [|c k] output s Hlength Hvalues;
      cbn [length] in Hlength; try discriminate.
    - split; [constructor|exact Hvalues].
    - inversion Hvalues as [|t' c' ts cs Hhead Htail]; subst t' c' ts cs.
      destruct (IH tail k output s ltac:(lia) Htail) as [Hargs Houtput].
      split; [constructor; assumption|exact Houtput].
  Qed.

  (** A row whose concatenated positions interpret the terms satisfies its function atom. *)
  Lemma run_fun_from_values : forall w s f args res k o,
    length args = length k ->
    terms_value s (args ++ option_list res) (k ++ option_list o) ->
    row w f k o -> atom_holds V.prim w s (Fun V.t f args res).
  Proof.
    intros w s f args res k o Hlength Hvalues Hrow.
    destruct (run_terms_value_append_inv args (option_list res) k (option_list o) s
      Hlength Hvalues) as [Hargs Hresult].
    exists k, o. split; [exact Hargs|]. split; [|exact Hrow].
    destruct res as [t|], o as [c|]; cbn [option_list] in Hresult.
    - inversion Hresult as [|t' c' ts cs Hvalue Hnil]; subst. exact Hvalue.
    - inversion Hresult.
    - inversion Hresult.
    - exact I.
  Qed.

  (** A true primitive post check holds in any pointwise identical binding environment. *)
  Lemma run_primitive_check_sound : forall w t p args res s,
    prim_holds V.prim V.eqb t p args res = true ->
    (forall x, s x = trie_get x t) -> atom_holds V.prim w s (Prim V.t p args res).
  Proof.
    intros w t p args res s Hcheck Henv.
    destruct (proj1 (run_prim_holds_spec w t p args res) Hcheck)
      as [cells [values [v [Hargs [Hvalues [Hprim Hres]]]]]].
    exists cells, values, v. split.
    - eapply run_terms_value_agree; [exact Hargs|]. intros x _. apply Henv.
    - split; [exact Hvalues|]. split; [exact Hprim|].
      destruct res as [x|value]; cbn [term_value] in *; [|exact Hres].
      rewrite Henv. exact Hres.
  Qed.

  (** A well-sorted checked query interprets each matched row after its copy comparisons. *)
  Lemma run_check_query_values : forall p cp db q g g',
    query_ok (program_sorts p) (program_kind p) g q g' ->
    forall table newok names n ai copy used count srcs columns post finalcount srcs'
      columns' expected s b,
    D.wf db -> loaded p cp db ->
    slot_table (decl_widths (decls V.t p) Empty) (Syntax.slots V.t cp) 0 Empty = Some table ->
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (finalcount, srcs', columns', expected) ->
    (forall x j, trie_get x names = Some j -> exists c,
      nth_error b (N.to_nat j) = Some c /\ s x = Some c) ->
    (forall k x, nth_error (run_query_duplicates q) k = Some x -> exists c,
      nth_error b (N.to_nat copy + k) = Some c /\ s x = Some c) ->
    run_sources_satisfied db b srcs columns ->
    Forall (fun a => match a with
      | Prim _ _ _ _ => atom_holds V.prim (D.view db) s a | Fun _ _ _ _ => True end) q ->
    matches V.prim (D.view db) q s /\ run_sources_satisfied db b srcs' columns'.
  Proof.
    intros p cp db q g g' Htyped.
    induction Htyped as [g|g g1 g2 g3 f args res ss kindout rest Hsort Hkind Hreads
      Hargs Hres Hrest IH|g g1 prim args res rest Hargs Hres Hrest IH];
      intros table newok names n ai copy used count srcs columns post finalcount srcs'
      columns' expected s b Hwf Hloaded Htable Hcheck Hnames Hcopies Hsources Hprimitives.
    - cbn [check_query] in Hcheck. inversion Hcheck; subst.
      split; [constructor|exact Hsources].
    - cbn [check_query] in Hcheck.
      destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
        copy used count srcs columns)
        as [[[[[[nextcopy nextused] nextcount] nextsrcs] nextcols] copied]|]
        eqn:Hatom; [|discriminate].
      assert (Hwidth : forall k o, row (D.view db) f k o ->
          length (k ++ option_list o) = length (args ++ option_list res)).
      { intros k o Hrow. destruct (run_atom_row_bindings p cp db f args res g g1 g2 ss
          kindout k o Hloaded Hsort Hkind Hargs Hres Hrow) as [_ [_ Hlength]].
        symmetry. exact Hlength. }
      destruct (run_check_atom_tuple db (decl_widths (decls V.t p) Empty)
        (Syntax.slots V.t cp) table newok names n f (args ++ option_list res)
        copy used count srcs columns nextcopy nextused nextcount nextsrcs nextcols copied b
        Hwf (proj1 (proj2 Hloaded)) Htable Hatom Hsources Hwidth)
        as [k [o [inv [before_srcs [before_cols
          [Hrow [Hterms [Hpositions [Hlength Hbefore_sources]]]]]]]]].
      assert (Hatom_copies : forall j x,
          nth_error (run_term_duplicates Empty (args ++ option_list res)) j = Some x ->
          exists c, nth_error b (N.to_nat copy + j) = Some c /\ s x = Some c).
      { intros j x Hnth. apply Hcopies. cbn [run_query_duplicates].
        rewrite nth_error_app1; [exact Hnth|].
        apply nth_error_Some. rewrite Hnth. discriminate. }
      destruct (run_check_terms_values (args ++ option_list res) names 0 Empty copy Empty
        before_srcs before_cols false nextcopy inv nextsrcs nextcols copied s b
        (k ++ option_list o) db Hterms Hlength)
        as [Hvalues Hremaining].
      + intros key value Hempty. rewrite PTrie.get_empty in Hempty. discriminate.
      + exact Hpositions.
      + exact Hnames.
      + exact Hatom_copies.
      + exact Hbefore_sources.
      + pose proof (run_check_terms_count (args ++ option_list res) names 0 Empty copy Empty
          before_srcs before_cols false nextcopy inv nextsrcs nextcols copied Hterms)
          as Hnextcopy.
        assert (Hrest_copies : forall j x, nth_error (run_query_duplicates rest) j = Some x ->
            exists c, nth_error b (N.to_nat nextcopy + j) = Some c /\ s x = Some c).
        { intros j x Hnth. rewrite Hnextcopy, N2Nat.inj_add, Nat2N.id.
          replace (N.to_nat copy + length (run_term_duplicates Empty
              (args ++ option_list res)) + j) with
            (N.to_nat copy + (length (run_term_duplicates Empty
              (args ++ option_list res)) + j)) by lia.
          apply Hcopies. cbn [run_query_duplicates]. rewrite nth_error_app2 by lia.
          replace (length (run_term_duplicates Empty (args ++ option_list res)) + j -
            length (run_term_duplicates Empty (args ++ option_list res))) with j by lia.
          exact Hnth. }
        inversion Hprimitives as [|a rest' Hprimitive Hprimitive_tail]; subst a rest'.
        destruct (IH table newok names n (S ai) nextcopy nextused nextcount nextsrcs nextcols
          (if copied then ai :: post else post) finalcount srcs' columns' expected s b
          Hwf Hloaded Htable Hcheck Hnames Hrest_copies Hremaining Hprimitive_tail)
          as [Hmatches Hsources_final].
        split; [|exact Hsources_final]. constructor; [|exact Hmatches].
        destruct (run_atom_row_bindings p cp db f args res g g1 g2 ss kindout k o Hloaded
          Hsort Hkind Hargs Hres Hrow) as [_ [Hargs_length _]].
        exact (run_fun_from_values (D.view db) s f args res k o Hargs_length Hvalues Hrow).
    - cbn [check_query] in Hcheck.
      inversion Hprimitives as [|a rest' Hprimitive Hprimitive_tail]; subst a rest'.
      destruct (IH table newok names n (S ai) copy used count srcs columns (ai :: post)
        finalcount srcs' columns' expected s b Hwf Hloaded Htable Hcheck Hnames Hcopies
        Hsources Hprimitive_tail) as [Hmatches Hsources_final].
      split; [constructor; assumption|exact Hsources_final].
  Qed.

  Lemma plan_match_sound : forall p cp db c b r, plans_ok p cp -> D.wf db ->
    loaded p cp db -> In c (all_plans cp) ->
    nth_error (rules V.t p) (N.to_nat (rule_ix V.t c)) = Some r ->
    In b (bindings cp c db) -> keep p c (bind_trie c b) = true ->
    matches V.prim (D.view db) (query V.t r) (env_of c b).
  Proof.
    intros p cp db c b [q acts] Hplan Hwf Hloaded Hin Hrule Hbinding Hkeep.
    pose proof (plans_ok_sorted p cp Hplan) as Hprogram. unfold program_ok in Hprogram.
    apply Forall_forall with (x := Rule V.t q acts) in Hprogram;
      [|now apply nth_error_In in Hrule].
    destruct Hprogram as [g [Htyped Hactions]].
    destruct (run_plan_member p cp c Hplan Hin)
      as [table [newok [r [Htable [Hfound Hcheck]]]]].
    rewrite Hrule in Hfound. injection Hfound as <-.
    destruct (run_check_cplan_parts newok table (rule_ix V.t c) (Rule V.t q acts) c Hcheck)
      as [_ [Hvar_length [names [expected [Hnames [Hlayout [Hquery Hpost]]]]]]].
    pose proof (run_plan_join_wf p cp db c Hplan Hwf Hloaded Hin) as Hjoin.
    pose proof (J.run_sound (join V.t c) (map (source_index db) (sources V.t c)) b
      Hjoin Hbinding) as Hanswer.
    pose proof (proj1 Hanswer) as Hbinding_length.
    pose proof (run_join_answer_sources db b (join V.t c) (sources V.t c) Hanswer) as Hsources.
    destruct (run_var_table_spec (var_of V.t c) names Hnames) as [Hdistinct Hindices].
    assert (Hname_cells : forall x j, trie_get x names = Some j -> exists cell,
        nth_error b (N.to_nat j) = Some cell /\ env_of c b x = Some cell).
    { apply run_checked_names_cells; [exact Hnames|lia]. }
    assert (Hpost_correct : post V.t c = run_query_post q 0).
    { pose proof (run_check_query_post q newok names (nvars (join V.t c)) table 0 0 Empty 0
        (sources V.t c) (cols (join V.t c)) [] (nat_n (nvars (join V.t c))) [] [] expected
        Hquery) as Hexpected.
      rewrite Hpost, Hexpected, !rev_append_rev, !app_nil_r, rev_involutive. reflexivity. }
    unfold keep in Hkeep. rewrite rule_at_nth in Hkeep.
    change (plan_rule_ix c) with (rule_ix V.t c) in Hkeep.
    rewrite (@nth_error_nth (rule V.t) (rules V.t p) (N.to_nat (rule_ix V.t c))
      (Rule V.t q acts) (Rule V.t [] []) Hrule) in Hkeep.
    change (keep_post V.prim V.eqb q (bind_trie c b) (post V.t c) (var_of V.t c) = true)
      in Hkeep.
    rewrite Hpost_correct in Hkeep.
    destruct (run_keep_post_sound q (bind_trie c b) (var_of V.t c) Hkeep)
      as [Hprimitive_checks Hcopy_checks].
    rewrite run_query_duplicates_count, Nat.add_0_r in Hcopy_checks.
    assert (Hcopies : forall j x, nth_error (run_query_duplicates q) j = Some x -> exists cell,
        nth_error b j = Some cell /\ env_of c b x = Some cell).
    { apply run_binding_copies_sound; [exact Hdistinct|exact Hcopy_checks]. }
    assert (Hprimitives : Forall (fun a => match a with
        | Prim _ _ _ _ => atom_holds V.prim (D.view db) (env_of c b) a
        | Fun _ _ _ _ => True end) q).
    { apply Forall_forall. intros a Ha.
      apply Forall_forall with (x := a) in Hprimitive_checks; [|exact Ha].
      destruct a as [f args res|prim args res]; [exact I|].
      eapply run_primitive_check_sound; [exact Hprimitive_checks|].
      intro x. unfold bind_trie. rewrite run_binding_trie_get. reflexivity. }
    exact (proj1 (run_check_query_values p cp db q ctx_empty g Htyped table newok names
      (nvars (join V.t c)) 0 0 Empty 0 (sources V.t c) (cols (join V.t c)) []
      (nat_n (nvars (join V.t c))) [] [] expected (env_of c b) b Hwf Hloaded Htable Hquery
      Hname_cells Hcopies Hsources Hprimitives)).
  Qed.




  Lemma naive_plans_complete : forall p cp db r s, plans_ok p cp -> D.wf db ->
    loaded p cp db -> D.canonical db -> In r (rules V.t p) ->
    matches V.prim (D.view db) (query V.t r) s ->
    exists c b, In c (naive V.t cp) /\
      nth_error (rules V.t p) (N.to_nat (rule_ix V.t c)) = Some r /\
      In b (bindings cp c db) /\ keep p c (bind_trie c b) = true /\
      agrees (env_of c b) s (query_vars r).
  Proof.
    intros p cp db [q acts] s Hplans Hwf Hloaded Hcanonical Hmember Hmatches.
    destruct (run_rule_naive_member p cp (Rule V.t q acts) Hplans Hmember)
      as [table [c [Hnaive [Hslots [Hrule Hchecked]]]]].
    destruct c as [ix [n columns] srcs vars postlist].
    destruct (run_check_cplan_parts false table ix (Rule V.t q acts)
      (CPlan V.t ix (JPlan n columns) srcs vars postlist) Hchecked)
      as [_ [Hlength [names [expected [Hnames [Hlayout [Hquery Hpost]]]]]]].
    cbn [var_of join sources query post nvars cols] in Hlength, Hnames, Hlayout, Hquery, Hpost.
    pose proof (plans_ok_sorted p cp Hplans) as Hprogram.
    apply Forall_forall with (x := Rule V.t q acts) in Hprogram; [|exact Hmember].
    destruct Hprogram as [g [Htyped Hactions]].
    assert (Hregistered : forall x, In (Var x) (flat_map atom_terms q) ->
        exists j, trie_get x names = Some j).
    { intros x Hin.
      destruct (run_query_vars_fun (program_sorts p) (program_kind p) q g Htyped x
        (proj2 (run_query_vars_member q x) Hin)) as [f [args [res [Hfun Hvar]]]].
      eapply run_check_query_names; [exact Hquery|exact Hfun|exact Hvar]. }
    set (b := run_make_binding s vars (run_query_duplicates q)
      (run_literal_entries srcs columns)).
    destruct (run_layout_assignment q vars srcs columns s Hlayout)
      as [Hbinding_length [Hcopies [Hreal Hliterals]]].
    change (length b = length vars) in Hbinding_length.
    change (forall j x, nth_error (run_query_duplicates q) j = Some x ->
      nth_error b j = Some (run_env_cell s x)) in Hcopies.
    change (forall j x, nth_error vars j = Some x ->
      (x <= query_max q 1%positive)%positive ->
      nth_error b j = Some (run_env_cell s x)) in Hreal.
    change (forall j c, In (j, c) (run_literal_entries srcs columns) ->
      nth_error b j = Some c) in Hliterals.
    destruct (run_var_table_spec vars names Hnames) as [Hdistinct Hpositions].
    assert (Hnamed_cells : forall x j, In (Var x) (flat_map atom_terms q) ->
        trie_get x names = Some j -> nth_error b (N.to_nat j) = Some (run_env_cell s x)).
    { intros x j Hin Hget. apply Hreal.
      - now apply Hpositions.
      - now apply planner_query_max_member with (m := 1%positive). }
    assert (Hslot_cells : forall f perm slot, slot_matches table f perm slot = true ->
        D.slot_of db slot = Some (f, perm)).
    { intros f perm slot Hmatch. unfold D.slot_of.
      rewrite (proj1 (proj2 Hloaded)).
      eapply run_slot_matches_index; [exact Hslots|exact Hmatch]. }
    destruct (run_check_query_answer q db names n table 0 0 Empty 0 srcs columns []
      (nat_n n) [] [] expected s b Hwf Hquery Hmatches Hnamed_cells Hcopies Hliterals
      Hslot_cells) as [_ Hanswer].
    assert (Hsatisfied : run_sources_satisfied db b srcs columns).
    { apply Hanswer. constructor. }
    assert (Hall : In (CPlan V.t ix (JPlan n columns) srcs vars postlist) (all_plans cp)).
    { unfold all_plans. apply in_or_app. now left. }
    assert (Hbinding : In b
        (bindings cp (CPlan V.t ix (JPlan n columns) srcs vars postlist) db)).
    { apply J.run_complete.
      - exact (run_plan_join_wf p cp db
          (CPlan V.t ix (JPlan n columns) srcs vars postlist) Hplans Hwf Hloaded Hall).
      - apply run_sources_join_answer; [cbn; lia|exact Hsatisfied]. }
    assert (Hagree : forall x, In (Var x) (flat_map atom_terms q) ->
        binding_env vars b x = s x).
    { eapply run_binding_agrees; eassumption. }
    assert (Hpost_exact : postlist = run_query_post q 0).
    { pose proof (run_check_query_post q false names n table 0 0 Empty 0 srcs columns []
        (nat_n n) [] [] expected Hquery) as Hexpected.
      rewrite Hpost, Hexpected, app_nil_r, rev_append_rev, app_nil_r, rev_involutive.
      reflexivity. }
    assert (Hkeep : keep p (CPlan V.t ix (JPlan n columns) srcs vars postlist)
        (bind_trie (CPlan V.t ix (JPlan n columns) srcs vars postlist) b) = true).
    { unfold keep, bind_trie. cbn [plan_rule_ix plan_vars plan_post].
      rewrite rule_at_nth.
      rewrite (@nth_error_nth (rule V.t) (rules V.t p) (N.to_nat ix)
        (Rule V.t q acts) (Rule V.t [] []) Hrule).
      rewrite Hpost_exact. apply run_keep_post_complete.
      - eapply run_binding_primitive_checks; eassumption.
      - eapply run_binding_copy_cells;
          [exact Hmatches|exact Hdistinct| |exact Hagree|exact Hcopies].
        exact (proj1 (run_layout_ok_sound q vars srcs columns Hlayout)). }
    exists (CPlan V.t ix (JPlan n columns) srcs vars postlist), b.
    split; [exact Hnaive|]. split; [exact Hrule|]. split; [exact Hbinding|].
    split; [exact Hkeep|]. intros x Hin. apply Hagree.
    now apply (proj1 (run_query_vars_member q x)).
  Qed.


  (** Canonicalization changes an identifier name without changing its sort. *)
  Lemma run_canon_sort : forall db (c : cell V.t), cell_sort (D.canon db c) = cell_sort c.
  Proof.
    intros db [i|v]; reflexivity.
  Qed.

  (** Canonicalizing a row keeps all argument sorts. *)
  Lemma run_canon_sorts : forall db (k : list (cell V.t)),
    map cell_sort (map (D.canon db) k) = map cell_sort k.
  Proof.
    intros db k. induction k as [|c rest IH]; cbn [map]; [reflexivity|].
    rewrite run_canon_sort, IH. reflexivity.
  Qed.

  (** Canonicalizing an optional output keeps its sort. *)
  Lemma run_canon_output_sort : forall db (o : option (cell V.t)),
    option_map cell_sort (option_map (D.canon db) o) = option_map cell_sort o.
  Proof.
    intros db [c|]; cbn [option_map]; [now rewrite run_canon_sort|reflexivity].
  Qed.

  (** Combining outputs of one declared kind preserves their output sort. *)
  Lemma run_combine_sorted : forall db f out previous o,
    kind (D.view db) f = Some out ->
    (match previous with
     | Some old => option_map cell_sort old = out_sort out
     | None => True
     end) ->
    option_map cell_sort o = out_sort out ->
    option_map cell_sort (D.combine db f previous o) = out_sort out.
  Proof.
    intros db f out previous o Hkind Hprevious Hout.
    unfold D.combine. rewrite Hkind.
    destruct previous as [[[i|v]|]|]; cbn in Hprevious |- *; try assumption.
    destruct out; destruct o as [[j|w]|]; cbn in *; congruence.
  Qed.

  (** Folding compatible outputs keeps their common sort. *)
  Lemma run_fold_outputs_sorted : forall db f out os acc,
    kind (D.view db) f = Some out ->
    Forall (fun o => option_map cell_sort o = out_sort out) os ->
    option_map cell_sort acc = out_sort out ->
    option_map cell_sort
      (fold_left (fun a o => D.combine db f (Some a) o) os acc) = out_sort out.
  Proof.
    intros db f out os. induction os as [|o rest IH]; intros acc Hkind Hsort Hacc.
    - exact Hacc.
    - inversion Hsort as [|o' rest' Ho Hrest]; subst o' rest'. cbn [fold_left].
      apply IH; [exact Hkind|exact Hrest|].
      apply run_combine_sorted; assumption.
  Qed.

  (** Merging a nonempty group of compatible outputs keeps their common sort. *)
  Lemma run_merged_sorted : forall db f out os,
    kind (D.view db) f = Some out -> os <> [] ->
    Forall (fun o => option_map cell_sort o = out_sort out) os ->
    option_map cell_sort (D.merged db f os) = out_sort out.
  Proof.
    intros db f out [|o rest] Hkind Hnonempty Hsort; [contradiction|].
    inversion Hsort as [|o' rest' Ho Hrest]; subst o' rest'.
    cbn [D.merged map]. apply run_fold_outputs_sorted; [exact Hkind| |].
    - apply Forall_forall. intros output Hin. apply in_map_iff in Hin as [old [<- Hin]].
      rewrite run_canon_output_sort. exact ((proj1 (Forall_forall _ _)) Hrest old Hin).
    - now rewrite run_canon_output_sort.
  Qed.

  Lemma put_preserves_sorted : forall sorts f k o db, D.wf db -> D.kind_ok db f k o ->
    view_sorted sorts (D.view db) -> row_sorted sorts (kind (D.view db)) f k o ->
    view_sorted sorts (D.view (D.put f k o db)).
  Proof.
    intros sorts f k o db Hwf Hallowed Hsorted [out [Hsort [Hkind Hout]]].
    intros g key output Hrow. unfold row_sorted.
    rewrite (proj1 (D.layout_put f k o db Hwf)).
    apply (proj1 (D.put_rows f k o db Hwf Hallowed g key output)) in Hrow.
    destruct Hrow as [[Hrow _]|[-> [-> <-]]].
    - exact (Hsorted g key output Hrow).
    - exists out. split; [now rewrite run_canon_sorts|]. split; [exact Hkind|].
      apply run_combine_sorted; [exact Hkind| |now rewrite run_canon_output_sort].
      destruct (D.old db f (map (D.canon db) k)) as [old|] eqn:Hold; [|exact I].
      apply (proj1 (D.old_row db f (map (D.canon db) k) old Hwf)) in Hold.
      destruct (Hsorted f (map (D.canon db) k) old Hold)
        as [oldout [_ [Holdkind Holdsort]]].
      rewrite Hkind in Holdkind. injection Holdkind as <-. exact Holdsort.
  Qed.

  Lemma make_preserves_sorted : forall sorts f k db, D.wf db -> kind (D.view db) f = Some OId ->
    sorts f = Some (map cell_sort k) -> view_sorted sorts (D.view db) ->
    view_sorted sorts (D.view (snd (D.make f k db))).
  Proof.
    intros sorts f k db Hwf Hkind Hsort Hsorted.
    pose proof (D.make_spec f k db Hwf Hkind) as Hmake.
    destruct (D.make f k db) as [i next]. cbn [snd].
    destruct Hmake as [[j [_ [_ ->]]]|[_ [_ [_ [Hkinds [_ Hrows]]]]]].
    - exact Hsorted.
    - intros g key output Hrow. unfold row_sorted. rewrite Hkinds.
      apply (proj1 (Hrows g key output)) in Hrow.
      destruct Hrow as [Hrow|[-> [-> ->]]].
      + exact (Hsorted g key output Hrow).
      + exists OId. split; [now rewrite run_canon_sorts|]. split; [exact Hkind|reflexivity].
  Qed.

  Lemma union_preserves_sorted : forall sorts i j db, D.wf db ->
    view_sorted sorts (D.view db) -> view_sorted sorts (D.view (D.union i j db)).
  Proof.
    intros sorts i j db Hwf Hsorted f k o Hrow.
    rewrite (D.union_rows i j db Hwf) in Hrow.
    unfold row_sorted. rewrite (proj1 (D.layout_union i j db Hwf)).
    exact (Hsorted f k o Hrow).
  Qed.

  Lemma rebuild_preserves_sorted : forall sorts db, D.wf db ->
    view_sorted sorts (D.view db) -> view_sorted sorts (D.view (D.rebuild db)).
  Proof.
    intros sorts db Hwf Hsorted f key output Hrow.
    destruct (D.rebuild_from db f key output Hwf Hrow)
      as [srcs [Hnonempty [Hsources Houtput]]].
    destruct srcs as [|[first old] rest]; [contradiction|].
    inversion Hsources as [|pair rest' [Hfirst Hkey] Hrest]; subst pair rest'.
    destruct (Hsorted f first old Hfirst) as [out [Hsort [Hkind Hout]]].
    assert (Hkind' : kind (D.view (D.rebuild db)) f = Some out).
    { rewrite (proj1 (D.layout_rebuild db Hwf)). exact Hkind. }
    exists out. split.
    - cbn [fst] in Hkey. rewrite <- Hkey, run_canon_sorts. exact Hsort.
    - split; [exact Hkind'|]. rewrite Houtput.
      apply run_merged_sorted; [exact Hkind'|discriminate|].
      apply Forall_forall. intros result Hin.
      apply in_map_iff in Hin as [[k o] [Heq Hin]]. cbn in Heq. subst result.
      destruct ((proj1 (Forall_forall _ _)) Hsources (k, o) Hin) as [Hsource _].
      destruct (Hsorted f k o Hsource) as [other [_ [Hother Hresult]]].
      rewrite Hkind in Hother. injection Hother as <-. exact Hresult.
  Qed.

  Lemma advance_preserves_sorted : forall sorts db, D.wf db ->
    view_sorted sorts (D.view db) -> view_sorted sorts (D.view (D.advance db)).
  Proof.
    intros sorts db Hwf Hsorted. rewrite (proj1 (proj2 (D.wf_advance db Hwf))).
    exact Hsorted.
  Qed.

  (** An empty local table leaves the binding environment unchanged. *)
  Lemma run_look_empty : forall (s : Model.env (V := V.t)) x, look s Empty x = s x.
  Proof.
    intros s x. unfold look. now rewrite PTrie.get_empty.
  Qed.

  (** Updating a local binding implements the semantic environment update. *)
  Lemma run_look_set : forall (s : Model.env (V := V.t)) locals x c y,
    look s (PTrieCode.set x c locals) y = update (look s locals) x c y.
  Proof.
    intros s locals x c y. unfold look, update.
    destruct (Pos.eqb x y) eqn:Hsame.
    - apply Pos.eqb_eq in Hsame. subst y. now rewrite PTrie.get_set_same.
    - apply Pos.eqb_neq in Hsame. rewrite PTrie.get_set_other by congruence. reflexivity.
  Qed.

  (** A successful action-term lookup has exactly its semantic value. *)
  Lemma run_term_cell_spec : forall (s : Model.env (V := V.t)) locals t c,
    term_cell s locals t = Some c <-> term_value (look s locals) t c.
  Proof.
    intros s locals [x|v] c; cbn [term_cell term_value]; [reflexivity|].
    split; intro Heq; [now injection Heq as <-|now subst c].
  Qed.

  (** A successful argument lookup gives the semantic argument list. *)
  Lemma run_term_cells_spec : forall (s : Model.env (V := V.t)) locals ts cs,
    term_cells s locals ts = Some cs <-> terms_value (look s locals) ts cs.
  Proof.
    intros s locals ts. induction ts as [|t rest IH]; intro cs.
    - cbn [term_cells terms_value]. split; intro H.
      + injection H as <-. constructor.
      + inversion H. reflexivity.
    - split; intro H.
      + cbn [term_cells] in H.
        destruct (term_cell s locals t) as [c|] eqn:Hcell; [|discriminate].
        destruct (term_cells s locals rest) as [more|] eqn:Hmore; [|discriminate].
        injection H as <-. constructor.
        * apply run_term_cell_spec. exact Hcell.
        * apply IH. reflexivity.
      + inversion H as [|t' c rest' more Hhead Htail]; subst t' rest' cs.
        cbn [term_cells].
        rewrite (proj2 (run_term_cell_spec s locals t c) Hhead), (proj2 (IH more) Htail).
        reflexivity.
  Qed.

  (** An optional result lookup agrees with the semantic result pattern. *)
  Lemma run_result_cell_spec : forall (s : Model.env (V := V.t)) locals res o,
    result_cell s locals res = Some o <->
    match res, o with
    | None, None => True
    | Some t, Some c => term_value (look s locals) t c
    | _, _ => False
    end.
  Proof.
    intros s locals [t|] [c|]; cbn [result_cell].
    - rewrite <- run_term_cell_spec. destruct (term_cell s locals t); split; congruence.
    - destruct (term_cell s locals t); split; intro H; try discriminate; contradiction.
    - split; [discriminate|contradiction].
    - split; [intros; exact I|intros; reflexivity].
  Qed.

  (** Primitive argument lookup supplies exactly the value cells it reads. *)
  Lemma run_term_values_spec : forall (s : Model.env (V := V.t)) locals ts vs,
    term_values s locals ts = Some vs ->
    terms_value (look s locals) ts (map Val vs).
  Proof.
    intros s locals ts. induction ts as [|t rest IH]; intros vs Hlookup.
    - injection Hlookup as <-. constructor.
    - cbn [term_values] in Hlookup.
      destruct (term_cell s locals t) as [[i|v]|] eqn:Hcell; try discriminate.
      destruct (term_values s locals rest) as [more|] eqn:Hmore; [|discriminate].
      injection Hlookup as <-. constructor.
      + apply run_term_cell_spec. exact Hcell.
      + apply IH. reflexivity.
  Qed.

  (** Value cells represent their underlying primitive arguments. *)
  Lemma run_value_cells : forall vs : list V.t, values (map Val vs) vs.
  Proof.
    intro vs. induction vs; constructor; auto.
  Qed.

  (** A sorted term has a successful lookup of its declared sort. *)
  Lemma run_term_cell_typed : forall g (s : Model.env (V := V.t)) locals t ty,
    env_sorted g (look s locals) -> has g t ty ->
    exists c, term_cell s locals t = Some c /\ cell_sort c = ty.
  Proof.
    intros g s locals [x|v] ty Henv Hhas.
    - apply Henv. exact Hhas.
    - cbn [has] in Hhas. subst ty. exists (Val v). split; reflexivity.
  Qed.

  (** Sorted argument terms have successful lookups with the declared argument sorts. *)
  Lemma run_term_cells_typed : forall g (s : Model.env (V := V.t)) locals ts ss,
    env_sorted g (look s locals) -> Forall2 (has g) ts ss ->
    exists cs, term_cells s locals ts = Some cs /\ map cell_sort cs = ss.
  Proof.
    intros g s locals ts ss Henv Hhas. induction Hhas as [|t ty ts ss Hhead Htail IH].
    - exists []. split; reflexivity.
    - destruct (run_term_cell_typed g s locals t ty Henv Hhead) as [c [Hc Hty]].
      destruct IH as [cs [Hcs Hsort]]. exists (c :: cs).
      cbn [term_cells map]. rewrite Hc, Hcs, Hty, Hsort. split; reflexivity.
  Qed.

  (** A sorted optional result has a successful lookup of its declared output sort. *)
  Lemma run_result_cell_typed : forall g (s : Model.env (V := V.t)) locals out res,
    env_sorted g (look s locals) -> has_result g out res ->
    exists o, result_cell s locals res = Some o /\ option_map cell_sort o = out_sort out.
  Proof.
    intros g s locals out res Henv Hhas. destruct out; destruct res as [t|];
      cbn [has_result out_sort] in Hhas; try contradiction.
    - exists None. split; reflexivity.
    - destruct (run_term_cell_typed g s locals t SId Henv Hhas) as [c [Hc Hsort]].
      exists (Some c). cbn [result_cell option_map out_sort]. rewrite Hc, Hsort.
      split; reflexivity.
    - destruct (run_term_cell_typed g s locals t SVal Henv Hhas) as [c [Hc Hsort]].
      exists (Some c). cbn [result_cell option_map out_sort]. rewrite Hc, Hsort.
      split; reflexivity.
  Qed.

  (** Sorted primitive arguments always evaluate to a list of values. *)
  Lemma run_term_values_typed : forall g (s : Model.env (V := V.t)) locals ts,
    env_sorted g (look s locals) -> Forall (fun t => has g t SVal) ts ->
    exists vs, term_values s locals ts = Some vs.
  Proof.
    intros g s locals ts Henv Hhas. induction Hhas as [|t rest Hhead Htail IH].
    - exists []. reflexivity.
    - destruct (run_term_cell_typed g s locals t SVal Henv Hhead) as [[i|v] [Hc Hsort]];
        [discriminate|].
      destruct IH as [vs Hvs]. exists (v :: vs). cbn [term_values]. now rewrite Hc, Hvs.
  Qed.

  (** An identifier read by an action term was already allocated. *)
  Lemma run_term_cell_allocated : forall db (s : Model.env (V := V.t)) locals t i,
    env_allocated db (look s locals) -> term_cell s locals t = Some (Id i) ->
    D.allocated db i.
  Proof.
    intros db s locals [x|v] i Hallocated Hcell; [eapply Hallocated; exact Hcell|discriminate].
  Qed.

  (** Every identifier in a successfully read argument list was already allocated. *)
  Lemma run_term_cells_allocated : forall db (s : Model.env (V := V.t)) locals ts cs,
    env_allocated db (look s locals) -> term_cells s locals ts = Some cs ->
    forall i, In (Id i) cs -> D.allocated db i.
  Proof.
    intros db s locals ts. induction ts as [|t rest IH]; intros cs Hallocated Hcells i Hin.
    - injection Hcells as <-. contradiction.
    - cbn [term_cells] in Hcells.
      destruct (term_cell s locals t) as [c|] eqn:Hc; [|discriminate].
      destruct (term_cells s locals rest) as [more|] eqn:Hmore; [|discriminate].
      injection Hcells as <-. destruct Hin as [Heq|Hin].
      + subst c. eapply run_term_cell_allocated; eauto.
      + eapply IH; eauto.
  Qed.

  (** An identifier in a successfully read result was already allocated. *)
  Lemma run_result_cell_allocated : forall db (s : Model.env (V := V.t)) locals res o,
    env_allocated db (look s locals) -> result_cell s locals res = Some o ->
    forall i, In (Id i) (option_list o) -> D.allocated db i.
  Proof.
    intros db s locals [t|] o Hallocated Hresult i Hin; cbn [result_cell] in Hresult.
    - destruct (term_cell s locals t) as [c|] eqn:Hc; [|discriminate].
      injection Hresult as <-. destruct Hin as [Heq|[]]. subst c.
      eapply run_term_cell_allocated; eauto.
    - injection Hresult as <-. contradiction.
  Qed.

  (** A local assignment preserves the context's environment typing. *)
  Lemma run_env_sorted_set : forall g (s : Model.env (V := V.t)) locals x c ty,
    env_sorted g (look s locals) -> cell_sort c = ty ->
    env_sorted (ctx_set g x ty) (look s (PTrieCode.set x c locals)).
  Proof.
    intros g s locals x c ty Henv Hsort y other Hctx.
    rewrite run_look_set. unfold ctx_set in Hctx. unfold update.
    destruct (Pos.eqb x y).
    - injection Hctx as <-. exists c. split; [reflexivity|exact Hsort].
    - apply Henv. exact Hctx.
  Qed.

  (** Allocated environment identifiers remain allocated when the counter grows. *)
  Lemma run_env_allocated_mono : forall db next (s : Model.env (V := V.t)),
    (D.ids db <= D.ids next)%N -> env_allocated db s -> env_allocated next s.
  Proof.
    intros db next s Hids Henv x i Hcell. unfold D.allocated.
    specialize (Henv x i Hcell). unfold D.allocated in Henv. lia.
  Qed.

  (** A local assignment preserves allocation when its new cell is allocated. *)
  Lemma run_env_allocated_set : forall db (s : Model.env (V := V.t)) locals x c,
    env_allocated db (look s locals) ->
    (forall i, c = Id i -> D.allocated db i) ->
    env_allocated db (look s (PTrieCode.set x c locals)).
  Proof.
    intros db s locals x c Henv Hcell y i Hlookup.
    rewrite run_look_set in Hlookup. unfold update in Hlookup.
    destruct (Pos.eqb x y).
    - apply Hcell. now injection Hlookup.
    - eapply Henv. exact Hlookup.
  Qed.

  (** Typing a query from the empty context determines every output-context binding. *)
  Lemma run_query_context : forall (p : program V.t) (q : list (atom V.t)) g h,
    query_ok (program_sorts p) (program_kind p) ctx_empty q g ->
    query_ok (program_sorts p) (program_kind p) ctx_empty q h ->
    forall x, g x = h x.
  Proof.
    intros p q g h Hg Hh x.
    destruct (bind_query_b_complete V.t (decls V.t p) Empty ctx_empty q g
      trie_ctx_empty Hg) as [tg [Htg Hgrepr]].
    destruct (bind_query_b_complete V.t (decls V.t p) Empty ctx_empty q h
      trie_ctx_empty Hh) as [th [Hth Hhrepr]].
    rewrite Htg in Hth. injection Hth as <-. rewrite <- Hgrepr, <- Hhrepr. reflexivity.
  Qed.

  (** A checked rule and its environment share a context that types all its actions. *)
  Lemma run_rule_context : forall p cp r s, plans_ok p cp -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s ->
    exists g, query_ok (program_sorts p) (program_kind p) ctx_empty (query V.t r) g /\
      actions_ok (program_sorts p) (program_kind p) g (actions V.t r) /\ env_sorted g s.
  Proof.
    intros p cp r s Hchecked Hin [h [Hquery Henv]].
    pose proof (plans_ok_sorted p cp Hchecked) as Hprogram.
    destruct ((proj1 (Forall_forall _ _)) Hprogram r Hin) as [g [Hg Hacts]].
    exists g. split; [exact Hg|]. split; [exact Hacts|].
    intros x ty Hctx. apply Henv. rewrite <- (run_query_context p (query V.t r) g h Hg Hquery x).
    exact Hctx.
  Qed.

  (** Every checked slot fits a row having its declaration's width. *)
  Lemma run_slots_fit : forall p cp db f ss kindout n,
    plans_ok p cp -> loaded p cp db -> program_sorts p f = Some ss ->
    program_kind p f = Some kindout ->
    n = length ss + match kindout with ORel => 0 | _ => 1 end -> D.slots_fit db f n.
  Proof.
    intros p cp db f ss kindout n Hchecked [_ [Hslots _]] Hsort Hkind Hwidth perm Hin.
    rewrite Hslots in Hin.
    destruct (check_plan_slots p cp f perm Hchecked Hin) as [d [Hdecl [Hnodup Hbound]]].
    destruct (run_find_decl_fields (decls V.t p) f d Hdecl) as [Hds Hdk].
    change (program_sorts p f = Some (arg_sorts d)) in Hds.
    change (program_kind p f = Some (out d)) in Hdk.
    rewrite Hsort in Hds. injection Hds as Hss. rewrite Hkind in Hdk. injection Hdk as Hout.
    rewrite <- Hss, <- Hout in Hbound. split; [exact Hnodup|]. now rewrite Hwidth.
  Qed.

  (** The output sort determines how many cells the output contributes. *)
  Lemma run_output_length : forall (o : option (cell V.t)) kindout,
    option_map cell_sort o = out_sort kindout ->
    length (option_list o) = match kindout with ORel => 0 | _ => 1 end.
  Proof.
    intros [c|] kindout Hsort; destruct kindout; cbn in *; try discriminate; reflexivity.
  Qed.

  (** A sorted and allocated row meets the database's insertion preconditions. *)
  Lemma run_put_allowed : forall p cp db f k o,
    plans_ok p cp -> loaded p cp db ->
    row_sorted (program_sorts p) (program_kind p) f k o ->
    (forall i, In (Id i) (k ++ option_list o) -> D.allocated db i) -> D.kind_ok db f k o.
  Proof.
    intros p cp db f k o Hchecked Hloaded [out [Hsort [Hkind Hout]]] Hallocated.
    split; [exact Hallocated|]. split.
    - eapply run_slots_fit; [exact Hchecked|exact Hloaded|exact Hsort|exact Hkind|].
      rewrite length_app, length_map, (run_output_length o out Hout). reflexivity.
    - rewrite (proj1 Hloaded), Hkind. destruct out; destruct o as [[i|v]|];
        cbn in *; try discriminate; exact I.
  Qed.

  (** Constructor allocation never decreases the identifier counter. *)
  Lemma run_make_ids : forall f k db, D.wf db -> kind (D.view db) f = Some OId ->
    (D.ids db <= D.ids (snd (D.make f k db)))%N.
  Proof.
    intros f k db Hwf Hkind. pose proof (D.make_spec f k db Hwf Hkind) as Hmake.
    destruct (D.make f k db) as [i next]. cbn [snd].
    destruct Hmake as [[j [_ [_ ->]]]|[Hfresh [_ [Hids _]]]]; [lia|].
    unfold D.fresh_id in Hfresh. rewrite Hids, Hfresh.
    replace (Npos (N.succ_pos (D.ids db))) with (N.succ (D.ids db))
      by (destruct (D.ids db); reflexivity).
    lia.
  Qed.

  (** A typed constructor action preserves the loaded state and returns an allocated name. *)
  Lemma run_make_state : forall p cp f k db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    program_kind p f = Some OId -> program_sorts p f = Some (map cell_sort k) ->
    (forall i, In (Id i) k -> D.allocated db i) ->
    D.wf (snd (D.make f k db)) /\ loaded p cp (snd (D.make f k db)) /\
    (D.ids db <= D.ids (snd (D.make f k db)))%N /\
    D.allocated (snd (D.make f k db)) (fst (D.make f k db)) /\
    D.pending (snd (D.make f k db)) = D.pending db.
  Proof.
    intros p cp f k db Hchecked Hwf Hloaded Hkind Hsort Hallocated.
    assert (Hkinddb : kind (D.view db) f = Some OId) by (rewrite (proj1 Hloaded); exact Hkind).
    assert (Hfit : D.slots_fit db f (S (length k))).
    { eapply run_slots_fit; [exact Hchecked|exact Hloaded|exact Hsort|exact Hkind|].
      rewrite length_map. cbn. lia. }
    destruct (D.layout_make f k db Hwf) as [Hkinds [Hslots [_ [Hnew Hpending]]]].
    split; [apply D.wf_make; assumption|]. split.
    - destruct Hloaded as [Hdecls [Hlayout Hsorted]].
      split; [intro g; rewrite Hkinds; apply Hdecls|].
      split; [now rewrite Hslots|]. apply make_preserves_sorted; assumption.
    - split; [apply run_make_ids; assumption|].
      split; assumption.
  Qed.

  (** A typed insertion preserves the loaded state and queues at most one entry. *)
  Lemma run_put_state : forall p cp f k o db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    row_sorted (program_sorts p) (program_kind p) f k o ->
    (forall i, In (Id i) (k ++ option_list o) -> D.allocated db i) ->
    D.wf (D.put f k o db) /\ loaded p cp (D.put f k o db) /\
    D.ids (D.put f k o db) = D.ids db /\
    D.pending (D.put f k o db) <= D.pending db + 1.
  Proof.
    intros p cp f k o db Hchecked Hwf Hloaded Hrow Hallocated.
    pose proof (run_put_allowed p cp db f k o Hchecked Hloaded Hrow Hallocated) as Hallowed.
    destruct (D.layout_put f k o db Hwf) as [Hkinds [Hslots [Hids Hpending]]].
    split; [apply D.wf_put; assumption|]. split.
    - destruct Hloaded as [Hdecls [Hlayout Hsorted]].
      split; [intro g; rewrite Hkinds; apply Hdecls|]. split; [now rewrite Hslots|].
      apply put_preserves_sorted; try assumption.
      destruct Hrow as [out [Hsort [Hkind Hout]]]. exists out.
      split; [exact Hsort|]. split; [rewrite Hdecls; exact Hkind|exact Hout].
    - split; assumption.
  Qed.

  (** An allocated union preserves the loaded state and queues at most one entry. *)
  Lemma run_union_state : forall p cp i j db,
    D.wf db -> loaded p cp db -> D.allocated db i -> D.allocated db j ->
    D.wf (D.union i j db) /\ loaded p cp (D.union i j db) /\
    D.ids (D.union i j db) = D.ids db /\
    D.pending (D.union i j db) <= D.pending db + 1.
  Proof.
    intros p cp i j db Hwf Hloaded Hi Hj.
    destruct (D.layout_union i j db Hwf) as [Hkinds [Hslots [Hids Hpending]]].
    split; [apply D.wf_union; assumption|]. split.
    - destruct Hloaded as [Hdecls [Hlayout Hsorted]].
      split; [intro g; rewrite Hkinds; apply Hdecls|]. split; [now rewrite Hslots|].
      apply union_preserves_sorted; assumption.
    - split; assumption.
  Qed.

  (** Typed actions preserve loaded well-formed states and bound their pending work. *)
  Lemma run_apply_go_typed : forall p cp acts g s locals db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    D.wf (apply_go acts s locals db) /\ loaded p cp (apply_go acts s locals db) /\
    (D.ids db <= D.ids (apply_go acts s locals db))%N /\
    D.pending (apply_go acts s locals db) <= D.pending db + length acts.
  Proof.
    intros p cp acts. induction acts as [|a rest IH]; intros g s locals db
      Hchecked Hwf Hloaded Hacts Henv Hallocated.
    - cbn [apply_go length]. split; [exact Hwf|]. split; [exact Hloaded|]. repeat split; lia.
    - destruct a as [x f args|f args res|t u|x op args]; cbn [actions_ok] in Hacts.
      + destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]].
        destruct (run_term_cells_typed g s locals args ss Henv Hargs)
          as [cells [Hcells Hsorts]].
        rewrite <- Hsorts in Hsort.
        pose proof (run_term_cells_allocated db s locals args cells Hallocated Hcells) as Hids.
        pose proof (run_make_state p cp f cells db Hchecked Hwf Hloaded Hkind Hsort Hids)
          as Hstate.
        destruct (D.make f cells db) as [i next] eqn:Hmake. cbn [fst snd] in Hstate.
        destruct Hstate as [Hwf' [Hloaded' [Hids' [Hnew Hpending]]]].
        assert (Henv' : env_sorted (ctx_set g x SId)
            (look s (PTrieCode.set x (Id i) locals))).
        { apply run_env_sorted_set; [exact Henv|reflexivity]. }
        assert (Hallocated' : env_allocated next (look s (PTrieCode.set x (Id i) locals))).
        { apply run_env_allocated_set.
          - eapply run_env_allocated_mono; [exact Hids'|exact Hallocated].
          - intros j Heq. injection Heq as <-. exact Hnew. }
        destruct (IH _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv' Hallocated')
          as [Hfinal [Hloadfinal [Hidfinal Hpendfinal]]].
        cbn [apply_go]. rewrite Hcells, Hmake.
        split; [exact Hfinal|]. split; [exact Hloadfinal|]. cbn [length]. repeat split; lia.
      + destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
        destruct (run_term_cells_typed g s locals args ss Henv Hargs)
          as [cells [Hcells Hsorts]].
        destruct (run_result_cell_typed g s locals out res Henv Hresult)
          as [output [Houtput Houtsort]].
        assert (Hrow : row_sorted (program_sorts p) (program_kind p) f cells output).
        { exists out. rewrite Hsorts. repeat split; assumption. }
        assert (Hids : forall i, In (Id i) (cells ++ option_list output) -> D.allocated db i).
        { intros i Hin. apply in_app_iff in Hin as [Hin|Hin].
          - eapply run_term_cells_allocated; eauto.
          - eapply run_result_cell_allocated; eauto. }
        destruct (run_put_state p cp f cells output db Hchecked Hwf Hloaded Hrow Hids)
          as [Hwf' [Hloaded' [Hids' Hpending]]].
        assert (Hallocated' : env_allocated (D.put f cells output db) (look s locals)).
        { eapply run_env_allocated_mono with (db := db);
            [rewrite Hids'; reflexivity|exact Hallocated]. }
        destruct (IH _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated')
          as [Hfinal [Hloadfinal [Hidfinal Hpendfinal]]].
        cbn [apply_go]. rewrite Hcells, Houtput.
        split; [exact Hfinal|]. split; [exact Hloadfinal|]. cbn [length]. repeat split; lia.
      + destruct Hacts as [Ht [Hu Hrest]].
        destruct (run_term_cell_typed g s locals t SId Henv Ht)
          as [[i|v] [Hi Hitype]]; [|discriminate].
        destruct (run_term_cell_typed g s locals u SId Henv Hu)
          as [[j|v] [Hj Hjtype]]; [|discriminate].
        pose proof (run_term_cell_allocated db s locals t i Hallocated Hi) as Hiall.
        pose proof (run_term_cell_allocated db s locals u j Hallocated Hj) as Hjall.
        destruct (run_union_state p cp i j db Hwf Hloaded Hiall Hjall)
          as [Hwf' [Hloaded' [Hids' Hpending]]].
        assert (Hallocated' : env_allocated (D.union i j db) (look s locals)).
        { eapply run_env_allocated_mono with (db := db);
            [rewrite Hids'; reflexivity|exact Hallocated]. }
        destruct (IH _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated')
          as [Hfinal [Hloadfinal [Hidfinal Hpendfinal]]].
        cbn [apply_go]. rewrite Hi, Hj.
        split; [exact Hfinal|]. split; [exact Hloadfinal|]. cbn [length]. repeat split; lia.
      + destruct Hacts as [Hargs Hrest].
        destruct (run_term_values_typed g s locals args Henv Hargs) as [vs Hvalues].
        cbn [apply_go]. rewrite Hvalues. destruct (V.prim op vs) as [v|] eqn:Hprim.
        * assert (Henv' : env_sorted (ctx_set g x SVal)
              (look s (PTrieCode.set x (Val v) locals))).
          { apply run_env_sorted_set; [exact Henv|reflexivity]. }
          assert (Hallocated' : env_allocated db (look s (PTrieCode.set x (Val v) locals))).
          { apply run_env_allocated_set; [exact Hallocated|]. intros i Heq. discriminate. }
          destruct (IH _ _ _ _ Hchecked Hwf Hloaded Hrest Henv' Hallocated')
            as [Hfinal [Hloadfinal [Hidfinal Hpendfinal]]].
          split; [exact Hfinal|]. split; [exact Hloadfinal|]. cbn [length]. repeat split; lia.
        * split; [exact Hwf|]. split; [exact Hloaded|]. cbn [length]. repeat split; lia.
  Qed.

  (** The public action entry starts the typed action invariant with no locals. *)
  Lemma run_apply_typed : forall p cp acts g s db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts -> env_sorted g s ->
    env_allocated db s ->
    D.wf (apply acts s db) /\ loaded p cp (apply acts s db) /\
    (D.ids db <= D.ids (apply acts s db))%N /\
    D.pending (apply acts s db) <= D.pending db + length acts.
  Proof.
    intros p cp acts g s db Hchecked Hwf Hloaded Hacts Henv Hallocated.
    unfold apply. eapply run_apply_go_typed; try eassumption.
    - intros x ty Hctx. destruct (Henv x ty Hctx) as [c [Hc Hty]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated. exact Hcell.
  Qed.

  (** Applying a checked rule preserves the functional state and bounds pending work. *)
  Lemma run_apply_state : forall p cp r s db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    In r (rules V.t p) -> rule_env (program_sorts p) (program_kind p) r s ->
    env_allocated db s ->
    D.wf (apply (actions V.t r) s db) /\ loaded p cp (apply (actions V.t r) s db) /\
    (D.ids db <= D.ids (apply (actions V.t r) s db))%N /\
    D.pending (apply (actions V.t r) s db) <= D.pending db + length (actions V.t r).
  Proof.
    intros p cp r s db Hchecked Hwf Hloaded Hin Henv Hallocated.
    destruct (run_rule_context p cp r s Hchecked Hin Henv) as [g [_ [Hacts Hsorted]]].
    exact (run_apply_typed p cp (actions V.t r) g s db Hchecked Hwf Hloaded Hacts
      Hsorted Hallocated).
  Qed.

  (** Applying a rule queues at most one pending entry per action. *)
  Lemma apply_pending_bound : forall p cp r s db, plans_ok p cp -> D.wf db ->
    loaded p cp db -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s -> env_allocated db s ->
    D.pending (apply (actions V.t r) s db) <= D.pending db + length (actions V.t r).
  Proof.
    intros p cp r s db Hchecked Hwf Hloaded Hin Henv Hallocated.
    exact (proj2 (proj2 (proj2 (run_apply_state p cp r s db Hchecked Hwf Hloaded
      Hin Henv Hallocated)))).
  Qed.

  (** Interpreting a concrete term preserves its environment lookup. *)
  Lemma run_model_term : forall (M : model (V := V.t)) nu s t c,
    term_value s t c ->
    model_term M (fun x => option_map (den nu) (s x)) t (den nu c).
  Proof.
    intros M nu s [x|v] c Hterm; cbn [term_value model_term] in *.
    - now rewrite Hterm.
    - subst c. reflexivity.
  Qed.

  (** Interpreting an argument list preserves each term witness. *)
  Lemma run_model_terms : forall (M : model (V := V.t)) nu s ts cs,
    terms_value s ts cs ->
    Forall2 (model_term M (fun x => option_map (den nu) (s x))) ts (map (den nu) cs).
  Proof.
    intros M nu s ts cs Hterms. induction Hterms; cbn [map]; constructor; auto.
    now apply run_model_term.
  Qed.

  (** Value-only argument lists have the same primitive inputs after interpretation. *)
  Lemma run_model_values : forall (M : model (V := V.t)) nu cs vs,
    values cs vs -> model_values M (map (den nu) cs) vs.
  Proof.
    intros M nu cs vs Hvalues. induction Hvalues; cbn [map]; constructor; auto.
    subst x. reflexivity.
  Qed.

  (** Every satisfied concrete query atom is true in a model of its view. *)
  Lemma run_model_atom : forall (M : model (V := V.t)) nu w kinds s a,
    (forall f, kind w f = kinds f) -> sat V.merge M nu w ->
    atom_holds V.prim w s a ->
    model_atom V.prim M kinds (fun x => option_map (den nu) (s x)) a.
  Proof.
    intros M nu w kinds s [f args res|p args res] Hkind [Hrows Hsat] Hatom;
      cbn [atom_holds model_atom] in *.
    - destruct Hatom as [k [o [Hterms [Hresult Hrow]]]].
      exists (map (den nu) k). split; [now apply run_model_terms|].
      specialize (Hrows f k o Hrow). unfold holds in Hrows. rewrite Hkind in Hrows.
      destruct (kinds f) as [out|]; [|contradiction].
      destruct out; destruct o as [[i|v]|]; cbn in Hrows; try contradiction.
      + destruct res as [t|]; [contradiction|exact Hrows].
      + destruct res as [t|]; [|contradiction]. rewrite Hrows.
        exact (run_model_term M nu s t (Id i) Hresult).
      + destruct res as [t|]; [|contradiction]. exists v. split.
        * exact (run_model_term M nu s t (Val v) Hresult).
        * exact Hrows.
    - destruct Hatom as [k [vs [v [Hterms [Hvalues [Hprim Hresult]]]]]].
      exists (map (den nu) k), vs, v. split; [now apply run_model_terms|].
      split; [now apply run_model_values|]. split; [exact Hprim|].
      exact (run_model_term M nu s res (Val v) Hresult).
  Qed.

  Lemma matched_atoms_model : forall (M : model (V := V.t)) nu p cp db q s,
    D.wf db -> loaded p cp db -> sat V.merge M nu (D.view db) ->
    matches V.prim (D.view db) q s ->
    Forall (model_atom V.prim M (program_kind p) (fun x => option_map (den nu) (s x))) q.
  Proof.
    intros M nu p cp db q s Hwf [Hkind Hloaded] Hsat Hmatch.
    eapply Forall_impl; [|exact Hmatch]. intros a Hatom.
    eapply run_model_atom; eassumption.
  Qed.


  (** A concrete term determines its value in the interpreted environment. *)
  Lemma run_model_term_unique : forall (M : model (V := V.t)) nu s t c value,
    term_value s t c -> model_term M (fun x => option_map (den nu) (s x)) t value ->
    value = den nu c.
  Proof.
    intros M nu s [x|v] c value Hcell Hvalue; cbn [term_value model_term] in *.
    - rewrite Hcell in Hvalue. now injection Hvalue.
    - subst c value. reflexivity.
  Qed.

  (** Concrete argument witnesses determine the model's argument list. *)
  Lemma run_model_terms_unique : forall (M : model (V := V.t)) nu s ts cs values,
    terms_value s ts cs ->
    Forall2 (model_term M (fun x => option_map (den nu) (s x))) ts values ->
    values = map (den nu) cs.
  Proof.
    intros M nu s ts cs values Hterms. revert values.
    induction Hterms as [|t c rest cells Hterm Hterms IH]; intros vals Hvals.
    - inversion Hvals. reflexivity.
    - inversion Hvals as [|t' v rest' vals' Hvalue Htail]; subst t' rest' vals.
      cbn [map]. f_equal; [eapply run_model_term_unique; eassumption|now apply IH].
  Qed.

  (** Concrete value arguments determine the primitive inputs in the model. *)
  Lemma run_model_values_unique : forall (M : model (V := V.t)) nu cs vs ws,
    values cs vs -> model_values M (map (den nu) cs) ws -> ws = vs.
  Proof.
    intros M nu cs vs ws Hvalues. revert ws.
    induction Hvalues as [|c v cells vals Hcell Hvalues IH]; intros ws Hmodel.
    - inversion Hmodel. reflexivity.
    - subst c. inversion Hmodel as [|c' w cells' ws' Hhead Htail]; subst c' cells' ws.
      cbn [den] in Hhead. injection Hhead as <-. f_equal. now apply IH.
  Qed.

  (** Interpreting a sorted environment preserves its sorts. *)
  Lemma run_model_env_sorted : forall (M : model (V := V.t)) nu g s,
    env_sorted g s -> model_env_sorted M g (fun x => option_map (den nu) (s x)).
  Proof.
    intros M nu g s Henv x ty Htype.
    destruct (Henv x ty Htype) as [c [Hlookup Hsort]].
    exists (den nu c). rewrite Hlookup. split; [reflexivity|].
    destruct c; exact Hsort.
  Qed.

  (** Pointwise agreement preserves a model term. *)
  Lemma run_model_term_agree : forall (M : model (V := V.t)) s t term value,
    (forall x, s x = t x) -> model_term M s term value -> model_term M t term value.
  Proof.
    intros M s t [x|v] value Henv Hterm.
    - cbn [model_term] in *. now rewrite <- Henv.
    - exact Hterm.
  Qed.

  (** Pointwise agreement preserves a list of model terms. *)
  Lemma run_model_terms_agree : forall (M : model (V := V.t)) s t terms values,
    (forall x, s x = t x) -> Forall2 (model_term M s) terms values ->
    Forall2 (model_term M t) terms values.
  Proof.
    intros M s t terms values Henv Hterms. induction Hterms; constructor; auto.
    eapply run_model_term_agree; eassumption.
  Qed.

  (** A common assignment preserves pointwise model-environment agreement. *)
  Lemma run_model_update_agree : forall (M : model (V := V.t)) s t x c,
    (forall y, s y = t y) ->
    forall y, model_update M s x c y = model_update M t x c y.
  Proof.
    intros M s t x c Henv y. unfold model_update. destruct (Pos.eqb x y); auto.
  Qed.

  (** Model action semantics depends only on pointwise environment observations. *)
  Lemma run_model_actions_agree : forall (M : model (V := V.t)) kinds acts s t,
    (forall x, s x = t x) -> model_actions V.prim M kinds s acts ->
    model_actions V.prim M kinds t acts.
  Proof.
    intros M kinds acts. induction acts as [|a rest IH]; intros s t Henv Hacts;
      [exact I|].
    destruct a as [x f args|f args res|a b|x p args]; cbn [model_actions] in *.
    - destruct Hacts as [k [Hargs [Hkind Hrest]]]. exists k. split.
      + eapply run_model_terms_agree; eassumption.
      + split; [exact Hkind|]. eapply IH; [apply run_model_update_agree; exact Henv|exact Hrest].
    - destruct Hacts as [k [Hargs [Hput Hrest]]]. exists k. split.
      + eapply run_model_terms_agree; eassumption.
      + split; [|eapply IH; eassumption].
        destruct (kinds f) as [out|]; [|contradiction].
        destruct out; destruct res as [term|]; try contradiction; try exact Hput.
        * eapply run_model_term_agree; eassumption.
        * destruct Hput as [v [Hterm Hlat]]. exists v. split;
            [eapply run_model_term_agree; eassumption|exact Hlat].
    - destruct Hacts as [c [d [Ha [Hb [Hsame Hrest]]]]]. exists c, d. split.
      + eapply run_model_term_agree; eassumption.
      + split; [eapply run_model_term_agree; eassumption|].
        split; [exact Hsame|eapply IH; eassumption].
    - destruct Hacts as [k [vs [Hargs [Hvalues Hrest]]]]. exists k, vs. split.
      + eapply run_model_terms_agree; eassumption.
      + split; [exact Hvalues|]. destruct (V.prim p vs); [|exact I].
        eapply IH; [apply run_model_update_agree; exact Henv|exact Hrest].
  Qed.

  (** A true model function atom justifies the corresponding concrete insertion. *)
  Lemma run_model_fun_holds : forall (M : model (V := V.t)) nu s w kinds f args res k o,
    (forall g, kind w g = kinds g) -> terms_value s args k ->
    (match res, o with
     | None, None => True
     | Some t, Some c => term_value s t c
     | _, _ => False
     end) ->
    model_atom V.prim M kinds (fun x => option_map (den nu) (s x))
      (Fun V.t f args res) -> holds M nu w f k o.
  Proof.
    intros M nu s w kinds f args res k o Hkind Hargs Hres [vals [Hvals Hhead]].
    pose proof (run_model_terms_unique M nu s args k vals Hargs Hvals) as Hlist.
    subst vals. unfold holds. rewrite Hkind.
    destruct (kinds f) as [out|]; [|contradiction].
    destruct out; destruct res as [term|]; try contradiction.
    - destruct o; [contradiction|exact Hhead].
    - destruct o as [[i|v]|]; [| |contradiction].
      + pose proof (run_model_term_unique M nu s term (Id i) _ Hres Hhead) as Hvalue.
        now injection Hvalue.
      + pose proof (run_model_term_unique M nu s term (Val v) _ Hres Hhead) as Hvalue.
        discriminate Hvalue.
    - destruct Hhead as [v [Hterm Hlat]]. destruct o as [[i|w']|]; [| |contradiction].
      + pose proof (run_model_term_unique M nu s term (Id i) _ Hres Hterm) as Hvalue.
        discriminate Hvalue.
      + pose proof (run_model_term_unique M nu s term (Val w') _ Hres Hterm) as Hvalue.
        injection Hvalue as ->. exact Hlat.
  Qed.

  (** Canonical representatives have their identifiers' original model meaning. *)
  Lemma run_canon_den : forall (M : model (V := V.t)) nu db c,
    D.wf db -> sat V.merge M nu (D.view db) -> den nu (D.canon db c) = den nu c.
  Proof.
    intros M nu db [i|v] Hwf [_ [Hsame Hlat]]; [|reflexivity].
    cbn [D.canon den]. f_equal. apply Hsame.
    apply (proj2 (D.same_repr db (D.repr db i) i Hwf)). now rewrite D.repr_idem.
  Qed.

  (** Canonicalizing arguments preserves their full interpreted key. *)
  Lemma run_canon_key_den : forall (M : model (V := V.t)) nu db k,
    D.wf db -> sat V.merge M nu (D.view db) ->
    map (den nu) (map (D.canon db) k) = map (den nu) k.
  Proof.
    intros M nu db k Hwf Hsat. rewrite map_map. apply map_ext.
    intro c. now apply run_canon_den.
  Qed.

  (** Constructor allocation extends the interpretation of every old allocated identifier. *)
  Lemma run_make_model : forall (M : model (V := V.t)) nu db f k i next,
    D.wf db -> kind (D.view db) f = Some OId ->
    (forall j, In (Id j) k -> D.allocated db j) -> sat V.merge M nu (D.view db) ->
    D.make f k db = (i, next) ->
    exists nu', extends db M nu nu' /\
      nu' i = con M f (map (den nu) k) /\ sat V.merge M nu' (D.view next).
  Proof.
    intros M nu db f k i next Hwf Hkind Hallocated Hsat Hmake.
    pose proof (D.make_spec f k db Hwf Hkind) as Hspec.
    pose proof (D.make_sat M nu db f k Hwf Hkind Hallocated Hsat) as Hmodel.
    rewrite Hmake in Hspec, Hmodel.
    destruct Hmodel as [nu' [Hother [Hmeaning Hsat']]].
    exists nu'. split; [|split; assumption].
    intros j Hj. destruct (Pos.eq_dec j i) as [->|Hdifferent]; [|now apply Hother].
    destruct Hspec as [[old [Hrow [Hrepr Hnext]]]|[Hfresh Hnew]].
    - pose proof (proj1 Hsat f (map (D.canon db) k) (Some (Id old)) Hrow) as Hholds.
      unfold holds in Hholds. rewrite Hkind in Hholds.
      rewrite (run_canon_key_den M nu db k Hwf Hsat) in Hholds.
      rewrite Hmeaning, Hholds, Hrepr.
      destruct Hsat as [_ [Hequal _]]. symmetry. apply Hequal.
      apply (proj2 (D.same_repr db (D.repr db old) old Hwf)). now rewrite D.repr_idem.
    - unfold D.fresh_id in Hfresh. unfold D.allocated in Hj. rewrite Hfresh in Hj.
      rewrite N.succ_pos_spec in Hj. lia.
  Qed.

  (** An interpretation extension preserves every allocated environment observation. *)
  Lemma run_env_den_ext : forall (M : model (V := V.t)) nu nu' db s,
    extends db M nu nu' -> env_allocated db s ->
    forall x, option_map (den nu') (s x) = option_map (den nu) (s x).
  Proof.
    intros M nu nu' db s Hext Hallocated x. destruct (s x) as [[i|v]|] eqn:Hlookup;
      [|reflexivity|reflexivity].
    cbn [option_map den]. rewrite Hext; [reflexivity|eapply Hallocated; exact Hlookup].
  Qed.

  (** Extensions through growing identifier counters compose on the original allocation. *)
  Lemma run_extends_trans : forall (M : model (V := V.t)) before middle nu nu' nu'',
    (D.ids before <= D.ids middle)%N -> extends before M nu nu' ->
    extends middle M nu' nu'' -> extends before M nu nu''.
  Proof.
    intros M before middle nu nu' nu'' Hids Hfirst Hsecond i Hallocated.
    rewrite Hsecond; [now apply Hfirst|]. unfold D.allocated in *. lia.
  Qed.

  (** Executing true typed actions preserves a model while extending allocated meanings. *)
  Lemma run_apply_go_sat : forall p cp (M : model (V := V.t)) acts g s locals db nu,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    model_actions V.prim M (program_kind p)
      (fun x => option_map (den nu) (look s locals x)) acts ->
    sat V.merge M nu (D.view db) ->
    exists nu', extends db M nu nu' /\ sat V.merge M nu' (D.view (apply_go acts s locals db)).
  Proof.
    intros p cp M acts. induction acts as [|a rest IH]; intros g s locals db nu
      Hchecked Hwf Hloaded Hacts Henv Hallocated Hmodel Hsat.
    - exists nu. split; [intros i Hi; reflexivity|exact Hsat].
    - destruct a as [x f args|f args res|t u|x op args];
        cbn [actions_ok] in Hacts; cbn [model_actions] in Hmodel.
      + destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]].
        destruct (run_term_cells_typed g s locals args ss Henv Hargs)
          as [cells [Hcells Hsorts]].
        rewrite <- Hsorts in Hsort.
        pose proof (run_term_cells_allocated db s locals args cells Hallocated Hcells) as Hids.
        destruct Hmodel as [vals [Hvals [Hmodelkind Hmodelrest]]].
        pose proof (run_model_terms_unique M nu (look s locals) args cells vals
          (proj1 (run_term_cells_spec s locals args cells) Hcells) Hvals) as Hargsmodel.
        subst vals.
        pose proof (run_make_state p cp f cells db Hchecked Hwf Hloaded Hkind Hsort Hids)
          as Hstate.
        destruct (D.make f cells db) as [i next] eqn:Hmake. cbn [fst snd] in Hstate.
        destruct Hstate as [Hwf' [Hloaded' [Hids' [Hnew Hpending]]]].
        assert (Hkinddb : kind (D.view db) f = Some OId).
        { rewrite (proj1 Hloaded). exact Hkind. }
        destruct (run_make_model M nu db f cells i next Hwf Hkinddb Hids Hsat Hmake)
          as [middle [Hextension [Hmeaning Hsat']]].
        assert (Henv' : env_sorted (ctx_set g x SId)
            (look s (PTrieCode.set x (Id i) locals))).
        { apply run_env_sorted_set; [exact Henv|reflexivity]. }
        assert (Hallocated' : env_allocated next (look s (PTrieCode.set x (Id i) locals))).
        { apply run_env_allocated_set.
          - eapply run_env_allocated_mono; [exact Hids'|exact Hallocated].
          - intros j Heq. injection Heq as <-. exact Hnew. }
        assert (Hmodel' : model_actions V.prim M (program_kind p)
            (fun y => option_map (den middle) (look s (PTrieCode.set x (Id i) locals) y)) rest).
        { eapply run_model_actions_agree; [|exact Hmodelrest].
          intro y. rewrite run_look_set. unfold model_update, update.
          destruct (Pos.eqb x y).
          - cbn [option_map den]. now rewrite Hmeaning.
          - symmetry. eapply run_env_den_ext; eassumption. }
        destruct (IH _ _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv' Hallocated' Hmodel' Hsat')
          as [final [Hfinal Hsatfinal]].
        cbn [apply_go]. rewrite Hcells, Hmake. exists final. split.
        * eapply run_extends_trans; eassumption.
        * exact Hsatfinal.
      + destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
        destruct (run_term_cells_typed g s locals args ss Henv Hargs)
          as [cells [Hcells Hsorts]].
        destruct (run_result_cell_typed g s locals out res Henv Hresult)
          as [output [Houtput Houtsort]].
        assert (Hrow : row_sorted (program_sorts p) (program_kind p) f cells output).
        { exists out. rewrite Hsorts. repeat split; assumption. }
        assert (Hids : forall i, In (Id i) (cells ++ option_list output) -> D.allocated db i).
        { intros i Hin. apply in_app_iff in Hin as [Hin|Hin].
          - eapply run_term_cells_allocated; eauto.
          - eapply run_result_cell_allocated; eauto. }
        pose proof (run_put_allowed p cp db f cells output Hchecked Hloaded Hrow Hids)
          as Hallowed.
        destruct (run_put_state p cp f cells output db Hchecked Hwf Hloaded Hrow Hids)
          as [Hwf' [Hloaded' [Hids' Hpending]]].
        destruct Hmodel as [vals [Hvals [Hput Hmodelrest]]].
        assert (Hholds : holds M nu (D.view db) f cells output).
        { eapply run_model_fun_holds.
          - exact (proj1 Hloaded).
          - apply run_term_cells_spec. exact Hcells.
          - apply run_result_cell_spec. exact Houtput.
          - exists vals. split; assumption. }
        pose proof (D.put_sat M nu db f cells output Hwf Hallowed Hsat Hholds) as Hsat'.
        assert (Hallocated' : env_allocated (D.put f cells output db) (look s locals)).
        { eapply run_env_allocated_mono with (db := db);
            [rewrite Hids'; reflexivity|exact Hallocated]. }
        destruct (IH _ _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated' Hmodelrest Hsat')
          as [final [Hfinal Hsatfinal]].
        cbn [apply_go]. rewrite Hcells, Houtput. exists final. split.
        * intros i Hi. apply Hfinal. unfold D.allocated in *. now rewrite Hids'.
        * exact Hsatfinal.
      + destruct Hacts as [Ht [Hu Hrest]].
        destruct (run_term_cell_typed g s locals t SId Henv Ht)
          as [[i|v] [Hi Hitype]]; [|discriminate].
        destruct (run_term_cell_typed g s locals u SId Henv Hu)
          as [[j|v] [Hj Hjtype]]; [|discriminate].
        pose proof (run_term_cell_allocated db s locals t i Hallocated Hi) as Hiall.
        pose proof (run_term_cell_allocated db s locals u j Hallocated Hj) as Hjall.
        destruct (run_union_state p cp i j db Hwf Hloaded Hiall Hjall)
          as [Hwf' [Hloaded' [Hids' Hpending]]].
        destruct Hmodel as [a [b [Hma [Hmb [Hequal Hmodelrest]]]]].
        pose proof (run_model_term_unique M nu (look s locals) t (Id i) a
          (proj1 (run_term_cell_spec s locals t (Id i)) Hi) Hma) as Ha.
        pose proof (run_model_term_unique M nu (look s locals) u (Id j) b
          (proj1 (run_term_cell_spec s locals u (Id j)) Hj) Hmb) as Hb.
        rewrite Ha, Hb in Hequal. change (nu i = nu j) in Hequal.
        pose proof (D.union_sat M nu db i j Hwf Hsat Hequal) as Hsat'.
        assert (Hallocated' : env_allocated (D.union i j db) (look s locals)).
        { eapply run_env_allocated_mono with (db := db);
            [rewrite Hids'; reflexivity|exact Hallocated]. }
        destruct (IH _ _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated' Hmodelrest Hsat')
          as [final [Hfinal Hsatfinal]].
        cbn [apply_go]. rewrite Hi, Hj. exists final. split.
        * intros k Hk. apply Hfinal. unfold D.allocated in *. now rewrite Hids'.
        * exact Hsatfinal.
      + destruct Hacts as [Hargs Hrest].
        destruct (run_term_values_typed g s locals args Henv Hargs) as [vs Hvalues].
        destruct Hmodel as [vals [inputs [Hvals [Hinputs Hmodelrest]]]].
        pose proof (run_term_values_spec s locals args vs Hvalues) as Hcells.
        pose proof (run_model_terms_unique M nu (look s locals) args (map Val vs) vals
          Hcells Hvals) as Hlist. subst vals.
        pose proof (run_model_values_unique M nu (map Val vs) vs inputs
          (run_value_cells vs) Hinputs) as Hinputs_eq. subst inputs.
        cbn [apply_go]. rewrite Hvalues. destruct (V.prim op vs) as [v|] eqn:Hprim.
        * assert (Henv' : env_sorted (ctx_set g x SVal)
              (look s (PTrieCode.set x (Val v) locals))).
          { apply run_env_sorted_set; [exact Henv|reflexivity]. }
          assert (Hallocated' : env_allocated db (look s (PTrieCode.set x (Val v) locals))).
          { apply run_env_allocated_set; [exact Hallocated|]. intros i Heq. discriminate. }
          assert (Hmodel' : model_actions V.prim M (program_kind p)
              (fun y => option_map (den nu) (look s (PTrieCode.set x (Val v) locals) y)) rest).
          { eapply run_model_actions_agree; [|exact Hmodelrest].
            intro y. rewrite run_look_set. unfold model_update, update.
            destruct (Pos.eqb x y); reflexivity. }
          destruct (IH _ _ _ _ _ Hchecked Hwf Hloaded Hrest Henv' Hallocated' Hmodel' Hsat)
            as [final [Hfinal Hsatfinal]].
          exists final. split; assumption.
        * exists nu. split; [intros i Hi; reflexivity|exact Hsat].
  Qed.

  Lemma apply_preserves_sat : forall (M : model (V := V.t)) nu p cp r s db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> env_allocated db s ->
    rule_env (program_sorts p) (program_kind p) r s ->
    valid_sorted V.prim V.merge M p -> In r (rules V.t p) ->
    Forall (model_atom V.prim M (program_kind p) (fun x => option_map (den nu) (s x)))
      (query V.t r) ->
    sat V.merge M nu (D.view db) ->
    exists nu', extends db M nu nu' /\
      sat V.merge M nu' (D.view (apply (actions V.t r) s db)).
  Proof.
    intros M nu p cp r s db Hchecked Hwf Hloaded Hallocated Henv [Hvalid Hlat] Hin
      Hmatch Hsat.
    destruct (run_rule_context p cp r s Hchecked Hin Henv) as [g [Hquery [Hacts Hsorted]]].
    pose proof ((proj1 (Forall_forall _ _)) Hvalid r Hin) as Hrule.
    specialize (Hrule g (fun x => option_map (den nu) (s x)) Hquery
      (run_model_env_sorted M nu g s Hsorted) Hmatch).
    unfold apply. eapply run_apply_go_sat;
      [exact Hchecked|exact Hwf|exact Hloaded|exact Hacts| | | |exact Hsat].
    - intros x ty Hctx. destruct (Hsorted x ty Hctx) as [c [Hc Hty]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated. exact Hcell.
    - eapply run_model_actions_agree; [|exact Hrule].
      intro x. now rewrite run_look_empty.
  Qed.


  (** Database equality is reflexive on every identifier. *)
  Lemma run_same_refl : forall db i, D.wf db -> same (D.view db) i i.
  Proof.
    intros db i Hwf. apply (proj2 (D.same_repr db i i Hwf)). reflexivity.
  Qed.

  (** Database equality composes through representatives. *)
  Lemma run_same_trans : forall db i j k, D.wf db ->
    same (D.view db) i j -> same (D.view db) j k -> same (D.view db) i k.
  Proof.
    intros db i j k Hwf Hij Hjk. apply (proj2 (D.same_repr db i k Hwf)).
    apply (proj1 (D.same_repr db i j Hwf)) in Hij.
    apply (proj1 (D.same_repr db j k Hwf)) in Hjk. congruence.
  Qed.

  (** Canonicalizing the source output leaves output containment unchanged. *)
  Lemma run_out_canon_left : forall db f a b, D.wf db ->
    (D.out_le db f (option_map (D.canon db) a) b <-> D.out_le db f a b).
  Proof.
    intros db f [[i|a]|] [[j|b]|] Hwf;
      cbn [D.out_le option_map D.canon cell_le]; try reflexivity.
    rewrite (D.same_repr db (D.repr db i) j Hwf), (D.same_repr db i j Hwf).
    now rewrite D.repr_idem.
  Qed.

  (** Enlarging equality while keeping kinds preserves output containment. *)
  Lemma run_out_le_mono : forall db next f a b,
    (forall g, kind (D.view next) g = kind (D.view db) g) ->
    (forall i j, same (D.view db) i j -> same (D.view next) i j) ->
    D.out_le db f a b -> D.out_le next f a b.
  Proof.
    intros db next f [[i|a]|] [[j|b]|] Hkind Hsame Hle;
      cbn [D.out_le cell_le] in *; try contradiction; try exact I.
    - now apply Hsame.
    - destruct Hle as [m [Hdecl Hmerge]]. exists m.
      split; [now rewrite Hkind|exact Hmerge].
  Qed.

  (** Output containment composes using equality and the semilattice merge laws. *)
  Lemma run_out_le_trans : forall db f a b c, D.wf db ->
    D.out_le db f a b -> D.out_le db f b c -> D.out_le db f a c.
  Proof.
    intros db f [a|] [b|] [c|] Hwf Hab Hbc;
      cbn [D.out_le] in *; try contradiction; try exact I.
    destruct a as [i|a], b as [j|b], c as [k|c]; cbn [cell_le] in *; try contradiction.
    - eapply run_same_trans; eassumption.
    - destruct Hab as [m [Hkind Hab]], Hbc as [n [Hkind' Hbc]].
      assert (Hequal : m = n) by congruence. subst n. exists m. split; [exact Hkind|].
      rewrite <- Hbc at 1. rewrite V.merge_assoc, Hab. exact Hbc.
  Qed.

  (** Enlarging identifier equality preserves a related pair of cells. *)
  Lemma run_cell_rel_mono : forall db next (a b : cell V.t),
    (forall i j, same (D.view db) i j -> same (D.view next) i j) ->
    cell_rel (same (D.view db)) a b -> cell_rel (same (D.view next)) a b.
  Proof.
    intros db next a b Hsame Hrel. destruct Hrel; constructor; auto.
  Qed.

  (** Enlarging identifier equality preserves related keys. *)
  Lemma run_key_rel_mono : forall db next (a b : list (cell V.t)),
    (forall i j, same (D.view db) i j -> same (D.view next) i j) ->
    Forall2 (cell_rel (same (D.view db))) a b ->
    Forall2 (cell_rel (same (D.view next))) a b.
  Proof.
    intros db next a b Hsame Hrel. induction Hrel; constructor; auto.
    eapply run_cell_rel_mono; eassumption.
  Qed.

  (** Every key is related to itself in a well-formed database. *)
  Lemma run_key_rel_refl : forall db (k : list (cell V.t)), D.wf db ->
    Forall2 (cell_rel (same (D.view db))) k k.
  Proof.
    intros db k Hwf. induction k as [|c rest IH]; [constructor|].
    constructor; [|exact IH]. destruct c as [i|v].
    - constructor. now apply run_same_refl.
    - constructor.
  Qed.

  (** Cell relatedness composes in a well-formed database. *)
  Lemma run_cell_rel_trans : forall db (a b c : cell V.t), D.wf db ->
    cell_rel (same (D.view db)) a b -> cell_rel (same (D.view db)) b c ->
    cell_rel (same (D.view db)) a c.
  Proof.
    intros db a b c Hwf Hab Hbc. destruct Hab.
    - inversion Hbc; subst. constructor. eapply run_same_trans; eassumption.
    - inversion Hbc; subst. constructor.
  Qed.

  (** Key relatedness composes in a well-formed database. *)
  Lemma run_key_rel_trans : forall db (a b c : list (cell V.t)), D.wf db ->
    Forall2 (cell_rel (same (D.view db))) a b ->
    Forall2 (cell_rel (same (D.view db))) b c ->
    Forall2 (cell_rel (same (D.view db))) a c.
  Proof.
    intros db a b c Hwf Hab. revert c.
    induction Hab as [|a b rest more Hab Hrest IH]; intros c Hbc.
    - inversion Hbc. constructor.
    - inversion Hbc as [|b' c' more' tail Hhead Htail]; subst b' more' c.
      constructor; [eapply run_cell_rel_trans; eassumption|now apply IH].
  Qed.

  (** A well-sorted row contains its own output. *)
  Lemma run_row_out_refl : forall sorts db f k o, D.wf db ->
    row_sorted sorts (kind (D.view db)) f k o ->
    D.out_le db f (option_map (D.canon db) o) o.
  Proof.
    intros sorts db f k o Hwf [out [_ [Hkind Hout]]].
    apply (proj2 (run_out_canon_left db f o o Hwf)).
    destruct o as [[i|v]|]; cbn [D.out_le cell_le]; [now apply run_same_refl| |exact I].
    destruct out as [| |m]; cbn [out_sort option_map cell_sort] in Hout; try discriminate.
    exists m. split; [exact Hkind|apply V.merge_idem].
  Qed.

  (** A sorted database grows to itself. *)
  Lemma run_grows_upto_refl : forall sorts db, D.wf db ->
    view_sorted sorts (D.view db) -> grows_upto db db.
  Proof.
    intros sorts db Hwf Hsorted. split; [auto|]. intros f k o Hrow.
    exists k, o. split; [exact Hrow|]. split; [now apply run_key_rel_refl|].
    eapply run_row_out_refl; [exact Hwf|eapply Hsorted; exact Hrow].
  Qed.

  (** Growth composes when later states keep kinds and remain well formed. *)
  Lemma run_grows_upto_trans : forall before middle after,
    D.wf middle -> D.wf after ->
    (forall f, kind (D.view after) f = kind (D.view middle) f) ->
    grows_upto before middle -> grows_upto middle after -> grows_upto before after.
  Proof.
    intros before middle after Hwfmid Hwfafter Hkinds [Hsame1 Hrows1] [Hsame2 Hrows2].
    split; [intros i j Hsame; apply Hsame2; now apply Hsame1|].
    intros f k o Hrow. destruct (Hrows1 f k o Hrow) as [k1 [o1 [Hrow1 [Hkey1 Hout1]]]].
    destruct (Hrows2 f k1 o1 Hrow1) as [k2 [o2 [Hrow2 [Hkey2 Hout2]]]].
    exists k2, o2. split; [exact Hrow2|]. split.
    - eapply run_key_rel_trans; [exact Hwfafter| |exact Hkey2].
      eapply run_key_rel_mono; eassumption.
    - apply (proj2 (run_out_canon_left after f o o2 Hwfafter)).
      eapply run_out_le_trans; [exact Hwfafter| |].
      + eapply run_out_le_mono; [exact Hkinds|exact Hsame2|].
        exact (proj1 (run_out_canon_left middle f o o1 Hwfmid) Hout1).
      + exact (proj1 (run_out_canon_left after f o1 o2 Hwfafter) Hout2).
  Qed.

  (** The value equality test also decides equality of complete cells. *)
  Lemma run_cell_eq_dec : forall a b : cell V.t, {a = b} + {a <> b}.
  Proof.
    intros a b. destruct (run_cell_eqb_spec a b); [left|right]; assumption.
  Qed.

  (** Combining a row's existing output with another output retains the old information. *)
  Lemma run_combine_old : forall sorts db next f k old o,
    D.wf next -> (forall g, kind (D.view next) g = kind (D.view db) g) ->
    row_sorted sorts (kind (D.view db)) f k old ->
    D.out_le next f old (D.combine db f (Some old) o).
  Proof.
    intros sorts db next f k old o Hwf Hkinds [out [_ [Hkind Hout]]].
    destruct old as [[i|v]|]; [| |exact I].
    - destruct out as [| |m]; cbn [out_sort option_map cell_sort] in Hout;
        try discriminate.
      cbn [D.combine D.out_le cell_le]. now apply run_same_refl.
    - destruct out as [| |m]; cbn [out_sort option_map cell_sort] in Hout;
        try discriminate.
      unfold D.combine. rewrite Hkind. destruct o as [[j|w]|]; cbn [D.out_le cell_le].
      + exists m. split; [rewrite Hkinds; exact Hkind|apply V.merge_idem].
      + exists m. split; [rewrite Hkinds; exact Hkind|].
        rewrite V.merge_assoc, V.merge_idem. reflexivity.
      + exists m. split; [rewrite Hkinds; exact Hkind|apply V.merge_idem].
  Qed.

  (** A well-typed insertion preserves every old row and equality up to output growth. *)
  Lemma run_put_grows : forall sorts f k o db, D.wf db -> D.kind_ok db f k o ->
    view_sorted sorts (D.view db) -> grows_upto db (D.put f k o db).
  Proof.
    intros sorts f k o db Hwf Hallowed Hsorted.
    pose proof (D.wf_put f k o db Hwf Hallowed) as Hnext.
    pose proof (proj1 (D.layout_put f k o db Hwf)) as Hkinds.
    split.
    - intros i j Hsame. apply (proj2 (D.put_same f k o db i j Hwf Hallowed)).
      apply rst_step. now left.
    - intros g key old Hrow.
      assert (Hchoice : (g, key) = (f, map (D.canon db) k) \/
          (g, key) <> (f, map (D.canon db) k)).
      { destruct (Pos.eq_dec g f) as [Hg|Hg]; [|right; congruence].
        destruct (list_eq_dec run_cell_eq_dec key (map (D.canon db) k)) as [Hk|Hk].
        - left. now subst.
        - right. congruence. }
      destruct Hchoice as [Hequal|Hother].
      + injection Hequal as Hgf Hkey. subst g key.
        assert (Hprevious : D.old db f (map (D.canon db) k) = Some old).
        { apply (proj2 (D.old_row db f (map (D.canon db) k) old Hwf)). exact Hrow. }
        exists (map (D.canon db) k),
          (D.combine db f (Some old) (option_map (D.canon db) o)).
        split.
        * apply (proj2 (D.put_rows f k o db Hwf Hallowed _ _ _)). right.
          split; [reflexivity|]. split; [reflexivity|]. now rewrite Hprevious.
        * split; [now apply run_key_rel_refl|].
          apply (proj2 (run_out_canon_left (D.put f k o db) f old _ Hnext)).
          eapply run_combine_old; [exact Hnext|intro h; now rewrite Hkinds|].
          apply Hsorted. exact Hrow.
      + exists key, old. split.
        * apply (proj2 (D.put_rows f k o db Hwf Hallowed _ _ _)). now left.
        * split; [now apply run_key_rel_refl|].
          eapply run_row_out_refl; [exact Hnext|].
          unfold row_sorted. rewrite Hkinds. apply Hsorted. exact Hrow.
  Qed.

  (** Constructor allocation preserves every old row and equality. *)
  Lemma run_make_grows : forall sorts f k db, D.wf db ->
    D.wf (snd (D.make f k db)) -> kind (D.view db) f = Some OId ->
    view_sorted sorts (D.view db) -> grows_upto db (snd (D.make f k db)).
  Proof.
    intros sorts f k db Hwf Hnext Hkind Hsorted.
    pose proof (D.make_spec f k db Hwf Hkind) as Hmake.
    destruct (D.make f k db) as [i next]. cbn [snd] in Hnext |- *.
    destruct Hmake as [[j [_ [_ ->]]]|[_ [_ [_ [Hkinds [Hsame Hrows]]]]]].
    - now apply (run_grows_upto_refl sorts).
    - split.
      + intros a b Hab. apply (proj2 (Hsame a b)). now left.
      + intros g key old Hrow. exists key, old. split.
        * apply (proj2 (Hrows g key old)). now left.
        * split; [now apply run_key_rel_refl|].
          eapply run_row_out_refl; [exact Hnext|].
          unfold row_sorted. rewrite Hkinds. apply Hsorted. exact Hrow.
  Qed.

  (** Identifier union preserves every old row and equality. *)
  Lemma run_union_grows : forall sorts i j db, D.wf db -> D.wf (D.union i j db) ->
    view_sorted sorts (D.view db) -> grows_upto db (D.union i j db).
  Proof.
    intros sorts i j db Hwf Hnext Hsorted. split.
    - intros a b Hab. apply (proj2 (D.union_same i j db a b Hwf)).
      apply rst_step. now left.
    - intros f k o Hrow. exists k, o. split.
      + rewrite (D.union_rows i j db Hwf). exact Hrow.
      + split; [now apply run_key_rel_refl|]. eapply run_row_out_refl; [exact Hnext|].
        unfold row_sorted. rewrite (proj1 (D.layout_union i j db Hwf)).
        apply Hsorted. exact Hrow.
  Qed.

  (** Growth composes between states loaded for the same program and compiled plan. *)
  Lemma run_loaded_growth_trans : forall p cp before db next,
    D.wf db -> D.wf next -> loaded p cp db -> loaded p cp next ->
    grows_upto before db -> grows_upto db next -> grows_upto before next.
  Proof.
    intros p cp before db next Hwf Hnext Hloaded Hloadnext Hbefore Hstep.
    eapply run_grows_upto_trans; [exact Hwf|exact Hnext| |exact Hbefore|exact Hstep].
    intro f. rewrite (proj1 Hloadnext), (proj1 Hloaded). reflexivity.
  Qed.

  (** Typed actions preserve growth from any earlier database. *)
  Lemma run_apply_go_grows : forall p cp acts g s locals db before,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    grows_upto before db -> grows_upto before (apply_go acts s locals db).
  Proof.
    intros p cp acts. induction acts as [|a rest IH]; intros g s locals db before
      Hchecked Hwf Hloaded Hacts Henv Hallocated Hbefore; [exact Hbefore|].
    destruct a as [x f args|f args res|t u|x op args]; cbn [actions_ok] in Hacts.
    - destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]].
      destruct (run_term_cells_typed g s locals args ss Henv Hargs)
        as [cells [Hcells Hsorts]]. rewrite <- Hsorts in Hsort.
      pose proof (run_term_cells_allocated db s locals args cells Hallocated Hcells) as Hids.
      pose proof (run_make_state p cp f cells db Hchecked Hwf Hloaded Hkind Hsort Hids)
        as Hstate.
      pose proof (run_make_grows (program_sorts p) f cells db Hwf (proj1 Hstate)
        ltac:(rewrite (proj1 Hloaded); exact Hkind) (proj2 (proj2 Hloaded))) as Hstep.
      destruct (D.make f cells db) as [i next] eqn:Hmake. cbn [fst snd] in Hstate, Hstep.
      destruct Hstate as [Hwf' [Hloaded' [Hids' [Hnew _]]]].
      cbn [apply_go]. rewrite Hcells, Hmake.
      eapply IH; [exact Hchecked|exact Hwf'|exact Hloaded'|exact Hrest| | |].
      + apply run_env_sorted_set; [exact Henv|reflexivity].
      + apply run_env_allocated_set.
        * eapply run_env_allocated_mono; [exact Hids'|exact Hallocated].
        * intros j Heq. injection Heq as <-. exact Hnew.
      + exact (run_loaded_growth_trans p cp before db next Hwf Hwf' Hloaded Hloaded'
          Hbefore Hstep).
    - destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
      destruct (run_term_cells_typed g s locals args ss Henv Hargs)
        as [cells [Hcells Hsorts]].
      destruct (run_result_cell_typed g s locals out res Henv Hresult)
        as [output [Houtput Houtsort]].
      assert (Hrow : row_sorted (program_sorts p) (program_kind p) f cells output).
      { exists out. rewrite Hsorts. repeat split; assumption. }
      assert (Hids : forall i, In (Id i) (cells ++ option_list output) -> D.allocated db i).
      { intros i Hin. apply in_app_iff in Hin as [Hin|Hin].
        - eapply run_term_cells_allocated; eauto.
        - eapply run_result_cell_allocated; eauto. }
      destruct (run_put_state p cp f cells output db Hchecked Hwf Hloaded Hrow Hids)
        as [Hwf' [Hloaded' [Hids' _]]].
      pose proof (run_put_allowed p cp db f cells output Hchecked Hloaded Hrow Hids)
        as Hallowed.
      pose proof (run_put_grows (program_sorts p) f cells output db Hwf Hallowed
        (proj2 (proj2 Hloaded))) as Hstep.
      cbn [apply_go]. rewrite Hcells, Houtput.
      eapply IH; [exact Hchecked|exact Hwf'|exact Hloaded'|exact Hrest|exact Henv| |].
      + eapply run_env_allocated_mono with (db := db);
          [rewrite Hids'; reflexivity|exact Hallocated].
      + exact (run_loaded_growth_trans p cp before db (D.put f cells output db)
          Hwf Hwf' Hloaded Hloaded' Hbefore Hstep).
    - destruct Hacts as [Ht [Hu Hrest]].
      destruct (run_term_cell_typed g s locals t SId Henv Ht)
        as [[i|v] [Hi Hitype]]; [|discriminate].
      destruct (run_term_cell_typed g s locals u SId Henv Hu)
        as [[j|v] [Hj Hjtype]]; [|discriminate].
      pose proof (run_term_cell_allocated db s locals t i Hallocated Hi) as Hiall.
      pose proof (run_term_cell_allocated db s locals u j Hallocated Hj) as Hjall.
      destruct (run_union_state p cp i j db Hwf Hloaded Hiall Hjall)
        as [Hwf' [Hloaded' [Hids' _]]].
      pose proof (run_union_grows (program_sorts p) i j db Hwf Hwf'
        (proj2 (proj2 Hloaded))) as Hstep.
      cbn [apply_go]. rewrite Hi, Hj.
      eapply IH; [exact Hchecked|exact Hwf'|exact Hloaded'|exact Hrest|exact Henv| |].
      + eapply run_env_allocated_mono with (db := db);
          [rewrite Hids'; reflexivity|exact Hallocated].
      + exact (run_loaded_growth_trans p cp before db (D.union i j db)
          Hwf Hwf' Hloaded Hloaded' Hbefore Hstep).
    - destruct Hacts as [Hargs Hrest].
      destruct (run_term_values_typed g s locals args Henv Hargs) as [vs Hvalues].
      cbn [apply_go]. rewrite Hvalues. destruct (V.prim op vs) as [v|]; [|exact Hbefore].
      eapply IH; [exact Hchecked|exact Hwf|exact Hloaded|exact Hrest| | |exact Hbefore].
      + apply run_env_sorted_set; [exact Henv|reflexivity].
      + apply run_env_allocated_set; [exact Hallocated|]. intros i Heq. discriminate.
  Qed.

  Lemma apply_grows : forall p cp r s db, plans_ok p cp -> D.wf db ->
    loaded p cp db -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s -> env_allocated db s ->
    grows_upto db (apply (actions V.t r) s db).
  Proof.
    intros p cp r s db Hchecked Hwf Hloaded Hin Henv Hallocated.
    destruct (run_rule_context p cp r s Hchecked Hin Henv) as [g [_ [Hacts Hsorted]]].
    unfold apply. eapply run_apply_go_grows; try eassumption.
    - intros x ty Hctx. destruct (Hsorted x ty Hctx) as [c [Hc Hty]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated. exact Hcell.
    - apply (run_grows_upto_refl (program_sorts p)); [exact Hwf|exact (proj2 (proj2 Hloaded))].
  Qed.

  (** Rebuilding retains every equality already present in the database. *)
  Lemma run_rebuild_same_incl : forall db i j, D.wf db ->
    same (D.view db) i j -> same (D.view (D.rebuild db)) i j.
  Proof.
    intros db i j Hwf Hsame. apply (proj2 (D.rebuild_same db i j Hwf)).
    apply cong_same. exact Hsame.
  Qed.

  (** Related old keys have identical canonical keys after rebuilding. *)
  Lemma run_rebuild_key_equal : forall db k k', D.wf db ->
    Forall2 (cell_rel (same (D.view db))) k k' ->
    map (D.canon (D.rebuild db)) k = map (D.canon (D.rebuild db)) k'.
  Proof.
    intros db k k' Hwf Hkeys. induction Hkeys as [|a b rest more Hab Htail IH].
    - reflexivity.
    - cbn [map]. rewrite IH. f_equal. destruct Hab as [i j Hij|v].
      + cbn [D.canon]. f_equal.
        apply (proj1 (D.same_repr (D.rebuild db) i j (D.wf_rebuild db Hwf))).
        apply run_rebuild_same_incl; assumption.
      + reflexivity.
  Qed.

  Lemma rebuild_grows : forall db0 db, D.wf db -> grows_upto db0 db ->
    grows db0 (D.rebuild db).
  Proof.
    intros db0 db Hwf [Hsame Hrows].
    pose proof (D.wf_rebuild db Hwf) as Hwf'.
    destruct (D.layout_rebuild db Hwf) as [Hkind Hlayout].
    assert (Hkeep : forall i j, same (D.view db) i j -> same (D.view (D.rebuild db)) i j).
    { intros i j Hij. now apply run_rebuild_same_incl. }
    split; [intros i j Hij; apply Hkeep; now apply Hsame|].
    intros f k o Hrow. destruct (Hrows f k o Hrow) as [k' [o' [Hrow' [Hkeys Hout]]]].
    destruct (D.rebuild_keeps db f k' o' Hwf Hrow') as [out [Hreb Hle]].
    exists out. split.
    - rewrite <- (run_rebuild_key_equal db k k' Hwf Hkeys) in Hreb. exact Hreb.
    - apply (proj2 (run_out_canon_left (D.rebuild db) f o out Hwf')).
      eapply run_out_le_trans; [exact Hwf'| |].
      + eapply run_out_le_mono; [intro g; now rewrite Hkind|exact Hkeep|].
        exact (proj1 (run_out_canon_left db f o o' Hwf) Hout).
      + exact (proj1 (run_out_canon_left (D.rebuild db) f o' out Hwf') Hle).
  Qed.

  (** A semantic identifier is supported when it occurs in a stored row. *)
  Definition run_supported (db : D.t) (c : cell V.t) : Prop :=
    match c with
    | Id i => exists f k o, row (D.view db) f k o /\ In (Id i) (k ++ option_list o)
    | Val _ => True
    end.

  (** Only context-bound variables need allocated action identifiers. *)
  Definition run_allocated_on (db : D.t) (g : ctx) (s : Model.env (V := V.t)) : Prop :=
    forall x ty i, g x = Some ty -> s x = Some (Id i) -> D.allocated db i.

  (** Semantic bindings use supported cells related to the evaluator's bindings. *)
  Definition run_env_related (db : D.t) (g : ctx)
      (actual semantic : Model.env (V := V.t)) : Prop :=
    forall x ty c, g x = Some ty -> actual x = Some c ->
    exists d, semantic x = Some d /\ run_supported db d /\
      cell_rel (same (D.view db)) c d.

  (** A cell occurring in a row is supported. *)
  Lemma run_row_supported : forall db f k o c, row (D.view db) f k o ->
    In c (k ++ option_list o) -> run_supported db c.
  Proof.
    intros db f k o [i|v] Hrow Hin; [exists f, k, o; now split|exact I].
  Qed.

  (** Supported identifiers are allocated in well-formed databases. *)
  Lemma run_supported_allocated : forall db i, D.wf db -> run_supported db (Id i) ->
    D.allocated db i.
  Proof.
    intros db i Hwf [f [k [o [Hrow Hin]]]]. eapply D.row_allocated; eassumption.
  Qed.

  (** Every cell is related to itself by database equality. *)
  Lemma run_cell_rel_refl : forall db (c : cell V.t), D.wf db ->
    cell_rel (same (D.view db)) c c.
  Proof.
    intros db [i|v] Hwf; constructor. now apply run_same_refl.
  Qed.

  (** Relating cells preserves their sorts. *)
  Lemma run_cell_rel_sort : forall db (c d : cell V.t), cell_rel (same (D.view db)) c d ->
    cell_sort c = cell_sort d.
  Proof.
    intros db c d Hrel. destruct Hrel; reflexivity.
  Qed.

  (** A variable's semantic cell occurs in every argument list that reads that variable. *)
  Lemma run_terms_var_cell : forall (s : Model.env (V := V.t)) ts cs x c,
    terms_value s ts cs -> In (Var x) ts -> s x = Some c -> In c cs.
  Proof.
    intros s ts cs x c Hterms. induction Hterms as [|t d rest more Hhead Htail IH];
      intros Hin Hlookup; [contradiction|].
    destruct Hin as [Heq|Hin].
    - subst t. cbn [term_value] in Hhead. rewrite Hlookup in Hhead.
      injection Hhead as <-. now left.
    - right. now apply IH.
  Qed.

  (** A matched function atom reads its arguments and result from one stored row. *)
  Lemma run_matched_fun_terms : forall db (s : Model.env (V := V.t)) f args res,
    atom_holds V.prim (D.view db) s (Fun V.t f args res) ->
    exists k o, row (D.view db) f k o /\
      terms_value s (args ++ option_list res) (k ++ option_list o).
  Proof.
    intros db s f args res [k [o [Hargs [Hresult Hrow]]]]. exists k, o.
    split; [exact Hrow|]. apply Forall2_app; [exact Hargs|].
    destruct res as [t|], o as [c|]; cbn [option_list] in *; try contradiction.
    - constructor; [exact Hresult|constructor].
    - constructor.
  Qed.

  (** Every variable bound by a closed query occurs in a function atom. *)
  Lemma run_query_bound_fun : forall sorts kinds q g,
    @query_ok V.t sorts kinds ctx_empty q g -> forall x ty, g x = Some ty ->
    exists f args res, In (Fun V.t f args res) q /\ In (Var x) (args ++ option_list res).
  Proof.
    intros sorts kinds q g Hquery x ty Hbound.
    destruct (run_query_scope sorts kinds ctx_empty q g Hquery x ty Hbound)
      as [Hempty|[a [Hin Hvar]]]; [discriminate|].
    apply (run_query_vars_fun sorts kinds q g Hquery x).
    apply in_flat_map. exists a. split; [exact Hin|]. rewrite run_atom_vars_terms.
    apply in_flat_map. exists (Var x). split; [exact Hvar|now left].
  Qed.

  (** Matched query bindings use supported cells, independently of unrelated environment entries. *)
  Lemma run_query_supported : forall sorts kinds q g db s,
    @query_ok V.t sorts kinds ctx_empty q g -> matches V.prim (D.view db) q s ->
    forall x ty c, g x = Some ty -> s x = Some c -> run_supported db c.
  Proof.
    intros sorts kinds q g db s Hquery Hmatches x ty c Hbound Hlookup.
    destruct (run_query_bound_fun sorts kinds q g Hquery x ty Hbound)
      as [f [args [res [Hfun Hvar]]]].
    destruct (run_matched_fun_terms db s f args res
      ((proj1 (Forall_forall _ _)) Hmatches _ Hfun)) as [k [o [Hrow Hterms]]].
    eapply run_row_supported; [exact Hrow|]. eapply run_terms_var_cell; eassumption.
  Qed.

  (** A well-typed identifier read uses only a context-bound allocation. *)
  Lemma run_term_allocated_on : forall db g s locals t ty i,
    run_allocated_on db g (look s locals) -> has g t ty ->
    term_cell s locals t = Some (Id i) -> D.allocated db i.
  Proof.
    intros db g s locals [x|v] ty i Hallocated Hhas Hcell; [|discriminate].
    eapply Hallocated; eassumption.
  Qed.

  (** Well-typed argument lookups require allocation only on their context. *)
  Lemma run_terms_allocated_on : forall db g s locals ts ss cs,
    run_allocated_on db g (look s locals) -> Forall2 (has g) ts ss ->
    term_cells s locals ts = Some cs -> forall i, In (Id i) cs -> D.allocated db i.
  Proof.
    intros db g s locals ts ss cs Hallocated Htyped. revert cs.
    induction Htyped as [|t ty rest types Hhead Htail IH]; intros cs Hcells i Hin.
    - injection Hcells as <-. contradiction.
    - cbn [term_cells] in Hcells.
      destruct (term_cell s locals t) as [c|] eqn:Hcell; [|discriminate].
      destruct (term_cells s locals rest) as [more|] eqn:Hmore; [|discriminate].
      injection Hcells as <-. destruct Hin as [Heq|Hin].
      + subst c. eapply run_term_allocated_on; eassumption.
      + eapply IH; eauto.
  Qed.

  (** Well-typed result lookups require allocation only on their context. *)
  Lemma run_result_allocated_on : forall db g s locals out res o,
    run_allocated_on db g (look s locals) -> has_result g out res ->
    result_cell s locals res = Some o ->
    forall i, In (Id i) (option_list o) -> D.allocated db i.
  Proof.
    intros db g s locals out res o Hallocated Htyped Hresult i Hin.
    destruct res as [t|]; cbn [result_cell] in Hresult.
    - destruct (term_cell s locals t) as [c|] eqn:Hcell; [|discriminate].
      injection Hresult as <-. destruct Hin as [Heq|[]]. subst c.
      destruct out; cbn [has_result out_sort] in Htyped; [contradiction| |];
        eapply run_term_allocated_on; eassumption.
    - injection Hresult as <-. contradiction.
  Qed.

  (** Related environments give related supported cells to every typed action term. *)
  Lemma run_term_related : forall db g s locals semantic t ty c,
    run_env_related db g (look s locals) semantic -> has g t ty ->
    term_cell s locals t = Some c ->
    exists d, term_value semantic t d /\ run_supported db d /\
      cell_rel (same (D.view db)) c d.
  Proof.
    intros db g s locals semantic [x|v] ty c Hrelated Hhas Hcell.
    - exact (Hrelated x ty c Hhas Hcell).
    - injection Hcell as <-. exists (Val v). split; [reflexivity|].
      split; [exact I|constructor].
  Qed.

  (** Related environments give related supported cells to a typed argument list. *)
  Lemma run_terms_related : forall db g s locals semantic ts ss cs,
    run_env_related db g (look s locals) semantic -> Forall2 (has g) ts ss ->
    term_cells s locals ts = Some cs ->
    exists ds, terms_value semantic ts ds /\ Forall (run_supported db) ds /\
      Forall2 (cell_rel (same (D.view db))) cs ds.
  Proof.
    intros db g s locals semantic ts ss cs Hrelated Htyped. revert cs.
    induction Htyped as [|t ty rest types Hhead Htail IH]; intros cs Hcells.
    - injection Hcells as <-. exists []. repeat split; constructor.
    - cbn [term_cells] in Hcells.
      destruct (term_cell s locals t) as [c|] eqn:Hcell; [|discriminate].
      destruct (term_cells s locals rest) as [more|] eqn:Hmore; [|discriminate].
      injection Hcells as <-.
      destruct (run_term_related db g s locals semantic t ty c Hrelated Hhead Hcell)
        as [d [Hvalue [Hsupport Hrel]]].
      destruct (IH more eq_refl) as [ds [Hvalues [Hsupports Hrels]]].
      exists (d :: ds). split; [now constructor|]. split; now constructor.
  Qed.

  (** Related environments agree on the value arguments supplied to a primitive. *)
  Lemma run_values_related : forall db g s locals semantic ts vs,
    run_env_related db g (look s locals) semantic -> Forall (fun t => has g t SVal) ts ->
    term_values s locals ts = Some vs -> terms_value semantic ts (map Val vs).
  Proof.
    intros db g s locals semantic ts vs Hrelated Htyped. revert vs.
    induction Htyped as [|t rest Hhead Htail IH]; intros vs Hvalues.
    - injection Hvalues as <-. constructor.
    - cbn [term_values] in Hvalues.
      destruct (term_cell s locals t) as [[i|v]|] eqn:Hcell; try discriminate.
      destruct (term_values s locals rest) as [more|] eqn:Hmore; [|discriminate].
      injection Hvalues as <-.
      destruct (run_term_related db g s locals semantic t SVal (Val v)
        Hrelated Hhead Hcell) as [d [Hvalue [_ Hrel]]].
      inversion Hrel; subst d. constructor; [exact Hvalue|now apply IH].
  Qed.

  (** A supported semantic cell equals a related canonical cell occurring in a row. *)
  Lemma run_canon_related_supported : forall db f k o c d,
    D.wf db -> row_ids_unique (D.view db) -> row (D.view db) f k o ->
    In (D.canon db c) (k ++ option_list o) -> run_supported db d ->
    cell_rel (same (D.view db)) c d -> D.canon db c = d.
  Proof.
    intros db f k o c d Hwf Hunique Hrow Hin Hsupport Hrel.
    destruct Hrel as [i j Hij|v]; [|reflexivity].
    destruct Hsupport as [g [key [output [Hother Hj]]]]. cbn [D.canon] in Hin |- *.
    f_equal. eapply Hunique; [exact Hrow|exact Hother|exact Hin|exact Hj|].
    apply (proj2 (D.same_repr db (D.repr db i) j Hwf)).
    rewrite D.repr_idem by exact Hwf. apply (proj1 (D.same_repr db i j Hwf)). exact Hij.
  Qed.

  (** A canonical row key equals its related supported semantic argument list. *)
  Lemma run_canon_key_related : forall db f key output actual semantic,
    D.wf db -> row_ids_unique (D.view db) -> row (D.view db) f key output ->
    (forall c, In c actual -> In (D.canon db c) (key ++ option_list output)) ->
    Forall2 (cell_rel (same (D.view db))) actual semantic ->
    Forall (run_supported db) semantic -> map (D.canon db) actual = semantic.
  Proof.
    intros db f key output actual semantic Hwf Hunique Hrow Hin Hrelated.
    revert Hin. induction Hrelated as [|a b rest more Hab Hrest IH]; intros Hin Hsupport.
    - reflexivity.
    - inversion Hsupport as [|b' more' Hb Hmore]; subst b' more'. cbn [map].
      f_equal.
      + eapply run_canon_related_supported; [exact Hwf|exact Hunique|exact Hrow| |exact Hb|].
        * apply Hin. now left.
        * exact Hab.
      + apply IH; [intros c Hc; apply Hin; now right|exact Hmore].
  Qed.

  (** A row read by actual arguments has exactly their supported semantic key. *)
  Lemma run_related_row_arguments : forall db f actual semantic output,
    D.wf db -> row_ids_unique (D.view db) ->
    row (D.view db) f (map (D.canon db) actual) output ->
    Forall2 (cell_rel (same (D.view db))) actual semantic ->
    Forall (run_supported db) semantic -> map (D.canon db) actual = semantic.
  Proof.
    intros db f actual semantic output Hwf Hunique Hrow Hrel Hsupport.
    eapply run_canon_key_related; [exact Hwf|exact Hunique|exact Hrow| |exact Hrel|exact Hsupport].
    intros c Hin. apply in_app_iff. left. now apply in_map.
  Qed.

  (** A typed result term has a related supported semantic result. *)
  Lemma run_result_related_term : forall db g s locals semantic out t c,
    run_env_related db g (look s locals) semantic -> has_result g out (Some t) ->
    term_cell s locals t = Some c ->
    exists d, term_value semantic t d /\ run_supported db d /\
      cell_rel (same (D.view db)) c d.
  Proof.
    intros db g s locals semantic out t c Hrelated Hhas Hcell.
    destruct out; cbn [has_result out_sort] in Hhas; [contradiction| |];
      eapply run_term_related; eassumption.
  Qed.

  (** Action execution cannot clear a raised change flag. *)
  Lemma run_apply_go_changed : forall acts s locals db, D.changed db = true ->
    D.changed (apply_go acts s locals db) = true.
  Proof.
    intro acts. induction acts as [|a rest IH]; intros s locals db Hchanged;
      [exact Hchanged|].
    destruct a as [x f args|f args res|t u|x op args]; cbn [apply_go].
    - destruct (term_cells s locals args) as [cells|]; [|exact Hchanged].
      pose proof (D.changed_make f cells db Hchanged) as Hnext.
      destruct (D.make f cells db) as [i next]. apply IH. exact Hnext.
    - destruct (term_cells s locals args) as [cells|]; [|exact Hchanged].
      destruct (result_cell s locals res) as [output|]; [|exact Hchanged].
      apply IH. now apply D.changed_put.
    - destruct (term_cell s locals t) as [[i|v]|]; [| |exact Hchanged];
        destruct (term_cell s locals u) as [[j|w]|]; try exact Hchanged;
        apply IH; try exact Hchanged.
      now apply D.changed_union.
    - destruct (term_values s locals args) as [vs|]; [|exact Hchanged].
      destruct (V.prim op vs); [apply IH|]; exact Hchanged.
  Qed.

  (** A quiet completed suffix started with a quiet database. *)
  Lemma run_apply_go_quiet_start : forall acts s locals db,
    D.changed (apply_go acts s locals db) = false -> D.changed db = false.
  Proof.
    intros acts s locals db Hquiet. destruct (D.changed db) eqn:Hchanged; [|reflexivity].
    pose proof (run_apply_go_changed acts s locals db Hchanged) as Hraised. congruence.
  Qed.

  (** Context-restricted allocation survives a growing identifier counter. *)
  Lemma run_allocated_on_mono : forall db next g s,
    (D.ids db <= D.ids next)%N -> run_allocated_on db g s -> run_allocated_on next g s.
  Proof.
    intros db next g s Hids Hallocated x ty i Hbound Hcell.
    specialize (Hallocated x ty i Hbound Hcell). unfold D.allocated in *. lia.
  Qed.

  (** A typed local assignment preserves context-restricted allocation. *)
  Lemma run_allocated_on_set : forall db g s locals x c ty,
    run_allocated_on db g (look s locals) ->
    (forall i, c = Id i -> D.allocated db i) ->
    run_allocated_on db (ctx_set g x ty) (look s (PTrieCode.set x c locals)).
  Proof.
    intros db g s locals x c ty Hallocated Hnew y other i Hbound Hcell.
    rewrite run_look_set in Hcell. unfold ctx_set in Hbound. unfold update in Hcell.
    destruct (Pos.eqb x y).
    - apply Hnew. now injection Hcell.
    - eapply Hallocated; eassumption.
  Qed.

  (** A pair of related local assignments preserves the environment relation. *)
  Lemma run_env_related_set : forall db g s locals semantic x c d ty,
    run_env_related db g (look s locals) semantic -> run_supported db d ->
    cell_rel (same (D.view db)) c d ->
    run_env_related db (ctx_set g x ty) (look s (PTrieCode.set x c locals))
      (update semantic x d).
  Proof.
    intros db g s locals semantic x c d ty Hrelated Hsupport Hrel y other a Hbound Hcell.
    rewrite run_look_set in Hcell. unfold ctx_set in Hbound. unfold update in Hcell |- *.
    destruct (Pos.eqb x y).
    - injection Hcell as <-. exists d. split; [reflexivity|]. split; assumption.
    - eapply Hrelated; eassumption.
  Qed.

  (** Retaining rows retains supported semantic identifiers. *)
  Lemma run_supported_mono : forall db next c,
    (forall f k o, row (D.view db) f k o -> row (D.view next) f k o) ->
    run_supported db c -> run_supported next c.
  Proof.
    intros db next [i|v] Hrows Hsupport; [|exact I].
    destruct Hsupport as [f [k [o [Hrow Hin]]]]. exists f, k, o. split; [now apply Hrows|exact Hin].
  Qed.

  (** Retaining rows and equalities preserves related semantic bindings. *)
  Lemma run_env_related_mono : forall db next g actual semantic,
    (forall f k o, row (D.view db) f k o -> row (D.view next) f k o) ->
    (forall i j, same (D.view db) i j -> same (D.view next) i j) ->
    run_env_related db g actual semantic -> run_env_related next g actual semantic.
  Proof.
    intros db next g actual semantic Hrows Hsame Hrelated x ty c Hbound Hcell.
    destruct (Hrelated x ty c Hbound Hcell) as [d [Hd [Hsupport Hrel]]].
    exists d. split; [exact Hd|]. split.
    - eapply run_supported_mono; eassumption.
    - eapply run_cell_rel_mono; eassumption.
  Qed.

  (** Database equality is symmetric. *)
  Lemma run_same_sym : forall db i j, D.wf db ->
    same (D.view db) i j -> same (D.view db) j i.
  Proof.
    intros db i j Hwf Hij. apply (proj2 (D.same_repr db j i Hwf)).
    symmetry. apply (proj1 (D.same_repr db i j Hwf)). exact Hij.
  Qed.

  (** Related source cells have the same output-containment consequences. *)
  Lemma run_cell_le_related : forall db f a b c, D.wf db ->
    cell_rel (same (D.view db)) a b -> cell_le V.merge (D.view db) f a c ->
    cell_le V.merge (D.view db) f b c.
  Proof.
    intros db f a b c Hwf Hrel Hle. destruct Hrel as [i j Hij|v]; [|exact Hle].
    destruct c as [k|w]; [|contradiction].
    eapply run_same_trans; [exact Hwf| |exact Hle]. now apply run_same_sym.
  Qed.

  (** A quiet union adds no new identifier equality. *)
  Lemma run_quiet_union_same : forall i j db, D.wf db -> D.changed db = false ->
    D.changed (D.union i j db) = false ->
    forall a b, same (D.view (D.union i j db)) a b -> same (D.view db) a b.
  Proof.
    intros i j db Hwf Hquiet Hnext a b Hsame.
    pose proof (D.union_quiet i j db Hwf Hquiet Hnext) as Hij.
    apply (proj1 (D.union_same i j db a b Hwf)) in Hsame.
    induction Hsame as [a b Hstep|a|a b Hstep IH|a b c Hab IH1 Hbc IH2].
    - destruct Hstep as [Hstep|Hpair]; [exact Hstep|].
      injection Hpair as Hai Hbj. subst a b. exact Hij.
    - now apply run_same_refl.
    - now apply run_same_sym.
    - eapply run_same_trans; eassumption.
  Qed.

  (** A quiet union preserves uniqueness of identifiers that occur in rows. *)
  Lemma run_quiet_union_unique : forall i j db, D.wf db -> D.changed db = false ->
    D.changed (D.union i j db) = false -> row_ids_unique (D.view db) ->
    row_ids_unique (D.view (D.union i j db)).
  Proof.
    intros i j db Hwf Hquiet Hnext Hunique f k o g key output a b Hrow Hother Ha Hb Hab.
    rewrite (D.union_rows i j db Hwf) in Hrow, Hother.
    eapply Hunique; [exact Hrow|exact Hother|exact Ha|exact Hb|].
    eapply run_quiet_union_same; eassumption.
  Qed.

  (** Row, equality and kind inclusion transports cell output containment. *)
  Lemma run_cell_le_transport : forall (before after : view (V := V.t)) f a b,
    (forall i j, same after i j -> same before i j) ->
    (forall g, kind before g = kind after g) ->
    cell_le V.merge after f a b -> cell_le V.merge before f a b.
  Proof.
    intros before after f [i|v] [j|w] Hsame Hkinds Hle; cbn [cell_le] in *;
      try contradiction.
    - now apply Hsame.
    - destruct Hle as [m [Hkind Hmerge]]. exists m. split; [now rewrite Hkinds|exact Hmerge].
  Qed.

  (** Keeping semantic rows, equalities and kinds transports action presence. *)
  Lemma run_present_transport : forall (before after : view (V := V.t)) acts semantic,
    (forall f k o, row after f k o -> row before f k o) ->
    (forall i j, same after i j -> same before i j) ->
    (forall f, kind before f = kind after f) ->
    present V.prim V.merge after semantic acts -> present V.prim V.merge before semantic acts.
  Proof.
    intros before after acts. induction acts as [|a rest IH]; intros semantic Hrows Hsame
      Hkinds Hpresent; [exact I|].
    destruct a as [x f args|f args res|t u|x op args]; cbn [present] in Hpresent |- *.
    - destruct Hpresent as [k [i [Hterms [Hrow Htail]]]]. exists k, i.
      split; [exact Hterms|]. split; [now apply Hrows|]. eapply IH; eassumption.
    - destruct Hpresent as [k [o [Hterms [Hrow [Hresult Htail]]]]]. exists k, o.
      split; [exact Hterms|]. split; [now apply Hrows|]. split.
      + destruct res as [t|]; [|exact I].
        destruct Hresult as [c [d [Ht [Ho Hle]]]]. exists c, d.
        split; [exact Ht|]. split; [exact Ho|]. eapply run_cell_le_transport; eassumption.
      + eapply IH; eassumption.
    - destruct Hpresent as [c [d [Ht [Hu [Hrel Htail]]]]]. exists c, d.
      split; [exact Ht|]. split; [exact Hu|]. split.
      + destruct c as [i|v], d as [j|w]; try exact I. now apply Hsame.
      + eapply IH; eassumption.
    - destruct Hpresent as [k [vs [Hterms [Hvalues Htail]]]]. exists k, vs.
      split; [exact Hterms|]. split; [exact Hvalues|].
      destruct (V.prim op vs) as [v|]; [eapply IH; eassumption|exact I].
  Qed.

  (** A quiet constructor call reuses an old row and leaves the database itself unchanged. *)
  Lemma run_quiet_make_reuse : forall db f k, D.wf db ->
    kind (D.view db) f = Some OId ->
    (forall j, In (Id j) k -> D.allocated db j) -> D.slots_fit db f (S (length k)) ->
    D.changed db = false -> D.changed (snd (D.make f k db)) = false ->
    exists i next j, D.make f k db = (i, next) /\ next = db /\
      row (D.view db) f (map (D.canon db) k) (Some (Id j)) /\ i = D.repr db j.
  Proof.
    intros db f k Hwf Hkind Hallocated Hfit Hquiet Hafter.
    destruct (D.make_quiet f k db Hwf Hquiet Hafter) as [old Hrowold].
    pose proof (D.make_spec f k db Hwf Hkind) as Hspec.
    pose proof (D.wf_make f k db Hwf Hallocated Hfit) as Hwfnext.
    destruct (D.make f k db) as [i next] eqn:Hmake. cbn [snd] in Hwfnext.
    destruct Hspec as [[j [Hrow [Hrepr Hnext]]]|[Hfresh [Hrow Hextension]]].
    - exists i, next, j. split; [reflexivity|]. split; [exact Hnext|]. split; assumption.
    - destruct Hextension as [Hids [Hkinds [Hsame Hrows]]].
      assert (Hold : row (D.view next) f (map (D.canon db) k) (Some (Id old))).
      { apply (proj2 (Hrows f (map (D.canon db) k) (Some (Id old)))). now left. }
      pose proof (D.row_functional next f (map (D.canon db) k) (Some (Id i))
        (Some (Id old)) Hwfnext Hrow Hold) as Heq. injection Heq as Heqold. subst old.
      assert (Hi : D.allocated db i).
      { eapply D.row_allocated; [exact Hwf|exact Hrowold|].
        apply in_app_iff. right. now left. }
      unfold D.fresh_id in Hfresh. unfold D.allocated in Hi.
      rewrite Hfresh, N.succ_pos_spec in Hi. lia.
  Qed.

  (** Quiet typed execution already has each action present in its semantic environment. *)
  Lemma run_apply_go_present : forall p cp acts g s locals semantic db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> run_allocated_on db g (look s locals) ->
    run_env_related db g (look s locals) semantic -> row_ids_unique (D.view db) ->
    D.changed db = false -> D.changed (apply_go acts s locals db) = false ->
    present V.prim V.merge (D.view db) semantic acts.
  Proof.
    intros p cp acts. induction acts as [|a rest IH]; intros g s locals semantic db
      Hchecked Hwf Hloaded Hacts Henv Hallocated Hrelated Hunique Hquiet Hfinal;
      [exact I|].
    destruct a as [x f args|f args res|t u|x op args]; cbn [actions_ok] in Hacts.
    - destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]].
      destruct (run_term_cells_typed g s locals args ss Henv Hargs)
        as [cells [Hcells Hsorts]].
      destruct (run_terms_related db g s locals semantic args ss cells Hrelated Hargs Hcells)
        as [semcells [Hsemterms [Hsupports Hrels]]].
      assert (Hargs_allocated : forall i, In (Id i) cells -> D.allocated db i).
      { eapply run_terms_allocated_on; eassumption. }
      assert (Hkinddb : kind (D.view db) f = Some OId).
      { rewrite (proj1 Hloaded). exact Hkind. }
      assert (Hfit : D.slots_fit db f (S (length cells))).
      { eapply run_slots_fit; [exact Hchecked|exact Hloaded|exact Hsort|exact Hkind|].
        rewrite <- Hsorts, length_map. cbn. lia. }
      cbn [apply_go] in Hfinal. rewrite Hcells in Hfinal.
      destruct (D.make f cells db) as [i next] eqn:Hmake.
      pose proof (run_apply_go_quiet_start rest s (PTrieCode.set x (Id i) locals) next Hfinal)
        as Hnextquiet.
      assert (Hafter : D.changed (snd (D.make f cells db)) = false).
      { rewrite Hmake. exact Hnextquiet. }
      destruct (run_quiet_make_reuse db f cells Hwf Hkinddb Hargs_allocated Hfit Hquiet Hafter)
        as [ri [rn [j [Hcall [Hsame [Hrow Hrepr]]]]]].
      rewrite Hmake in Hcall. injection Hcall as Heqi Heqn. subst ri rn next.
      assert (Hnew : D.allocated db i).
      { pose proof (D.layout_make f cells db Hwf) as Hlayout. rewrite Hmake in Hlayout.
        destruct Hlayout as [_ [_ [_ [Hnew _]]]]. exact Hnew. }
      pose proof (run_related_row_arguments db f cells semcells (Some (Id j))
        Hwf Hunique Hrow Hrels Hsupports) as Hkey.
      rewrite Hkey in Hrow. cbn [present]. exists semcells, j.
      split; [exact Hsemterms|]. split; [exact Hrow|].
      assert (Henv' : env_sorted (ctx_set g x SId)
          (look s (PTrieCode.set x (Id i) locals))).
      { apply run_env_sorted_set; [exact Henv|reflexivity]. }
      assert (Hallocated' : run_allocated_on db (ctx_set g x SId)
          (look s (PTrieCode.set x (Id i) locals))).
      { apply run_allocated_on_set; [exact Hallocated|].
        intros k Heq. injection Heq as <-. exact Hnew. }
      assert (Hrelated' : run_env_related db (ctx_set g x SId)
          (look s (PTrieCode.set x (Id i) locals)) (update semantic x (Id j))).
      { apply run_env_related_set; [exact Hrelated| |].
        - eapply run_row_supported; [exact Hrow|]. apply in_app_iff. right. now left.
        - constructor. apply (proj2 (D.same_repr db i j Hwf)).
          rewrite Hrepr, D.repr_idem by exact Hwf. reflexivity. }
      exact (IH _ _ _ _ _ Hchecked Hwf Hloaded Hrest Henv' Hallocated' Hrelated'
        Hunique Hquiet Hfinal).
    - destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
      destruct (run_term_cells_typed g s locals args ss Henv Hargs)
        as [cells [Hcells Hsorts]].
      destruct (run_result_cell_typed g s locals out res Henv Hresult)
        as [output [Houtput Houtsort]].
      destruct (run_terms_related db g s locals semantic args ss cells Hrelated Hargs Hcells)
        as [semcells [Hsemterms [Hsupports Hrels]]].
      assert (Hrowtyped : row_sorted (program_sorts p) (program_kind p) f cells output).
      { exists out. rewrite Hsorts. repeat split; assumption. }
      assert (Hargs_allocated : forall i, In (Id i) (cells ++ option_list output) ->
          D.allocated db i).
      { intros i Hin. apply in_app_iff in Hin as [Hin|Hin].
        - eapply run_terms_allocated_on; eassumption.
        - eapply run_result_allocated_on; eassumption. }
      pose proof (run_put_allowed p cp db f cells output Hchecked Hloaded Hrowtyped
        Hargs_allocated) as Hallowed.
      destruct (run_put_state p cp f cells output db Hchecked Hwf Hloaded Hrowtyped
        Hargs_allocated) as [Hwf' [Hloaded' [Hids _]]].
      cbn [apply_go] in Hfinal. rewrite Hcells, Houtput in Hfinal.
      pose proof (run_apply_go_quiet_start rest s locals (D.put f cells output db) Hfinal)
        as Hnextquiet.
      destruct (D.put_quiet f cells output db Hwf Hallowed Hquiet Hnextquiet)
        as [Hview [stored [Hrow Hcontained]]].
      pose proof (run_related_row_arguments db f cells semcells stored Hwf Hunique Hrow
        Hrels Hsupports) as Hkey. rewrite Hkey in Hrow.
      assert (Hallocated' : run_allocated_on (D.put f cells output db) g (look s locals)).
      { eapply run_allocated_on_mono with (db := db);
          [rewrite Hids; reflexivity|exact Hallocated]. }
      assert (Hrelated' : run_env_related (D.put f cells output db) g (look s locals) semantic).
      { eapply run_env_related_mono; [| |exact Hrelated]; intros; now rewrite Hview. }
      assert (Hunique' : row_ids_unique (D.view (D.put f cells output db))).
      { now rewrite Hview. }
      pose proof (IH _ _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated' Hrelated'
        Hunique' Hnextquiet Hfinal) as Htail.
      rewrite Hview in Htail. cbn [present]. exists semcells, stored.
      split; [exact Hsemterms|]. split; [exact Hrow|]. split; [|exact Htail].
      destruct res as [t|]; [|exact I]. cbn [result_cell] in Houtput.
      destruct (term_cell s locals t) as [c|] eqn:Hcell; [|discriminate].
      injection Houtput as Heqoutput. subst output.
      destruct (run_result_related_term db g s locals semantic out t c
        Hrelated Hresult Hcell) as [d [Hterm [_ Hrel]]].
      destruct stored as [target|]; [|contradiction]. exists d, target.
      split; [exact Hterm|]. split; [reflexivity|].
      eapply run_cell_le_related; eassumption.
    - destruct Hacts as [Ht [Hu Hrest]].
      destruct (run_term_cell_typed g s locals t SId Henv Ht)
        as [[i|v] [Hi Hitype]]; [|discriminate].
      destruct (run_term_cell_typed g s locals u SId Henv Hu)
        as [[j|v] [Hj Hjtype]]; [|discriminate].
      pose proof (run_term_allocated_on db g s locals t SId i Hallocated Ht Hi) as Hiall.
      pose proof (run_term_allocated_on db g s locals u SId j Hallocated Hu Hj) as Hjall.
      destruct (run_union_state p cp i j db Hwf Hloaded Hiall Hjall)
        as [Hwf' [Hloaded' [Hids _]]].
      cbn [apply_go] in Hfinal. rewrite Hi, Hj in Hfinal.
      pose proof (run_apply_go_quiet_start rest s locals (D.union i j db) Hfinal) as Hnextquiet.
      pose proof (D.union_quiet i j db Hwf Hquiet Hnextquiet) as Hij.
      destruct (run_term_related db g s locals semantic t SId (Id i) Hrelated Ht Hi)
        as [c [Hsemantic_t [_ Hic]]].
      destruct (run_term_related db g s locals semantic u SId (Id j) Hrelated Hu Hj)
        as [d [Hsemantic_u [_ Hjd]]].
      inversion Hic as [i0 a Hia|]; subst.
      inversion Hjd as [j0 b Hjb|]; subst.
      assert (Hab : same (D.view db) a b).
      { eapply run_same_trans with (j := i); [exact Hwf|now apply run_same_sym|].
        eapply run_same_trans; [exact Hwf|exact Hij|exact Hjb]. }
      assert (Hallocated' : run_allocated_on (D.union i j db) g (look s locals)).
      { eapply run_allocated_on_mono with (db := db);
          [rewrite Hids; reflexivity|exact Hallocated]. }
      assert (Hrelated' : run_env_related (D.union i j db) g (look s locals) semantic).
      { eapply run_env_related_mono; [| |exact Hrelated].
        - intros f k o Hrow. now rewrite (D.union_rows i j db Hwf).
        - intros k l Hkl. apply (proj2 (D.union_same i j db k l Hwf)).
          apply rst_step. now left. }
      assert (Hunique' : row_ids_unique (D.view (D.union i j db))).
      { eapply run_quiet_union_unique; eassumption. }
      pose proof (IH _ _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated' Hrelated'
        Hunique' Hnextquiet Hfinal) as Htail.
      cbn [present]. exists (Id a), (Id b).
      split; [exact Hsemantic_t|]. split; [exact Hsemantic_u|]. split; [exact Hab|].
      eapply run_present_transport; [| | |exact Htail].
      + intros f k o Hrow. rewrite (D.union_rows i j db Hwf) in Hrow. exact Hrow.
      + eapply run_quiet_union_same; eassumption.
      + intro f. rewrite (proj1 (D.layout_union i j db Hwf)). reflexivity.
    - destruct Hacts as [Hargs Hrest].
      destruct (run_term_values_typed g s locals args Henv Hargs) as [vs Hvalues].
      pose proof (run_values_related db g s locals semantic args vs Hrelated Hargs Hvalues)
        as Hsemterms.
      cbn [apply_go] in Hfinal. rewrite Hvalues in Hfinal.
      cbn [present]. exists (map Val vs), vs.
      split; [exact Hsemterms|]. split; [apply run_value_cells|].
      destruct (V.prim op vs) as [v|]; [|exact I].
      assert (Henv' : env_sorted (ctx_set g x SVal)
          (look s (PTrieCode.set x (Val v) locals))).
      { apply run_env_sorted_set; [exact Henv|reflexivity]. }
      assert (Hallocated' : run_allocated_on db (ctx_set g x SVal)
          (look s (PTrieCode.set x (Val v) locals))).
      { apply run_allocated_on_set; [exact Hallocated|]. intros i Heq. discriminate. }
      assert (Hrelated' : run_env_related db (ctx_set g x SVal)
          (look s (PTrieCode.set x (Val v) locals)) (update semantic x (Val v))).
      { apply run_env_related_set; [exact Hrelated|exact I|constructor]. }
      exact (IH _ _ _ _ _ Hchecked Hwf Hloaded Hrest Henv' Hallocated' Hrelated'
        Hunique Hquiet Hfinal).
  Qed.

  Lemma quiet_apply_present : forall p cp r s db, plans_ok p cp -> D.wf db ->
    loaded p cp db -> In r (rules V.t p) -> matches V.prim (D.view db) (query V.t r) s ->
    row_ids_unique (D.view db) ->
    D.changed db = false -> D.changed (apply (actions V.t r) s db) = false ->
    present V.prim V.merge (D.view db) s (actions V.t r).
  Proof.
    intros p cp r s db Hchecked Hwf Hloaded Hin Hmatches Hunique Hquiet Hfinal.
    pose proof (plans_ok_sorted p cp Hchecked) as Hprogram.
    destruct ((proj1 (Forall_forall _ _)) Hprogram r Hin) as [g [Hquery Hacts]].
    pose proof (matches_rule_env V.t V.prim (D.view db) (program_sorts p) (program_kind p)
      r g s (proj2 (proj2 Hloaded)) (proj1 Hloaded) Hquery Hmatches) as Henv.
    assert (Hsupport : forall x ty c, g x = Some ty -> s x = Some c -> run_supported db c).
    { eapply run_query_supported; eassumption. }
    unfold apply in Hfinal. eapply run_apply_go_present; try eassumption.
    - intros x ty Hbound. destruct (Henv x ty Hbound) as [c [Hc Hsort]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x ty i Hbound Hcell. rewrite run_look_empty in Hcell.
      apply run_supported_allocated; [exact Hwf|]. eapply Hsupport; eassumption.
    - intros x ty c Hbound Hcell. rewrite run_look_empty in Hcell.
      exists c. split; [exact Hcell|]. split.
      + eapply Hsupport; eassumption.
      + now apply run_cell_rel_refl.
  Qed.

  (** Relational declarations never assign a constructor or lattice output. *)
  Lemma run_relational_kind : forall (p : program V.t) f out,
    relational_fragment p = true -> program_kind p f = Some out -> out = ORel.
  Proof.
    intros p f out Hfragment Hkind. apply andb_true_iff in Hfragment as [Hdecls _].
    unfold program_kind in Hkind. revert Hdecls Hkind.
    generalize (decls V.t p) as ds. intro ds. induction ds as [|d rest IH];
      intros Hdecls Hkind; [discriminate|].
    cbn [forallb] in Hdecls. apply andb_true_iff in Hdecls as [Hout Hrest].
    cbn [lookup_kind] in Hkind. destruct (Pos.eqb (name d) f).
    - injection Hkind as <-. unfold relational_output in Hout.
      destruct (Syntax.out d); try discriminate; reflexivity.
    - now apply IH.
  Qed.

  (** Relational rules contain only insertion and primitive actions. *)
  Lemma run_relational_actions : forall (p : program V.t) r, relational_fragment p = true ->
    In r (rules V.t p) -> forallb relational_action (actions V.t r) = true.
  Proof.
    intros p r Hfragment Hin. apply andb_true_iff in Hfragment as [_ Hrules].
    exact ((proj1 (forallb_forall _ _)) Hrules r Hin).
  Qed.

  (** Value-only keys are unchanged by canonicalization. *)
  Lemma run_value_key_canon : forall db k,
    Forall (fun c : cell V.t => exists v, c = Val v) k -> map (D.canon db) k = k.
  Proof.
    intros db k Hvalues. induction Hvalues as [|c rest [v ->] Hrest IH];
      cbn [map D.canon]; [reflexivity|now rewrite IH].
  Qed.

  (** With no allocated identifiers, action argument lists contain values only. *)
  Lemma run_no_ids_terms : forall db s locals ts cs,
    no_ids db -> env_allocated db (look s locals) -> term_cells s locals ts = Some cs ->
    Forall (fun c : cell V.t => exists v, c = Val v) cs.
  Proof.
    intros db s locals ts cs [Hzero Hrows] Hallocated Hcells.
    apply Forall_forall. intros [i|v] Hin; [|exists v; reflexivity].
    pose proof (run_term_cells_allocated db s locals ts cs Hallocated Hcells i Hin) as Hi.
    unfold D.allocated in Hi. rewrite Hzero in Hi. lia.
  Qed.

  (** Inserting an output-free row in an identifier-free database only adds that row. *)
  Lemma run_put_none_origin : forall db f k, D.wf db -> no_ids db ->
    D.kind_ok db f k None ->
    Forall (fun c : cell V.t => exists v, c = Val v) k ->
    forall g key output, row (D.view (D.put f k None db)) g key output ->
      row (D.view db) g key output \/ (g = f /\ key = k /\ output = None).
  Proof.
    intros db f k Hwf Hnoids Hallowed Hvalues g key output Hrow.
    apply (proj1 (D.put_rows f k None db Hwf Hallowed g key output)) in Hrow.
    rewrite (run_value_key_canon db k Hvalues) in Hrow.
    destruct Hrow as [[Hrow _]|[-> [-> Houtput]]]; [now left|].
    right. split; [reflexivity|]. split; [reflexivity|].
    destruct (D.old db f k) as [old|] eqn:Hold.
    - apply (proj1 (D.old_row db f k old Hwf)) in Hold.
      destruct ((proj2 Hnoids) f k old Hold) as [-> _].
      cbn [D.combine] in Houtput. symmetry. exact Houtput.
    - cbn [D.combine] in Houtput. symmetry. exact Houtput.
  Qed.

  (** Value-only relational insertion preserves the absence of identifiers. *)
  Lemma run_put_no_ids : forall db f k, D.wf db -> no_ids db ->
    D.kind_ok db f k None ->
    Forall (fun c : cell V.t => exists v, c = Val v) k -> no_ids (D.put f k None db).
  Proof.
    intros db f k Hwf Hnoids Hallowed Hvalues. split.
    - rewrite (proj1 (proj2 (proj2 (D.layout_put f k None db Hwf)))). exact (proj1 Hnoids).
    - intros g key output Hrow.
      destruct (run_put_none_origin db f k Hwf Hnoids Hallowed Hvalues g key output Hrow)
        as [Holdrow|[-> [-> ->]]].
      + exact ((proj2 Hnoids) g key output Holdrow).
      + split; [reflexivity|exact Hvalues].
  Qed.

  (** Pointwise environment equality transports concrete term values. *)
  Lemma run_term_value_env : forall (s t : Model.env (V := V.t)) a c,
    (forall x, s x = t x) -> term_value s a c -> term_value t a c.
  Proof.
    intros s t [x|v] c Heq Hvalue; [unfold term_value in *; now rewrite <- Heq|exact Hvalue].
  Qed.

  (** Pointwise environment equality transports concrete argument lists. *)
  Lemma run_terms_value_env : forall (s t : Model.env (V := V.t)) args cs,
    (forall x, s x = t x) -> terms_value s args cs -> terms_value t args cs.
  Proof.
    intros s t args cs Heq Hvalues. induction Hvalues as [|a c rest more Hhead Htail IH];
      constructor; [eapply run_term_value_env; eassumption|exact IH].
  Qed.

  (** Pointwise environment equality transports relational action derivations. *)
  Lemma run_derivation_action_env : forall (s t : Model.env (V := V.t)) acts f k,
    (forall x, s x = t x) -> derivation_action V.prim s acts f k ->
    derivation_action V.prim t acts f k.
  Proof.
    intros s t acts f k Heq Hderivation. revert t Heq.
    induction Hderivation as
      [s f args k rest Hterms
      |s f args input rest g k Hterms Htail IH
      |s x q args k vs v rest f out Hterms Hvalues Hprim Htail IH]; intros t Heq.
    - apply derive_put. eapply run_terms_value_env; eassumption.
    - eapply derive_put_later; [eapply run_terms_value_env; eassumption|now apply IH].
    - eapply derive_let; [eapply run_terms_value_env; eassumption|exact Hvalues|exact Hprim|].
      apply IH. intro y. unfold update. destruct (Pos.eqb x y); [reflexivity|apply Heq].
  Qed.

  (** Checked relational actions preserve derivability and introduce no identifiers. *)
  Lemma run_apply_go_derives_checked : forall p cp initial acts g s locals db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    forallb relational_action acts = true ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    no_ids db -> derived p initial db ->
    (forall f k, derivation_action V.prim (look s locals) acts f k ->
      derives V.prim p (D.view initial) f k) ->
    no_ids (apply_go acts s locals db) /\ derived p initial (apply_go acts s locals db).
  Proof.
    intros p cp initial acts. induction acts as [|a rest IH]; intros g s locals db
      Hchecked Hwf Hloaded Hfragment Hrel Hacts Henv Hallocated Hnoids Hderived Hjustify.
    - split; assumption.
    - cbn [forallb] in Hrel. apply andb_true_iff in Hrel as [Haction Hrestrel].
      destruct a as [x f args|f args res|t u|x op args]; try discriminate.
      + cbn [actions_ok] in Hacts.
        destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
        pose proof (run_relational_kind p f out Hfragment Hkind) as Hout. subst out.
        destruct res as [t|]; [contradiction|].
        destruct (run_term_cells_typed g s locals args ss Henv Hargs)
          as [cells [Hcells Hsorts]].
        assert (Hrowtyped : row_sorted (program_sorts p) (program_kind p) f cells None).
        { exists ORel. rewrite Hsorts. repeat split; assumption. }
        assert (Hids : forall i, In (Id i) (cells ++ option_list None) -> D.allocated db i).
        { intros i Hin. rewrite app_nil_r in Hin.
          eapply run_term_cells_allocated; eassumption. }
        pose proof (run_put_allowed p cp db f cells None Hchecked Hloaded Hrowtyped Hids)
          as Hallowed.
        destruct (run_put_state p cp f cells None db Hchecked Hwf Hloaded Hrowtyped Hids)
          as [Hwf' [Hloaded' [Hids' _]]].
        pose proof (run_no_ids_terms db s locals args cells Hnoids Hallocated Hcells) as Hvalues.
        pose proof (run_put_no_ids db f cells Hwf Hnoids Hallowed Hvalues) as Hnoids'.
        assert (Hderived' : derived p initial (D.put f cells None db)).
        { intros name key output Hrow.
          destruct (run_put_none_origin db f cells Hwf Hnoids Hallowed Hvalues
            name key output Hrow) as [Holdrow|[-> [-> ->]]].
          - eapply Hderived; exact Holdrow.
          - apply Hjustify. apply derive_put. now apply run_term_cells_spec. }
        assert (Hallocated' : env_allocated (D.put f cells None db) (look s locals)).
        { eapply run_env_allocated_mono with (db := db);
            [rewrite Hids'; reflexivity|exact Hallocated]. }
        cbn [apply_go result_cell]. rewrite Hcells.
        eapply IH; try eassumption. intros name key Htail. apply Hjustify.
        eapply derive_put_later with (input := cells).
        * exact ((proj1 (run_term_cells_spec s locals args cells)) Hcells).
        * exact Htail.
      + cbn [actions_ok] in Hacts. destruct Hacts as [Hargs Hrest].
        destruct (run_term_values_typed g s locals args Henv Hargs) as [vs Hvalues].
        cbn [apply_go]. rewrite Hvalues. destruct (V.prim op vs) as [v|] eqn:Hprim.
        * assert (Henv' : env_sorted (ctx_set g x SVal)
              (look s (PTrieCode.set x (Val v) locals))).
          { apply run_env_sorted_set; [exact Henv|reflexivity]. }
          assert (Hallocated' : env_allocated db (look s (PTrieCode.set x (Val v) locals))).
          { apply run_env_allocated_set; [exact Hallocated|]. intros i Heq. discriminate. }
          eapply IH; try eassumption. intros name key Htail. apply Hjustify.
          eapply derive_let; [eapply run_term_values_spec; exact Hvalues
            |apply run_value_cells|exact Hprim|].
          eapply run_derivation_action_env; [intro y; apply run_look_set|exact Htail].
        * split; assumption.
  Qed.

  (** The checked replacement for F7 uses the loaded action sorts and current allocation. *)
  Lemma run_apply_derives_checked : forall p cp initial db r s,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    no_ids db -> derived p initial db -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s -> env_allocated db s ->
    derivation_body V.prim p (D.view initial) s (query V.t r) ->
    no_ids (apply (actions V.t r) s db) /\ derived p initial (apply (actions V.t r) s db).
  Proof.
    intros p cp initial db r s Hchecked Hwf Hloaded Hfragment Hnoids Hderived
      Hin Henv Hallocated Hbody.
    destruct (run_rule_context p cp r s Hchecked Hin Henv) as [g [_ [Hacts Hsorted]]].
    unfold apply. eapply run_apply_go_derives_checked; try eassumption.
    - eapply run_relational_actions; eassumption.
    - intros x ty Hbound. destruct (Hsorted x ty Hbound) as [c [Hc Hsort]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated; exact Hcell.
    - intros f k Haction. eapply derive_rule; [exact Hin|exact Hbody|].
      eapply run_derivation_action_env; [intro x; apply run_look_empty|exact Haction].
  Qed.

  Lemma bindings_rule_env : forall p cp db c b r, plans_ok p cp -> D.wf db ->
    loaded p cp db -> In c (all_plans cp) ->
    nth_error (rules V.t p) (N.to_nat (rule_ix V.t c)) = Some r -> In b (bindings cp c db) ->
    rule_env (program_sorts p) (program_kind p) r (env_of c b) /\ env_allocated db (env_of c b).
  Proof.
    intros p cp db c b r Hplans Hwf Hloaded Hin Hrule Hbinding. split.
    - pose proof (plans_ok_sorted p cp Hplans) as Hprogram.
      unfold program_ok in Hprogram.
      assert (Hmember : In r (rules V.t p)) by (eapply nth_error_In; exact Hrule).
      apply Forall_forall with (x := r) in Hprogram; [|exact Hmember].
      destruct Hprogram as [g [Htyped Hactions]]. exists g. split; [exact Htyped|].
      destruct (run_plan_member p cp c Hplans Hin)
        as [table [newok [checked_r [Htable [Hchecked_rule Hcheck]]]]].
      rewrite Hrule in Hchecked_rule. injection Hchecked_rule as <-.
      destruct (run_check_cplan_parts newok table (rule_ix V.t c) r c Hcheck)
        as [_ [Hlength [names [expected [Hnames [Hlayout [Hquery Hpost]]]]]]].
      pose proof (run_plan_join_wf p cp db c Hplans Hwf Hloaded Hin) as Hjoin.
      pose proof (J.run_sound (join V.t c) (map (source_index db) (sources V.t c)) b
        Hjoin Hbinding) as Hanswer.
      destruct Hanswer as [Hbinding_length Hprojections].
      assert (Hsources : run_sources_satisfied db b (sources V.t c) (cols (join V.t c))).
      { apply (run_join_answer_sources db b (join V.t c) (sources V.t c)).
        split; assumption. }
      assert (Hname_cells : forall x j, trie_get x names = Some j -> exists cell,
          nth_error b (N.to_nat j) = Some cell /\ env_of c b x = Some cell).
      { intros x j Hget. unfold env_of.
        eapply run_checked_names_cells; [exact Hnames|lia|exact Hget]. }
      eapply (run_check_query_sorted p cp db table Hwf Hloaded Htable ctx_empty
        (query V.t r) g Htyped newok names (nvars (join V.t c)) 0 0 Empty 0
        (sources V.t c) (cols (join V.t c)) [] (nat_n (nvars (join V.t c))) [] [] expected
        b (env_of c b) Hquery Hsources Hname_cells).
      intros x ty Hempty. discriminate.
    - eapply run_plan_bindings_allocated; eassumption.
  Qed.


  Lemma check_plan_eq_split : forall p cp,
    check_plan p cp = check_program p && check_shape p cp.
  Proof.
    reflexivity.
  Qed.

  Lemma shape_slots_ok : forall p cp f perm, plans_ok p cp ->
    In (f, perm) (Syntax.slots V.t cp) -> exists ss out,
      program_sorts p f = Some ss /\ program_kind p f = Some out /\
      NoDup perm /\ Forall (fun i => i < length ss +
        match out_sort out with
        | Some _ => 1
        | None => 0
        end) perm.
  Proof.
    intros p cp f perm Hplan Hslot.
    destruct (check_plan_slots p cp f perm Hplan Hslot)
      as [d [Hdecl [Hnodup Hbound]]].
    destruct (run_find_decl_fields (decls V.t p) f d Hdecl) as [Hsort Hkind].
    exists (arg_sorts d), (out d).
    split; [exact Hsort|]. split; [exact Hkind|].
    split; [exact Hnodup|]. destruct (out d); exact Hbound.
  Qed.


  (** The round advances the database before it applies, so its result carries the rows that
      the round changed as new rows. The driver passes that result on without advancing. *)
  Lemma driver_def : forall p cp lim nv db,
    driver p cp lim (nv, db) =
      let next := round p cp nv db in
      if N.ltb (max_ids lim) (D.ids next) then inr (IdLimit, next)
      else if andb nv (negb (D.changed next)) then inr (Saturated, next)
      else inl (negb (D.changed next), next).
  Proof.
    reflexivity.
  Qed.

  (** The trie of a binding gives the plan's binding environment. *)
  Lemma bind_trie_spec : forall c b x, trie_get x (bind_trie c b) = env_of c b x.
  Proof.
    intros c b x. unfold bind_trie, env_of.
    rewrite bind_cells_get, PTrie.get_empty. reflexivity.
  Qed.

  (** A round's jobs are the kept bindings of its plans, plan by plan. *)
  Lemma jobs_def : forall p cp nv db,
    jobs p cp nv db = flat_map (fun c => map (fun b => (c, b))
      (filter (fun b => keep p c (bind_trie c b)) (bindings cp c db)))
      (if nv then naive V.t cp else seminaive V.t cp).
  Proof.
    reflexivity.
  Qed.

  (** The job loop of a round applies the jobs as the plan's job application does. *)
  Lemma apply_all_jobs : forall p js db, apply_all p js db = apply_jobs p js db.
  Proof.
    intros p js. induction js as [| [c b] rest IH]; intro db.
    - reflexivity.
    - cbn [apply_all apply_jobs]. rewrite IH.
      unfold job_rule. rewrite rule_at_nth. reflexivity.
  Qed.

  (** A round reads its jobs from the starting database, applies them to its advanced copy
      in order and rebuilds once. *)
  Lemma round_eq_jobs : forall p cp nv db,
    round p cp nv db = D.rebuild (apply_jobs p (jobs p cp nv db) (D.advance db)).
  Proof.
    intros p cp nv db. unfold round. rewrite apply_all_jobs. reflexivity.
  Qed.

  (** Two views agree when they have the same rows, identifier equalities and kinds. *)
  Definition run_view_agrees (before after : view (V := V.t)) : Prop :=
    (forall f k o, row before f k o <-> row after f k o) /\
    (forall i j, same before i j <-> same after i j) /\
    (forall f, kind before f = kind after f).

  (** A view agrees with itself. *)
  Lemma run_view_agrees_refl : forall w, run_view_agrees w w.
  Proof.
    intro w. split; [intros f k o; reflexivity|].
    split; [intros i j; reflexivity|intro f; reflexivity].
  Qed.

  (** Observable view agreement composes. *)
  Lemma run_view_agrees_trans : forall before middle after,
    run_view_agrees before middle -> run_view_agrees middle after ->
    run_view_agrees before after.
  Proof.
    intros before middle after [Hrows1 [Hsame1 Hkind1]] [Hrows2 [Hsame2 Hkind2]].
    split.
    - intros f k o. rewrite Hrows1. apply Hrows2.
    - split; [intros i j; rewrite Hsame1; apply Hsame2|].
      intro f. rewrite Hkind1. apply Hkind2.
  Qed.

  (** Observable view agreement is symmetric. *)
  Lemma run_view_agrees_sym : forall before after,
    run_view_agrees before after -> run_view_agrees after before.
  Proof.
    intros before after [Hrows [Hsame Hkinds]]. split.
    - intros f k o. symmetry. apply Hrows.
    - split; [intros i j; symmetry; apply Hsame|]. intro f. symmetry. apply Hkinds.
  Qed.

  (** Equivalent view observations preserve uniqueness of row identifiers. *)
  Lemma run_view_agrees_unique : forall before after,
    run_view_agrees before after -> row_ids_unique before -> row_ids_unique after.
  Proof.
    intros before after [Hrows [Hsame Hkind]] Hunique f k o g key output i j
      Hrow Hother Hi Hj Hij.
    eapply Hunique; [apply (proj2 (Hrows f k o)); exact Hrow|
      apply (proj2 (Hrows g key output)); exact Hother|exact Hi|exact Hj|].
    apply (proj2 (Hsame i j)). exact Hij.
  Qed.

  (** Canonical row identifiers are unique within each identifier-equality class. *)
  Lemma run_canonical_unique : forall db, D.wf db -> D.canonical db ->
    row_ids_unique (D.view db).
  Proof.
    intros db Hwf Hcanonical f k o g key output i j Hrow Hother Hi Hj Hij.
    apply (proj1 (D.same_repr db i j Hwf)) in Hij.
    rewrite (Hcanonical f k o Hrow i Hi), (Hcanonical g key output Hother j Hj) in Hij.
    exact Hij.
  Qed.

  (** Retaining rows retains every concrete query match. *)
  Lemma run_matches_rows : forall (before after : view (V := V.t)) q s,
    (forall f k o, row before f k o -> row after f k o) ->
    matches V.prim before q s -> matches V.prim after q s.
  Proof.
    intros before after q s Hrows Hmatches.
    induction Hmatches as [|a rest Hhead Htail IH]; constructor; [|exact IH].
    destruct a as [f args res|op args res]; [|exact Hhead].
    destruct Hhead as [k [o [Hargs [Hresult Hrow]]]]. exists k, o.
    split; [exact Hargs|]. split; [exact Hresult|now apply Hrows].
  Qed.

  (** Pointwise environment equality retains every concrete query match. *)
  Lemma run_matches_env : forall (w : view (V := V.t)) q s t,
    (forall x, s x = t x) -> matches V.prim w q s -> matches V.prim w q t.
  Proof.
    intros w q s t Heq Hmatches. induction Hmatches as [|a rest Hhead Htail IH];
      constructor; [|exact IH].
    destruct a as [f args res|op args res].
    - destruct Hhead as [k [o [Hargs [Hresult Hrow]]]]. exists k, o.
      split; [eapply run_terms_value_env; eassumption|]. split; [|exact Hrow].
      destruct res as [term|], o as [c|]; try contradiction; [|exact I].
      eapply run_term_value_env; eassumption.
    - destruct Hhead as [k [vs [v [Hargs [Hvalues [Hprim Hresult]]]]]]. exists k, vs, v.
      split; [eapply run_terms_value_env; eassumption|]. split; [exact Hvalues|].
      split; [exact Hprim|]. eapply run_term_value_env; eassumption.
  Qed.

  (** Observable view agreement transports action presence back to the earlier view. *)
  Lemma run_view_agrees_present : forall before after acts s,
    run_view_agrees before after -> present V.prim V.merge after s acts ->
    present V.prim V.merge before s acts.
  Proof.
    intros before after acts s [Hrows [Hsame Hkinds]] Hpresent.
    eapply run_present_transport; [| |exact Hkinds|exact Hpresent].
    - intros f k o Hrow. apply (proj2 (Hrows f k o)). exact Hrow.
    - intros i j Hij. apply (proj2 (Hsame i j)). exact Hij.
  Qed.

  (** Observable view agreement preserves closure under the program's rules. *)
  Lemma run_view_agrees_closed : forall p before after,
    run_view_agrees before after -> closed V.prim V.merge p before ->
    closed V.prim V.merge p after.
  Proof.
    intros p before after Hagree Hclosed r s Hin Hmatches.
    eapply run_view_agrees_present; [exact (run_view_agrees_sym _ _ Hagree)|].
    apply Hclosed; [exact Hin|]. eapply run_matches_rows; [|exact Hmatches].
    intros f k o Hrow. apply (proj2 (proj1 Hagree f k o)). exact Hrow.
  Qed.

  (** A quiet union preserves all observable view components. *)
  Lemma run_quiet_union_view : forall i j db, D.wf db -> D.changed db = false ->
    D.changed (D.union i j db) = false -> run_view_agrees (D.view db) (D.view (D.union i j db)).
  Proof.
    intros i j db Hwf Hquiet Hnext. split.
    - intros f k o. now rewrite (D.union_rows i j db Hwf).
    - split.
      + intros a b. split.
        * intro Hab. apply (proj2 (D.union_same i j db a b Hwf)). apply rst_step. now left.
        * eapply run_quiet_union_same; eassumption.
      + intro f. now rewrite (proj1 (D.layout_union i j db Hwf)).
  Qed.

  (** Quiet typed action execution preserves all observable view components. *)
  Lemma run_apply_go_quiet_view : forall p cp acts g s locals db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    D.changed db = false -> D.changed (apply_go acts s locals db) = false ->
    run_view_agrees (D.view db) (D.view (apply_go acts s locals db)).
  Proof.
    intros p cp acts. induction acts as [|a rest IH]; intros g s locals db
      Hchecked Hwf Hloaded Hacts Henv Hallocated Hquiet Hfinal;
      [apply run_view_agrees_refl|].
    destruct a as [x f args|f args res|t u|x op args]; cbn [actions_ok] in Hacts.
    - destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]].
      destruct (run_term_cells_typed g s locals args ss Henv Hargs)
        as [cells [Hcells Hsorts]].
      pose proof (run_term_cells_allocated db s locals args cells Hallocated Hcells) as Hids.
      assert (Hkinddb : kind (D.view db) f = Some OId).
      { rewrite (proj1 Hloaded). exact Hkind. }
      assert (Hfit : D.slots_fit db f (S (length cells))).
      { eapply run_slots_fit; [exact Hchecked|exact Hloaded|exact Hsort|exact Hkind|].
        rewrite <- Hsorts, length_map. cbn. lia. }
      cbn [apply_go] in Hfinal |- *. rewrite Hcells in Hfinal |- *.
      destruct (D.make f cells db) as [i next] eqn:Hmake.
      pose proof (run_apply_go_quiet_start rest s (PTrieCode.set x (Id i) locals) next Hfinal)
        as Hnextquiet.
      assert (Hafter : D.changed (snd (D.make f cells db)) = false).
      { rewrite Hmake. exact Hnextquiet. }
      destruct (run_quiet_make_reuse db f cells Hwf Hkinddb Hids Hfit Hquiet Hafter)
        as [ri [rn [j [Hcall [Hsame Hrow]]]]].
      rewrite Hmake in Hcall. injection Hcall as Heqi Heqn. subst ri rn next.
      assert (Hnew : D.allocated db i).
      { pose proof (D.layout_make f cells db Hwf) as Hlayout. rewrite Hmake in Hlayout.
        destruct Hlayout as [_ [_ [_ [Hnew _]]]]. exact Hnew. }
      eapply IH; [exact Hchecked|exact Hwf|exact Hloaded|exact Hrest| | |exact Hquiet|exact Hfinal].
      + apply run_env_sorted_set; [exact Henv|reflexivity].
      + apply run_env_allocated_set; [exact Hallocated|].
        intros k Heq. injection Heq as <-. exact Hnew.
    - destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
      destruct (run_term_cells_typed g s locals args ss Henv Hargs)
        as [cells [Hcells Hsorts]].
      destruct (run_result_cell_typed g s locals out res Henv Hresult)
        as [output [Houtput Houtsort]].
      assert (Hrow : row_sorted (program_sorts p) (program_kind p) f cells output).
      { exists out. rewrite Hsorts. repeat split; assumption. }
      assert (Hids : forall i, In (Id i) (cells ++ option_list output) -> D.allocated db i).
      { intros i Hin. apply in_app_iff in Hin as [Hin|Hin].
        - eapply run_term_cells_allocated; eauto.
        - eapply run_result_cell_allocated; eauto. }
      pose proof (run_put_allowed p cp db f cells output Hchecked Hloaded Hrow Hids) as Hallowed.
      destruct (run_put_state p cp f cells output db Hchecked Hwf Hloaded Hrow Hids)
        as [Hwf' [Hloaded' [Hids' _]]].
      cbn [apply_go] in Hfinal |- *. rewrite Hcells, Houtput in Hfinal |- *.
      pose proof (run_apply_go_quiet_start rest s locals (D.put f cells output db) Hfinal)
        as Hnextquiet.
      pose proof (proj1 (D.put_quiet f cells output db Hwf Hallowed Hquiet Hnextquiet)) as Hview.
      assert (Hallocated' : env_allocated (D.put f cells output db) (look s locals)).
      { eapply run_env_allocated_mono with (db := db);
          [rewrite Hids'; reflexivity|exact Hallocated]. }
      pose proof (IH _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated' Hnextquiet Hfinal)
        as Htail. rewrite Hview in Htail. exact Htail.
    - destruct Hacts as [Ht [Hu Hrest]].
      destruct (run_term_cell_typed g s locals t SId Henv Ht)
        as [[i|v] [Hi Hitype]]; [|discriminate].
      destruct (run_term_cell_typed g s locals u SId Henv Hu)
        as [[j|v] [Hj Hjtype]]; [|discriminate].
      pose proof (run_term_cell_allocated db s locals t i Hallocated Hi) as Hiall.
      pose proof (run_term_cell_allocated db s locals u j Hallocated Hj) as Hjall.
      destruct (run_union_state p cp i j db Hwf Hloaded Hiall Hjall)
        as [Hwf' [Hloaded' [Hids' _]]].
      cbn [apply_go] in Hfinal |- *. rewrite Hi, Hj in Hfinal |- *.
      pose proof (run_apply_go_quiet_start rest s locals (D.union i j db) Hfinal) as Hnextquiet.
      assert (Hallocated' : env_allocated (D.union i j db) (look s locals)).
      { eapply run_env_allocated_mono with (db := db);
          [rewrite Hids'; reflexivity|exact Hallocated]. }
      eapply run_view_agrees_trans.
      + eapply run_quiet_union_view; eassumption.
      + exact (IH _ _ _ _ Hchecked Hwf' Hloaded' Hrest Henv Hallocated' Hnextquiet Hfinal).
    - destruct Hacts as [Hargs Hrest].
      destruct (run_term_values_typed g s locals args Henv Hargs) as [vs Hvalues].
      cbn [apply_go] in Hfinal |- *. rewrite Hvalues in Hfinal |- *.
      destruct (V.prim op vs) as [v|]; [|apply run_view_agrees_refl].
      eapply IH; [exact Hchecked|exact Hwf|exact Hloaded|exact Hrest| | |exact Hquiet|exact Hfinal].
      + apply run_env_sorted_set; [exact Henv|reflexivity].
      + apply run_env_allocated_set; [exact Hallocated|]. intros i Heq. discriminate.
  Qed.

  (** A quiet checked rule application preserves rows, equality and declarations. *)
  Lemma run_apply_quiet_view : forall p cp r s db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s -> env_allocated db s ->
    D.changed db = false -> D.changed (apply (actions V.t r) s db) = false ->
    run_view_agrees (D.view db) (D.view (apply (actions V.t r) s db)).
  Proof.
    intros p cp r s db Hchecked Hwf Hloaded Hin Henv Hallocated Hquiet Hfinal.
    destruct (run_rule_context p cp r s Hchecked Hin Henv) as [g [_ [Hacts Hsorted]]].
    unfold apply in *. eapply run_apply_go_quiet_view; try eassumption.
    - intros x ty Hbound. destruct (Hsorted x ty Hbound) as [c [Hc Hsort]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated; exact Hcell.
  Qed.

  (** Environments agree on a context when all of its bound variables agree. *)
  Definition run_context_agrees (g : ctx) (s t : Model.env (V := V.t)) : Prop :=
    forall x ty, g x = Some ty -> s x = t x.

  (** Context agreement preserves the value of a typed term. *)
  Lemma run_term_context : forall g s t (a : term V.t) ty c,
    run_context_agrees g s t -> has g a ty -> term_value s a c -> term_value t a c.
  Proof.
    intros g s t [x|v] ty c Hagree Hhas Hvalue; [|exact Hvalue].
    cbn [has term_value] in *. rewrite <- (Hagree x ty Hhas). exact Hvalue.
  Qed.

  (** Context agreement preserves the values of typed arguments. *)
  Lemma run_terms_context : forall g s t (args : list (term V.t)) ss cs,
    run_context_agrees g s t -> Forall2 (has g) args ss ->
    terms_value s args cs -> terms_value t args cs.
  Proof.
    intros g s t args ss cs Hagree Htyped. revert cs.
    induction Htyped as [|a ty rest types Hhead Htail IH]; intros cs Hvalues.
    - inversion Hvalues. constructor.
    - inversion Hvalues as [|a' c rest' more Hvalue Hmore]; subst a' rest' cs.
      constructor; [eapply run_term_context; eassumption|now apply IH].
  Qed.

  (** Context agreement preserves a list of value-typed arguments. *)
  Lemma run_values_context : forall g s t (args : list (term V.t)) cs,
    run_context_agrees g s t -> Forall (fun a => has g a SVal) args ->
    terms_value s args cs -> terms_value t args cs.
  Proof.
    intros g s t args cs Hagree Htyped. revert cs.
    induction Htyped as [|a rest Hhead Htail IH]; intros cs Hvalues.
    - inversion Hvalues. constructor.
    - inversion Hvalues as [|a' c rest' more Hvalue Hmore]; subst a' rest' cs.
      constructor; [eapply run_term_context; eassumption|now apply IH].
  Qed.

  (** Updating both environments with one cell preserves agreement on the updated context. *)
  Lemma run_context_update : forall g s t x c ty,
    run_context_agrees g s t ->
    run_context_agrees (ctx_set g x ty) (update s x c) (update t x c).
  Proof.
    intros g s t x c ty Hagree y other Hbound. unfold ctx_set in Hbound. unfold update.
    destruct (Pos.eqb x y); [reflexivity|]. eapply Hagree. exact Hbound.
  Qed.

  (** Presence of typed actions depends only on the context's current bindings. *)
  Lemma run_present_agrees : forall sorts kinds acts g w source target,
    @actions_ok V.t sorts kinds g acts -> run_context_agrees g source target ->
    present V.prim V.merge w source acts -> present V.prim V.merge w target acts.
  Proof.
    intros sorts kinds acts. induction acts as [|action rest IH]; intros g w source target
      Htyped Hagree Hpresent; [exact I|].
    destruct action as [x f args|f args res|a b|x op args];
      cbn [actions_ok] in Htyped; cbn [present] in Hpresent |- *.
    - destruct Htyped as [ss [Hsort [Hkind [Hargs Hrest]]]].
      destruct Hpresent as [k [i [Hvalues [Hrow Htail]]]]. exists k, i.
      split; [eapply run_terms_context; eassumption|]. split; [exact Hrow|].
      eapply IH; [exact Hrest| |exact Htail]. now apply run_context_update.
    - destruct Htyped as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
      destruct Hpresent as [k [o [Hvalues [Hrow [Hout Htail]]]]]. exists k, o.
      split; [eapply run_terms_context; eassumption|]. split; [exact Hrow|]. split.
      + destruct res as [a|]; [|exact I]. destruct Hout as [c [d [Ha [Ho Hle]]]].
        exists c, d. split; [|split; assumption].
        destruct out; cbn [has_result out_sort] in Hresult; [contradiction| |];
          eapply run_term_context; eassumption.
      + eapply IH; eassumption.
    - destruct Htyped as [Ha [Hb Hrest]].
      destruct Hpresent as [c [d [Hc [Hd [Hrel Htail]]]]]. exists c, d.
      split; [eapply run_term_context; [exact Hagree|exact Ha|exact Hc]|].
      split; [eapply run_term_context; [exact Hagree|exact Hb|exact Hd]|].
      split; [exact Hrel|]. eapply IH; eassumption.
    - destruct Htyped as [Hargs Hrest].
      destruct Hpresent as [k [vs [Hvalues [Hvals Htail]]]]. exists k, vs.
      split; [eapply run_values_context; eassumption|]. split; [exact Hvals|].
      destruct (V.prim op vs) as [v|]; [|exact I].
      eapply IH; [exact Hrest| |exact Htail]. now apply run_context_update.
  Qed.

  (** Agreement on a closed query's variables covers its final typing context. *)
  Lemma run_query_context_agrees : forall sorts kinds (q : list (atom V.t)) g source target,
    query_ok sorts kinds ctx_empty q g -> agrees source target (flat_map atom_vars q) ->
    run_context_agrees g source target.
  Proof.
    intros sorts kinds q g source target Hquery Hagree x ty Hbound.
    destruct (run_query_bound_fun sorts kinds q g Hquery x ty Hbound)
      as [f [args [res [Hfun Hvar]]]].
    apply Hagree. apply in_flat_map. exists (Fun V.t f args res). split; [exact Hfun|].
    rewrite run_atom_vars_terms. cbn [atom_terms].
    apply run_term_vars_member. exact Hvar.
  Qed.


  Lemma run_unfolds_loop : forall p cp lim db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    match loopN (driver p cp lim) (max_iter lim) (false, db) with
    | inl (_, db') => run p cp lim db = (IterLimit, D.rebuild db')
    | inr (st, db') => run p cp lim db = (st, D.rebuild db')
    end.
  Proof.
    intros p cp lim db _ _ _. unfold run.
    change (limits_iter lim) with (max_iter lim).
    destruct (loopN (driver p cp lim) (max_iter lim) (false, db)) as [[nv db'] | [st db']];
      reflexivity.
  Qed.

  (** A scheduled job is a kept binding of one of the compiled plans. *)
  Lemma run_jobs_member : forall p cp nv db c b,
    In (c, b) (jobs p cp nv db) ->
    In c (all_plans cp) /\ In b (bindings cp c db) /\ keep p c (bind_trie c b) = true.
  Proof.
    intros p cp nv db c b Hin. rewrite jobs_def in Hin.
    apply in_flat_map in Hin as [plan [Hplan Hbinding]].
    apply in_map_iff in Hbinding as [binding [Heq Hkept]].
    inversion Heq; subst plan binding.
    apply filter_In in Hkept as [Hbinding Hkeep].
    split; [|split; assumption]. unfold all_plans.
    apply in_or_app. destruct nv; [left|right]; exact Hplan.
  Qed.

  (** Job facts refer to the database where the bindings were collected. *)
  Definition run_job_facts (p : program V.t) (original : D.t)
      (job : cplan V.t * list (cell V.t)) : Prop :=
    let '(c, b) := job in
    In (job_rule p c) (rules V.t p) /\
    rule_env (program_sorts p) (program_kind p) (job_rule p c) (env_of c b) /\
    env_allocated original (env_of c b) /\
    matches V.prim (D.view original) (query V.t (job_rule p c)) (env_of c b).

  (** Every collected job has a typed, allocated environment and a true query. *)
  Lemma run_jobs_facts : forall p cp nv db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    Forall (run_job_facts p db) (jobs p cp nv db).
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded. apply Forall_forall.
    intros [c b] Hin. cbn [run_job_facts].
    destruct (run_jobs_member p cp nv db c b Hin) as [Hplan [Hbinding Hkeep]].
    pose proof (job_rule_spec p cp c Hchecked Hplan) as Hrule.
    destruct (bindings_rule_env p cp db c b (job_rule p c) Hchecked Hwf Hloaded
      Hplan Hrule Hbinding) as [Henv Hallocated].
    split; [now apply nth_error_In in Hrule|]. split; [exact Henv|].
    split; [exact Hallocated|]. eapply plan_match_sound; eassumption.
  Qed.

  (** The execution trie keeps the job's typing and its original allocated identifiers. *)
  Lemma run_job_environment : forall p original db c b,
    (D.ids original <= D.ids db)%N ->
    rule_env (program_sorts p) (program_kind p) (job_rule p c) (env_of c b) ->
    env_allocated original (env_of c b) ->
    rule_env (program_sorts p) (program_kind p) (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) /\
    env_allocated db (fun x => trie_get x (bind_trie c b)).
  Proof.
    intros p original db c b Hids [g [Hquery Hsorted]] Hallocated. split.
    - exists g. split; [exact Hquery|]. intros x ty Hbound.
      destruct (Hsorted x ty Hbound) as [cell [Hcell Hsort]].
      exists cell. rewrite bind_trie_spec. split; assumption.
    - eapply run_env_allocated_mono; [exact Hids|].
      intros x i Hcell. rewrite bind_trie_spec in Hcell. eapply Hallocated; exact Hcell.
  Qed.

  (** Every kept binding of a naive plan occurs in the naive job list. *)
  Lemma run_naive_job_member : forall p cp db c b,
    In c (naive V.t cp) -> In b (bindings cp c db) ->
    keep p c (bind_trie c b) = true -> In (c, b) (jobs p cp true db).
  Proof.
    intros p cp db c b Hplan Hbinding Hkeep. rewrite jobs_def.
    apply in_flat_map. exists c. split; [exact Hplan|].
    apply in_map. apply filter_In. split; assumption.
  Qed.

  (** Job facts survive view agreement and an increasing allocation counter. *)
  Lemma run_job_facts_agrees : forall p before after cb,
    (D.ids before <= D.ids after)%N -> run_view_agrees (D.view before) (D.view after) ->
    run_job_facts p before cb -> run_job_facts p after cb.
  Proof.
    intros p before after [c b] Hids [Hrows [Hsame Hkinds]]
      [Hrule [Henv [Hallocated Hmatches]]]. cbn [run_job_facts].
    split; [exact Hrule|]. split; [exact Henv|]. split.
    - eapply run_env_allocated_mono; eassumption.
    - eapply run_matches_rows; [|exact Hmatches].
      intros f k o Hrow. apply (proj1 (Hrows f k o)). exact Hrow.
  Qed.

  (** Advancing preserves the validity of jobs saved from the old delta. *)
  Lemma run_job_facts_advance : forall p db js, D.wf db ->
    Forall (run_job_facts p db) js -> Forall (run_job_facts p (D.advance db)) js.
  Proof.
    intros p db js Hwf Hjobs.
    eapply Forall_impl; [|exact Hjobs]. intros cb Hjob.
    eapply run_job_facts_agrees; [| |exact Hjob].
    - rewrite (proj1 (D.advance_keeps db Hwf)). apply N.le_refl.
    - rewrite (proj1 (proj2 (D.wf_advance db Hwf))). apply run_view_agrees_refl.
  Qed.

  (** Executing jobs cannot clear a raised change flag. *)
  Lemma run_apply_jobs_changed : forall p js db, D.changed db = true ->
    D.changed (apply_jobs p js db) = true.
  Proof.
    intros p js. induction js as [|[c b] rest IH]; intros db Hchanged;
      [exact Hchanged|].
    cbn [apply_jobs]. apply IH. unfold apply. now apply run_apply_go_changed.
  Qed.

  (** A quiet completed job list started with a quiet database. *)
  Lemma run_apply_jobs_quiet_start : forall p js db,
    D.changed (apply_jobs p js db) = false -> D.changed db = false.
  Proof.
    intros p js db Hquiet. destruct (D.changed db) eqn:Hchanged; [|reflexivity].
    pose proof (run_apply_jobs_changed p js db Hchanged) as Hraised. congruence.
  Qed.

  (** A quiet job list preserves the view and every scheduled action was already present. *)
  Lemma run_apply_jobs_quiet : forall p cp js db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> row_ids_unique (D.view db) ->
    D.changed db = false -> D.changed (apply_jobs p js db) = false ->
    Forall (run_job_facts p db) js ->
    run_view_agrees (D.view db) (D.view (apply_jobs p js db)) /\
    Forall (fun cb => let '(c, b) := cb in
      present V.prim V.merge (D.view db) (fun x => trie_get x (bind_trie c b))
        (actions V.t (job_rule p c))) js.
  Proof.
    intros p cp js. induction js as [|[c b] rest IH]; intros db Hchecked Hwf Hloaded
      Hunique Hquiet Hfinal Hjobs.
    - split; [apply run_view_agrees_refl|constructor].
    - inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
      destruct Hjob as [Hrule [Henv [Hallocated Hmatches]]].
      destruct (run_job_environment p db db c b (N.le_refl _) Henv Hallocated)
        as [Htyped Hactual_allocated].
      assert (Hactual_matches : matches V.prim (D.view db) (query V.t (job_rule p c))
          (fun x => trie_get x (bind_trie c b))).
      { eapply run_matches_env; [|exact Hmatches]. intro x. symmetry. apply bind_trie_spec. }
      pose (next := apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b)) db).
      change (D.changed (apply_jobs p rest next) = false) in Hfinal.
      pose proof (run_apply_jobs_quiet_start p rest next Hfinal) as Hnextquiet.
      destruct (run_apply_state p cp (job_rule p c)
        (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hrule
        Htyped Hactual_allocated) as [Hnext [Hloadnext [Hidnext Hpending]]].
      assert (Hview : run_view_agrees (D.view db) (D.view next)).
      { eapply run_apply_quiet_view; eassumption. }
      assert (Hunique' : row_ids_unique (D.view next)).
      { eapply run_view_agrees_unique; eassumption. }
      assert (Hfacts' : Forall (run_job_facts p next) rest).
      { eapply Forall_impl; [|exact Hrest]. intros cb Hfact.
        eapply run_job_facts_agrees; eassumption. }
      destruct (IH next Hchecked Hnext Hloadnext Hunique' Hnextquiet Hfinal Hfacts')
        as [Htailview Htail]. split.
      + change (run_view_agrees (D.view db) (D.view (apply_jobs p rest next))).
        eapply run_view_agrees_trans; eassumption.
      + constructor.
        * eapply quiet_apply_present; eassumption.
        * eapply Forall_impl; [|exact Htail]. intros [plan binding] Hpresent.
          eapply run_view_agrees_present; eassumption.
  Qed.

  (** Advancing keeps the loaded state and its allocation counter. *)
  Lemma run_advance_state : forall p cp db, D.wf db -> loaded p cp db ->
    D.wf (D.advance db) /\ loaded p cp (D.advance db) /\
    D.ids (D.advance db) = D.ids db.
  Proof.
    intros p cp db Hwf [Hkinds [Hslots Hsorted]].
    destruct (D.wf_advance db Hwf) as [Hnext [Hview Hchanged]].
    split; [exact Hnext|]. split; [|exact (proj1 (D.advance_keeps db Hwf))].
    split; [intro f; rewrite Hview; apply Hkinds|].
    split; [rewrite D.layout_advance; exact Hslots|]. now rewrite Hview.
  Qed.

  (** A quiet naive round has already made every match's actions present. *)
  Lemma naive_quiet_closed : forall p cp db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    D.canonical db -> D.changed db = false -> D.changed (round p cp true db) = false ->
    closed V.prim V.merge p (D.view db).
  Proof.
    intros p cp db Hchecked Hwf Hloaded Hcanonical Hquiet Hroundquiet.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hids]].
    destruct (D.wf_advance db Hwf) as [_ [Hview Hdown]].
    assert (Hjobsquiet : D.changed (apply_jobs p (jobs p cp true db) (D.advance db)) = false).
    { rewrite round_eq_jobs in Hroundquiet.
      destruct (D.changed (apply_jobs p (jobs p cp true db) (D.advance db))) eqn:Hchanged;
        [|reflexivity].
      pose proof (D.changed_rebuild _ Hchanged) as Hraised. congruence. }
    pose proof (run_jobs_facts p cp true db Hchecked Hwf Hloaded) as Hfacts.
    assert (Hunique : row_ids_unique (D.view (D.advance db))).
    { rewrite Hview. now apply run_canonical_unique. }
    destruct (run_apply_jobs_quiet p cp (jobs p cp true db) (D.advance db) Hchecked
      Hadvanced Hloadadvanced Hunique Hdown Hjobsquiet
      (run_job_facts_advance p db _ Hwf Hfacts)) as [_ Hpresent].
    rewrite Hview in Hpresent.
    intros r s Hin Hmatches.
    destruct (naive_plans_complete p cp db r s Hchecked Hwf Hloaded Hcanonical Hin Hmatches)
      as [c [b [Hnaive [Hrule [Hbinding [Hkeep Hagree]]]]]].
    pose proof (run_naive_job_member p cp db c b Hnaive Hbinding Hkeep) as Hjob.
    apply Forall_forall with (x := (c, b)) in Hpresent; [|exact Hjob].
    assert (Hplan : In c (all_plans cp)).
    { unfold all_plans. apply in_or_app. now left. }
    pose proof (job_rule_spec p cp c Hchecked Hplan) as Hselected.
    assert (Heq : job_rule p c = r) by congruence.
    change (present V.prim V.merge (D.view db) (fun x => trie_get x (bind_trie c b))
      (actions V.t (job_rule p c))) in Hpresent.
    rewrite Heq in Hpresent.
    pose proof (plans_ok_sorted p cp Hchecked) as Hprogram.
    unfold program_ok in Hprogram.
    apply Forall_forall with (x := r) in Hprogram; [|exact Hin].
    destruct Hprogram as [g [Hquery Hacts]].
    pose proof (run_query_context_agrees _ _ _ _ _ _ Hquery Hagree) as Hcontext.
    eapply run_present_agrees; [exact Hacts| |exact Hpresent].
    intros x ty Hbound. rewrite bind_trie_spec. exact (Hcontext x ty Hbound).
  Qed.

  (** Applying saved jobs preserves the loaded state and grows the allocation counter. *)
  Lemma run_apply_jobs_state : forall p cp original js db,
    plans_ok p cp -> Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    D.wf (apply_jobs p js db) /\ loaded p cp (apply_jobs p js db) /\
    (D.ids db <= D.ids (apply_jobs p js db))%N.
  Proof.
    intros p cp original js. induction js as [|[c b] rest IH]; intros db
      Hchecked Hjobs Hwf Hloaded Hids.
    - cbn [apply_jobs]. split; [exact Hwf|]. split; [exact Hloaded|lia].
    - inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
      destruct Hjob as [Hrule [Henv [Hallocated Hmatch]]].
      destruct (run_job_environment p original db c b Hids Henv Hallocated)
        as [Htyped Hallocated_now].
      destruct (run_apply_state p cp (job_rule p c)
        (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hrule
        Htyped Hallocated_now) as [Hnext [Hloadnext [Hidnext Hpending]]].
      destruct (IH _ Hchecked Hrest Hnext Hloadnext (N.le_trans _ _ _ Hids Hidnext))
        as [Hfinal [Hloadfinal Hidfinal]].
      cbn [apply_jobs]. split; [exact Hfinal|]. split; [exact Hloadfinal|lia].
  Qed.

  (** Rebuilding preserves the loaded declarations, slot layout and row sorts. *)
  Lemma run_rebuild_state : forall p cp db, D.wf db -> loaded p cp db ->
    D.wf (D.rebuild db) /\ loaded p cp (D.rebuild db) /\
    D.ids (D.rebuild db) = D.ids db.
  Proof.
    intros p cp db Hwf [Hkinds [Hslots Hsorted]].
    destruct (D.layout_rebuild db Hwf) as [Hkind [Hslot Hids]].
    split; [apply D.wf_rebuild; exact Hwf|]. split; [|exact Hids].
    split; [intro f; rewrite Hkind; apply Hkinds|].
    split; [now rewrite Hslot|]. apply rebuild_preserves_sorted; assumption.
  Qed.

  (** One round preserves the loaded state and never loses allocated identifiers. *)
  Lemma run_round_state : forall p cp nv db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    D.wf (round p cp nv db) /\ loaded p cp (round p cp nv db) /\
    (D.ids db <= D.ids (round p cp nv db))%N.
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded.
    pose proof (run_jobs_facts p cp nv db Hchecked Hwf Hloaded) as Hjobs.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hadvanceids]].
    assert (Hids : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hadvanceids; lia).
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db) Hchecked
      Hjobs Hadvanced Hloadadvanced Hids) as [Hnext [Hloadnext Hidnext]].
    destruct (run_rebuild_state p cp _ Hnext Hloadnext) as [Hfinal [Hloadfinal Hfinalids]].
    rewrite round_eq_jobs. split; [exact Hfinal|]. split; [exact Hloadfinal|lia].
  Qed.

  (** Canonicalizing a key preserves each cell up to the database's identifier equality. *)
  Lemma run_key_canon_rel : forall db (key : list (cell V.t)), D.wf db ->
    Forall2 (cell_rel (same (D.view db))) key (map (D.canon db) key).
  Proof.
    intros db key Hwf. induction key as [|[i|v] rest IH]; cbn [map D.canon].
    - constructor.
    - constructor; [|exact IH]. constructor.
      apply (proj2 (D.same_repr db i (D.repr db i) Hwf)).
      now rewrite D.repr_idem.
    - constructor; [constructor|exact IH].
  Qed.

  (** Canonical growth also supplies the more general row witnesses used by action folds. *)
  Lemma run_grows_upto_of_grows : forall before after, D.wf after ->
    grows before after -> grows_upto before after.
  Proof.
    intros before after Hwf [Hsame Hrows]. split; [exact Hsame|].
    intros f key output Hrow. destruct (Hrows f key output Hrow) as [out [Hfound Hout]].
    exists (map (D.canon after) key), out. split; [exact Hfound|].
    split; [now apply run_key_canon_rel|exact Hout].
  Qed.

  (** A saved job sequence preserves every row and equality from an earlier state. *)
  Lemma run_apply_jobs_grows : forall p cp original js db before,
    plans_ok p cp -> Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    grows_upto before db -> grows_upto before (apply_jobs p js db).
  Proof.
    intros p cp original js. induction js as [|[c b] rest IH]; intros db before
      Hchecked Hjobs Hwf Hloaded Hids Hbefore; [exact Hbefore|].
    inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
    destruct Hjob as [Hrule [Henv [Hallocated Hmatch]]].
    destruct (run_job_environment p original db c b Hids Henv Hallocated)
      as [Htyped Hallocated_now].
    destruct (run_apply_state p cp (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hrule
      Htyped Hallocated_now) as [Hnext [Hloadnext [Hidnext Hpending]]].
    pose proof (apply_grows p cp (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hrule
      Htyped Hallocated_now) as Hstep.
    cbn [apply_jobs]. eapply IH; [exact Hchecked|exact Hrest|exact Hnext
      |exact Hloadnext|eapply N.le_trans; eassumption|].
    exact (run_loaded_growth_trans p cp before db _ Hwf Hnext Hloaded Hloadnext Hbefore Hstep).
  Qed.

  (** Clearing the delta frontier preserves an existing growth relation. *)
  Lemma run_advance_grows : forall before db, D.wf db ->
    grows_upto before db -> grows_upto before (D.advance db).
  Proof.
    intros before db Hwf [Hsame Hrows].
    pose proof (proj1 (proj2 (D.wf_advance db Hwf))) as Hview.
    pose proof (proj2 (proj2 (D.advance_keeps db Hwf))) as Hrepr.
    split; [intros i j Hij; rewrite Hview; now apply Hsame|].
    intros f key output Hrow. destruct (Hrows f key output Hrow)
      as [key' [output' [Hfound [Hkey Hout]]]].
    exists key', output'. split; [now rewrite Hview|].
    split; [now rewrite Hview|]. unfold D.out_le, D.canon in *.
    now rewrite Hview, Hrepr.
  Qed.

  (** Rebuilding a completed round gives canonical witnesses for every earlier row. *)
  Lemma run_round_grows_from : forall p cp nv before db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> grows_upto before db ->
    grows before (round p cp nv db).
  Proof.
    intros p cp nv before db Hchecked Hwf Hloaded Hbefore.
    pose proof (run_jobs_facts p cp nv db Hchecked Hwf Hloaded) as Hjobs.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hadvanceids]].
    assert (Hids : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hadvanceids; lia).
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db) Hchecked
      Hjobs Hadvanced Hloadadvanced Hids) as [Hnext Hstate].
    rewrite round_eq_jobs. apply rebuild_grows; [exact Hnext|].
    eapply run_apply_jobs_grows; [exact Hchecked|exact Hjobs|exact Hadvanced|
      exact Hloadadvanced|exact Hids|]. now apply run_advance_grows.
  Qed.

  (** Each round grows its input database. *)
  Lemma run_round_grows : forall p cp nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> grows db (round p cp nv db).
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded.
    eapply run_round_grows_from; [exact Hchecked|exact Hwf|exact Hloaded|].
    apply (run_grows_upto_refl (program_sorts p)); [exact Hwf|exact (proj2 (proj2 Hloaded))].
  Qed.

  (** A model query atom depends only on pointwise observations of its environment. *)
  Lemma run_model_atom_agree : forall (M : model (V := V.t)) kinds s t a,
    (forall x, s x = t x) -> model_atom V.prim M kinds s a ->
    model_atom V.prim M kinds t a.
  Proof.
    intros M kinds s t [f args res|op args res] Heq Hatom; cbn [model_atom] in *.
    - destruct Hatom as [key [Hterms Hresult]]. exists key. split.
      + eapply run_model_terms_agree; eassumption.
      + destruct (kinds f) as [[| |m]|]; destruct res as [result|];
          cbn in Hresult |- *; try contradiction; try exact Hresult.
        * eapply run_model_term_agree; eassumption.
        * destruct Hresult as [value [Hterm Hlat]]. exists value.
          split; [eapply run_model_term_agree; eassumption|exact Hlat].
    - destruct Hatom as [cells [values [value [Hterms [Hvalues [Hprim Hresult]]]]]].
      exists cells, values, value. split; [eapply run_model_terms_agree; eassumption|].
      split; [exact Hvalues|]. split; [exact Hprim|].
      eapply run_model_term_agree; eassumption.
  Qed.

  (** Saved jobs keep their original model queries as later actions extend the interpretation. *)
  Lemma run_apply_jobs_sat : forall p cp original (M : model (V := V.t)) initial_nu js db nu,
    plans_ok p cp -> D.wf original -> loaded p cp original ->
    sat V.merge M initial_nu (D.view original) -> valid_sorted V.prim V.merge M p ->
    Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    extends original M initial_nu nu -> sat V.merge M nu (D.view db) ->
    exists final_nu, extends db M nu final_nu /\
      sat V.merge M final_nu (D.view (apply_jobs p js db)).
  Proof.
    intros p cp original M initial_nu js.
    induction js as [|[c b] rest IH]; intros db nu Hchecked Horiginal Hloadoriginal
      Hsatoriginal Hvalid Hjobs Hwf Hloaded Hids Hext Hsat.
    - exists nu. split; [intros i Hi; reflexivity|exact Hsat].
    - inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
      destruct Hjob as [Hrule [Henv [Hallocated Hmatch]]].
      destruct (run_job_environment p original db c b Hids Henv Hallocated)
        as [Htyped Hallocated_now].
      assert (Hmodel : Forall
          (model_atom V.prim M (program_kind p)
            (fun x => option_map (den nu) (trie_get x (bind_trie c b))))
          (query V.t (job_rule p c))).
      { pose proof (matched_atoms_model M initial_nu p cp original
          (query V.t (job_rule p c)) (env_of c b) Horiginal Hloadoriginal
          Hsatoriginal Hmatch) as Hinitial.
        eapply Forall_impl; [|exact Hinitial]. intros atom Hatom.
        eapply run_model_atom_agree; [|exact Hatom]. intro x.
        rewrite bind_trie_spec. symmetry.
        exact (run_env_den_ext M initial_nu nu original (env_of c b) Hext Hallocated x). }
      destruct (apply_preserves_sat M nu p cp (job_rule p c)
        (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hallocated_now
        Htyped Hvalid Hrule Hmodel Hsat) as [next_nu [Hextnext Hsatnext]].
      destruct (run_apply_state p cp (job_rule p c)
        (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hrule
        Htyped Hallocated_now) as [Hnext [Hloadnext [Hidnext Hpending]]].
      destruct (IH _ next_nu Hchecked Horiginal Hloadoriginal Hsatoriginal Hvalid Hrest
        Hnext Hloadnext (N.le_trans _ _ _ Hids Hidnext)
        (run_extends_trans M original db initial_nu nu next_nu Hids Hext Hextnext) Hsatnext)
        as [final_nu [Hextfinal Hsatfinal]].
      exists final_nu. cbn [apply_jobs]. split; [|exact Hsatfinal].
      eapply run_extends_trans; eassumption.
  Qed.

  (** A round preserves every sorted model and extends only freshly allocated meanings. *)
  Lemma run_round_sat : forall p cp nv db (M : model (V := V.t)) nu,
    plans_ok p cp -> D.wf db -> loaded p cp db -> valid_sorted V.prim V.merge M p ->
    sat V.merge M nu (D.view db) ->
    exists nu', extends db M nu nu' /\ sat V.merge M nu' (D.view (round p cp nv db)).
  Proof.
    intros p cp nv db M nu Hchecked Hwf Hloaded Hvalid Hsat.
    pose proof (run_jobs_facts p cp nv db Hchecked Hwf Hloaded) as Hjobs.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hadvanceids]].
    assert (Hids : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hadvanceids; lia).
    assert (Hsatadvanced : sat V.merge M nu (D.view (D.advance db))).
    { rewrite (proj1 (proj2 (D.wf_advance db Hwf))). exact Hsat. }
    destruct (run_apply_jobs_sat p cp db M nu (jobs p cp nv db) (D.advance db) nu
      Hchecked Hwf Hloaded Hsat Hvalid Hjobs Hadvanced Hloadadvanced Hids
      (fun i Hi => eq_refl) Hsatadvanced) as [final_nu [Hext Hsatfinal]].
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db) Hchecked
      Hjobs Hadvanced Hloadadvanced Hids) as [Hnext Hstate].
    exists final_nu. split.
    - intros i Hi. apply Hext. unfold D.allocated in *. now rewrite Hadvanceids.
    - rewrite round_eq_jobs. apply D.rebuild_sat; assumption.
  Qed.

  (** A driver step keeps any database invariant respected by rounds. *)
  Lemma run_driver_database_invariant : forall p cp lim (P : D.t -> Prop),
    (forall nv db, P db -> P (round p cp nv db)) ->
    forall nv db, P db ->
    match driver p cp lim (nv, db) with
    | inl next => P (snd next)
    | inr result => P (snd result)
    end.
  Proof.
    intros p cp lim P Hround nv db Hcurrent.
    pose proof (Hround nv db Hcurrent) as Hnext.
    rewrite driver_def. cbn zeta.
    destruct (N.ltb (max_ids lim) (D.ids (round p cp nv db))); [exact Hnext|].
    destruct (andb nv (negb (D.changed (round p cp nv db)))); exact Hnext.
  Qed.

  (** The round's final rebuild canonicalizes its rows and empties pending repairs. *)
  Lemma run_round_canonical : forall p cp nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    D.canonical (round p cp nv db) /\ D.pending (round p cp nv db) = 0.
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hadvanceids]].
    assert (Hids : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hadvanceids; lia).
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db) Hchecked
      (run_jobs_facts p cp nv db Hchecked Hwf Hloaded) Hadvanced Hloadadvanced Hids)
      as [Hnext Hstate].
    rewrite round_eq_jobs. apply D.rebuild_canonical. exact Hnext.
  Qed.

  (** Advancing changes neither the rows nor their representatives. *)
  Lemma run_advance_canonical : forall db, D.wf db -> D.canonical db ->
    D.canonical (D.advance db).
  Proof.
    intros db Hwf Hcanonical. unfold D.canonical in *.
    rewrite (proj1 (proj2 (D.wf_advance db Hwf))),
      (proj2 (proj2 (D.advance_keeps db Hwf))). exact Hcanonical.
  Qed.

  (** A naive phase begins only after a canonical quiet frontier has been established. *)
  Definition run_driver_state (p : program V.t) (cp : compiled V.t)
      (state : bool * D.t) : Prop :=
    let '(nv, db) := state in
    D.wf db /\ loaded p cp db /\
      (nv = true -> D.canonical db /\ D.pending db = 0 /\ D.changed db = false).

  (** Every continuing driver state carries the invariant needed for a later naive check. *)
  Lemma run_driver_state_continue : forall p cp lim start next,
    plans_ok p cp -> run_driver_state p cp start ->
    driver p cp lim start = inl next -> run_driver_state p cp next.
  Proof.
    intros p cp lim [nv db] [nv' db'] Hchecked [Hwf [Hloaded Hfrontier]] Hstep.
    rewrite driver_def in Hstep. cbn zeta in Hstep.
    destruct (N.ltb (max_ids lim) (D.ids (round p cp nv db))) eqn:Hlimit;
      [discriminate|].
    destruct (andb nv (negb (D.changed (round p cp nv db)))) eqn:Hquiet;
      [discriminate|].
    injection Hstep as Hflag Hdb. subst nv' db'. cbn [run_driver_state].
    destruct (run_round_state p cp nv db Hchecked Hwf Hloaded)
      as [Hnext [Hloadnext Hids]].
    destruct (run_round_canonical p cp nv db Hchecked Hwf Hloaded) as [Hcanon Hpending].
    split; [exact Hnext|]. split; [exact Hloadnext|]. intro Hflag.
    split; [exact Hcanon|]. split; [exact Hpending|].
    now apply Bool.negb_true_iff in Hflag.
  Qed.

  (** Binary-fuel iteration keeps a database invariant in both result variants. *)
  Lemma run_loop_database_invariant : forall p cp lim (P : D.t -> Prop),
    (forall nv db, P db -> P (round p cp nv db)) ->
    forall fuel nv db, P db ->
    match loopN (driver p cp lim) fuel (nv, db) with
    | inl next => P (snd next)
    | inr result => P (snd result)
    end.
  Proof.
    intros p cp lim P Hround fuel nv db Hinitial.
    eapply (run_loopN_invariant (bool * D.t) (stop * D.t) (driver p cp lim)
      (fun state => P (snd state)) (fun result => P (snd result))).
    - intros [flag current] next Hcurrent Hstep.
      pose proof (run_driver_database_invariant p cp lim P Hround
        flag current Hcurrent) as Hnext. rewrite Hstep in Hnext. exact Hnext.
    - intros [flag current] result Hcurrent Hstep.
      pose proof (run_driver_database_invariant p cp lim P Hround
        flag current Hcurrent) as Hnext. rewrite Hstep in Hnext. exact Hnext.
    - exact Hinitial.
  Qed.

  (** Every intermediate or stopped loop state is loaded and retains the original allocation. *)
  Lemma run_loop_state : forall p cp lim fuel nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    match loopN (driver p cp lim) fuel (nv, db) with
    | inl next => D.wf (snd next) /\ loaded p cp (snd next) /\
        (D.ids db <= D.ids (snd next))%N
    | inr result => D.wf (snd result) /\ loaded p cp (snd result) /\
        (D.ids db <= D.ids (snd result))%N
    end.
  Proof.
    intros p cp lim fuel nv db Hchecked Hwf Hloaded.
    refine (run_loop_database_invariant p cp lim
      (fun current => D.wf current /\ loaded p cp current /\
        (D.ids db <= D.ids current)%N) _ fuel nv db _).
    - intros flag current [Hcurrent [Hloadcurrent Hids]].
      destruct (run_round_state p cp flag current Hchecked Hcurrent Hloadcurrent)
        as [Hnext [Hloadnext Hidnext]].
      split; [exact Hnext|]. split; [exact Hloadnext|lia].
    - split; [exact Hwf|]. split; [exact Hloaded|lia].
  Qed.


  (** Equal supported identifiers are literally the same stored identifier. *)
  Lemma run_supported_related_equal : forall db (c d : cell V.t),
    row_ids_unique (D.view db) -> run_supported db c -> run_supported db d ->
    cell_rel (same (D.view db)) c d -> c = d.
  Proof.
    intros db c d Hunique Hc Hd Hrel. destruct Hrel as [i j Hij|v]; [|reflexivity].
    destruct Hc as [f [k [o [Hrow Hin]]]]; destruct Hd as [g [key [out [Hother Hmem]]]].
    f_equal. exact (Hunique f k o g key out i j Hrow Hother Hin Hmem Hij).
  Qed.

  (** Pointwise related supported keys are identical in a view with unique row identifiers. *)
  Lemma run_supported_keys_equal : forall db k key, row_ids_unique (D.view db) ->
    Forall (run_supported db) k -> Forall (run_supported db) key ->
    Forall2 (cell_rel (same (D.view db))) k key -> k = key.
  Proof.
    intros db k key Hunique Hleft Hright Hrel. revert Hleft Hright.
    induction Hrel as [|c d rest more Hcd Htail IH]; intros Hleft Hright; [reflexivity|].
    inversion Hleft as [|c' rest' Hc Hrest]; subst c' rest'.
    inversion Hright as [|d' more' Hd Hmore]; subst d' more'.
    f_equal; [eapply run_supported_related_equal; eassumption|now apply IH].
  Qed.

  (** Every cell of a stored key is supported by that row. *)
  Lemma run_row_key_supported : forall db f k o, row (D.view db) f k o ->
    Forall (run_supported db) k.
  Proof.
    intros db f k o Hrow. apply Forall_forall. intros c Hin.
    eapply run_row_supported; [exact Hrow|]. apply in_app_iff. now left.
  Qed.

  (** Unique stored identifiers make all constructor congruences redundant. *)
  Lemma run_unique_congruent : forall db, D.wf db -> row_ids_unique (D.view db) ->
    forall i j, D.cong db i j -> same (D.view db) i j.
  Proof.
    intros db Hwf Hunique i j Hcong.
    induction Hcong as
      [i j Hsame|f k key i j Hrow Hother Hcells IHcells|
       i j Hcong IH|i j k Hleft IHleft Hright IHright].
    - exact Hsame.
    - assert (Hkeys : Forall2 (cell_rel (same (D.view db))) k key).
      { clear Hrow Hother.
        induction IHcells as [|c d rest more Hr Hhead Htail Hall IH]; constructor.
        - destruct Hhead as [a b Hab Hsame|v]; constructor; assumption.
        - exact IH. }
      pose proof (run_supported_keys_equal db k key Hunique
        (run_row_key_supported db f k (Some (Id i)) Hrow)
        (run_row_key_supported db f key (Some (Id j)) Hother) Hkeys) as Heq. subst key.
      pose proof (D.row_functional db f k (Some (Id i)) (Some (Id j)) Hwf Hrow Hother)
        as Hout. injection Hout as <-. now apply run_same_refl.
    - now apply run_same_sym.
    - eapply run_same_trans; eassumption.
  Qed.

  (** Rebuilding a view with unique row identifiers adds no equality. *)
  Lemma run_rebuild_unique_same : forall db, D.wf db -> row_ids_unique (D.view db) ->
    forall i j, same (D.view (D.rebuild db)) i j <-> same (D.view db) i j.
  Proof.
    intros db Hwf Hunique i j. split.
    - intro Hsame. apply (proj1 (D.rebuild_same db i j Hwf)) in Hsame.
      eapply run_unique_congruent; eassumption.
    - intro Hsame. now apply run_rebuild_same_incl.
  Qed.

  (** Canonicalization is injective on supported cells when no stored identifiers merge. *)
  Lemma run_supported_canon_injective : forall db next (c d : cell V.t),
    D.wf next -> row_ids_unique (D.view db) ->
    (forall i j, same (D.view next) i j -> same (D.view db) i j) ->
    run_supported db c -> run_supported db d -> D.canon next c = D.canon next d -> c = d.
  Proof.
    intros db next [i|v] [j|w] Hwf Hunique Hsame Hc Hd Heq;
      cbn [D.canon] in Heq; try discriminate.
    - injection Heq as Hrepr. eapply run_supported_related_equal; try eassumption.
      constructor. apply Hsame. now apply (proj2 (D.same_repr next i j Hwf)).
    - now injection Heq as <-.
  Qed.

  (** Canonicalization is injective on supported keys when no stored identifiers merge. *)
  Lemma run_supported_canon_keys : forall db next k key,
    D.wf next -> row_ids_unique (D.view db) ->
    (forall i j, same (D.view next) i j -> same (D.view db) i j) ->
    Forall (run_supported db) k -> Forall (run_supported db) key ->
    map (D.canon next) k = map (D.canon next) key -> k = key.
  Proof.
    intros db next k key Hwf Hunique Hsame Hleft. revert key.
    induction Hleft as [|c rest Hc Hrest IH]; intros [|d more] Hright Heq;
      cbn [map] in Heq; try discriminate; [reflexivity|].
    inversion Hright as [|d' more' Hd Hmore]; subst d' more'.
    injection Heq as Hhead Htail. f_equal.
    - eapply run_supported_canon_injective; eassumption.
    - now apply IH.
  Qed.

  (** Combining an output with itself is idempotent for every database kind. *)
  Lemma run_combine_idempotent : forall db f o, D.combine db f (Some o) o = o.
  Proof.
    intros db f [[i|v]|]; unfold D.combine;
      destruct (kind (D.view db) f) as [[| |m]|]; try reflexivity.
    now rewrite V.merge_idem.
  Qed.

  (** A fold of identical outputs retains the first output. *)
  Lemma run_combine_identical : forall db f o os, Forall (fun other => other = o) os ->
    fold_left (fun previous next => D.combine db f (Some previous) next) os o = o.
  Proof.
    intros db f o os Hsame. induction Hsame as [|other rest -> Hrest IH];
      cbn [fold_left]; [reflexivity|]. now rewrite run_combine_idempotent.
  Qed.

  (** Merging a nonempty group of identical outputs only canonicalizes that output. *)
  Lemma run_merged_identical : forall db f o os, os <> [] ->
    Forall (fun other => other = o) os -> D.merged db f os = option_map (D.canon db) o.
  Proof.
    intros db f o [|first rest] Hnonempty Hsame; [contradiction|].
    inversion Hsame as [|first' rest' Hfirst Hrest]; subst first' rest' first.
    cbn [D.merged map]. apply run_combine_identical.
    apply Forall_forall. intros output Hin. apply in_map_iff in Hin as [old [<- Hin]].
    rewrite ((proj1 (Forall_forall _ _)) Hrest old Hin). reflexivity.
  Qed.

  (** A rebuilt row in a view with unique identifiers is one canonically renamed old row. *)
  Lemma run_rebuild_unique_origin : forall db, D.wf db -> row_ids_unique (D.view db) ->
    forall f key output, row (D.view (D.rebuild db)) f key output ->
    exists k o, row (D.view db) f k o /\ key = map (D.canon (D.rebuild db)) k /\
      output = option_map (D.canon (D.rebuild db)) o.
  Proof.
    intros db Hwf Hunique f key output Hrow.
    destruct (D.rebuild_from db f key output Hwf Hrow)
      as [srcs [Hnonempty [Hsources Houtput]]].
    destruct srcs as [|[k o] rest]; [contradiction|].
    pose proof Hsources as Hall.
    inversion Hsources as [|first rest' [Hfirst Hkey] Hrest]; subst first rest'.
    cbn [fst snd] in Hfirst, Hkey. exists k, o. split; [exact Hfirst|].
    split; [symmetry; exact Hkey|]. rewrite Houtput.
    apply run_merged_identical; [discriminate|].
    apply Forall_forall. intros old Hin. apply in_map_iff in Hin as [[key' out] [Heq Hin]].
    cbn [snd] in Heq. subst old.
    destruct ((proj1 (Forall_forall _ _)) Hall (key', out) Hin) as [Hsource Hsourcekey].
    cbn [fst snd] in Hsource, Hsourcekey.
    assert (Hkeys : key' = k).
    { eapply run_supported_canon_keys; [apply D.wf_rebuild; exact Hwf|exact Hunique| | | |].
      - intros i j Hij. exact (proj1 (run_rebuild_unique_same db Hwf Hunique i j) Hij).
      - exact (run_row_key_supported db f key' out Hsource).
      - exact (run_row_key_supported db f k o Hfirst).
      - now rewrite Hsourcekey, Hkey. }
    subst key'. eapply D.row_functional; eassumption.
  Qed.

  (** Rebuilding a view with unique identifiers gives exactly its canonically renamed rows. *)
  Lemma run_rebuild_unique_rows : forall db, D.wf db -> row_ids_unique (D.view db) ->
    forall f key output, row (D.view (D.rebuild db)) f key output <->
    exists k o, row (D.view db) f k o /\ key = map (D.canon (D.rebuild db)) k /\
      output = option_map (D.canon (D.rebuild db)) o.
  Proof.
    intros db Hwf Hunique f key output. split.
    - apply run_rebuild_unique_origin; assumption.
    - intros [k [o [Hrow [-> ->]]]].
      destruct (D.rebuild_keeps db f k o Hwf Hrow) as [out [Hkept Hle]].
      destruct (run_rebuild_unique_origin db Hwf Hunique f
        (map (D.canon (D.rebuild db)) k) out Hkept) as [key [output [Hsource [Hkey Hout]]]].
      assert (Hkeys : key = k).
      { eapply run_supported_canon_keys; [apply D.wf_rebuild; exact Hwf|exact Hunique| | | |].
        - intros i j Hij. exact (proj1 (run_rebuild_unique_same db Hwf Hunique i j) Hij).
        - exact (run_row_key_supported db f key output Hsource).
        - exact (run_row_key_supported db f k o Hrow).
        - symmetry. exact Hkey. }
      subst key. pose proof (D.row_functional db f k output o Hwf Hsource Hrow) as ->.
      now rewrite Hout in Hkept.
  Qed.

  (** An identifier-free stored tuple contains no identifier cell. *)
  Lemma run_no_ids_row_identifier : forall db f k o i,
    no_ids db -> row (D.view db) f k o -> In (Id i) (k ++ option_list o) -> False.
  Proof.
    intros db f k o i Hnoids Hrow Hin.
    destruct ((proj2 Hnoids) f k o Hrow) as [-> Hvalues].
    cbn [option_list] in Hin. rewrite app_nil_r in Hin.
    apply Forall_forall with (x := Id i) in Hvalues; [|exact Hin].
    destruct Hvalues as [v Heq]. discriminate.
  Qed.

  (** A database without identifier cells has unique stored identifiers. *)
  Lemma run_no_ids_unique : forall db, no_ids db -> row_ids_unique (D.view db).
  Proof.
    intros db Hnoids f k o g key output i j Hrow Hother Hin Hmem Hsame.
    exfalso. eapply run_no_ids_row_identifier; eassumption.
  Qed.

  (** A database without identifier cells is already canonical. *)
  Lemma run_no_ids_canonical : forall db, no_ids db -> D.canonical db.
  Proof.
    intros db Hnoids f k o Hrow i Hin.
    exfalso. eapply run_no_ids_row_identifier; eassumption.
  Qed.

  (** Rebuilding an identifier-free database preserves each row exactly. *)
  Lemma run_no_ids_rebuild_rows : forall db, D.wf db -> no_ids db ->
    forall f k o, row (D.view (D.rebuild db)) f k o <-> row (D.view db) f k o.
  Proof.
    intros db Hwf Hnoids f k o.
    rewrite (run_rebuild_unique_rows db Hwf (run_no_ids_unique db Hnoids)). split.
    - intros [key [output [Hrow [Hkey Houtput]]]].
      destruct ((proj2 Hnoids) f key output Hrow) as [-> Hvalues].
      rewrite (run_value_key_canon (D.rebuild db) key Hvalues) in Hkey.
      cbn [option_map] in Houtput. subst k o. exact Hrow.
    - intro Hrow. destruct ((proj2 Hnoids) f k o Hrow) as [-> Hvalues].
      exists k, None. split; [exact Hrow|]. split; [|reflexivity].
      now rewrite (run_value_key_canon (D.rebuild db) k Hvalues).
  Qed.

  (** Rebuilding cannot introduce identifiers into an identifier-free database. *)
  Lemma run_no_ids_rebuild : forall db, D.wf db -> no_ids db -> no_ids (D.rebuild db).
  Proof.
    intros db Hwf Hnoids. split.
    - rewrite (proj2 (proj2 (D.layout_rebuild db Hwf))). exact (proj1 Hnoids).
    - intros f k o Hrow. apply (proj1 (run_no_ids_rebuild_rows db Hwf Hnoids f k o)) in Hrow.
      exact ((proj2 Hnoids) f k o Hrow).
  Qed.

  (** An identifier-free rebuild cannot raise or clear the change flag. *)
  Lemma run_no_ids_rebuild_changed : forall db, D.wf db -> no_ids db ->
    D.changed (D.rebuild db) = D.changed db.
  Proof.
    intros db Hwf Hnoids. apply D.rebuild_quiet; [exact Hwf| |].
    - now apply run_no_ids_canonical.
    - apply run_unique_congruent; [exact Hwf|now apply run_no_ids_unique].
  Qed.

  (** Inserting a value-only relational key stores that exact key with no output. *)
  Lemma run_put_none_row : forall db f k, D.wf db -> no_ids db ->
    D.kind_ok db f k None -> Forall (fun c : cell V.t => exists v, c = Val v) k ->
    row (D.view (D.put f k None db)) f k None.
  Proof.
    intros db f k Hwf Hnoids Hallowed Hvalues.
    apply (proj2 (D.put_rows f k None db Hwf Hallowed f k None)).
    rewrite (run_value_key_canon db k Hvalues). right.
    split; [reflexivity|]. split; [reflexivity|].
    destruct (D.old db f k) as [old|] eqn:Hold.
    - apply (proj1 (D.old_row db f k old Hwf)) in Hold.
      destruct ((proj2 Hnoids) f k old Hold) as [-> Hkey]. reflexivity.
    - reflexivity.
  Qed.

  (** Inserting a value-only relation retains every earlier relational row exactly. *)
  Lemma run_put_none_keeps : forall db f k, D.wf db -> no_ids db ->
    D.kind_ok db f k None -> Forall (fun c : cell V.t => exists v, c = Val v) k ->
    forall g key, row (D.view db) g key None ->
      row (D.view (D.put f k None db)) g key None.
  Proof.
    intros db f k Hwf Hnoids Hallowed Hvalues g key Hrow.
    destruct (Pos.eq_dec g f) as [->|Hfunction].
    - destruct (list_eq_dec run_cell_eq_dec key k) as [->|Hkey].
      + eapply run_put_none_row; eassumption.
      + apply (proj2 (D.put_rows f k None db Hwf Hallowed f key None)).
        rewrite (run_value_key_canon db k Hvalues). left. split; [exact Hrow|congruence].
    - apply (proj2 (D.put_rows f k None db Hwf Hallowed g key None)).
      rewrite (run_value_key_canon db k Hvalues). left. split; [exact Hrow|congruence].
  Qed.

  (** A raised relational change flag has a row absent from the round's initial snapshot. *)
  Definition run_relational_progress (initial current : D.t) : Prop :=
    no_ids current /\
    (forall f k, row (D.view initial) f k None -> row (D.view current) f k None) /\
    (D.changed current = true -> exists f k,
      row (D.view current) f k None /\ ~ row (D.view initial) f k None).

  (** A quiet initial snapshot starts the relational progress invariant. *)
  Lemma run_progress_initial : forall db, no_ids db -> D.changed db = false ->
    run_relational_progress db db.
  Proof.
    intros db Hnoids Hquiet. split; [exact Hnoids|]. split; [auto|].
    intro Hchanged. congruence.
  Qed.

  (** A relational insertion either retains an earlier witness or adds a new absent key. *)
  Lemma run_progress_put : forall initial db f k, D.wf db ->
    run_relational_progress initial db -> D.kind_ok db f k None ->
    Forall (fun c : cell V.t => exists v, c = Val v) k ->
    run_relational_progress initial (D.put f k None db).
  Proof.
    intros initial db f k Hwf [Hnoids [Hincludes Hraised]] Hallowed Hvalues.
    split; [eapply run_put_no_ids; eassumption|]. split.
    - intros g key Hrow. eapply run_put_none_keeps; try eassumption. now apply Hincludes.
    - intro Hchanged. destruct (D.changed db) eqn:Hflag.
      + assert (Hfresh : exists g key, row (D.view db) g key None /\
            ~ row (D.view initial) g key None) by (apply Hraised; congruence).
        destruct Hfresh as [g [key [Hrow Habsent]]]. exists g, key.
        split; [eapply run_put_none_keeps; eassumption|exact Habsent].
      + exists f, k. split; [eapply run_put_none_row; eassumption|]. intro Hrow.
        pose proof (D.put_changed f k None db Hwf Hallowed Hflag Hchanged) as Habsent.
        rewrite (run_value_key_canon db k Hvalues) in Habsent.
        apply Habsent. exists None. split; [now apply Hincludes|exact I].
  Qed.

  (** Rebuilding preserves the relational progress witness and initial row inclusion. *)
  Lemma run_progress_rebuild : forall initial db, D.wf db ->
    run_relational_progress initial db -> run_relational_progress initial (D.rebuild db).
  Proof.
    intros initial db Hwf [Hnoids [Hincludes Hraised]].
    split; [now apply run_no_ids_rebuild|]. split.
    - intros f k Hrow. apply (proj2 (run_no_ids_rebuild_rows db Hwf Hnoids f k None)).
      now apply Hincludes.
    - intro Hchanged. rewrite (run_no_ids_rebuild_changed db Hwf Hnoids) in Hchanged.
      destruct (Hraised Hchanged) as [f [k [Hrow Habsent]]]. exists f, k.
      split; [|exact Habsent].
      now apply (proj2 (run_no_ids_rebuild_rows db Hwf Hnoids f k None)).
  Qed.

  (** Typed relational actions preserve the progress witness through their ordered mutations. *)
  Lemma run_apply_go_progress : forall p cp initial acts g s locals db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    forallb relational_action acts = true ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    run_relational_progress initial db ->
    run_relational_progress initial (apply_go acts s locals db).
  Proof.
    intros p cp initial acts. induction acts as [|a rest IH]; intros g s locals db
      Hchecked Hwf Hloaded Hfragment Hrel Hacts Henv Hallocated Hprogress;
      [exact Hprogress|].
    cbn [forallb] in Hrel. apply andb_true_iff in Hrel as [Haction Hrestrel].
    destruct a as [x f args|f args res|t u|x op args]; try discriminate.
    - cbn [actions_ok] in Hacts.
      destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
      pose proof (run_relational_kind p f out Hfragment Hkind) as Hout. subst out.
      destruct res as [t|]; [contradiction|].
      destruct (run_term_cells_typed g s locals args ss Henv Hargs)
        as [cells [Hcells Hsorts]].
      assert (Hrowtyped : row_sorted (program_sorts p) (program_kind p) f cells None).
      { exists ORel. rewrite Hsorts. repeat split; assumption. }
      assert (Hids : forall i, In (Id i) (cells ++ option_list None) -> D.allocated db i).
      { intros i Hin. rewrite app_nil_r in Hin.
        eapply run_term_cells_allocated; eassumption. }
      pose proof (run_put_allowed p cp db f cells None Hchecked Hloaded Hrowtyped Hids)
        as Hallowed.
      destruct (run_put_state p cp f cells None db Hchecked Hwf Hloaded Hrowtyped Hids)
        as [Hwf' [Hloaded' [Hids' Hpending]]].
      pose proof (run_no_ids_terms db s locals args cells (proj1 Hprogress) Hallocated Hcells)
        as Hvalues.
      pose proof (run_progress_put initial db f cells Hwf Hprogress Hallowed Hvalues)
        as Hprogress'.
      assert (Hallocated' : env_allocated (D.put f cells None db) (look s locals)).
      { eapply run_env_allocated_mono with (db := db);
          [rewrite Hids'; reflexivity|exact Hallocated]. }
      cbn [apply_go result_cell]. rewrite Hcells. eapply IH; eassumption.
    - cbn [actions_ok] in Hacts. destruct Hacts as [Hargs Hrest].
      destruct (run_term_values_typed g s locals args Henv Hargs) as [vs Hvalues].
      cbn [apply_go]. rewrite Hvalues. destruct (V.prim op vs) as [v|] eqn:Hprim;
        [|exact Hprogress].
      eapply IH; try eassumption.
      + apply run_env_sorted_set; [exact Henv|reflexivity].
      + apply run_env_allocated_set; [exact Hallocated|]. intros i Heq. discriminate.
  Qed.

  (** Applying a typed relational rule retains the round's progress invariant. *)
  Lemma run_apply_progress : forall p cp initial r s db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    In r (rules V.t p) -> rule_env (program_sorts p) (program_kind p) r s ->
    env_allocated db s -> run_relational_progress initial db ->
    run_relational_progress initial (apply (actions V.t r) s db).
  Proof.
    intros p cp initial r s db Hchecked Hwf Hloaded Hfragment Hin Henv Hallocated Hprogress.
    destruct (run_rule_context p cp r s Hchecked Hin Henv) as [g [_ [Hacts Hsorted]]].
    unfold apply. eapply run_apply_go_progress; try eassumption.
    - eapply run_relational_actions; eassumption.
    - intros x ty Hbound. destruct (Hsorted x ty Hbound) as [c [Hc Hsort]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated; exact Hcell.
  Qed.

  (** Saved relational jobs preserve initial rows and retain a witness for a raised flag. *)
  Lemma run_apply_jobs_progress : forall p cp original js db,
    plans_ok p cp -> relational_fragment p = true -> Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    run_relational_progress original db ->
    run_relational_progress original (apply_jobs p js db).
  Proof.
    intros p cp original js. induction js as [|[c b] rest IH]; intros db
      Hchecked Hfragment Hjobs Hwf Hloaded Hids Hprogress; [exact Hprogress|].
    inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
    destruct Hjob as [Hrule [Henv [Hallocated Hmatch]]].
    destruct (run_job_environment p original db c b Hids Henv Hallocated)
      as [Htyped Hallocated_now].
    destruct (run_apply_state p cp (job_rule p c) (fun x => trie_get x (bind_trie c b)) db
      Hchecked Hwf Hloaded Hrule Htyped Hallocated_now)
      as [Hnext [Hloadnext [Hidnext Hpending]]].
    pose proof (run_apply_progress p cp original (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hfragment
      Hrule Htyped Hallocated_now Hprogress) as Hnextprogress.
    cbn [apply_jobs]. eapply IH; try eassumption. eapply N.le_trans; eassumption.
  Qed.

  (** A changed relational round adds a row absent from its starting view. *)
  Lemma round_changed_adds_row : forall p cp nv db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    relational_fragment p = true -> no_ids db ->
    D.changed (round p cp nv db) = true ->
    exists f k, row (D.view (round p cp nv db)) f k None /\ ~ row (D.view db) f k None.
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded Hfragment Hnoids Hchanged.
    pose proof (run_jobs_facts p cp nv db Hchecked Hwf Hloaded) as Hjobs.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hadvanceids]].
    destruct (D.wf_advance db Hwf) as [_ [Hview Hdown]].
    assert (Hids : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hadvanceids; lia).
    assert (Hinitial : run_relational_progress db (D.advance db)).
    { split.
      - unfold no_ids. rewrite Hadvanceids, Hview. exact Hnoids.
      - split; [intros f k Hrow; now rewrite Hview|]. intro Hraised. congruence. }
    pose proof (run_apply_jobs_progress p cp db (jobs p cp nv db) (D.advance db)
      Hchecked Hfragment Hjobs Hadvanced Hloadadvanced Hids Hinitial) as Hprogress.
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db)
      Hchecked Hjobs Hadvanced Hloadadvanced Hids) as [Hnext Hstate].
    pose proof (run_progress_rebuild db (apply_jobs p (jobs p cp nv db) (D.advance db))
      Hnext Hprogress) as [_ [_ Hraised]].
    rewrite round_eq_jobs in Hchanged |- *. now apply Hraised.
  Qed.

  (** A finite driver trace always starts with its supplied state. *)
  Lemma run_driver_trace_head : forall A B (step : A -> A + B) fuel start,
    nth_error (driver_trace step fuel start) 0 = Some start.
  Proof.
    intros A B step [|fuel] start; reflexivity.
  Qed.

  (** The trace contains at most the initial state and one state per continuing step. *)
  Lemma run_driver_trace_length : forall A B (step : A -> A + B) fuel start,
    length (driver_trace step fuel start) <= fuel + 1.
  Proof.
    intros A B step fuel. induction fuel as [|fuel IH]; intro start.
    - cbn [driver_trace length]. lia.
    - cbn [driver_trace]. destruct (step start) as [next|result]; cbn [length].
      + specialize (IH next). lia.
      + lia.
  Qed.

  (** Adjacent trace entries are exactly one continuing driver transition apart. *)
  Lemma run_driver_trace_chain : forall A B (step : A -> A + B) fuel start n s s',
    nth_error (driver_trace step fuel start) n = Some s ->
    nth_error (driver_trace step fuel start) (S n) = Some s' -> step s = inl s'.
  Proof.
    intros A B step fuel. induction fuel as [|fuel IH]; intros start n s s' Hfirst Hsecond.
    - destruct n; cbn [driver_trace nth_error] in Hsecond; discriminate.
    - cbn [driver_trace] in Hfirst, Hsecond. destruct n as [|n].
      + cbn [nth_error] in Hfirst. injection Hfirst as <-.
        destruct (step start) as [next|result] eqn:Hstep.
        * change (nth_error (driver_trace step fuel next) 0 = Some s') in Hsecond.
          rewrite run_driver_trace_head in Hsecond. injection Hsecond as <-. reflexivity.
        * discriminate Hsecond.
      + destruct (step start) as [next|result] eqn:Hstep.
        * change (nth_error (driver_trace step fuel next) n = Some s) in Hfirst.
          change (nth_error (driver_trace step fuel next) (S n) = Some s') in Hsecond.
          eapply IH; eassumption.
        * destruct n; discriminate Hfirst.
  Qed.

  (** A state invariant preserved by continuing steps holds at every traced state. *)
  Lemma run_driver_trace_invariant : forall A B (step : A -> A + B) (P : A -> Prop),
    (forall state next, P state -> step state = inl next -> P next) ->
    forall fuel start, P start -> Forall P (driver_trace step fuel start).
  Proof.
    intros A B step P Hstep fuel. induction fuel as [|fuel IH]; intros start Hstart.
    - cbn [driver_trace]. constructor; [exact Hstart|constructor].
    - cbn [driver_trace]. constructor; [exact Hstart|].
      destruct (step start) as [next|result] eqn:Hnext; [|constructor].
      apply IH. eapply Hstep; eassumption.
  Qed.

  Lemma trace_spec : forall p cp lim db,
    trace p cp lim db =
      driver_trace (driver p cp lim) (N.to_nat (max_iter lim)) (false, db).
  Proof.
    reflexivity.
  Qed.

  (** A preserved driver invariant holds throughout the public run trace. *)
  Lemma run_trace_invariant : forall p cp lim db (P : bool * D.t -> Prop),
    P (false, db) ->
    (forall state next, P state -> driver p cp lim state = inl next -> P next) ->
    Forall P (trace p cp lim db).
  Proof.
    intros p cp lim db P Hstart Hstep. rewrite trace_spec.
    eapply run_driver_trace_invariant; eassumption.
  Qed.

  Lemma trace_is_chain : forall p cp lim db,
    hd_error (trace p cp lim db) = Some (false, db) /\
    length (trace p cp lim db) <= N.to_nat (max_iter lim) + 1 /\
    forall n s s', nth_error (trace p cp lim db) n = Some s ->
      nth_error (trace p cp lim db) (S n) = Some s' -> driver p cp lim s = inl s'.
  Proof.
    intros p cp lim db. rewrite trace_spec. split.
    - change (nth_error (driver_trace (driver p cp lim)
        (N.to_nat (max_iter lim)) (false, db)) 0 = Some (false, db)).
      apply run_driver_trace_head.
    - split; [apply run_driver_trace_length|].
      intros n s s' Hfirst Hsecond. eapply run_driver_trace_chain; eassumption.
  Qed.

  Lemma round_leaves_idle : forall p cp nv db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    D.canonical (round p cp nv db) /\ D.pending (round p cp nv db) = 0.
  Proof.
    exact run_round_canonical.
  Qed.

  Lemma run_wf : forall p cp lim db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    D.wf (snd (run p cp lim db)) /\ D.canonical (snd (run p cp lim db)) /\
    loaded p cp (snd (run p cp lim db)).
  Proof.
    intros p cp lim db Hchecked Hwf Hloaded.
    pose proof (run_loop_state p cp lim (limits_iter lim) false db Hchecked Hwf Hloaded)
      as Hloop. unfold run.
    destruct (loopN (driver p cp lim) (limits_iter lim) (false, db))
      as [[flag final]|[status final]]; cbn [snd] in *.
    all: destruct Hloop as [Hfinal [Hloadfinal Hids]].
    all: destruct (run_rebuild_state p cp final Hfinal Hloadfinal)
      as [Hrebuilt [Hloadrebuilt Hrebuiltids]].
    all: split; [exact Hrebuilt|].
    all: split; [exact (proj1 (D.rebuild_canonical final Hfinal))|exact Hloadrebuilt].
  Qed.

  Lemma run_grows : forall p cp lim db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    grows db (snd (run p cp lim db)).
  Proof.
    intros p cp lim db Hchecked Hwf Hloaded.
    assert (Hloop : match loopN (driver p cp lim) (limits_iter lim) (false, db) with
      | inl next => D.wf (snd next) /\ loaded p cp (snd next) /\ grows_upto db (snd next)
      | inr result => D.wf (snd result) /\ loaded p cp (snd result) /\
          grows_upto db (snd result)
      end).
    { refine (run_loop_database_invariant p cp lim
        (fun current => D.wf current /\ loaded p cp current /\ grows_upto db current)
        _ (limits_iter lim) false db _).
      - intros flag current [Hcurrent [Hloadcurrent Hgrowth]].
        destruct (run_round_state p cp flag current Hchecked Hcurrent Hloadcurrent)
          as [Hnext [Hloadnext Hids]].
        split; [exact Hnext|]. split; [exact Hloadnext|].
        apply run_grows_upto_of_grows; [exact Hnext|].
        eapply run_round_grows_from; eassumption.
      - split; [exact Hwf|]. split; [exact Hloaded|].
        apply (run_grows_upto_refl (program_sorts p));
          [exact Hwf|exact (proj2 (proj2 Hloaded))]. }
    unfold run. destruct (loopN (driver p cp lim) (limits_iter lim) (false, db))
      as [[flag final]|[status final]]; cbn [snd] in *;
      destruct Hloop as [Hfinal [Hloadfinal Hgrowth]];
      apply rebuild_grows; assumption.
  Qed.

  Lemma run_sat : forall p cp lim db (M : model (V := V.t)) nu,
    plans_ok p cp -> D.wf db -> loaded p cp db -> valid_sorted V.prim V.merge M p ->
    sat V.merge M nu (D.view db) -> exists nu',
      (forall i, D.allocated db i -> nu' i = nu i) /\
      sat V.merge M nu' (D.view (snd (run p cp lim db))).
  Proof.
    intros p cp lim db M nu Hchecked Hwf Hloaded Hvalid Hsat.
    set (Inv := fun current => D.wf current /\ loaded p cp current /\
      (D.ids db <= D.ids current)%N /\
      exists current_nu, extends db M nu current_nu /\
        sat V.merge M current_nu (D.view current)).
    assert (Hloop : match loopN (driver p cp lim) (limits_iter lim) (false, db) with
      | inl next => Inv (snd next)
      | inr result => Inv (snd result)
      end).
    { refine (run_loop_database_invariant p cp lim Inv _ (limits_iter lim) false db _).
      - intros flag current [Hcurrent [Hloadcurrent [Hids [current_nu [Hext Hsatcurrent]]]]].
        destruct (run_round_state p cp flag current Hchecked Hcurrent Hloadcurrent)
          as [Hnext [Hloadnext Hidnext]].
        destruct (run_round_sat p cp flag current M current_nu Hchecked Hcurrent
          Hloadcurrent Hvalid Hsatcurrent) as [next_nu [Hextnext Hsatnext]].
        split; [exact Hnext|]. split; [exact Hloadnext|]. split; [lia|].
        exists next_nu. split; [|exact Hsatnext].
        eapply run_extends_trans; eassumption.
      - split; [exact Hwf|]. split; [exact Hloaded|]. split; [lia|].
        exists nu. split; [intros i Hi; reflexivity|exact Hsat]. }
    unfold run. destruct (loopN (driver p cp lim) (limits_iter lim) (false, db))
      as [[flag final]|[status final]]; cbn [snd] in *.
    all: destruct Hloop as [Hfinal [Hloadfinal [Hids [final_nu [Hext Hsatfinal]]]]].
    all: exists final_nu; split; [exact Hext|]; apply D.rebuild_sat; assumption.
  Qed.

  (** Renaming a supported cell and returning to its canonical source recovers the cell. *)
  Lemma run_canon_roundtrip : forall before after c,
    D.wf before -> D.wf after -> D.canonical before ->
    (forall i j, same (D.view after) i j -> same (D.view before) i j) ->
    run_supported before c -> D.canon before (D.canon after c) = c.
  Proof.
    intros before after [i|v] Hbefore Hafter Hcanonical Hsame Hsupport; [|reflexivity].
    destruct Hsupport as [f [k [o [Hrow Hin]]]].
    pose proof (Hcanonical f k o Hrow i Hin) as Hfixed. cbn [D.canon]. f_equal.
    assert (Hrel : same (D.view after) (D.repr after i) i).
    { apply (proj2 (D.same_repr after (D.repr after i) i Hafter)).
      now rewrite D.repr_idem by exact Hafter. }
    pose proof (proj1 (D.same_repr before (D.repr after i) i Hbefore) (Hsame _ _ Hrel))
      as Heq. now rewrite Hfixed in Heq.
  Qed.

  (** A supported key is recovered after a round trip between equivalent representatives. *)
  Lemma run_canon_key_roundtrip : forall before after k,
    D.wf before -> D.wf after -> D.canonical before ->
    (forall i j, same (D.view after) i j -> same (D.view before) i j) ->
    Forall (run_supported before) k ->
    map (D.canon before) (map (D.canon after) k) = k.
  Proof.
    intros before after k Hbefore Hafter Hcanonical Hsame Hsupport.
    induction Hsupport as [|c rest Hc Hrest IH]; cbn [map]; [reflexivity|].
    rewrite IH. f_equal. eapply run_canon_roundtrip; eassumption.
  Qed.

  (** A stored output is recovered after a round trip between equivalent representatives. *)
  Lemma run_canon_output_roundtrip : forall before after f k o,
    D.wf before -> D.wf after -> D.canonical before ->
    (forall i j, same (D.view after) i j -> same (D.view before) i j) ->
    row (D.view before) f k o ->
    option_map (D.canon before) (option_map (D.canon after) o) = o.
  Proof.
    intros before after f k [c|] Hbefore Hafter Hcanonical Hsame Hrow; [|reflexivity].
    cbn [option_map]. f_equal. eapply run_canon_roundtrip; try eassumption.
    eapply run_row_supported; [exact Hrow|]. apply in_app_iff. right. now left.
  Qed.

  (** Canonically renamed environments preserve concrete term evaluation. *)
  Lemma run_term_value_canon : forall db source target (term : term V.t) c,
    (forall x, target x = option_map (D.canon db) (source x)) ->
    term_value source term c -> term_value target term (D.canon db c).
  Proof.
    intros db source target [x|v] c Henv Hterm.
    - cbn [term_value] in *. now rewrite Henv, Hterm.
    - cbn [term_value] in *. subst c. reflexivity.
  Qed.

  (** Canonically renamed environments preserve argument evaluation. *)
  Lemma run_terms_value_canon : forall db source target args cs,
    (forall x, target x = option_map (D.canon db) (source x)) ->
    terms_value source args cs -> terms_value target args (map (D.canon db) cs).
  Proof.
    intros db source target args cs Henv Hterms.
    induction Hterms as [|term c rest more Hhead Htail IH]; cbn [map]; constructor.
    - eapply run_term_value_canon; eassumption.
    - exact IH.
  Qed.

  (** Canonicalization leaves the value arguments of primitives unchanged. *)
  Lemma run_values_canon : forall db cs vs, values cs vs -> values (map (D.canon db) cs) vs.
  Proof.
    intros db cs vs Hvalues. induction Hvalues as [|c v rest more Hhead Htail IH];
      cbn [map]; constructor; [subst c; reflexivity|exact IH].
  Qed.

  (** Equal identifiers have equal canonical representatives in the same database. *)
  Lemma run_same_canon : forall db i j, D.wf db -> same (D.view db) i j ->
    same (D.view db) (D.repr db i) (D.repr db j).
  Proof.
    intros db i j Hwf Hsame. apply (proj2 (D.same_repr db _ _ Hwf)).
    rewrite !D.repr_idem by exact Hwf. now apply (proj1 (D.same_repr db i j Hwf)).
  Qed.

  (** Canonical renaming preserves output containment when equality and kinds are retained. *)
  Lemma run_cell_le_canon : forall (before : view (V := V.t)) after f c d,
    D.wf after ->
    (forall i j, same before i j -> same (D.view after) i j) ->
    (forall g, kind (D.view after) g = kind before g) ->
    cell_le V.merge before f c d ->
    cell_le V.merge (D.view after) f (D.canon after c) (D.canon after d).
  Proof.
    intros before after f [i|v] [j|w] Hwf Hsame Hkinds Hle;
      cbn [cell_le D.canon] in *; try contradiction.
    - apply run_same_canon; [exact Hwf|now apply Hsame].
    - destruct Hle as [m [Hkind Hmerge]]. exists m. split; [now rewrite Hkinds|exact Hmerge].
  Qed.

  (** Presence transports through an exact canonical renaming of rows. *)
  Lemma run_present_canon : forall (before : view (V := V.t)) after acts source target,
    D.wf after ->
    (forall f k o, row before f k o ->
      row (D.view after) f (map (D.canon after) k) (option_map (D.canon after) o)) ->
    (forall i j, same before i j -> same (D.view after) i j) ->
    (forall f, kind (D.view after) f = kind before f) ->
    (forall x, target x = option_map (D.canon after) (source x)) ->
    present V.prim V.merge before source acts ->
    present V.prim V.merge (D.view after) target acts.
  Proof.
    intros before after acts. induction acts as [|action rest IH]; intros source target
      Hwf Hrows Hsame Hkinds Henv Hpresent; [exact I|].
    destruct action as [x f args|f args res|a b|x op args];
      cbn [present] in Hpresent |- *.
    - destruct Hpresent as [k [i [Hterms [Hrow Htail]]]].
      exists (map (D.canon after) k), (D.repr after i).
      split; [eapply run_terms_value_canon; eassumption|]. split; [exact (Hrows _ _ _ Hrow)|].
      eapply IH; try eassumption. intro y. unfold update.
      destruct (Pos.eqb x y); [reflexivity|apply Henv].
    - destruct Hpresent as [k [o [Hterms [Hrow [Hresult Htail]]]]].
      exists (map (D.canon after) k), (option_map (D.canon after) o).
      split; [eapply run_terms_value_canon; eassumption|]. split; [exact (Hrows _ _ _ Hrow)|].
      split.
      + destruct res as [term|]; [|exact I].
        destruct Hresult as [c [d [Hterm [Ho Hle]]]].
        exists (D.canon after c), (D.canon after d).
        split; [eapply run_term_value_canon; eassumption|]. split; [now rewrite Ho|].
        eapply run_cell_le_canon; eassumption.
      + eapply IH; eassumption.
    - destruct Hpresent as [c [d [Ha [Hb [Hrel Htail]]]]].
      exists (D.canon after c), (D.canon after d).
      split; [eapply run_term_value_canon; [exact Henv|exact Ha]|].
      split; [eapply run_term_value_canon; [exact Henv|exact Hb]|]. split.
      + destruct c as [i|v], d as [j|w]; try exact I.
        apply run_same_canon; [exact Hwf|now apply Hsame].
      + eapply IH; eassumption.
    - destruct Hpresent as [k [vs [Hterms [Hvalues Htail]]]].
      exists (map (D.canon after) k), vs.
      split; [eapply run_terms_value_canon; eassumption|]. split; [now apply run_values_canon|].
      destruct (V.prim op vs) as [v|]; [|exact I].
      eapply IH; try eassumption. intro y. unfold update.
      destruct (Pos.eqb x y); [reflexivity|apply Henv].
  Qed.

  (** Pulling rows back through canonicalization also pulls matching queries back. *)
  Lemma run_matches_pullback : forall before after q source,
    (forall f k o, row (D.view after) f k o ->
      row (D.view before) f (map (D.canon before) k) (option_map (D.canon before) o)) ->
    matches V.prim (D.view after) q source ->
    matches V.prim (D.view before) q (fun x => option_map (D.canon before) (source x)).
  Proof.
    intros before after q source Hrows Hmatches.
    induction Hmatches as [|atom rest Hatom Hrest IH]; constructor; [|exact IH].
    destruct atom as [f args res|op args result]; cbn [atom_holds] in Hatom |- *.
    - destruct Hatom as [k [o [Hterms [Hresult Hrow]]]].
      exists (map (D.canon before) k), (option_map (D.canon before) o).
      split; [eapply run_terms_value_canon; [reflexivity|exact Hterms]|].
      split; [|now apply Hrows].
      destruct res as [term|], o as [c|]; try contradiction; [|exact I].
      eapply run_term_value_canon; [reflexivity|exact Hresult].
    - destruct Hatom as [k [vs [v [Hterms [Hvalues [Hprim Hresult]]]]]].
      exists (map (D.canon before) k), vs, v.
      split; [eapply run_terms_value_canon; [reflexivity|exact Hterms]|].
      split; [now apply run_values_canon|]. split; [exact Hprim|].
      change (term_value (fun x => option_map (D.canon before) (source x)) result
        (D.canon before (Val v))).
      eapply run_term_value_canon; [reflexivity|exact Hresult].
  Qed.

  (** Rule closure is invariant under a bijective canonical renaming of stored identifiers. *)
  Lemma run_closed_canonical_rename : forall p before after,
    program_ok p -> D.wf before -> D.wf after -> D.canonical before -> D.canonical after ->
    (forall i j, same (D.view after) i j <-> same (D.view before) i j) ->
    (forall f, kind (D.view after) f = kind (D.view before) f) ->
    (forall f key output, row (D.view after) f key output <->
      exists k o, row (D.view before) f k o /\ key = map (D.canon after) k /\
        output = option_map (D.canon after) o) ->
    closed V.prim V.merge p (D.view before) -> closed V.prim V.merge p (D.view after).
  Proof.
    intros p before after Hprogram Hbefore Hafter Hcanonical Hcanonical_after
      Hsame Hkinds Hrows Hclosed.
    unfold program_ok in Hprogram.
    assert (Hpush : forall f k o, row (D.view before) f k o ->
      row (D.view after) f (map (D.canon after) k) (option_map (D.canon after) o)).
    { intros f k o Hrow. apply (proj2 (Hrows _ _ _)). exists k, o.
      split; [exact Hrow|]. split; reflexivity. }
    assert (Hpull : forall f k o, row (D.view after) f k o ->
      row (D.view before) f (map (D.canon before) k) (option_map (D.canon before) o)).
    { intros f key output Hrow. apply (proj1 (Hrows _ _ _)) in Hrow.
      destruct Hrow as [k [o [Hsource [-> ->]]]].
      rewrite (run_canon_key_roundtrip before after k Hbefore Hafter Hcanonical
        (fun i j => proj1 (Hsame i j)) (run_row_key_supported before f k o Hsource)).
      rewrite (run_canon_output_roundtrip before after f k o Hbefore Hafter Hcanonical
        (fun i j => proj1 (Hsame i j)) Hsource). exact Hsource. }
    intros r source Hin Hmatches.
    destruct ((proj1 (Forall_forall _ _)) Hprogram r Hin) as [g [Hquery Hacts]].
    pose (back := fun x => option_map (D.canon before) (source x)).
    assert (Hback : matches V.prim (D.view before) (query V.t r) back).
    { eapply run_matches_pullback; eassumption. }
    pose proof (Hclosed r back Hin Hback) as Hpresent.
    pose (forward := fun x => option_map (D.canon after) (back x)).
    assert (Hforward : present V.prim V.merge (D.view after) forward (actions V.t r)).
    { eapply run_present_canon; [exact Hafter|exact Hpush| |exact Hkinds| |exact Hpresent].
      - intros i j Hij. exact (proj2 (Hsame i j) Hij).
      - reflexivity. }
    eapply run_present_agrees; [exact Hacts| |exact Hforward].
    intros x ty Hbound. unfold forward, back. destruct (source x) as [c|] eqn:Hlookup;
      cbn [option_map]; [|reflexivity]. f_equal.
    eapply run_canon_roundtrip; [exact Hafter|exact Hbefore|exact Hcanonical_after| |].
    - intros i j Hij. exact (proj2 (Hsame i j) Hij).
    - eapply run_query_supported; eassumption.
  Qed.

  (** Rebuilding a view equivalent to a canonical closed view retains rule closure. *)
  Lemma run_quiet_rebuild_closed : forall p cp before current,
    plans_ok p cp -> D.wf before -> D.wf current -> D.canonical before ->
    run_view_agrees (D.view before) (D.view current) ->
    closed V.prim V.merge p (D.view before) ->
    closed V.prim V.merge p (D.view (D.rebuild current)).
  Proof.
    intros p cp before current Hchecked Hbefore Hcurrent Hcanonical Hagree Hclosed.
    assert (Hunique : row_ids_unique (D.view current)).
    { eapply run_view_agrees_unique; [exact Hagree|]. now apply run_canonical_unique. }
    destruct Hagree as [Hrows [Hsame Hkinds]].
    eapply run_closed_canonical_rename; [exact (plans_ok_sorted p cp Hchecked)|exact Hbefore|
      apply D.wf_rebuild; exact Hcurrent|exact Hcanonical|
      exact (proj1 (D.rebuild_canonical current Hcurrent))| | | |exact Hclosed].
    - intros i j. rewrite (run_rebuild_unique_same current Hcurrent Hunique i j).
      symmetry. apply Hsame.
    - intro f. rewrite (proj1 (D.layout_rebuild current Hcurrent)). symmetry. apply Hkinds.
    - intros f key output. rewrite (run_rebuild_unique_rows current Hcurrent Hunique).
      split; intros [k [o [Hrow [Hkey Hout]]]]; exists k, o; split.
      + apply (proj2 (Hrows _ _ _)). exact Hrow.
      + split; assumption.
      + apply (proj1 (Hrows _ _ _)). exact Hrow.
      + split; assumption.
  Qed.

  (** A quiet naive confirmation is closed also in its rebuilt output view. *)
  Lemma run_quiet_round_closed : forall p cp db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    D.canonical db -> D.changed db = false -> D.changed (round p cp true db) = false ->
    closed V.prim V.merge p (D.view (round p cp true db)).
  Proof.
    intros p cp db Hchecked Hwf Hloaded Hcanonical Hquiet Hroundquiet.
    pose proof (naive_quiet_closed p cp db Hchecked Hwf Hloaded Hcanonical
      Hquiet Hroundquiet) as Hclosed.
    pose proof (run_jobs_facts p cp true db Hchecked Hwf Hloaded) as Hjobs.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hadvanceids]].
    destruct (D.wf_advance db Hwf) as [_ [Hview Hdown]].
    assert (Hids : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hadvanceids; lia).
    assert (Hjobsquiet : D.changed (apply_jobs p (jobs p cp true db) (D.advance db)) = false).
    { rewrite round_eq_jobs in Hroundquiet.
      destruct (D.changed (apply_jobs p (jobs p cp true db) (D.advance db))) eqn:Hchanged;
        [|reflexivity]. pose proof (D.changed_rebuild _ Hchanged) as Hraised. congruence. }
    destruct (run_apply_jobs_state p cp db (jobs p cp true db) (D.advance db) Hchecked Hjobs
      Hadvanced Hloadadvanced Hids) as [Hnext Hrest].
    assert (Hunique : row_ids_unique (D.view (D.advance db))).
    { rewrite Hview. now apply run_canonical_unique. }
    destruct (run_apply_jobs_quiet p cp (jobs p cp true db) (D.advance db) Hchecked
      Hadvanced Hloadadvanced Hunique Hdown Hjobsquiet
      (run_job_facts_advance p db _ Hwf Hjobs)) as [Hagree Hpresent].
    rewrite Hview in Hagree. rewrite round_eq_jobs.
    exact (run_quiet_rebuild_closed p cp db (apply_jobs p (jobs p cp true db) (D.advance db))
      Hchecked Hwf Hnext Hcanonical Hagree Hclosed).
  Qed.

  (** A saturated driver result is canonical, has no pending repairs, and is closed. *)
  Lemma run_driver_closed_stop : forall p cp lim start result,
    plans_ok p cp -> run_driver_state p cp start ->
    driver p cp lim start = inr (Saturated, result) ->
    D.wf result /\ D.canonical result /\ D.pending result = 0 /\
      closed V.prim V.merge p (D.view result).
  Proof.
    intros p cp lim [nv db] result Hchecked [Hwf [Hloaded Hfrontier]] Hstep.
    cbn [driver] in Hstep.
    destruct (N.ltb (limits_ids lim) (D.ids (round p cp nv db))); [discriminate|].
    destruct (nv && negb (D.changed (round p cp nv db))) eqn:Hquiet; [|discriminate].
    injection Hstep as <-. apply andb_true_iff in Hquiet as [Hnaive Hquiet].
    subst nv. apply negb_true_iff in Hquiet.
    destruct (Hfrontier eq_refl) as [Hcanonical [Hpending Hunchanged]].
    destruct (run_round_state p cp true db Hchecked Hwf Hloaded) as [Hnext Hrest].
    destruct (run_round_canonical p cp true db Hchecked Hwf Hloaded) as [Hcanon Hempty].
    split; [exact Hnext|]. split; [exact Hcanon|]. split; [exact Hempty|].
    eapply run_quiet_round_closed; eassumption.
  Qed.

  Lemma run_closed : forall p cp lim db db', plans_ok p cp -> D.wf db -> loaded p cp db ->
    run p cp lim db = (Saturated, db') -> closed V.prim V.merge p (D.view db').
  Proof.
    intros p cp lim db db' Hchecked Hwf Hloaded Hresult.
    assert (Hloop : match loopN (driver p cp lim) (max_iter lim) (false, db) with
      | inl next => run_driver_state p cp next
      | inr stopped => fst stopped = Saturated ->
          D.wf (snd stopped) /\ D.canonical (snd stopped) /\ D.pending (snd stopped) = 0 /\
            closed V.prim V.merge p (D.view (snd stopped))
      end).
    { eapply run_loopN_invariant with (P := run_driver_state p cp).
      - intros start next Hstate Hstep. eapply run_driver_state_continue; eassumption.
      - intros start [status result] Hstate Hstep Hstatus. cbn [fst] in Hstatus. subst status.
        eapply run_driver_closed_stop; eassumption.
      - cbn [run_driver_state]. split; [exact Hwf|]. split; [exact Hloaded|]. discriminate. }
    pose proof (run_unfolds_loop p cp lim db Hchecked Hwf Hloaded) as Hrun.
    destruct (loopN (driver p cp lim) (max_iter lim) (false, db))
      as [[nv current]|[status current]].
    - rewrite Hrun in Hresult. discriminate.
    - rewrite Hrun in Hresult.
      injection Hresult as Hstatus Hdb. subst status db'.
      destruct (Hloop eq_refl) as [Hcurrent [Hcanonical [Hpending Hclosed]]].
      now rewrite (D.rebuild_idle current Hcurrent Hcanonical Hpending).
  Qed.


  (** Evaluating one argument list in one environment determines its cells uniquely. *)
  Lemma run_terms_value_unique : forall (s : Model.env (V := V.t)) ts first second,
    terms_value s ts first -> terms_value s ts second -> first = second.
  Proof.
    intros s ts first second Hfirst. revert second.
    induction Hfirst as [|t c ts cs Hterm Htail IH]; intros second Hsecond.
    - inversion Hsecond. reflexivity.
    - inversion Hsecond as [|t' c' ts' cs' Hterm' Htail']; subst.
      f_equal.
      + destruct t; cbn [term_value] in Hterm, Hterm'; congruence.
      + now apply IH.
  Qed.

  (** A list of value cells determines its primitive arguments uniquely. *)
  Lemma run_values_unique : forall (cs : list (cell V.t)) first second,
    values cs first -> values cs second -> first = second.
  Proof.
    intros cs first second Hfirst. revert second.
    induction Hfirst as [|c v cs vs Hvalue Htail IH]; intros second Hsecond.
    - inversion Hsecond. reflexivity.
    - inversion Hsecond as [|c' v' cs' vs' Hvalue' Htail']; subst.
      f_equal; [congruence|now apply IH].
  Qed.

  (** Rows in a sorted relational comparison view have no output. *)
  Lemma run_relational_view_outputs : forall (p : program V.t) (w : view (V := V.t)),
    relational_fragment p = true -> (forall f, kind w f = program_kind p f) ->
    view_sorted (program_sorts p) w -> forall f k o, row w f k o -> o = None.
  Proof.
    intros p w Hfragment Hkinds Hsorted f k o Hrow.
    destruct (Hsorted f k o Hrow) as [out [Hsort [Hkind Houtput]]].
    rewrite Hkinds in Hkind.
    pose proof (run_relational_kind p f out Hfragment Hkind) as Hout. subst out.
    destruct o; [discriminate|reflexivity].
  Qed.

  (** Every derivable action output occurs in a view where those actions are present. *)
  Lemma run_derivation_action_present : forall (w : view (V := V.t)),
    (forall f k o, row w f k o -> o = None) ->
    forall s acts f k, derivation_action V.prim s acts f k ->
      present V.prim V.merge w s acts -> row w f k None.
  Proof.
    intros w Houtputs s acts f k Hderivation.
    induction Hderivation as
      [s f args k rest Hterms
      |s f args input rest g k Hterms Htail IH
      |s x op args k vs v rest f output Hterms Hvalues Hprim Htail IH]; intro Hpresent.
    - destruct Hpresent as [key [output [Hterms' [Hrow Hrest]]]].
      pose proof (run_terms_value_unique s args k key Hterms Hterms') as Heq. subst key.
      now rewrite (Houtputs f k output Hrow) in Hrow.
    - destruct Hpresent as [key [output [Hterms' [Hrow [Hout Hrest]]]]].
      now apply IH.
    - destruct Hpresent as [key [values' [Hterms' [Hvalues' Hrest]]]].
      pose proof (run_terms_value_unique s args k key Hterms Hterms') as Heq. subst key.
      pose proof (run_values_unique k vs values' Hvalues Hvalues') as Heq. subst values'.
      rewrite Hprim in Hrest. now apply IH.
  Qed.

  Scheme run_derives_ind := Induction for derives Sort Prop
  with run_derivation_body_ind := Induction for derivation_body Sort Prop.

  (** Relational derivations occur in every output-free closed extension of their facts. *)
  Lemma run_derives_closed : forall p (initial final : view (V := V.t)),
    closed V.prim V.merge p final -> includes initial final ->
    (forall f k o, row final f k o -> o = None) ->
    forall f k, derives V.prim p initial f k -> row final f k None.
  Proof.
    intros p initial final Hclosed Hinclude Houtputs.
    refine (@run_derives_ind V.t V.prim p initial
      (fun f k _ => row final f k None)
      (fun s q _ => matches V.prim final q s) _ _ _ _ _).
    - intros f k Hrow. now apply Hinclude.
    - intros r s f k Hin Hbody IHbody Haction.
      eapply run_derivation_action_present; [exact Houtputs|exact Haction|].
      apply Hclosed; [exact Hin|exact IHbody].
    - intro s. constructor.
    - intros s f args k rest Hterms Hderive IHderive Hbody IHbody.
      constructor; [|exact IHbody]. exists k, None.
      split; [exact Hterms|]. split; [exact I|exact IHderive].
    - intros s op args res k vs v rest Hterms Hvalues Hprim Hresult Hbody IHbody.
      constructor; [|exact IHbody]. exists k, vs, v.
      split; [exact Hterms|]. split; [exact Hvalues|]. split; assumption.
  Qed.

  Lemma derives_least : forall p db w f k, relational_fragment p = true ->
    no_ids db -> closed V.prim V.merge p w -> includes (D.view db) w ->
    (forall g, kind w g = program_kind p g) -> view_sorted (program_sorts p) w ->
    derives V.prim p (D.view db) f k -> row w f k None.
  Proof.
    intros p db w f k Hfragment Hnoids Hclosed Hinclude Hkinds Hsorted Hderive.
    eapply run_derives_closed; [exact Hclosed|exact Hinclude| |exact Hderive].
    eapply run_relational_view_outputs; eassumption.
  Qed.

  (** Every row of an identifier-free initial database is an initial derivation. *)
  Lemma run_derived_initial : forall p db, no_ids db -> derived p db db.
  Proof.
    intros p db Hnoids f k o Hrow.
    destruct ((proj2 Hnoids) f k o Hrow) as [-> Hvalues]. now apply derive_fact.
  Qed.

  (** Matches in a derived relational snapshot supply derivation bodies. *)
  Lemma run_matches_derivation_body : forall p initial db q s,
    no_ids db -> derived p initial db -> matches V.prim (D.view db) q s ->
    derivation_body V.prim p (D.view initial) s q.
  Proof.
    intros p initial db q s Hnoids Hderived Hmatches.
    induction Hmatches as [|a rest Hhead Htail IH]; [constructor|].
    destruct a as [f args res|op args res].
    - destruct Hhead as [k [o [Hargs [Hresult Hrow]]]].
      destruct ((proj2 Hnoids) f k o Hrow) as [-> Hvalues].
      destruct res as [term|]; [contradiction|].
      eapply derive_body_fun; [exact Hargs|eapply Hderived; exact Hrow|exact IH].
    - destruct Hhead as [k [vs [v [Hargs [Hvalues [Hprim Hresult]]]]]].
      eapply derive_body_prim; eassumption.
  Qed.

  (** Checked saved jobs derive every inserted row from their original matched snapshot. *)
  Lemma run_apply_jobs_derives : forall p cp initial original js db,
    plans_ok p cp -> relational_fragment p = true ->
    no_ids original -> derived p initial original -> Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    no_ids db -> derived p initial db ->
    no_ids (apply_jobs p js db) /\ derived p initial (apply_jobs p js db).
  Proof.
    intros p cp initial original js. induction js as [|[c b] rest IH]; intros db
      Hchecked Hfragment Horiginal_noids Horiginal_derived Hjobs Hwf Hloaded Hids
      Hnoids Hderived; [split; assumption|].
    inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
    destruct Hjob as [Hrule [Henv [Hallocated Hmatches]]].
    destruct (run_job_environment p original db c b Hids Henv Hallocated)
      as [Htyped Hallocated_now].
    assert (Hactual_matches : matches V.prim (D.view original) (query V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b))).
    { eapply run_matches_env; [|exact Hmatches]. intro x. symmetry. apply bind_trie_spec. }
    pose proof (run_matches_derivation_body p initial original _ _ Horiginal_noids
      Horiginal_derived Hactual_matches) as Hbody.
    destruct (run_apply_state p cp (job_rule p c) (fun x => trie_get x (bind_trie c b)) db
      Hchecked Hwf Hloaded Hrule Htyped Hallocated_now)
      as [Hnext [Hloadnext [Hidnext Hpending]]].
    destruct (run_apply_derives_checked p cp initial db (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) Hchecked Hwf Hloaded Hfragment Hnoids Hderived
      Hrule Htyped Hallocated_now Hbody) as [Hnoidsnext Hderivednext].
    cbn [apply_jobs]. eapply IH; try eassumption. eapply N.le_trans; eassumption.
  Qed.

  (** Rebuilding an identifier-free derived database retains its exact derivations. *)
  Lemma run_rebuild_derives : forall p initial db,
    D.wf db -> no_ids db -> derived p initial db ->
    no_ids (D.rebuild db) /\ derived p initial (D.rebuild db).
  Proof.
    intros p initial db Hwf Hnoids Hderived. split.
    - now apply run_no_ids_rebuild.
    - intros f k o Hrow. apply Hderived with (o := o).
      apply (proj1 (run_no_ids_rebuild_rows db Hwf Hnoids f k o)). exact Hrow.
  Qed.

  (** Advancing cannot introduce identifiers into an identifier-free database. *)
  Lemma run_no_ids_advance : forall db, D.wf db -> no_ids db -> no_ids (D.advance db).
  Proof.
    intros db Hwf Hnoids. split.
    - rewrite (proj1 (D.advance_keeps db Hwf)). exact (proj1 Hnoids).
    - intros f k o Hrow.
      rewrite (proj1 (proj2 (D.wf_advance db Hwf))) in Hrow.
      exact ((proj2 Hnoids) f k o Hrow).
  Qed.

  (** Advancing retains every relational derivation because it retains the view. *)
  Lemma run_advance_derives : forall p initial db,
    D.wf db -> derived p initial db -> derived p initial (D.advance db).
  Proof.
    intros p initial db Hwf Hderived f k o Hrow.
    rewrite (proj1 (proj2 (D.wf_advance db Hwf))) in Hrow. eapply Hderived. exact Hrow.
  Qed.

  (** Each checked relational round preserves derivability and has no identifiers. *)
  Lemma run_round_derives : forall p cp initial nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    no_ids db -> derived p initial db ->
    no_ids (round p cp nv db) /\ derived p initial (round p cp nv db).
  Proof.
    intros p cp initial nv db Hchecked Hwf Hloaded Hfragment Hnoids Hderived.
    pose proof (run_jobs_facts p cp nv db Hchecked Hwf Hloaded) as Hjobs.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvance [Hloadadvance Hids]].
    assert (Hidbound : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hids; reflexivity).
    pose proof (run_no_ids_advance db Hwf Hnoids) as Hnoidsadvance.
    pose proof (run_advance_derives p initial db Hwf Hderived) as Hderivedadvance.
    destruct (run_apply_jobs_derives p cp initial db (jobs p cp nv db) (D.advance db)
      Hchecked Hfragment Hnoids Hderived Hjobs Hadvance Hloadadvance Hidbound
      Hnoidsadvance Hderivedadvance) as [Hnoidsnext Hderivednext].
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db) Hchecked Hjobs
      Hadvance Hloadadvance Hidbound) as [Hnext Hrest].
    rewrite round_eq_jobs. now apply run_rebuild_derives.
  Qed.

  (** A checked relational round does not allocate identifiers. *)
  Lemma run_round_no_ids : forall p cp nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    no_ids db -> no_ids (round p cp nv db).
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded Hfragment Hnoids.
    exact (proj1 (run_round_derives p cp db nv db Hchecked Hwf Hloaded Hfragment
      Hnoids (run_derived_initial p db Hnoids))).
  Qed.

  (** A checked relational run retains a derivation for every final row and allocates no ids. *)
  Lemma run_derives_state : forall p cp lim db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    no_ids db -> no_ids (snd (run p cp lim db)) /\ derived p db (snd (run p cp lim db)).
  Proof.
    intros p cp lim db Hchecked Hwf Hloaded Hfragment Hnoids.
    assert (Hloop : match loopN (driver p cp lim) (max_iter lim) (false, db) with
      | inl next => D.wf (snd next) /\ loaded p cp (snd next) /\
          no_ids (snd next) /\ derived p db (snd next)
      | inr result => D.wf (snd result) /\ loaded p cp (snd result) /\
          no_ids (snd result) /\ derived p db (snd result)
      end).
    { refine (run_loop_database_invariant p cp lim
        (fun current => D.wf current /\ loaded p cp current /\
          no_ids current /\ derived p db current) _ (max_iter lim) false db _).
      - intros nv current [Hcurrent [Hloadcurrent [Hnoidscurrent Hderivedcurrent]]].
        destruct (run_round_state p cp nv current Hchecked Hcurrent Hloadcurrent)
          as [Hnext [Hloadnext Hidnext]].
        destruct (run_round_derives p cp db nv current Hchecked Hcurrent Hloadcurrent
          Hfragment Hnoidscurrent Hderivedcurrent) as [Hnoidsnext Hderivednext].
        split; [exact Hnext|]. split; [exact Hloadnext|]. split; assumption.
      - split; [exact Hwf|]. split; [exact Hloaded|]. split; [exact Hnoids|].
        now apply run_derived_initial. }
    pose proof (run_unfolds_loop p cp lim db Hchecked Hwf Hloaded) as Hrun.
    destruct (loopN (driver p cp lim) (max_iter lim) (false, db))
      as [[nv current]|[status current]].
    all: rewrite Hrun; cbn [snd].
    all: destruct Hloop as [Hcurrent [Hloadcurrent [Hnoidscurrent Hderivedcurrent]]].
    all: apply run_rebuild_derives; assumption.
  Qed.

  (** A checked relational run never introduces identifiers. *)
  Lemma run_no_ids : forall p cp lim db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    no_ids db -> no_ids (snd (run p cp lim db)).
  Proof.
    intros p cp lim db Hchecked Hwf Hloaded Hfragment Hnoids.
    exact (proj1 (run_derives_state p cp lim db Hchecked Hwf Hloaded Hfragment Hnoids)).
  Qed.

  Lemma run_derives : forall p cp lim db f k o, plans_ok p cp -> D.wf db -> loaded p cp db ->
    relational_fragment p = true -> no_ids db ->
    row (D.view (snd (run p cp lim db))) f k o -> derives V.prim p (D.view db) f k.
  Proof.
    intros p cp lim db f k o Hchecked Hwf Hloaded Hfragment Hnoids Hrow.
    exact (proj2 (run_derives_state p cp lim db Hchecked Hwf Hloaded Hfragment Hnoids)
      f k o Hrow).
  Qed.

  Lemma run_least : forall p cp lim db db', plans_ok p cp -> D.wf db -> loaded p cp db ->
    relational_fragment p = true -> no_ids db -> run p cp lim db = (Saturated, db') ->
    forall w, closed V.prim V.merge p w -> includes (D.view db) w ->
      (forall f, kind w f = program_kind p f) -> view_sorted (program_sorts p) w ->
      includes (D.view db') w.
  Proof.
    intros p cp lim db db' Hchecked Hwf Hloaded Hfragment Hnoids Hrun w
      Hclosed Hinclude Hkinds Hsorted.
    destruct (run_derives_state p cp lim db Hchecked Hwf Hloaded Hfragment Hnoids)
      as [Hnoidsfinal Hderived].
    rewrite Hrun in Hnoidsfinal, Hderived. cbn [snd] in Hnoidsfinal, Hderived.
    intros f k o Hrow. destruct ((proj2 Hnoidsfinal) f k o Hrow) as [-> Hvalues].
    eapply derives_least; [exact Hfragment|exact Hnoids|exact Hclosed|exact Hinclude|
      exact Hkinds|exact Hsorted|]. eapply Hderived. exact Hrow.
  Qed.

  (** Constant sources consumed by a term scan come from its literal terms. *)
  Lemma run_check_terms_constants : forall (P : V.t -> Prop) ts names pos seen copy inv
      srcs columns copied copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    (forall v, In (Lit v) ts -> P v) ->
    Forall (fun src => match src with Const _ c => exists v, c = Val v /\ P v
      | _ => True end) srcs' ->
    Forall (fun src => match src with Const _ c => exists v, c = Val v /\ P v
      | _ => True end) srcs.
  Proof.
    intros P ts. induction ts as [|t ts IH]; intros names pos seen copy inv srcs columns
      copied copy' inv' srcs' columns' copied' Hscan Hliterals Htail.
    - cbn [check_terms] in Hscan. inversion Hscan; subst. exact Htail.
    - assert (Hrest : forall v, In (Lit v) ts -> P v).
      { intros v Hin. apply Hliterals. now right. }
      destruct t as [x|v]; cbn [check_terms] in Hscan.
      + destruct (trie_get x seen).
        * eapply IH; eassumption.
        * destruct (trie_get x names); [eapply IH; eassumption|discriminate].
      + destruct srcs as [|src srcs]; [discriminate|].
        destruct src as [s|s|c]; try discriminate.
        destruct c as [i|w]; [discriminate|].
        destruct columns as [|lv columns]; [discriminate|].
        destruct lv as [|j lv]; [discriminate|]. destruct lv; [|discriminate].
        destruct (V.eqb w v) eqn:Heq; [|discriminate].
        destruct (V.eqb_spec w v) as [Hwv|Hwv]; [subst w|discriminate]. constructor.
        * exists v. split; [reflexivity|]. apply Hliterals. now left.
        * eapply IH; eassumption.
  Qed.

  (** Every constant source of an accepted query is one of that query's literals. *)
  Lemma run_check_query_constants : forall (P : V.t -> Prop) q newok names n table ai
      copy used count srcs columns post finalcount expected,
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (finalcount, [], [], expected) ->
    (forall a v, In a q -> In (Lit v) (atom_terms a) -> P v) ->
    Forall (fun src => match src with Const _ c => exists v, c = Val v /\ P v
      | _ => True end) srcs.
  Proof.
    intros P q. induction q as [|a q IH]; intros newok names n table ai copy used count
      srcs columns post finalcount expected Hcheck Hliterals.
    - cbn [check_query] in Hcheck. inversion Hcheck; subst. constructor.
    - assert (Hrest : forall a v, In a q -> In (Lit v) (atom_terms a) -> P v).
      { intros a' v Hin Hlit. eapply Hliterals; [right; exact Hin|exact Hlit]. }
      destruct a as [f args res|op args res]; cbn [check_query] in Hcheck.
      + destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
          copy used count srcs columns)
          as [[[[[[nextcopy nextused] nextcount] nextsrcs] nextcols] copied]|]
          eqn:Hatom; [|discriminate].
        destruct (run_check_atom_parts newok names n table f (args ++ option_list res)
          copy used count srcs columns nextcopy nextused nextcount nextsrcs nextcols
          copied Hatom) as [src [src_tail [lv [col_tail [s [inv [perm
          [Hsrcs [Hcols [Hsource [Hcolumn [Hlength [Hterms [Hperm Hslot]]]]]]]]]]]]]].
        subst srcs columns. constructor.
        * destruct src; try exact I. discriminate Hsource.
        * eapply run_check_terms_constants; [exact Hterms| |].
          -- intros v Hin. eapply Hliterals; [now left|exact Hin].
          -- eapply IH; eassumption.
      + eapply IH; eassumption.
  Qed.

  (** Literals in a rule's query belong to the program's term list. *)
  Lemma run_program_query_literal : forall (p : program V.t) r a v,
    In r (rules V.t p) -> In a (query V.t r) -> In (Lit v) (atom_terms a) ->
    In (Lit v) (program_terms p).
  Proof.
    intros p [q acts] a v Hrule Hatom Hliteral.
    unfold program_terms. apply in_flat_map. exists (Rule V.t q acts).
    split; [exact Hrule|]. cbn. apply in_or_app. left. apply in_flat_map.
    exists a. split; assumption.
  Qed.

  (** Checked plans contain only program literals in their constant sources. *)
  Lemma run_plan_constants : forall p cp c, plans_ok p cp -> In c (all_plans cp) ->
    Forall (fun src => match src with
      | Const _ cell => exists v, cell = Val v /\ In (Lit v) (program_terms p)
      | _ => True end) (sources V.t c).
  Proof.
    intros p cp c Hchecked Hin.
    destruct (run_plan_member p cp c Hchecked Hin)
      as [table [newok [r [Htable [Hrule Hcheck]]]]].
    destruct (run_check_cplan_parts newok table (rule_ix V.t c) r c Hcheck)
      as [_ [Hlength [names [expected [Hnames [Hlayout [Hquery Hpost]]]]]]].
    eapply run_check_query_constants; [exact Hquery|]. intros a v Hatom Hliteral.
    eapply run_program_query_literal; [eapply nth_error_In; exact Hrule|exact Hatom|exact Hliteral].
  Qed.

  (** Every value in a checked source is active in the source database. *)
  Lemma run_source_mem_active : forall p db src u v,
    D.wf db ->
    (match src with Const _ c => exists w, c = Val w /\ In (Lit w) (program_terms p)
      | _ => True end) ->
    I.mem (source_index db src) u -> In (Val v) u -> active_value p db v.
  Proof.
    intros p db [s|s|c] u v Hwf Hsafe Hmem Hin; cbn [source_index] in Hmem.
    - destruct (D.index_all db s false u Hwf Hmem)
        as [f [perm [k [o [Hslot [Hrow Heq]]]]]].
      right. exists s, u. split.
      + unfold D.slot_of in Hslot. apply nth_error_Some. rewrite Hslot. discriminate.
      + split; assumption.
    - destruct (D.index_all db s true u Hwf Hmem)
        as [f [perm [k [o [Hslot [Hrow Heq]]]]]].
      right. exists s, u. split.
      + unfold D.slot_of in Hslot. apply nth_error_Some. rewrite Hslot. discriminate.
      + split; [subst u; eapply D.index_all_complete; eassumption|exact Hin].
    - destruct Hsafe as [w [-> Hliteral]].
      apply (proj1 (I.mem_insert 1 [Val w] I.empty u (I.wf_empty 1) eq_refl)) in Hmem.
      destruct Hmem as [->|Hempty].
      + cbn [In] in Hin. destruct Hin as [Heq|Hin]; [|contradiction].
        injection Heq as <-. now left.
      + exfalso. exact (I.mem_empty u Hempty).
  Qed.

  (** Every value selected from a checked join column is active in its source database. *)
  Lemma run_source_columns_active : forall p db srcs columns b,
    D.wf db ->
    Forall (fun src => match src with
      | Const _ c => exists v, c = Val v /\ In (Lit v) (program_terms p)
      | _ => True end) srcs ->
    Forall2 (fun lv ix => exists u, J.project lv b = Some u /\ I.mem ix u)
      columns (map (source_index db) srcs) ->
    forall lv j v, In lv columns -> In j lv -> nth_error b j = Some (Val v) ->
      active_value p db v.
  Proof.
    intros p db srcs columns b Hwf Hsources. revert columns.
    induction Hsources as [|src srcs Hhead Htail IH]; intros columns Hanswer lv j v
      Hcol Hj Hnth.
    - inversion Hanswer; subst. contradiction.
    - destruct columns as [|col columns]; inversion Hanswer as
        [|lv' ix columns' ixs Hsource Hrest]; subst.
      destruct Hcol as [Heq|Hcol].
      + subst lv. destruct Hsource as [u [Hproject Hmem]].
        eapply run_source_mem_active; [exact Hwf|exact Hhead|exact Hmem|].
        eapply run_project_selected; eassumption.
      + eapply IH; eassumption.
  Qed.

  (** The environment of a checked binding contains only active values. *)
  Lemma run_plan_bindings_active : forall p cp db c b,
    plans_ok p cp -> D.wf db -> loaded p cp db -> In c (all_plans cp) ->
    In b (bindings cp c db) ->
    forall x v, env_of c b x = Some (Val v) -> active_value p db v.
  Proof.
    intros p cp db c b Hchecked Hwf Hloaded Hin Hbinding x v Henv.
    pose proof (run_plan_join_wf p cp db c Hchecked Hwf Hloaded Hin) as Hjoin.
    destruct (J.run_sound (join V.t c) (map (source_index db) (sources V.t c)) b
      Hjoin Hbinding) as [Hlength Hanswer].
    destruct Hjoin as [_ [_ Hcover]]. apply run_binding_env_member in Henv.
    apply In_nth_error in Henv. destruct Henv as [j Hnth].
    assert (Hbound : j < nvars (join V.t c)).
    { rewrite <- Hlength. apply nth_error_Some. rewrite Hnth. discriminate. }
    destruct (Hcover j Hbound) as [lv [Hcol Hj]].
    eapply run_source_columns_active; [exact Hwf| |exact Hanswer|exact Hcol|exact Hj|exact Hnth].
    now apply run_plan_constants with (cp := cp).
  Qed.

  (** New rows use initially active values; existing rows retain their exact old keys. *)
  Definition run_domain (p : program V.t) (initial current : D.t) : Prop :=
    no_ids current /\ D.slots current = D.slots initial /\
    forall f k o, row (D.view current) f k o -> row (D.view initial) f k o \/
      Forall (fun c => exists v, c = Val v /\ active_value p initial v) k.

  (** Every initial row satisfies the old-row branch of the domain invariant. *)
  Lemma run_domain_initial : forall p db, no_ids db -> run_domain p db db.
  Proof.
    intros p db Hnoids. split; [exact Hnoids|]. split; [reflexivity|].
    intros f k o Hrow. now left.
  Qed.

  (** The same slot layout witnesses every previously indexed value in the seed. *)
  Lemma run_domain_active : forall p initial current,
    D.wf initial -> D.wf current -> run_domain p initial current ->
    forall v, active_value p current v -> active_value p initial v.
  Proof.
    intros p initial current Hinitial Hcurrent [Hnoids [Hslots Hrows]] v Hactive.
    destruct Hactive as [Hliteral|[s [u [Hbound [Hmem Hin]]]]]; [now left|].
    destruct (D.index_all current s false u Hcurrent Hmem)
      as [f [perm [k [o [Hslot [Hrow Heq]]]]]].
    destruct (Hrows f k o Hrow) as [Hold|Hkey].
    - right. exists s, u. split; [now rewrite <- Hslots|]. split; [|exact Hin].
      subst u. apply (D.index_all_complete initial s f perm k o Hinitial); [|exact Hold].
      unfold D.slot_of in *. now rewrite <- Hslots.
    - destruct ((proj2 Hnoids) f k o Hrow) as [-> Hvalues].
      subst u. apply run_permute_member in Hin.
      cbn [option_list] in Hin. rewrite app_nil_r in Hin.
      apply Forall_forall with (x := Val v) in Hkey; [|exact Hin].
      destruct Hkey as [w [Heq Hactive]]. injection Heq as ->. exact Hactive.
  Qed.

  (** Inserting one active relational key preserves the initial-domain invariant. *)
  Lemma run_domain_put : forall p initial db f k,
    D.wf db -> run_domain p initial db -> D.kind_ok db f k None ->
    Forall (fun c => exists v, c = Val v /\ active_value p initial v) k ->
    run_domain p initial (D.put f k None db).
  Proof.
    intros p initial db f k Hwf [Hnoids [Hslots Hrows]] Hallowed Hkey.
    assert (Hvalues : Forall (fun c : cell V.t => exists v, c = Val v) k).
    { eapply Forall_impl; [|exact Hkey]. intros c [v [Hcell Hactive]]. now exists v. }
    split; [eapply run_put_no_ids; eassumption|]. split.
    - rewrite (proj1 (proj2 (D.layout_put f k None db Hwf))). exact Hslots.
    - intros g key output Hrow.
      destruct (run_put_none_origin db f k Hwf Hnoids Hallowed Hvalues g key output Hrow)
        as [Hold|[-> [-> ->]]]; [now apply Hrows|now right].
  Qed.

  (** Identifier-free rebuilding preserves every exact row and its initial-domain witness. *)
  Lemma run_domain_rebuild : forall p initial db,
    D.wf db -> run_domain p initial db -> run_domain p initial (D.rebuild db).
  Proof.
    intros p initial db Hwf [Hnoids [Hslots Hrows]].
    split; [now apply run_no_ids_rebuild|]. split.
    - rewrite (proj1 (proj2 (D.layout_rebuild db Hwf))). exact Hslots.
    - intros f k o Hrow. apply Hrows.
      apply (proj1 (run_no_ids_rebuild_rows db Hwf Hnoids f k o)). exact Hrow.
  Qed.

  (** Advancing keeps rows, slots and the absence of identifiers. *)
  Lemma run_domain_advance : forall p initial db,
    D.wf db -> run_domain p initial db -> run_domain p initial (D.advance db).
  Proof.
    intros p initial db Hwf [Hnoids [Hslots Hrows]].
    split; [now apply run_no_ids_advance|]. split; [now rewrite D.layout_advance|].
    intros f k o Hrow. apply Hrows.
    now rewrite (proj1 (proj2 (D.wf_advance db Hwf))) in Hrow.
  Qed.

  (** Terms can select only environment values or literal values. *)
  Lemma run_term_cells_active : forall p initial db s locals ts cs,
    no_ids db -> env_allocated db (look s locals) ->
    (forall x v, look s locals x = Some (Val v) -> active_value p initial v) ->
    (forall v, In (Lit v) ts -> active_value p initial v) ->
    term_cells s locals ts = Some cs ->
    Forall (fun c => exists v, c = Val v /\ active_value p initial v) cs.
  Proof.
    intros p initial db s locals ts. induction ts as [|t rest IH]; intros cs Hnoids
      Hallocated Henv Hliterals Hcells.
    - cbn [term_cells] in Hcells. injection Hcells as <-. constructor.
    - cbn [term_cells] in Hcells.
      destruct (term_cell s locals t) as [c|] eqn:Hcell; [|discriminate].
      destruct (term_cells s locals rest) as [more|] eqn:Hrest; [|discriminate].
      injection Hcells as <-. constructor.
      + destruct t as [x|v]; cbn [term_cell] in Hcell.
        * destruct c as [i|v].
          -- exfalso. pose proof (Hallocated x i Hcell) as Hi.
             unfold D.allocated in Hi. rewrite (proj1 Hnoids) in Hi. lia.
          -- exists v. split; [reflexivity|]. eapply Henv. exact Hcell.
        * injection Hcell as <-. exists v. split; [reflexivity|].
          apply Hliterals. now left.
      + eapply IH; try eassumption; try reflexivity.
        intros v Hin. apply Hliterals. now right.
  Qed.

  (** Program action literals belong to the seed's active domain. *)
  Lemma run_program_action_literal : forall (p : program V.t) initial r a v,
    In r (rules V.t p) -> In a (actions V.t r) -> In (Lit v) (action_terms a) ->
    active_value p initial v.
  Proof.
    intros p initial [q acts] a v Hrule Haction Hliteral. left.
    unfold program_terms. apply in_flat_map. exists (Rule V.t q acts).
    split; [exact Hrule|]. cbn. apply in_or_app. right. apply in_flat_map.
    exists a. split; assumption.
  Qed.

  (** Primitive-free rules have no action that computes a fresh value. *)
  Lemma run_prim_free_actions : forall (p : program V.t) r, prim_free p = true ->
    In r (rules V.t p) ->
    forallb (fun a => match a with Let _ _ _ => false | _ => true end) (actions V.t r) = true.
  Proof.
    intros p [q acts] Hfree Hrule. unfold prim_free in Hfree.
    apply forallb_forall with (x := Rule V.t q acts) in Hfree; [|exact Hrule].
    apply andb_true_iff in Hfree as [_ Hactions]. exact Hactions.
  Qed.

  (** Typed primitive-free relational actions preserve the initial active domain. *)
  Lemma run_apply_go_domain : forall p cp initial acts g s locals db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    forallb relational_action acts = true ->
    forallb (fun a => match a with Let _ _ _ => false | _ => true end) acts = true ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    (forall x v, look s locals x = Some (Val v) -> active_value p initial v) ->
    (forall a v, In a acts -> In (Lit v) (action_terms a) -> active_value p initial v) ->
    run_domain p initial db -> run_domain p initial (apply_go acts s locals db).
  Proof.
    intros p cp initial acts. induction acts as [|a rest IH]; intros g s locals db
      Hchecked Hwf Hloaded Hfragment Hrel Hfree Hacts Henv Hallocated Hactive Hliterals
      Hdomain; [exact Hdomain|].
    cbn [forallb] in Hrel, Hfree.
    apply andb_true_iff in Hrel as [Haction Hrestrel].
    apply andb_true_iff in Hfree as [Hnofresh Hrestfree].
    destruct a as [x f args|f args res|t u|x op args]; try discriminate.
    cbn [actions_ok] in Hacts.
    destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hresult Hrest]]]]]].
    pose proof (run_relational_kind p f out Hfragment Hkind) as Hout. subst out.
    destruct res as [t|]; [contradiction|].
    destruct (run_term_cells_typed g s locals args ss Henv Hargs)
      as [cells [Hcells Hsorts]].
    assert (Hrowtyped : row_sorted (program_sorts p) (program_kind p) f cells None).
    { exists ORel. rewrite Hsorts. repeat split; assumption. }
    assert (Hids : forall i, In (Id i) (cells ++ option_list None) -> D.allocated db i).
    { intros i Hin. rewrite app_nil_r in Hin.
      eapply run_term_cells_allocated; eassumption. }
    pose proof (run_put_allowed p cp db f cells None Hchecked Hloaded Hrowtyped Hids)
      as Hallowed.
    destruct (run_put_state p cp f cells None db Hchecked Hwf Hloaded Hrowtyped Hids)
      as [Hwf' [Hloaded' [Hids' Hpending]]].
    assert (Hkey : Forall (fun c => exists v, c = Val v /\ active_value p initial v) cells).
    { eapply run_term_cells_active; [exact (proj1 Hdomain)|exact Hallocated|exact Hactive|
        |exact Hcells].
      intros v Hin. eapply Hliterals; [now left|]. cbn [action_terms option_list].
      rewrite app_nil_r. exact Hin. }
    pose proof (run_domain_put p initial db f cells Hwf Hdomain Hallowed Hkey) as Hdomain'.
    assert (Hallocated' : env_allocated (D.put f cells None db) (look s locals)).
    { eapply run_env_allocated_mono with (db := db);
        [rewrite Hids'; reflexivity|exact Hallocated]. }
    cbn [apply_go result_cell]. rewrite Hcells. eapply IH; try eassumption.
    intros a v Hin Hliteral. eapply Hliterals; [right; exact Hin|exact Hliteral].
  Qed.

  (** Applying one checked rule preserves the seed domain when its bindings are active. *)
  Lemma run_apply_domain : forall p cp initial r s db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    prim_free p = true -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s -> env_allocated db s ->
    (forall x v, s x = Some (Val v) -> active_value p initial v) ->
    run_domain p initial db -> run_domain p initial (apply (actions V.t r) s db).
  Proof.
    intros p cp initial r s db Hchecked Hwf Hloaded Hfragment Hfree Hrule Henv Hallocated
      Hactive Hdomain.
    destruct (run_rule_context p cp r s Hchecked Hrule Henv) as [g [_ [Hacts Hsorted]]].
    unfold apply. eapply run_apply_go_domain; try eassumption.
    - eapply run_relational_actions; eassumption.
    - eapply run_prim_free_actions; eassumption.
    - intros x ty Hbound. destruct (Hsorted x ty Hbound) as [c [Hc Hsort]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated; exact Hcell.
    - intros x v Hcell. rewrite run_look_empty in Hcell. eapply Hactive; exact Hcell.
    - intros a v Hin Hliteral. eapply run_program_action_literal; eassumption.
  Qed.

  (** Every saved job contains only values active in its binding snapshot. *)
  Lemma run_jobs_active : forall p cp nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    Forall (fun cb => forall x v,
      trie_get x (bind_trie (fst cb) (snd cb)) = Some (Val v) -> active_value p db v)
      (jobs p cp nv db).
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded. apply Forall_forall.
    intros [c b] Hin x v Hcell. cbn [fst snd] in Hcell.
    rewrite bind_trie_spec in Hcell.
    destruct (run_jobs_member p cp nv db c b Hin) as [Hplan [Hbinding Hkeep]].
    eapply run_plan_bindings_active; eassumption.
  Qed.

  (** Applying saved active jobs preserves the new-row domain invariant. *)
  Lemma run_apply_jobs_domain : forall p cp initial original js db,
    plans_ok p cp -> relational_fragment p = true -> prim_free p = true ->
    Forall (run_job_facts p original) js ->
    Forall (fun cb => forall x v,
      trie_get x (bind_trie (fst cb) (snd cb)) = Some (Val v) -> active_value p initial v) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    run_domain p initial db -> run_domain p initial (apply_jobs p js db).
  Proof.
    intros p cp initial original js. induction js as [|[c b] rest IH]; intros db
      Hchecked Hfragment Hfree Hjobs Hactive Hwf Hloaded Hids Hdomain; [exact Hdomain|].
    inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
    inversion Hactive as [|job remaining Hvalues Htail]; subst job remaining.
    destruct Hjob as [Hrule [Henv [Hallocated Hmatch]]].
    destruct (run_job_environment p original db c b Hids Henv Hallocated)
      as [Htyped Hallocated_now].
    destruct (run_apply_state p cp (job_rule p c) (fun x => trie_get x (bind_trie c b)) db
      Hchecked Hwf Hloaded Hrule Htyped Hallocated_now)
      as [Hnext [Hloadnext [Hidnext Hpending]]].
    pose proof (run_apply_domain p cp initial (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hfragment Hfree
      Hrule Htyped Hallocated_now Hvalues Hdomain) as Hdomain'.
    cbn [apply_jobs]. eapply IH; try eassumption. eapply N.le_trans; eassumption.
  Qed.

  (** A primitive-free relational round creates no values outside the initial active domain. *)
  Lemma run_round_domain : forall p cp initial nv current,
    plans_ok p cp -> D.wf initial -> D.wf current -> loaded p cp current ->
    relational_fragment p = true -> prim_free p = true -> run_domain p initial current ->
    run_domain p initial (round p cp nv current).
  Proof.
    intros p cp initial nv current Hchecked Hinitial Hcurrent Hloaded Hfragment Hfree Hdomain.
    pose proof (run_jobs_facts p cp nv current Hchecked Hcurrent Hloaded) as Hjobs.
    pose proof (run_jobs_active p cp nv current Hchecked Hcurrent Hloaded) as Hvalues.
    assert (Hactive : Forall (fun cb => forall x v,
      trie_get x (bind_trie (fst cb) (snd cb)) = Some (Val v) -> active_value p initial v)
      (jobs p cp nv current)).
    { eapply Forall_impl; [|exact Hvalues]. intros cb Henv x v Hget.
      eapply run_domain_active; [exact Hinitial|exact Hcurrent|exact Hdomain|].
      eapply Henv. exact Hget. }
    destruct (run_advance_state p cp current Hcurrent Hloaded)
      as [Hadvance [Hloadadvance Hids]].
    assert (Hidbound : (D.ids current <= D.ids (D.advance current))%N).
    { rewrite Hids. reflexivity. }
    pose proof (run_domain_advance p initial current Hcurrent Hdomain) as Hdomainadvance.
    pose proof (run_apply_jobs_domain p cp initial current (jobs p cp nv current)
      (D.advance current) Hchecked Hfragment Hfree Hjobs Hactive Hadvance Hloadadvance
      Hidbound Hdomainadvance) as Hdomain'.
    destruct (run_apply_jobs_state p cp current (jobs p cp nv current) (D.advance current)
      Hchecked Hjobs Hadvance Hloadadvance Hidbound) as [Hnext Hrest].
    rewrite round_eq_jobs. now apply run_domain_rebuild.
  Qed.

  (** Inclusion of active values gives inclusion of the corresponding finite universes. *)
  Lemma run_universe_active_incl : forall p before after,
    D.wf before -> D.wf after ->
    (forall v, active_value p after v -> active_value p before v) ->
    incl (universe p after) (universe p before).
  Proof.
    intros p before after Hbefore Hafter Hactive [f k] Hin.
    apply (proj1 (run_universe_member p after f k Hafter)) in Hin.
    destruct Hin as [Hkind [Hdecl Hvalues]].
    apply (proj2 (run_universe_member p before f k Hbefore)).
    split; [exact Hkind|]. split; [exact Hdecl|].
    eapply Forall_impl; [|exact Hvalues]. intros c [v [Hcell Hv]].
    exists v. split; [exact Hcell|now apply Hactive].
  Qed.

  (** No new active values means no larger Herbrand budget. *)
  Lemma run_herbrand_active_bound : forall p before after,
    D.wf before -> D.wf after ->
    (forall v, active_value p after v -> active_value p before v) ->
    herbrand p after <= herbrand p before.
  Proof.
    intros p before after Hbefore Hafter Hactive. rewrite !herbrand_spec.
    apply NoDup_incl_length; [apply run_universe_nodup|].
    eapply run_universe_active_incl; eassumption.
  Qed.

  (** A sorted relational row over the initial active values belongs to its universe. *)
  Lemma run_loaded_active_row_universe : forall p cp initial current f k o,
    D.wf initial -> relational_fragment p = true -> loaded p cp current ->
    row (D.view current) f k o ->
    Forall (fun c => exists v, c = Val v /\ active_value p initial v) k ->
    In (f, k) (universe p initial).
  Proof.
    intros p cp initial current f k o Hinitial Hfragment [Hkinds [Hslots Hsorted]]
      Hrow Hactive.
    destruct (Hsorted f k o Hrow) as [out [Hsort [Hkind Houtput]]].
    rewrite Hkinds in Hkind.
    pose proof (run_relational_kind p f out Hfragment Hkind) as Hout. subst out.
    destruct (run_lookup_sorts_decl (decls V.t p) f (map cell_sort k) Hsort)
      as [d [Hfind Hargs]].
    apply (proj2 (run_universe_member p initial f k Hinitial)).
    split; [exact Hkind|]. split; [|exact Hactive]. exists d. split; [exact Hfind|].
    rewrite Hargs, length_map. reflexivity.
  Qed.

  (** A database invariant preserved by rounds holds throughout the trace. *)
  Lemma run_trace_database_invariant : forall p cp lim (P : D.t -> Prop),
    (forall nv db, P db -> P (round p cp nv db)) ->
    forall initial, P initial -> Forall (fun state => P (snd state)) (trace p cp lim initial).
  Proof.
    intros p cp lim P Hround initial Hinitial.
    apply run_trace_invariant; [exact Hinitial|].
    intros [nv current] next Hcurrent Hstep.
    pose proof (run_driver_database_invariant p cp lim P Hround nv current Hcurrent)
      as Hnext. rewrite Hstep in Hnext. exact Hnext.
  Qed.

  (** Every traced database remains loaded and draws new row values from the initial domain. *)
  Lemma run_trace_domain : forall p cp lim initial,
    plans_ok p cp -> D.wf initial -> loaded p cp initial ->
    relational_fragment p = true -> prim_free p = true -> no_ids initial ->
    Forall (fun state => D.wf (snd state) /\ loaded p cp (snd state) /\
      run_domain p initial (snd state)) (trace p cp lim initial).
  Proof.
    intros p cp lim initial Hchecked Hinitial Hloaded Hfragment Hfree Hnoids.
    refine (run_trace_database_invariant p cp lim
      (fun current => D.wf current /\ loaded p cp current /\
        run_domain p initial current) _ initial _).
    - intros nv current [Hcurrent [Hloadcurrent Hdomain]].
      destruct (run_round_state p cp nv current Hchecked Hcurrent Hloadcurrent)
        as [Hnext [Hloadnext Hidnext]].
      split; [exact Hnext|]. split; [exact Hloadnext|].
      exact (run_round_domain p cp initial nv current Hchecked Hinitial Hcurrent
        Hloadcurrent Hfragment Hfree Hdomain).
    - split; [exact Hinitial|]. split; [exact Hloaded|]. now apply run_domain_initial.
  Qed.

  Lemma herbrand_round_le : forall p cp db nv, plans_ok p cp -> D.wf db -> loaded p cp db ->
    relational_fragment p = true -> prim_free p = true -> no_ids db ->
    herbrand p (round p cp nv db) <= herbrand p db.
  Proof.
    intros p cp db nv Hchecked Hwf Hloaded Hfragment Hfree Hnoids.
    pose proof (run_round_domain p cp db nv db Hchecked Hwf Hwf Hloaded Hfragment Hfree
      (run_domain_initial p db Hnoids)) as Hdomain.
    destruct (run_round_state p cp nv db Hchecked Hwf Hloaded) as [Hnext Hrest].
    eapply run_herbrand_active_bound; [exact Hwf|exact Hnext|].
    eapply run_domain_active; eassumption.
  Qed.

  Lemma new_rows_in_universe : forall p cp lim db nv current f k o,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    prim_free p = true -> no_ids db ->
    In (nv, current) (trace p cp lim db) -> row (D.view current) f k o ->
    ~ row (D.view db) f k o ->
    In (f, k) (universe p db).
  Proof.
    intros p cp lim db nv current f k o Hchecked Hwf Hloaded Hfragment Hfree Hnoids
      Hin Hrow Hnew.
    pose proof (run_trace_domain p cp lim db Hchecked Hwf Hloaded Hfragment Hfree Hnoids)
      as Htrace.
    apply Forall_forall with (x := (nv, current)) in Htrace; [|exact Hin].
    change (D.wf current /\ loaded p cp current /\ run_domain p db current) in Htrace.
    destruct Htrace as [Hcurrent [Hloadcurrent Hdomain]].
    destruct (proj2 (proj2 Hdomain) f k o Hrow) as [Hold|Hactive]; [contradiction|].
    eapply run_loaded_active_row_universe; eassumption.
  Qed.

  (** * Finite relational saturation *)

  (** Identifier-free relational rounds preserve each existing row exactly. *)
  Lemma run_round_relational_rows : forall p cp nv current,
    plans_ok p cp -> D.wf current -> loaded p cp current ->
    relational_fragment p = true -> no_ids current ->
    forall f k, row (D.view current) f k None ->
      row (D.view (round p cp nv current)) f k None.
  Proof.
    intros p cp nv current Hchecked Hcurrent Hloaded Hfragment Hnoids f k Hrow.
    destruct ((proj2 (run_round_grows p cp nv current Hchecked Hcurrent Hloaded))
      f k None Hrow) as [output [Hnext Houtput]].
    destruct ((proj2 Hnoids) f k None Hrow) as [_ Hvalues].
    rewrite (run_value_key_canon (round p cp nv current) k Hvalues) in Hnext.
    pose proof (run_round_no_ids p cp nv current Hchecked Hcurrent Hloaded
      Hfragment Hnoids) as Hnext_noids.
    destruct ((proj2 Hnext_noids) f k output Hnext) as [-> _]. exact Hnext.
  Qed.

  (** The termination witnesses are distinct universe rows already stored in the current state. *)
  Definition run_termination_state (p : program V.t) (cp : compiled V.t)
      (initial current : D.t) (seen : list (positive * list (cell V.t))) : Prop :=
    D.wf current /\ loaded p cp current /\ run_domain p initial current /\
    (forall f k, row (D.view initial) f k None -> row (D.view current) f k None) /\
    NoDup seen /\ incl seen (universe p initial) /\
    Forall (fun fk => row (D.view current) (fst fk) (snd fk) None) seen.

  (** Distinct witnessed rows cannot outnumber the initial universe. *)
  Lemma run_termination_count : forall p cp initial current seen,
    run_termination_state p cp initial current seen -> length seen <= herbrand p initial.
  Proof.
    intros p cp initial current seen [_ [_ [_ [_ [Hnodup [Hinside Hrows]]]]]].
    rewrite herbrand_spec. apply NoDup_incl_length; assumption.
  Qed.

  (** The initial database starts with no witnessed fresh rows. *)
  Lemma run_termination_initial : forall p cp initial,
    D.wf initial -> loaded p cp initial -> no_ids initial ->
    run_termination_state p cp initial initial [].
  Proof.
    intros p cp initial Hwf Hloaded Hnoids.
    split; [exact Hwf|]. split; [exact Hloaded|].
    split; [now apply run_domain_initial|]. split; [auto|].
    split; [constructor|]. split; [intros fk Hnone; contradiction|constructor].
  Qed.

  (** A round preserves every stored termination witness. *)
  Lemma run_termination_round : forall p cp initial nv current seen,
    plans_ok p cp -> D.wf initial -> relational_fragment p = true -> prim_free p = true ->
    run_termination_state p cp initial current seen ->
    run_termination_state p cp initial (round p cp nv current) seen.
  Proof.
    intros p cp initial nv current seen Hchecked Hinitial Hfragment Hfree
      [Hcurrent [Hloaded [Hdomain [Hinitial_rows [Hnodup [Hinside Hseen]]]]]].
    destruct (run_round_state p cp nv current Hchecked Hcurrent Hloaded)
      as [Hnext [Hloadnext Hids]].
    pose proof (run_round_domain p cp initial nv current Hchecked Hinitial Hcurrent
      Hloaded Hfragment Hfree Hdomain) as Hround_domain.
    assert (Hkeeps : forall f k, row (D.view current) f k None ->
      row (D.view (round p cp nv current)) f k None).
    { intros f k Hrow. eapply run_round_relational_rows;
        [exact Hchecked|exact Hcurrent|exact Hloaded|exact Hfragment|
         exact (proj1 Hdomain)|exact Hrow]. }
    split; [exact Hnext|]. split; [exact Hloadnext|].
    split; [exact Hround_domain|]. split.
    - intros f k Hrow. apply Hkeeps. now apply Hinitial_rows.
    - split; [exact Hnodup|]. split; [exact Hinside|].
      eapply Forall_impl; [|exact Hseen]. intros [f k] Hrow. now apply Hkeeps.
  Qed.

  (** Every productive relational round supplies a new universe witness. *)
  Lemma run_termination_fresh : forall p cp initial nv current seen,
    plans_ok p cp -> D.wf initial -> relational_fragment p = true -> prim_free p = true ->
    run_termination_state p cp initial current seen ->
    D.changed (round p cp nv current) = true ->
    exists fk, ~ In fk seen /\ In fk (universe p initial) /\
      row (D.view (round p cp nv current)) (fst fk) (snd fk) None.
  Proof.
    intros p cp initial nv current seen Hchecked Hinitial Hfragment Hfree
      [Hcurrent [Hloaded [Hdomain [Hinitial_rows [Hnodup [Hinside Hseen]]]]]] Hchanged.
    destruct (round_changed_adds_row p cp nv current Hchecked Hcurrent Hloaded Hfragment
      (proj1 Hdomain) Hchanged) as [f [k [Hrow Hfresh]]].
    destruct (run_round_state p cp nv current Hchecked Hcurrent Hloaded)
      as [Hround [Hloadround Hids]].
    pose proof (run_round_domain p cp initial nv current Hchecked Hinitial Hcurrent
      Hloaded Hfragment Hfree Hdomain) as Hround_domain.
    exists (f, k). split.
    - intro Hin. apply Hfresh.
      apply Forall_forall with (x := (f, k)) in Hseen; [exact Hseen|exact Hin].
    - split.
      + destruct ((proj2 (proj2 Hround_domain)) f k None Hrow) as [Hold|Hactive].
        * exfalso. apply Hfresh. now apply Hinitial_rows.
        * eapply run_loaded_active_row_universe; eassumption.
      + exact Hrow.
  Qed.

  (** Adding a previously absent stored universe row preserves the termination invariant. *)
  Lemma run_termination_extend : forall p cp initial current seen fk,
    run_termination_state p cp initial current seen -> ~ In fk seen ->
    In fk (universe p initial) -> row (D.view current) (fst fk) (snd fk) None ->
    run_termination_state p cp initial current (fk :: seen).
  Proof.
    intros p cp initial current seen fk
      [Hcurrent [Hloaded [Hdomain [Hinitial_rows [Hnodup [Hinside Hseen]]]]]]
      Hfresh Hmember Hrow.
    split; [exact Hcurrent|]. split; [exact Hloaded|]. split; [exact Hdomain|].
    split; [exact Hinitial_rows|]. split; [now constructor|]. split.
    - intros entry [->|Hin]; [exact Hmember|now apply Hinside].
    - now constructor.
  Qed.

  (** Each continuing driver step spends a credit or records one new finite-universe row. *)
  Lemma run_termination_step : forall p cp initial lim (nv : bool) current seen fuel,
    plans_ok p cp -> D.wf initial -> relational_fragment p = true -> prim_free p = true ->
    run_termination_state p cp initial current seen ->
    2 * length seen + S fuel >= 2 * herbrand p initial + (if nv then 1 else 2) ->
    match driver p cp lim (nv, current) with
    | inl (next_nv, next) => exists seen', run_termination_state p cp initial next seen' /\
        2 * length seen' + fuel >= 2 * herbrand p initial + (if next_nv then 1 else 2)
    | inr (status, _) => status = Saturated
    end.
  Proof.
    intros p cp initial lim nv current seen fuel Hchecked Hinitial Hfragment Hfree
      Hstate Hfuel.
    pose proof Hstate as Hstate_parts.
    destruct Hstate_parts as [Hcurrent [Hloaded [Hdomain Hrest]]].
    pose proof (run_round_no_ids p cp nv current Hchecked Hcurrent Hloaded Hfragment
      (proj1 Hdomain)) as Hnoids.
    assert (Hlimit : (max_ids lim <? D.ids (round p cp nv current))%N = false).
    { apply N.ltb_ge. rewrite (proj1 Hnoids). lia. }
    pose proof (run_termination_round p cp initial nv current seen Hchecked Hinitial
      Hfragment Hfree Hstate) as Hnext.
    rewrite driver_def. cbn zeta. rewrite Hlimit.
    destruct (D.changed (round p cp nv current)) eqn:Hchanged; cbn [negb andb].
    - rewrite andb_false_r. cbn beta iota.
      destruct (run_termination_fresh p cp initial nv current seen Hchecked Hinitial
        Hfragment Hfree Hstate Hchanged) as [fk [Hfresh [Hmember Hrow]]].
      exists (fk :: seen). split.
      + eapply run_termination_extend; eassumption.
      + cbn [length]. destruct nv; lia.
    - destruct nv; [reflexivity|]. exists seen. split; [exact Hnext|]. lia.
  Qed.

  (** Enough finite-universe credit makes the binary driver return saturation. *)
  Lemma run_termination_loop : forall p cp initial lim fuel (nv : bool) current seen,
    plans_ok p cp -> D.wf initial -> relational_fragment p = true -> prim_free p = true ->
    run_termination_state p cp initial current seen ->
    2 * length seen + N.to_nat fuel >= 2 * herbrand p initial + (if nv then 1 else 2) ->
    exists final, loopN (driver p cp lim) fuel (nv, current) = inr (Saturated, final).
  Proof.
    intros p cp initial lim fuel nv current seen Hchecked Hinitial Hfragment Hfree.
    assert (Hacc : forall (fs : N * (bool * D.t)) (H : Acc loopN_lt fs) witnesses,
      run_termination_state p cp initial (snd (snd fs)) witnesses ->
      2 * length witnesses + N.to_nat (fst fs) >= 2 * herbrand p initial +
        (if fst (snd fs) then 1 else 2) ->
      exists final, loop loopN_lt (loopN_step (driver p cp lim)) fs H =
        inr (Saturated, final)).
    { intros fs H. induction H as [[n [mode db]] Hsmaller IH] using Acc_ind_dep.
      cbn [fst snd]. intros witnesses Hstate Hfuel. destruct n as [|n].
      - pose proof (run_termination_count p cp initial db witnesses Hstate) as Hcount.
        cbn [N.to_nat] in Hfuel. destruct mode; lia.
      - assert (Hpos : 0 < N.to_nat (N.pos n)) by apply Pos2Nat.is_pos.
        assert (Hpred : N.to_nat (N.pos n) = S (N.to_nat (N.pred (N.pos n)))).
        { rewrite N2Nat.inj_pred. lia. }
        rewrite Hpred in Hfuel.
        pose proof (run_termination_step p cp initial lim mode db witnesses
          (N.to_nat (N.pred (N.pos n))) Hchecked Hinitial Hfragment Hfree Hstate Hfuel)
          as Hstep.
        cbn [loop loopN_step Acc_inv].
        destruct (driver p cp lim (mode, db)) as [[next_mode next]|[status final]] eqn:Hdriver.
        + destruct Hstep as [seen' [Hnext Hcredit]]. eapply IH; eassumption.
        + subst status. exists final. reflexivity. }
    intros Hstate Hfuel. unfold loopN. eapply Hacc; eassumption.
  Qed.

  (** The two confirmation modes fit the public round budget with one round of slack. *)
  Lemma run_terminates : forall p cp lim db, plans_ok p cp -> D.wf db ->
    loaded p cp db -> relational_fragment p = true -> prim_free p = true -> no_ids db ->
    N.to_nat (max_iter lim) >= 2 * herbrand p db + 3 ->
    fst (run p cp lim db) = Saturated.
  Proof.
    intros p cp lim db Hchecked Hwf Hloaded Hfragment Hfree Hnoids Hfuel.
    assert (Hcredit : 2 * length ([] : list (positive * list (cell V.t))) +
      N.to_nat (max_iter lim) >= 2 * herbrand p db + (if false then 1 else 2)).
    { cbn [length]. lia. }
    destruct (run_termination_loop p cp db lim (max_iter lim) false db []
      Hchecked Hwf Hfragment Hfree (run_termination_initial p cp db Hwf Hloaded Hnoids)
      Hcredit) as [final Hloop].
    pose proof (run_unfolds_loop p cp lim db Hchecked Hwf Hloaded) as Hrun.
    rewrite Hloop in Hrun. rewrite Hrun. reflexivity.
  Qed.

  (** An identifier-limit stop is produced only by a round above the requested bound. *)
  Lemma run_loop_id_limit : forall p cp lim fuel nv db result,
    loopN (driver p cp lim) fuel (nv, db) = inr (IdLimit, result) ->
    (max_ids lim < D.ids result)%N.
  Proof.
    intros p cp lim fuel nv db result Hresult.
    assert (Hlimit : match loopN (driver p cp lim) fuel (nv, db) with
      | inl _ => True
      | inr stopped => fst stopped = IdLimit -> (max_ids lim < D.ids (snd stopped))%N
      end).
    { eapply run_loopN_invariant with (P := fun _ => True).
      - intros state next _ _. exact I.
      - intros [naive current] [status next] _ Hdriver Hstatus.
        cbn [fst snd] in Hstatus |- *. subst status. unfold driver in Hdriver.
        destruct (N.ltb (limits_ids lim) (D.ids (round p cp naive current))) eqn:Hids.
        + injection Hdriver as <-. apply N.ltb_lt in Hids. exact Hids.
        + destruct (naive && negb (D.changed (round p cp naive current))); discriminate.
      - exact I. }
    rewrite Hresult in Hlimit. apply Hlimit. reflexivity.
  Qed.

  Lemma run_limits : forall p cp lim db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    fst (run p cp lim db) = IdLimit -> (D.ids (snd (run p cp lim db)) > max_ids lim)%N.
  Proof.
    intros p cp lim db Hchecked Hwf Hloaded Hstatus.
    pose proof (run_loop_state p cp lim (max_iter lim) false db Hchecked Hwf Hloaded)
      as Hstate.
    pose proof (run_unfolds_loop p cp lim db Hchecked Hwf Hloaded) as Hresult.
    destruct (loopN (driver p cp lim) (max_iter lim) (false, db))
      as [[naive current]|[status current]] eqn:Hloop.
    - rewrite Hresult in Hstatus. discriminate.
    - rewrite Hresult in Hstatus |- *. cbn [fst snd] in Hstatus |- *. subst status.
      destruct Hstate as [Hcurrent _].
      rewrite (proj2 (proj2 (D.layout_rebuild current Hcurrent))).
      pose proof (run_loop_id_limit p cp lim (max_iter lim) false db current Hloop) as Hlimit.
      apply N.lt_gt. exact Hlimit.
  Qed.

End Run.

Module RunT (V : VALUE_T) (I : INDEX_T V) (J : JOIN_T V I) (D : DATABASE_T V I)
    <: RUN_ALL V I J D.
  Include Run V I J D.
  TimeFun plan.
  TimeFun check_shape.
  TimeFun check_plan.
  TimeFun load.
  TimeFun apply_go.
  TimeFun apply.
  TimeFun bind_trie.
  TimeFun keep.
  TimeFun source_ix.
  TimeFun plan_bindings.
  TimeFun jobs.
  TimeFun apply_all.
  TimeFun round.
  TimeFun driver.
  TimeFun run.
  (** Post work counts the position and the terms of each listed atom. *)
  Definition post_work (p : program V.t) (c : cplan V.t) : nat :=
    fold_right (fun i n => i + 1 +
      match nth_error (query V.t (job_rule p c)) i with
      | Some a => length (atom_terms a)
      | None => 0
      end + n) 0 (post V.t c).
  (** Finding the rule of a plan walks the rule list with a binary counter. *)
  Definition rule_work (p : program V.t) (c : cplan V.t) : nat :=
    (length (rules V.t p) + 1) * (N.size_nat (rule_ix V.t c) + 1).
  (** Reading the index of a source pays for the bits of its slot number. *)
  Definition source_bits (c : cplan V.t) : nat :=
    fold_right (fun src n =>
      match src with
      | All _ slot | New _ slot => N.size_nat slot + 1 + n
      | Const _ _ => 1 + n
      end) 0 (sources V.t c).
  Definition round_work (p : program V.t) (cp : compiled V.t) (nv : bool) (db : D.t) : nat :=
    length (Syntax.slots V.t cp) +
      fold_right Nat.add 0 (map (fun c =>
        (J.work (join V.t c) (map (source_index db) (sources V.t c)) +
          length (sources V.t c) + source_bits c + 2) *
          (nvars (join V.t c) + 1) * (nvars (join V.t c) + 1) +
        length (bindings cp c db) *
          (fold_right (fun x n => (Pos.size_nat x + 1 + n)%nat) 0%nat (var_of V.t c) +
           post_work p c + rule_work p c + 1 +
           fold_right (fun a n => match a with
             | Make _ f args | Put f args _ => (length args + 2) * (length args + 2) *
                 (length (filter (fun sl => Pos.eqb (fst sl) f) (Syntax.slots V.t cp)) + 1) + n
             | Union _ _ => 1 + n
             | Let _ _ args => length args + 1 + n
             end) 0 (actions V.t (nth (N.to_nat (rule_ix V.t c)) (rules V.t p)
               (Rule V.t [] [])))) +
        fold_right Nat.add 0 (map (fun binding =>
          let r := nth (N.to_nat (rule_ix V.t c)) (rules V.t p) (Rule V.t [] []) in
          N.to_nat (query_prim_work V.prim_work (query V.t r) (env_of c binding) +
            action_prim_work V.prim V.prim_work (program_kind p) (actions V.t r)
              (env_of c binding))%N)
          (bindings cp c db)))
        (if nv then naive V.t cp else seminaive V.t cp)).
  Definition size_program (p : program V.t) : nat := program_bits p.
  Definition size_compiled (cp : compiled V.t) : nat :=
    fold_right (fun sl n => Pos.size_nat (fst sl) +
        fold_right (fun i m => i + 1 + m) 0 (snd sl) + 1 + n) 0 (Syntax.slots V.t cp) +
      fold_right (fun c n => N.size_nat (rule_ix V.t c) + nvars (join V.t c) +
        fold_right (fun col m => fold_right (fun i k => i + 1 + k) 0 col + 1 + m)
          0 (cols (join V.t c)) +
        fold_right (fun src m => match src with
          | All _ i | New _ i => N.size_nat i + 1 + m
          | Const _ value => cell_bits V.encode value + 1 + m
          end) 0 (sources V.t c) +
        fold_right (fun x m => Pos.size_nat x + 1 + m) 0 (var_of V.t c) +
        fold_right (fun i m => i + 1 + m) 0 (post V.t c) + 1 + n)
        0 (naive V.t cp ++ seminaive V.t cp).
  Definition wbits (p : program V.t) : nat :=
    fold_right (fun x n => Nat.max (Pos.size_nat x) n)
      0 (program_words V.encode p).
  Definition c_run : N :=
    (1024 * 4096 * (D.c_db + I.c_ix + J.c_join + V.c_val + V.c_key +
      PTrieT.c_trie + 1))%N.
  Lemma size_compiled_spec : forall cp,
    size_compiled cp =
      fold_right (fun sl n => Pos.size_nat (fst sl) +
        fold_right (fun i m => i + 1 + m) 0 (snd sl) + 1 + n) 0 (Syntax.slots V.t cp) +
      fold_right (fun c n => N.size_nat (rule_ix V.t c) + nvars (join V.t c) +
        fold_right (fun col m => fold_right (fun i k => i + 1 + k) 0 col + 1 + m)
          0 (cols (join V.t c)) +
        fold_right (fun src m => match src with
          | All _ i | New _ i => N.size_nat i + 1 + m
          | Const _ value => cell_bits V.encode value + 1 + m
          end) 0 (sources V.t c) +
        fold_right (fun x m => Pos.size_nat x + 1 + m) 0 (var_of V.t c) +
        fold_right (fun i m => i + 1 + m) 0 (post V.t c) + 1 + n)
        0 (naive V.t cp ++ seminaive V.t cp).
  Proof.
    reflexivity.
  Qed.

  Lemma wbits_spec : forall p,
    wbits p = fold_right (fun x n => Nat.max (Pos.size_nat x) n)
      0 (program_words V.encode p).
  Proof.
    reflexivity.
  Qed.

  (** Stored slots charge the bits of their name and the number of their positions. *)
  Definition run_slots_size (sl : list (positive * list nat)) : nat :=
    fold_right (fun s n => Pos.size_nat (fst s) + length (snd s) + 1 + n) 0 sl.

  Definition run_slot_state_size (st : slot_state) : nat :=
    match st with
    | SlotState _ _ rows => run_slots_size rows
    end.

  (** Accumulating a reversed list preserves the sum of its slot charges. *)
  Lemma run_slots_size_rev_append : forall xs ys,
    run_slots_size (rev_append xs ys) = run_slots_size xs + run_slots_size ys.
  Proof.
    induction xs as [| [f perm] xs IH]; intro ys.
    - reflexivity.
    - cbn [rev_append]. rewrite IH.
      change (run_slots_size xs +
        (Pos.size_nat f + length perm + 1 + run_slots_size ys) =
        Pos.size_nat f + length perm + 1 + run_slots_size xs + run_slots_size ys).
      lia.
  Qed.

  (** Registering a slot either reuses it or adds exactly its own charge. *)
  Lemma run_add_slot_size : forall f perm st,
    run_slot_state_size (snd (add_slot f perm st)) <=
      run_slot_state_size st + Pos.size_nat f + length perm + 1.
  Proof.
    intros f perm [table next rows]. unfold add_slot.
    destruct (trie_get (slot_code f perm) table).
    - change (run_slots_size rows <=
        run_slots_size rows + Pos.size_nat f + length perm + 1). lia.
    - change (Pos.size_nat f + length perm + 1 + run_slots_size rows <=
        run_slots_size rows + Pos.size_nat f + length perm + 1). lia.
  Qed.

  (** Counting consecutive positions allocates exactly the requested number of positions. *)
  Lemma run_count_from_length : forall len start,
    length (count_from start len) = len.
  Proof.
    induction len as [| len IH]; intro start; cbn [count_from length].
    - reflexivity.
    - rewrite IH. reflexivity.
  Qed.

  (** Insertion adds one position to a sorted list of pairs. *)
  Lemma run_insert_pair_length : forall pairs j pos,
    length (insert_pair j pos pairs) = S (length pairs).
  Proof.
    induction pairs as [| [k q] pairs IH]; intros j pos; cbn [insert_pair length].
    - reflexivity.
    - destruct (Nat.leb j k); cbn [length]; [reflexivity|].
      rewrite IH. reflexivity.
  Qed.

  (** Sorting positions preserves their number. *)
  Lemma run_sort_pairs_length : forall pairs,
    length (sort_pairs pairs) = length pairs.
  Proof.
    induction pairs as [| [j pos] pairs IH]; cbn [sort_pairs length].
    - reflexivity.
    - rewrite run_insert_pair_length, IH. reflexivity.
  Qed.

  (** Every term contributes one position pair to the layout. *)
  Lemma run_place_terms_length : forall base ts pos seen lay pairs lits copied,
    length (snd (fst (fst (@place_terms V.t base ts pos seen lay pairs lits copied)))) =
      length ts + length pairs.
  Proof.
    intros base ts. induction ts as [| [x | v] ts IH];
      intros pos seen [names nc nm fresh cn mn] pairs lits copied.
    - reflexivity.
    - cbn [place_terms]. destruct (trie_get x seen).
      + rewrite IH. cbn [length]. lia.
      + destruct (trie_get x names); rewrite IH; cbn [length]; lia.
    - cbn [place_terms]. rewrite IH. cbn [length]. lia.
  Qed.

  (** The number of term positions is bounded by their syntax charge. *)
  Lemma run_terms_length_bits : forall ts : list (term V.t),
    length ts <= terms_bits ts.
  Proof.
    induction ts as [| t ts IH].
    - change (0 <= 0). lia.
    - change (S (length ts) <= term_bits t + terms_bits ts).
      destruct t as [x | v]; unfold term_bits; lia.
  Qed.

  (** An optional result contributes at most its syntax charge. *)
  Lemma run_result_length_bits : forall res : option (term V.t),
    length (option_list res) <= result_bits res.
  Proof.
    intros [[x | v] |]; cbn [option_list length result_bits term_bits]; lia.
  Qed.

  (** Planning a query adds at most its syntax charge to the stored slots. *)
  Lemma run_plan_atoms_size : forall base q ai lay st outs post,
    run_slot_state_size
      (snd (fst (fst (@plan_atoms V.t base q ai lay st outs post)))) <=
      run_slot_state_size st + fold_right (fun a n => atom_bits a + n) 0 q.
  Proof.
    intros base q. induction q as [| [f args res | op args res] q IH];
      intros ai lay st outs post.
    - cbn [plan_atoms fst snd fold_right]. lia.
    - cbn [plan_atoms].
      destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
        as [[[lay' pairs] lits] copied] eqn:Hterms.
      destruct (add_slot f (map snd (sort_pairs pairs)) st) as [s st'] eqn:Hslot.
      pose proof (run_place_terms_length base (args ++ option_list res) 0 Empty
        lay [] [] false) as Hlength.
      rewrite Hterms in Hlength. cbn [fst snd length] in Hlength.
      pose proof (run_add_slot_size f (map snd (sort_pairs pairs)) st) as Hsize.
      rewrite Hslot in Hsize. cbn [snd] in Hsize.
      rewrite length_map, run_sort_pairs_length, Hlength, length_app in Hsize.
      pose proof (IH (S ai) lay' st' (AtomPlan s (map fst (sort_pairs pairs))
        (rev_append lits []) :: outs) (if copied then ai :: post else post)) as Htail.
      pose proof (run_terms_length_bits args) as Hargs.
      pose proof (run_result_length_bits res) as Hres.
      cbn [fold_right atom_bits]. lia.
    - cbn [plan_atoms fold_right atom_bits].
      pose proof (IH (S ai) lay st outs (ai :: post)). lia.
  Qed.

  (** Planning one rule adds at most the charge of that rule. *)
  Lemma run_plan_rule_size : forall i r st,
    run_slot_state_size (fst (fst (@plan_rule V.t i r st))) <=
      run_slot_state_size st + rule_bits r.
  Proof.
    intros i [q acts] st. unfold plan_rule.
    pose proof (run_plan_atoms_size (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []) as Hsize.
    destruct (plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay st'] outs] post] eqn:Hplan.
    cbn [fst snd] in Hsize.
    destruct lay as [names nc nm fresh cn mn].
    change (run_slot_state_size st' <= run_slot_state_size st +
      (fold_right (fun a n => atom_bits a + n) 0 q +
       fold_right (fun a n => action_bits a + n) 0 acts + 1)).
    lia.
  Qed.

  (** The rule traversal sums the charge of its rules. *)
  Lemma run_plan_rules_size : forall rs i st naive semi,
    run_slot_state_size (fst (fst (@plan_rules V.t rs i st naive semi))) <=
      run_slot_state_size st + fold_right (fun r n => rule_bits r + n) 0 rs.
  Proof.
    induction rs as [| r rs IH]; intros i st naive semi.
    - cbn [plan_rules fst run_slot_state_size fold_right]. lia.
    - cbn [plan_rules].
      pose proof (run_plan_rule_size i r st) as Hsize.
      destruct (plan_rule i r st) as [[st' c] cs] eqn:Hrule.
      cbn [fst] in Hsize.
      pose proof (IH (N.succ i) st' (c :: naive) (rev_append cs semi)) as Htail.
      cbn [fold_right]. lia.
  Qed.

  (** Declared full slots cost at most twice the charge of their declarations. *)
  Lemma run_full_slots_size : forall ds seen st,
    run_slot_state_size (full_slots ds seen st) <=
      run_slot_state_size st + 2 * fold_right (fun d n => decl_bits d + n) 0 ds.
  Proof.
    induction ds as [| [f ss out] ds IH]; intros seen st.
    - cbn [full_slots fold_right]. lia.
    - cbn [full_slots]. destruct (trie_get f seen).
      + pose proof (IH seen st). cbn [fold_right decl_bits name arg_sorts]. lia.
      + destruct out.
        * pose proof (IH (PTrieCode.set f tt seen) st).
          cbn [fold_right decl_bits name arg_sorts]. lia.
        * pose proof (IH (PTrieCode.set f tt seen)
            (snd (add_slot f (count_from 0 (S (length ss))) st))) as Htail.
          pose proof (run_add_slot_size f (count_from 0 (S (length ss))) st) as Hsize.
          rewrite run_count_from_length in Hsize.
          cbn [fold_right decl_bits name arg_sorts].
          change (decl_bits (Decl f ss OId)) with (Pos.size_nat f + length ss + 1).
          lia.
        * pose proof (IH (PTrieCode.set f tt seen) st).
          cbn [fold_right decl_bits name arg_sorts]. lia.
  Qed.

  (** The planner's stored slot charge is linear in the program syntax. *)
  Lemma run_plan_slots_size : forall p,
    run_slots_size (Syntax.slots V.t (plan p)) <= 2 * (size_program p + 1).
  Proof.
    intros [ds rs]. unfold plan, plan_program.
    pose proof (run_full_slots_size ds Empty (SlotState Empty 0 [])) as Hfull.
    pose proof (run_plan_rules_size rs 0
      (full_slots ds Empty (SlotState Empty 0 [])) [] []) as Hrules.
    destruct (plan_rules rs 0 (full_slots ds Empty (SlotState Empty 0 [])) [] [])
      as [[[table next rows] nv] sn] eqn:Hplan.
    change (run_slots_size rows <=
      run_slot_state_size (full_slots ds Empty (SlotState Empty 0 [])) +
      fold_right (fun r n => rule_bits r + n) 0 rs) in Hrules.
    change (run_slot_state_size (full_slots ds Empty (SlotState Empty 0 [])) <=
      2 * fold_right (fun d n => decl_bits d + n) 0 ds) in Hfull.
    cbn [Syntax.slots]. rewrite run_slots_size_rev_append.
    change (run_slots_size rows + 0 <=
      2 * (fold_right (fun d n => decl_bits d + n) 0 ds +
        fold_right (fun r n => rule_bits r + n) 0 rs + 1 + 1)).
    lia.
  Qed.

  (** A position list charges the unary size of each stored position. *)
  Definition run_positions_size (positions : list nat) : nat :=
    fold_right (fun i n => i + 1 + n) 0 positions.

  (** A unary position code has one bit beyond its position. *)
  Lemma run_nat_code_bits : forall n, Pos.size_nat (nat_code n) = n + 1.
  Proof.
    induction n as [| n IH]; cbn [nat_code Pos.size_nat]; lia.
  Qed.

  (** Constructing a position code visits each unary constructor once. *)
  Lemma run_nat_code_time : forall n,
    (T_nat_code n <= N.of_nat (n + 1))%N.
  Proof.
    induction n as [| n IH]; time_unfold T_nat_code; lia.
  Qed.

  (** The self-delimiting position list has at most twice its unary input charge. *)
  Lemma run_nat_codes_bits : forall positions,
    Pos.size_nat (list_code nat_code positions) <= 2 * run_positions_size positions + 1.
  Proof.
    induction positions as [| i positions IH].
    - cbn [list_code Pos.size_nat run_positions_size fold_right]. lia.
    - cbn [list_code]. rewrite glue_bits, run_nat_code_bits.
      change (run_positions_size (i :: positions)) with (i + 1 + run_positions_size positions).
      lia.
  Qed.

  (** Encoding a list of positions is linear in their unary input charge. *)
  Lemma run_nat_codes_time : forall positions,
    (T_list_code nat_code T_nat_code positions <=
      4 * N.of_nat (run_positions_size positions) + 1)%N.
  Proof.
    induction positions as [| i positions IH].
    - time_unfold @T_list_code. cbn [run_positions_size fold_right]. lia.
    - pose proof (run_nat_code_time i) as Hcode.
      pose proof (T_glue_le (nat_code i) (list_code nat_code positions)) as Hglue.
      unfold c_glue in Hglue. rewrite run_nat_code_bits in Hglue.
      time_unfold @T_list_code.
      change (run_positions_size (i :: positions)) with (i + 1 + run_positions_size positions).
      lia.
  Qed.

  (** A slot code charges the name's bits and its unary position list. *)
  Lemma run_slot_code_bits : forall f positions,
    Pos.size_nat (slot_code f positions) <=
      2 * (Pos.size_nat f + run_positions_size positions + 1).
  Proof.
    intros f positions. unfold slot_code. rewrite glue_bits.
    pose proof (run_nat_codes_bits positions). lia.
  Qed.

  (** Constructing a slot code is linear in the same charge. *)
  Lemma run_slot_code_time : forall f positions,
    (T_slot_code f positions <=
      8 * N.of_nat (Pos.size_nat f + run_positions_size positions + 1))%N.
  Proof.
    intros f positions.
    pose proof (run_nat_codes_time positions) as Hpositions.
    pose proof (T_glue_le f (list_code nat_code positions)) as Hglue.
    unfold c_glue in Hglue. time_unfold T_slot_code.
    change (T_list_code nat_code (fun n => T_nat_code n) positions) with
      (T_list_code nat_code T_nat_code positions).
    lia.
  Qed.

  (** Replacing one trie entry has a fixed cost per bit of its key. *)
  Lemma run_planner_set_clock : forall A x (v : A) t,
    (PTrieCode.T_set x v t <= 9 * N.of_nat (Pos.size_nat x + 1))%N.
  Proof.
    intros A x v t. pose proof (PTrieT.replace_clock_bound A x (Some v) t).
    time_step.
  Qed.

  (** Term charges add across concatenation. *)
  Lemma run_terms_bits_app : forall xs ys : list (term V.t),
    terms_bits (xs ++ ys) = terms_bits xs + terms_bits ys.
  Proof.
    induction xs as [|x xs IH]; intro ys.
    - reflexivity.
    - change (term_bits x + terms_bits (xs ++ ys) =
        term_bits x + terms_bits xs + terms_bits ys).
      rewrite IH. lia.
  Qed.

  (** The option-list representation retains exactly the result's syntax charge. *)
  Lemma run_terms_bits_result : forall res : option (term V.t),
    terms_bits (option_list res) = result_bits res.
  Proof.
    intros [r|]; cbn [option_list terms_bits fold_right result_bits]; lia.
  Qed.

  (** Every atom has a positive syntax charge. *)
  Lemma run_atom_bits_pos : forall a : atom V.t, 1 <= atom_bits a.
  Proof.
    intros [f args res|p args res]; cbn [atom_bits]; lia.
  Qed.

  (** A query has no more atoms than its syntax charge. *)
  Lemma run_query_length_bits : forall q : list (atom V.t),
    length q <= fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q.
  Proof.
    induction q as [|a q IH]; cbn [length fold_right].
    - lia.
    - pose proof (run_atom_bits_pos a). lia.
  Qed.

  (** Taking a maximum chooses one of its two inputs. *)
  Lemma run_pos_max_bits : forall x y,
    Pos.size_nat (pos_max x y) <= Pos.size_nat x + Pos.size_nat y.
  Proof.
    intros x y. unfold pos_max. destruct (Pos.compare x y); lia.
  Qed.

  (** The maximum scan pays only for the variable that each comparison reads first. *)
  Lemma run_term_max_clock : forall (t : term V.t) m,
    (T_term_max t m <= 4 * N.of_nat (term_bits t))%N.
  Proof.
    intros [x|v] m.
    - pose proof (Pos.T_compare_le x m) as Hcompare.
      time_unfold @T_term_max. time_unfold T_pos_max. time_simpl.
      cbn [term_bits]. nia.
    - time_unfold @T_term_max. cbn [term_bits]. nia.
  Qed.

  (** The width of a term maximum grows by at most the term's charge. *)
  Lemma run_term_max_bits : forall (t : term V.t) m,
    Pos.size_nat (term_max t m) <= Pos.size_nat m + term_bits t.
  Proof.
    intros [x|v] m; cbn [term_max term_bits].
    - pose proof (run_pos_max_bits x m). lia.
    - lia.
  Qed.

  (** Scanning term maxima is linear in their syntax charge. *)
  Lemma run_terms_max_clock : forall (ts : list (term V.t)) m,
    (T_terms_max ts m <= 8 * N.of_nat (terms_bits ts + 1))%N.
  Proof.
    induction ts as [|t ts IH]; intro m.
    - time_unfold @T_terms_max. time_cbn. nia.
    - pose proof (run_term_max_clock t m).
      pose proof (IH (term_max t m)).
      assert (Hpositive : 1 <= term_bits t) by (destruct t; cbn [term_bits]; lia).
      time_unfold @T_terms_max.
      change (terms_bits (t :: ts)) with (term_bits t + terms_bits ts).
      rewrite !Nat2N.inj_add in *. nia.
  Qed.

  (** The maximum scan's output width is bounded by its seed and input charge. *)
  Lemma run_terms_max_bits : forall (ts : list (term V.t)) m,
    Pos.size_nat (terms_max ts m) <= Pos.size_nat m + terms_bits ts.
  Proof.
    induction ts as [|t ts IH]; intro m; cbn [terms_max terms_bits fold_right].
    - lia.
    - pose proof (run_term_max_bits t m).
      pose proof (IH (term_max t m)). unfold terms_bits in *. lia.
  Qed.

  (** Query maxima pay once for every atom and its term list. *)
  Lemma run_query_max_clock : forall (q : list (atom V.t)) m,
    (T_query_max q m <=
      32 * N.of_nat (fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q + 1))%N.
  Proof.
    induction q as [|[f args res|p args res] q IH]; intro m.
    - time_unfold @T_query_max. time_cbn. nia.
    - pose proof (run_terms_max_clock (args ++ option_list res) m).
      pose proof (IH (terms_max (args ++ option_list res) m)).
      pose proof (Datatypes.T_app_le args (option_list res)).
      pose proof (run_terms_length_bits args).
      time_unfold @T_query_max. time_simpl.
      rewrite run_terms_bits_app, run_terms_bits_result in *.
      cbn [fold_right atom_bits]. nia.
    - pose proof (run_terms_max_clock (res :: args) m).
      pose proof (IH (terms_max (res :: args) m)).
      time_unfold @T_query_max. time_simpl.
      cbn [fold_right atom_bits terms_bits] in *. unfold terms_bits in *. nia.
  Qed.

  (** Query scanning cannot add more width than the query's syntax charge. *)
  Lemma run_query_max_bits : forall (q : list (atom V.t)) m,
    Pos.size_nat (query_max q m) <= Pos.size_nat m +
      fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q.
  Proof.
    induction q as [|[f args res|p args res] q IH]; intro m.
    - cbn [query_max fold_right]. lia.
    - cbn [query_max fold_right atom_bits].
      pose proof (IH (terms_max (args ++ option_list res) m)).
      pose proof (run_terms_max_bits (args ++ option_list res) m).
      rewrite run_terms_bits_app, run_terms_bits_result in *. lia.
    - cbn [query_max fold_right atom_bits].
      pose proof (IH (terms_max (res :: args) m)).
      pose proof (run_terms_max_bits (res :: args) m).
      cbn [terms_bits fold_right] in *. unfold terms_bits in *. lia.
  Qed.

  (** Counting duplicate positions adds at most one copy for each term. *)
  Lemma run_term_copies_count : forall (ts : list (term V.t)) seen n,
    term_copies seen ts n <= n + length ts.
  Proof.
    induction ts as [|[x|v] ts IH]; intros seen n; cbn [term_copies length].
    - lia.
    - destruct (trie_get x seen).
      + pose proof (IH seen (S n)). lia.
      + pose proof (IH (PTrieCode.set x tt seen) n). lia.
    - pose proof (IH seen n). lia.
  Qed.

  (** Duplicate counting charges one lookup and at most one insertion per variable. *)
  Lemma run_term_copies_clock : forall (ts : list (term V.t)) seen n,
    (T_term_copies seen ts n <= 16 * N.of_nat (terms_bits ts + 1))%N.
  Proof.
    induction ts as [|[x|v] ts IH]; intros seen n.
    - time_unfold @T_term_copies. time_cbn. nia.
    - pose proof (run_planner_set_clock unit x tt seen).
      pose proof (IH seen (S n)).
      pose proof (IH (PTrieCode.set x tt seen) n).
      time_unfold @T_term_copies. PTrieT.trie_get_le.
      destruct (trie_get x seen); cbn [terms_bits term_bits fold_right] in *;
        unfold terms_bits in *; nia.
    - pose proof (IH seen n).
      time_unfold @T_term_copies. cbn [terms_bits term_bits fold_right] in *.
      unfold terms_bits in *. nia.
  Qed.

  (** The number of copies in a query is bounded by its syntax charge. *)
  Lemma run_query_copies_count : forall (q : list (atom V.t)) n,
    query_copies q n <= n + fold_right (fun a k => (atom_bits a + k)%nat) 0%nat q.
  Proof.
    induction q as [|[f args res|p args res] q IH]; intro n;
      cbn [query_copies fold_right atom_bits].
    - lia.
    - pose proof (IH (term_copies Empty (args ++ option_list res) n)).
      pose proof (run_term_copies_count (args ++ option_list res) Empty n).
      rewrite length_app in *.
      pose proof (run_terms_length_bits args).
      pose proof (run_result_length_bits res). lia.
    - pose proof (IH n). lia.
  Qed.

  (** Counting query copies is linear in the syntax charge. *)
  Lemma run_query_copies_clock : forall (q : list (atom V.t)) n,
    (T_query_copies q n <=
      32 * N.of_nat (fold_right (fun a k => (atom_bits a + k)%nat) 0%nat q + 1))%N.
  Proof.
    induction q as [|[f args res|p args res] q IH]; intro n.
    - time_unfold @T_query_copies. time_cbn. nia.
    - pose proof (run_term_copies_clock (args ++ option_list res) Empty n).
      pose proof (IH (term_copies Empty (args ++ option_list res) n)).
      pose proof (Datatypes.T_app_le args (option_list res)).
      pose proof (run_terms_length_bits args).
      time_unfold @T_query_copies. time_simpl.
      rewrite run_terms_bits_app, run_terms_bits_result in *.
      cbn [fold_right atom_bits]. nia.
    - pose proof (IH n). time_unfold @T_query_copies.
      cbn [fold_right atom_bits]. nia.
  Qed.

  (** Insertion preserves any property of the position pairs. *)
  Lemma run_insert_pair_Forall : forall (P : nat * nat -> Prop) ps j pos,
    P (j, pos) -> Forall P ps -> Forall P (insert_pair j pos ps).
  Proof.
    intros P ps. induction ps as [|[k q] ps IH]; intros j pos Hnew Hall.
    - cbn [insert_pair]. constructor; [exact Hnew|constructor].
    - inversion Hall as [|entry rest Hentry Hrest]; subst.
      cbn [insert_pair]. destruct (Nat.leb j k).
      + constructor; assumption.
      + constructor; [exact Hentry|apply IH; assumption].
  Qed.

  (** Sorting preserves any property of the position pairs. *)
  Lemma run_sort_pairs_Forall : forall (P : nat * nat -> Prop) ps,
    Forall P ps -> Forall P (sort_pairs ps).
  Proof.
    intros P ps Hall. induction Hall as [|[j pos] ps Hentry Hrest IH].
    - constructor.
    - cbn [sort_pairs]. apply run_insert_pair_Forall; assumption.
  Qed.

  (** One insertion pays for each comparison at the inserted variable's unary size. *)
  Lemma run_insert_pair_clock : forall ps j pos,
    (T_insert_pair j pos ps <=
      4 * N.of_nat (j + 1) * N.of_nat (length ps + 1))%N.
  Proof.
    induction ps as [|[k q] ps IH]; intros j pos.
    - time_unfold T_insert_pair. time_cbn. nia.
    - pose proof (Nat.T_leb_le j k).
      pose proof (IH j pos).
      time_unfold T_insert_pair. destruct (Nat.leb j k);
        cbn [length]; rewrite ?Nat2N.inj_succ, ?Nat2N.inj_add in *; nia.
  Qed.

  (** Sorting is quadratic in the list length and linear in the largest variable number. *)
  Lemma run_sort_pairs_clock : forall ps bound,
    Forall (fun entry => fst entry <= bound) ps ->
    (T_sort_pairs ps <= 8 * N.of_nat (bound + 1) *
      N.of_nat (length ps + 1) * N.of_nat (length ps + 1))%N.
  Proof.
    induction ps as [|[j pos] ps IH]; intros bound Hall.
    - time_unfold T_sort_pairs. time_cbn. nia.
    - inversion Hall as [|entry rest Hentry Hrest]; subst.
      pose proof (IH bound Hrest).
      pose proof (run_insert_pair_clock (sort_pairs ps) j pos).
      rewrite run_sort_pairs_length in *.
      time_unfold T_sort_pairs. cbn [length fst] in *.
      rewrite !Nat2N.inj_add, ?Nat2N.inj_succ in *. nia.
  Qed.

  (** Bounded positions bound the total unary charge of a permutation. *)
  Lemma run_pairs_positions_size : forall (ps : list (nat * nat)) cap,
    Forall (fun entry => snd entry < cap) ps ->
    run_positions_size (map snd ps) <= cap * length ps.
  Proof.
    induction ps as [|[j pos] ps IH]; intros cap Hall.
    - cbn [map length run_positions_size fold_right]. lia.
    - inversion Hall as [|entry rest Hentry Hrest]; subst.
      pose proof (IH cap Hrest).
      cbn [map length run_positions_size fold_right snd] in *.
      unfold run_positions_size in *. nia.
  Qed.

  (** Incrementing a positive word increases its width by at most one. *)
  Lemma run_pos_succ_bits : forall p,
    Pos.size_nat (Pos.succ p) <= Pos.size_nat p + 1.
  Proof.
    induction p as [p IH|p IH|]; cbn [Pos.succ Pos.size_nat]; lia.
  Qed.

  (** The same width bound includes the zero binary counter. *)
  Lemma run_N_succ_bits : forall n,
    N.size_nat (N.succ n) <= N.size_nat n + 1.
  Proof.
    intros [|p]; cbn [N.succ N.size_nat Pos.size_nat].
    - lia.
    - apply run_pos_succ_bits.
  Qed.

  Definition run_slot_counter_bits (st : slot_state) : nat :=
    match st with SlotState _ next _ => N.size_nat next end.

  (** Registering one slot increments its counter at most once. *)
  Lemma run_add_slot_counter_bits : forall f positions st,
    run_slot_counter_bits (snd (add_slot f positions st)) <= run_slot_counter_bits st + 1.
  Proof.
    intros f positions [table next rows]. unfold add_slot.
    destruct (trie_get (slot_code f positions) table);
      cbn [snd run_slot_counter_bits]; [lia|apply run_N_succ_bits].
  Qed.

  (** Registering a slot pays for its encoded key and its binary counter. *)
  Lemma run_add_slot_clock : forall f positions st,
    (T_add_slot f positions st <= 64 *
      N.of_nat (Pos.size_nat f + run_positions_size positions + run_slot_counter_bits st + 1))%N.
  Proof.
    intros f positions [table next rows].
    pose proof (run_slot_code_time f positions).
    pose proof (run_slot_code_bits f positions).
    pose proof (run_planner_set_clock N (slot_code f positions) next table).
    pose proof (N.T_succ_le next).
    time_unfold T_add_slot. PTrieT.trie_get_le.
    destruct (trie_get (slot_code f positions) table);
      cbn [run_slot_counter_bits]; nia.
  Qed.

  (** A consecutive-position list has a quadratic unary charge. *)
  Lemma run_count_from_positions_size : forall len start,
    run_positions_size (count_from start len) <= len * (start + len + 1).
  Proof.
    induction len as [|len IH]; intro start.
    - reflexivity.
    - cbn [count_from run_positions_size fold_right].
      pose proof (IH (S start)). unfold run_positions_size in *. nia.
  Qed.

  (** Enumerating positions allocates one list cell per requested position. *)
  Lemma run_count_from_clock : forall len start,
    (T_count_from start len <= N.of_nat (len + 1))%N.
  Proof.
    induction len as [|len IH]; intro start; time_step.
  Qed.

  (** Full-slot initialization increases the counter at most once per declaration. *)
  Lemma run_full_slots_counter_bits : forall ds seen st,
    run_slot_counter_bits (full_slots ds seen st) <= run_slot_counter_bits st + length ds.
  Proof.
    induction ds as [|[f ss out] ds IH]; intros seen st.
    - cbn [full_slots length]. lia.
    - cbn [full_slots length]. destruct (trie_get f seen).
      + pose proof (IH seen st). lia.
      + destruct out.
        * pose proof (IH (PTrieCode.set f tt seen) st). lia.
        * pose proof (IH (PTrieCode.set f tt seen)
            (snd (add_slot f (count_from 0 (S (length ss))) st))).
          pose proof (run_add_slot_counter_bits f (count_from 0 (S (length ss))) st). lia.
        * pose proof (IH (PTrieCode.set f tt seen) st). lia.
  Qed.
  (** A layout budget bounds its counters, fresh-name width and accumulated name lists.
      Stored real-variable numbers stay below the current main-variable frontier. *)
  Definition run_layout_ok (base budget : nat) (lay : var_layout) : Prop :=
    match lay with
    | VarLayout names nc nm fresh cn mn =>
        nc <= budget /\ nm <= budget /\ Pos.size_nat fresh <= budget /\
        length cn <= budget /\ length mn <= budget /\
        forall x j, trie_get x names = Some j -> j <= base + nm
    end.

  (** Enlarging a budget preserves a prepared layout. *)
  Lemma run_layout_ok_mono : forall base small large lay,
    small <= large -> run_layout_ok base small lay -> run_layout_ok base large lay.
  Proof.
    intros base small large [names nc nm fresh cn mn] Hle Hready.
    destruct Hready as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
    cbn [run_layout_ok]. repeat split; try lia. exact Hnames.
  Qed.

  (** A literal allocates one main variable and advances the fresh name. *)
  Lemma run_layout_literal : forall base budget names nc nm fresh cn mn,
    run_layout_ok base budget (VarLayout names nc nm fresh cn mn) ->
    run_layout_ok base (S budget)
      (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn)).
  Proof.
    intros base budget names nc nm fresh cn mn Hready.
    destruct Hready as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
    pose proof (run_pos_succ_bits fresh).
    cbn [run_layout_ok length]. repeat split; try lia.
    intros x j Hget. specialize (Hnames x j Hget). lia.
  Qed.

  (** A repeated variable allocates one copy and advances the fresh name. *)
  Lemma run_layout_copy : forall base budget names nc nm fresh cn mn,
    run_layout_ok base budget (VarLayout names nc nm fresh cn mn) ->
    run_layout_ok base (S budget)
      (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn).
  Proof.
    intros base budget names nc nm fresh cn mn Hready.
    destruct Hready as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
    pose proof (run_pos_succ_bits fresh).
    cbn [run_layout_ok length]. repeat split; try lia. exact Hnames.
  Qed.

  (** A new real variable is stored at the former main-variable frontier. *)
  Lemma run_layout_variable : forall base budget names nc nm fresh cn mn x,
    run_layout_ok base budget (VarLayout names nc nm fresh cn mn) ->
    run_layout_ok base (S budget)
      (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn)).
  Proof.
    intros base budget names nc nm fresh cn mn x Hready.
    destruct Hready as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
    cbn [run_layout_ok length]. repeat split; try lia.
    intros y j Hget. destruct (Pos.eq_dec y x) as [Heq|Hneq].
    - subst y. rewrite PTrie.get_set_same in Hget. inversion Hget. lia.
    - rewrite PTrie.get_set_other in Hget by exact Hneq.
      specialize (Hnames y j Hget). lia.
  Qed.

  (** The empty layout needs only the width of its initial fresh name. *)
  Lemma run_layout_initial : forall base budget fresh,
    Pos.size_nat fresh <= budget ->
    run_layout_ok base budget (VarLayout Empty 0 0 fresh [] []).
  Proof.
    intros base budget fresh Hfresh. cbn [run_layout_ok length].
    repeat split; try lia. intros x j Hget.
    rewrite PTrie.get_empty in Hget. discriminate.
  Qed.

  (** Each processed term grows the layout budget by at most one. *)
  Lemma run_place_terms_layout : forall base (ts : list (term V.t)) pos seen lay pairs lits
      copied budget,
    run_layout_ok base budget lay ->
    run_layout_ok base (budget + length ts)
      (fst (fst (fst (place_terms base ts pos seen lay pairs lits copied)))).
  Proof.
    intros base ts. induction ts as [|[x|v] ts IH];
      intros pos seen [names nc nm fresh cn mn] pairs lits copied budget Hready.
    - cbn [place_terms fst length]. replace (budget + 0) with budget by lia. exact Hready.
    - cbn [place_terms length].
      replace (budget + S (length ts)) with (S budget + length ts) by lia.
      destruct (trie_get x seen).
      + apply IH. now apply run_layout_copy.
      + destruct (trie_get x names).
        * apply IH. eapply run_layout_ok_mono with (small := budget); [lia|exact Hready].
        * apply IH. now apply run_layout_variable.
    - cbn [place_terms length].
      replace (budget + S (length ts)) with (S budget + length ts) by lia.
      apply IH. now apply run_layout_literal.
  Qed.

  (** The term layout creates at most one literal entry per term. *)
  Lemma run_place_terms_literals_length : forall base (ts : list (term V.t)) pos seen lay
      pairs lits copied,
    length (snd (fst (place_terms base ts pos seen lay pairs lits copied))) <=
      length ts + length lits.
  Proof.
    intros base ts. induction ts as [|[x|v] ts IH];
      intros pos seen [names nc nm fresh cn mn] pairs lits copied;
      cbn [place_terms fst snd length].
    - lia.
    - destruct (trie_get x seen).
      + pose proof (IH (S pos) seen
          (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn)
          ((nc, pos) :: pairs) lits true). lia.
      + destruct (trie_get x names) as [j|].
        * pose proof (IH (S pos) (PTrieCode.set x tt seen)
            (VarLayout names nc nm fresh cn mn) ((j, pos) :: pairs) lits copied). lia.
        * pose proof (IH (S pos) (PTrieCode.set x tt seen)
            (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
            ((base + nm, pos) :: pairs) lits copied). lia.
    - pose proof (IH (S pos) seen
        (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn))
        ((base + nm, pos) :: pairs) ((base + nm, v) :: lits) copied).
      cbn [length] in *. lia.
  Qed.

  (** Every generated pair stays within the variable and position frontiers. *)
  Lemma run_place_terms_pairs : forall base (ts : list (term V.t)) pos seen lay pairs lits
      copied budget variables positions,
    run_layout_ok base budget lay ->
    base + budget + length ts <= variables -> pos + length ts <= positions ->
    Forall (fun pair => fst pair <= variables /\ snd pair < positions) pairs ->
    Forall (fun pair => fst pair <= variables /\ snd pair < positions)
      (snd (fst (fst (place_terms base ts pos seen lay pairs lits copied)))).
  Proof.
    intros base ts. induction ts as [|[x|v] ts IH];
      intros pos seen [names nc nm fresh cn mn] pairs lits copied budget variables positions
        Hready Hvariables Hpositions Hpairs; cbn [length] in Hvariables, Hpositions.
    - exact Hpairs.
    - pose proof Hready as Hparts.
      destruct Hparts as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
      cbn [place_terms]. destruct (trie_get x seen).
      + eapply IH with (budget := S budget).
        * now apply run_layout_copy.
        * cbn [length] in Hvariables. lia.
        * cbn [length] in Hpositions. lia.
        * constructor; [cbn [fst snd]; split; lia|exact Hpairs].
      + destruct (trie_get x names) as [j|] eqn:Hname.
        * eapply IH with (budget := S budget).
          -- eapply run_layout_ok_mono with (small := budget); [lia|exact Hready].
          -- cbn [length] in Hvariables. lia.
          -- cbn [length] in Hpositions. lia.
          -- constructor; [|exact Hpairs].
             specialize (Hnames x j Hname). cbn [fst snd]. split; lia.
        * eapply IH with (budget := S budget).
          -- now apply run_layout_variable.
          -- cbn [length] in Hvariables. lia.
          -- cbn [length] in Hpositions. lia.
          -- constructor; [cbn [fst snd]; split; lia|exact Hpairs].
    - pose proof Hready as Hparts.
      destruct Hparts as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
      cbn [place_terms]. eapply IH with (budget := S budget).
      + now apply run_layout_literal.
      + cbn [length] in Hvariables. lia.
      + cbn [length] in Hpositions. lia.
      + constructor; [cbn [fst snd]; split; lia|exact Hpairs].
  Qed.

  (** Term placement pays its syntax charge at the bounded layout frontier. *)
  Lemma run_place_terms_clock : forall base (ts : list (term V.t)) pos seen lay pairs lits
      copied budget cap,
    run_layout_ok base budget lay -> budget + terms_bits ts <= cap ->
    (T_place_terms base ts pos seen lay pairs lits copied <=
      64 * N.of_nat (terms_bits ts + 1) * N.of_nat (base + cap + 1))%N.
  Proof.
    intros base ts. induction ts as [|[x|v] ts IH];
      intros pos seen [names nc nm fresh cn mn] pairs lits copied budget cap Hready Hcap.
    - time_unfold @T_place_terms. time_cbn. nia.
    - pose proof Hready as Hparts.
      destruct Hparts as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
      assert (Htail : S budget + terms_bits ts <= cap)
        by (cbn [terms_bits fold_right term_bits] in Hcap; unfold terms_bits in *; lia).
      pose proof (run_planner_set_clock unit x tt seen) as Hseen.
      pose proof (run_planner_set_clock nat x (base + nm) names) as Hset.
      pose proof (Pos.T_succ_le fresh) as Hsucc.
      pose proof (Nat.T_add_le base nm) as Hadd.
      time_unfold @T_place_terms. time_simpl.
      destruct (trie_get x seen).
      + pose proof (IH (S pos) seen
          (VarLayout names (S nc) nm (Pos.succ fresh) (fresh :: cn) mn)
          ((nc, pos) :: pairs) lits true (S budget) cap
          (run_layout_copy base budget names nc nm fresh cn mn Hready) Htail) as Hrest.
        PTrieT.trie_get_le.
        cbn [terms_bits fold_right term_bits] in *. unfold terms_bits in *. nia.
      + destruct (trie_get x names) as [j|].
        * assert (Hnext : run_layout_ok base (S budget)
            (VarLayout names nc nm fresh cn mn))
            by (eapply run_layout_ok_mono with (small := budget); [lia|exact Hready]).
          pose proof (IH (S pos) (PTrieCode.set x tt seen)
            (VarLayout names nc nm fresh cn mn) ((j, pos) :: pairs) lits copied
            (S budget) cap Hnext Htail) as Hrest.
          PTrieT.trie_get_le.
          cbn [terms_bits fold_right term_bits] in *. unfold terms_bits in *. nia.
        * pose proof (IH (S pos) (PTrieCode.set x tt seen)
            (VarLayout (PTrieCode.set x (base + nm) names) nc (S nm) fresh cn (x :: mn))
            ((base + nm, pos) :: pairs) lits copied (S budget) cap
            (run_layout_variable base budget names nc nm fresh cn mn x Hready) Htail) as Hrest.
          PTrieT.trie_get_le.
          cbn [terms_bits fold_right term_bits] in *. unfold terms_bits in *. nia.
    - assert (Htail : S budget + terms_bits ts <= cap)
        by (cbn [terms_bits fold_right term_bits] in Hcap; unfold terms_bits in *; lia).
      pose proof (IH (S pos) seen
        (VarLayout names nc (S nm) (Pos.succ fresh) cn (fresh :: mn))
        ((base + nm, pos) :: pairs) ((base + nm, v) :: lits) copied (S budget) cap
        (run_layout_literal base budget names nc nm fresh cn mn Hready) Htail) as Hrest.
      pose proof Hready as Hparts.
      destruct Hparts as [Hnc [Hnm [Hfresh [Hcn [Hmn Hnames]]]]].
      pose proof (Pos.T_succ_le fresh) as Hsucc.
      pose proof (Nat.T_add_le base nm) as Hadd.
      time_unfold @T_place_terms. time_simpl.
      cbn [terms_bits fold_right term_bits] in *. unfold terms_bits in *. nia.
  Qed.
  (** Declaration syntax bounds both the number of declarations and their argument lists. *)
  Lemma run_decls_length_bits : forall ds,
    length ds <= fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds.
  Proof.
    induction ds as [|[f ss out] ds IH].
    - cbn [length fold_right]. lia.
    - change (S (length ds) <= Pos.size_nat f + length ss + 1 +
        fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds). lia.
  Qed.

  (** Full-slot preparation is quadratic in the enclosing syntax budget. *)
  Lemma run_full_slots_clock : forall ds seen st cap,
    fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds + run_slot_counter_bits st <= cap ->
    (T_full_slots ds seen st <= 512 *
      N.of_nat (fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds + 1) * N.of_nat (cap + 1))%N.
  Proof.
    induction ds as [|[f ss out] ds IH]; intros seen st cap Hcap.
    - time_unfold T_full_slots. time_cbn. nia.
    - cbn [fold_right] in Hcap |- *.
      change (decl_bits (Decl f ss out)) with (Pos.size_nat f + length ss + 1) in *.
      assert (Htail : fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds +
        run_slot_counter_bits st <= cap)
        by (cbn [fold_right] in Hcap; lia).
      pose proof (run_planner_set_clock unit f tt seen) as Hset.
      time_unfold T_full_slots. time_simpl.
      destruct (trie_get f seen).
      + pose proof (IH seen st cap Htail) as Hrest.
        PTrieT.trie_get_le.
        cbn [fold_right decl_bits name arg_sorts] in *. nia.
      + destruct out.
        * pose proof (IH (PTrieCode.set f tt seen) st cap Htail) as Hrest.
          PTrieT.trie_get_le.
          cbn [fold_right decl_bits name arg_sorts] in *. nia.
        * set (st' := snd (add_slot f (count_from 0 (S (length ss))) st)).
          pose proof (run_add_slot_counter_bits f (count_from 0 (S (length ss))) st) as Hwidth.
          change (run_slot_counter_bits st' <= run_slot_counter_bits st + 1) in Hwidth.
          assert (Hnext : fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds +
              run_slot_counter_bits st' <= cap)
            by (cbn [fold_right decl_bits name arg_sorts] in Hcap; lia).
          pose proof (IH (PTrieCode.set f tt seen) st' cap Hnext) as Hrest.
          pose proof (run_add_slot_clock f (count_from 0 (S (length ss))) st) as Hslot.
          pose proof (run_count_from_positions_size (S (length ss)) 0) as Hpositions.
          pose proof (run_count_from_clock (S (length ss)) 0) as Hcount.
          pose proof (Datatypes.T_length_le ss) as Hlength.
          assert (Hpositions_cap : run_positions_size (count_from 0 (S (length ss))) <=
              S (length ss) * (cap + 1)) by (clear -Hpositions Hcap; nia).
          assert (HpositionsN : (N.of_nat (run_positions_size (count_from 0 (S (length ss)))) <=
              N.of_nat (S (length ss) * (cap + 1)))%N) by lia.
          rewrite Nat2N.inj_mul in HpositionsN.
          assert (Hslot' : (T_add_slot f (count_from 0 (S (length ss))) st <=
              128 * N.of_nat (Pos.size_nat f + length ss + 1) * N.of_nat (cap + 1))%N).
          { clear -Hslot HpositionsN Hcap. rewrite !Nat2N.inj_add in Hslot.
            assert (Hlarge : (N.of_nat (Pos.size_nat f + length ss + 1) <=
                N.of_nat (Pos.size_nat f + length ss + 1) * N.of_nat (cap + 1))%N)
              by nia.
            assert (Hpositive : (N.of_nat (cap + 1) <=
                N.of_nat (Pos.size_nat f + length ss + 1) * N.of_nat (cap + 1))%N)
              by nia.
            nia. }
          clear Hslot Hpositions Hpositions_cap HpositionsN IH Hwidth Hnext.
          assert (Hcredit : (N.of_nat (Pos.size_nat f + length ss + 1) <=
              N.of_nat (Pos.size_nat f + length ss + 1) * N.of_nat (cap + 1))%N)
            by (clear; nia).
          clear Hcap Htail.
          PTrieT.trie_get_le.
          time_simpl. cbn [fold_right decl_bits name arg_sorts] in *.
          rewrite !Nat2N.inj_add, ?Nat2N.inj_succ in *.
          nia.
        * pose proof (IH (PTrieCode.set f tt seen) st cap Htail) as Hrest.
          PTrieT.trie_get_le.
          cbn [fold_right decl_bits name arg_sorts] in *. nia.
  Qed.

  (** Reversal onto an accumulator preserves the total number of list cells. *)
  Lemma run_rev_append_length : forall A (xs ys : list A),
    length (rev_append xs ys) = length xs + length ys.
  Proof.
    intros A xs. induction xs as [|x xs IH]; intro ys; cbn [rev_append length].
    - reflexivity.
    - rewrite IH. cbn [length]. lia.
  Qed.

  (** Source and column construction visit each atom and each literal once. *)
  Definition run_atoms_charge (atoms : list (atom_plan V.t)) : nat :=
    fold_right (fun a n => match a with AtomPlan _ _ lits => length lits + 1 + n end) 0 atoms.

  Lemma run_atoms_charge_rev_append : forall xs ys,
    run_atoms_charge (rev_append xs ys) = run_atoms_charge xs + run_atoms_charge ys.
  Proof.
    induction xs as [|[slot col lits] xs IH]; intro ys.
    - reflexivity.
    - cbn [rev_append]. rewrite IH. cbn [run_atoms_charge fold_right].
      unfold run_atoms_charge in *. lia.
  Qed.

  Lemma run_atoms_charge_length : forall atoms,
    length atoms <= run_atoms_charge atoms.
  Proof.
    induction atoms as [|[slot col lits] atoms IH];
      cbn [length run_atoms_charge fold_right] in *; unfold run_atoms_charge in *; lia.
  Qed.

  (** Each function atom contributes exactly one planned atom. *)
  Lemma run_plan_atoms_out_length : forall base (q : list (atom V.t)) ai lay st outs post,
    length (snd (fst (plan_atoms base q ai lay st outs post))) = fun_count q + length outs.
  Proof.
    intros base q. induction q as [|[f args res|p args res] q IH];
      intros ai lay st outs post.
    - reflexivity.
    - cbn [plan_atoms fun_count].
      destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
        as [[[lay' pairs] lits] copied].
      destruct (add_slot f (map snd (sort_pairs pairs)) st) as [slot st'].
      rewrite IH. cbn [length]. lia.
    - cbn [plan_atoms fun_count]. apply IH.
  Qed.

  (** An atom contributes at most one entry to the post filter. *)
  Lemma run_plan_atoms_post_length : forall base (q : list (atom V.t)) ai lay st outs post,
    length (snd (plan_atoms base q ai lay st outs post)) <= length q + length post.
  Proof.
    intros base q. induction q as [|[f args res|p args res] q IH];
      intros ai lay st outs post.
    - cbn [plan_atoms length snd]. lia.
    - cbn [plan_atoms length].
      destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
        as [[[lay' pairs] lits] copied].
      destruct (add_slot f (map snd (sort_pairs pairs)) st) as [slot st'].
      pose proof (IH (S ai) lay' st'
        (AtomPlan slot (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
        (if copied then ai :: post else post)).
      destruct copied; cbn [length] in *; lia.
    - cbn [plan_atoms length].
      pose proof (IH (S ai) lay st outs (ai :: post)). cbn [length] in *. lia.
  Qed.

  (** Planning function atoms increments the slot counter at most once per atom. *)
  Lemma run_plan_atoms_counter_bits : forall base (q : list (atom V.t)) ai lay st outs post,
    run_slot_counter_bits (snd (fst (fst (plan_atoms base q ai lay st outs post)))) <=
      run_slot_counter_bits st + length q.
  Proof.
    intros base q. induction q as [|[f args res|p args res] q IH];
      intros ai lay st outs post.
    - cbn [plan_atoms fst snd length]. lia.
    - cbn [plan_atoms length].
      destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
        as [[[lay' pairs] lits] copied].
      pose proof (run_add_slot_counter_bits f (map snd (sort_pairs pairs)) st) as Hslot.
      destruct (add_slot f (map snd (sort_pairs pairs)) st) as [slot st'] eqn:Hadd.
      try rewrite Hadd in Hslot. cbn [snd] in Hslot.
      pose proof (IH (S ai) lay' st'
        (AtomPlan slot (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
        (if copied then ai :: post else post)). lia.
    - cbn [plan_atoms length]. pose proof (IH (S ai) lay st outs (ai :: post)). lia.
  Qed.

  (** Planning a query grows its layout by no more than its syntax charge. *)
  Lemma run_plan_atoms_layout : forall base (q : list (atom V.t)) ai lay st outs post budget,
    run_layout_ok base budget lay ->
    run_layout_ok base (budget + fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q)
      (fst (fst (fst (plan_atoms base q ai lay st outs post)))).
  Proof.
    intros base q. induction q as [|[f args res|p args res] q IH];
      intros ai lay st outs post budget Hready.
    - cbn [plan_atoms fst fold_right]. replace (budget + 0) with budget by lia. exact Hready.
    - cbn [plan_atoms].
      pose proof (run_place_terms_layout base (args ++ option_list res) 0 Empty
        lay [] [] false budget Hready) as Hlayout.
      destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
        as [[[lay' pairs] lits] copied] eqn:Hterms.
      try rewrite Hterms in Hlayout. cbn [fst] in Hlayout.
      destruct (add_slot f (map snd (sort_pairs pairs)) st) as [slot st'].
      pose proof (IH (S ai) lay' st'
        (AtomPlan slot (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
        (if copied then ai :: post else post) (budget + length (args ++ option_list res))
        Hlayout) as Htail.
      eapply run_layout_ok_mono; [|exact Htail].
      pose proof (run_terms_length_bits args).
      pose proof (run_result_length_bits res).
      rewrite length_app. cbn [fold_right atom_bits]. lia.
    - cbn [plan_atoms].
      pose proof (IH (S ai) lay st outs (ai :: post) budget Hready) as Htail.
      eapply run_layout_ok_mono; [|exact Htail]. cbn [fold_right atom_bits]. lia.
  Qed.

  (** Planned atoms and their literal entries are bounded by the query's syntax charge. *)
  Lemma run_plan_atoms_charge : forall base (q : list (atom V.t)) ai lay st outs post,
    run_atoms_charge (snd (fst (plan_atoms base q ai lay st outs post))) <=
      run_atoms_charge outs + fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q.
  Proof.
    intros base q. induction q as [|[f args res|p args res] q IH];
      intros ai lay st outs post.
    - cbn [plan_atoms fst snd fold_right]. lia.
    - cbn [plan_atoms].
      pose proof (run_place_terms_literals_length base (args ++ option_list res) 0 Empty
        lay [] [] false) as Hlits.
      destruct (place_terms base (args ++ option_list res) 0 Empty lay [] [] false)
        as [[[lay' pairs] lits] copied] eqn:Hterms.
      try rewrite Hterms in Hlits. cbn [fst snd length] in Hlits.
      destruct (add_slot f (map snd (sort_pairs pairs)) st) as [slot st'].
      pose proof (IH (S ai) lay' st'
        (AtomPlan slot (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
        (if copied then ai :: post else post)) as Htail.
      cbn [run_atoms_charge fold_right] in Htail.
      rewrite run_rev_append_length in Htail. cbn [length] in Htail.
      pose proof (run_terms_length_bits args).
      pose proof (run_result_length_bits res).
      rewrite length_app in Hlits. cbn [fold_right atom_bits].
      unfold run_atoms_charge in *. lia.
    - cbn [plan_atoms].
      pose proof (IH (S ai) lay st outs (ai :: post)). cbn [fold_right atom_bits]. lia.
  Qed.

  (** Literal-column construction is linear in the literal list. *)
  Lemma run_literal_cols_clock : forall (lits : list (nat * V.t)) tail,
    (T_literal_cols lits tail <= 2 * N.of_nat (length lits + 1))%N.
  Proof.
    induction lits as [|[j v] lits IH]; intro tail; time_step.
  Qed.

  (** Building all join columns visits each atom and literal once. *)
  Lemma run_plan_cols_clock : forall atoms : list (atom_plan V.t),
    (T_plan_cols atoms <= 4 * N.of_nat (run_atoms_charge atoms + 1))%N.
  Proof.
    induction atoms as [|[slot col lits] atoms IH].
    - time_unfold @T_plan_cols. time_cbn. nia.
    - pose proof (run_literal_cols_clock lits (plan_cols atoms)).
      time_unfold @T_plan_cols. cbn [run_atoms_charge fold_right] in *.
      unfold run_atoms_charge in *. nia.
  Qed.

  (** Literal sources have the same linear construction bound. *)
  Lemma run_literal_sources_clock : forall (lits : list (nat * V.t)) tail,
    (T_literal_sources lits tail <= 2 * N.of_nat (length lits + 1))%N.
  Proof.
    induction lits as [|[j v] lits IH]; intro tail; time_step.
  Qed.

  (** Building a source list additionally performs constant-time pivot tests. *)
  Lemma run_plan_srcs_clock : forall (atoms : list (atom_plan V.t)) pivot,
    (T_plan_srcs atoms pivot <= 8 * N.of_nat (run_atoms_charge atoms + 1))%N.
  Proof.
    induction atoms as [|[slot col lits] atoms IH]; intro pivot.
    - time_unfold @T_plan_srcs. time_cbn. nia.
    - pose proof (IH (pivot_next pivot)).
      pose proof (run_literal_sources_clock lits (plan_srcs atoms (pivot_next pivot))).
      time_unfold @T_plan_srcs. time_simpl.
      cbn [run_atoms_charge fold_right] in *. unfold run_atoms_charge in *. nia.
  Qed.

  (** There is one semi-naive plan for every remaining pivot atom. *)
  Lemma run_semi_plans_length : forall i j vars post atoms m todo,
    length (@semi_plans V.t i j vars post atoms m todo) = length todo.
  Proof.
    intros i j vars post atoms m todo. revert m.
    induction todo as [|a todo IH]; intro m; cbn [semi_plans length].
    - reflexivity.
    - rewrite IH. reflexivity.
  Qed.

  (** Semi-naive construction pays once for the source list of each pivot. *)
  Lemma run_semi_plans_clock : forall i j vars post atoms m todo,
    (T_semi_plans i j vars post atoms m todo <=
      16 * N.of_nat (length todo + 1) * N.of_nat (run_atoms_charge atoms + 1))%N.
  Proof.
    intros i j vars post atoms m todo. revert m.
    induction todo as [|a todo IH]; intro m.
    - time_unfold @T_semi_plans. time_cbn. nia.
    - pose proof (run_plan_srcs_clock atoms (Some m)).
      pose proof (IH (S m)).
      time_unfold @T_semi_plans. cbn [length].
      rewrite ?Nat2N.inj_succ, !Nat2N.inj_add in *. nia.
  Qed.

  (** The function-atom count is bounded by the query's syntax charge. *)
  Lemma run_fun_count_bits : forall q : list (atom V.t),
    fun_count q <= fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q.
  Proof.
    induction q as [|[f args res|p args res] q IH]; cbn [fun_count fold_right atom_bits]; lia.
  Qed.

  (** A rule produces exactly its function-atom count of semi-naive plans. *)
  Lemma run_plan_rule_semis_length : forall i r st,
    length (snd (@plan_rule V.t i r st)) = fun_count (query V.t r).
  Proof.
    intros i [q acts] st. unfold plan_rule.
    pose proof (run_plan_atoms_out_length (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []) as Houts.
    destruct (plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay st'] outs] post] eqn:Hplan.
    try rewrite Hplan in Houts. cbn [fst snd length] in Houts.
    destruct lay. cbn [snd query].
    rewrite run_semi_plans_length, run_rev_append_length. cbn [length]. lia.
  Qed.
  (** A freshly placed atom has bounded columns and positions and no extra literals. *)
  Lemma run_placed_atom_bounds : forall base (ts : list (term V.t))
      lay budget cap lay' pairs lits copied,
    run_layout_ok base budget lay -> budget + terms_bits ts <= cap ->
    place_terms base ts 0 Empty lay [] [] false = (((lay', pairs), lits), copied) ->
    length pairs = length ts /\ length lits <= length ts /\
    Forall (fun pair => fst pair <= base + cap) pairs /\
    Forall (fun pair => snd pair < length ts) pairs.
  Proof.
    intros base ts lay budget cap lay' pairs lits copied Hready Hcap Hterms.
    pose proof (run_place_terms_length base ts 0 Empty lay [] [] false) as Hlength.
    pose proof (run_place_terms_literals_length base ts 0 Empty lay [] [] false) as Hlits.
    pose proof (run_terms_length_bits ts) as Hts.
    pose proof (run_place_terms_pairs base ts 0 Empty lay [] [] false budget
      (base + cap) (length ts) Hready ltac:(lia) ltac:(lia) (Forall_nil _)) as Hpairs.
    try rewrite Hterms in Hlength, Hlits, Hpairs. cbn [fst snd length] in *.
    split; [lia|]. split; [lia|]. split.
    - eapply Forall_impl; [|exact Hpairs]. intros [j pos] [Hj Hpos]. exact Hj.
    - eapply Forall_impl; [|exact Hpairs]. intros [j pos] [Hj Hpos]. exact Hpos.
  Qed.

  (** One atom pays for term placement, sorting and registration within the common budget. *)
  Lemma run_planned_atom_clock : forall base (ts : list (term V.t))
      lay st budget cap f lay' pairs lits copied,
    run_layout_ok base budget lay -> budget + terms_bits ts <= cap ->
    run_slot_counter_bits st <= cap ->
    place_terms base ts 0 Empty lay [] [] false = (((lay', pairs), lits), copied) ->
    (T_place_terms base ts 0 Empty lay [] [] false + T_sort_pairs pairs +
      ListDef.T_map (@snd nat nat) (fun pair => Datatypes.T_snd pair) (sort_pairs pairs) +
      T_add_slot f (map snd (sort_pairs pairs)) st +
      ListDef.T_map (@fst nat nat) (fun pair => Datatypes.T_fst pair) (sort_pairs pairs) +
      List.T_rev_append lits [] <=
      512 * N.of_nat (Pos.size_nat f + terms_bits ts + 1) *
        N.of_nat (base + cap + 1) * N.of_nat (base + cap + 1))%N.
  Proof.
    intros base ts lay st budget cap f lay' pairs lits copied Hready Hcap Hcounter Hterms.
    destruct (run_placed_atom_bounds base ts lay budget cap lay' pairs lits copied
      Hready Hcap Hterms) as [Hlength [Hlits [Hvars Hpositions]]].
    pose proof (run_place_terms_clock base ts 0 Empty lay [] [] false budget cap Hready Hcap)
      as Hplace.
    pose proof (run_sort_pairs_clock pairs (base + cap) Hvars) as Hsort.
    pose proof (run_add_slot_clock f (map snd (sort_pairs pairs)) st) as Hslot.
    pose proof (ListDef.T_map_le (@snd nat nat) (fun pair => Datatypes.T_snd pair)
      1%N (sort_pairs pairs) (fun pair => Datatypes.T_snd_le pair)) as Hmap_snd.
    pose proof (ListDef.T_map_le (@fst nat nat) (fun pair => Datatypes.T_fst pair)
      1%N (sort_pairs pairs) (fun pair => Datatypes.T_fst_le pair)) as Hmap_fst.
    pose proof (List.T_rev_append_le lits []) as Hreverse.
    pose proof (run_pairs_positions_size (sort_pairs pairs) (length ts)
      (run_sort_pairs_Forall _ _ Hpositions)) as Hpermutation.
    rewrite run_sort_pairs_length in Hpermutation, Hmap_snd, Hmap_fst.
    rewrite Hlength in Hpermutation, Hsort, Hmap_snd, Hmap_fst.
    pose proof (run_terms_length_bits ts) as Hts.
    set (h := N.of_nat (Pos.size_nat f + terms_bits ts + 1)).
    set (g := N.of_nat (base + cap + 1)).
    set (k := N.of_nat (length ts + 1)).
    assert (Hh : (1 <= h)%N) by (unfold h; lia).
    assert (Hg : (1 <= g)%N) by (unfold g; lia).
    assert (Hkh : (k <= h)%N) by (unfold k, h; lia).
    assert (Hkg : (k <= g)%N) by (unfold k, g; lia).
    assert (Hsquare : (k * k <= h * g)%N) by (apply N.mul_le_mono; assumption).
    pose proof (N.mul_le_mono_l _ _ g Hsquare) as Hcube.
    assert (Hcredit : (h <= h * g * g /\ g <= h * g * g /\ h * g <= h * g * g)%N)
      by (clear -Hh Hg;
        pose proof (N.mul_le_mono_l 1 g h Hg);
        pose proof (N.mul_le_mono_r 1 h g Hh);
        pose proof (N.mul_le_mono_l 1 g (h * g) Hg);
        repeat split; nia).
    destruct Hcredit as [Hcredit_h [Hcredit_g Hcredit_hg]].
    assert (Hperm : (N.of_nat (run_positions_size (map snd (sort_pairs pairs))) <= h * g)%N).
    { assert (HpermutationN : (N.of_nat (run_positions_size (map snd (sort_pairs pairs))) <=
          N.of_nat (length ts * length ts))%N) by lia.
      rewrite Nat2N.inj_mul in HpermutationN.
      clear -HpermutationN Hsquare. unfold k in Hsquare. nia. }
    assert (Hterm : (N.of_nat (terms_bits ts + 1) <= h)%N) by (unfold h; lia).
    assert (Hword : (N.of_nat (Pos.size_nat f) + 1 <= h)%N) by (unfold h; lia).
    assert (HcounterN : (N.of_nat (run_slot_counter_bits st) <= g)%N)
      by (unfold g; lia).
    assert (Hplace' : (T_place_terms base ts 0 Empty lay [] [] false <=
        64 * (h * g * g))%N).
    { change (T_place_terms base ts 0 Empty lay [] [] false <=
        64 * N.of_nat (terms_bits ts + 1) * g)%N in Hplace.
      pose proof (N.mul_le_mono_r _ _ g Hterm) as Hterm_product.
      clear -Hplace Hterm_product Hcredit_hg. nia. }
    assert (Hsort' : (T_sort_pairs pairs <= 8 * (h * g * g))%N).
    { change (T_sort_pairs pairs <= 8 * g * k * k)%N in Hsort.
      clear -Hsort Hcube. nia. }
    assert (Hslot' : (T_add_slot f (map snd (sort_pairs pairs)) st <=
        256 * (h * g * g))%N).
    { rewrite !Nat2N.inj_add in Hslot.
      clear -Hslot Hperm Hword HcounterN Hcredit_h Hcredit_g Hcredit_hg. nia. }
    assert (Hmaps : (ListDef.T_map (@snd nat nat) (fun pair => Datatypes.T_snd pair)
        (sort_pairs pairs) +
        ListDef.T_map (@fst nat nat) (fun pair => Datatypes.T_fst pair) (sort_pairs pairs) +
        List.T_rev_append lits [] <= 8 * (h * g * g))%N).
    { clear -Hmap_snd Hmap_fst Hreverse Hlits Hkh Hcredit_h.
      unfold k in Hkh. nia. }
    clear -Hplace' Hsort' Hslot' Hmaps. fold h g. nia.
  Qed.

  (** Query planning spends each atom's charge at the square of the common frontier. *)
  (** The atom's cubic allowance covers its list-traversal overhead.
      This arithmetic lemma keeps program expressions out of the solver context. *)
  Lemma run_plan_atom_overhead_credit : forall words terms result frontier,
    (1 <= frontier)%N ->
    (terms + 3 <= 512 * (words + terms + result + 1) * frontier * frontier)%N.
  Proof.
    intros words terms result frontier Hfrontier.
    assert (Hsyntax : (terms + 3 <= 512 * (words + terms + result + 1))%N) by lia.
    pose proof (N.mul_le_mono_l 1 frontier
      (512 * (words + terms + result + 1)) Hfrontier) as Hfirst.
    pose proof (N.mul_le_mono_l 1 frontier
      (512 * (words + terms + result + 1) * frontier) Hfrontier) as Hsecond.
    rewrite N.mul_1_r in Hfirst, Hsecond.
    eapply N.le_trans; [exact Hsyntax |].
    eapply N.le_trans; [exact Hfirst | exact Hsecond].
  Qed.

  Lemma run_plan_atoms_clock : forall base (q : list (atom V.t)) ai lay st outs post budget cap,
    run_layout_ok base budget lay ->
    budget + fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <= cap ->
    run_slot_counter_bits st + fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <= cap ->
    (T_plan_atoms base q ai lay st outs post <=
      1024 * N.of_nat (fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q + 1) *
        N.of_nat (base + cap + 1) * N.of_nat (base + cap + 1))%N.
  Proof.
    intros base q. induction q as [|[f args res|p args res] q IH];
      intros ai lay st outs post budget cap Hready Hbudget Hcounter.
    - time_unfold @T_plan_atoms. time_cbn. nia.
    - set (ts := args ++ option_list res).
      assert (Hts : terms_bits ts = terms_bits args + result_bits res)
        by (unfold ts; rewrite run_terms_bits_app, run_terms_bits_result; reflexivity).
      assert (Hlength : length ts <= terms_bits ts) by apply run_terms_length_bits.
      assert (Hplace_budget : budget + terms_bits ts <= cap)
        by (cbn [fold_right atom_bits] in Hbudget; lia).
      assert (Hslot_budget : run_slot_counter_bits st <= cap)
        by (cbn [fold_right atom_bits] in Hcounter; lia).
      pose proof (run_place_terms_layout base ts 0 Empty lay [] [] false budget Hready)
        as Hlayout.
      pose proof (run_add_slot_counter_bits f
        (map snd (sort_pairs (snd (fst (fst (place_terms base ts 0 Empty lay [] [] false))))))
        st) as Hwidth.
      time_unfold @T_plan_atoms. time_simpl. fold ts.
      destruct (place_terms base ts 0 Empty lay [] [] false)
        as [[[lay' pairs] lits] copied] eqn:Hterms.
      try rewrite Hterms in Hlayout, Hwidth. cbn [fst snd] in Hlayout, Hwidth.
      pose proof (run_planned_atom_clock base ts lay st budget cap f lay' pairs lits copied
        Hready Hplace_budget Hslot_budget Hterms) as Hhead.
      destruct (add_slot f (map snd (sort_pairs pairs)) st) as [slot st'] eqn:Hslot.
      try rewrite Hslot in Hwidth. cbn [snd] in Hwidth.
      assert (Hnext_budget : budget + length ts +
          fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <= cap)
        by (cbn [fold_right atom_bits] in Hbudget; lia).
      assert (Hnext_counter : run_slot_counter_bits st' +
          fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <= cap)
        by (cbn [fold_right atom_bits] in Hcounter; lia).
      pose proof (IH (S ai) lay' st'
        (AtomPlan slot (map fst (sort_pairs pairs)) (rev_append lits []) :: outs)
        (if copied then ai :: post else post) (budget + length ts) cap
        Hlayout Hnext_budget Hnext_counter) as Htail.
      pose proof (Datatypes.T_app_le args (option_list res)) as Happend.
      pose proof (run_terms_length_bits args) as Hargs.
      assert (Hcredit : (N.of_nat (terms_bits args) + 3 <=
          512 * N.of_nat (Pos.size_nat f + terms_bits args + result_bits res + 1) *
            N.of_nat (base + cap + 1) * N.of_nat (base + cap + 1))%N).
      { clear. rewrite !Nat2N.inj_add.
        apply run_plan_atom_overhead_credit. lia. }
      cbn [fold_right atom_bits]. rewrite Hts in Hhead.
      cbn [Datatypes.T_snd Datatypes.T_fst] in Hhead.
      change (fun pair : nat * nat => Datatypes.T_snd pair) with
        (fun _ : nat * nat => 1%N) in Hhead.
      change (fun pair : nat * nat => Datatypes.T_fst pair) with
        (fun _ : nat * nat => 1%N) in Hhead.
      rewrite !Nat2N.inj_add in *.
      clear -Hhead Htail Happend Hargs Hcredit.
      assert (Hextra : (Datatypes.T_app args (option_list res) + 2 <=
          512 * (N.of_nat (Pos.size_nat f) + N.of_nat (terms_bits args) +
            N.of_nat (result_bits res) + N.of_nat 1) *
            (N.of_nat base + N.of_nat cap + N.of_nat 1) *
            (N.of_nat base + N.of_nat cap + N.of_nat 1))%N) by lia.
      pose proof (N.add_le_mono _ _ _ _ Hhead Htail) as Hjoined.
      pose proof (N.add_le_mono _ _ _ _ Hjoined Hextra) as Htotal.
      clear -Htotal.
      nia.
    - assert (Hnext_budget : budget + fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <= cap)
        by (cbn [fold_right atom_bits] in Hbudget; lia).
      assert (Hnext_counter : run_slot_counter_bits st +
          fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <= cap)
        by (cbn [fold_right atom_bits] in Hcounter; lia).
      pose proof (IH (S ai) lay st outs (ai :: post) budget cap Hready
        Hnext_budget Hnext_counter) as Htail.
      time_unfold @T_plan_atoms. cbn [fold_right atom_bits].
      rewrite !Nat2N.inj_add in *.
      clear IH Hready Hbudget Hcounter Hnext_budget Hnext_counter.
      nia.
  Qed.
  (** A completed rule can increase the slot counter only at its function atoms. *)
  Lemma run_plan_rule_counter_bits : forall i r st,
    run_slot_counter_bits (fst (fst (@plan_rule V.t i r st))) <=
      run_slot_counter_bits st + rule_bits r.
  Proof.
    intros i [q acts] st. unfold plan_rule.
    pose proof (run_plan_atoms_counter_bits (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] []) as Hcounter.
    pose proof (run_query_length_bits q) as Hquery.
    assert (Hsyntax : fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <=
        rule_bits (Rule V.t q acts))
      by (unfold rule_bits; cbn [query actions]; lia).
    destruct (plan_atoms (query_copies q 0) q 0
      (VarLayout Empty 0 0 (Pos.succ (query_max q 1%positive)) [] []) st [] [])
      as [[[lay st'] outs] post] eqn:Hplan.
    try rewrite Hplan in Hcounter. cbn [fst snd] in Hcounter.
    destruct lay. cbn [fst]. lia.
  Qed.

  (** A rule's construction is bounded by its syntax charge and the enclosing counter budget. *)
  Lemma run_plan_rule_clock : forall i (r : rule V.t) st cap,
    rule_bits r + run_slot_counter_bits st <= cap ->
    (T_plan_rule i r st <= 16384 * N.of_nat (rule_bits r) *
      N.of_nat (cap + 1) * N.of_nat (cap + 1))%N.
  Proof.
    intros i [q acts] st cap Hcap.
    set (Q := fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q).
    set (base := query_copies q 0).
    set (fresh := Pos.succ (query_max q 1%positive)).
    set (initial := VarLayout Empty 0 0 fresh [] []).
    assert (HQ : Q + 1 <= rule_bits (Rule V.t q acts))
      by (unfold rule_bits, Q; cbn [query actions]; lia).
    assert (Hbase : base <= Q).
    { pose proof (run_query_copies_count q 0). unfold base, Q. lia. }
    assert (Hfresh : Pos.size_nat fresh <= Q + 2).
    { pose proof (run_query_max_bits q 1%positive).
      pose proof (run_pos_succ_bits (query_max q 1%positive)).
      unfold fresh, Q. cbn [Pos.size_nat] in *. lia. }
    assert (Hinitial : run_layout_ok base (Q + 2) initial)
      by (unfold initial; now apply run_layout_initial).
    assert (Hbudget : Q + 2 + Q <= 2 * cap + 2) by lia.
    assert (Hcounter : run_slot_counter_bits st + Q <= 2 * cap + 2) by lia.
    pose proof (run_plan_atoms_clock base q 0 initial st [] [] (Q + 2) (2 * cap + 2)
      Hinitial Hbudget Hcounter) as Hmain.
    pose proof (run_plan_atoms_layout base q 0 initial st [] [] (Q + 2) Hinitial)
      as Hlayout.
    pose proof (run_plan_atoms_out_length base q 0 initial st [] []) as Houts.
    pose proof (run_plan_atoms_post_length base q 0 initial st [] []) as Hpost.
    pose proof (run_plan_atoms_charge base q 0 initial st [] []) as Hcharge.
    pose proof (run_query_length_bits q) as Hqlength.
    pose proof (run_fun_count_bits q) as Hfunctions.
    pose proof (run_query_copies_clock q 0) as Hcopies.
    pose proof (run_query_max_clock q 1%positive) as Hmaximum.
    pose proof (Pos.T_succ_le (query_max q 1%positive)) as Hsuccessor.
    pose proof (run_query_max_bits q 1%positive) as Hmaxbits.
    time_unfold @T_plan_rule. time_simpl. fold base fresh initial.
    destruct (plan_atoms base q 0 initial st [] [])
      as [[[[names nc nm fresh' cn mn] st'] outs] post] eqn:Hplan.
    try rewrite Hplan in Hlayout, Houts, Hpost, Hcharge.
    cbn [fst snd length run_layout_ok run_atoms_charge fold_right] in
      Hlayout, Houts, Hpost, Hcharge.
    destruct Hlayout as [Hnc [Hnm [Hfresh' [Hcn [Hmn Hnames]]]]].
    pose proof (List.T_rev_append_le outs []) as Hrevouts.
    pose proof (List.T_rev_append_le cn (rev_append mn [])) as Hrevcn.
    pose proof (List.T_rev_append_le mn []) as Hrevmn.
    pose proof (List.T_rev_append_le post []) as Hrevpost.
    pose proof (Nat.T_add_le base nm) as Hadd.
    pose proof (run_plan_cols_clock (rev_append outs [])) as Hcols.
    pose proof (run_plan_srcs_clock (rev_append outs []) None) as Hsources.
    pose proof (run_semi_plans_clock i
      (JPlan (base + nm) (plan_cols (rev_append outs [])))
      (rev_append cn (rev_append mn [])) (rev_append post [])
      (rev_append outs []) 0 (rev_append outs [])) as Hsemis.
    rewrite run_atoms_charge_rev_append in Hcols, Hsources, Hsemis.
    rewrite run_rev_append_length in Hsemis.
    cbn [run_atoms_charge fold_right length] in Hcols, Hsources, Hsemis.
    unfold run_atoms_charge in Hcharge, Hcols, Hsources, Hsemis.
    fold Q in Hmain, Hnc, Hnm, Hfresh', Hcn, Hmn, Hcharge, Hqlength, Hfunctions,
      Hcopies, Hmaximum, Hmaxbits.
    assert (Hfrontier : (N.of_nat (base + (2 * cap + 2) + 1) <=
        3 * N.of_nat (cap + 1))%N) by lia.
    assert (Hmain' : (T_plan_atoms base q 0 initial st [] [] <=
        9216 * N.of_nat (rule_bits (Rule V.t q acts)) *
          N.of_nat (cap + 1) * N.of_nat (cap + 1))%N).
    { assert (HqueryN : (N.of_nat (Q + 1) <=
          N.of_nat (rule_bits (Rule V.t q acts)))%N) by lia.
      pose proof (N.mul_le_mono _ _ _ _ Hfrontier Hfrontier) as Hsquare.
      pose proof (N.mul_le_mono _ _ _ _ HqueryN Hsquare) as Hproduct.
      clear -Hmain Hproduct. nia. }
    assert (Hlinear_credit : (N.of_nat (Q + 1) <=
        N.of_nat (rule_bits (Rule V.t q acts)) * N.of_nat (cap + 1) *
          N.of_nat (cap + 1))%N) by (clear -HQ; nia).
    assert (Hquadratic_credit : (N.of_nat (Q + 1) * N.of_nat (Q + 1) <=
        N.of_nat (rule_bits (Rule V.t q acts)) * N.of_nat (cap + 1) *
          N.of_nat (cap + 1))%N) by (clear -HQ Hcap; nia).
    assert (Hsemis' : (T_semi_plans i
        (JPlan (base + nm) (plan_cols (rev_append outs [])))
        (rev_append cn (rev_append mn [])) (rev_append post [])
        (rev_append outs []) 0 (rev_append outs []) <=
        16 * N.of_nat (Q + 1) * N.of_nat (Q + 1))%N).
    { clear -Hsemis Houts Hfunctions Hcharge. nia. }
    cbn [Pos.size_nat] in Hmaxbits.
    assert (Hoverhead_linear :
      (1 + T_query_copies q 0 + T_query_max q 1%positive +
        Pos.T_succ (query_max q 1%positive) +
        List.T_rev_append outs [] +
        List.T_rev_append cn (rev_append mn []) + List.T_rev_append mn [] +
        List.T_rev_append post [] + Nat.T_add base nm +
        T_plan_cols (rev_append outs []) + T_plan_srcs (rev_append outs []) None <=
        256 * N.of_nat (Q + 1))%N).
    { clear -Hcopies Hmaximum Hsuccessor Hmaxbits Hrevouts Hrevcn Hrevmn
        Hrevpost Hadd Hcols Hsources Hcn Hmn Houts Hpost Hcharge Hqlength
        Hfunctions Hbase.
      lia. }
    assert (Hoverhead_cubic :
      (1 + T_query_copies q 0 + T_query_max q 1%positive +
        Pos.T_succ (query_max q 1%positive) +
        List.T_rev_append outs [] +
        List.T_rev_append cn (rev_append mn []) + List.T_rev_append mn [] +
        List.T_rev_append post [] + Nat.T_add base nm +
        T_plan_cols (rev_append outs []) + T_plan_srcs (rev_append outs []) None <=
        256 * N.of_nat (rule_bits (Rule V.t q acts)) *
          N.of_nat (cap + 1) * N.of_nat (cap + 1))%N).
    { pose proof (N.mul_le_mono_l _ _ 256 Hlinear_credit) as Hscaled.
      clear -Hoverhead_linear Hscaled. nia. }
    assert (Hsemis_cubic :
      (T_semi_plans i
        (JPlan (base + nm) (plan_cols (rev_append outs [])))
        (rev_append cn (rev_append mn [])) (rev_append post [])
        (rev_append outs []) 0 (rev_append outs []) <=
        16 * N.of_nat (rule_bits (Rule V.t q acts)) *
          N.of_nat (cap + 1) * N.of_nat (cap + 1))%N).
    { pose proof (N.mul_le_mono_l _ _ 16 Hquadratic_credit) as Hscaled.
      clear -Hsemis' Hscaled. nia. }
    pose proof (N.add_le_mono _ _ _ _ Hmain' Hoverhead_cubic) as Hjoined.
    pose proof (N.add_le_mono _ _ _ _ Hjoined Hsemis_cubic) as Htotal.
    clear -Htotal. nia.
  Qed.

  (** Every rule contributes at least one unit to program syntax. *)
  Lemma run_rules_length_bits : forall rs : list (rule V.t),
    length rs <= fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs.
  Proof.
    induction rs as [|r rs IH]; cbn [length fold_right].
    - lia.
    - assert (Hpositive : 1 <= rule_bits r) by (unfold rule_bits; lia). lia.
  Qed.

  (** The naive-plan accumulator receives one element per rule. *)
  Lemma run_plan_rules_naive_length : forall rs i st naive semi,
    length (snd (fst (@plan_rules V.t rs i st naive semi))) = length rs + length naive.
  Proof.
    induction rs as [|r rs IH]; intros i st naive semi.
    - reflexivity.
    - cbn [plan_rules]. destruct (plan_rule i r st) as [[st' c] cs].
      rewrite IH. cbn [length]. lia.
  Qed.

  (** Semi-naive plans add at most the remaining rules' syntax charge. *)
  Lemma run_plan_rules_semis_length : forall rs i st naive semi,
    length (snd (@plan_rules V.t rs i st naive semi)) <=
      fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs + length semi.
  Proof.
    induction rs as [|[q acts] rs IH]; intros i st naive semi.
    - cbn [plan_rules snd fold_right]. lia.
    - pose proof (run_plan_rule_semis_length i (Rule V.t q acts) st) as Hsemis.
      pose proof (run_fun_count_bits q) as Hfun.
      assert (Hsyntax : fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q <=
          rule_bits (Rule V.t q acts))
        by (unfold rule_bits; cbn [query actions]; lia).
      cbn [plan_rules]. destruct (plan_rule i (Rule V.t q acts) st)
        as [[st' c] cs] eqn:Hrule.
      try rewrite Hrule in Hsemis. cbn [snd query] in Hsemis.
      pose proof (IH (N.succ i) st' (c :: naive) (rev_append cs semi)) as Hrest.
      rewrite run_rev_append_length in Hrest. cbn [fold_right]. lia.
  Qed.

  (** A fixed budget covers both the growing slot counter and rule index. *)
  Lemma run_plan_rules_clock : forall (rs : list (rule V.t)) i st naive semi cap,
    fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs + run_slot_counter_bits st <= cap ->
    fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs + N.size_nat i <= cap ->
    (T_plan_rules rs i st naive semi <= 32768 *
      N.of_nat (fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs + 1) *
      N.of_nat (cap + 1) * N.of_nat (cap + 1))%N.
  Proof.
    induction rs as [|[q acts] rs IH]; intros i st naive semi cap Hslots Hindex.
    - time_unfold @T_plan_rules. time_cbn. nia.
    - assert (HQ : fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q + 1 <=
          rule_bits (Rule V.t q acts))
        by (unfold rule_bits; cbn [query actions]; lia).
      pose proof (run_plan_rule_clock i (Rule V.t q acts) st cap
        ltac:(cbn [fold_right] in Hslots; lia)) as Hhead.
      pose proof (run_plan_rule_counter_bits i (Rule V.t q acts) st) as Hcounter.
      pose proof (run_plan_rule_semis_length i (Rule V.t q acts) st) as Hsemis.
      pose proof (run_fun_count_bits q) as Hfun.
      pose proof (N.T_succ_le i) as Hsucc.
      pose proof (run_N_succ_bits i) as Hwidth.
      time_unfold @T_plan_rules.
      destruct (plan_rule i (Rule V.t q acts) st) as [[st' c] cs] eqn:Hrule.
      try rewrite Hrule in Hcounter, Hsemis. cbn [fst snd query] in Hcounter, Hsemis.
      assert (Hnext_slots : fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs +
          run_slot_counter_bits st' <= cap)
        by (cbn [fold_right] in Hslots; lia).
      assert (Hnext_index : fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs +
          N.size_nat (N.succ i) <= cap)
        by (cbn [fold_right] in Hindex; lia).
      pose proof (IH (N.succ i) st' (c :: naive) (rev_append cs semi)
        cap Hnext_slots Hnext_index) as Htail.
      pose proof (List.T_rev_append_le cs semi) as Hreverse.
      assert (Hsucc' : (N.T_succ i <= N.of_nat (cap + 1))%N)
        by (cbn [fold_right] in Hindex; lia).
      assert (Hcredit : (N.of_nat (cap + 1) + N.of_nat (rule_bits (Rule V.t q acts)) + 1 <=
          4 * N.of_nat (rule_bits (Rule V.t q acts)) *
            N.of_nat (cap + 1) * N.of_nat (cap + 1))%N)
        by (clear -HQ; nia).
      cbn [fold_right].
      assert (Hextra : (N.T_succ i + List.T_rev_append cs semi + 1 <=
          16384 * N.of_nat (rule_bits (Rule V.t q acts)) *
            N.of_nat (cap + 1) * N.of_nat (cap + 1))%N).
      { clear -Hreverse Hsemis Hfun HQ Hsucc' Hcredit. nia. }
      pose proof (N.add_le_mono _ _ _ _ Hhead Htail) as Hjoined.
      pose proof (N.add_le_mono _ _ _ _ Hjoined Hextra) as Htotal.
      clear -Htotal. rewrite !Nat2N.inj_add. nia.
  Qed.

  (** The row list is bounded by its positive slot charge. *)
  Lemma run_slots_length_size : forall rows,
    length rows <= run_slots_size rows.
  Proof.
    induction rows as [|[f positions] rows IH]; cbn [length run_slots_size fold_right] in *;
      unfold run_slots_size in *;
      lia.
  Qed.

  (** Program planning has one cubic charge for all declarations, rules and output reversals. *)
  Lemma run_plan_program_clock : forall p : program V.t,
    (T_plan_program p <= 65536 * N.of_nat (size_program p + 1) *
      N.of_nat (size_program p + 1) * N.of_nat (size_program p + 1))%N.
  Proof.
    intros [ds rs].
    set (S := size_program (Program V.t ds rs)).
    assert (Hsyntax : fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds +
        fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs + 1 = S)
      by reflexivity.
    set (st0 := full_slots ds Empty (SlotState Empty 0%N [])).
    pose proof (run_full_slots_counter_bits ds Empty (SlotState Empty 0%N [])) as Hwidth.
    pose proof (run_decls_length_bits ds) as Hdecls.
    pose proof (run_rules_length_bits rs) as Hrules.
    pose proof (run_full_slots_clock ds Empty (SlotState Empty 0%N []) S) as Hfull.
    assert (Hfullcap : fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds +
        run_slot_counter_bits (SlotState Empty 0%N []) <= S)
      by (cbn [run_slot_counter_bits N.size_nat]; lia).
    specialize (Hfull Hfullcap).
    assert (Hslots : fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs +
        run_slot_counter_bits st0 <= S).
    { unfold st0. cbn [run_slot_counter_bits N.size_nat] in Hwidth.
      lia. }
    assert (Hindex : fold_right (fun r n => (rule_bits r + n)%nat) 0%nat rs + N.size_nat 0 <= S)
      by (cbn [N.size_nat]; lia).
    pose proof (run_plan_rules_clock rs 0 st0 [] [] S Hslots Hindex) as Hmain.
    pose proof (run_plan_rules_naive_length rs 0 st0 [] []) as Hnaive.
    pose proof (run_plan_rules_semis_length rs 0 st0 [] []) as Hsemi.
    pose proof (run_plan_rules_size rs 0 st0 [] []) as Hrows.
    pose proof (run_full_slots_size ds Empty (SlotState Empty 0%N [])) as Hinitial.
    fold st0 in Hinitial.
    time_unfold @T_plan_program. fold st0.
    destruct (plan_rules rs 0 st0 [] []) as [[[table next rows] naive] semi] eqn:Hplan.
    try rewrite Hplan in Hnaive, Hsemi, Hrows.
    cbn [fst snd length run_slot_state_size] in Hnaive, Hsemi, Hrows.
    pose proof (run_slots_length_size rows) as Hrowlength.
    pose proof (List.T_rev_append_le rows []) as Hrevrows.
    pose proof (List.T_rev_append_le naive []) as Hrevnaive.
    pose proof (List.T_rev_append_le semi []) as Hrevsemi.
    change (run_slot_state_size st0 <=
      0 + 2 * fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds) in Hinitial.
    assert (Hmain' : (T_plan_rules rs 0 st0 [] [] <= 32768 *
        N.of_nat (S + 1) * N.of_nat (S + 1) * N.of_nat (S + 1))%N).
    { assert (Hquery : (N.of_nat (fold_right (fun r n => (rule_bits r + n)%nat)
          0%nat rs + 1) <= N.of_nat (S + 1))%N) by lia.
      pose proof (N.mul_le_mono_r _ _ (N.of_nat (S + 1) * N.of_nat (S + 1)) Hquery)
        as Hproduct.
      clear -Hmain Hproduct. nia. }
    assert (Hfull' : (T_full_slots ds Empty (SlotState Empty 0%N []) <= 512 *
        N.of_nat (S + 1) * N.of_nat (S + 1) * N.of_nat (S + 1))%N).
    { assert (Hdecl : (N.of_nat (fold_right (fun d n => (decl_bits d + n)%nat)
          0%nat ds + 1) <= N.of_nat (S + 1))%N) by lia.
      pose proof (N.mul_le_mono_r _ _ (N.of_nat (S + 1)) Hdecl) as Hproduct.
      assert (Hsquare : (N.of_nat (S + 1) * N.of_nat (S + 1) <=
          N.of_nat (S + 1) * N.of_nat (S + 1) * N.of_nat (S + 1))%N)
        by (clear; nia).
      clear -Hfull Hproduct Hsquare. nia. }
    assert (Hcredit : (N.of_nat (S + 1) <= N.of_nat (S + 1) *
        N.of_nat (S + 1) * N.of_nat (S + 1))%N) by (clear; nia).
    fold S.
    clear -Hmain' Hfull' Hnaive Hsemi Hrows Hinitial Hrules Hrowlength
      Hrevrows Hrevnaive Hrevsemi Hsyntax Hcredit. nia.
  Qed.

  Lemma T_plan_le : forall p,
    (T_plan p <= c_run * N.of_nat (size_program p + 1) * N.of_nat (size_program p + 1) *
      N.of_nat (size_program p + 1))%N.
  Proof.
    intro p. pose proof (run_plan_program_clock p) as Hprogram.
    time_unfold T_plan. unfold c_run. nia.
  Qed.

  Lemma plan_slots_le : forall p,
    (N.of_nat (fold_right (fun s n =>
      (Pos.size_nat (fst s) + length (snd s) + 1 + n)%nat) 0%nat
      (Syntax.slots V.t (plan p))) <=
      c_run * N.of_nat (size_program p + 1) * N.of_nat (size_program p + 1) *
        N.of_nat (size_program p + 1))%N.
  Proof.
    intro p. pose proof (run_plan_slots_size p) as Hslots.
    assert (HslotsN : (N.of_nat (run_slots_size (Syntax.slots V.t (plan p))) <=
      N.of_nat (2 * (size_program p + 1)))%N) by lia.
    rewrite Nat2N.inj_mul in HslotsN.
    change (N.of_nat (run_slots_size (Syntax.slots V.t (plan p))) <=
      c_run * N.of_nat (size_program p + 1) * N.of_nat (size_program p + 1) *
        N.of_nat (size_program p + 1))%N.
    assert (Hconstant : (2 <= c_run)%N) by (unfold c_run; lia).
    assert (Hpositive : (1 <= N.of_nat (size_program p + 1))%N) by lia.
    nia.
  Qed.

  Lemma T_load_le : forall p cp,
    (T_load p cp <= D.T_init (decls V.t p) (Syntax.slots V.t cp) + c_run)%N.
  Proof.
    intros [ds rs] [sl nv sn].
    assert (Hconstant : (3 <= c_run)%N) by (unfold c_run; lia).
    time_unfold T_load.
    unfold T_decls, T_compiled_slots, decls, compiled_slots, Syntax.slots.
    time_cbn. lia.
  Qed.

  Fixpoint T_apply_jobs (p : program V.t) (js : list (cplan V.t * list (cell V.t)))
      (db : D.t) : N :=
    match js with
    | [] => 0%N
    | (c, b) :: rest =>
        (T_apply (actions V.t (job_rule p c)) (fun x => trie_get x (bind_trie c b))
            (fun x => 1 + T_trie_get x (bind_trie c b)) db +
          T_apply_jobs p rest
            (apply (actions V.t (job_rule p c)) (fun x => trie_get x (bind_trie c b)) db))%N
    end.

  Definition k_driver : N :=
    (64 * 1024 * (D.c_db + I.c_ix + J.c_join + V.c_val + V.c_key +
      PTrieT.c_trie + 1))%N.
  Definition k_check : N := (64 * 1024 * (V.c_key + PTrieT.c_trie + 1))%N.
  (** A well-sorted action list has well-sorted prefixes in its initial context. *)
  Lemma run_actions_ok_prefix : forall sorts kinds (pre suffix : list (action V.t)) g,
    actions_ok sorts kinds g (pre ++ suffix) -> actions_ok sorts kinds g pre.
  Proof.
    intros sorts kinds pre. induction pre as [|a pre IH]; intros suffix g Hacts.
    - exact I.
    - destruct a as [x f args|f args res|t u|x op args]; cbn [app actions_ok] in *.
      + destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]]. exists ss.
        split; [exact Hsort|]. split; [exact Hkind|]. split; [exact Hargs|].
        eapply IH. exact Hrest.
      + destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hres Hrest]]]]]].
        exists ss, out. split; [exact Hsort|]. split; [exact Hkind|].
        split; [exact Hargs|]. split; [exact Hres|]. eapply IH. exact Hrest.
      + destruct Hacts as [Ht [Hu Hrest]]. split; [exact Ht|]. split; [exact Hu|].
        eapply IH. exact Hrest.
      + destruct Hacts as [Hargs Hrest]. split; [exact Hargs|]. eapply IH. exact Hrest.
  Qed.

  (** Action execution never lowers the unit when every executed prefix is well formed. *)
  Lemma run_apply_go_unit : forall acts s locals db,
    (forall pre suffix, acts = pre ++ suffix -> D.wf (apply_go pre s locals db)) ->
    D.unit db <= D.unit (apply_go acts s locals db).
  Proof.
    intros acts. induction acts as [|a rest IH]; intros s locals db Hprefix.
    - cbn [apply_go]. lia.
    - assert (Hwf : D.wf db).
      { exact (Hprefix [] (a :: rest) eq_refl). }
      destruct a as [x f args|f args res|t u|x op args]; cbn [apply_go].
      + destruct (term_cells s locals args) as [cells|] eqn:Hcells; [|lia].
        pose proof (D.unit_mono_make f cells db Hwf) as Hunit.
        destruct (D.make f cells db) as [i next] eqn:Hmake. cbn [snd] in Hunit.
        eapply Nat.le_trans; [exact Hunit|]. apply IH. intros pre suffix Hrest.
        pose proof (Hprefix (Make x f args :: pre) suffix
          ltac:(cbn [app]; now rewrite Hrest)) as Hstate.
        cbn [apply_go] in Hstate. rewrite Hcells, Hmake in Hstate. exact Hstate.
      + destruct (term_cells s locals args) as [cells|] eqn:Hcells; [|lia].
        destruct (result_cell s locals res) as [out|] eqn:Hout; [|lia].
        eapply Nat.le_trans with (m := D.unit (D.put f cells out db)).
        * apply D.unit_mono_put. exact Hwf.
        * apply IH. intros pre suffix Hrest.
          pose proof (Hprefix (Put f args res :: pre) suffix
            ltac:(cbn [app]; now rewrite Hrest)) as Hstate.
          cbn [apply_go] in Hstate. rewrite Hcells, Hout in Hstate. exact Hstate.
      + destruct (term_cell s locals t) as [ct|] eqn:Ht; [|lia].
        destruct (term_cell s locals u) as [cu|] eqn:Hu; [|destruct ct; cbn; lia].
        destruct ct as [i|v]; destruct cu as [j|w].
        * eapply Nat.le_trans with (m := D.unit (D.union i j db));
            [apply D.unit_mono_union; exact Hwf|].
          apply IH. intros pre suffix Hrest.
          pose proof (Hprefix (Union t u :: pre) suffix
            ltac:(cbn [app]; now rewrite Hrest)) as Hstate.
          cbn [apply_go] in Hstate. rewrite Ht, Hu in Hstate. exact Hstate.
        * apply IH. intros pre suffix Hrest.
          pose proof (Hprefix (Union t u :: pre) suffix
            ltac:(cbn [app]; now rewrite Hrest)) as Hstate.
          cbn [apply_go] in Hstate. rewrite Ht, Hu in Hstate. exact Hstate.
        * apply IH. intros pre suffix Hrest.
          pose proof (Hprefix (Union t u :: pre) suffix
            ltac:(cbn [app]; now rewrite Hrest)) as Hstate.
          cbn [apply_go] in Hstate. rewrite Ht, Hu in Hstate. exact Hstate.
        * apply IH. intros pre suffix Hrest.
          pose proof (Hprefix (Union t u :: pre) suffix
            ltac:(cbn [app]; now rewrite Hrest)) as Hstate.
          cbn [apply_go] in Hstate. rewrite Ht, Hu in Hstate. exact Hstate.
      + destruct (term_values s locals args) as [values|] eqn:Hvalues; [|lia].
        destruct (V.prim op values) as [v|] eqn:Hprim; [|lia].
        apply IH. intros pre suffix Hrest.
        pose proof (Hprefix (Let x op args :: pre) suffix
          ltac:(cbn [app]; now rewrite Hrest)) as Hstate.
        cbn [apply_go] in Hstate. rewrite Hvalues, Hprim in Hstate. exact Hstate.
  Qed.

  (** The functional action invariant supplies the well-formed prefixes for unit monotonicity. *)
  Lemma run_apply_go_typed_unit : forall p cp acts g s locals db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    D.unit db <= D.unit (apply_go acts s locals db).
  Proof.
    intros p cp acts g s locals db Hchecked Hwf Hloaded Hacts Henv Hallocated.
    apply run_apply_go_unit. intros pre suffix Hsplit.
    assert (Hpre : actions_ok (program_sorts p) (program_kind p) g pre).
    { eapply run_actions_ok_prefix with (suffix := suffix). now rewrite <- Hsplit. }
    exact (proj1 (run_apply_go_typed p cp pre g s locals db Hchecked Hwf Hloaded
      Hpre Henv Hallocated)).
  Qed.

  Lemma apply_wf : forall p cp r s db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    In r (rules V.t p) -> rule_env (program_sorts p) (program_kind p) r s ->
    env_allocated db s ->
    D.wf (apply (actions V.t r) s db) /\ loaded p cp (apply (actions V.t r) s db) /\
    (D.ids db <= D.ids (apply (actions V.t r) s db))%N /\
    D.unit db <= D.unit (apply (actions V.t r) s db).
  Proof.
    intros p cp r s db Hchecked Hwf Hloaded Hin Henv Hallocated.
    destruct (run_apply_state p cp r s db Hchecked Hwf Hloaded Hin Henv Hallocated)
      as [Hwf' [Hloaded' [Hids Hpending]]].
    split; [exact Hwf'|]. split; [exact Hloaded'|]. split; [exact Hids|].
    destruct (run_rule_context p cp r s Hchecked Hin Henv) as [g [_ [Hacts Hsorted]]].
    unfold apply. eapply run_apply_go_typed_unit; try eassumption.
    - intros x ty Hctx. destruct (Hsorted x ty Hctx) as [c [Hc Hty]].
      exists c. rewrite run_look_empty. split; assumption.
    - intros x i Hcell. rewrite run_look_empty in Hcell. eapply Hallocated. exact Hcell.
  Qed.

  Lemma apply_derives : forall p cp initial db r s,
    plans_ok p cp -> D.wf db -> loaded p cp db -> relational_fragment p = true ->
    no_ids db -> derived p initial db -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s -> env_allocated db s ->
    derivation_body V.prim p (D.view initial) s (query V.t r) ->
    no_ids (apply (actions V.t r) s db) /\ derived p initial (apply (actions V.t r) s db).
  Proof.
    exact run_apply_derives_checked.
  Qed.

  Lemma herbrand_universe_length : forall p db,
    relational_fragment p = true -> prim_free p = true ->
    herbrand p db = length (universe p db) /\ NoDup (universe p db).
  Proof.
    intros p db _ _. split; [reflexivity|apply run_universe_nodup].
  Qed.

  Lemma unit_scale : forall (T C P P' : N) (u U : nat), 1 <= u -> u <= U ->
    (T + N.of_nat u * P' <= N.of_nat u * (C + P))%N ->
    (T + N.of_nat U * P' <= N.of_nat U * (C + P))%N.
  Proof.
    intros T C P P' u U Hu HuU Hbound.
    assert (HuN : (1 <= N.of_nat u)%N) by lia.
    assert (HuUN : (N.of_nat u <= N.of_nat U)%N) by lia.
    assert (Hpotential : (P' <= C + P)%N) by nia.
    pose proof (N.mul_le_mono_l P' (C + P) (N.of_nat U - N.of_nat u) Hpotential)
      as Hextra.
    nia.
  Qed.

  Lemma unit_pos : forall db, 1 <= D.unit db.
  Proof.
    intro db. unfold D.unit. nia.
  Qed.

  (** Applying saved typed jobs never lowers the database's spending unit. *)
  Lemma run_apply_jobs_unit : forall p cp original js db,
    plans_ok p cp -> Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    D.unit db <= D.unit (apply_jobs p js db).
  Proof.
    intros p cp original js. induction js as [|[c b] rest IH]; intros db
      Hchecked Hjobs Hwf Hloaded Hids; [cbn [apply_jobs]; lia|].
    inversion Hjobs as [|job remaining Hjob Hrest]; subst job remaining.
    destruct Hjob as [Hrule [Henv [Hallocated Hmatch]]].
    destruct (run_job_environment p original db c b Hids Henv Hallocated)
      as [Htyped Hallocated_now].
    destruct (apply_wf p cp (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) db Hchecked Hwf Hloaded Hrule
      Htyped Hallocated_now) as [Hnext [Hloadnext [Hidnext Hunit]]].
    cbn [apply_jobs]. eapply Nat.le_trans; [exact Hunit|].
    eapply IH; [exact Hchecked|exact Hrest|exact Hnext|exact Hloadnext|].
    eapply N.le_trans; eassumption.
  Qed.

  Lemma round_monotone : forall p cp nv db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    D.wf (round p cp nv db) /\ loaded p cp (round p cp nv db) /\
    (D.ids db <= D.ids (round p cp nv db))%N /\ D.unit db <= D.unit (round p cp nv db).
  Proof.
    intros p cp nv db Hchecked Hwf Hloaded.
    destruct (run_round_state p cp nv db Hchecked Hwf Hloaded)
      as [Hnext [Hloadnext Hids]].
    split; [exact Hnext|]. split; [exact Hloadnext|]. split; [exact Hids|].
    pose proof (run_jobs_facts p cp nv db Hchecked Hwf Hloaded) as Hjobs.
    destruct (run_advance_state p cp db Hwf Hloaded) as [Hadvanced [Hloadadvanced Hadvanceids]].
    assert (Hadvance : (D.ids db <= D.ids (D.advance db))%N) by (rewrite Hadvanceids; lia).
    pose proof (run_apply_jobs_unit p cp db (jobs p cp nv db) (D.advance db)
      Hchecked Hjobs Hadvanced Hloadadvanced Hadvance) as Hunit.
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db)
      Hchecked Hjobs Hadvanced Hloadadvanced Hadvance) as [Happlied Hstate].
    assert (Hunitadvance : D.unit (D.advance db) = D.unit db).
    { unfold D.unit. rewrite Hadvanceids, (proj1 (D.advance_credit 0 db Hwf)).
      reflexivity. }
    rewrite Hunitadvance in Hunit. rewrite round_eq_jobs.
    eapply Nat.le_trans; [exact Hunit|]. apply D.unit_mono_rebuild. exact Happlied.
  Qed.


  Lemma round_work_def : forall p cp nv db,
    round_work p cp nv db =
      length (Syntax.slots V.t cp) +
      fold_right Nat.add 0 (map (fun c =>
        (J.work (join V.t c) (map (source_index db) (sources V.t c)) +
          length (sources V.t c) + source_bits c + 2) *
          (nvars (join V.t c) + 1) * (nvars (join V.t c) + 1) +
        length (bindings cp c db) *
          (fold_right (fun x n => (Pos.size_nat x + 1 + n)%nat) 0%nat (var_of V.t c) +
           post_work p c + rule_work p c + 1 +
           fold_right (fun a n => match a with
             | Make _ f args | Put f args _ =>
                 (length args + 2) * (length args + 2) *
                   (length (filter (fun sl => Pos.eqb (fst sl) f) (Syntax.slots V.t cp)) + 1)
                 + n
             | Union _ _ => 1 + n
             | Let _ _ args => length args + 1 + n
             end) 0 (actions V.t (nth (N.to_nat (rule_ix V.t c)) (rules V.t p)
               (Rule V.t [] [])))) +
        fold_right Nat.add 0 (map (fun binding =>
          let r := nth (N.to_nat (rule_ix V.t c)) (rules V.t p) (Rule V.t [] []) in
          N.to_nat (query_prim_work V.prim_work (query V.t r) (env_of c binding) +
            action_prim_work V.prim V.prim_work (program_kind p) (actions V.t r)
              (env_of c binding))%N)
          (bindings cp c db)))
        (if nv then naive V.t cp else seminaive V.t cp)).
  Proof.
    reflexivity.
  Qed.

  Lemma T_check_plan_split : forall p cp,
    (T_check_plan p cp <= T_check_program p + T_check_shape p cp + k_check)%N.
  Proof.
    intros p cp.
    assert (Hconstant : (2 <= k_check)%N) by (unfold k_check; lia).
    time_unfold T_check_plan.
    pose proof (Datatypes.T_andb_le (check_program p) (check_shape p cp)) as Hand.
    lia.
  Qed.

  (** Set bits pay for carry propagation in a binary counter. *)
  Fixpoint run_positive_credit (p : positive) : N :=
    match p with
    | xH => 1%N
    | xO q => run_positive_credit q
    | xI q => (1 + run_positive_credit q)%N
    end.

  Definition run_counter_credit (n : N) : N :=
    match n with
    | N0 => 0%N
    | Npos p => run_positive_credit p
    end.

  Lemma run_positive_succ_amort : forall p,
    (Pos.T_succ p + run_positive_credit (Pos.succ p) <=
      2 + run_positive_credit p)%N.
  Proof.
    intro p. induction p as [p IH | p IH |]; time_unfold Pos.T_succ;
      cbn [Pos.succ run_positive_credit]; lia.
  Qed.

  Lemma run_counter_succ_amort : forall n,
    (N.T_succ n + run_counter_credit (N.succ n) <=
      3 + run_counter_credit n)%N.
  Proof.
    intros [| p]; time_unfold N.T_succ; cbn [N.succ run_counter_credit].
    - cbn [run_positive_credit]. lia.
    - pose proof (run_positive_succ_amort p). lia.
  Qed.

  (** The checker converts unary positions to their binary values. *)
  Lemma run_nat_n_spec : forall n, nat_n n = N.of_nat n.
  Proof.
    induction n as [| n IH].
    - reflexivity.
    - cbn [nat_n]. rewrite IH, Nat2N.inj_succ. reflexivity.
  Qed.

  (** The carries of unary-to-binary conversion have a linear total charge. *)
  Lemma run_nat_n_amort : forall n,
    (T_nat_n n + run_counter_credit (nat_n n) <= 4 * N.of_nat n + 1)%N.
  Proof.
    induction n as [| n IH].
    - time_unfold T_nat_n. cbn [nat_n run_counter_credit]. lia.
    - pose proof (run_counter_succ_amort (nat_n n)) as Hstep.
      time_unfold T_nat_n. cbn [nat_n]. lia.
  Qed.

  Lemma run_nat_n_time : forall n, (T_nat_n n <= 4 * N.of_nat n + 1)%N.
  Proof.
    intro n. pose proof (run_nat_n_amort n). lia.
  Qed.

  (** Unary comparisons stop when their right operand stops. *)
  Lemma run_nat_eqb_right : forall i j,
    (Nat.T_eqb i j <= N.of_nat j + 1)%N.
  Proof.
    intro i. induction i as [| i IH]; intros [| j]; time_step.
  Qed.

  Lemma run_nat_leb_right : forall i j,
    (Nat.T_leb i j <= N.of_nat j + 1)%N.
  Proof.
    intro i. induction i as [| i IH]; intros [| j]; time_step.
  Qed.

  Lemma run_positive_eqb_right : forall p q,
    (Pos.T_eqb p q <= N.of_nat (Pos.size_nat q))%N.
  Proof.
    intro p. induction p as [p IH | p IH |]; intros [q | q |]; time_step.
  Qed.

  Lemma run_counter_eqb_right : forall n m,
    (N.T_eqb n m <= N.of_nat (N.size_nat m) + 1)%N.
  Proof.
    intros [| p] [| q]; time_unfold N.T_eqb; cbn [N.size_nat]; try lia.
    pose proof (run_positive_eqb_right p q). lia.
  Qed.

  (** Comparing position lists can be charged to the right list alone. *)
  Lemma run_nats_eqb_time : forall a b,
    (T_nats_eqb a b <= 2 * N.of_nat (run_positions_size b) + 1)%N.
  Proof.
    induction a as [| i a IH]; intros [| j b].
    - time_unfold T_nats_eqb. change (1 <= 2 * N.of_nat 0 + 1)%N. lia.
    - time_unfold T_nats_eqb. lia.
    - time_unfold T_nats_eqb. change (1 <= 2 * N.of_nat 0 + 1)%N. lia.
    - pose proof (run_nat_eqb_right i j) as Hcompare.
      pose proof (IH b) as Htail. time_unfold T_nats_eqb.
      destruct (Nat.eqb i j); time_cbn;
        change (run_positions_size (j :: b)) with (j + 1 + run_positions_size b);
        fold (run_positions_size b); lia.
  Qed.

  (** A slot check charges its input key and the supplied source number. *)
  Lemma run_slot_matches_time : forall table f positions slot,
    (T_slot_matches table f positions slot <=
      32 * N.of_nat (Pos.size_nat f + run_positions_size positions + N.size_nat slot + 1))%N.
  Proof.
    intros table f positions slot.
    pose proof (run_slot_code_time f positions) as Hcode.
    pose proof (run_slot_code_bits f positions) as Hbits.
    time_unfold T_slot_matches. PTrieT.trie_get_le.
    destruct (trie_get (slot_code f positions) table) as [[slot' [f' positions']] |].
    - pose proof (run_counter_eqb_right slot' slot) as Hslot.
      pose proof (run_positive_eqb_right f' f) as Hname.
      pose proof (run_nats_eqb_time positions' positions) as Hpositions.
      destruct (N.eqb slot' slot); destruct (Pos.eqb f' f); time_cbn; lia.
    - time_cbn. lia.
  Qed.

  Lemma run_source_slot_time : forall newok (src : source V.t),
    (T_source_slot newok src <= 3)%N.
  Proof.
    intros newok src. destruct src; destruct newok; time_unfold @T_source_slot; time_cbn; lia.
  Qed.

  (** Column ordering and range tests charge each unary position a constant number of times. *)
  Lemma run_column_ok_time : forall n positions prev,
    (T_column_ok n positions prev <=
      8 * N.of_nat (run_positions_size positions) + 1)%N.
  Proof.
    intros n positions. induction positions as [| i positions IH]; intro prev.
    - destruct prev; time_unfold T_column_ok; change (1 <= 8 * N.of_nat 0 + 1)%N; lia.
    - pose proof (Nat.T_leb_le (S i) n) as Hrange.
      pose proof (IH (Some i)) as Htail.
      time_unfold T_column_ok.
      change (run_positions_size (i :: positions)) with
        (i + 1 + run_positions_size positions).
      destruct prev as [p |].
      + pose proof (run_nat_leb_right (S p) i) as Habove.
        destruct (Nat.leb (S p) i); destruct (Nat.leb (S i) n); time_cbn; lia.
      + destruct (Nat.leb (S i) n); time_cbn; lia.
  Qed.

  (** Validating a permutation charges its stored unary positions. *)
  Lemma run_perm_ok_time : forall width positions seen,
    (T_perm_ok width positions seen <=
      16 * (PTrieT.c_trie + 1) * N.of_nat (run_positions_size positions + 1))%N.
  Proof.
    intros width positions. induction positions as [| i positions IH]; intro seen.
    - time_unfold T_perm_ok.
      change (1 <= 16 * (PTrieT.c_trie + 1) * N.of_nat (0 + 1))%N. nia.
    - pose proof (run_nat_code_time i) as Hcode.
      pose proof (Nat.T_leb_le (S i) width) as Hrange.
      pose proof (PTrieT.T_set_le unit (nat_code i) tt seen) as Hset.
      rewrite run_nat_code_bits in Hset.
      pose proof (IH (PTrieCode.set (nat_code i) tt seen)) as Htail.
      pose proof (PTrieT.T_trie_get_le unit (nat_code i) seen) as Hget.
      rewrite run_nat_code_bits in Hget.
      time_unfold T_perm_ok.
      change (run_positions_size (i :: positions)) with
        (i + 1 + run_positions_size positions).
      destruct (trie_get (nat_code i) seen); destruct (Nat.leb (S i) width);
        time_cbn; nia.
  Qed.

  Definition run_vars_size (vars : list positive) : nat :=
    fold_right (fun x n => Pos.size_nat x + 1 + n) 0 vars.

  (** Name validation pays the name bits and amortized ordinal increments. *)
  Lemma run_var_table_time : forall vars j table,
    (T_var_table vars j table <=
      16 * (PTrieT.c_trie + 1) * N.of_nat (run_vars_size vars + 1) +
      run_counter_credit j)%N.
  Proof.
    induction vars as [| x vars IH]; intros j table.
    - time_unfold T_var_table.
      change (1 <= 16 * (PTrieT.c_trie + 1) * N.of_nat (0 + 1) +
        run_counter_credit j)%N. nia.
    - pose proof (run_counter_succ_amort j) as Hstep.
      pose proof (PTrieT.T_set_le N x j table) as Hset.
      pose proof (IH (N.succ j) (PTrieCode.set x j table)) as Htail.
      time_unfold T_var_table. PTrieT.trie_get_le.
      change (run_vars_size (x :: vars)) with (Pos.size_nat x + 1 + run_vars_size vars).
      destruct (trie_get x table); time_cbn; nia.
  Qed.

  (** Declaration widths read each name and its list of argument sorts once. *)
  Lemma run_decl_widths_time : forall ds table,
    (T_decl_widths ds table <= 16 * (PTrieT.c_trie + 1) *
      N.of_nat (fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds + 1))%N.
  Proof.
    induction ds as [| [f ss out] ds IH]; intro table.
    - time_unfold T_decl_widths. cbn [fold_right]. nia.
    - pose proof (Datatypes.T_length_le ss) as Hlength.
      pose proof (PTrieT.T_set_le nat f (length ss) table) as Hrelset.
      pose proof (PTrieT.T_set_le nat f (S (length ss)) table) as Hfunset.
      pose proof (IH table) as Hkeep.
      pose proof (IH (PTrieCode.set f (length ss) table)) as Hrel.
      pose proof (IH (PTrieCode.set f (S (length ss)) table)) as Hfun.
      change (fold_right (fun d n => decl_bits d + n) 0 (Decl f ss out :: ds)) with
        (Pos.size_nat f + length ss + 1 + fold_right (fun d n => decl_bits d + n) 0 ds).
      time_unfold T_decl_widths. PTrieT.trie_get_le.
      destruct (trie_get f table); destruct out; time_cbn; nia.
  Qed.

  Definition run_slot_syntax_size (sl : list (positive * list nat)) : nat :=
    fold_right (fun slot n =>
      Pos.size_nat (fst slot) + run_positions_size (snd slot) + 1 + n) 0 sl.

  (** Slot validation pays the stored names and unary permutation positions. *)
  Lemma run_slot_table_time : forall widths sl next table,
    (T_slot_table widths sl next table <= 128 * (PTrieT.c_trie + 1) *
      N.of_nat (run_slot_syntax_size sl + 1) + run_counter_credit next)%N.
  Proof.
    intros widths sl. induction sl as [| [f perm] sl IH]; intros next table.
    - time_unfold T_slot_table. change
        (1 <= 128 * (PTrieT.c_trie + 1) * N.of_nat (0 + 1) +
          run_counter_credit next)%N. nia.
    - pose proof (run_counter_succ_amort next) as Hnext.
      pose proof (run_slot_code_time f perm) as Hcode.
      pose proof (run_slot_code_bits f perm) as Hbits.
      pose proof (PTrieT.T_set_le (N * (positive * list nat))
        (slot_code f perm) (next, (f, perm)) table) as Hset.
      change (PTrieCode.T_set (slot_code f perm) (next, (f, perm)) table <=
        PTrieT.c_trie * N.of_nat (Pos.size_nat (slot_code f perm) + 1))%N in Hset.
      assert (Hset_bound : (PTrieCode.T_set (slot_code f perm) (next, (f, perm)) table <=
        3 * (PTrieT.c_trie + 1) *
          N.of_nat (Pos.size_nat f + run_positions_size perm + 1))%N).
      { clear -Hbits Hset. nia. }
      clear Hset.
      assert (Hbudget :
        (1 + 2 * N.of_nat (Pos.size_nat f) +
          16 * (PTrieT.c_trie + 1) * N.of_nat (run_positions_size perm + 1) +
          8 * N.of_nat (Pos.size_nat f + run_positions_size perm + 1) +
          2 * N.of_nat (Pos.size_nat (slot_code f perm)) + 3 +
          3 * (PTrieT.c_trie + 1) * N.of_nat (Pos.size_nat f + run_positions_size perm + 1) +
          128 * (PTrieT.c_trie + 1) * N.of_nat (run_slot_syntax_size sl + 1) <=
          128 * (PTrieT.c_trie + 1) *
            N.of_nat (Pos.size_nat f + run_positions_size perm + 1 + run_slot_syntax_size sl + 1))%N).
      { clear -Hbits. nia. }
      pose proof (IH (N.succ next) table) as Hkeep.
      pose proof (IH (N.succ next)
        (PTrieCode.set (slot_code f perm) (next, (f, perm)) table)) as Hnew.
      change (run_slot_syntax_size ((f, perm) :: sl)) with
        (Pos.size_nat f + run_positions_size perm + 1 + run_slot_syntax_size sl).
      time_unfold T_slot_table. PTrieT.trie_get_le.
      destruct (trie_get f widths) as [width |].
      + pose proof (run_perm_ok_time width perm Empty) as Hperm.
        destruct (perm_ok width perm Empty);
          destruct (trie_get (slot_code f perm) table); time_cbn;
          fold (run_slot_syntax_size sl) (run_positions_size perm); lia.
      + time_cbn. fold (run_slot_syntax_size sl) (run_positions_size perm). lia.
  Qed.

  (** Binary widths have a quadratic bound in their unary values. *)
  Lemma run_positive_bits_value : forall p, Pos.size_nat p <= Pos.to_nat p.
  Proof.
    intro p. induction p as [p IH | p IH |]; cbn [Pos.size_nat].
    - rewrite Pos2Nat.inj_xI. lia.
    - rewrite Pos2Nat.inj_xO. pose proof (Pos2Nat.is_pos p). lia.
    - reflexivity.
  Qed.

  Lemma run_positive_bits_square : forall p,
    Pos.size_nat p * Pos.size_nat p <= 3 * Pos.to_nat p.
  Proof.
    intro p. induction p as [p IH | p IH |]; cbn [Pos.size_nat].
    - rewrite Pos2Nat.inj_xI. pose proof (run_positive_bits_value p).
      pose proof (Pos2Nat.is_pos p). nia.
    - rewrite Pos2Nat.inj_xO. pose proof (run_positive_bits_value p).
      pose proof (Pos2Nat.is_pos p). nia.
    - cbn [Pos.to_nat]. lia.
  Qed.

  Lemma run_counter_bits_value : forall n, N.size_nat n <= N.to_nat n.
  Proof.
    intros [| p]; [reflexivity | apply run_positive_bits_value].
  Qed.

  Lemma run_positive_succ_bits : forall p,
    Pos.size_nat p <= Pos.size_nat (Pos.succ p).
  Proof.
    intro p. induction p as [p IH | p IH |]; cbn [Pos.size_nat Pos.succ]; lia.
  Qed.

  Lemma run_counter_key_bits_lower : forall n,
    N.size_nat n <= Pos.size_nat (N.succ_pos n).
  Proof.
    intros [| p]; [cbn; lia | apply run_positive_succ_bits].
  Qed.

  Lemma run_counter_key_value : forall n,
    Pos.to_nat (N.succ_pos n) = N.to_nat n + 1.
  Proof.
    intro n. pose proof (f_equal N.to_nat (N.succ_pos_spec n)) as H.
    rewrite N2Nat.inj_succ in H. cbn [N.to_nat] in H. lia.
  Qed.

  Lemma run_position_key_value : forall n,
    Pos.to_nat (N.succ_pos (nat_n n)) = n + 1.
  Proof.
    intro n. rewrite run_counter_key_value, run_nat_n_spec, Nat2N.id. reflexivity.
  Qed.

  Lemma run_position_key_inj : forall n m,
    N.succ_pos (nat_n n) = N.succ_pos (nat_n m) -> n = m.
  Proof.
    intros n m H. apply (f_equal Pos.to_nat) in H.
    rewrite !run_position_key_value in H. lia.
  Qed.

  (** The distinct-variable counter retains the credit released by its carries. *)
  Lemma run_column_perm_time : forall inv positions used count,
    (T_column_perm inv positions used count +
      match column_perm inv positions used count with
      | Some (_, _, count') => run_counter_credit count'
      | None => 0
      end <=
      64 * (PTrieT.c_trie + 1) * N.of_nat (run_positions_size positions + 1) +
      run_counter_credit count)%N.
  Proof.
    intros inv positions. induction positions as [| i positions IH]; intros used count.
    - time_unfold T_column_perm. cbn [column_perm].
      change (1 + run_counter_credit count <=
        64 * (PTrieT.c_trie + 1) * N.of_nat (0 + 1) + run_counter_credit count)%N.
      nia.
    - pose proof (run_nat_n_time i) as Hnat.
      pose proof (N.T_succ_pos_le (nat_n i)) as Hcode.
      pose proof (run_counter_bits_value (nat_n i)) as Hvalue.
      assert (Hnatvalue : N.to_nat (nat_n i) = i) by
        (rewrite run_nat_n_spec, Nat2N.id; reflexivity).
      rewrite Hnatvalue in Hvalue.
      pose proof (run_positive_bits_value (N.succ_pos (nat_n i))) as Hbits.
      rewrite run_position_key_value in Hbits.
      pose proof (PTrieT.T_set_le unit (N.succ_pos (nat_n i)) tt used) as Hset.
      assert (Hset_bound : (PTrieCode.T_set (N.succ_pos (nat_n i)) tt used <=
        PTrieT.c_trie * N.of_nat (i + 2))%N).
      { change (PTrieCode.T_set (N.succ_pos (nat_n i)) tt used <=
          PTrieT.c_trie * N.of_nat (Pos.size_nat (N.succ_pos (nat_n i)) + 1))%N in Hset.
        clear -Hset Hbits. nia. }
      clear Hset.
      assert (Hbudget :
        (1 + (4 * N.of_nat i + 1) + (N.of_nat i + 1) + 4 * N.of_nat (i + 1) +
          PTrieT.c_trie * N.of_nat (i + 2) + 3 +
          64 * (PTrieT.c_trie + 1) * N.of_nat (run_positions_size positions + 1) <=
          64 * (PTrieT.c_trie + 1) * N.of_nat (i + 1 + run_positions_size positions + 1))%N).
      { clear. nia. }
      pose proof (run_counter_succ_amort count) as Hcount.
      pose proof (IH (PTrieCode.set (N.succ_pos (nat_n i)) tt used) count) as Hkeep.
      pose proof (IH (PTrieCode.set (N.succ_pos (nat_n i)) tt used) (N.succ count)) as Hnew.
      change (run_positions_size (i :: positions)) with
        (i + 1 + run_positions_size positions).
      time_unfold T_column_perm. PTrieT.trie_get_le.
      cbn [column_perm].
      destruct (trie_get (N.succ_pos (nat_n i)) inv) as [pos |];
        [| time_cbn; fold (run_positions_size positions); lia].
      destruct (trie_get (N.succ_pos (nat_n i)) used).
      + clear Hnew Hcount. destruct (column_perm inv positions
          (PTrieCode.set (N.succ_pos (nat_n i)) tt used) count)
          as [[ [perm used'] count'] |]; time_cbn;
          fold (run_positions_size positions); lia.
      + clear Hkeep. destruct (column_perm inv positions
          (PTrieCode.set (N.succ_pos (nat_n i)) tt used) (N.succ count))
          as [[ [perm used'] count'] |]; time_cbn;
          fold (run_positions_size positions); lia.
  Qed.

  Lemma run_width_product : forall m p,
    m * Pos.size_nat p <= m * m + 3 * Pos.to_nat p.
  Proof.
    intros m p. pose proof (run_positive_bits_square p) as Hsquare.
    assert (Horder : m <= Pos.size_nat p \/ Pos.size_nat p <= m) by lia.
    destruct Horder; nia.
  Qed.

  (** A rising column gives the lower bound for its next position. *)
  Fixpoint run_rising (lower : nat) (positions : list nat) : Prop :=
    match positions with
    | [] => True
    | i :: rest => lower <= i /\ run_rising (S i) rest
    end.

  Lemma run_rising_lower : forall positions lower i,
    run_rising lower positions -> In i positions -> lower <= i.
  Proof.
    induction positions as [| j positions IH]; intros lower i Hrise Hin.
    - contradiction.
    - cbn [run_rising] in Hrise. destruct Hrise as [Hlower Htail].
      destruct Hin as [<- | Hin]; [exact Hlower |].
      pose proof (IH (S j) i Htail Hin). lia.
  Qed.

  Lemma run_rising_nodup : forall positions lower,
    run_rising lower positions -> NoDup positions.
  Proof.
    induction positions as [| i positions IH]; intros lower Hrise.
    - constructor.
    - cbn [run_rising] in Hrise. destruct Hrise as [Hlower Htail].
      constructor.
      + intro Hin. pose proof (run_rising_lower positions (S i) i Htail Hin). lia.
      + now apply (IH (S i)).
  Qed.

  Lemma run_rising_size : forall positions lower,
    run_rising lower positions ->
    length positions * (length positions + 2 * lower + 1) <=
      2 * run_positions_size positions.
  Proof.
    induction positions as [| i positions IH]; intros lower Hrise.
    - change (0 <= 0). lia.
    - cbn [run_rising] in Hrise. destruct Hrise as [Hlower Htail].
      pose proof (IH (S i) Htail) as Hsize.
      change (run_positions_size (i :: positions)) with
        (i + 1 + run_positions_size positions).
      cbn [length]. nia.
  Qed.

  Lemma run_column_ok_rising : forall n positions prev,
    column_ok n positions prev = true ->
    run_rising (match prev with None => 0 | Some p => S p end) positions.
  Proof.
    intros n positions. induction positions as [| i positions IH]; intros prev Hcheck.
    - exact I.
    - destruct prev as [p |]; cbn [column_ok] in Hcheck.
      + destruct (Nat.leb (S p) i) eqn:Habove; [| discriminate].
        destruct (Nat.leb (S i) n) eqn:Hrange; [| discriminate].
        cbn [run_rising]. split.
        * now apply Nat.leb_le.
        * now apply (IH (Some i)).
      + destruct (Nat.leb (S i) n) eqn:Hrange; [| discriminate].
        cbn [run_rising]. split; [lia |]. now apply (IH (Some i)).
  Qed.

  Lemma run_column_ok_nodup : forall n positions,
    column_ok n positions None = true -> NoDup positions.
  Proof.
    intros n positions H. apply (run_rising_nodup positions 0).
    exact (run_column_ok_rising n positions None H).
  Qed.

  Lemma run_column_ok_quadratic : forall n positions,
    column_ok n positions None = true ->
    length positions * length positions <= 2 * run_positions_size positions.
  Proof.
    intros n positions H. pose proof (run_column_ok_rising n positions None H) as Hrising.
    pose proof (run_rising_size positions 0 Hrising). nia.
  Qed.

  (** Every accepted column key was found in the inverse table. *)
  Lemma run_column_perm_domain : forall inv positions used count perm used' count',
    column_perm inv positions used count = Some (perm, used', count') ->
    forall i, In i positions -> exists pos,
      trie_get (N.succ_pos (nat_n i)) inv = Some pos.
  Proof.
    intros inv positions. induction positions as [| i positions IH];
      intros used count perm used' count' Hcheck j Hin.
    - contradiction.
    - cbn [column_perm] in Hcheck.
      destruct (trie_get (N.succ_pos (nat_n i)) inv) as [pos |] eqn:Hget;
        [| discriminate].
      destruct (column_perm inv positions
        (PTrieCode.set (N.succ_pos (nat_n i)) tt used)
        (match trie_get (N.succ_pos (nat_n i)) used with
         | Some _ => count | None => N.succ count end))
        as [[ [perm1 used1] count1] |] eqn:Htail; [| discriminate].
      destruct Hin as [<- | Hin].
      + now exists pos.
      + eapply IH; eauto.
  Qed.

  Lemma run_trie_set_domain : forall A (inv : ptrie A) key value q result,
    trie_get q (PTrieCode.set key value inv) = Some result ->
    q = key \/ trie_get q inv = Some result.
  Proof.
    intros A inv key value q result Hget. destruct (Pos.eq_dec q key) as [Heq | Hneq].
    - now left.
    - right. rewrite PTrie.get_set_other in Hget by exact Hneq. exact Hget.
  Qed.

  Lemma run_trie_domain_cons : forall (inv inv' : ptrie nat) key value keys,
    (forall q pos, trie_get q inv' = Some pos ->
      In q keys \/ exists old, trie_get q (PTrieCode.set key value inv) = Some old) ->
    forall q pos, trie_get q inv' = Some pos ->
      In q (key :: keys) \/ exists old, trie_get q inv = Some old.
  Proof.
    intros inv inv' key value keys Hdomain q pos Hget.
    destruct (Hdomain q pos Hget) as [Hin | [old Hold]].
    - left. now right.
    - destruct (run_trie_set_domain nat inv key value q old Hold) as [Heq | Hprevious].
      + left. now left.
      + right. now exists old.
  Qed.

  Lemma run_position_keys_nodup : forall positions,
    NoDup positions -> NoDup (map (fun i => N.succ_pos (nat_n i)) positions).
  Proof.
    intros positions Hnodup. induction Hnodup as [| i positions Hnotin Hnodup IH].
    - constructor.
    - cbn [map]. constructor; [| exact IH].
      intro Hin. apply in_map_iff in Hin. destruct Hin as [j [Heq Hin]].
      apply run_position_key_inj in Heq. subst j. contradiction.
  Qed.

  (** Equal-length distinct column keys account for the complete insertion list. *)
  Lemma run_inverse_keys_permutation : forall inv positions keys n used count perm used' count',
    column_ok n positions None = true ->
    length keys = length positions ->
    (forall key pos, trie_get key inv = Some pos -> In key keys) ->
    column_perm inv positions used count = Some (perm, used', count') ->
    Permutation keys (map (fun i => N.succ_pos (nat_n i)) positions).
  Proof.
    intros inv positions keys n used count perm used' count'
      Hcolumn Hlength Hdomain Hperm.
    apply Permutation_sym. apply NoDup_Permutation_bis.
    - apply run_position_keys_nodup. now apply (run_column_ok_nodup n).
    - rewrite length_map. lia.
    - intros key Hin. apply in_map_iff in Hin. destruct Hin as [i [<- Hin]].
      destruct (run_column_perm_domain inv positions used count perm used' count'
        Hperm i Hin) as [pos Hget].
      exact (Hdomain _ _ Hget).
  Qed.

  Definition run_key_size (keys : list positive) : nat :=
    fold_right (fun key n => Pos.size_nat key + 1 + n) 0 keys.

  Lemma run_key_size_permutation : forall keys keys',
    Permutation keys keys' -> run_key_size keys = run_key_size keys'.
  Proof.
    intros keys keys' Hperm. induction Hperm.
    - reflexivity.
    - change (run_key_size (x :: l)) with (Pos.size_nat x + 1 + run_key_size l).
      change (run_key_size (x :: l')) with (Pos.size_nat x + 1 + run_key_size l').
      lia.
    - change (run_key_size (y :: x :: l)) with
        (Pos.size_nat y + 1 + (Pos.size_nat x + 1 + run_key_size l)).
      change (run_key_size (x :: y :: l)) with
        (Pos.size_nat x + 1 + (Pos.size_nat y + 1 + run_key_size l)).
      lia.
    - lia.
  Qed.

  Lemma run_position_keys_size : forall positions,
    run_key_size (map (fun i => N.succ_pos (nat_n i)) positions) <=
      2 * run_positions_size positions.
  Proof.
    induction positions as [| i positions IH].
    - change (0 <= 0). lia.
    - pose proof (run_positive_bits_value (N.succ_pos (nat_n i))) as Hbits.
      rewrite run_position_key_value in Hbits.
      change (run_key_size (map (fun j => N.succ_pos (nat_n j)) (i :: positions))) with
        (Pos.size_nat (N.succ_pos (nat_n i)) + 1 +
          run_key_size (map (fun j => N.succ_pos (nat_n j)) positions)).
      change (run_positions_size (i :: positions)) with
        (i + 1 + run_positions_size positions). lia.
  Qed.

  Lemma run_inverse_keys_size : forall inv positions keys n used count perm used' count',
    column_ok n positions None = true ->
    length keys = length positions ->
    (forall key pos, trie_get key inv = Some pos -> In key keys) ->
    column_perm inv positions used count = Some (perm, used', count') ->
    run_key_size keys <= 2 * run_positions_size positions.
  Proof.
    intros inv positions keys n used count perm used' count' Hcolumn Hlength Hdomain Hperm.
    pose proof (run_inverse_keys_permutation inv positions keys n used count perm used' count'
      Hcolumn Hlength Hdomain Hperm) as Hkeys.
    rewrite (run_key_size_permutation keys _ Hkeys). apply run_position_keys_size.
  Qed.

  (** The public checker clock follows from a proved shape clock. *)
  Lemma run_check_plan_from_shape : forall p cp,
    (T_check_shape p cp <= k_check * N.of_nat (size_program p + size_compiled cp + 1) *
      N.of_nat (wbits p + 1))%N ->
    (T_check_plan p cp <= c_run * N.of_nat (size_program p + size_compiled cp + 1) *
      N.of_nat (wbits p + 1))%N.
  Proof.
    intros p cp Hshape.
    pose proof (T_check_plan_split p cp) as Hsplit.
    pose proof (Sorts.T_check_program_le V.t p) as Hprogram.
    change (T_check_program p <= c_sorts * N.of_nat (size_program p + 1))%N in Hprogram.
    assert (Hcoefficient : (c_sorts + 2 * k_check <= c_run)%N).
    { unfold c_sorts, k_check, c_run. lia. }
    set (text := N.of_nat (size_program p + size_compiled cp + 1)).
    set (width := N.of_nat (wbits p + 1)).
    assert (Htext : (1 <= text)%N) by (unfold text; lia).
    assert (Hwidth : (1 <= width)%N) by (unfold width; lia).
    assert (Hprogram_text : (N.of_nat (size_program p + 1) <= text)%N)
      by (unfold text; lia).
    assert (Hprogram_budget : (N.of_nat (size_program p + 1) <= text * width)%N) by nia.
    assert (Hone : (1 <= text * width)%N) by nia.
    assert (Htotal : (T_check_plan p cp <= (c_sorts + 2 * k_check) * (text * width))%N).
    { fold text width in Hshape. nia. }
    fold text width. nia.
  Qed.
  Definition run_sources_size (srcs : list (source V.t)) : nat :=
    fold_right (fun src m => match src with
      | All _ i | New _ i => N.size_nat i + 1 + m
      | Const _ value => cell_bits V.encode value + 1 + m
      end) 0 srcs.

  Definition run_columns_size (columns : list (list nat)) : nat :=
    fold_right (fun col m => run_positions_size col + 1 + m) 0 columns.

  Definition run_payload_size (srcs : list (source V.t)) (columns : list (list nat)) : nat :=
    run_sources_size srcs + run_columns_size columns.

  Definition run_check_term_width (width : nat) (t : term V.t) : Prop :=
    match t with
    | Var x => Pos.size_nat x <= width
    | Lit _ => True
    end.

  Lemma run_trie_set_time : forall A key (value : A) table,
    (PTrieCode.T_set key value table <=
      PTrieT.c_trie * N.of_nat (Pos.size_nat key + 1))%N.
  Proof.
    intros A key value table. apply PTrieT.T_set_le.
  Qed.

  (** Successful term checks retain the unused literal-source and column resources. *)
  Lemma run_check_terms_success_time : forall names ts width pos seen copy inv srcs columns
      copied copy' inv' srcs' columns' copied',
    Forall (run_check_term_width width) ts ->
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    exists keys,
      length keys = length ts /\
      (forall key position, trie_get key inv' = Some position ->
        In key keys \/ exists old, trie_get key inv = Some old) /\
      (T_check_terms V.eqb V.T_eqb names ts pos seen copy inv srcs columns copied +
        64 * (V.c_key + PTrieT.c_trie + 1) *
          N.of_nat ((width + 1) * run_payload_size srcs' columns') <=
       64 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat (length ts * (width + 1) + run_key_size keys +
          (width + 1) * run_payload_size srcs columns + 1))%N.
  Proof.
    intros names ts. induction ts as [| t ts IH];
      intros width pos seen copy inv srcs columns copied copy' inv' srcs' columns' copied'
        Hwidth Hcheck.
    - cbn [check_terms] in Hcheck. inversion Hcheck; subst.
      exists []. split; [reflexivity |]. split.
      + intros key position Hget. right. now exists position.
      + time_unfold @T_check_terms. change (run_key_size []) with 0.
        cbn [length]. nia.
    - inversion Hwidth as [| t0 ts0 Hterm Htail]; subst.
      destruct t as [x | value]; cbn [check_terms] in Hcheck.
      + cbn [run_check_term_width] in Hterm.
        destruct (trie_get x seen) as [present |] eqn:Hseen.
        * destruct (IH width (S pos) seen (N.succ copy)
            (PTrieCode.set (N.succ_pos copy) pos inv) srcs columns true
            copy' inv' srcs' columns' copied' Htail Hcheck)
            as [keys [Hlength [Hdomain Hclock]]].
          exists (N.succ_pos copy :: keys). split.
          -- cbn [length]. lia.
          -- split.
             ++ eapply run_trie_domain_cons. exact Hdomain.
             ++ assert (Hlocal :
                  (1 + 2 * N.of_nat (Pos.size_nat x) + N.T_succ copy +
                    N.T_succ_pos copy + PTrieCode.T_set (N.succ_pos copy) pos inv <=
                    64 * (V.c_key + PTrieT.c_trie + 1) *
                      N.of_nat (width + 1 + (Pos.size_nat (N.succ_pos copy) + 1)))%N).
                { pose proof (run_trie_set_time nat (N.succ_pos copy) pos inv) as Hset.
                  pose proof (N.T_succ_le copy) as Hsucc.
                  pose proof (N.T_succ_pos_le copy) as Hcode.
                  pose proof (run_counter_key_bits_lower copy) as Hbits.
                  clear -Hterm Hset Hsucc Hcode Hbits. nia. }
                time_unfold @T_check_terms. rewrite Hseen. PTrieT.trie_get_le.
                change (run_key_size (N.succ_pos copy :: keys)) with
                  (Pos.size_nat (N.succ_pos copy) + 1 + run_key_size keys).
                cbn [length]. clear -Hclock Hlocal. PTrieT.trie_get_le. nia.
        * destruct (trie_get x names) as [ordinal |] eqn:Hname; [| discriminate].
          destruct (IH width (S pos) (PTrieCode.set x tt seen) copy
            (PTrieCode.set (N.succ_pos ordinal) pos inv) srcs columns copied
            copy' inv' srcs' columns' copied' Htail Hcheck)
            as [keys [Hlength [Hdomain Hclock]]].
          exists (N.succ_pos ordinal :: keys). split.
          -- cbn [length]. lia.
          -- split.
             ++ eapply run_trie_domain_cons. exact Hdomain.
             ++ assert (Hlocal :
                  (1 + 4 * N.of_nat (Pos.size_nat x) + PTrieCode.T_set x tt seen +
                    N.T_succ_pos ordinal + PTrieCode.T_set (N.succ_pos ordinal) pos inv <=
                    64 * (V.c_key + PTrieT.c_trie + 1) *
                      N.of_nat (width + 1 + (Pos.size_nat (N.succ_pos ordinal) + 1)))%N).
                { pose proof (run_trie_set_time unit x tt seen) as Hseen_set.
                  pose proof (run_trie_set_time nat (N.succ_pos ordinal) pos inv) as Hset.
                  pose proof (N.T_succ_pos_le ordinal) as Hcode.
                  pose proof (run_counter_key_bits_lower ordinal) as Hbits.
                  clear -Hterm Hseen_set Hset Hcode Hbits. nia. }
                time_unfold @T_check_terms. rewrite Hseen, Hname. PTrieT.trie_get_le.
                change (run_key_size (N.succ_pos ordinal :: keys)) with
                  (Pos.size_nat (N.succ_pos ordinal) + 1 + run_key_size keys).
                cbn [length]. clear -Hclock Hlocal. PTrieT.trie_get_le. nia.
      + destruct srcs as [| src srcs]; [discriminate |].
        destruct src as [slot | slot | cell]; [discriminate | discriminate |].
        destruct cell as [identifier | stored]; [discriminate |].
        destruct columns as [| column columns]; [discriminate |].
        destruct column as [| i [| j rest]]; try discriminate.
        destruct (V.eqb stored value) eqn:Hvalue; [| discriminate].
        destruct (IH width (S pos) seen copy
          (PTrieCode.set (N.succ_pos (nat_n i)) pos inv) srcs columns copied
          copy' inv' srcs' columns' copied' Htail Hcheck)
          as [keys [Hlength [Hdomain Hclock]]].
        exists (N.succ_pos (nat_n i) :: keys). split.
        * cbn [length]. lia.
        * split.
          -- eapply run_trie_domain_cons. exact Hdomain.
          -- assert (Hlocal :
               (1 + V.T_eqb stored value + T_nat_n i + N.T_succ_pos (nat_n i) +
                 PTrieCode.T_set (N.succ_pos (nat_n i)) pos inv <=
                 64 * (V.c_key + PTrieT.c_trie + 1) *
                   N.of_nat (width + 1 + (Pos.size_nat (N.succ_pos (nat_n i)) + 1) +
                     (S (V.bits stored) + 1) + (i + 1 + 1)))%N).
             { pose proof (V.T_eqb_le stored value) as Hcompare.
               pose proof (run_nat_n_time i) as Hnat.
               pose proof (N.T_succ_pos_le (nat_n i)) as Hcode.
               pose proof (run_counter_key_bits_lower (nat_n i)) as Hbits.
               pose proof (run_trie_set_time nat (N.succ_pos (nat_n i)) pos inv) as Hset.
               clear -Hcompare Hnat Hcode Hbits Hset. nia. }
             time_unfold @T_check_terms. rewrite Hvalue.
             change (run_key_size (N.succ_pos (nat_n i) :: keys)) with
               (Pos.size_nat (N.succ_pos (nat_n i)) + 1 + run_key_size keys).
             unfold run_payload_size in Hclock |- *.
             change (run_sources_size (Const V.t (Val stored) :: srcs)) with
               (S (V.bits stored) + 1 + run_sources_size srcs).
             change (run_columns_size ([i] :: columns)) with
               (i + 1 + 0 + 1 + run_columns_size columns).
             cbn [length]. clear -Hclock Hlocal. lia.
  Qed.

  Definition run_key_width (upper : nat) : nat :=
    Pos.size_nat (N.succ_pos (N.of_nat upper)).

  Lemma run_counter_key_monotone : forall n m,
    N.to_nat n <= N.to_nat m ->
    Pos.size_nat (N.succ_pos n) <= Pos.size_nat (N.succ_pos m).
  Proof.
    intros n m Hle.
    destruct (Pos.eq_dec (N.succ_pos n) (N.succ_pos m)) as [Heq | Hneq].
    - now rewrite Heq.
    - apply Pos.size_nat_monotone. apply Pos2Nat.inj_lt.
      assert (Hvalues : Pos.to_nat (N.succ_pos n) <> Pos.to_nat (N.succ_pos m)).
      { intro H. apply Hneq. now apply Pos2Nat.inj. }
      rewrite !run_counter_key_value in *. lia.
  Qed.

  Lemma run_counter_key_bound : forall n upper,
    N.to_nat n <= upper ->
    N.size_nat n <= run_key_width upper /\
    Pos.size_nat (N.succ_pos n) <= run_key_width upper.
  Proof.
    intros n upper Hbound.
    assert (Hkey : Pos.size_nat (N.succ_pos n) <= run_key_width upper).
    { unfold run_key_width. apply run_counter_key_monotone. now rewrite Nat2N.id. }
    pose proof (run_counter_key_bits_lower n). lia.
  Qed.

  Lemma run_key_width_product : forall m upper,
    m * run_key_width upper <= m * m + 3 * (upper + 1).
  Proof.
    intros m upper. pose proof (run_width_product m (N.succ_pos (N.of_nat upper))) as H.
    rewrite run_counter_key_value, Nat2N.id in H. exact H.
  Qed.

  (** A first failing term traversal may use the variable-count allowance once. *)
  Lemma run_check_terms_bounded_time : forall names ts width upper pos seen copy inv srcs columns copied,
    Forall (run_check_term_width width) ts ->
    (forall x ordinal, trie_get x names = Some ordinal -> N.to_nat ordinal <= upper) ->
    N.to_nat copy + length ts <= upper ->
    (T_check_terms V.eqb V.T_eqb names ts pos seen copy inv srcs columns copied <=
      64 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat (length ts * (width + run_key_width upper + 1) +
          run_payload_size srcs columns + 1))%N.
  Proof.
    intros names ts. induction ts as [| t ts IH];
      intros width upper pos seen copy inv srcs columns copied Hwidth Hnames Hcopy.
    - time_unfold @T_check_terms. cbn [length]. nia.
    - inversion Hwidth as [| t0 ts0 Hterm Htail]; subst.
      assert (Hcopy_tail : N.to_nat copy + length ts <= upper) by (cbn [length] in Hcopy; lia).
      assert (Hcopy_value : N.to_nat copy <= upper) by lia.
      destruct (run_counter_key_bound copy upper Hcopy_value) as [Hcopy_bits Hcopy_key].
      destruct t as [x | value].
      + cbn [run_check_term_width] in Hterm.
        pose proof (N.T_succ_le copy) as Hsucc.
        pose proof (N.T_succ_pos_le copy) as Hcode.
        pose proof (run_trie_set_time nat (N.succ_pos copy) pos inv) as Hset.
        assert (Hduplicate :
          (1 + 2 * N.of_nat (Pos.size_nat x) + N.T_succ copy +
            N.T_succ_pos copy + PTrieCode.T_set (N.succ_pos copy) pos inv <=
            64 * (V.c_key + PTrieT.c_trie + 1) *
              N.of_nat (width + run_key_width upper + 1))%N).
        { clear -Hterm Hsucc Hcode Hset Hcopy_bits Hcopy_key. nia. }
        time_unfold @T_check_terms. PTrieT.trie_get_le.
        destruct (trie_get x seen) as [present |] eqn:Hseen.
        * assert (Hcopy_step : N.to_nat (N.succ copy) + length ts <= upper).
          { rewrite N2Nat.inj_succ. cbn [length] in Hcopy. lia. }
          pose proof (IH width upper (S pos) seen (N.succ copy)
            (PTrieCode.set (N.succ_pos copy) pos inv) srcs columns true
            Htail Hnames Hcopy_step) as Hclock.
          cbn [length]. clear -Hduplicate Hclock. PTrieT.trie_get_le. nia.
        * destruct (trie_get x names) as [ordinal |] eqn:Hname.
          -- destruct (run_counter_key_bound ordinal upper (Hnames x ordinal Hname))
               as [Hordinal_bits Hordinal_key].
             pose proof (N.T_succ_pos_le ordinal) as Hordinal_code.
             pose proof (run_trie_set_time unit x tt seen) as Hseen_set.
             pose proof (run_trie_set_time nat (N.succ_pos ordinal) pos inv) as Hordinal_set.
             assert (Hlocal :
               (1 + 4 * N.of_nat (Pos.size_nat x) + PTrieCode.T_set x tt seen +
                 N.T_succ_pos ordinal + PTrieCode.T_set (N.succ_pos ordinal) pos inv <=
                 64 * (V.c_key + PTrieT.c_trie + 1) *
                   N.of_nat (width + run_key_width upper + 1))%N).
             { clear -Hterm Hordinal_bits Hordinal_key Hordinal_code Hseen_set Hordinal_set. nia. }
             pose proof (IH width upper (S pos) (PTrieCode.set x tt seen) copy
               (PTrieCode.set (N.succ_pos ordinal) pos inv) srcs columns copied
               Htail Hnames Hcopy_tail) as Hclock.
             cbn [length]. clear -Hlocal Hclock. PTrieT.trie_get_le. nia.
          -- cbn [length]. clear -Hterm. PTrieT.trie_get_le. nia.
      + destruct srcs as [| src srcs].
        * time_unfold @T_check_terms. cbn [length]. nia.
        * destruct columns as [| column columns].
          -- destruct src as [slot | slot | [identifier | stored]];
               time_unfold @T_check_terms; cbn [length]; nia.
          -- destruct src as [slot | slot | cell].
             ++ time_unfold @T_check_terms. cbn [length]. nia.
             ++ time_unfold @T_check_terms. cbn [length]. nia.
             ++ destruct cell as [identifier | stored].
                ** time_unfold @T_check_terms. cbn [length]. nia.
                ** destruct column as [| i column].
                   --- time_unfold @T_check_terms. cbn [length]. nia.
                   --- destruct column as [| j rest].
                       +++ pose proof (V.T_eqb_le stored value) as Hcompare.
                           pose proof (run_nat_n_time i) as Hnat.
                           pose proof (N.T_succ_pos_le (nat_n i)) as Hcode.
                           pose proof (run_positive_bits_value (N.succ_pos (nat_n i))) as Hkey.
                           rewrite run_position_key_value in Hkey.
                           pose proof (run_counter_key_bits_lower (nat_n i)) as Hbits.
                           pose proof (run_trie_set_time nat (N.succ_pos (nat_n i)) pos inv) as Hset.
                           assert (Hlocal :
                             (1 + V.T_eqb stored value + T_nat_n i +
                               N.T_succ_pos (nat_n i) +
                               PTrieCode.T_set (N.succ_pos (nat_n i)) pos inv <=
                               64 * (V.c_key + PTrieT.c_trie + 1) *
                                 N.of_nat (width + run_key_width upper + 1 +
                                   (S (V.bits stored) + 1) + (i + 1 + 1)))%N).
                           { clear -Hcompare Hnat Hcode Hkey Hbits Hset. nia. }
                           pose proof (IH width upper (S pos) seen copy
                             (PTrieCode.set (N.succ_pos (nat_n i)) pos inv) srcs columns copied
                             Htail Hnames Hcopy_tail) as Hclock.
                           time_unfold @T_check_terms.
                           unfold run_payload_size in Hclock |- *.
                           change (run_sources_size (Const V.t (Val stored) :: srcs)) with
                             (S (V.bits stored) + 1 + run_sources_size srcs).
                           change (run_columns_size ([i] :: columns)) with
                             (i + 1 + 0 + 1 + run_columns_size columns).
                           destruct (V.eqb stored value); cbn [length]; clear -Hlocal Hclock; nia.
                       +++ time_unfold @T_check_terms. cbn [length]. nia.
  Qed.

  Lemma run_trie_set_present : forall A (table : ptrie A) key value query old,
    trie_get query table = Some old ->
    exists result, trie_get query (PTrieCode.set key value table) = Some result.
  Proof.
    intros A table key value query old Hget. destruct (Pos.eq_dec query key) as [-> | Hneq].
    - exists value. apply PTrie.get_set_same.
    - exists old. rewrite PTrie.get_set_other by exact Hneq. exact Hget.
  Qed.

  (** Successful term checks preserve keys and record every allocated copy ordinal. *)
  Lemma run_check_terms_state : forall names ts pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    (copy <= copy' <= copy + N.of_nat (length ts))%N /\
    (forall key old, trie_get key inv = Some old ->
      exists result, trie_get key inv' = Some result) /\
    (forall ordinal, (copy <= ordinal < copy')%N ->
      exists position, trie_get (N.succ_pos ordinal) inv' = Some position) /\
    run_payload_size srcs' columns' <= run_payload_size srcs columns.
  Proof.
    intros names ts. induction ts as [| t ts IH];
      intros pos seen copy inv srcs columns copied copy' inv' srcs' columns' copied' Hcheck.
    - cbn [check_terms] in Hcheck. inversion Hcheck; subst.
      split; [cbn [length]; lia |]. split.
      + intros key old Hget. now exists old.
      + split; [intros ordinal Hrange; lia | lia].
    - destruct t as [x | value]; cbn [check_terms] in Hcheck.
      + destruct (trie_get x seen) as [present |] eqn:Hseen.
        * destruct (IH (S pos) seen (N.succ copy)
            (PTrieCode.set (N.succ_pos copy) pos inv) srcs columns true
            copy' inv' srcs' columns' copied' Hcheck) as [Hrange [Hpreserve [Hcopies Hpayload]]].
          split; [cbn [length]; lia |]. split.
          -- intros key old Hget.
             destruct (run_trie_set_present nat inv (N.succ_pos copy) pos key old Hget)
               as [value Hvalue]. now apply (Hpreserve key value).
          -- split; [| exact Hpayload].
             intros ordinal Hordinal. destruct (N.eq_dec ordinal copy) as [-> | Hneq].
             ++ apply (Hpreserve (N.succ_pos copy) pos). apply PTrie.get_set_same.
             ++ apply Hcopies. lia.
        * destruct (trie_get x names) as [ordinal |] eqn:Hname; [| discriminate].
          destruct (IH (S pos) (PTrieCode.set x tt seen) copy
            (PTrieCode.set (N.succ_pos ordinal) pos inv) srcs columns copied
            copy' inv' srcs' columns' copied' Hcheck) as [Hrange [Hpreserve [Hcopies Hpayload]]].
          split; [cbn [length]; lia |]. split; [| now split].
          intros key old Hget.
          destruct (run_trie_set_present nat inv (N.succ_pos ordinal) pos key old Hget)
            as [value Hvalue]. now apply (Hpreserve key value).
      + destruct srcs as [| src srcs]; [discriminate |].
        destruct src as [slot | slot | cell]; [discriminate | discriminate |].
        destruct cell as [identifier | stored]; [discriminate |].
        destruct columns as [| column columns]; [discriminate |].
        destruct column as [| i [| j rest]]; try discriminate.
        destruct (V.eqb stored value) eqn:Hvalue; [| discriminate].
        destruct (IH (S pos) seen copy
          (PTrieCode.set (N.succ_pos (nat_n i)) pos inv) srcs columns copied
          copy' inv' srcs' columns' copied' Hcheck) as [Hrange [Hpreserve [Hcopies Hpayload]]].
        split; [cbn [length]; lia |]. split.
        * intros key old Hget.
          destruct (run_trie_set_present nat inv (N.succ_pos (nat_n i)) pos key old Hget)
            as [found Hfound]. now apply (Hpreserve key found).
        * split; [exact Hcopies |]. unfold run_payload_size in Hpayload |- *.
          change (run_sources_size (Const V.t (Val stored) :: srcs)) with
            (S (V.bits stored) + 1 + run_sources_size srcs).
          change (run_columns_size ([i] :: columns)) with
            (i + 1 + 0 + 1 + run_columns_size columns). lia.
  Qed.

  Lemma run_trie_set_values_bound : forall table key value bound,
    value < bound ->
    (forall query old, trie_get query table = Some old -> old < bound) ->
    forall query result, trie_get query (PTrieCode.set key value table) = Some result ->
      result < bound.
  Proof.
    intros table key value bound Hvalue Htable query result Hget.
    destruct (Pos.eq_dec query key) as [-> | Hneq].
    - rewrite PTrie.get_set_same in Hget. inversion Hget; subst. exact Hvalue.
    - rewrite PTrie.get_set_other in Hget by exact Hneq. now apply (Htable query result).
  Qed.

  (** Every generated permutation position names one term of the atom. *)
  Lemma run_check_terms_values_bound : forall names ts bound pos seen copy inv srcs columns copied
      copy' inv' srcs' columns' copied',
    pos + length ts <= bound ->
    (forall key old, trie_get key inv = Some old -> old < bound) ->
    check_terms V.eqb names ts pos seen copy inv srcs columns copied =
      Some (copy', inv', srcs', columns', copied') ->
    forall key position, trie_get key inv' = Some position -> position < bound.
  Proof.
    intros names ts. induction ts as [| t ts IH];
      intros bound pos seen copy inv srcs columns copied copy' inv' srcs' columns' copied'
        Hlength Hinv Hcheck.
    - cbn [check_terms] in Hcheck. inversion Hcheck; subst. exact Hinv.
    - assert (Hposition : pos < bound) by (cbn [length] in Hlength; lia).
      assert (Hrest : S pos + length ts <= bound) by (cbn [length] in Hlength; lia).
      destruct t as [x | value]; cbn [check_terms] in Hcheck.
      + destruct (trie_get x seen) as [present |].
        * eapply IH; [exact Hrest | | exact Hcheck].
          now apply run_trie_set_values_bound.
        * destruct (trie_get x names) as [ordinal |]; [| discriminate].
          eapply IH; [exact Hrest | | exact Hcheck].
          now apply run_trie_set_values_bound.
      + destruct srcs as [| src srcs]; [discriminate |].
        destruct src as [slot | slot | cell]; [discriminate | discriminate |].
        destruct cell as [identifier | stored]; [discriminate |].
        destruct columns as [| column columns]; [discriminate |].
        destruct column as [| i [| j rest]]; try discriminate.
        destruct (V.eqb stored value); [| discriminate].
        eapply IH; [exact Hrest | | exact Hcheck].
        now apply run_trie_set_values_bound.
  Qed.

  Lemma run_column_perm_size : forall inv positions used count perm used' count' bound,
    (forall key position, trie_get key inv = Some position -> position < bound) ->
    column_perm inv positions used count = Some (perm, used', count') ->
    run_positions_size perm <= bound * length positions.
  Proof.
    intros inv positions. induction positions as [| i positions IH];
      intros used count perm used' count' bound Hbound Hcheck.
    - cbn [column_perm] in Hcheck. inversion Hcheck; subst.
      change (0 <= bound * 0). lia.
    - cbn [column_perm] in Hcheck.
      destruct (trie_get (N.succ_pos (nat_n i)) inv) as [pos |] eqn:Hget;
        [| discriminate].
      destruct (column_perm inv positions
        (PTrieCode.set (N.succ_pos (nat_n i)) tt used)
        (match trie_get (N.succ_pos (nat_n i)) used with
         | Some _ => count | None => N.succ count end))
        as [[ [perm1 used1] count1] |] eqn:Htail; [| discriminate].
      inversion Hcheck; subst. pose proof (IH _ _ _ _ _ bound Hbound Htail) as Hrest.
      pose proof (Hbound _ _ Hget) as Hpos.
      change (run_positions_size (pos :: perm1)) with (pos + 1 + run_positions_size perm1).
      cbn [length]. nia.
  Qed.

  Lemma run_column_ok_range : forall n positions prev,
    column_ok n positions prev = true -> Forall (fun i => i < n) positions.
  Proof.
    intros n positions. induction positions as [| i positions IH]; intros prev Hcheck.
    - constructor.
    - destruct prev as [p |]; cbn [column_ok] in Hcheck.
      + destruct (Nat.leb (S p) i); [| discriminate].
        destruct (Nat.leb (S i) n) eqn:Hrange; [| discriminate].
        constructor; [apply Nat.leb_le in Hrange; lia |]. now apply (IH (Some i)).
      + destruct (Nat.leb (S i) n) eqn:Hrange; [| discriminate].
        constructor; [apply Nat.leb_le in Hrange; lia |]. now apply (IH (Some i)).
  Qed.

  Lemma run_positions_length : forall positions,
    length positions <= run_positions_size positions.
  Proof.
    induction positions as [| i positions IH].
    - reflexivity.
    - change (run_positions_size (i :: positions)) with
        (i + 1 + run_positions_size positions). cbn [length]. lia.
  Qed.

  Lemma run_column_ok_mass : forall n positions,
    column_ok n positions None = true -> 1 <= run_positions_size positions.
  Proof.
    intros n [| i positions] Hcheck; [discriminate |].
    change (run_positions_size (i :: positions)) with
      (i + 1 + run_positions_size positions). lia.
  Qed.

  Lemma run_column_copies_bounded : forall n positions keys inv used count perm used' count'
      copy copy',
    column_ok n positions None = true ->
    length keys = length positions ->
    (forall key pos, trie_get key inv = Some pos -> In key keys) ->
    column_perm inv positions used count = Some (perm, used', count') ->
    (copy <= N.of_nat n)%N ->
    (forall ordinal, (copy <= ordinal < copy')%N ->
      exists pos, trie_get (N.succ_pos ordinal) inv = Some pos) ->
    (copy' <= N.of_nat n)%N.
  Proof.
    intros n positions keys inv used count perm used' count' copy copy'
      Hcolumn Hlength Hdomain Hperm Hcopy Hcopies.
    pose proof (run_inverse_keys_permutation inv positions keys n used count perm used' count'
      Hcolumn Hlength Hdomain Hperm) as Hkeys.
    pose proof (run_column_ok_range n positions None Hcolumn) as Hrange.
    assert (Horder : (copy' <= N.of_nat n \/ N.of_nat n < copy')%N) by lia.
    destruct Horder as [Hdone | Hlarge]; [exact Hdone |].
    destruct (Hcopies (N.of_nat n) (conj Hcopy Hlarge)) as [pos Hget].
    pose proof (Hdomain _ _ Hget) as Hin.
    apply (Permutation_in _ Hkeys) in Hin.
    apply in_map_iff in Hin. destruct Hin as [i [Heq Hin]].
    apply (f_equal Pos.to_nat) in Heq.
    rewrite run_position_key_value, run_counter_key_value, Nat2N.id in Heq.
    apply Forall_forall with (x := i) in Hrange; [lia | exact Hin].
  Qed.

  Definition run_source_bits (src : source V.t) : nat :=
    match src with
    | All _ i | New _ i => N.size_nat i + 1
    | Const _ value => cell_bits V.encode value + 1
    end.

  Lemma run_sources_size_cons : forall src srcs,
    run_sources_size (src :: srcs) = run_source_bits src + run_sources_size srcs.
  Proof.
    intros src srcs. destruct src; reflexivity.
  Qed.

  Lemma run_payload_size_cons : forall src srcs col columns,
    run_payload_size (src :: srcs) (col :: columns) =
      run_source_bits src + run_positions_size col + 1 + run_payload_size srcs columns.
  Proof.
    intros src srcs col columns. unfold run_payload_size. rewrite run_sources_size_cons.
    change (run_columns_size (col :: columns)) with
      (run_positions_size col + 1 + run_columns_size columns). lia.
  Qed.

  Lemma run_source_slot_bits : forall newok src slot,
    source_slot newok src = Some slot -> N.size_nat slot + 1 <= run_source_bits src.
  Proof.
    intros newok src slot H. destruct src; destruct newok; cbn [source_slot] in H;
      inversion H; subst; cbn [run_source_bits]; lia.
  Qed.

  (** A larger residual-resource coefficient leaves the processing charge unchanged. *)
  Lemma run_clock_raise_resource : forall clock small large before after extra,
    (small <= large)%N -> (after <= before)%N ->
    (clock + small * after <= small * (before + extra))%N ->
    (clock + large * after <= large * before + small * extra)%N.
  Proof.
    intros clock small large before after extra Hcoeff Hmono Hclock.
    assert (Hgap : (small * (before - after) <= large * (before - after))%N).
    { now apply N.mul_le_mono_r. }
    assert (Hbefore : (before = (before - after) + after)%N) by lia.
    rewrite Hbefore in Hclock |- *. nia.
  Qed.

  Lemma run_check_terms_column_budget : forall names ts width n column pos seen copy inv srcs columns copied,
    Forall (run_check_term_width width) ts ->
    (forall x ordinal, trie_get x names = Some ordinal -> N.to_nat ordinal <= n) ->
    (copy <= N.of_nat n)%N ->
    column_ok n column None = true -> length column = length ts ->
    (T_check_terms V.eqb V.T_eqb names ts pos seen copy inv srcs columns copied <=
      512 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * (run_positions_size column + run_payload_size srcs columns + 1) + n))%N.
  Proof.
    intros names ts width n column pos seen copy inv srcs columns copied
      Hwidth Hnames Hcopy Hcolumn Hlength.
    assert (Hnames_upper : forall x ordinal, trie_get x names = Some ordinal ->
      N.to_nat ordinal <= n + length ts) by (intros; specialize (Hnames _ _ H); lia).
    assert (Hcopy_upper : N.to_nat copy + length ts <= n + length ts) by lia.
    pose proof (run_check_terms_bounded_time names ts width (n + length ts) pos seen copy inv
      srcs columns copied Hwidth Hnames_upper Hcopy_upper) as Hclock.
    pose proof (run_positions_length column) as Hlen.
    pose proof (run_column_ok_quadratic n column Hcolumn) as Hsquare.
    pose proof (run_key_width_product (length ts) (n + length ts)) as Hwidth_product.
    assert (Hcharge :
      length ts * (width + run_key_width (n + length ts) + 1) +
        run_payload_size srcs columns + 1 <=
      8 * ((width + 1) * (run_positions_size column + run_payload_size srcs columns + 1) + n)).
    { clear -Hlength Hlen Hsquare Hwidth_product. nia. }
    clear -Hclock Hcharge. nia.
  Qed.

  (** A complete atom column pays for every term insertion and generated permutation position. *)
  Lemma run_check_atom_core : forall names ts width n column copy srcs columns
      copy' inv' srcs' columns' copied used count perm used' count',
    Forall (run_check_term_width width) ts ->
    (copy <= N.of_nat n)%N ->
    column_ok n column None = true -> length column = length ts ->
    check_terms V.eqb names ts 0 Empty copy Empty srcs columns false =
      Some (copy', inv', srcs', columns', copied) ->
    column_perm inv' column used count = Some (perm, used', count') ->
    (copy' <= N.of_nat n)%N /\
    run_payload_size srcs' columns' <= run_payload_size srcs columns /\
    run_positions_size perm <= 2 * run_positions_size column /\
    (T_check_terms V.eqb V.T_eqb names ts 0 Empty copy Empty srcs columns false +
      1024 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * run_payload_size srcs' columns') <=
     1024 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * run_payload_size srcs columns) +
      256 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * run_positions_size column))%N.
  Proof.
    intros names ts width n column copy srcs columns copy' inv' srcs' columns' copied
      used count perm used' count' Hwidth Hcopy Hcolumn Hlength Hterms Hperm.
    destruct (run_check_terms_success_time names ts width 0 Empty copy Empty srcs columns false
      copy' inv' srcs' columns' copied Hwidth Hterms)
      as [keys [Hkey_length [Hdomain Hclock]]].
    assert (Hkeys : forall key position, trie_get key inv' = Some position -> In key keys).
    { intros key position Hget. destruct (Hdomain key position Hget) as [Hin | [old Hold]].
      - exact Hin.
      - rewrite PTrie.get_empty in Hold. discriminate. }
    assert (Hkey_column : length keys = length column) by lia.
    pose proof (run_inverse_keys_size inv' column keys n used count perm used' count'
      Hcolumn Hkey_column Hkeys Hperm) as Hkey_mass.
    destruct (run_check_terms_state names ts 0 Empty copy Empty srcs columns false
      copy' inv' srcs' columns' copied Hterms)
      as [Hcopy_range [Hpreserve [Hcopies Hpayload]]].
    split.
    - eapply run_column_copies_bounded; eauto.
    - split; [exact Hpayload |].
      assert (Hvalues : forall key position, trie_get key inv' = Some position -> position < length ts).
      { eapply (run_check_terms_values_bound names ts (length ts) 0 Empty copy Empty srcs columns false
          copy' inv' srcs' columns' copied); [lia | | exact Hterms].
        intros key old Hget. rewrite PTrie.get_empty in Hget. discriminate. }
      pose proof (run_column_perm_size inv' column used count perm used' count' (length ts)
        Hvalues Hperm) as Hperm_size.
      pose proof (run_column_ok_quadratic n column Hcolumn) as Hcolumn_square.
      pose proof (run_positions_length column) as Hcolumn_length.
      pose proof (run_column_ok_mass n column Hcolumn) as Hcolumn_mass.
      split; [nia |].
      assert (Hprocessing : length ts * (width + 1) + run_key_size keys + 1 <=
        4 * ((width + 1) * run_positions_size column)).
      { clear -Hkey_mass Hcolumn_mass Hcolumn_length Hlength. nia. }
      assert (Hsmall :
        (T_check_terms V.eqb V.T_eqb names ts 0 Empty copy Empty srcs columns false +
          64 * (V.c_key + PTrieT.c_trie + 1) *
            N.of_nat ((width + 1) * run_payload_size srcs' columns') <=
          64 * (V.c_key + PTrieT.c_trie + 1) *
            (N.of_nat ((width + 1) * run_payload_size srcs columns) +
             4 * N.of_nat ((width + 1) * run_positions_size column)))%N).
      { clear -Hclock Hprocessing. nia. }
      assert (Hmono : (N.of_nat ((width + 1) * run_payload_size srcs' columns') <=
        N.of_nat ((width + 1) * run_payload_size srcs columns))%N).
      { clear -Hpayload. nia. }
      pose proof (run_clock_raise_resource
        (T_check_terms V.eqb V.T_eqb names ts 0 Empty copy Empty srcs columns false)
        (64 * (V.c_key + PTrieT.c_trie + 1))%N
        (1024 * (V.c_key + PTrieT.c_trie + 1))%N
        (N.of_nat ((width + 1) * run_payload_size srcs columns))
        (N.of_nat ((width + 1) * run_payload_size srcs' columns'))
        (4 * N.of_nat ((width + 1) * run_positions_size column))%N) as Hraise.
      assert (Hcoeff : (64 * (V.c_key + PTrieT.c_trie + 1) <=
        1024 * (V.c_key + PTrieT.c_trie + 1))%N) by (clear; nia).
      specialize (Hraise Hcoeff Hmono Hsmall). clear -Hraise. nia.
  Qed.

  Lemma run_check_atom_success_time : forall newok names n table f ts width copy used count
      srcs columns copy' used' count' srcs' columns' copied,
    Pos.size_nat f <= width -> Forall (run_check_term_width width) ts ->
    (copy <= N.of_nat n)%N ->
    check_atom V.eqb newok names n table f ts copy used count srcs columns =
      Some (copy', used', count', srcs', columns', copied) ->
    (copy' <= N.of_nat n)%N /\
    run_payload_size srcs' columns' + length ts + 2 <= run_payload_size srcs columns /\
    (T_check_atom V.eqb V.T_eqb newok names n table f ts copy used count srcs columns +
      1024 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * run_payload_size srcs' columns') + run_counter_credit count' <=
     1024 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * run_payload_size srcs columns) + run_counter_credit count)%N.
  Proof.
    intros newok names n table f ts width copy used count srcs columns
      copy' used' count' srcs' columns' copied Hname Hwidth Hcopy Hcheck.
    unfold check_atom in Hcheck.
    destruct srcs as [| src srcs]; [discriminate |].
    destruct columns as [| column columns]; [discriminate |].
    destruct (source_slot newok src) as [slot |] eqn:Hsource; [| discriminate].
    destruct (column_ok n column None) eqn:Hcolumn; [| discriminate].
    destruct (Nat.eqb (length column) (length ts)) eqn:Hlength_bool; [| discriminate].
    pose proof Hlength_bool as Hlength. apply Nat.eqb_eq in Hlength.
    destruct (check_terms V.eqb names ts 0 Empty copy Empty srcs columns false)
      as [[[[[copy1 inv1] srcs1] columns1] copied1] |] eqn:Hterms; [| discriminate].
    destruct (column_perm inv1 column used count) as [[[perm used1] count1] |] eqn:Hperm;
      [| discriminate].
    destruct (slot_matches table f perm slot) eqn:Hslot; [| discriminate].
    inversion Hcheck. subst copy' used' count' srcs' columns' copied.
    destruct (run_check_atom_core names ts width n column copy srcs columns
      copy1 inv1 srcs1 columns1 copied1 used count perm used1 count1
      Hwidth Hcopy Hcolumn Hlength Hterms Hperm)
      as [Hcopy1 [Hpayload [Hperm_size Hterms_clock]]].
    split; [exact Hcopy1 |]. split.
    - rewrite run_payload_size_cons.
      pose proof (run_positions_length column).
      pose proof (run_source_slot_bits newok src slot Hsource). lia.
    - pose proof (run_column_perm_time inv1 column used count) as Hcolumn_clock.
      rewrite Hperm in Hcolumn_clock.
      pose proof (run_source_slot_time newok src) as Hsource_clock.
      pose proof (run_column_ok_time n column None) as Hvalid_clock.
      pose proof (Datatypes.T_length_le column) as Hcolumn_length_clock.
      pose proof (Datatypes.T_length_le ts) as Hterms_length_clock.
      pose proof (Nat.T_eqb_le (length column) (length ts)) as Hlength_clock.
      pose proof (run_slot_matches_time table f perm slot) as Hslot_clock.
      pose proof (run_positions_length column) as Hcolumn_length.
      pose proof (run_column_ok_mass n column Hcolumn) as Hcolumn_mass.
      pose proof (run_source_slot_bits newok src slot Hsource) as Hsource_bits.
      assert (Hbudget :
        (1 + 3 + (8 * N.of_nat (run_positions_size column) + 1) +
          (N.of_nat (length column) + 1) + (N.of_nat (length ts) + 1) +
          (N.of_nat (length column) + 1) +
          64 * (PTrieT.c_trie + 1) * N.of_nat (run_positions_size column + 1) +
          32 * N.of_nat (Pos.size_nat f + run_positions_size perm + N.size_nat slot + 1) +
          256 * (V.c_key + PTrieT.c_trie + 1) *
            N.of_nat ((width + 1) * run_positions_size column) <=
          1024 * (V.c_key + PTrieT.c_trie + 1) *
            N.of_nat ((width + 1) * (run_source_bits src + run_positions_size column + 1)))%N).
      { clear -Hname Hperm_size Hcolumn_length Hcolumn_mass Hsource_bits Hlength. nia. }
      time_unfold @T_check_atom.
      rewrite Hsource, Hcolumn, Hlength_bool, Hterms, Hperm.
      rewrite ?Hslot, run_payload_size_cons.
      replace (N.of_nat ((width + 1) *
        (run_source_bits src + run_positions_size column + 1 + run_payload_size srcs columns))) with
        (N.of_nat ((width + 1) * (run_source_bits src + run_positions_size column + 1)) +
         N.of_nat ((width + 1) * run_payload_size srcs columns))%N
        by (rewrite !Nat2N.inj_mul, !Nat2N.inj_add; ring).
      rewrite N.mul_add_distr_l.
      clear -Hterms_clock Hcolumn_clock Hsource_clock Hvalid_clock Hcolumn_length_clock
        Hterms_length_clock Hlength_clock Hslot_clock Hbudget. lia.
  Qed.

  Lemma run_check_atom_bounded_time : forall newok names n table f ts width copy used count
      srcs columns,
    Pos.size_nat f <= width -> Forall (run_check_term_width width) ts ->
    (forall x ordinal, trie_get x names = Some ordinal -> N.to_nat ordinal <= n) ->
    (copy <= N.of_nat n)%N ->
    (T_check_atom V.eqb V.T_eqb newok names n table f ts copy used count srcs columns <=
      1024 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * (run_payload_size srcs columns + terms_bits ts + 1) + n) +
      run_counter_credit count)%N.
  Proof.
    intros newok names n table f ts width copy used count srcs columns
      Hname Hwidth Hnames Hcopy.
    destruct srcs as [| src srcs].
    - time_unfold @T_check_atom. nia.
    - destruct columns as [| column columns].
      + time_unfold @T_check_atom. nia.
      + time_unfold @T_check_atom. rewrite run_payload_size_cons.
        pose proof (run_source_slot_time newok src) as Hsource_clock.
        destruct (source_slot newok src) as [slot |] eqn:Hsource.
        * pose proof (run_column_ok_time n column None) as Hvalid_clock.
          pose proof (run_positions_length column) as Hcolumn_length.
          destruct (column_ok n column None) eqn:Hcolumn.
          -- pose proof (Datatypes.T_length_le column) as Hcolumn_length_clock.
             pose proof (Datatypes.T_length_le ts) as Hterms_length_clock.
             pose proof (Nat.T_eqb_le (length column) (length ts)) as Hlength_clock.
             pose proof (run_terms_length_bits ts) as Hterms_length.
             destruct (Nat.eqb (length column) (length ts)) eqn:Hlength_bool.
             ++ pose proof Hlength_bool as Hlength. apply Nat.eqb_eq in Hlength.
                pose proof (run_column_ok_mass n column Hcolumn) as Hcolumn_mass.
                pose proof (run_source_slot_bits newok src slot Hsource) as Hsource_bits.
                pose proof (run_check_terms_column_budget names ts width n column 0 Empty copy Empty
                  srcs columns false Hwidth Hnames Hcopy Hcolumn Hlength) as Hterms_clock.
                assert (Hbudget :
                  (1 + 3 + (8 * N.of_nat (run_positions_size column) + 1) +
                    (N.of_nat (length column) + 1) + (N.of_nat (length ts) + 1) +
                    (N.of_nat (length column) + 1) +
                    512 * (V.c_key + PTrieT.c_trie + 1) *
                      N.of_nat ((width + 1) *
                        (run_positions_size column + run_payload_size srcs columns + 1) + n) +
                    64 * (PTrieT.c_trie + 1) * N.of_nat (run_positions_size column + 1) +
                    32 * N.of_nat (width + 2 * run_positions_size column + N.size_nat slot + 1) <=
                    1024 * (V.c_key + PTrieT.c_trie + 1) *
                      N.of_nat ((width + 1) *
                        (run_source_bits src + run_positions_size column + 1 +
                          run_payload_size srcs columns + terms_bits ts + 1) + n))%N).
                { assert (Hfront :
                    (1 + 3 + (8 * N.of_nat (run_positions_size column) + 1) +
                      (N.of_nat (length column) + 1) + (N.of_nat (length ts) + 1) +
                      (N.of_nat (length column) + 1) +
                      64 * (PTrieT.c_trie + 1) * N.of_nat (run_positions_size column + 1) +
                      32 * N.of_nat (width + 2 * run_positions_size column + N.size_nat slot + 1) <=
                      512 * (V.c_key + PTrieT.c_trie + 1) *
                        N.of_nat ((width + 1) *
                          (run_source_bits src + run_positions_size column + 1)))%N).
                  { clear -Hcolumn_length Hsource_bits Hlength. nia. }
                  assert (Hcharge :
                    (N.of_nat ((width + 1) *
                        (run_positions_size column + run_payload_size srcs columns + 1) + n) +
                      N.of_nat ((width + 1) *
                        (run_source_bits src + run_positions_size column + 1)) <=
                      2 * N.of_nat ((width + 1) *
                        (run_source_bits src + run_positions_size column + 1 +
                          run_payload_size srcs columns + terms_bits ts + 1) + n))%N).
                  { clear. nia. }
                  pose proof (N.mul_le_mono_l _ _
                    (512 * (V.c_key + PTrieT.c_trie + 1))%N Hcharge) as Hscaled.
                  rewrite N.mul_add_distr_l in Hscaled.
                  replace (512 * (V.c_key + PTrieT.c_trie + 1) *
                    (2 * N.of_nat ((width + 1) *
                      (run_source_bits src + run_positions_size column + 1 +
                        run_payload_size srcs columns + terms_bits ts + 1) + n)))%N
                    with (1024 * (V.c_key + PTrieT.c_trie + 1) *
                      N.of_nat ((width + 1) *
                        (run_source_bits src + run_positions_size column + 1 +
                          run_payload_size srcs columns + terms_bits ts + 1) + n))%N
                    in Hscaled by ring.
                  clear -Hfront Hscaled. lia. }
                destruct (check_terms V.eqb names ts 0 Empty copy Empty srcs columns false)
                  as [[[[[copy1 inv1] srcs1] columns1] copied1] |] eqn:Hterms.
                ** pose proof (run_column_perm_time inv1 column used count) as Hcolumn_clock.
                   destruct (column_perm inv1 column used count)
                     as [[[perm used1] count1] |] eqn:Hperm.
                   --- assert (Hvalues : forall key position,
                         trie_get key inv1 = Some position -> position < length ts).
                       { eapply (run_check_terms_values_bound names ts (length ts) 0 Empty copy Empty
                           srcs columns false copy1 inv1 srcs1 columns1 copied1); [lia | | exact Hterms].
                         intros key old Hget. rewrite PTrie.get_empty in Hget. discriminate. }
                       pose proof (run_column_perm_size inv1 column used count perm used1 count1
                         (length ts) Hvalues Hperm) as Hperm_length.
                       pose proof (run_column_ok_quadratic n column Hcolumn) as Hcolumn_square.
                       assert (Hperm_size : run_positions_size perm <= 2 * run_positions_size column).
                       { clear -Hperm_length Hcolumn_square Hlength. nia. }
                       pose proof (run_slot_matches_time table f perm slot) as Hslot_clock.
                       assert (Hslot_bound : (T_slot_matches table f perm slot <=
                         32 * N.of_nat (width + 2 * run_positions_size column + N.size_nat slot + 1))%N).
                       { clear -Hslot_clock Hname Hperm_size. nia. }
                       destruct (slot_matches table f perm slot);
                         clear -Hsource_clock Hvalid_clock Hcolumn_length_clock Hterms_length_clock
                           Hlength_clock Hterms_clock Hcolumn_clock Hslot_bound Hbudget; lia.
                   --- clear -Hsource_clock Hvalid_clock Hcolumn_length_clock Hterms_length_clock
                         Hlength_clock Hterms_clock Hcolumn_clock Hbudget. lia.
                ** clear -Hsource_clock Hvalid_clock Hcolumn_length_clock Hterms_length_clock
                     Hlength_clock Hterms_clock Hbudget. lia.
             ++ clear -Hsource_clock Hvalid_clock Hcolumn_length_clock Hterms_length_clock
                  Hlength_clock Hcolumn_length Hterms_length. nia.
          -- clear -Hsource_clock Hvalid_clock. nia.
        * clear -Hsource_clock. nia.
  Qed.

  Lemma run_clock_reserve_gap : forall clock coefficient before after gap extra allowance,
    (2 <= coefficient)%N -> (after + gap <= before)%N -> (extra <= 2 * gap)%N ->
    (clock + coefficient * after <= coefficient * before + allowance)%N ->
    (extra + clock + 2 * coefficient * after <= 2 * coefficient * before + allowance)%N.
  Proof.
    intros clock coefficient before after gap extra allowance Hcoefficient Hgap Hextra Hclock.
    assert (Hreserve : (extra + coefficient * after <= coefficient * before)%N) by nia.
    nia.
  Qed.

  Lemma run_check_query_head_time : forall newok names n table f args res width copy used count
      srcs columns copy' used' count' srcs' columns' copied,
    Pos.size_nat f <= width ->
    Forall (run_check_term_width width) (args ++ option_list res) ->
    (copy <= N.of_nat n)%N ->
    check_atom V.eqb newok names n table f (args ++ option_list res) copy used count srcs columns =
      Some (copy', used', count', srcs', columns', copied) ->
    (copy' <= N.of_nat n)%N /\
    (2 + Datatypes.T_app args (option_list res) +
      T_check_atom V.eqb V.T_eqb newok names n table f (args ++ option_list res)
        copy used count srcs columns +
      2048 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * run_payload_size srcs' columns') + run_counter_credit count' <=
     2048 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat ((width + 1) * run_payload_size srcs columns) + run_counter_credit count)%N.
  Proof.
    intros newok names n table f args res width copy used count srcs columns copy' used' count'
      srcs' columns' copied Hname Hwidth Hcopy Hcheck.
    destruct (run_check_atom_success_time newok names n table f (args ++ option_list res) width
      copy used count srcs columns copy' used' count' srcs' columns' copied
      Hname Hwidth Hcopy Hcheck) as [Hcopy' [Hgap Hclock]].
    split; [exact Hcopy' |].
    pose proof (Datatypes.T_app_le args (option_list res)) as Happend.
    set (coefficient := (1024 * (V.c_key + PTrieT.c_trie + 1) * N.of_nat (width + 1))%N).
    assert (Hcoefficient : (2 <= coefficient)%N).
    { unfold coefficient. clear. assert (1 <= N.of_nat (width + 1))%N by lia. nia. }
    assert (Hgap' : (N.of_nat (run_payload_size srcs' columns') +
      N.of_nat (length args + 2) <= N.of_nat (run_payload_size srcs columns))%N).
    { rewrite length_app in Hgap. clear -Hgap. lia. }
    assert (Hextra : (2 + Datatypes.T_app args (option_list res) <=
      2 * N.of_nat (length args + 2))%N) by (clear -Happend; lia).
    assert (Hclock' :
      (T_check_atom V.eqb V.T_eqb newok names n table f (args ++ option_list res)
        copy used count srcs columns + run_counter_credit count' +
        coefficient * N.of_nat (run_payload_size srcs' columns') <=
        coefficient * N.of_nat (run_payload_size srcs columns) + run_counter_credit count)%N).
    { unfold coefficient. rewrite !Nat2N.inj_mul in Hclock. clear -Hclock. nia. }
    pose proof (run_clock_reserve_gap
      (T_check_atom V.eqb V.T_eqb newok names n table f (args ++ option_list res)
        copy used count srcs columns + run_counter_credit count')%N coefficient
      (N.of_nat (run_payload_size srcs columns)) (N.of_nat (run_payload_size srcs' columns'))
      (N.of_nat (length args + 2)) (2 + Datatypes.T_app args (option_list res))%N
      (run_counter_credit count) Hcoefficient Hgap' Hextra Hclock') as Hreserved.
    unfold coefficient in Hreserved. rewrite !Nat2N.inj_mul. clear -Hreserved. nia.
  Qed.

  (** Query and compiled-plan sizes used in the checker bounds. *)
  Definition run_query_size (q : list (atom V.t)) : nat :=
    fold_right (fun a n => atom_bits a + n) 0 q.

  Definition run_query_width (width : nat) (q : list (atom V.t)) : Prop :=
    Forall (fun a => Forall (fun word => Pos.size_nat word <= width)
      (atom_words V.encode a)) q.

  Definition run_cplan_size (c : cplan V.t) : nat :=
    N.size_nat (rule_ix V.t c) + nvars (join V.t c) + run_columns_size (cols (join V.t c)) +
      run_sources_size (sources V.t c) + run_vars_size (var_of V.t c) +
      run_positions_size (post V.t c) + 1.

  Definition run_check_inner (width : nat) : N :=
    ((4 * 1024) * (V.c_key + PTrieT.c_trie + 1) * N.of_nat (width + 1))%N.

  Lemma run_check_terms_words_width : forall ts width,
    Forall (fun word => Pos.size_nat word <= width) (flat_map (term_words V.encode) ts) ->
    Forall (run_check_term_width width) ts.
  Proof.
    induction ts as [| [x | value] ts IH]; intros width Hwords.
    - constructor.
    - cbn [flat_map term_words app] in Hwords.
      inversion Hwords as [| word words Hhead Htail]; subst.
      constructor; [exact Hhead | now apply IH].
    - cbn [flat_map term_words app] in Hwords.
      inversion Hwords as [| word words Hhead Htail]; subst.
      constructor; [exact I | now apply IH].
  Qed.

  Lemma run_check_fun_width : forall width f args res,
    Forall (fun word => Pos.size_nat word <= width) (atom_words V.encode (Fun V.t f args res)) ->
    Pos.size_nat f <= width /\ Forall (run_check_term_width width) (args ++ option_list res).
  Proof.
    intros width f args res H. cbn [atom_words] in H.
    inversion H as [| word words Hhead Htail]; subst.
    split; [exact Hhead | now apply run_check_terms_words_width].
  Qed.

  Lemma run_check_option_time : forall res : option (term V.t), (T_option_list res <= 1)%N.
  Proof.
    intros [t |]; time_unfold @T_option_list; lia.
  Qed.

  Definition run_query_coefficient (width : nat) : N :=
    ((2 * 1024) * (V.c_key + PTrieT.c_trie + 1) * N.of_nat (width + 1))%N.

  Lemma run_query_coefficient_pos : forall width, (1 <= run_query_coefficient width)%N.
  Proof.
    intro width. unfold run_query_coefficient.
    assert (1 <= N.of_nat (width + 1))%N by lia. nia.
  Qed.

  (** Successful primitive steps are paid by the growth of the required post list. *)
  Lemma run_check_query_success_time : forall newok names n table q width ai copy used count
      srcs columns post count' srcs' columns' expected,
    run_query_width width q -> (copy <= N.of_nat n)%N ->
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (count', srcs', columns', expected) ->
    (T_check_query V.eqb V.T_eqb newok names n table q ai copy used count srcs columns post +
      run_query_coefficient width * N.of_nat (run_payload_size srcs' columns' + length post) +
      run_counter_credit count' <=
     run_query_coefficient width * N.of_nat (run_payload_size srcs columns + length expected + 1) +
      run_counter_credit count)%N.
  Proof.
    intros newok names n table q. induction q as [| a q IH];
      intros width ai copy used count srcs columns post count' srcs' columns' expected
        Hwidth Hcopy Hcheck.
    - cbn [check_query] in Hcheck. inversion Hcheck. subst count' srcs' columns' expected.
      pose proof (run_query_coefficient_pos width) as Hcoefficient.
      time_unfold @T_check_query. nia.
    - inversion Hwidth as [| a0 q0 Hhead Htail]; subst.
      destruct a as [f args res | primitive args res]; cbn [check_query] in Hcheck.
      + destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
          copy used count srcs columns)
          as [[[[[[copy1 used1] count1] srcs1] columns1] copied] |] eqn:Hatom;
          [| discriminate].
        destruct (run_check_fun_width width f args res Hhead) as [Hname Hterms_width].
        destruct (run_check_query_head_time newok names n table f args res width copy used count
          srcs columns copy1 used1 count1 srcs1 columns1 copied Hname Hterms_width Hcopy Hatom)
          as [Hcopy1 Hhead_clock].
        pose proof (IH width (S ai) copy1 used1 count1 srcs1 columns1
          (if copied then ai :: post else post) count' srcs' columns' expected
          Htail Hcopy1 Hcheck) as Htail_clock.
        assert (Hhead_scaled :
          (2 + Datatypes.T_app args (option_list res) +
            T_check_atom V.eqb V.T_eqb newok names n table f (args ++ option_list res)
              copy used count srcs columns +
            run_query_coefficient width * N.of_nat (run_payload_size srcs1 columns1) +
            run_counter_credit count1 <=
            run_query_coefficient width * N.of_nat (run_payload_size srcs columns) +
            run_counter_credit count)%N).
        { unfold run_query_coefficient. rewrite !Nat2N.inj_mul in Hhead_clock.
          clear -Hhead_clock. nia. }
        pose proof (run_check_option_time res) as Hoption.
        time_unfold @T_check_query. rewrite Hatom.
        destruct copied; cbn [length] in Htail_clock;
          rewrite !Nat2N.inj_add in Htail_clock |- *;
          rewrite ?time_of_nat_succ in Htail_clock |- *;
          rewrite !N.mul_add_distr_l in Htail_clock |- *;
          clear -Hhead_scaled Htail_clock Hoption; lia.
      + pose proof (IH width (S ai) copy used count srcs columns (ai :: post)
          count' srcs' columns' expected Htail Hcopy Hcheck) as Htail_clock.
        pose proof (run_query_coefficient_pos width) as Hcoefficient.
        time_unfold @T_check_query. cbn [length] in Htail_clock.
        rewrite !Nat2N.inj_add in Htail_clock |- *.
        rewrite ?time_of_nat_succ in Htail_clock |- *.
        rewrite !N.mul_add_distr_l in Htail_clock |- *.
        clear -Htail_clock Hcoefficient. lia.
  Qed.

  Lemma run_check_query_post_length : forall newok names n table q ai copy used count
      srcs columns post count' srcs' columns' expected,
    check_query V.eqb newok names n table q ai copy used count srcs columns post =
      Some (count', srcs', columns', expected) ->
    length expected <= length post + length q.
  Proof.
    intros newok names n table q. induction q as [| a q IH];
      intros ai copy used count srcs columns post count' srcs' columns' expected Hcheck.
    - cbn [check_query] in Hcheck. inversion Hcheck. subst expected. cbn [length]. lia.
    - destruct a as [f args res | primitive args res]; cbn [check_query] in Hcheck.
      + destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
          copy used count srcs columns)
          as [[[[[[copy1 used1] count1] srcs1] columns1] copied] |] eqn:Hatom;
          [| discriminate].
        pose proof (IH (S ai) copy1 used1 count1 srcs1 columns1
          (if copied then ai :: post else post) count' srcs' columns' expected Hcheck) as Hlength.
        destruct copied; cbn [length] in *; lia.
      + pose proof (IH (S ai) copy used count srcs columns (ai :: post)
          count' srcs' columns' expected Hcheck) as Hlength.
        cbn [length] in *. lia.
  Qed.









  Lemma run_check_fun_charge : forall f args res,
    terms_bits (args ++ option_list res) + 1 <= atom_bits (Fun V.t f args res).
  Proof.
    intros f args res. rewrite run_terms_bits_app, run_terms_bits_result. cbn [atom_bits]. lia.
  Qed.

  (** A rejected query pays its program text once, after any accepted compiled prefix. *)
  Lemma run_check_query_failure_time : forall newok names n table q width ai copy used count
      srcs columns post,
    run_query_width width q ->
    (forall x ordinal, trie_get x names = Some ordinal -> N.to_nat ordinal <= n) ->
    (copy <= N.of_nat n)%N ->
    check_query V.eqb newok names n table q ai copy used count srcs columns post = None ->
    (T_check_query V.eqb V.T_eqb newok names n table q ai copy used count srcs columns post <=
      run_query_coefficient width * N.of_nat (run_payload_size srcs columns + run_query_size q + 1) +
      2048 * (V.c_key + PTrieT.c_trie + 1) * N.of_nat n + run_counter_credit count)%N.
  Proof.
    intros newok names n table q. induction q as [| a q IH];
      intros width ai copy used count srcs columns post Hwidth Hnames Hcopy Hcheck.
    - discriminate.
    - inversion Hwidth as [| a0 q0 Hhead Htail]; subst.
      destruct a as [f args res | primitive args res]; cbn [check_query] in Hcheck.
      + destruct (run_check_fun_width width f args res Hhead) as [Hname Hterms_width].
        destruct (check_atom V.eqb newok names n table f (args ++ option_list res)
          copy used count srcs columns)
          as [[[[[[copy1 used1] count1] srcs1] columns1] copied] |] eqn:Hatom.
        * destruct (run_check_query_head_time newok names n table f args res width copy used count
            srcs columns copy1 used1 count1 srcs1 columns1 copied Hname Hterms_width Hcopy Hatom)
            as [Hcopy1 Hhead_clock].
          pose proof (IH width (S ai) copy1 used1 count1 srcs1 columns1
            (if copied then ai :: post else post) Htail Hnames Hcopy1 Hcheck) as Htail_clock.
          assert (Hhead_scaled :
            (2 + Datatypes.T_app args (option_list res) +
              T_check_atom V.eqb V.T_eqb newok names n table f (args ++ option_list res)
                copy used count srcs columns +
              run_query_coefficient width * N.of_nat (run_payload_size srcs1 columns1) +
              run_counter_credit count1 <=
              run_query_coefficient width * N.of_nat (run_payload_size srcs columns) +
              run_counter_credit count)%N).
          { unfold run_query_coefficient. rewrite !Nat2N.inj_mul in Hhead_clock.
            clear -Hhead_clock. nia. }
          pose proof (run_check_option_time res) as Hoption.
          time_unfold @T_check_query. rewrite Hatom.
          change (run_query_size (Fun V.t f args res :: q)) with
            (atom_bits (Fun V.t f args res) + run_query_size q).
          rewrite !Nat2N.inj_add in Htail_clock |- *.
          rewrite !N.mul_add_distr_l in Htail_clock |- *.
          clear -Hhead_scaled Htail_clock Hoption. lia.
        * pose proof (run_check_atom_bounded_time newok names n table f (args ++ option_list res)
            width copy used count srcs columns Hname Hterms_width Hnames Hcopy) as Hatom_clock.
          pose proof (Datatypes.T_app_le args (option_list res)) as Happend.
          pose proof (run_check_option_time res) as Hoption.
          pose proof (run_check_fun_charge f args res) as Hcharge.
          pose proof (run_terms_length_bits (args ++ option_list res)) as Hlength.
          rewrite length_app in Hlength.
          assert (Hbudget :
            (2 + (N.of_nat (length args) + 1) +
              1024 * (V.c_key + PTrieT.c_trie + 1) *
                N.of_nat ((width + 1) *
                  (run_payload_size srcs columns + terms_bits (args ++ option_list res) + 1) + n) <=
              run_query_coefficient width *
                N.of_nat (run_payload_size srcs columns +
                  atom_bits (Fun V.t f args res) + run_query_size q + 1) +
              2048 * (V.c_key + PTrieT.c_trie + 1) * N.of_nat n)%N).
          { unfold run_query_coefficient. clear -Hcharge Hlength. nia. }
          time_unfold @T_check_query. rewrite Hatom.
          change (run_query_size (Fun V.t f args res :: q)) with
            (atom_bits (Fun V.t f args res) + run_query_size q).
          clear -Hatom_clock Happend Hoption Hbudget. lia.
      + pose proof (IH width (S ai) copy used count srcs columns (ai :: post)
          Htail Hnames Hcopy Hcheck) as Htail_clock.
        pose proof (run_atom_bits_pos (Prim V.t primitive args res)) as Hcharge.
        pose proof (run_query_coefficient_pos width) as Hcoefficient.
        time_unfold @T_check_query.
        change (run_query_size (Prim V.t primitive args res :: q)) with
          (atom_bits (Prim V.t primitive args res) + run_query_size q).
        rewrite !Nat2N.inj_add in Htail_clock |- *.
        rewrite !N.mul_add_distr_l in Htail_clock |- *.
        clear -Htail_clock Hcharge Hcoefficient. nia.
  Qed.

  Lemma run_vars_length : forall vars, length vars <= run_vars_size vars.
  Proof.
    induction vars as [| x vars IH].
    - reflexivity.
    - change (run_vars_size (x :: vars)) with (Pos.size_nat x + 1 + run_vars_size vars).
      cbn [length]. lia.
  Qed.

  Lemma run_nats_eqb_length : forall xs ys,
    nats_eqb xs ys = true -> length xs = length ys.
  Proof.
    induction xs as [| x xs IH]; intros [| y ys] H; try discriminate; [reflexivity |].
    cbn [nats_eqb] in H. destruct (Nat.eqb x y); [| discriminate].
    cbn [length]. now rewrite (IH ys H).
  Qed.

  (** Positive comparison stops when either operand ends. *)
  Lemma compare_cont_right_clock : forall order p q,
    (Pos.T_compare_cont order p q <= N.of_nat (Pos.size_nat q))%N.
  Proof.
    intros order p q. revert order p.
    induction q as [q IH | q IH |]; intros order [p | p |];
      time_unfold Pos.T_compare_cont; cbn [Pos.size_nat];
      rewrite ?Nat2N.inj_succ;
      try pose proof (IH order p); try pose proof (IH Lt p);
      try pose proof (IH Gt p); lia.
  Qed.

  (** The layout check's strict comparison is charged to the variable it reads second. *)
  Lemma run_pos_ltb_right : forall p q,
    (Pos.T_ltb p q <= N.of_nat (Pos.size_nat q) + 2)%N.
  Proof.
    intros p q. pose proof (compare_cont_right_clock Eq p q) as Hcompare.
    time_unfold Pos.T_ltb. time_unfold Pos.T_compare.
    destruct (Pos.compare p q); time_cbn; lia.
  Qed.

  (** Distinct positives of bounded width fit below a power of two. *)
  Lemma run_distinct_small : forall (xs : list positive) s,
    NoDup xs -> Forall (fun x => Pos.size_nat x <= s) xs -> length xs < 2 ^ s.
  Proof.
    intros xs s Hnodup Hsmall.
    assert (Hmap : NoDup (map Pos.to_nat xs)).
    { apply run_map_nodup; [exact Pos2Nat.inj | exact Hnodup]. }
    assert (Hincl : incl (map Pos.to_nat xs) (seq 1 (2 ^ s - 1))).
    { intros n Hn. apply in_map_iff in Hn. destruct Hn as [x [Hx Hin]]. subst n.
      rewrite in_seq. rewrite Forall_forall in Hsmall.
      pose proof (Hsmall x Hin) as Hsize.
      pose proof (Pos.size_nat_upper x) as Hupper.
      pose proof (Nat.pow_le_mono_r 2 _ _ (Nat.neq_succ_0 1) Hsize) as Hpow.
      pose proof (Pos2Nat.is_pos x) as Hpos. lia. }
    pose proof (NoDup_incl_length Hmap Hincl) as Hlength.
    rewrite length_map, length_seq in Hlength.
    pose proof (Nat.pow_nonzero 2 s (Nat.neq_succ_0 1)) as Hnonzero.
    lia.
  Qed.

  (** Bit sizes of distinct positives sum to at least the size of the largest small class. *)
  Lemma run_distinct_mass : forall (xs : list positive) s,
    (s + 1) * length xs <= fold_right (fun x n => Pos.size_nat x + n) 0 xs +
      (s + 1) * length (filter (fun x => Nat.leb (Pos.size_nat x) s) xs).
  Proof.
    intros xs s. induction xs as [|x xs IH]; cbn [fold_right length filter].
    - lia.
    - assert (Hsize : 1 <= Pos.size_nat x) by (destruct x; cbn [Pos.size_nat]; lia).
      destruct (Nat.leb (Pos.size_nat x) s) eqn:Hleb; cbn [length].
      + nia.
      + apply Nat.leb_gt in Hleb. nia.
  Qed.

  (** The width of the largest counter is paid by the distinct names of a plan. *)
  Lemma run_distinct_key_mass : forall vars, NoDup vars ->
    length vars * Pos.size_nat (N.succ_pos (N.of_nat (length vars))) <=
      2 * run_vars_size vars + 2 * length vars + 1.
  Proof.
    intros vars Hnodup.
    set (m := length vars). set (b := Pos.size_nat (N.succ_pos (N.of_nat m))).
    assert (Hvalue : Pos.to_nat (N.succ_pos (N.of_nat m)) = m + 1).
    { rewrite run_counter_key_value, Nat2N.id. reflexivity. }
    assert (Hsum : fold_right (fun x n => Pos.size_nat x + n) 0 vars <= run_vars_size vars).
    { clear. unfold run_vars_size. induction vars as [|x xs IH]; cbn [fold_right]; lia. }
    destruct (Nat.le_gt_cases b 1) as [Hsmall | Hbig].
    - nia.
    - destruct b as [|[|s]] eqn:Hb; [lia | lia |].
      assert (Hlower : 2 ^ (S s) <= m + 1).
      { pose proof (Pos.size_nat_least (N.succ_pos (N.of_nat m)) (S s)) as Hleast.
        rewrite Hvalue in Hleast. fold b in Hleast. rewrite Hb in Hleast.
        destruct (Nat.lt_ge_cases (m + 1) (2 ^ S s)) as [Hlt | Hge]; [|exact Hge].
        specialize (Hleast Hlt). lia. }
      pose proof (run_distinct_mass vars s) as Hmass.
      assert (Hcount : length (filter (fun x => Nat.leb (Pos.size_nat x) s) vars) < 2 ^ s).
      { apply run_distinct_small.
        - apply NoDup_filter. exact Hnodup.
        - apply Forall_forall. intros x Hx. apply filter_In in Hx. destruct Hx as [_ Hleb].
          apply Nat.leb_le. exact Hleb. }
      cbn [Nat.pow] in Hlower. fold m in Hmass.
      assert (Hprod : (s + 1) * (2 * length (filter (fun x => Nat.leb (Pos.size_nat x) s) vars)
        + 2) <= (s + 1) * (m + 1)).
      { apply Nat.mul_le_mono_l. lia. }
      nia.
  Qed.

  (** A smaller positive has no more bits. *)
  Lemma run_pos_size_mono : forall p q,
    Pos.to_nat p <= Pos.to_nat q -> Pos.size_nat p <= Pos.size_nat q.
  Proof.
    intros p q Hle. apply Pos.size_nat_least.
    pose proof (Pos.size_nat_upper q). lia.
  Qed.

  (** Building the allowed set pays for each variable and the width of its index key. *)
  Lemma run_layout_fresh_time : forall vars bound copies j allowed kb,
    Pos.size_nat (N.succ_pos (j + N.of_nat (length vars))) <= kb ->
    (T_layout_fresh bound copies vars j allowed <=
      16 * (PTrieT.c_trie + 1) * N.of_nat (run_vars_size vars + length vars * kb + 1) +
        run_counter_credit j)%N.
  Proof.
    intro vars. induction vars as [| x vars IH]; intros bound copies j allowed kb Hkb.
    - time_unfold T_layout_fresh. destruct copies; time_cbn; nia.
    - pose proof (run_counter_succ_amort j) as Hstep.
      pose proof (run_pos_ltb_right bound x) as Hltb.
      assert (Hkey : Pos.size_nat (N.succ_pos j) <= kb).
      { eapply Nat.le_trans; [| exact Hkb]. apply run_pos_size_mono.
        rewrite !run_counter_key_value, N2Nat.inj_add, Nat2N.id.
        cbn [length]. lia. }
      assert (Hnext : Pos.size_nat (N.succ_pos (N.succ j + N.of_nat (length vars))) <= kb).
      { eapply Nat.le_trans; [| exact Hkb]. apply run_pos_size_mono.
        rewrite !run_counter_key_value, !N2Nat.inj_add, N2Nat.inj_succ,
          Nat2N.id. cbn [length]. lia. }
      pose proof (N.T_succ_pos_le j) as Hcode.
      pose proof (run_counter_key_bits_lower j) as Hbits.
      pose proof (PTrieT.T_set_le unit (N.succ_pos j) tt allowed) as Hset.
      change (run_vars_size (x :: vars)) with (Pos.size_nat x + 1 + run_vars_size vars).
      cbn [length].
      time_unfold T_layout_fresh. destruct copies as [| copies].
      + pose proof (IH bound 0 (N.succ j) allowed kb Hnext) as Htail.
        destruct (Pos.ltb bound x);
          [pose proof (IH bound 0 (N.succ j) (PTrieCode.set (N.succ_pos j) tt allowed) kb Hnext)
            as Htail_set | ];
          time_cbn; nia.
      + pose proof (IH bound copies (N.succ j) allowed kb Hnext) as Htail.
        destruct (Pos.ltb bound x); time_cbn; nia.
  Qed.

  (** Checking literal sources pays for the positions of the columns it consumes. *)
  Lemma run_layout_literals_time : forall (srcs : list (source V.t)) cols allowed,
    (T_layout_literals srcs cols allowed <=
      16 * (PTrieT.c_trie + 1) * N.of_nat (run_columns_size cols + 1))%N.
  Proof.
    intro srcs. induction srcs as [| src srcs IH]; intros cols allowed.
    - time_unfold @T_layout_literals. destruct cols; time_cbn; nia.
    - destruct cols as [| col cols].
      + time_unfold @T_layout_literals. destruct src; time_cbn; nia.
      + change (run_columns_size (col :: cols)) with
          (run_positions_size col + 1 + run_columns_size cols).
        destruct src as [slot | slot | value].
        * pose proof (IH cols allowed) as Htail.
          time_unfold @T_layout_literals. time_cbn. nia.
        * pose proof (IH cols allowed) as Htail.
          time_unfold @T_layout_literals. time_cbn. nia.
        * destruct col as [| j [| k rest]].
          -- time_unfold @T_layout_literals. time_cbn. nia.
          -- change (run_positions_size [j]) with (j + 1 + 0).
             pose proof (run_nat_n_time j) as Hnat.
             pose proof (N.T_succ_pos_le (nat_n j)) as Hcode.
             pose proof (run_counter_bits_value (nat_n j)) as Hvalue.
             assert (Hnatvalue : N.to_nat (nat_n j) = j) by
               (rewrite run_nat_n_spec, Nat2N.id; reflexivity).
             rewrite Hnatvalue in Hvalue.
             pose proof (run_positive_bits_value (N.succ_pos (nat_n j))) as Hbits.
             rewrite run_position_key_value in Hbits.
             pose proof (PTrieT.T_remove_le unit (N.succ_pos (nat_n j)) allowed) as Hremove.
             pose proof (IH cols allowed) as Htail.
             pose proof (IH cols (PTrieCode.remove (N.succ_pos (nat_n j)) allowed)) as Htail_remove.
             time_unfold @T_layout_literals. PTrieT.trie_get_le.
             destruct (trie_get (N.succ_pos (nat_n j)) allowed); time_cbn; nia.
          -- time_unfold @T_layout_literals. time_cbn. nia.
  Qed.

  (** Checking a layout with names that are already distinct is linear in the plan's text. *)
  Lemma run_layout_ok_at_time : forall bound copies vars (srcs : list (source V.t)) cols,
    NoDup vars ->
    (T_layout_ok_at bound copies vars srcs cols <=
      128 * (PTrieT.c_trie + 1) *
        N.of_nat (run_vars_size vars + run_columns_size cols + 1))%N.
  Proof.
    intros bound copies vars srcs cols Hnodup.
    set (kb := Pos.size_nat (N.succ_pos (N.of_nat (length vars)))).
    pose proof (run_layout_fresh_time vars bound copies 0 Empty kb
      ltac:(rewrite N.add_0_l; subst kb; lia)) as Hfresh.
    pose proof (run_distinct_key_mass vars Hnodup) as Hmass.
    pose proof (run_vars_length vars) as Hlength.
    assert (Hcost : run_vars_size vars + length vars * kb + 1 <= 5 * run_vars_size vars + 2)
      by (subst kb; lia).
    cbn [run_counter_credit] in Hfresh.
    assert (Hscaled : (16 * (PTrieT.c_trie + 1) *
      N.of_nat (run_vars_size vars + length vars * kb + 1) <=
      16 * (PTrieT.c_trie + 1) * (5 * N.of_nat (run_vars_size vars) + 2))%N).
    { apply N.mul_le_mono_l. lia. }
    assert (HK : (1 <= PTrieT.c_trie + 1)%N) by lia.
    time_unfold @T_layout_ok_at.
    destruct (layout_fresh bound copies vars 0 Empty) as [allowed |].
    - pose proof (run_layout_literals_time srcs cols allowed) as Hliterals.
      rewrite !Nat2N.inj_add in Hliterals |- *. time_cbn.
      replace (N.of_nat 0) with 0%N by reflexivity.
      clear -Hfresh Hscaled Hliterals HK. nia.
    - rewrite !Nat2N.inj_add. time_cbn.
      replace (N.of_nat 0) with 0%N by reflexivity.
      clear -Hfresh Hscaled HK. nia.
  Qed.

  (** The non-query checks read each stored plan field once. *)
  Lemma run_check_cplan_overhead : forall ix i n vars stored_post expected count,
    (1 + N.T_eqb ix i + Datatypes.T_length vars + Nat.T_eqb (length vars) n +
      T_var_table vars 0 Empty + T_nat_n n + N.T_eqb count (nat_n n) +
      List.T_rev_append expected [] + T_nats_eqb (rev_append expected []) stored_post <=
      64 * (V.c_key + PTrieT.c_trie + 1) *
        N.of_nat (N.size_nat ix + run_vars_size vars + n + run_positions_size stored_post +
          length expected + 1))%N.
  Proof.
    intros ix i n vars stored_post expected count.
    pose proof (N.T_eqb_le ix i) as Hrule.
    pose proof (Datatypes.T_length_le vars) as Hlength.
    pose proof (Nat.T_eqb_le (length vars) n) as Hvars.
    pose proof (run_var_table_time vars 0 Empty) as Htable.
    cbn [run_counter_credit] in Htable.
    pose proof (run_nat_n_time n) as Hnat.
    pose proof (run_counter_eqb_right count (nat_n n)) as Hcount.
    pose proof (run_counter_bits_value (nat_n n)) as Hbits.
    assert (Hvalue : N.to_nat (nat_n n) = n) by
      (rewrite run_nat_n_spec, Nat2N.id; reflexivity).
    rewrite Hvalue in Hbits.
    pose proof (List.T_rev_append_le expected []) as Hreverse.
    pose proof (run_nats_eqb_time (rev_append expected []) stored_post) as Hpost.
    pose proof (run_vars_length vars) as Hvars_length.
    nia.
  Qed.

  (** Successful name-table construction needs distinct names that the table lacks. *)
  Lemma run_var_table_nodup_fresh : forall vars start table names,
    var_table vars start table = Some names ->
    NoDup vars /\ Forall (fun x => trie_get x table = None) vars.
  Proof.
    intro vars. induction vars as [| key vars IH]; intros start table names Htable.
    - split; constructor.
    - cbn [var_table] in Htable.
      destruct (trie_get key table) as [old |] eqn:Hkey; [discriminate |].
      destruct (IH (N.succ start) (PTrieCode.set key start table) names Htable)
        as [Hnodup Hfresh].
      rewrite Forall_forall in Hfresh.
      split.
      + constructor; [| exact Hnodup]. intro Hin.
        pose proof (Hfresh key Hin) as Hnone. rewrite PTrie.get_set_same in Hnone. discriminate.
      + constructor; [exact Hkey |]. apply Forall_forall. intros y Hy.
        pose proof (Hfresh y Hy) as Hnone.
        destruct (Pos.eq_dec y key) as [Heq | Hneq].
        * subst y. rewrite PTrie.get_set_same in Hnone. discriminate.
        * rewrite PTrie.get_set_other in Hnone by exact Hneq. exact Hnone.
  Qed.

  Lemma run_check_cplan_accepted_time : forall bound copies newok table i q acts c width,
    run_query_width width q ->
    check_cplan_at bound copies V.eqb newok table i (Rule V.t q acts) c = true ->
    (T_check_cplan_at bound copies V.eqb V.T_eqb newok table i (Rule V.t q acts) c <=
      run_check_inner width * N.of_nat (run_cplan_size c))%N.
  Proof.
    intros bound copies newok table i q acts [ix [n columns] srcs vars stored_post] width
      Hwidth Hcheck.
    cbn [check_cplan_at] in Hcheck.
    destruct (N.eqb ix i) eqn:Hrule; [| discriminate].
    destruct (Nat.eqb (length vars) n) eqn:Hvars; [| discriminate].
    destruct (var_table vars 0 Empty) as [names |] eqn:Htable; [| discriminate].
    destruct (layout_ok_at bound copies vars srcs columns) eqn:Hlayout; [| discriminate].
    destruct (check_query V.eqb newok names n table q 0 0 Empty 0 srcs columns [])
      as [[[[count rest_srcs] rest_columns] expected] |] eqn:Hquery; [| discriminate].
    destruct rest_srcs as [| src rest_srcs]; [| discriminate].
    destruct rest_columns as [| col rest_columns]; [| discriminate].
    destruct (N.eqb count (nat_n n)) eqn:Hcount; [| discriminate].
    pose proof (run_nats_eqb_length (rev_append expected []) stored_post Hcheck) as Hpost_length.
    rewrite rev_append_rev, length_app, length_rev in Hpost_length.
    cbn [length] in Hpost_length.
    pose proof (run_positions_length stored_post) as Hpost_mass.
    assert (Hcopy : (0 <= N.of_nat n)%N) by lia.
    pose proof (run_check_query_success_time newok names n table q width 0 0 Empty 0
      srcs columns [] count [] [] expected Hwidth Hcopy Hquery) as Hquery_clock.
    change (run_payload_size [] []) with 0 in Hquery_clock.
    cbn [length run_counter_credit] in Hquery_clock.
    pose proof (run_check_cplan_overhead ix i n vars stored_post expected count) as Hoverhead.
    pose proof (run_var_table_nodup_fresh vars 0 Empty names Htable) as [Hnodup _].
    pose proof (run_layout_ok_at_time bound copies vars srcs columns Hnodup) as Hlayout_clock.
    assert (HK : (PTrieT.c_trie + 1 <= V.c_key + PTrieT.c_trie + 1)%N) by lia.
    assert (Hbudget :
      (run_query_coefficient width * N.of_nat (run_payload_size srcs columns + length expected + 1) +
        128 * (PTrieT.c_trie + 1) *
          N.of_nat (run_vars_size vars + run_columns_size columns + 1) +
        64 * (V.c_key + PTrieT.c_trie + 1) *
          N.of_nat (N.size_nat ix + run_vars_size vars + n + run_positions_size stored_post +
            length expected + 1) <=
        run_check_inner width *
          N.of_nat (run_cplan_size (CPlan V.t ix (JPlan n columns) srcs vars stored_post)))%N).
    { unfold run_query_coefficient, run_check_inner, run_cplan_size, run_payload_size.
      cbn [rule_ix join nvars cols sources var_of Syntax.post].
      clear -Hpost_length Hpost_mass HK. nia. }
    time_unfold @T_check_cplan_at. rewrite Hrule, Hvars, Htable, Hlayout, Hquery, Hcount.
    clear -Hquery_clock Hoverhead Hbudget Hlayout_clock. lia.
  Qed.

  (** Successful name-table construction tracks old entries and bounds new ordinals. *)
  Lemma run_var_table_lookup_range : forall vars start table names,
    var_table vars start table = Some names ->
    forall x ordinal, trie_get x names = Some ordinal ->
      trie_get x table = Some ordinal \/
      (start <= ordinal < start + N.of_nat (length vars))%N.
  Proof.
    intro vars. induction vars as [| key vars IH];
      intros start table names Htable x ordinal Hget.
    - cbn [var_table] in Htable. injection Htable as Hsame. subst names.
      left. exact Hget.
    - cbn [var_table] in Htable.
      destruct (trie_get key table) as [old |] eqn:Hkey; [discriminate |].
      destruct (IH (N.succ start) (PTrieCode.set key start table) names Htable
        x ordinal Hget) as [Hprevious | Hnew].
      + destruct (Pos.eq_dec x key) as [Heq | Hneq].
        * subst x. rewrite PTrie.get_set_same in Hprevious.
          injection Hprevious as Hsame. subst ordinal.
          right. cbn [length]. rewrite Nat2N.inj_succ. lia.
        * left. rewrite PTrie.get_set_other in Hprevious by exact Hneq.
          exact Hprevious.
      + right. cbn [length]. rewrite Nat2N.inj_succ. lia.
  Qed.

  Lemma run_var_table_index_strict : forall vars names,
    var_table vars 0%N Empty = Some names ->
    forall x ordinal, trie_get x names = Some ordinal -> N.to_nat ordinal < length vars.
  Proof.
    intros vars names Htable x ordinal Hget.
    destruct (run_var_table_lookup_range vars 0%N Empty names Htable x ordinal Hget)
      as [Hempty | Hrange].
    - rewrite PTrie.get_empty in Hempty. discriminate.
    - lia.
  Qed.

  Lemma run_var_table_index_bound : forall vars names,
    var_table vars 0%N Empty = Some names ->
    forall x ordinal, trie_get x names = Some ordinal -> N.to_nat ordinal <= length vars.
  Proof.
    intros vars names Htable x ordinal Hget.
    pose proof (run_var_table_index_strict vars names Htable x ordinal Hget). lia.
  Qed.

  Lemma run_check_cplan_general_time : forall bound copies newok table i q acts c width,
    run_query_width width q ->
    (T_check_cplan_at bound copies V.eqb V.T_eqb newok table i (Rule V.t q acts) c <=
      run_check_inner width * N.of_nat (run_cplan_size c + run_query_size q))%N.
  Proof.
    intros bound copies newok table i q acts [ix [n columns] srcs vars stored_post] width Hwidth.
    assert (HK : (PTrieT.c_trie + 1 <= V.c_key + PTrieT.c_trie + 1)%N) by lia.
    assert (Hbudget : forall expected_length, expected_length <= run_query_size q ->
      (run_query_coefficient width * N.of_nat (run_payload_size srcs columns + run_query_size q + 1) +
        2048 * (V.c_key + PTrieT.c_trie + 1) * N.of_nat n +
        128 * (PTrieT.c_trie + 1) *
          N.of_nat (run_vars_size vars + run_columns_size columns + 1) +
        64 * (V.c_key + PTrieT.c_trie + 1) *
          N.of_nat (N.size_nat ix + run_vars_size vars + n + run_positions_size stored_post +
            expected_length + 1) <=
        run_check_inner width *
          N.of_nat (run_cplan_size (CPlan V.t ix (JPlan n columns) srcs vars stored_post) +
            run_query_size q))%N).
    { intros expected_length Hexpected.
      unfold run_query_coefficient, run_check_inner, run_cplan_size, run_payload_size.
      cbn [rule_ix join nvars cols sources var_of Syntax.post].
      clear -Hexpected HK. nia. }
    pose proof (Hbudget 0 (Nat.le_0_l _)) as Hbudget0.
    pose proof (run_check_cplan_overhead ix i n vars stored_post [] 0) as Hbase.
    cbn [length] in Hbase.
    time_unfold @T_check_cplan_at.
    destruct (N.eqb ix i) eqn:Hrule.
    - destruct (Nat.eqb (length vars) n) eqn:Hvars.
      + destruct (var_table vars 0 Empty) as [names |] eqn:Htable.
        * assert (Hnames : forall x ordinal, trie_get x names = Some ordinal ->
            N.to_nat ordinal <= n).
          { intros x ordinal Hget.
            pose proof (run_var_table_index_bound vars names Htable x ordinal Hget).
            apply Nat.eqb_eq in Hvars. lia. }
          assert (Hcopy : (0 <= N.of_nat n)%N) by lia.
          pose proof (run_var_table_nodup_fresh vars 0 Empty names Htable) as [Hnodup _].
          pose proof (run_layout_ok_at_time bound copies vars srcs columns Hnodup)
            as Hlayout_clock.
          destruct (layout_ok_at bound copies vars srcs columns) eqn:Hlayout; cycle 1.
          { clear -Hlayout_clock Hbase Hbudget0. lia. }
          destruct (check_query V.eqb newok names n table q 0 0 Empty 0 srcs columns [])
            as [[[[count rest_srcs] rest_columns] expected] |] eqn:Hquery.
          -- pose proof (run_check_query_success_time newok names n table q width 0 0 Empty 0
               srcs columns [] count rest_srcs rest_columns expected Hwidth Hcopy Hquery)
               as Hquery_success.
             cbn [length run_counter_credit] in Hquery_success.
             pose proof (run_check_query_post_length newok names n table q 0 0 Empty 0
               srcs columns [] count rest_srcs rest_columns expected Hquery) as Hpost_length.
             cbn [length] in Hpost_length.
             pose proof (run_query_length_bits q) as Hquery_length.
             change (length q <= run_query_size q) in Hquery_length.
             assert (Hexpected : length expected <= run_query_size q).
             { clear -Hpost_length Hquery_length. lia. }
             pose proof (Hbudget (length expected) Hexpected) as Hbudget_expected.
             pose proof (run_check_cplan_overhead ix i n vars stored_post expected count) as Hoverhead.
             assert (Hquery_clock :
               (T_check_query V.eqb V.T_eqb newok names n table q 0 0 Empty 0 srcs columns [] <=
                run_query_coefficient width *
                  N.of_nat (run_payload_size srcs columns + run_query_size q + 1) +
                2048 * (V.c_key + PTrieT.c_trie + 1) * N.of_nat n)%N).
             { clear -Hquery_success Hexpected. nia. }
             destruct rest_srcs; destruct rest_columns; destruct (N.eqb count (nat_n n));
               clear -Hquery_clock Hoverhead Hbudget_expected Hlayout_clock; lia.
          -- pose proof (run_check_query_failure_time newok names n table q width 0 0 Empty 0
               srcs columns [] Hwidth Hnames Hcopy Hquery) as Hquery_clock.
             cbn [run_counter_credit] in Hquery_clock.
             clear -Hquery_clock Hbase Hbudget0 Hlayout_clock. lia.
        * clear -Hbase Hbudget0. lia.
      + clear -Hbase Hbudget0. lia.
    - clear -Hbase Hbudget0. lia.
  Qed.

  (** Accepted plans pay their own compiled representation; only a rejected plan pays its query text. *)
  Lemma run_check_cplan_time : forall bound copies newok table i q acts c width,
    run_query_width width q ->
    (T_check_cplan_at bound copies V.eqb V.T_eqb newok table i (Rule V.t q acts) c <=
      run_check_inner width * N.of_nat (run_cplan_size c +
        if check_cplan_at bound copies V.eqb newok table i (Rule V.t q acts) c then 0 else run_query_size q))%N.
  Proof.
    intros bound copies newok table i q acts c width Hwidth.
    destruct (check_cplan_at bound copies V.eqb newok table i (Rule V.t q acts) c) eqn:Hcheck.
    - rewrite Nat.add_0_r. now apply run_check_cplan_accepted_time.
    - now apply run_check_cplan_general_time.
  Qed.
  (** The maximum word width covers every member of the program's encoded words. *)
  Lemma run_word_width : forall p x, In x (program_words V.encode p) ->
    Pos.size_nat x <= wbits p.
  Proof.
    intros p x Hx. unfold wbits. revert Hx.
    generalize (program_words V.encode p) as xs. intro xs.
    induction xs as [|y xs IH]; intro Hx; [contradiction|].
    cbn [fold_right] in *. destruct Hx as [Hx |Hx].
    - subst y. apply Nat.le_max_l.
    - specialize (IH Hx). eapply Nat.le_trans; [exact IH|apply Nat.le_max_r].
  Qed.






  Definition run_cplan_list_size (cs : list (cplan V.t)) : nat :=
    fold_right (fun c n => run_cplan_size c + n) 0 cs.

  Definition run_rules_size (rs : list (rule V.t)) : nat :=
    fold_right (fun r n => rule_bits r + n) 0 rs.


  Lemma run_check_inner_large : forall width, (16 <= run_check_inner width)%N.
  Proof.
    intro width. unfold run_check_inner.
    assert (Hwidth : (1 <= N.of_nat (width + 1))%N) by lia. nia.
  Qed.

  Lemma run_cplan_size_pos : forall c, 1 <= run_cplan_size c.
  Proof.
    intro c. unfold run_cplan_size. lia.
  Qed.

  Lemma run_cplan_list_size_app : forall cs ds,
    run_cplan_list_size (cs ++ ds) = run_cplan_list_size cs + run_cplan_list_size ds.
  Proof.
    intro cs. induction cs as [|c cs IH]; intro ds.
    - reflexivity.
    - change (run_cplan_size c + run_cplan_list_size (cs ++ ds) =
        (run_cplan_size c + run_cplan_list_size cs) + run_cplan_list_size ds).
      rewrite IH. lia.
  Qed.

  Lemma run_compiled_size_breakdown : forall cp,
    size_compiled cp = run_slot_syntax_size (Syntax.slots V.t cp) +
      run_cplan_list_size (naive V.t cp ++ seminaive V.t cp).
  Proof.
    intro cp. unfold size_compiled, run_slot_syntax_size, run_cplan_list_size, run_cplan_size,
      run_columns_size, run_sources_size, run_vars_size, run_positions_size. reflexivity.
  Qed.

  Lemma run_program_size_breakdown : forall p,
    size_program p = fold_right (fun d n => decl_bits d + n) 0 (decls V.t p) +
      run_rules_size (rules V.t p) + 1.
  Proof.
    intro p. reflexivity.
  Qed.

  Lemma run_query_rule_size : forall r,
    run_query_size (query V.t r) + 1 <= rule_bits r.
  Proof.
    intros [q acts]. unfold run_query_size, rule_bits. cbn [query actions]. lia.
  Qed.

  (** Every program query obeys its maximum encoded word width. *)
  Lemma run_program_query_width : forall p,
    Forall (fun r => run_query_width (wbits p) (query V.t r)) (rules V.t p).
  Proof.
    intro p. rewrite Forall_forall. intros r Hr. unfold run_query_width.
    rewrite Forall_forall. intros a Ha. rewrite Forall_forall. intros word Hword.
    apply run_word_width. unfold program_words. apply in_or_app. right.
    apply in_flat_map. exists r. split; [exact Hr|].
    destruct r as [q acts]. apply in_or_app. left. apply in_flat_map.
    exists a. split; assumption.
  Qed.

  Lemma run_fun_count_clock : forall q : list (atom V.t),
    (T_fun_count q <= N.of_nat (run_query_size q + 1))%N.
  Proof.
    intro q. induction q as [|a q IH].
    - time_unfold @T_fun_count. cbn [run_query_size fold_right]. lia.
    - time_unfold @T_fun_count.
      change (run_query_size (a :: q)) with (atom_bits a + run_query_size q).
      destruct a as [f args res |op args res]; cbn [atom_bits]; lia.
  Qed.

  (** A semi-naive prefix retains the budget of the plans it leaves unread. *)
  Lemma run_check_semis_outer : forall bound copies q acts table i C, (16 <= C)%N ->
    (forall c,
      (T_check_cplan_at bound copies V.eqb V.T_eqb true table i (Rule V.t q acts) c <=
        C * N.of_nat (run_cplan_size c +
          if check_cplan_at bound copies V.eqb true table i (Rule V.t q acts) c then 0
          else run_query_size q))%N) ->
    forall k cs,
    (T_check_semis_at bound copies V.eqb V.T_eqb table i (Rule V.t q acts) k cs +
      4 * C * N.of_nat (match check_semis_at bound copies V.eqb table i (Rule V.t q acts) k cs with
        | Some tail => run_cplan_list_size tail | None => 0 end) <=
      4 * C * N.of_nat (run_cplan_list_size cs) +
      C * N.of_nat (match check_semis_at bound copies V.eqb table i (Rule V.t q acts) k cs with
        | Some _ => 0 | None => run_query_size q end) + 4 * C)%N.
  Proof.
    intros bound copies q acts table i C HC Hplan k. induction k as [|k IH]; intro cs.
    - change (1 + 4 * C * N.of_nat (run_cplan_list_size cs) <=
        4 * C * N.of_nat (run_cplan_list_size cs) + C * N.of_nat 0 + 4 * C)%N.
      lia.
    - destruct cs as [|c cs].
      + change (1 + 4 * C * N.of_nat 0 <=
          4 * C * N.of_nat 0 + C * N.of_nat (run_query_size q) + 4 * C)%N.
        nia.
      + pose proof (Hplan c) as Hhead.
        pose proof (IH cs) as Htail.
        pose proof (run_cplan_size_pos c) as Hsize.
        (* These conversions expose one recursive step only. In particular,
           check_cplan and N arithmetic remain as named applications. *)
        change (T_check_semis_at bound copies V.eqb V.T_eqb table i (Rule V.t q acts) (S k) (c :: cs))
          with (1 + (T_check_cplan_at bound copies V.eqb V.T_eqb true table i (Rule V.t q acts) c +
            (if check_cplan_at bound copies V.eqb true table i (Rule V.t q acts) c
             then T_check_semis_at bound copies V.eqb V.T_eqb table i (Rule V.t q acts) k cs
             else 0)))%N.
        change (check_semis_at bound copies V.eqb table i (Rule V.t q acts) (S k) (c :: cs))
          with (if check_cplan_at bound copies V.eqb true table i (Rule V.t q acts) c
            then check_semis_at bound copies V.eqb table i (Rule V.t q acts) k cs else None).
        change (run_cplan_list_size (c :: cs))
          with (run_cplan_size c + run_cplan_list_size cs).
        destruct (check_cplan_at bound copies V.eqb true table i (Rule V.t q acts) c) eqn:Hcheck.
        * rewrite ?Hcheck in Hhead. rewrite Nat.add_0_r in Hhead.
          destruct (check_semis_at bound copies V.eqb table i (Rule V.t q acts) k cs) as [tail |]
            eqn:Hresult in Htail |- *;
            cbv beta iota zeta in Htail |- *;
            rewrite !Nat2N.inj_add;
            clear -HC Hhead Htail Hsize; nia.
        * rewrite ?Hcheck in Hhead.
          cbv beta iota zeta in Hhead |- *.
          rewrite !Nat2N.inj_add in Hhead |- *.
          clear -HC Hhead Hsize. nia.
  Qed.

  Definition run_rule_cplan_bound (C : N) (table : ptrie (N * (positive * list nat)))
      (r : rule V.t) : Prop :=
    forall newok i c,
      (T_check_cplan_at (query_max (query V.t r) 1%positive) (query_copies (query V.t r) 0)
        V.eqb V.T_eqb newok table i r c <=
        C * N.of_nat (run_cplan_size c +
          if check_cplan_at (query_max (query V.t r) 1%positive) (query_copies (query V.t r) 0)
            V.eqb newok table i r c then 0
          else run_query_size (query V.t r)))%N.

  (** Rule checking charges its first rejected plan's query only once. *)
  Lemma run_check_rule_plans_outer : forall C table, (64 <= C)%N ->
    forall rs i nv sn, Forall (run_rule_cplan_bound C table) rs ->
    (T_check_rule_plans_at V.eqb V.T_eqb table rs i nv sn <=
      4 * C * N.of_nat (run_rules_size rs + run_cplan_list_size nv +
        run_cplan_list_size sn + 1) + run_counter_credit i)%N.
  Proof.
    intros C table HC rs. induction rs as [|[q acts] rs IH]; intros i nv sn Hbounds.
    - destruct nv as [|c nv]; destruct sn as [|c' sn];
        time_unfold @T_check_rule_plans_at;
        change (run_rules_size []) with 0%nat;
        cbv beta iota zeta; nia.
    - destruct nv as [|c nv].
      + time_unfold @T_check_rule_plans_at. cbv beta iota zeta. nia.
      + inversion Hbounds as [|r rs' Hbound Hrest]; subst r rs'.
        pose proof (Hbound false i c) as Hhead. cbn [query] in Hhead.
        pose proof (run_check_semis_outer (query_max q 1%positive) (query_copies q 0) q acts
          table i C ltac:(lia) (Hbound true i)
          (fun_count q) sn) as Hsemis.
        pose proof (run_fun_count_clock q) as Hfun.
        pose proof (run_query_max_clock q 1%positive) as Hmax.
        pose proof (run_query_copies_clock q 0) as Hcopies.
        change (fold_right (fun a n => (atom_bits a + n)%nat) 0%nat q) with (run_query_size q)
          in Hmax, Hcopies.
        rewrite !Nat2N.inj_add in Hmax, Hcopies.
        pose proof (run_counter_succ_amort i) as Hsucc.
        pose proof (run_query_rule_size (Rule V.t q acts)) as Hqsize.
        pose proof (run_cplan_size_pos c) as Hcsize.
        change (run_query_size q + 1 <= rule_bits (Rule V.t q acts)) in Hqsize.
        time_unfold @T_check_rule_plans_at.
        change (run_rules_size (Rule V.t q acts :: rs)) with
          (rule_bits (Rule V.t q acts) + run_rules_size rs).
        change (run_cplan_list_size (c :: nv)) with
          (run_cplan_size c + run_cplan_list_size nv).
        assert (Hscan : (65 * N.of_nat (run_query_size q + 1) + 4 + C <=
          4 * C * N.of_nat (rule_bits (Rule V.t q acts)))%N).
        { assert (Hrule : (N.of_nat (run_query_size q + 1) <= N.of_nat (rule_bits (Rule V.t q acts)))%N)
            by lia.
          assert (Hone : (1 <= N.of_nat (run_query_size q + 1))%N) by lia.
          set (Q := N.of_nat (run_query_size q + 1)) in *.
          set (R := N.of_nat (rule_bits (Rule V.t q acts))) in *.
          clear -HC Hrule Hone. nia. }
        destruct (check_cplan_at (query_max q 1%positive) (query_copies q 0) V.eqb false table i
          (Rule V.t q acts) c) eqn:Hcheck.
        * rewrite ?Hcheck in Hhead. rewrite Nat.add_0_r in Hhead.
          destruct (check_semis_at (query_max q 1%positive) (query_copies q 0) V.eqb table i
            (Rule V.t q acts) (fun_count q) sn)
            as [tail |] eqn:Hsemi in Hsemis |- *.
          -- pose proof (IH (N.succ i) nv tail Hrest) as Htail.
             cbv beta iota zeta in Hsemis |- *.
             rewrite !Nat2N.inj_add in Htail |- *.
             rewrite ?Nat2N.inj_add in *.
             clear -HC Hhead Hsemis Hfun Hsucc Hqsize Hcsize Htail Hmax Hcopies Hscan. nia.
          -- cbv beta iota zeta in Hsemis |- *.
             rewrite !Nat2N.inj_add.
             rewrite ?Nat2N.inj_add in *.
             clear -HC Hhead Hsemis Hfun Hqsize Hcsize Hmax Hcopies Hscan. nia.
        * rewrite ?Hcheck in Hhead.
          change (T_check_cplan_at (query_max q 1%positive) (query_copies q 0) V.eqb V.T_eqb false table
            i (Rule V.t q acts) c <=
            C * N.of_nat (run_cplan_size c + run_query_size q))%N in Hhead.
          cbv beta iota zeta.
          rewrite !Nat2N.inj_add in Hhead |- *.
          rewrite ?Nat2N.inj_add in *.
          clear -HC Hhead Hqsize Hcsize Hmax Hcopies Hscan. nia.
  Qed.

  (** The outer checker needs only the per-plan bound and the already checked prefix clocks. *)
  Lemma run_check_shape_from_cplans :
    (forall bound copies newok table i q acts c width, run_query_width width q ->
      (T_check_cplan_at bound copies V.eqb V.T_eqb newok table i (Rule V.t q acts) c <=
        (4 * 1024) * (V.c_key + PTrieT.c_trie + 1) *
          N.of_nat (run_cplan_size c +
            if check_cplan_at bound copies V.eqb newok table i (Rule V.t q acts) c then 0
            else run_query_size q) * N.of_nat (width + 1))%N) ->
    forall p cp,
    (T_check_shape p cp <= k_check * N.of_nat (size_program p + size_compiled cp + 1) *
      N.of_nat (wbits p + 1))%N.
  Proof.
    intros Hinner [ds rs] [sl nv sn].
    set (p := Program V.t ds rs). set (cp := Compiled V.t sl nv sn).
    set (width := wbits p). set (C := run_check_inner width).
    assert (HC : (16 <= C)%N) by apply run_check_inner_large.
    assert (Hfront : (128 * (PTrieT.c_trie + 1) <= C)%N).
    { unfold C, run_check_inner.
      assert (Hw : (1 <= N.of_nat (width + 1))%N) by lia. nia. }
    assert (HC64 : (64 <= C)%N) by (clear -Hfront; lia).
    assert (Hconstant : (k_check * N.of_nat (width + 1) = 16 * C)%N).
    { unfold C, run_check_inner, k_check. nia. }
    assert (Hbudget : forall n,
      (k_check * N.of_nat n * N.of_nat (width + 1) = 16 * C * N.of_nat n)%N).
    { intro n. clear -Hconstant. nia. }
    assert (Hrules : forall table, Forall (run_rule_cplan_bound C table) rs).
    { intro table. pose proof (run_program_query_width p) as Hwidth.
      change (Forall (fun r => run_query_width width (query V.t r)) rs) in Hwidth.
      rewrite Forall_forall in Hwidth |- *. intros [q acts] Hr newok i c.
      pose proof (Hinner (query_max q 1%positive) (query_copies q 0) newok table i q acts c width
        (Hwidth (Rule V.t q acts) Hr)) as Hc.
      change (T_check_cplan_at (query_max q 1%positive) (query_copies q 0) V.eqb V.T_eqb newok
        table i (Rule V.t q acts) c <=
        C * N.of_nat (run_cplan_size c +
          if check_cplan_at (query_max q 1%positive) (query_copies q 0) V.eqb newok table i
            (Rule V.t q acts) c then 0
          else run_query_size q))%N.
      unfold C, run_check_inner. clear -Hc. nia. }
    assert (Hsize : size_program p + size_compiled cp + 1 =
      fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds + run_rules_size rs +
        run_slot_syntax_size sl + run_cplan_list_size nv + run_cplan_list_size sn + 2).
    { unfold p, cp.
      rewrite run_program_size_breakdown, run_compiled_size_breakdown,
        run_cplan_list_size_app.
      change ((fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds + run_rules_size rs + 1) +
        (run_slot_syntax_size sl + (run_cplan_list_size nv + run_cplan_list_size sn)) + 1 =
        fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds + run_rules_size rs +
          run_slot_syntax_size sl + run_cplan_list_size nv + run_cplan_list_size sn + 2).
      lia. }
    pose proof (run_decl_widths_time ds Empty) as Hdecls.
    pose proof (run_slot_table_time (decl_widths ds Empty) sl 0 Empty) as Hslots.
    change (run_counter_credit 0%N) with 0%N in Hslots.
    rewrite N.add_0_r in Hslots.
    change (T_check_shape p cp <= k_check *
      N.of_nat (size_program p + size_compiled cp + 1) * N.of_nat (width + 1))%N.
    rewrite Hbudget, Hsize.
    clearbody C.
    assert (Hdecls_scaled : (T_decl_widths ds Empty <= C *
      N.of_nat (fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds + 1))%N).
    { eapply N.le_trans; [exact Hdecls|].
      apply N.mul_le_mono_r. clear -Hfront. lia. }
    assert (Hslots_scaled : (T_slot_table (decl_widths ds Empty) sl 0 Empty <=
      C * N.of_nat (run_slot_syntax_size sl + 1))%N).
    { eapply N.le_trans; [exact Hslots|].
      apply N.mul_le_mono_r. exact Hfront. }
    pose proof (N.add_le_mono _ _ _ _ Hdecls_scaled Hslots_scaled) as Hprefix.
    change (T_check_shape (Program V.t ds rs) (Compiled V.t sl nv sn) <=
      16 * C * N.of_nat (fold_right (fun d n => (decl_bits d + n)%nat) 0%nat ds +
        run_rules_size rs + run_slot_syntax_size sl + run_cplan_list_size nv +
        run_cplan_list_size sn + 2))%N.
    time_unfold T_check_shape. time_unfold @T_check_shape_with.
    change (fun a b : V.t => V.T_eqb a b) with V.T_eqb.
    destruct (slot_table (decl_widths ds Empty) sl 0 Empty) as [table |] eqn:Htable.
    - pose proof (run_check_rule_plans_outer C table HC64 rs 0 nv sn (Hrules table)) as Hplans.
      change (run_counter_credit 0%N) with 0%N in Hplans.
      rewrite N.add_0_r in Hplans.
      pose proof (N.add_le_mono _ _ _ _ Hprefix Hplans) as Htotal.
      cbv beta iota zeta.
      rewrite !Nat2N.inj_add in Htotal |- *.
      rewrite !N.mul_add_distr_l in Htotal |- *.
      clear -HC Htotal. nia.
    - cbv beta iota zeta.
      rewrite !Nat2N.inj_add in Hprefix |- *.
      rewrite !N.mul_add_distr_l in Hprefix |- *.
      clear -HC Hprefix. nia.
  Qed.

  Lemma T_check_shape_le : forall p cp,
    (T_check_shape p cp <= k_check * N.of_nat (size_program p + size_compiled cp + 1) *
      N.of_nat (wbits p + 1))%N.
  Proof.
    intros p cp. apply run_check_shape_from_cplans.
    intros bound copies newok table i q acts c width Hwidth.
    pose proof (run_check_cplan_time bound copies newok table i q acts c width Hwidth) as Hplan.
    unfold run_check_inner in Hplan. clear -Hplan. nia.
  Qed.

  Lemma T_check_plan_le : forall p cp,
    (T_check_plan p cp <= c_run * N.of_nat (size_program p + size_compiled cp + 1) *
      N.of_nat (wbits p + 1))%N.
  Proof.
    intros p cp. apply run_check_plan_from_shape. apply T_check_shape_le.
  Qed.

  (** A binding traversal pays for each variable's lookup and optional insertion once. *)
  Lemma bind_cells_clock_le : forall vars (cells : list (cell V.t)) t,
    (T_bind_cells vars cells t <= 16 *
      N.of_nat (fold_right (fun x n => (Pos.size_nat x + 1 + n)%nat) 0%nat vars + 1))%N.
  Proof.
    intro vars. induction vars as [|x xs IH]; intros cells t.
    - time_unfold @T_bind_cells. time_simpl. time_cbn. nia.
    - destruct cells as [|c cs].
      + time_unfold @T_bind_cells. time_simpl. time_cbn.
        rewrite !Nat2N.inj_add. nia.
      + pose proof (IH cs t) as Hkeep.
        pose proof (IH cs (PTrieCode.set x c t)) as Hnew.
        pose proof (PTrieT.replace_clock_bound (cell V.t) x (Some c) t) as Hset.
        time_unfold @T_bind_cells. time_simpl. time_cbn.
        unfold PTrieCode.T_set. PTrieT.trie_get_le.
        destruct (trie_get x t); cbn [fold_right];
          rewrite !Nat2N.inj_add in *; nia.
  Qed.

  (** The wrapper adds only its own call and the variable-field reader. *)
  Lemma bind_trie_clock_le : forall c b,
    (T_bind_trie c b <= 32 *
      N.of_nat (fold_right (fun x n => (Pos.size_nat x + 1 + n)%nat) 0%nat
        (var_of V.t c) + 1))%N.
  Proof.
    intros c b. pose proof (bind_cells_clock_le (plan_vars c) b Empty) as Hcells.
    destruct c as [ix j srcs vars post].
    time_unfold T_bind_trie. time_simpl. time_cbn.
    cbn [plan_vars] in Hcells. nia.
  Qed.

  (** Building the trie of a binding pays for the bits of the plan's variables. *)
  Lemma T_bind_trie_le : forall c b,
    (T_bind_trie c b <= k_driver *
      N.of_nat (fold_right (fun x n => (Pos.size_nat x + 1 + n)%nat) 0%nat
        (var_of V.t c) + 1))%N.
  Proof.
    intros c b.
    pose proof (bind_trie_clock_le c b) as Hbind.
    unfold k_driver. nia.
  Qed.

  Definition keep_width_program : program V.t :=
    Program V.t [] [Rule V.t [Fun V.t 1%positive [Var 1%positive; Var 1%positive] None] []].

  Definition keep_width_plan (z : positive) : cplan V.t :=
    CPlan V.t 0%N (JPlan 0 []) [] [z] [0].

  (** A bound copy name makes the first copy-name lookup pay its full width. *)
  Lemma keep_width_clock_lower : forall z,
    (N.of_nat (Pos.size_nat z) <=
      T_keep keep_width_program (keep_width_plan z)
        (bind_trie (keep_width_plan z) [Id 1%positive]))%N.
  Proof.
    intro z.
    unfold T_keep, keep_width_program, keep_width_plan, bind_trie.
    cbn [plan_rule_ix rules rule_at plan_post plan_vars bind_cells].
    rewrite trie_get_empty.
    time_unfold @T_rule_at. time_unfold @T_keep_post.
    time_simpl. time_cbn.
    time_unfold @T_copies_ok. time_simpl. time_cbn.
    time_unfold @T_copies_ok. time_simpl. time_cbn.
    time_simpl. time_cbn.
    match goal with
    | |- context [T_trie_get z ?bound] =>
      assert (Hhit : T_trie_get z bound = N.of_nat (Pos.size_nat z))
    end.
    { apply PTrieT.T_trie_get_hit.
      change (PTrieCode.get z (PTrieCode.set z (@Id V.t 1%positive) Empty) <> None).
      rewrite PTrie.get_set_same. discriminate. }
    lia.
  Qed.

  (** Every charged measure stays fixed while the copy name grows. *)
  Lemma keep_width_work_fixed : forall z,
    post_work keep_width_program (keep_width_plan z) = 3%nat /\
    rule_work keep_width_program (keep_width_plan z) = 2%nat /\
    wbits keep_width_program = 1%nat /\
    query_prim_work V.prim_work (query V.t (job_rule keep_width_program
      (keep_width_plan z))) (env_of (keep_width_plan z) [Id 1%positive]) = 0%N.
  Proof.
    intro z. repeat split; reflexivity.
  Qed.

  (** Positive keys can have any nonzero width. *)
  Lemma keep_width_key_exists : forall n, exists z, Pos.size_nat z = S n.
  Proof.
    induction n as [|n [z Hz]].
    - exists 1%positive. reflexivity.
    - exists (xO z). cbn [Pos.size_nat]. now rewrite Hz.
  Qed.

  (** The old filter bound, which omitted copied-variable name widths, has no fixed constant. *)
  Lemma keep_width_unbounded : forall k : N, exists z,
    (10 * k < T_keep keep_width_program (keep_width_plan z)
      (bind_trie (keep_width_plan z) [Id 1%positive]))%N.
  Proof.
    intro k.
    destruct (keep_width_key_exists (N.to_nat (10 * k)%N)) as [z Hz].
    exists z. pose proof (keep_width_clock_lower z) as Hclock.
    rewrite Hz, Nat2N.inj_succ, N2Nat.id in Hclock. lia.
  Qed.

  (** The proposed filter contract fails for every replacement of its constant. *)
  Lemma keep_bound_counterexample : forall k : N, exists p c b,
    ~ (T_keep p c (bind_trie c b) <= k * N.of_nat (post_work p c + 1) *
      N.of_nat (wbits p + fold_right (fun x n => Nat.max (cell_bits V.encode x) n) 0%nat b + 1) +
      k * query_prim_work V.prim_work (query V.t (job_rule p c)) (env_of c b) +
      k * N.of_nat (rule_work p c))%N.
  Proof.
    intro k. destruct (keep_width_unbounded (2 * k)) as [z Hlarge].
    exists keep_width_program, (keep_width_plan z), [Id 1%positive].
    destruct (keep_width_work_fixed z) as [Hpost [Hrule [Hwidth Hprim]]].
    rewrite Hpost, Hrule, Hwidth, Hprim. cbn [fold_right cell_bits Pos.size_nat Nat.max].
    intro Hbound. nia.
  Qed.
  (** * Round scheduling costs *)

  (** A program literal is one of the encoded words used by its width measure. *)
  Lemma run_split_literal_word : forall p v, In (Lit v) (program_terms p) ->
    In (V.encode v) (program_words V.encode p).
  Proof.
    intros p v Hin. unfold program_terms in Hin.
    apply in_flat_map in Hin as [[q acts] [Hrule Hin]].
    unfold program_words. apply in_or_app. right. apply in_flat_map.
    exists (Rule V.t q acts). split; [exact Hrule|].
    apply in_app_or in Hin as [Hin|Hin].
    - apply in_or_app. left. apply in_flat_map in Hin as [a [Ha Hliteral]].
      apply in_flat_map. exists a. split; [exact Ha|].
      destruct a as [f args res|f args res]; cbn [atom_terms atom_words] in *;
        right; apply in_flat_map; exists (Lit v); split; try exact Hliteral; now left.
    - apply in_or_app. right. apply in_flat_map in Hin as [a [Ha Hliteral]].
      apply in_flat_map. exists a. split; [exact Ha|].
      destruct a as [x f args|f args res|a b|x f args];
        cbn [action_terms action_words] in *.
      + right. right. apply in_flat_map. exists (Lit v).
        split; [exact Hliteral|now left].
      + right. apply in_flat_map. exists (Lit v).
        split; [exact Hliteral|now left].
      + destruct Hliteral as [Hliteral|[Hliteral|[]]].
        * subst a. apply in_or_app. left. now left.
        * subst b. apply in_or_app. right. now left.
      + right. right. apply in_flat_map. exists (Lit v).
        split; [exact Hliteral|now left].
  Qed.

  (** The cell tag adds one bit to a literal's program word. *)
  Lemma run_split_literal_width : forall p v, In (Lit v) (program_terms p) ->
    cell_bits V.encode (Val v) <= wbits p + 1.
  Proof.
    intros p v Hin.
    pose proof (run_word_width p (V.encode v) (run_split_literal_word p v Hin)) as Hword.
    cbn [cell_bits Pos.size_nat]. lia.
  Qed.

  (** Binary and unary bit counts agree for positive words. *)
  Lemma run_split_size_value : forall x,
    Pos.to_nat (Pos.size x) = Pos.size_nat x.
  Proof.
    induction x as [x IH|x IH|]; cbn [Pos.size Pos.size_nat];
      rewrite ?Pos2Nat.inj_succ; lia.
  Qed.

  (** The logarithm used by index lookup is at most the stored slot width. *)
  Lemma run_split_log2_size : forall n, N.to_nat (N.log2 n) <= N.size_nat n.
  Proof.
    intros [|[x|x|]]; cbn [N.log2 N.to_nat N.size_nat Pos.size_nat];
      rewrite ?run_split_size_value; lia.
  Qed.

  (** Rule lookup walks no more than the rule list at the original counter width. *)
  Lemma run_split_rule_clock : forall n (rs : list (rule V.t)),
    (T_rule_at n rs <= 8 * N.of_nat ((length rs + 1) * (N.size_nat n + 1)))%N.
  Proof.
    intros n rs. revert n. induction rs as [|r rs IH]; intro n.
    - time_unfold @T_rule_at. cbn [length]. rewrite !Nat2N.inj_mul, !Nat2N.inj_add. nia.
    - destruct n as [|x].
      + time_unfold @T_rule_at. cbn [length N.size_nat].
        rewrite !Nat2N.inj_mul, !Nat2N.inj_add, !Nat2N.inj_succ. nia.
      + pose proof (IH (N.pred (Npos x))) as Htail.
        pose proof (N.T_pred_le (Npos x)) as Hpred.
        pose proof (N.size_nat_pred_N x) as Hwidth.
        change (N.size_nat (N.pred (Npos x)) <= N.size_nat (Npos x)) in Hwidth.
        time_unfold @T_rule_at. cbn [length].
        rewrite !Nat2N.inj_mul, !Nat2N.inj_add, !Nat2N.inj_succ in *.
        nia.
  Qed.

  (** A source's syntactic charge counts the slot width or one literal entry. *)
  Definition run_split_source_weight (src : source V.t) : nat :=
    match src with
    | All _ slot | New _ slot => N.size_nat slot + 1
    | Const _ _ => 1
    end.

  Lemma run_split_source_positive : forall src, 1 <= run_split_source_weight src.
  Proof.
    intros [slot|slot|value]; cbn [run_split_source_weight]; lia.
  Qed.

  (** Reading a source pays for its slot number or for its program literal. *)
  Lemma run_split_source_clock : forall p db src,
    (match src with Const _ c => exists v, c = Val v /\ In (Lit v) (program_terms p)
    | _ => True end) ->
    (T_source_ix db src <= 16 * (D.c_db + I.c_ix + 1) *
      N.of_nat (run_split_source_weight src) * N.of_nat (wbits p + 1))%N.
  Proof.
    intros p db [slot|slot|value] Hsafe.
    - pose proof (D.T_index_le slot false db) as Hindex.
      pose proof (run_split_log2_size slot) as Hwidth.
      time_unfold T_source_ix. cbn [run_split_source_weight].
      assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia.
      rewrite !Nat2N.inj_add in *. nia.
    - pose proof (D.T_index_le slot true db) as Hindex.
      pose proof (run_split_log2_size slot) as Hwidth.
      time_unfold T_source_ix. cbn [run_split_source_weight].
      assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia.
      rewrite !Nat2N.inj_add in *. nia.
    - destruct Hsafe as [v [-> Hliteral]].
      pose proof (run_split_literal_width p v Hliteral) as Hliteralwidth.
      pose proof (I.width_le I.empty [Val v]) as Hwidth.
      rewrite I.next_empty, I.max_cell_bits_empty in Hwidth.
      cbn [length Pos.of_nat Pos.add Pos.size_nat fold_right] in Hwidth.
      rewrite Nat.max_0_r, Nat.add_0_r in Hwidth.
      pose proof (I.T_insert_le 1 [Val v] I.empty (I.wf_empty 1)) as Hinsert.
      pose proof I.T_empty_le as Hempty.
      time_unfold T_source_ix. cbn [run_split_source_weight length] in *.
      rewrite !Nat2N.inj_add in *. nia.
  Qed.

  (** Reading the source list adds one map step to each charged source. *)
  Lemma run_split_sources_clock : forall p db srcs,
    Forall (fun src => match src with
      | Const _ c => exists v, c = Val v /\ In (Lit v) (program_terms p)
      | _ => True end) srcs ->
    (ListDef.T_map (source_ix db) (T_source_ix db) srcs <=
      32 * (D.c_db + I.c_ix + 1) *
      N.of_nat (fold_right (fun src n => (run_split_source_weight src + n)%nat) 0%nat srcs + 1) *
      N.of_nat (wbits p + 1))%N.
  Proof.
    intros p db srcs Hsafe. induction Hsafe as [|src srcs Hhead Hrest IH].
    - time_unfold @ListDef.T_map. cbn [fold_right].
      assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia. nia.
    - pose proof (run_split_source_clock p db src Hhead) as Hsource.
      pose proof (run_split_source_positive src) as Hpositive.
      time_unfold @ListDef.T_map. cbn [fold_right].
      assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia.
      rewrite !Nat2N.inj_add in *. nia.
  Qed.

  Lemma run_split_sources_weight : forall c,
    fold_right (fun src n => run_split_source_weight src + n) 0 (sources V.t c) =
      source_bits c.
  Proof.
    intro c. unfold source_bits. generalize (sources V.t c) as srcs. intro srcs.
    induction srcs as [|src srcs IH]; [reflexivity|].
    destruct src; cbn [fold_right run_split_source_weight]; now rewrite IH.
  Qed.

  Lemma run_split_sum_app : forall (A : Type) (f : A -> N) xs ys,
    fold_right N.add 0%N (map f (xs ++ ys)) =
      (fold_right N.add 0%N (map f xs) + fold_right N.add 0%N (map f ys))%N.
  Proof.
    intros A f xs ys. induction xs as [|x xs IH]; cbn [app map fold_right];
      rewrite ?IH; lia.
  Qed.

  Lemma run_split_sum_const : forall (A : Type) (xs : list A) k,
    fold_right N.add 0%N (map (fun _ => k) xs) = (N.of_nat (length xs) * k)%N.
  Proof.
    intros A xs k. induction xs as [|x xs IH]; cbn [map fold_right length];
      rewrite ?IH, ?Nat2N.inj_succ; nia.
  Qed.

  Lemma run_split_filter_length : forall (A : Type) (f : A -> bool) xs,
    length (filter f xs) <= length xs.
  Proof.
    intros A f xs. induction xs as [|x xs IH]; cbn [filter length]; [lia|].
    destruct (f x); cbn [length]; lia.
  Qed.

  (** Job scheduling reads the variable names and the rule index once. *)
  Definition run_split_job_weight (p : program V.t) (c : cplan V.t) : nat :=
    fold_right (fun x n => Pos.size_nat x + 1 + n) 0 (var_of V.t c) +
      rule_work p c + 1.

  (** The shell pays for source construction and for every candidate binding. *)
  Definition run_split_plan_weight (p : program V.t) (cp : compiled V.t) (db : D.t)
      (c : cplan V.t) : nat :=
    source_bits c + 2 + length (bindings cp c db) * run_split_job_weight p c.

  (** The public plan budget includes the smaller source-and-scheduling shell. *)
  Lemma run_split_budget_arithmetic : forall jw ls sb nv lb vb pw rw aw primitive,
    sb + 2 + lb * (vb + rw + 1) <=
      (jw + ls + sb + 2) * (nv + 1) * (nv + 1) +
      lb * (vb + pw + rw + 1 + aw) + primitive.
  Proof.
    intros jw ls sb nv lb vb pw rw aw primitive.
    assert (Hsource : sb + 2 <= (jw + ls + sb + 2) * (nv + 1) * (nv + 1)).
    { assert (Hfirst : jw + ls + sb + 2 <= (jw + ls + sb + 2) * (nv + 1)) by nia.
      assert (Hsecond : (jw + ls + sb + 2) * (nv + 1) <=
        (jw + ls + sb + 2) * (nv + 1) * (nv + 1)).
      { set (base := (jw + ls + sb + 2) * (nv + 1)). nia. }
      lia. }
    assert (Hbindings : lb * (vb + rw + 1) <= lb * (vb + pw + rw + 1 + aw)).
    { apply Nat.mul_le_mono_l. lia. }
    lia.
  Qed.

  Lemma run_split_work_bound : forall p cp (nv : bool) db,
    fold_right Nat.add 0%nat (map (run_split_plan_weight p cp db)
      (if nv then naive V.t cp else seminaive V.t cp)) <= round_work p cp nv db.
  Proof.
    intros p cp nv db. unfold round_work.
    eapply Nat.le_trans; [|apply Nat.le_add_l].
    generalize (if nv then naive V.t cp else seminaive V.t cp) as cs. intro cs.
    induction cs as [|c cs IH]; cbn [map fold_right]; [lia|].
    apply Nat.add_le_mono; [|exact IH].
    unfold run_split_plan_weight, run_split_job_weight. apply run_split_budget_arithmetic.
  Qed.

  (** A binding enumeration pays its join clock and its source-list construction. *)
  Lemma run_split_bindings_clock : forall p cp db c,
    plans_ok p cp -> In c (all_plans cp) ->
    (T_plan_bindings cp c db <=
      J.T_run (join V.t c) (map (source_index db) (sources V.t c)) +
      64 * (D.c_db + I.c_ix + 1) * N.of_nat (source_bits c + 2) *
        N.of_nat (wbits p + 1))%N.
  Proof.
    intros p cp db c Hplans Hc.
    pose proof (run_split_sources_clock p db (sources V.t c)
      (run_plan_constants p cp c Hplans Hc)) as Hsources.
    rewrite run_split_sources_weight in Hsources.
    time_unfold T_plan_bindings. time_simpl. time_cbn.
    change (plan_sources c) with (sources V.t c) in *.
    change (plan_join c) with (join V.t c) in *.
    change (source_index db) with (source_ix db) in *.
    change (fun src : source V.t => T_source_ix db src) with (T_source_ix db) in *.
    assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia.
    rewrite !Nat2N.inj_add in *. nia.
  Qed.

  (** Job application pays the action clocks plus binding and rule-lookup overhead. *)
  Lemma run_split_apply_clock : forall p js db,
    (T_apply_all p js db <= T_apply_jobs p js db + 64 *
      fold_right N.add 0%N (map (fun job =>
        N.of_nat (run_split_job_weight p (fst job))) js) + 1)%N.
  Proof.
    intros p js. induction js as [|[c b] js IH]; intro db.
    - time_unfold T_apply_all. cbn [T_apply_jobs map fold_right]. lia.
    - pose proof (IH (apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b)) db)) as Htail.
      pose proof (bind_trie_clock_le c b) as Hbind.
      pose proof (run_split_rule_clock (rule_ix V.t c) (rules V.t p)) as Hrule.
      change (T_rule_at (rule_ix V.t c) (rules V.t p) <=
        8 * N.of_nat (rule_work p c))%N in Hrule.
      time_unfold T_apply_all. time_simpl. time_cbn.
      rewrite rule_at_nth. cbn [T_apply_jobs map fold_right fst].
      change (plan_rule_ix c) with (rule_ix V.t c) in *.
      change (nth (N.to_nat (rule_ix V.t c)) (rules V.t p) (Rule V.t [] []))
        with (job_rule p c) in *.
      unfold run_split_job_weight in *. rewrite !Nat2N.inj_add in *. lia.
  Qed.

  (** Removing failed bindings cannot raise the scheduling weight. *)
  Lemma run_split_jobs_weight : forall p cp nv db,
    (fold_right N.add 0%N (map (fun job => N.of_nat (run_split_job_weight p (fst job)))
      (jobs p cp nv db)) <= N.of_nat (fold_right Nat.add 0%nat
        (map (run_split_plan_weight p cp db)
          (if nv then naive V.t cp else seminaive V.t cp))))%N.
  Proof.
    intros p cp nv db. rewrite jobs_def.
    generalize (if nv then naive V.t cp else seminaive V.t cp) as cs. intro cs.
    induction cs as [|c cs IH]; cbn [flat_map map fold_right]; [reflexivity|].
    rewrite run_split_sum_app, map_map. cbn [fst].
    rewrite run_split_sum_const, Nat2N.inj_add.
    apply N.add_le_mono; [|exact IH].
    pose proof (run_split_filter_length (list (cell V.t))
      (fun b => keep p c (bind_trie c b)) (bindings cp c db)) as Hlength.
    unfold run_split_plan_weight. rewrite !Nat2N.inj_add, !Nat2N.inj_mul. nia.
  Qed.

  (** Filtering candidates preserves their exact trie-building and filter clocks. *)
  Lemma run_split_filter_bindings_clock : forall p c bs,
    (List.T_filter (fun b => keep p c (bind_trie c b))
      (fun b => 1 + (T_bind_trie c b + T_keep p c (bind_trie c b))) bs <=
      fold_right N.add 0%N (map (fun b => T_bind_trie c b +
        T_keep p c (bind_trie c b)) bs) + 2 * N.of_nat (length bs) + 1)%N.
  Proof.
    intros p c bs. induction bs as [|b bs IH].
    - time_unfold @List.T_filter. cbn [map fold_right length]. lia.
    - time_unfold @List.T_filter. cbn [map fold_right length].
      destruct (keep p c (bind_trie c b)); rewrite Nat2N.inj_succ; lia.
  Qed.

  (** A plan's callback pays each join and filter exactly, with a linear scheduling shell. *)
  Lemma run_split_plan_jobs_clock : forall p cp db c,
    plans_ok p cp -> In c (all_plans cp) ->
    (1 + (T_plan_bindings cp c db +
      List.T_filter (fun b => keep p c (bind_trie c b))
        (fun b => 1 + (T_bind_trie c b + T_keep p c (bind_trie c b)))
        (plan_bindings cp c db) +
      ListDef.T_map (fun b => (c, b)) (fun _ => 1)
        (filter (fun b => keep p c (bind_trie c b)) (plan_bindings cp c db))) +
      N.of_nat (length (map (fun b => (c, b))
        (filter (fun b => keep p c (bind_trie c b)) (plan_bindings cp c db))) + 2) <=
      J.T_run (join V.t c) (map (source_index db) (sources V.t c)) +
      fold_right N.add 0%N (map (fun b => T_bind_trie c b + T_keep p c (bind_trie c b))
        (bindings cp c db)) +
      128 * (D.c_db + I.c_ix + 1) * N.of_nat (run_split_plan_weight p cp db c) *
        N.of_nat (wbits p + 1))%N.
  Proof.
    intros p cp db c Hplans Hc.
    pose proof (run_split_bindings_clock p cp db c Hplans Hc) as Hbindings.
    pose proof (run_split_filter_bindings_clock p c (bindings cp c db)) as Hfilter.
    pose proof (run_split_filter_length (list (cell V.t))
      (fun b => keep p c (bind_trie c b)) (bindings cp c db)) as Hlength.
    pose proof (ListDef.T_map_le (fun b : list (cell V.t) => (c, b)) (fun _ => 1%N)
      1%N (filter (fun b => keep p c (bind_trie c b)) (bindings cp c db))
      (fun _ => N.le_refl 1%N)) as Hmap.
    change (plan_bindings cp c db) with (bindings cp c db).
    rewrite length_map.
    assert (Hweight : 1 <= run_split_job_weight p c).
    { unfold run_split_job_weight. lia. }
    assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia.
    unfold run_split_plan_weight. rewrite !Nat2N.inj_add, !Nat2N.inj_mul in *.
    nia.
  Qed.

  (** Flattening plan callbacks sums their exact clocks and scheduling shells. *)
  Lemma run_split_jobs_list_clock : forall p cp db cs,
    plans_ok p cp -> (forall c, In c cs -> In c (all_plans cp)) ->
    (Code.List.T_flat_map
      (fun c => map (fun b => (c, b))
        (filter (fun b => keep p c (bind_trie c b)) (plan_bindings cp c db)))
      (fun c => 1 + (T_plan_bindings cp c db +
        List.T_filter (fun b => keep p c (bind_trie c b))
          (fun b => 1 + (T_bind_trie c b + T_keep p c (bind_trie c b)))
          (plan_bindings cp c db) +
        ListDef.T_map (fun b => (c, b)) (fun _ => 1)
          (filter (fun b => keep p c (bind_trie c b)) (plan_bindings cp c db)))) cs <=
      fold_right N.add 0%N (map (fun c =>
        J.T_run (join V.t c) (map (source_index db) (sources V.t c))) cs) +
      fold_right N.add 0%N (map (fun c => fold_right N.add 0
        (map (fun b => T_bind_trie c b + T_keep p c (bind_trie c b))
          (bindings cp c db))) cs) +
      128 * (D.c_db + I.c_ix + 1) *
        N.of_nat (fold_right Nat.add 0%nat (map (run_split_plan_weight p cp db) cs)) *
        N.of_nat (wbits p + 1) + 1)%N.
  Proof.
    intros p cp db cs. induction cs as [|c cs IH]; intros Hplans Hmembers.
    - time_unfold @Code.List.T_flat_map. cbn [map fold_right]. nia.
    - pose proof (run_split_plan_jobs_clock p cp db c Hplans
        (Hmembers c (or_introl eq_refl))) as Hhead.
      specialize (IH Hplans (fun x Hx => Hmembers x (or_intror Hx))).
      pose proof (Datatypes.T_app_le
        (map (fun b => (c, b))
          (filter (fun b => keep p c (bind_trie c b)) (plan_bindings cp c db)))
        (flat_map (fun c => map (fun b => (c, b))
          (filter (fun b => keep p c (bind_trie c b)) (plan_bindings cp c db))) cs))
        as Happend.
      time_unfold @Code.List.T_flat_map. cbn [map fold_right].
      rewrite !Nat2N.inj_add in *. nia.
  Qed.

  (** Constructing the job list preserves exact join and filter charges. *)
  Lemma run_split_jobs_clock : forall p cp nv db, plans_ok p cp ->
    (T_jobs p cp nv db <=
      fold_right N.add 0%N (map (fun c =>
        J.T_run (join V.t c) (map (source_index db) (sources V.t c)))
        (if nv then naive V.t cp else seminaive V.t cp)) +
      fold_right N.add 0%N (map (fun c => fold_right N.add 0
        (map (fun b => T_bind_trie c b + T_keep p c (bind_trie c b))
          (bindings cp c db))) (if nv then naive V.t cp else seminaive V.t cp)) +
      256 * (D.c_db + I.c_ix + 1) *
        N.of_nat (fold_right Nat.add 0%nat (map (run_split_plan_weight p cp db)
          (if nv then naive V.t cp else seminaive V.t cp)) + 1) *
        N.of_nat (wbits p + 1))%N.
  Proof.
    intros p cp nv db Hplans.
    assert (Hmembers : forall c, In c (if nv then naive V.t cp else seminaive V.t cp) ->
      In c (all_plans cp)).
    { intros c Hc. unfold all_plans. apply in_or_app.
      destruct nv; [left|right]; exact Hc. }
    pose proof (run_split_jobs_list_clock p cp db
      (if nv then naive V.t cp else seminaive V.t cp) Hplans Hmembers) as Hlist.
    assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia.
    time_unfold T_jobs. time_simpl. time_cbn.
    change (compiled_naive cp) with (naive V.t cp).
    change (compiled_semi cp) with (seminaive V.t cp).
    destruct nv; cbn [compiled_naive compiled_semi] in Hlist |- *;
      rewrite !Nat2N.inj_add in *; nia.
  Qed.

  (** The published scheduling constant covers the smaller source-and-list constant. *)
  Lemma run_split_constant : (512 * (D.c_db + I.c_ix + 1) <= k_driver)%N.
  Proof.
    unfold k_driver. nia.
  Qed.

  (** A round pays for its joins, its advance, its applications, its rebuild and its
      per-binding work. *)
  Lemma T_round_split : forall p cp nv db, plans_ok p cp -> D.wf db ->
    loaded p cp db ->
    (T_round p cp nv db <=
      fold_right N.add 0 (map (fun c =>
        J.T_run (join V.t c) (map (source_index db) (sources V.t c)))
        (if nv then naive V.t cp else seminaive V.t cp)) +
      fold_right N.add 0 (map (fun c =>
        fold_right N.add 0 (map (fun b => T_bind_trie c b + T_keep p c (bind_trie c b))
          (bindings cp c db)))
        (if nv then naive V.t cp else seminaive V.t cp)) +
      T_apply_jobs p (jobs p cp nv db) (D.advance db) +
      D.T_rebuild (apply_jobs p (jobs p cp nv db) (D.advance db)) +
      D.T_advance db +
      k_driver * N.of_nat (round_work p cp nv db + 1) * N.of_nat (wbits p + 1))%N.
  Proof.
    intros p cp nv db Hplans Hwf Hloaded.
    pose proof (run_split_jobs_clock p cp nv db Hplans) as Hjobs.
    pose proof (run_split_apply_clock p (jobs p cp nv db) (D.advance db)) as Happly.
    pose proof (run_split_jobs_weight p cp nv db) as Hweight.
    pose proof (run_split_work_bound p cp nv db) as Hwork.
    set (shell := fold_right Nat.add 0%nat (map (run_split_plan_weight p cp db)
      (if nv then naive V.t cp else seminaive V.t cp))) in *.
    assert (Hone : (1 <= N.of_nat (wbits p + 1))%N) by lia.
    assert (Hoverhead :
      (256 * (D.c_db + I.c_ix + 1) * N.of_nat (shell + 1) * N.of_nat (wbits p + 1) +
        64 * N.of_nat shell + 2 <=
        k_driver * N.of_nat (round_work p cp nv db + 1) * N.of_nat (wbits p + 1))%N).
    { eapply N.le_trans with
        (m := (512 * (D.c_db + I.c_ix + 1) * N.of_nat (shell + 1) *
          N.of_nat (wbits p + 1))%N).
      - clear -Hone. rewrite Nat2N.inj_add. nia.
      - apply N.mul_le_mono_r. apply N.mul_le_mono.
        + exact run_split_constant.
        + lia. }
    time_unfold T_round. rewrite apply_all_jobs. lia.
  Qed.

  (** The driver constant covers the stored fields and binary comparison. *)
  Lemma driver_constant_fields : (32 * (D.c_db + 1) <= k_driver)%N.
  Proof.
    unfold k_driver. nia.
  Qed.

  Lemma T_run_split : forall p cp lim db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    (T_run p cp lim db <=
      T_loopN (driver p cp lim) (T_driver p cp lim) (max_iter lim) (false, db) +
      match loopN (driver p cp lim) (max_iter lim) (false, db) with
      | inl (_, final) => D.T_rebuild final
      | inr (_, final) => D.T_rebuild final
      end + k_driver)%N.
  Proof.
    intros p cp lim db Hplans Hwf Hloaded.
    pose proof driver_constant_fields as Hconstant.
    time_unfold T_run. time_unfold T_limits_iter.
    change (limits_iter lim) with (max_iter lim).
    change (fun st : bool * D.t => T_driver p cp lim st) with (T_driver p cp lim).
    destruct (loopN (driver p cp lim) (max_iter lim) (false, db))
      as [[nv final] | [st final]]; lia.
  Qed.


  (** Natural comparison can be charged to the second operand. *)
  Lemma compare_right_clock : forall a b,
    (N.T_compare a b <= N.of_nat (N.size_nat b) + 2)%N.
  Proof.
    intros [|a] [|b]; time_unfold N.T_compare; cbn [N.size_nat]; try lia.
    pose proof (compare_cont_right_clock Eq a b) as Hcompare.
    time_unfold Pos.T_compare. lia.
  Qed.

  (** A driver call pays for its round, limit test and flag test. *)
  Lemma T_driver_split : forall p cp lim nv db, plans_ok p cp -> D.wf db ->
    loaded p cp db ->
    (T_driver p cp lim (nv, db) <= T_round p cp nv db + k_driver *
      N.of_nat (length (Syntax.slots V.t cp) +
        N.size_nat (D.ids (round p cp nv db)) + 1))%N.
  Proof.
    intros p cp lim nv db Hplans Hwf Hloaded.
    pose proof (D.T_ids_le (round p cp nv db)) as Hids.
    pose proof (D.T_changed_le (round p cp nv db)) as Hchanged.
    pose proof (compare_right_clock (max_ids lim) (D.ids (round p cp nv db))) as Hcompare.
    pose proof driver_constant_fields as Hconstant.
    clear Hplans Hwf Hloaded.
    time_unfold T_driver. time_unfold T_limits_ids. time_unfold N.T_ltb.
    change (limits_ids lim) with (max_ids lim).
    destruct (N.ltb (max_ids lim) (D.ids (round p cp nv db)));
      [| destruct (andb nv (negb (D.changed (round p cp nv db))))];
      rewrite ?Nat2N.inj_add in *; time_simpl; nia.
  Qed.

  (** A loop pays each visited callback and amortised binary decrement once. *)
  Lemma loop_trace_clock_acc : forall (St Out : Type) (step : St -> St + Out)
      (T_step : St -> N) fs (Hacc : Acc loopN_lt fs),
    (Loop.T_loop loopN_lt (loopN_step step) (fun fs => T_loopN_step step T_step fs) fs Hacc <=
      fold_right N.add 0 (map (fun st => T_step st + c_loopN)
        (firstn (N.to_nat (fst fs))
          (driver_trace step (N.to_nat (fst fs)) (snd fs)))) +
      loopN_zero_bits (fst fs) + 2)%N.
  Proof.
    intros St Out step T_step fs Hacc.
    induction Hacc as [[fuel state] Hnext IH] using Loop.Acc_ind_dep.
    cbn [fst snd]. destruct fuel as [|p].
    - time_unfold @Loop.T_loop. cbn [loopN_step Acc_inv].
      unfold T_loopN_step at 1.
      cbn [loopN_step loopN_zero_bits N.to_nat firstn map fold_right]. lia.
    - assert (Hfuel : N.to_nat (Npos p) = S (N.to_nat (N.pred (Npos p)))).
      { rewrite N2Nat.inj_pred.
        change (Pos.to_nat p = S (Nat.pred (Pos.to_nat p))).
        pose proof (Pos2Nat.is_pos p). lia. }
      time_unfold @Loop.T_loop.
      cbn [loopN_step Acc_inv].
      destruct (step state) as [next | result] eqn:Hstep.
      + match goal with
        | |- context [Loop.T_loop _ _ _ ?fs (Hnext _ ?Hlt)] =>
            pose proof (IH fs Hlt) as Htail
        end.
        cbn [fst snd] in Htail.
        pose proof (loopN_pred_credit (Npos p)) as Hcredit.
        unfold T_loopN_step at 1. cbn beta iota zeta. rewrite Hstep.
        rewrite Hfuel. cbn [driver_trace firstn map fold_right]. rewrite Hstep.
        unfold c_loopN in Htail |- *. lia.
      + unfold T_loopN_step at 1. cbn beta iota zeta. rewrite Hstep.
        rewrite Hfuel. cbn [driver_trace firstn map fold_right]. rewrite Hstep.
        rewrite ?firstn_nil. cbn [map fold_right]. unfold c_loopN. lia.
  Qed.

  (** The loop pays for every driver call in the trace prefix and its fuel. *)
  Lemma T_driver_loop_split : forall p cp lim db,
    (T_loopN (driver p cp lim) (T_driver p cp lim) (max_iter lim) (false, db) <=
      fold_right N.add 0 (map (fun st => T_driver p cp lim st + c_loopN)
        (firstn (N.to_nat (max_iter lim)) (trace p cp lim db))) +
      c_loopN * N.of_nat (N.size_nat (max_iter lim) + 1))%N.
  Proof.
    intros p cp lim db. unfold trace.
    time_unfold @T_loopN.
    match goal with
    | |- context [Loop.T_loop _ _ _ _ ?Hacc] =>
        pose proof (loop_trace_clock_acc _ _ (driver p cp lim) (T_driver p cp lim)
          (max_iter lim, (false, db)) Hacc) as Hloop
    end.
    pose proof (loopN_zero_bits_le_size (max_iter lim)) as Hbits.
    cbn [fst snd] in Hloop. unfold c_loopN in Hloop |- *.
    rewrite Nat2N.inj_add. lia.
  Qed.
  (** Primitive arguments observe values but do not distinguish class identifiers. *)
  Definition run_value_view (s : Model.env (V := V.t)) (x : positive) : option V.t :=
    match s x with
    | Some (Val v) => Some v
    | _ => None
    end.

  Lemma run_value_terms_agree : forall ts s t,
    (forall x, run_value_view s x = run_value_view t x) ->
    value_terms s ts = value_terms t ts.
  Proof.
    intro ts. induction ts as [|a ts IH]; intros s t Hagree.
    - reflexivity.
    - cbn [value_terms]. rewrite (IH s t Hagree).
      destruct a as [x | v]; [|reflexivity].
      specialize (Hagree x). unfold run_value_view in Hagree.
      destruct (s x) as [[i | u] |]; destruct (t x) as [[j | v] |];
        cbn in Hagree; destruct (value_terms t ts); congruence.
  Qed.

  Lemma run_value_update_agree : forall s t x c d,
    (forall y, run_value_view s y = run_value_view t y) ->
    (match c with Val v => Some v | _ => None end) =
      (match d with Val v => Some v | _ => None end) ->
    forall y, run_value_view (update s x c) y = run_value_view (update t x d) y.
  Proof.
    intros s t x c d Hagree Hvalue y. unfold run_value_view, update.
    destruct (Pos.eqb x y); [exact Hvalue | exact (Hagree y)].
  Qed.

  (** The primitive-work specification depends only on the available values. *)
  Lemma run_action_prim_work_agree : forall kinds acts s t,
    (forall x, run_value_view s x = run_value_view t x) ->
    action_prim_work V.prim V.prim_work kinds acts s =
      action_prim_work V.prim V.prim_work kinds acts t.
  Proof.
    intros kinds acts. induction acts as [|a acts IH]; intros s t Hagree.
    - reflexivity.
    - destruct a as [x f args | f args res | a b | x op args];
        cbn [action_prim_work].
      + destruct (kinds f) as [kind |]; [destruct kind |];
          apply IH; try exact Hagree.
        apply run_value_update_agree; [exact Hagree | reflexivity].
      + apply IH. exact Hagree.
      + apply IH. exact Hagree.
      + rewrite (run_value_terms_agree args s t Hagree).
        destruct (value_terms t args) as [vs |]; [|reflexivity].
        destruct (V.prim op vs) as [v |]; [|reflexivity].
        f_equal. apply IH. apply run_value_update_agree; [exact Hagree | reflexivity].
  Qed.

  (** Local lookup charges one trie walk and at most one external environment call. *)
  Lemma run_look_clock : forall s Ts locals x,
    (@T_look V.t s Ts locals x <= 2 * N.of_nat (Pos.size_nat x) + Ts x + 1)%N.
  Proof.
    intros s Ts locals x. time_unfold @T_look.
    PTrieT.trie_get_le. destruct (trie_get x locals); lia.
  Qed.

  (** Reading a term pays its variable width and its external callback once. *)
  Lemma run_term_clock : forall s Ts locals t W,
    (forall x, In x (term_vars t) -> Pos.size_nat x <= W) ->
    (@T_term_cell V.t s Ts locals t <= 2 * N.of_nat (W + 1) +
      fold_right N.add 0%N (map Ts (term_vars t)))%N.
  Proof.
    intros s Ts locals [x | v] W Hwidth.
    - pose proof (Hwidth x (or_introl eq_refl)) as Hx.
      pose proof (run_look_clock s Ts locals x) as Hlook.
      time_unfold @T_term_cell. cbn [term_vars map fold_right].
      rewrite Nat2N.inj_add. nia.
    - time_unfold @T_term_cell. cbn [term_vars map fold_right].
      rewrite Nat2N.inj_add. lia.
  Qed.

  Lemma run_sum_app : forall xs ys : list N,
    fold_right N.add 0%N (xs ++ ys) = (fold_right N.add 0%N xs + fold_right N.add 0%N ys)%N.
  Proof.
    induction xs as [|x xs IH]; intro ys; cbn [fold_right app]; [reflexivity|].
    rewrite IH. lia.
  Qed.

  (** A short-circuiting list read charges at most every listed variable once. *)
  Lemma run_terms_clock : forall ts s Ts locals W,
    Forall (fun t => forall x, In x (term_vars t) -> Pos.size_nat x <= W) ts ->
    (@T_term_cells V.t s Ts locals ts <= 4 * N.of_nat ((length ts + 1) * (W + 1)) +
      fold_right N.add 0%N (map Ts (flat_map term_vars ts)))%N.
  Proof.
    intro ts. induction ts as [|t ts IH]; intros s Ts locals W Hwidth.
    - time_unfold @T_term_cells. cbn [length flat_map map fold_right].
      rewrite Nat2N.inj_mul, !Nat2N.inj_add. nia.
    - inversion Hwidth as [|t' ts' Hhead Htail]; subst t' ts'.
      pose proof (run_term_clock s Ts locals t W Hhead) as Hterm.
      pose proof (IH s Ts locals W Htail) as Hrest.
      time_unfold @T_term_cells.
      destruct (term_cell s locals t); [destruct (term_cells s locals ts)|];
        cbn [length flat_map]; rewrite map_app, run_sum_app;
        rewrite !Nat2N.inj_mul, !Nat2N.inj_add, ?Nat2N.inj_succ in *; nia.
  Qed.

  (** Value arguments obey the same callback budget as cell arguments. *)
  Lemma run_values_clock : forall ts s Ts locals W,
    Forall (fun t => forall x, In x (term_vars t) -> Pos.size_nat x <= W) ts ->
    (@T_term_values V.t s Ts locals ts <= 4 * N.of_nat ((length ts + 1) * (W + 1)) +
      fold_right N.add 0%N (map Ts (flat_map term_vars ts)))%N.
  Proof.
    intro ts. induction ts as [|t ts IH]; intros s Ts locals W Hwidth.
    - time_unfold @T_term_values. cbn [length flat_map map fold_right].
      rewrite Nat2N.inj_mul, !Nat2N.inj_add. nia.
    - inversion Hwidth as [|t' ts' Hhead Htail]; subst t' ts'.
      pose proof (run_term_clock s Ts locals t W Hhead) as Hterm.
      pose proof (IH s Ts locals W Htail) as Hrest.
      time_unfold @T_term_values.
      destruct (term_cell s locals t) as [[i | v] |];
        try destruct (term_values s locals ts);
        cbn [length flat_map]; rewrite map_app, run_sum_app;
        rewrite !Nat2N.inj_mul, !Nat2N.inj_add, ?Nat2N.inj_succ in *; nia.
  Qed.
  (** Query typing determines its final context pointwise. *)
  Lemma run_query_context_agree : forall (p : program V.t) (q : list (atom V.t)) g h,
    query_ok (program_sorts p) (program_kind p) ctx_empty q g ->
    query_ok (program_sorts p) (program_kind p) ctx_empty q h -> forall x, g x = h x.
  Proof.
    intros p q g h Hg Hh x.
    assert (Hempty : forall y, trie_get y (@Empty sort) = ctx_empty y).
    { intro y. rewrite PTrie.get_empty. reflexivity. }
    destruct (bind_query_b_complete V.t (decls V.t p) Empty ctx_empty q g Hempty Hg)
      as [tg [Htg Hrg]].
    destruct (bind_query_b_complete V.t (decls V.t p) Empty ctx_empty q h Hempty Hh)
      as [th [Hth Hrh]].
    rewrite Htg in Hth. inversion Hth; subst th. rewrite <- Hrg, <- Hrh. reflexivity.
  Qed.

  (** The rule environment supplies the context used to type its actions. *)
  Lemma run_rule_actions_env : forall p cp r s, plans_ok p cp -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s ->
    exists g, actions_ok (program_sorts p) (program_kind p) g (actions V.t r) /\
      env_sorted g s.
  Proof.
    intros p cp r s Hplans Hr [h [Hqh Henv]].
    pose proof (plans_ok_sorted p cp Hplans) as Hok.
    unfold program_ok in Hok. rewrite Forall_forall in Hok.
    destruct (Hok r Hr) as [g [Hqg Hacts]]. exists g. split; [exact Hacts|].
    intros x ty Hx. apply Henv. rewrite <- (run_query_context_agree p _ g h Hqg Hqh x).
    exact Hx.
  Qed.

  (** A typed term resolves to a cell of its declared sort. *)
  Lemma run_term_sorted : forall g (s : Model.env (V := V.t)) locals t ty,
    env_sorted g (look s locals) -> has g t ty ->
    exists c, term_cell s locals t = Some c /\ cell_sort c = ty.
  Proof.
    intros g s locals [x | v] ty Henv Hhas.
    - exact (Henv x ty Hhas).
    - exists (Val v). cbn [term_cell cell_sort]. split; [reflexivity|symmetry; exact Hhas].
  Qed.

  (** A term cannot manufacture an unallocated class identifier. *)
  Lemma run_term_allocated : forall db s locals t i,
    env_allocated db (look s locals) -> term_cell s locals t = Some (Id i) ->
    D.allocated db i.
  Proof.
    intros db s locals [x | v] i Halloc Hterm.
    - exact (Halloc x i Hterm).
    - discriminate Hterm.
  Qed.

  (** Reading typed arguments preserves their list of sorts and their length. *)
  Lemma run_cells_sorted : forall (ts : list (term V.t)) ss g s locals,
    Forall2 (has g) ts ss -> env_sorted g (look s locals) ->
    exists cells, term_cells s locals ts = Some cells /\ map cell_sort cells = ss /\
      length cells = length ts.
  Proof.
    intros ts ss g s locals Htyped Henv. induction Htyped as [|t ty ts ss Ht Hts IH].
    - exists []. repeat split; reflexivity.
    - destruct (run_term_sorted g s locals t ty Henv Ht) as [c [Hc Hsort]].
      destruct IH as [cells [Hcells [Hsorts Hlen]]]. exists (c :: cells).
      cbn [term_cells map length]. rewrite Hc, Hcells, Hsort, Hsorts, Hlen.
      repeat split; reflexivity.
  Qed.

  (** Every identifier returned by an argument read came from its environment. *)
  Lemma run_cells_allocated : forall ts db s locals cells,
    env_allocated db (look s locals) -> term_cells s locals ts = Some cells ->
    forall i, In (Id i) cells -> D.allocated db i.
  Proof.
    intro ts. induction ts as [|t ts IH]; intros db s locals cells Halloc Hcells i Hi.
    - cbn [term_cells] in Hcells. inversion Hcells; subst cells. contradiction.
    - cbn [term_cells] in Hcells.
      destruct (term_cell s locals t) as [c |] eqn:Hc; [|discriminate].
      destruct (term_cells s locals ts) as [cs |] eqn:Hcs; [|discriminate].
      inversion Hcells; subst cells. destruct Hi as [Hi | Hi].
      + subst c. eapply run_term_allocated; eauto.
      + eapply IH; eauto.
  Qed.

  (** An optional output agrees with the function's output kind. *)
  Lemma run_result_sorted : forall g (s : Model.env (V := V.t)) locals out res,
    env_sorted g (look s locals) -> has_result g out res ->
    exists o, result_cell s locals res = Some o /\ option_map cell_sort o = out_sort out.
  Proof.
    intros g s locals out res Henv Htyped.
    destruct out as [| |m]; destruct res as [t |];
      cbn [has_result out_sort] in Htyped; try contradiction.
    - exists None. split; reflexivity.
    - destruct (run_term_sorted g s locals t SId Henv Htyped) as [c [Hc Hsort]].
      exists (Some c). cbn [result_cell]. rewrite Hc. split; [reflexivity|].
      cbn [option_map out_sort]. now rewrite Hsort.
    - destruct (run_term_sorted g s locals t SVal Henv Htyped) as [c [Hc Hsort]].
      exists (Some c). cbn [result_cell]. rewrite Hc. split; [reflexivity|].
      cbn [option_map out_sort]. now rewrite Hsort.
  Qed.

  Lemma run_result_allocated : forall db s locals res o,
    env_allocated db (look s locals) -> result_cell s locals res = Some o ->
    forall i, In (Id i) (option_list o) -> D.allocated db i.
  Proof.
    intros db s locals [t |] o Halloc Hres i Hi; cbn [result_cell] in Hres.
    - destruct (term_cell s locals t) as [c |] eqn:Hc; [|discriminate].
      inversion Hres; subst o. destruct Hi as [Hi | Hi]; [|contradiction].
      subst c. eapply run_term_allocated; eauto.
    - inversion Hres; subst o. contradiction.
  Qed.

  (** The executable value reader agrees with the work specification. *)
  Lemma run_values_spec : forall (ts : list (term V.t)) s locals,
    term_values s locals ts = value_terms (look s locals) ts.
  Proof.
    intro ts. induction ts as [|t ts IH]; intros s locals; cbn [term_values value_terms].
    - reflexivity.
    - rewrite IH. destruct t as [x |v]; cbn [term_cell]; [|reflexivity].
      destruct (look s locals x) as [[i | v] |]; reflexivity.
  Qed.

  (** A checked slot fits every tuple with its declared argument and output sorts. *)
  Lemma run_typed_slots : forall p cp db f (k : list (cell V.t)) o out,
    plans_ok p cp -> loaded p cp db -> program_sorts p f = Some (map cell_sort k) ->
    program_kind p f = Some out -> option_map cell_sort o = out_sort out ->
    D.slots_fit db f (length (k ++ option_list o)).
  Proof.
    intros p cp db f k o out Hplans [_ [Hslots _]] Hsort Hkind Hout perm Hin.
    rewrite Hslots in Hin.
    destruct (shape_slots_ok p cp f perm Hplans Hin)
      as [ss [out' [Hss [Hout' [Hnodup Hbound]]]]].
    rewrite Hsort in Hss. inversion Hss; subst ss.
    rewrite Hkind in Hout'. inversion Hout'; subst out'.
    split; [exact Hnodup|]. rewrite length_map in Hbound. rewrite length_app.
    destruct out as [| |m]; destruct o as [[i |v] |];
      cbn [option_map out_sort] in Hout; try discriminate;
      cbn [option_list length]; exact Hbound.
  Qed.

  Lemma run_make_slots : forall p cp db f (k : list (cell V.t)),
    plans_ok p cp -> loaded p cp db -> program_sorts p f = Some (map cell_sort k) ->
    program_kind p f = Some OId -> D.slots_fit db f (S (length k)).
  Proof.
    intros p cp db f k Hplans Hloaded Hsort Hkind.
    pose proof (run_typed_slots p cp db f k (Some (Id 1)) OId
      Hplans Hloaded Hsort Hkind eq_refl) as Hslots.
    rewrite length_app in Hslots. cbn [option_list length] in Hslots.
    replace (length k + 1) with (S (length k)) in Hslots by lia. exact Hslots.
  Qed.

  Lemma run_put_kind : forall p cp db f k o out,
    plans_ok p cp -> loaded p cp db ->
    (forall i, In (Id i) (k ++ option_list o) -> D.allocated db i) ->
    program_sorts p f = Some (map cell_sort k) -> program_kind p f = Some out ->
    option_map cell_sort o = out_sort out -> D.kind_ok db f k o.
  Proof.
    intros p cp db f k o out Hplans Hloaded Halloc Hsort Hkind Hout.
    split; [exact Halloc|]. split.
    - eapply run_typed_slots; eauto.
    - destruct Hloaded as [Hkinds _]. rewrite Hkinds, Hkind.
      destruct out as [| |m]; destruct o as [[i |v] |];
        cbn [option_map out_sort] in Hout; try discriminate; exact I.
  Qed.

  (** Local updates preserve the typing and allocation conditions of an action environment. *)
  Lemma run_local_sorted : forall g s locals x (c : cell V.t),
    env_sorted g (look s locals) ->
    env_sorted (ctx_set g x (cell_sort c)) (look s (PTrieCode.set x c locals)).
  Proof.
    intros g s locals x c Henv y ty Hy. rewrite run_look_set. unfold ctx_set in Hy.
    unfold update. destruct (Pos.eqb x y) eqn:Hxy.
    - inversion Hy; subst ty. exists c. split; reflexivity.
    - exact (Henv y ty Hy).
  Qed.

  Lemma run_local_allocated : forall db s locals x c,
    env_allocated db (look s locals) ->
    (forall i, c = Id i -> D.allocated db i) ->
    env_allocated db (look s (PTrieCode.set x c locals)).
  Proof.
    intros db s locals x c Henv Hnew y i Hy. rewrite run_look_set in Hy.
    unfold update in Hy. destruct (Pos.eqb x y).
    - apply Hnew. now inversion Hy.
    - exact (Henv y i Hy).
  Qed.

  Lemma run_loaded_put : forall p cp db f k o, D.wf db -> loaded p cp db ->
    D.kind_ok db f k o -> row_sorted (program_sorts p) (kind (D.view db)) f k o ->
    loaded p cp (D.put f k o db).
  Proof.
    intros p cp db f k o Hwf [Hkinds [Hslots Hsorted]] Hkind Hrow.
    destruct (D.layout_put f k o db Hwf) as [Hkinds' [Hslots' _]].
    split.
    - intro x. rewrite Hkinds'. apply Hkinds.
    - split; [now rewrite Hslots'|]. eapply put_preserves_sorted; eauto.
  Qed.

  Lemma run_loaded_make : forall p cp db f k, D.wf db -> loaded p cp db ->
    program_kind p f = Some OId -> program_sorts p f = Some (map cell_sort k) ->
    loaded p cp (snd (D.make f k db)).
  Proof.
    intros p cp db f k Hwf [Hkinds [Hslots Hsorted]] Hkind Hsort.
    destruct (D.layout_make f k db Hwf) as [Hkinds' [Hslots' _]].
    split.
    - intro x. rewrite Hkinds'. apply Hkinds.
    - split; [now rewrite Hslots'|]. eapply make_preserves_sorted; eauto.
      rewrite Hkinds. exact Hkind.
  Qed.

  Lemma run_loaded_union : forall p cp db i j, D.wf db -> loaded p cp db ->
    loaded p cp (D.union i j db).
  Proof.
    intros p cp db i j Hwf [Hkinds [Hslots Hsorted]].
    destruct (D.layout_union i j db Hwf) as [Hkinds' [Hslots' _]].
    split.
    - intro x. rewrite Hkinds'. apply Hkinds.
    - split; [now rewrite Hslots'|]. eapply union_preserves_sorted; eauto.
  Qed.

  (** Every suffix of an action application keeps its typing and monotone budgets. *)
  Lemma run_apply_go_state : forall acts p cp g s locals db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    D.wf (apply_go acts s locals db) /\ loaded p cp (apply_go acts s locals db) /\
    (D.ids db <= D.ids (apply_go acts s locals db))%N /\
    D.unit db <= D.unit (apply_go acts s locals db).
  Proof.
    intro acts. induction acts as [|a acts IH];
      intros p cp g s locals db Hplans Hwf Hloaded Hacts Henv Halloc.
    - cbn [apply_go]. split; [assumption|]. split; [assumption|]. split; lia.
    - destruct a as [x f args |f args res |a b |x op args]; cbn [apply_go].
      + destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]].
        destruct (run_cells_sorted args ss g s locals Hargs Henv)
          as [cells [Hcells [Hsorts Hlen]]]. rewrite Hcells.
        assert (Hsort_cells : program_sorts p f = Some (map cell_sort cells)).
        { now rewrite Hsorts. }
        pose proof (run_cells_allocated args db s locals cells Halloc Hcells) as Hcells_alloc.
        pose proof (run_make_slots p cp db f cells Hplans Hloaded Hsort_cells Hkind) as Hslots.
        assert (Hkind_db : kind (D.view db) f = Some OId).
        { rewrite (proj1 Hloaded). exact Hkind. }
        pose proof (D.wf_make f cells db Hwf Hcells_alloc Hslots) as Hwf_next.
        pose proof (run_loaded_make p cp db f cells Hwf Hloaded Hkind Hsort_cells)
          as Hloaded_next.
        pose proof (run_make_ids f cells db Hwf Hkind_db) as Hids.
        pose proof (D.unit_mono_make f cells db Hwf) as Hunit.
        pose proof (D.layout_make f cells db Hwf) as Hlayout.
        destruct (D.make f cells db) as [i next] eqn:Hmake in *.
        cbn [fst snd] in *. destruct Hlayout as [_ [_ [_ [Hi _]]]].
        assert (Henv_next : env_sorted (ctx_set g x SId)
          (look s (PTrieCode.set x (Id i) locals))).
        { exact (run_local_sorted g s locals x (Id i) Henv). }
        assert (Halloc_next : env_allocated next (look s (PTrieCode.set x (Id i) locals))).
        { apply run_local_allocated.
          - eapply run_env_allocated_mono; eauto.
          - intros j Heq. inversion Heq; subst j. exact Hi. }
        destruct (IH p cp (ctx_set g x SId) s (PTrieCode.set x (Id i) locals) next
          Hplans Hwf_next Hloaded_next Hrest Henv_next Halloc_next)
          as [Hwf_final [Hloaded_final [Hids_final Hunit_final]]].
        split; [assumption|]. split; [assumption|]. split; lia.
      + destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hres Hrest]]]]]].
        destruct (run_cells_sorted args ss g s locals Hargs Henv)
          as [cells [Hcells [Hsorts Hlen]]].
        destruct (run_result_sorted g s locals out res Henv Hres) as [o [Ho Hout]].
        rewrite Hcells, Ho.
        assert (Hsort_cells : program_sorts p f = Some (map cell_sort cells)).
        { now rewrite Hsorts. }
        assert (Htuple : forall i, In (Id i) (cells ++ option_list o) -> D.allocated db i).
        { intros i Hi. apply in_app_iff in Hi. destruct Hi as [Hi |Hi].
          - eapply run_cells_allocated; eauto.
          - eapply run_result_allocated; eauto. }
        pose proof (run_put_kind p cp db f cells o out Hplans Hloaded Htuple
          Hsort_cells Hkind Hout) as Hkind_ok.
        assert (Hrow : row_sorted (program_sorts p) (kind (D.view db)) f cells o).
        { exists out. split; [exact Hsort_cells|]. split; [|exact Hout].
          rewrite (proj1 Hloaded). exact Hkind. }
        pose proof (D.wf_put f cells o db Hwf Hkind_ok) as Hwf_next.
        pose proof (run_loaded_put p cp db f cells o Hwf Hloaded Hkind_ok Hrow)
          as Hloaded_next.
        destruct (D.layout_put f cells o db Hwf) as [_ [_ [Hids _]]].
        pose proof (D.unit_mono_put f cells o db Hwf) as Hunit.
        assert (Halloc_next : env_allocated (D.put f cells o db) (look s locals)).
        { apply (run_env_allocated_mono db _ (look s locals));
          [rewrite Hids; lia|exact Halloc]. }
        destruct (IH p cp g s locals (D.put f cells o db) Hplans Hwf_next Hloaded_next
          Hrest Henv Halloc_next) as [Hwf_final [Hloaded_final [Hids_final Hunit_final]]].
        split; [assumption|]. split; [assumption|]. split; lia.
      + destruct Hacts as [Ha [Hb Hrest]].
        destruct (run_term_sorted g s locals a SId Henv Ha) as [c [Hc Hcsort]].
        destruct c as [i |v]; [|discriminate Hcsort].
        destruct (run_term_sorted g s locals b SId Henv Hb) as [d [Hd Hdsort]].
        destruct d as [j |v]; [|discriminate Hdsort]. rewrite Hc, Hd.
        pose proof (run_term_allocated db s locals a i Halloc Hc) as Hi.
        pose proof (run_term_allocated db s locals b j Halloc Hd) as Hj.
        pose proof (D.wf_union i j db Hwf Hi Hj) as Hwf_next.
        pose proof (run_loaded_union p cp db i j Hwf Hloaded) as Hloaded_next.
        destruct (D.layout_union i j db Hwf) as [_ [_ [Hids _]]].
        pose proof (D.unit_mono_union i j db Hwf) as Hunit.
        assert (Halloc_next : env_allocated (D.union i j db) (look s locals)).
        { apply (run_env_allocated_mono db _ (look s locals));
          [rewrite Hids; lia|exact Halloc]. }
        destruct (IH p cp g s locals (D.union i j db) Hplans Hwf_next Hloaded_next
          Hrest Henv Halloc_next) as [Hwf_final [Hloaded_final [Hids_final Hunit_final]]].
        split; [assumption|]. split; [assumption|]. split; lia.
      + destruct Hacts as [Hargs Hrest].
        destruct (term_values s locals args) as [vs |] eqn:Hvs.
        * destruct (V.prim op vs) as [v |] eqn:Hprim.
          -- apply (IH p cp (ctx_set g x SVal)); try assumption.
             ++ exact (run_local_sorted g s locals x (Val v) Henv).
             ++ apply run_local_allocated; [exact Halloc|]. intros i Heq. discriminate Heq.
          -- split; [assumption|]. split; [assumption|]. split; lia.
        * split; [assumption|]. split; [assumption|]. split; lia.
  Qed.

  Definition run_term_width (W : nat) (t : term V.t) : Prop :=
    forall x, In x (term_vars t) -> Pos.size_nat x <= W.

  Definition run_action_width (W : nat) (a : action V.t) : Prop :=
    Forall (fun x => Pos.size_nat x <= W) (action_binds a) /\
    Forall (run_term_width W) (action_terms a).

  Lemma run_action_words_in : forall p r a x, In r (rules V.t p) -> In a (actions V.t r) ->
    In x (action_words V.encode a) -> In x (program_words V.encode p).
  Proof.
    intros p r a x Hr Ha Hx. unfold program_words.
    apply in_or_app. right. apply in_flat_map. exists r. split; [exact Hr|].
    destruct r as [q acts]. apply in_or_app. right. apply in_flat_map.
    exists a. split; assumption.
  Qed.

  Lemma run_term_words_in : forall t x, In x (term_vars t) -> In x (term_words V.encode t).
  Proof.
    intros [y |v] x Hx; exact Hx || contradiction.
  Qed.

  Lemma run_action_term_words : forall a t x, In t (action_terms a) ->
    In x (term_words V.encode t) -> In x (action_words V.encode a).
  Proof.
    intros [y f args |f args res |a b |y op args] t x Ht Hx;
      cbn [action_terms action_words] in *.
    - right. right. apply in_flat_map. exists t. split; assumption.
    - right. apply in_flat_map. exists t. split; assumption.
    - destruct Ht as [Ht |[Ht |Ht]]; try contradiction; subst t;
        apply in_or_app; [left|right]; exact Hx.
    - right. right. apply in_flat_map. exists t. split; assumption.
  Qed.

  Lemma run_action_bind_words : forall a x, In x (action_binds a) ->
    In x (action_words V.encode a).
  Proof.
    intros [y f args |f args res |a b |y op args] x Hx;
      cbn [action_binds action_words] in *.
    - destruct Hx as [<-|[]]. now left.
    - contradiction.
    - contradiction.
    - destruct Hx as [<-|[]]. now left.
  Qed.

  (** Every action name read by the engine has the program's maximum word width. *)
  Lemma run_rule_width : forall p r, In r (rules V.t p) ->
    Forall (run_action_width (wbits p)) (actions V.t r).
  Proof.
    intros p r Hr. rewrite Forall_forall. intros a Ha. split.
    - rewrite Forall_forall. intros x Hx. apply run_word_width.
      eapply run_action_words_in; eauto using run_action_bind_words.
    - rewrite Forall_forall. intros t Ht x Hx. apply run_word_width.
      eapply run_action_words_in; eauto.
      eapply run_action_term_words; [exact Ht|now apply run_term_words_in].
  Qed.

  Definition run_action_weight (cp : compiled V.t) (a : action V.t) : nat :=
    match a with
    | Make _ f args | Put f args _ => (length args + 2) * (length args + 2) *
        (length (filter (fun sl => Pos.eqb (fst sl) f) (Syntax.slots V.t cp)) + 1)
    | Union _ _ => 1
    | Let _ _ args => length args + 1
    end.

  Definition run_actions_weight (cp : compiled V.t) (acts : list (action V.t)) : nat :=
    fold_right (fun a n => match a with
      | Make _ f args | Put f args _ => (length args + 2) * (length args + 2) *
          (length (filter (fun sl => Pos.eqb (fst sl) f) (Syntax.slots V.t cp)) + 1) + n
      | Union _ _ => 1 + n
      | Let _ _ args => length args + 1 + n
      end) 0 acts.

  Definition run_term_calls (Ts : positive -> N) (ts : list (term V.t)) : N :=
    fold_right N.add 0%N (map Ts (flat_map term_vars ts)).

  Lemma run_term_calls_app : forall Ts xs ys,
    run_term_calls Ts (xs ++ ys) = (run_term_calls Ts xs + run_term_calls Ts ys)%N.
  Proof.
    intros Ts xs ys. unfold run_term_calls. rewrite flat_map_app, map_app, run_sum_app.
    reflexivity.
  Qed.

  Lemma run_action_weight_pos : forall cp a, 1 <= run_action_weight cp a.
  Proof.
    intros cp [x f args |f args res |a b |x op args]; unfold run_action_weight; nia.
  Qed.

  Lemma run_result_clock : forall res s Ts locals W,
    Forall (run_term_width W) (option_list res) ->
    (T_result_cell s Ts locals res <= 4 * N.of_nat (W + 1) +
      run_term_calls Ts (option_list res))%N.
  Proof.
    intros [t |] s Ts locals W Hwidth.
    - inversion Hwidth as [|t' ts Hhead Htail]; subst t' ts.
      pose proof (run_term_clock s Ts locals t W Hhead) as Hterm.
      time_unfold @T_result_cell. destruct (term_cell s locals t);
        cbn [option_list run_term_calls flat_map app map fold_right];
        rewrite ?app_nil_r; rewrite Nat2N.inj_add in *; lia.
    - time_unfold @T_result_cell. cbn [option_list run_term_calls flat_map map fold_right].
      rewrite Nat2N.inj_add. lia.
  Qed.

  (** Every nonzero final unit dominates the syntax and identifier factors separately. *)
  Lemma run_spending_factors : forall U L W,
    1 <= U -> 1 <= L ->
    (1 <= N.of_nat U * N.of_nat L * N.of_nat (W + 1))%N /\
    (N.of_nat (W + 1) <= N.of_nat U * N.of_nat L * N.of_nat (W + 1))%N /\
    (N.of_nat U * N.of_nat L <= N.of_nat U * N.of_nat L * N.of_nat (W + 1))%N.
  Proof.
    intros U L W HU HL.
    assert (Hu : (1 <= N.of_nat U)%N) by lia.
    assert (Hl : (1 <= N.of_nat L)%N) by lia.
    assert (Hw : (1 <= N.of_nat (W + 1))%N) by lia.
    assert (Hul : (1 <= N.of_nat U * N.of_nat L)%N) by nia.
    repeat split; nia.
  Qed.

  Definition run_apply_factor : N := (128 * (D.c_db + V.c_val + 1))%N.

  Lemma run_apply_factor_le : (2 * run_apply_factor + 8 <= k_driver)%N.
  Proof.
    unfold run_apply_factor, k_driver. nia.
  Qed.

  Definition run_action_budget (B : N) (U W : nat) : N :=
    (run_apply_factor * (N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) *
      N.of_nat (W + 1)))%N.

  (** The action coefficient covers syntax, database operations and a primitive call. *)
  Lemma run_action_budget_covers : forall B U W, 1 <= U ->
    (32 * N.of_nat (W + 1) +
      D.c_db * N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) + V.c_val + 8 <=
      run_action_budget B U W)%N.
  Proof.
    intros B U W HU.
    destruct (run_spending_factors U (N.to_nat (N.log2 B) + 1) W HU ltac:(lia))
      as [Hpos [Hwidth Hdb]].
    set (E := (N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) * N.of_nat (W + 1))%N)
      in Hpos, Hwidth, Hdb.
    assert (Hsyntax : (32 * N.of_nat (W + 1) <= 32 * E)%N) by nia.
    assert (Hdatabase : (D.c_db * N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) <=
      D.c_db * E)%N) by nia.
    assert (Hvalue : (V.c_val + 8 <= (V.c_val + 8) * E)%N) by nia.
    change (32 * N.of_nat (W + 1) +
      D.c_db * N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) + V.c_val + 8 <=
      run_apply_factor * E)%N.
    unfold run_apply_factor. nia.
  Qed.

  Lemma run_set_clock : forall x (c : cell V.t) locals,
    (PTrieCode.T_set x c locals <= 8 * N.of_nat (Pos.size_nat x) + 1)%N.
  Proof.
    intros x c locals. pose proof (PTrieT.replace_clock_bound (cell V.t) x (Some c) locals).
    unfold PTrieCode.T_set. lia.
  Qed.

  (** Binding actions read their terms and insert a local result within one syntax charge. *)
  Lemma run_binding_charge : forall args s Ts locals x c W weight,
    Forall (run_term_width W) args -> Pos.size_nat x <= W -> length args + 1 <= weight ->
    (T_term_cells s Ts locals args + PTrieCode.T_set x c locals + 8 <=
      32 * N.of_nat (W + 1) * N.of_nat weight + run_term_calls Ts args)%N.
  Proof.
    intros args s Ts locals x c W weight Hterms Hx Hweight.
    pose proof (run_terms_clock args s Ts locals W Hterms) as Hread.
    pose proof (run_set_clock x c locals) as Hset.
    unfold run_term_calls. rewrite !Nat2N.inj_mul, !Nat2N.inj_add in *.
    assert (Hwidth : (1 <= N.of_nat W + 1)%N) by lia.
    assert (Hcount : (N.of_nat (length args) + 1 <= N.of_nat weight)%N) by lia.
    assert (Hname : (N.of_nat (Pos.size_nat x) <= N.of_nat W)%N) by lia.
    clear -Hread Hset Hwidth Hcount Hname. nia.
  Qed.

  Lemma run_value_binding_charge : forall args s Ts locals x c W weight,
    Forall (run_term_width W) args -> Pos.size_nat x <= W -> length args + 1 <= weight ->
    (T_term_values s Ts locals args + PTrieCode.T_set x c locals + 8 <=
      32 * N.of_nat (W + 1) * N.of_nat weight + run_term_calls Ts args)%N.
  Proof.
    intros args s Ts locals x c W weight Hterms Hx Hweight.
    pose proof (run_values_clock args s Ts locals W Hterms) as Hread.
    pose proof (run_set_clock x c locals) as Hset.
    unfold run_term_calls. rewrite !Nat2N.inj_mul, !Nat2N.inj_add in *.
    assert (Hwidth : (1 <= N.of_nat W + 1)%N) by lia.
    assert (Hcount : (N.of_nat (length args) + 1 <= N.of_nat weight)%N) by lia.
    assert (Hname : (N.of_nat (Pos.size_nat x) <= N.of_nat W)%N) by lia.
    clear -Hread Hset Hwidth Hcount Hname. nia.
  Qed.

  (** Put reads its arguments and optional output within the same tuple charge. *)
  Lemma run_put_charge : forall args res s Ts locals W weight,
    Forall (run_term_width W) (args ++ option_list res) -> length args + 2 <= weight ->
    (T_term_cells s Ts locals args + T_result_cell s Ts locals res + 8 <=
      32 * N.of_nat (W + 1) * N.of_nat weight +
        run_term_calls Ts (args ++ option_list res))%N.
  Proof.
    intros args res s Ts locals W weight Hterms Hweight.
    apply Forall_app in Hterms. destruct Hterms as [Hargs Hres].
    pose proof (run_terms_clock args s Ts locals W Hargs) as Hread.
    pose proof (run_result_clock res s Ts locals W Hres) as Hout.
    rewrite run_term_calls_app. unfold run_term_calls in *.
    rewrite !Nat2N.inj_mul, !Nat2N.inj_add in *.
    assert (Hwidth : (1 <= N.of_nat W + 1)%N) by lia.
    assert (Hcount : (N.of_nat (length args) + 2 <= N.of_nat weight)%N) by lia.
    clear -Hread Hout Hwidth Hcount. nia.
  Qed.

  Lemma run_union_charge : forall a b s Ts locals W,
    Forall (run_term_width W) [a; b] ->
    (T_term_cell s Ts locals a + T_term_cell s Ts locals b + 8 <=
      32 * N.of_nat (W + 1) + run_term_calls Ts [a; b])%N.
  Proof.
    intros a b s Ts locals W Hterms.
    inversion Hterms as [|a' ts Ha Htail]; subst a' ts.
    inversion Htail as [|b' ts Hb Hnil]; subst b' ts.
    pose proof (run_term_clock s Ts locals a W Ha) as Hleft.
    pose proof (run_term_clock s Ts locals b W Hb) as Hright.
    unfold run_term_calls. cbn [flat_map]. rewrite app_nil_r, map_app, run_sum_app.
    assert (Hwidth : (1 <= N.of_nat (W + 1))%N) by lia.
    lia.
  Qed.

  (** A database operation can be charged at any later, larger spending unit. *)
  Lemma run_operation_scale : forall B U old next T C,
    D.unit next <= U ->
    (T + N.of_nat (D.unit next) * D.potential B next <=
      N.of_nat (D.unit next) * (C + D.potential B old))%N ->
    (T + N.of_nat U * D.potential B next <=
      N.of_nat U * C + N.of_nat U * D.potential B old)%N.
  Proof.
    intros B U old next T C Hunit Htime.
    pose proof (unit_scale T C (D.potential B old) (D.potential B next)
      (D.unit next) U (unit_pos next) Hunit Htime) as Hscaled.
    rewrite N.mul_add_distr_l in Hscaled. exact Hscaled.
  Qed.

  Lemma run_make_clock_split : forall x f args acts s Ts locals db cells i next,
    term_cells s locals args = Some cells -> D.make f cells db = (i, next) ->
    (T_apply_go (Make x f args :: acts) s Ts locals db <=
      T_term_cells s Ts locals args + D.T_make f cells db +
      PTrieCode.T_set x (Id i) locals +
      T_apply_go acts s Ts (PTrieCode.set x (Id i) locals) next + 8)%N.
  Proof.
    intros x f args acts s Ts locals db cells i next Hcells Hmake.
    time_unfold T_apply_go. rewrite Hcells, Hmake. lia.
  Qed.

  Lemma run_put_clock_split : forall f args res acts s Ts locals db cells o,
    term_cells s locals args = Some cells -> result_cell s locals res = Some o ->
    (T_apply_go (Put f args res :: acts) s Ts locals db <=
      T_term_cells s Ts locals args + T_result_cell s Ts locals res + D.T_put f cells o db +
      T_apply_go acts s Ts locals (D.put f cells o db) + 8)%N.
  Proof.
    intros f args res acts s Ts locals db cells o Hcells Ho.
    time_unfold T_apply_go. rewrite Hcells, Ho. lia.
  Qed.

  Lemma run_union_clock_split : forall a b acts s Ts locals db i j,
    term_cell s locals a = Some (Id i) -> term_cell s locals b = Some (Id j) ->
    (T_apply_go (Union a b :: acts) s Ts locals db <=
      T_term_cell s Ts locals a + T_term_cell s Ts locals b + D.T_union i j db +
      T_apply_go acts s Ts locals (D.union i j db) + 8)%N.
  Proof.
    intros a b acts s Ts locals db i j Ha Hb.
    time_unfold T_apply_go. rewrite Ha, Hb. lia.
  Qed.

  Lemma run_let_clock_split : forall x op args acts s Ts locals db vs v,
    term_values s locals args = Some vs -> V.prim op vs = Some v ->
    (T_apply_go (Let x op args :: acts) s Ts locals db <=
      T_term_values s Ts locals args + V.T_prim op vs +
      PTrieCode.T_set x (Val v) locals +
      T_apply_go acts s Ts (PTrieCode.set x (Val v) locals) db + 8)%N.
  Proof.
    intros x op args acts s Ts locals db vs v Hvs Hv.
    time_unfold T_apply_go. rewrite Hvs, Hv. lia.
  Qed.

  (** Typed actions telescope their database potential at the final spending unit. *)
  Lemma run_apply_go_amort : forall acts p cp g s Ts locals db W B U,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    actions_ok (program_sorts p) (program_kind p) g acts ->
    env_sorted g (look s locals) -> env_allocated db (look s locals) ->
    Forall (run_action_width W) acts ->
    (D.ids (apply_go acts s locals db) <= B)%N -> D.unit (apply_go acts s locals db) <= U ->
    (T_apply_go acts s Ts locals db + N.of_nat U * D.potential B (apply_go acts s locals db) <=
      run_action_budget B U W * N.of_nat (run_actions_weight cp acts + 1) +
      run_term_calls Ts (flat_map action_terms acts) +
      run_apply_factor * action_prim_work V.prim V.prim_work (program_kind p) acts
        (look s locals) + N.of_nat U * D.potential B db)%N.
  Proof.
    intro acts. induction acts as [|a acts IH];
      intros p cp g s Ts locals db W B U Hplans Hwf Hloaded Hacts Henv Halloc Hwidth HB HU.
    - assert (Hunit : 1 <= U) by (pose proof (unit_pos db); cbn [apply_go] in HU; lia).
      pose proof (run_action_budget_covers B U W Hunit) as Hcover.
      time_unfold T_apply_go.
      cbn [apply_go run_actions_weight run_term_calls flat_map map fold_right action_prim_work].
      lia.
    - assert (Hunit : 1 <= U).
      { pose proof (unit_pos (apply_go (a :: acts) s locals db)). lia. }
      pose proof (run_action_budget_covers B U W Hunit) as Hcover.
      inversion Hwidth as [|a' acts' Hhead Htail]; subst a' acts'.
      pose proof (run_action_weight_pos cp a) as Hweight_pos.
      pose proof (N.mul_le_mono_r
        (32 * N.of_nat (W + 1) +
          D.c_db * N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) + V.c_val + 8)%N
        (run_action_budget B U W) (N.of_nat (run_action_weight cp a)) Hcover) as Hcharge.
      destruct a as [x f args |f args res |a b |x op args].
      + destruct Hacts as [ss [Hsort [Hkind [Hargs Hrest]]]].
        destruct Hhead as [Hbind Hterms]. cbn [action_binds action_terms] in Hbind, Hterms.
        inversion Hbind as [|x' xs Hx Hnil]; subst x' xs.
        destruct (run_cells_sorted args ss g s locals Hargs Henv)
          as [cells [Hcells [Hsorts Hlen]]].
        assert (Hsort_cells : program_sorts p f = Some (map cell_sort cells)).
        { now rewrite Hsorts. }
        pose proof (run_cells_allocated args db s locals cells Halloc Hcells) as Hcells_alloc.
        pose proof (run_make_slots p cp db f cells Hplans Hloaded Hsort_cells Hkind) as Hslots.
        assert (Hkind_db : kind (D.view db) f = Some OId).
        { rewrite (proj1 Hloaded). exact Hkind. }
        pose proof (D.wf_make f cells db Hwf Hcells_alloc Hslots) as Hwf_next.
        pose proof (run_loaded_make p cp db f cells Hwf Hloaded Hkind Hsort_cells)
          as Hloaded_next.
        pose proof (run_make_ids f cells db Hwf Hkind_db) as Hids.
        pose proof (D.layout_make f cells db Hwf) as Hlayout.
        destruct (D.make f cells db) as [i next] eqn:Hmake in *.
        cbn [fst snd] in *. destruct Hlayout as [_ [_ [_ [Hi _]]]].
        assert (Henv_next : env_sorted (ctx_set g x SId)
          (look s (PTrieCode.set x (Id i) locals))).
        { exact (run_local_sorted g s locals x (Id i) Henv). }
        assert (Halloc_next : env_allocated next (look s (PTrieCode.set x (Id i) locals))).
        { apply run_local_allocated.
          - eapply run_env_allocated_mono; eauto.
          - intros j Heq. inversion Heq; subst j. exact Hi. }
        cbn [apply_go] in HB, HU |- *. rewrite Hcells, Hmake in HB, HU |- *.
        destruct (run_apply_go_state acts p cp (ctx_set g x SId) s
          (PTrieCode.set x (Id i) locals) next Hplans Hwf_next Hloaded_next Hrest
          Henv_next Halloc_next) as [_ [_ [Hids_final Hunit_final]]].
        assert (HBnext : (D.ids next <= B)%N) by lia.
        assert (HUnext : D.unit next <= U) by lia.
        pose proof (D.T_make_amort B f cells db Hwf Hslots) as Hdatabase.
        rewrite Hmake in Hdatabase. cbn [snd] in Hdatabase.
        specialize (Hdatabase HBnext).
        pose proof (run_operation_scale B U db next (D.T_make f cells db) _
          HUnext Hdatabase) as Hscaled.
        assert (Hdbcharge : (D.T_make f cells db + N.of_nat U * D.potential B next <=
          D.c_db * N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) *
            N.of_nat (run_action_weight cp (Make x f args)) +
          N.of_nat U * D.potential B db)%N).
        { unfold D.slots_of in Hscaled. rewrite (proj1 (proj2 Hloaded)), Hlen in Hscaled.
          unfold run_action_weight. rewrite !Nat2N.inj_mul in *. clear -Hscaled. nia. }
        pose proof (IH p cp (ctx_set g x SId) s Ts (PTrieCode.set x (Id i) locals) next
          W B U Hplans Hwf_next Hloaded_next Hrest Henv_next Halloc_next Htail HB HU)
          as Hremaining.
        assert (Hprim : action_prim_work V.prim V.prim_work (program_kind p) acts
          (look s (PTrieCode.set x (Id i) locals)) =
          action_prim_work V.prim V.prim_work (program_kind p) acts
            (update (look s locals) x (Id 1))).
        { apply run_action_prim_work_agree. intro y. unfold run_value_view.
          rewrite run_look_set. unfold update. destruct (Pos.eqb x y); reflexivity. }
        rewrite Hprim in Hremaining.
        pose proof (run_binding_charge args s Ts locals x (Id i) W
          (run_action_weight cp (Make x f args)) Hterms Hx ltac:(unfold run_action_weight; nia))
          as Hsyntax.
        pose proof (run_make_clock_split x f args acts s Ts locals db cells i next
          Hcells Hmake) as Hclock.
        change (T_apply_go (Make x f args :: acts) s Ts locals db +
          N.of_nat U * D.potential B (apply_go acts s (PTrieCode.set x (Id i) locals) next) <=
          run_action_budget B U W *
            N.of_nat (run_action_weight cp (Make x f args) + run_actions_weight cp acts + 1) +
          run_term_calls Ts (args ++ flat_map action_terms acts) +
          run_apply_factor * action_prim_work V.prim V.prim_work (program_kind p)
            (Make x f args :: acts) (look s locals) + N.of_nat U * D.potential B db)%N.
        rewrite run_term_calls_app. cbn [action_prim_work]. rewrite Hkind.
        rewrite !Nat2N.inj_add in Hremaining |- *.
        clear -Hsyntax Hclock Hremaining Hdbcharge Hcharge. nia.
      + destruct Hacts as [ss [out [Hsort [Hkind [Hargs [Hres Hrest]]]]]].
        destruct Hhead as [_ Hterms]. cbn [action_terms] in Hterms.
        destruct (run_cells_sorted args ss g s locals Hargs Henv)
          as [cells [Hcells [Hsorts Hlen]]].
        destruct (run_result_sorted g s locals out res Henv Hres) as [o [Ho Hout]].
        assert (Hsort_cells : program_sorts p f = Some (map cell_sort cells)).
        { now rewrite Hsorts. }
        assert (Htuple : forall i, In (Id i) (cells ++ option_list o) -> D.allocated db i).
        { intros i Hi. apply in_app_iff in Hi. destruct Hi as [Hi |Hi].
          - eapply run_cells_allocated; eauto.
          - eapply run_result_allocated; eauto. }
        pose proof (run_put_kind p cp db f cells o out Hplans Hloaded Htuple
          Hsort_cells Hkind Hout) as Hkind_ok.
        assert (Hrow : row_sorted (program_sorts p) (kind (D.view db)) f cells o).
        { exists out. split; [exact Hsort_cells|]. split; [|exact Hout].
          rewrite (proj1 Hloaded). exact Hkind. }
        pose proof (D.wf_put f cells o db Hwf Hkind_ok) as Hwf_next.
        pose proof (run_loaded_put p cp db f cells o Hwf Hloaded Hkind_ok Hrow)
          as Hloaded_next.
        destruct (D.layout_put f cells o db Hwf) as [_ [_ [Hids _]]].
        assert (Halloc_next : env_allocated (D.put f cells o db) (look s locals)).
        { apply (run_env_allocated_mono db _ (look s locals));
          [rewrite Hids; lia|exact Halloc]. }
        cbn [apply_go] in HB, HU |- *. rewrite Hcells, Ho in HB, HU |- *.
        destruct (run_apply_go_state acts p cp g s locals (D.put f cells o db)
          Hplans Hwf_next Hloaded_next Hrest Henv Halloc_next)
          as [_ [_ [Hids_final Hunit_final]]].
        assert (HBnext : (D.ids (D.put f cells o db) <= B)%N) by lia.
        assert (HUnext : D.unit (D.put f cells o db) <= U) by lia.
        pose proof (D.T_put_amort B f cells o db Hwf (proj1 (proj2 Hkind_ok)) HBnext)
          as Hdatabase.
        pose proof (run_operation_scale B U db (D.put f cells o db) (D.T_put f cells o db) _
          HUnext Hdatabase) as Hscaled.
        assert (Hdbcharge : (D.T_put f cells o db +
          N.of_nat U * D.potential B (D.put f cells o db) <=
          D.c_db * N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) *
            N.of_nat (run_action_weight cp (Put f args res)) +
          N.of_nat U * D.potential B db)%N).
        { unfold D.slots_of in Hscaled. rewrite (proj1 (proj2 Hloaded)), Hlen in Hscaled.
          unfold run_action_weight. rewrite !Nat2N.inj_mul in *. clear -Hscaled. nia. }
        pose proof (IH p cp g s Ts locals (D.put f cells o db) W B U Hplans Hwf_next
          Hloaded_next Hrest Henv Halloc_next Htail HB HU) as Hremaining.
        pose proof (run_put_charge args res s Ts locals W
          (run_action_weight cp (Put f args res)) Hterms
          ltac:(unfold run_action_weight; nia)) as Hsyntax.
        pose proof (run_put_clock_split f args res acts s Ts locals db cells o Hcells Ho)
          as Hclock.
        change (T_apply_go (Put f args res :: acts) s Ts locals db +
          N.of_nat U * D.potential B (apply_go acts s locals (D.put f cells o db)) <=
          run_action_budget B U W *
            N.of_nat (run_action_weight cp (Put f args res) + run_actions_weight cp acts + 1) +
          run_term_calls Ts ((args ++ option_list res) ++ flat_map action_terms acts) +
          run_apply_factor * action_prim_work V.prim V.prim_work (program_kind p) acts
            (look s locals) + N.of_nat U * D.potential B db)%N.
        rewrite run_term_calls_app. rewrite !Nat2N.inj_add in Hremaining |- *.
        clear -Hsyntax Hclock Hremaining Hdbcharge Hcharge. nia.
      + destruct Hacts as [Ha [Hb Hrest]].
        destruct Hhead as [_ Hterms]. cbn [action_terms] in Hterms.
        destruct (run_term_sorted g s locals a SId Henv Ha) as [c [Hc Hcsort]].
        destruct c as [i |v]; [|discriminate Hcsort].
        destruct (run_term_sorted g s locals b SId Henv Hb) as [d [Hd Hdsort]].
        destruct d as [j |v]; [|discriminate Hdsort].
        pose proof (run_term_allocated db s locals a i Halloc Hc) as Hi.
        pose proof (run_term_allocated db s locals b j Halloc Hd) as Hj.
        pose proof (D.wf_union i j db Hwf Hi Hj) as Hwf_next.
        pose proof (run_loaded_union p cp db i j Hwf Hloaded) as Hloaded_next.
        destruct (D.layout_union i j db Hwf) as [_ [_ [Hids _]]].
        assert (Halloc_next : env_allocated (D.union i j db) (look s locals)).
        { apply (run_env_allocated_mono db _ (look s locals));
          [rewrite Hids; lia|exact Halloc]. }
        cbn [apply_go] in HB, HU |- *. rewrite Hc, Hd in HB, HU |- *.
        destruct (run_apply_go_state acts p cp g s locals (D.union i j db)
          Hplans Hwf_next Hloaded_next Hrest Henv Halloc_next)
          as [_ [_ [Hids_final Hunit_final]]].
        assert (HBold : (D.ids db <= B)%N) by lia.
        assert (HUnext : D.unit (D.union i j db) <= U) by lia.
        pose proof (D.T_union_amort B i j db Hwf Hi Hj HBold) as Hdatabase.
        pose proof (run_operation_scale B U db (D.union i j db) (D.T_union i j db) D.c_db
          HUnext Hdatabase) as Hscaled.
        pose proof (IH p cp g s Ts locals (D.union i j db) W B U Hplans Hwf_next
          Hloaded_next Hrest Henv Halloc_next Htail HB HU) as Hremaining.
        pose proof (run_union_charge a b s Ts locals W Hterms) as Hsyntax.
        pose proof (run_union_clock_split a b acts s Ts locals db i j Hc Hd) as Hclock.
        change (T_apply_go (Union a b :: acts) s Ts locals db +
          N.of_nat U * D.potential B (apply_go acts s locals (D.union i j db)) <=
          run_action_budget B U W * N.of_nat (1 + run_actions_weight cp acts + 1) +
          run_term_calls Ts ([a; b] ++ flat_map action_terms acts) +
          run_apply_factor * action_prim_work V.prim V.prim_work (program_kind p) acts
            (look s locals) + N.of_nat U * D.potential B db)%N.
        rewrite run_term_calls_app. rewrite !Nat2N.inj_add in Hremaining |- *.
        cbn [run_action_weight N.of_nat] in Hcharge.
        assert (Hlog : (1 <= N.of_nat (N.to_nat (N.log2 B) + 1))%N) by lia.
        assert (Hdb : (N.of_nat U * D.c_db <=
          D.c_db * N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1))%N) by nia.
        clear -Hsyntax Hclock Hremaining Hscaled Hcharge Hdb. nia.
      + destruct Hacts as [Hargs Hrest].
        destruct Hhead as [Hbind Hterms]. cbn [action_binds action_terms] in Hbind, Hterms.
        inversion Hbind as [|x' xs Hx Hnil]; subst x' xs.
        pose proof (run_values_spec args s locals) as Hvalues.
        assert (Hfactor : (V.c_val <= run_apply_factor)%N) by (unfold run_apply_factor; lia).
        destruct (term_values s locals args) as [vs |] eqn:Hvs.
        * try rewrite Hvs in Hvalues. pose proof (V.T_prim_le op vs) as Hprimitive.
          destruct (V.prim op vs) as [v |] eqn:Hprim.
          -- assert (Henv_next : env_sorted (ctx_set g x SVal)
               (look s (PTrieCode.set x (Val v) locals))).
             { exact (run_local_sorted g s locals x (Val v) Henv). }
             assert (Halloc_next : env_allocated db (look s (PTrieCode.set x (Val v) locals))).
             { apply run_local_allocated; [exact Halloc|]. intros i Heq. discriminate Heq. }
             cbn [apply_go] in HB, HU |- *. rewrite Hvs, Hprim in HB, HU |- *.
             pose proof (IH p cp (ctx_set g x SVal) s Ts (PTrieCode.set x (Val v) locals) db
               W B U Hplans Hwf Hloaded Hrest Henv_next Halloc_next Htail HB HU)
               as Hremaining.
             assert (Hprim_rest : action_prim_work V.prim V.prim_work (program_kind p) acts
               (look s (PTrieCode.set x (Val v) locals)) =
               action_prim_work V.prim V.prim_work (program_kind p) acts
                 (update (look s locals) x (Val v))).
             { apply run_action_prim_work_agree. intro y. unfold run_value_view.
               rewrite run_look_set. reflexivity. }
             rewrite Hprim_rest in Hremaining.
             pose proof (run_value_binding_charge args s Ts locals x (Val v) W
               (run_action_weight cp (Let x op args)) Hterms Hx ltac:(cbn; lia)) as Hsyntax.
             pose proof (run_let_clock_split x op args acts s Ts locals db vs v Hvs Hprim)
               as Hclock.
             change (T_apply_go (Let x op args :: acts) s Ts locals db +
               N.of_nat U * D.potential B (apply_go acts s (PTrieCode.set x (Val v) locals) db) <=
               run_action_budget B U W *
                 N.of_nat (run_action_weight cp (Let x op args) + run_actions_weight cp acts + 1) +
               run_term_calls Ts (args ++ flat_map action_terms acts) +
               run_apply_factor * action_prim_work V.prim V.prim_work (program_kind p)
                 (Let x op args :: acts) (look s locals) + N.of_nat U * D.potential B db)%N.
             rewrite run_term_calls_app. cbn [action_prim_work]. rewrite <- Hvalues, Hprim.
             rewrite !Nat2N.inj_add in Hremaining |- *.
             assert (Hpositive : (1 <= N.of_nat (run_action_weight cp (Let x op args)))%N)
               by lia.
             clear -Hsyntax Hclock Hremaining Hprimitive Hfactor Hcharge Hpositive. nia.
          -- pose proof (run_value_binding_charge args s Ts locals x (Id 1) W
               (run_action_weight cp (Let x op args)) Hterms Hx ltac:(cbn; lia)) as Hsyntax.
             assert (Hclock : (T_apply_go (Let x op args :: acts) s Ts locals db <=
               T_term_values s Ts locals args + V.T_prim op vs + 8)%N).
             { time_unfold T_apply_go. rewrite Hvs, Hprim. lia. }
             cbn [apply_go]. rewrite Hvs, Hprim.
             change (T_apply_go (Let x op args :: acts) s Ts locals db +
               N.of_nat U * D.potential B db <=
               run_action_budget B U W *
                 N.of_nat (run_action_weight cp (Let x op args) + run_actions_weight cp acts + 1) +
               run_term_calls Ts (args ++ flat_map action_terms acts) +
               run_apply_factor * action_prim_work V.prim V.prim_work (program_kind p)
                 (Let x op args :: acts) (look s locals) + N.of_nat U * D.potential B db)%N.
             rewrite run_term_calls_app. cbn [action_prim_work]. rewrite <- Hvalues, Hprim.
             rewrite !Nat2N.inj_add.
             assert (Hpositive : (1 <= N.of_nat (run_action_weight cp (Let x op args)))%N)
               by lia.
             clear -Hsyntax Hclock Hprimitive Hfactor Hcharge Hpositive. nia.
        * try rewrite Hvs in Hvalues.
          pose proof (run_value_binding_charge args s Ts locals x (Id 1) W
            (run_action_weight cp (Let x op args)) Hterms Hx ltac:(cbn; lia)) as Hsyntax.
          assert (Hclock : (T_apply_go (Let x op args :: acts) s Ts locals db <=
            T_term_values s Ts locals args + 8)%N).
          { time_unfold T_apply_go. rewrite Hvs. lia. }
          cbn [apply_go]. rewrite Hvs.
          change (T_apply_go (Let x op args :: acts) s Ts locals db +
            N.of_nat U * D.potential B db <=
            run_action_budget B U W *
              N.of_nat (run_action_weight cp (Let x op args) + run_actions_weight cp acts + 1) +
            run_term_calls Ts (args ++ flat_map action_terms acts) +
            run_apply_factor * action_prim_work V.prim V.prim_work (program_kind p)
              (Let x op args :: acts) (look s locals) + N.of_nat U * D.potential B db)%N.
          rewrite run_term_calls_app. cbn [action_prim_work]. rewrite <- Hvalues.
          rewrite !Nat2N.inj_add. clear -Hsyntax Hclock Hcharge. nia.
  Qed.

  Lemma run_apply_wrapper_clock : forall acts s Ts db,
    (T_apply acts s Ts db <= T_apply_go acts s Ts Empty db + 2)%N.
  Proof.
    intros acts s Ts db. time_unfold T_apply. lia.
  Qed.

  (** Applying a rule pays for its actions, referenced bindings and transferred potential. *)
  Lemma T_apply_amort : forall B U p cp r s Ts db, plans_ok p cp -> D.wf db ->
    loaded p cp db -> In r (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) r s -> env_allocated db s ->
    (D.ids (apply (actions V.t r) s db) <= B)%N ->
    D.unit (apply (actions V.t r) s db) <= U ->
    (T_apply (actions V.t r) s Ts db +
      N.of_nat U * D.potential B (apply (actions V.t r) s db) <=
      k_driver * N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat ((fold_right (fun a n => match a with
          | Make _ f args | Put f args _ => ((length args + 2) * (length args + 2) *
              (length (filter (fun sl => Pos.eqb (fst sl) f) (Syntax.slots V.t cp)) + 1) + n)%nat
          | Union _ _ => (1 + n)%nat
          | Let _ _ args => (length args + 1 + n)%nat
          end) 0%nat (actions V.t r) + 1)%nat) +
      fold_right N.add 0 (map Ts (flat_map term_vars (flat_map action_terms (actions V.t r)))) +
      k_driver * action_prim_work V.prim V.prim_work (program_kind p) (actions V.t r) s +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U p cp r s Ts db Hplans Hwf Hloaded Hr Hrule Halloc HB HU.
    destruct (run_rule_actions_env p cp r s Hplans Hr Hrule) as [g [Hacts Henv]].
    assert (Henv_empty : env_sorted g (look s Empty)).
    { intros x ty Hx. rewrite run_look_empty. exact (Henv x ty Hx). }
    assert (Halloc_empty : env_allocated db (look s Empty)).
    { intros x i Hx. rewrite run_look_empty in Hx. exact (Halloc x i Hx). }
    pose proof (run_apply_go_amort (actions V.t r) p cp g s Ts Empty db (wbits p) B U
      Hplans Hwf Hloaded Hacts Henv_empty Halloc_empty (run_rule_width p r Hr) HB HU)
      as Hcost.
    assert (Hprim : action_prim_work V.prim V.prim_work (program_kind p) (actions V.t r)
      (look s Empty) = action_prim_work V.prim V.prim_work (program_kind p) (actions V.t r) s).
    { apply run_action_prim_work_agree. intro x. unfold run_value_view.
      rewrite run_look_empty. reflexivity. }
    rewrite Hprim in Hcost.
    pose proof (run_apply_wrapper_clock (actions V.t r) s Ts db) as Hwrapper.
    pose proof run_apply_factor_le as Hfactor.
    assert (Hunit : 1 <= U) by (pose proof (unit_pos (apply (actions V.t r) s db)); lia).
    destruct (run_spending_factors U (N.to_nat (N.log2 B) + 1) (wbits p) Hunit ltac:(lia))
      as [Hpositive _].
    assert (Hweight : (1 <= N.of_nat (run_actions_weight cp (actions V.t r) + 1))%N) by lia.
    change (T_apply (actions V.t r) s Ts db +
      N.of_nat U * D.potential B (apply_go (actions V.t r) s Empty db) <=
      k_driver * N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (run_actions_weight cp (actions V.t r) + 1) +
      run_term_calls Ts (flat_map action_terms (actions V.t r)) +
      k_driver * action_prim_work V.prim V.prim_work (program_kind p) (actions V.t r) s +
      N.of_nat U * D.potential B db)%N.
    unfold run_action_budget in Hcost. rewrite Nat2N.inj_mul.
    clear -Hcost Hwrapper Hfactor Hpositive Hweight. nia.
  Qed.

  (** * Filtering accepted plans *)

  Definition run_filter_width (width : nat) (ts : list (term V.t)) : Prop :=
    Forall (fun term => Forall (fun word => Pos.size_nat word <= width)
      (term_words V.encode term)) ts.

  Definition run_filter_cells (t : ptrie (cell V.t)) (width : nat) : Prop :=
    forall name value, trie_get name t = Some value -> cell_bits V.encode value <= width.

  Definition run_filter_factor : N := (128 * (V.c_val + V.c_key + PTrieT.c_trie + 1))%N.

  Lemma run_filter_factor_bounds :
    (128 <= run_filter_factor /\ 128 * V.c_key <= run_filter_factor /\
      128 * V.c_val <= run_filter_factor /\ 128 * PTrieT.c_trie <= run_filter_factor)%N.
  Proof.
    unfold run_filter_factor. repeat split; nia.
  Qed.

  Lemma run_filter_term_clock : forall t term width,
    Forall (fun word => Pos.size_nat word <= width) (term_words V.encode term) ->
    (T_trie_term t term <= 8 * N.of_nat (width + 1))%N.
  Proof.
    intros t [name|value] width Hwidth.
    - inversion Hwidth as [|word words Hname Hrest]; subst word words.
      time_unfold @T_trie_term. PTrieT.trie_get_le.
      destruct (trie_get name t) as [[id|v]|]; rewrite Nat2N.inj_add; lia.
    - time_unfold @T_trie_term. rewrite Nat2N.inj_add. lia.
  Qed.

  Lemma run_filter_terms_clock : forall ts t width,
    run_filter_width width ts ->
    (T_trie_terms t ts <= 16 * N.of_nat (length ts + 1) * N.of_nat (width + 1))%N.
  Proof.
    intro ts. induction ts as [|term ts IH]; intros t width Hwidth.
    - time_unfold @T_trie_terms. cbn [length]. rewrite Nat2N.inj_add. nia.
    - inversion Hwidth as [|term' ts' Hhead Htail]; subst term' ts'.
      pose proof (run_filter_term_clock t term width Hhead) as Hterm.
      pose proof (IH t width Htail) as Hrest.
      time_unfold @T_trie_terms.
      destruct (trie_term t term); [destruct (trie_terms t ts)|];
        cbn [length]; rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *; nia.
  Qed.

  Lemma run_filter_term_value_width : forall t term width cells value,
    Forall (fun word => Pos.size_nat word <= width) (term_words V.encode term) ->
    run_filter_cells t cells -> trie_term t term = Some value ->
    V.bits value <= width + cells.
  Proof.
    intros t [name|literal] width cells value Hwidth Hcells Hvalue.
    - cbn [trie_term] in Hvalue.
      destruct (trie_get name t) as [[id|stored]|] eqn:Hget; try discriminate.
      injection Hvalue as <-. specialize (Hcells name (Val stored) Hget).
      change (S (V.bits stored) <= cells) in Hcells. lia.
    - cbn [trie_term] in Hvalue. injection Hvalue as <-.
      inversion Hwidth as [|word words Hliteral Hrest]; subst word words.
      change (V.bits literal <= width) in Hliteral. lia.
  Qed.

  Lemma run_filter_terms_values : forall (ts : list (term V.t)) (t : ptrie (cell V.t)),
    trie_terms t ts = value_terms (fun name => trie_get name t) ts.
  Proof.
    intro ts. induction ts as [|[name|literal] ts IH]; intro t.
    - reflexivity.
    - cbn [trie_terms trie_term value_terms]. rewrite IH.
      destruct (trie_get name t) as [[id|value]|];
        destruct (value_terms (fun name => trie_get name t) ts); reflexivity.
    - cbn [trie_terms trie_term value_terms]. rewrite IH.
      destruct (value_terms (fun name => trie_get name t) ts); reflexivity.
  Qed.

  Lemma run_filter_cell_clock : forall left right cells,
    cell_bits V.encode left <= cells ->
    (T_cell_eqb V.eqb V.T_eqb left right <=
      (V.c_key + 4) * N.of_nat (cells + 1))%N.
  Proof.
    intros [a|a] [b|b] cells Hleft; time_unfold @T_cell_eqb;
      cbn [cell_bits Pos.size_nat] in Hleft.
    - pose proof (Pos.T_eqb_le a b) as Hcompare.
      rewrite Nat2N.inj_add. nia.
    - rewrite Nat2N.inj_add. nia.
    - rewrite Nat2N.inj_add. nia.
    - pose proof (V.T_eqb_le a b) as Hcompare.
      change (S (V.bits a) <= cells) in Hleft.
      rewrite !Nat2N.inj_add in *. nia.
  Qed.

  Lemma run_filter_prim_clock : forall t op args result width cells,
    run_filter_width width (args ++ [result]) -> run_filter_cells t cells ->
    (T_prim_holds V.prim V.T_prim V.eqb V.T_eqb t op args result <=
      run_filter_factor * N.of_nat (length args + 2) * N.of_nat (width + cells + 1) +
      V.c_val * match value_terms (fun name => trie_get name t) args with
        | Some values => V.prim_work op values
        | None => 0
        end)%N.
  Proof.
    intros t op args result width cells Hwidth Hcells.
    apply Forall_app in Hwidth. destruct Hwidth as [Hargs Hresult].
    inversion Hresult as [|result' rest Hres Hnil]; subst result' rest.
    pose proof (run_filter_terms_clock args t width Hargs) as Hargs_clock.
    pose proof (run_filter_term_clock t result width Hres) as Hres_clock.
    destruct run_filter_factor_bounds as [Hfactor [Hkey [Hvalue Htrie]]].
    rewrite <- run_filter_terms_values.
    time_unfold @T_prim_holds.
    destruct (trie_terms t args) as [values|] eqn:Hargs_value.
    - pose proof (V.T_prim_le op values) as Hprim.
      destruct (V.prim op values) as [value|] eqn:Hprim_value.
      + destruct (trie_term t result) as [stored|] eqn:Hstored.
        * pose proof (run_filter_term_value_width t result width cells stored Hres Hcells
            Hstored) as Hstored_width.
          pose proof (V.T_eqb_le stored value) as Hcompare.
          rewrite !Nat2N.inj_add in *. nia.
        * rewrite !Nat2N.inj_add in *. nia.
      + rewrite !Nat2N.inj_add in *. nia.
    - rewrite !Nat2N.inj_add in *. nia.
  Qed.

  Definition run_filter_copy_credit (result : option (list positive)) : N :=
    match result with
    | Some names => N.of_nat (run_vars_size names)
    | None => 0%N
    end.

  (** A copied name is paid once, when the filter consumes it. *)
  Lemma run_filter_copies_clock : forall terms t seen copies width cells,
    run_filter_width width terms -> run_filter_cells t cells ->
    (T_copies_ok V.eqb V.T_eqb t seen terms copies +
      run_filter_factor * run_filter_copy_credit (copies_ok V.eqb t seen terms copies) <=
      run_filter_factor * (N.of_nat (length terms + 1) * N.of_nat (width + cells + 1) +
        N.of_nat (run_vars_size copies)))%N.
  Proof.
    intro terms. induction terms as [|[name|literal] terms IH];
      intros t seen copies width cells Hwidth Hcells.
    - time_unfold @T_copies_ok.
      cbn [copies_ok run_filter_copy_credit length].
      pose proof (proj1 run_filter_factor_bounds). rewrite !Nat2N.inj_add. nia.
    - inversion Hwidth as [|term rest Hname Hterms]; subst term rest.
      inversion Hname as [|word words Hname_width Hnil]; subst word words.
      destruct run_filter_factor_bounds as [Hfactor [Hkey [Hvalue Htrie]]].
      pose proof (PTrieT.T_set_le unit name tt seen) as Hset.
      time_unfold @T_copies_ok. cbn [copies_ok].
      PTrieT.trie_get_le.
      destruct (trie_get name seen) as [[]|] eqn:Hseen.
      + destruct copies as [|copy more].
        * cbn [run_filter_copy_credit run_vars_size fold_right length].
          rewrite !Nat2N.inj_add, !Nat2N.inj_succ. nia.
        * pose proof (IH t seen more width cells Hterms Hcells) as Htail.
          PTrieT.trie_get_le.
          destruct (trie_get copy t) as [left|] eqn:Hleft;
            destruct (trie_get name t) as [right|] eqn:Hright.
          -- pose proof (run_filter_cell_clock left right cells (Hcells copy left Hleft))
               as Hcompare.
             destruct (cell_eqb V.eqb left right) eqn:Hequal.
             ++ cbn [length].
                change (run_vars_size (copy :: more)) with
                  (Pos.size_nat copy + 1 + run_vars_size more).
                rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *. nia.
             ++ cbn [run_filter_copy_credit length].
                change (run_vars_size (copy :: more)) with
                  (Pos.size_nat copy + 1 + run_vars_size more).
                rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *. nia.
          -- cbn [run_filter_copy_credit length].
             change (run_vars_size (copy :: more)) with
               (Pos.size_nat copy + 1 + run_vars_size more).
             rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *. nia.
          -- cbn [run_filter_copy_credit length].
             change (run_vars_size (copy :: more)) with
               (Pos.size_nat copy + 1 + run_vars_size more).
             rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *. nia.
          -- cbn [run_filter_copy_credit length].
             change (run_vars_size (copy :: more)) with
               (Pos.size_nat copy + 1 + run_vars_size more).
             rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *. nia.
      + pose proof (IH t (PTrieCode.set name tt seen) copies width cells Hterms Hcells)
          as Htail.
        cbn [length]. rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *. nia.
    - inversion Hwidth as [|term rest Hliteral Hterms]; subst term rest.
      pose proof (IH t seen copies width cells Hterms Hcells) as Htail.
      pose proof (proj1 run_filter_factor_bounds) as Hfactor.
      time_unfold @T_copies_ok. cbn [copies_ok length].
      rewrite !Nat2N.inj_add, !Nat2N.inj_succ in *. nia.
  Qed.

  Definition run_filter_post_work (q : list (atom V.t)) (posts : list nat) : nat :=
    fold_right (fun index budget => index + 1 +
      match nth_error q index with
      | Some a => length (atom_terms a)
      | None => 0
      end + budget) 0 posts.

  Lemma run_filter_post_work_cons : forall q index a posts,
    nth_error q index = Some a ->
    run_filter_post_work q (index :: posts) =
      index + 1 + length (atom_terms a) + run_filter_post_work q posts.
  Proof.
    intros q index a posts Hindex. unfold run_filter_post_work. cbn [fold_right].
    now rewrite Hindex.
  Qed.

  Lemma run_filter_nth_clock : forall (q : list (atom V.t)) index,
    (List.T_nth_error q index <= N.of_nat index + 1)%N.
  Proof.
    intro q. induction q as [|a q IH]; intros [|index]; time_step.
  Qed.

  (** Exact checked post lists charge each query primitive at most once. *)
  Lemma run_filter_posts_clock : forall q whole index t copies width cells,
    (forall j a, nth_error q j = Some a -> nth_error whole (index + j) = Some a) ->
    run_query_width width q -> run_filter_cells t cells ->
    (T_keep_post V.prim V.T_prim V.eqb V.T_eqb whole t (run_query_post q index) copies <=
      4 * run_filter_factor *
        N.of_nat (run_filter_post_work whole (run_query_post q index) + 1) *
        N.of_nat (width + cells + 1) +
      run_filter_factor * query_prim_work V.prim_work q (fun name => trie_get name t) +
      run_filter_factor * N.of_nat (run_vars_size copies))%N.
  Proof.
    intro q. induction q as [|a q IH];
      intros whole index t copies width cells Hindex Hwidth Hcells.
    - cbn [run_query_post run_filter_post_work query_prim_work fold_right].
      time_unfold @T_keep_post. pose proof (proj1 run_filter_factor_bounds) as Hfactor.
      rewrite !Nat2N.inj_add. nia.
    - inversion Hwidth as [|a' q' Hhead Htail]; subst a' q'.
      assert (Hhere : nth_error whole index = Some a).
      { replace index with (index + 0) at 1 by lia. apply Hindex. reflexivity. }
      assert (Hnext : forall j a', nth_error q j = Some a' ->
          nth_error whole (S index + j) = Some a').
      { intros j a' Hget. replace (S index + j) with (index + S j) by lia.
        apply Hindex. exact Hget. }
      pose proof (run_filter_nth_clock whole index) as Hnth.
      destruct run_filter_factor_bounds as [Hfactor [Hkey [Hvalue Htrie]]].
      destruct a as [function args result|op args result].
      + cbn [run_query_post query_prim_work fold_right].
        destruct (run_term_duplicates Empty (args ++ option_list result))
          as [|duplicate duplicates] eqn:Hduplicates.
        * apply IH; assumption.
        * rewrite (run_filter_post_work_cons whole index (Fun V.t function args result)
            (run_query_post q (S index)) Hhere).
          inversion Hhead as [|word words Hfunction Hterms]; subst word words.
          assert (Hterms_width : run_filter_width width (args ++ option_list result)).
          { unfold run_filter_width. rewrite Forall_forall in *.
            intros term Hterm. rewrite Forall_forall. intros word Hword.
            apply Hterms. apply in_flat_map. now exists term. }
          pose proof (run_filter_copies_clock (args ++ option_list result) t Empty copies
            width cells Hterms_width Hcells) as Hcopies.
          pose proof (Datatypes.T_app_le args (option_list result)) as Happend.
          pose proof (run_check_option_time result) as Hoption.
          assert (Hargs_length : length args <= length (args ++ option_list result)).
          { rewrite length_app. lia. }
          time_unfold @T_keep_post. rewrite Hhere.
          destruct (copies_ok V.eqb t Empty (args ++ option_list result) copies)
            as [remaining|] eqn:Hcopy.
          -- pose proof (IH whole (S index) t remaining width cells Hnext Htail Hcells)
               as Hrest.
             unfold query_prim_work in Hrest.
             cbn [run_filter_copy_credit] in Hcopies.
             cbn [atom_terms]. rewrite !Nat2N.inj_add in *.
             clear -Hfactor Hcopies Happend Hoption Hrest Hnth Hargs_length. nia.
          -- cbn [run_filter_copy_credit] in Hcopies.
             cbn [atom_terms]. rewrite !Nat2N.inj_add in *.
             clear -Hfactor Hcopies Happend Hoption Hnth Hargs_length. nia.
      + cbn [run_query_post query_prim_work fold_right].
        rewrite (run_filter_post_work_cons whole index (Prim V.t op args result)
          (run_query_post q (S index)) Hhere).
        inversion Hhead as [|word words Hop Hterms]; subst word words.
        assert (Hterms_width : run_filter_width width (args ++ [result])).
        { unfold run_filter_width. rewrite Forall_forall in *.
          intros term Hterm. rewrite Forall_forall. intros word Hword.
          apply Hterms. apply in_flat_map. now exists term. }
        pose proof (run_filter_prim_clock t op args result width cells Hterms_width Hcells)
          as Hprim.
        pose proof (IH whole (S index) t copies width cells Hnext Htail Hcells) as Hrest.
        unfold query_prim_work in Hrest.
        time_unfold @T_keep_post. rewrite Hhere.
        destruct (value_terms (fun name => trie_get name t) args) as [values|] eqn:Hvalues;
          destruct (prim_holds V.prim V.eqb t op args result);
          cbn [atom_terms]; rewrite length_app; cbn [length];
          rewrite !Nat2N.inj_add in *;
          clear -Hfactor Hvalue Hprim Hrest Hnth; nia.
  Qed.

  Lemma run_filter_checked_post : forall p cp c, plans_ok p cp -> In c (all_plans cp) ->
    post V.t c = run_query_post (query V.t (job_rule p c)) 0.
  Proof.
    intros p cp c Hplans Hin.
    destruct (run_plan_member p cp c Hplans Hin)
      as [table [newok [r [Htable [Hrule Hcheck]]]]].
    assert (Hr : r = job_rule p c).
    { unfold job_rule. symmetry. eapply nth_error_nth. exact Hrule. }
    subst r.
    destruct (run_check_cplan_parts newok table (rule_ix V.t c) (job_rule p c) c Hcheck)
      as [_ [_ [names [expected [Hnames [Hlayout [Hquery Hpost]]]]]]].
    pose proof (run_check_query_post (query V.t (job_rule p c)) newok names
      (nvars (join V.t c)) table 0 0 Empty 0 (sources V.t c) (cols (join V.t c)) []
      (nat_n (nvars (join V.t c))) [] [] expected Hquery) as Hexpected.
    rewrite Hpost, Hexpected, !rev_append_rev, !app_nil_r, rev_involutive. reflexivity.
  Qed.

  Lemma run_filter_max_cell : forall (cells : list (cell V.t)) value, In value cells ->
    cell_bits V.encode value <=
      fold_right (fun item width => Nat.max (cell_bits V.encode item) width) 0 cells.
  Proof.
    intro cells. induction cells as [|head cells IH]; intros value Hin.
    - contradiction.
    - cbn [fold_right]. destruct Hin as [<-|Hin].
      + apply Nat.le_max_l.
      + eapply Nat.le_trans; [apply IH; exact Hin | apply Nat.le_max_r].
  Qed.

  Lemma run_filter_binding_width : forall c b,
    run_filter_cells (bind_trie c b)
      (fold_right (fun value width => Nat.max (cell_bits V.encode value) width) 0 b).
  Proof.
    intros c b name value Hget. rewrite bind_trie_spec in Hget.
    apply run_filter_max_cell. eapply run_binding_env_member. exact Hget.
  Qed.

  Lemma run_filter_values_agree : forall terms (s t : Model.env (V := V.t)),
    (forall name, s name = t name) -> value_terms s terms = value_terms t terms.
  Proof.
    intro terms. induction terms as [|[name|value] terms IH]; intros s t Hagree.
    - reflexivity.
    - cbn [value_terms]. rewrite Hagree, (IH s t Hagree). reflexivity.
    - cbn [value_terms]. rewrite (IH s t Hagree). reflexivity.
  Qed.

  Lemma run_filter_query_work_agree : forall q (s t : Model.env (V := V.t)),
    (forall name, s name = t name) ->
    query_prim_work V.prim_work q s = query_prim_work V.prim_work q t.
  Proof.
    intro q. induction q as [|[function args result|op args result] q IH]; intros s t Hagree.
    - reflexivity.
    - cbn [query_prim_work fold_right]. apply IH. exact Hagree.
    - cbn [query_prim_work fold_right].
      pose proof (IH s t Hagree) as Hrest. unfold query_prim_work in Hrest.
      rewrite (run_filter_values_agree args s t Hagree), Hrest. reflexivity.
  Qed.

  Lemma run_filter_keep_split : forall p c t,
    (T_keep p c t <= 8 + T_rule_at (rule_ix V.t c) (rules V.t p) +
      T_keep_post V.prim V.T_prim V.eqb V.T_eqb
        (query V.t (job_rule p c)) t (post V.t c) (var_of V.t c))%N.
  Proof.
    intros [decls rules] [index j sources vars posts] t.
    time_unfold T_keep. time_simpl. time_cbn.
    rewrite rule_at_nth. unfold job_rule.
    cbn [rule_ix query post var_of].
    destruct (nth (N.to_nat index) rules (Rule V.t [] [])) as [query actions].
    cbn [Syntax.query].
    change (fun p args => V.T_prim p args) with V.T_prim.
    change (fun a b => V.T_eqb a b) with V.T_eqb.
    nia.
  Qed.

  Lemma run_filter_factor_le : (4 * run_filter_factor + 16 <= k_driver)%N.
  Proof.
    unfold run_filter_factor, k_driver. nia.
  Qed.


  (** Checked plans satisfy the intended filter bound without repeating primitive charges. *)
  Lemma T7_keep_le_checked : forall p cp c b,
    plans_ok p cp -> In c (naive V.t cp ++ seminaive V.t cp) ->
    (T_keep p c (bind_trie c b) <= k_driver * N.of_nat (post_work p c + 1) *
      N.of_nat (wbits p + fold_right (fun x n => Nat.max (cell_bits V.encode x) n) 0%nat b + 1) +
      k_driver * query_prim_work V.prim_work (query V.t (job_rule p c)) (env_of c b) +
      k_driver * N.of_nat (rule_work p c) +
      k_driver * N.of_nat (fold_right (fun x n => (Pos.size_nat x + 1 + n)%nat) 0%nat
        (var_of V.t c) + 1))%N.
  Proof.
    intros p cp c b Hplans Hin.
    pose proof (run_filter_checked_post p cp c Hplans Hin) as Hposts.
    pose proof (job_rule_spec p cp c Hplans Hin) as Hrule.
    pose proof (run_program_query_width p) as Hwidth.
    rewrite Forall_forall in Hwidth.
    assert (Hrule_member : In (job_rule p c) (rules V.t p)).
    { now apply nth_error_In in Hrule. }
    specialize (Hwidth (job_rule p c) Hrule_member).
    pose proof (run_filter_posts_clock (query V.t (job_rule p c))
      (query V.t (job_rule p c)) 0 (bind_trie c b) (var_of V.t c) (wbits p)
      (fold_right (fun value width => Nat.max (cell_bits V.encode value) width) 0 b)
      (fun j a Hget => Hget) Hwidth (run_filter_binding_width c b)) as Hfilter.
    rewrite <- Hposts in Hfilter.
    rewrite (run_filter_query_work_agree (query V.t (job_rule p c))
      (fun name => trie_get name (bind_trie c b)) (env_of c b) (bind_trie_spec c b)) in Hfilter.
    change (run_filter_post_work (query V.t (job_rule p c)) (post V.t c))
      with (post_work p c) in Hfilter.
    pose proof (run_filter_keep_split p c (bind_trie c b)) as Hwrapper.
    pose proof (run_split_rule_clock (rule_ix V.t c) (rules V.t p)) as Hlookup.
    change ((length (rules V.t p) + 1) * (N.size_nat (rule_ix V.t c) + 1))
      with (rule_work p c) in Hlookup.
    pose proof run_filter_factor_le as Hfactor.
    unfold run_vars_size in Hfilter. rewrite Nat2N.inj_add.
    clear -Hfilter Hwrapper Hlookup Hfactor.
    nia.
  Qed.

  (** The filter of a checked plan pays for finding its rule, for looking up the names of its
      join variables, for its atoms at the widest program word or binding cell, and for the
      primitive work of the query. A checked plan lists each atom at most once. *)
  Lemma T_keep_le : forall p cp c b,
    plans_ok p cp -> In c (naive V.t cp ++ seminaive V.t cp) ->
    (T_keep p c (bind_trie c b) <= k_driver * N.of_nat (post_work p c + 1) *
      N.of_nat (wbits p + fold_right (fun x n => Nat.max (cell_bits V.encode x) n) 0%nat b + 1) +
      k_driver * query_prim_work V.prim_work (query V.t (job_rule p c)) (env_of c b) +
      k_driver * N.of_nat (rule_work p c) +
      k_driver * N.of_nat (fold_right (fun x n => (Pos.size_nat x + 1 + n)%nat) 0%nat
        (var_of V.t c) + 1))%N.
  Proof.
    exact T7_keep_le_checked.
  Qed.


  (** * Action and job cost aggregation *)


  Definition run_cost_scale (B : N) (U : nat) (p : program V.t) : N :=
    (N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) * N.of_nat (wbits p + 1))%N.

  Lemma run_cost_scale_factors : forall B U p, 1 <= U ->
    (1 <= run_cost_scale B U p)%N /\
    (N.of_nat (wbits p + 1) <= run_cost_scale B U p)%N /\
    (N.of_nat U <= run_cost_scale B U p)%N.
  Proof.
    intros B U p HU. unfold run_cost_scale.
    assert (Hu : (1 <= N.of_nat U)%N) by lia.
    assert (Hl : (1 <= N.of_nat (N.to_nat (N.log2 B) + 1))%N) by lia.
    assert (Hw : (1 <= N.of_nat (wbits p + 1))%N) by lia.
    repeat split; nia.
  Qed.

  Lemma run_cost_constants : (32 <= k_driver /\ D.c_db <= k_driver /\
    J.c_join <= k_driver /\ 64 * k_driver = c_run)%N.
  Proof.
    unfold k_driver, c_run. repeat split; nia.
  Qed.

  Lemma run_cost_nat_sum : forall (xs : list nat),
    fold_right N.add 0%N (map N.of_nat xs) = N.of_nat (fold_right Nat.add 0 xs).
  Proof.
    intro xs. induction xs as [|x xs IH]; cbn [map fold_right]; [reflexivity|].
    rewrite IH, Nat2N.inj_add. reflexivity.
  Qed.

  Lemma run_cost_term_variables : forall ts : list (term V.t),
    length (flat_map term_vars ts) <= length ts.
  Proof.
    intro ts. induction ts as [|[x|v] ts IH]; cbn [flat_map term_vars length app]; lia.
  Qed.

  Lemma run_cost_action_terms : forall cp a,
    length (action_terms a) <= 2 * run_action_weight cp a.
  Proof.
    intros cp [x f args|f args res|a b|x op args];
      cbn [action_terms run_action_weight length]; try nia.
    rewrite length_app. destruct res; cbn [option_list length]; nia.
  Qed.

  Lemma run_cost_action_variables : forall cp acts,
    length (flat_map term_vars (flat_map action_terms acts)) <=
      2 * run_actions_weight cp acts.
  Proof.
    intros cp acts. induction acts as [|a acts IH].
    - reflexivity.
    - change (length (flat_map term_vars (action_terms a ++ flat_map action_terms acts)) <=
        2 * run_actions_weight cp (a :: acts)).
      rewrite flat_map_app, length_app.
      pose proof (run_cost_term_variables (action_terms a)) as Hterms.
      pose proof (run_cost_action_terms cp a) as Haction.
      assert (Hweight : run_actions_weight cp (a :: acts) =
        run_action_weight cp a + run_actions_weight cp acts).
      { destruct a; reflexivity. }
      rewrite Hweight. lia.
  Qed.

  Lemma run_cost_rule_variables : forall p r,
    In r (rules V.t p) ->
    Forall (fun x => Pos.size_nat x <= wbits p)
      (flat_map term_vars (flat_map action_terms (actions V.t r))).
  Proof.
    intros p r Hr. pose proof (run_rule_width p r Hr) as Hwidth.
    apply Forall_forall. intros x Hx.
    apply in_flat_map in Hx as [t [Ht Hx]].
    apply in_flat_map in Ht as [a [Ha Ht]].
    apply Forall_forall with (x := a) in Hwidth; [|exact Ha].
    destruct Hwidth as [_ Hterms].
    apply Forall_forall with (x := t) in Hterms; [|exact Ht].
    exact (Hterms x Hx).
  Qed.

  Lemma run_cost_trie_calls : forall names (t : ptrie (cell V.t)) W,
    Forall (fun x => Pos.size_nat x <= W) names ->
    (fold_right N.add 0 (map (fun x => 1 + T_trie_get x t) names) <=
      3 * N.of_nat (W + 1) * N.of_nat (length names))%N.
  Proof.
    intros names t W Hnames. induction Hnames as [|x xs Hx Hxs IH].
    - cbn [map fold_right length]. nia.
    - cbn [map fold_right length]. rewrite Nat2N.inj_succ. PTrieT.trie_get_le.
      assert (Hwidth : (N.of_nat (Pos.size_nat x) <= N.of_nat W)%N) by lia.
      rewrite Nat2N.inj_add. nia.
  Qed.

  Lemma run_cost_rule_calls : forall p cp r (t : ptrie (cell V.t)), In r (rules V.t p) ->
    (fold_right N.add 0 (map (fun x => 1 + T_trie_get x t)
      (flat_map term_vars (flat_map action_terms (actions V.t r)))) <=
      6 * N.of_nat (wbits p + 1) * N.of_nat (run_actions_weight cp (actions V.t r)))%N.
  Proof.
    intros p cp r t Hr.
    pose proof (run_cost_trie_calls _ t (wbits p) (run_cost_rule_variables p r Hr)) as Hcalls.
    pose proof (run_cost_action_variables cp (actions V.t r)) as Hcount.
    assert (HcountN : (N.of_nat (length (flat_map term_vars
      (flat_map action_terms (actions V.t r)))) <=
      2 * N.of_nat (run_actions_weight cp (actions V.t r)))%N) by lia.
    nia.
  Qed.

  Definition run_cost_job_weight (p : program V.t) (cp : compiled V.t)
      (c : cplan V.t) (b : list (cell V.t)) : nat :=
    run_actions_weight cp (actions V.t (job_rule p c)) + 1 +
      N.to_nat (action_prim_work V.prim V.prim_work (program_kind p)
        (actions V.t (job_rule p c)) (env_of c b)).

  Lemma run_cost_apply_arithmetic : forall T P P' K A W F Q C : N,
    (6 <= K -> 1 <= A -> W <= A -> C <= 6 * W * F ->
      T + P' <= K * A * (F + 1) + C + K * Q + P ->
      T + P' <= 2 * K * A * (F + 1 + Q) + P)%N.
  Proof.
    intros T P P' K A W F Q C HK HA HW HC HT.
    assert (Hfactor : (6 * W <= K * A)%N) by nia.
    assert (Hcalls : (C <= K * A * F)%N).
    { eapply N.le_trans; [exact HC|]. now apply N.mul_le_mono_r. }
    assert (Hprimitive : (K * Q <= K * A * Q)%N).
    { apply N.mul_le_mono_r. nia. }
    nia.
  Qed.

  Lemma run_cost_apply_job : forall B U p cp c b db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    In (job_rule p c) (rules V.t p) ->
    rule_env (program_sorts p) (program_kind p) (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) ->
    env_allocated db (fun x => trie_get x (bind_trie c b)) ->
    (D.ids (apply (actions V.t (job_rule p c))
      (fun x => trie_get x (bind_trie c b)) db) <= B)%N ->
    D.unit (apply (actions V.t (job_rule p c))
      (fun x => trie_get x (bind_trie c b)) db) <= U ->
    (T_apply (actions V.t (job_rule p c)) (fun x => trie_get x (bind_trie c b))
      (fun x => (1 + T_trie_get x (bind_trie c b))%N) db +
      N.of_nat U * D.potential B (apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b)) db) <=
      2 * k_driver * run_cost_scale B U p * N.of_nat (run_cost_job_weight p cp c b) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U p cp c b db Hplans Hwf Hloaded Hr Henv Halloc HB HU.
    pose proof (T_apply_amort B U p cp (job_rule p c)
      (fun x => trie_get x (bind_trie c b)) (fun x => (1 + T_trie_get x (bind_trie c b))%N)
      db Hplans Hwf Hloaded Hr Henv Halloc HB HU) as Happly.
    pose proof (run_cost_rule_calls p cp (job_rule p c) (bind_trie c b) Hr) as Hcalls.
    assert (Hprim : action_prim_work V.prim V.prim_work (program_kind p)
      (actions V.t (job_rule p c)) (fun x => trie_get x (bind_trie c b)) =
      action_prim_work V.prim V.prim_work (program_kind p)
        (actions V.t (job_rule p c)) (env_of c b)).
    { apply run_action_prim_work_agree. intro x. unfold run_value_view.
      rewrite bind_trie_spec. reflexivity. }
    rewrite Hprim in Happly.
    assert (HUpos : 1 <= U).
    { pose proof (unit_pos (apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b)) db)); lia. }
    destruct (run_cost_scale_factors B U p HUpos) as [Hscale [Hwidth Hunit]].
    destruct run_cost_constants as [Hconstant Hconstants].
    change (T_apply (actions V.t (job_rule p c)) (fun x => trie_get x (bind_trie c b))
      (fun x => (1 + T_trie_get x (bind_trie c b))%N) db +
      N.of_nat U * D.potential B (apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b)) db) <=
      k_driver * N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (run_actions_weight cp (actions V.t (job_rule p c)) + 1) +
      fold_right N.add 0 (map (fun x => (1 + T_trie_get x (bind_trie c b))%N)
        (flat_map term_vars (flat_map action_terms (actions V.t (job_rule p c))))) +
      k_driver * action_prim_work V.prim V.prim_work (program_kind p)
        (actions V.t (job_rule p c)) (env_of c b) +
      N.of_nat U * D.potential B db)%N in Happly.
    rewrite Nat2N.inj_mul in Happly.
    replace (k_driver * N.of_nat U * (N.of_nat (N.to_nat (N.log2 B) + 1) *
      N.of_nat (wbits p + 1)))%N with (k_driver * run_cost_scale B U p)%N in Happly
      by (unfold run_cost_scale; ring).
    unfold run_cost_job_weight. rewrite !Nat2N.inj_add, N2Nat.id.
    rewrite Nat2N.inj_add in Happly.
    eapply run_cost_apply_arithmetic with
      (W := N.of_nat (wbits p + 1))
      (C := fold_right N.add 0%N (map (fun x => (1 + T_trie_get x (bind_trie c b))%N)
        (flat_map term_vars (flat_map action_terms (actions V.t (job_rule p c)))))).
    - lia.
    - exact Hscale.
    - exact Hwidth.
    - exact Hcalls.
    - exact Happly.
  Qed.
  Definition run_cost_jobs_weight (p : program V.t) (cp : compiled V.t)
      (js : list (cplan V.t * list (cell V.t))) : nat :=
    fold_right (fun cb n => run_cost_job_weight p cp (fst cb) (snd cb) + n) 0 js.

  (** Saved jobs transfer their potential through the actual evolving databases. *)
  Lemma run_cost_apply_jobs : forall B U p cp original js db,
    plans_ok p cp -> Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    (D.ids (apply_jobs p js db) <= B)%N -> D.unit (apply_jobs p js db) <= U ->
    (T_apply_jobs p js db + N.of_nat U * D.potential B (apply_jobs p js db) <=
      2 * k_driver * run_cost_scale B U p * N.of_nat (run_cost_jobs_weight p cp js) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U p cp original js. induction js as [|[c b] js IH];
      intros db Hplans Hfacts Hwf Hloaded Horigin HB HU.
    - cbn [T_apply_jobs apply_jobs run_cost_jobs_weight fold_right]. nia.
    - inversion Hfacts as [|cb rest Hhead Htail]; subst cb rest.
      destruct Hhead as [Hr [Henv [Halloc Hmatch]]].
      destruct (run_job_environment p original db c b Horigin Henv Halloc)
        as [Htyped Hallocated].
      set (next := apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b)) db).
      destruct (apply_wf p cp (job_rule p c)
        (fun x => trie_get x (bind_trie c b)) db Hplans Hwf Hloaded Hr Htyped Hallocated)
        as [Hnext [Hloadnext [Hidsnext Hunitnext]]].
      fold next in Hnext, Hloadnext, Hidsnext, Hunitnext.
      assert (Horiginnext : (D.ids original <= D.ids next)%N) by lia.
      change (D.ids (apply_jobs p js next) <= B)%N in HB.
      change (D.unit (apply_jobs p js next) <= U) in HU.
      destruct (run_apply_jobs_state p cp original js next Hplans Htail Hnext
        Hloadnext Horiginnext) as [_ [_ Hfinalids]].
      pose proof (run_apply_jobs_unit p cp original js next Hplans Htail Hnext
        Hloadnext Horiginnext) as Hfinalunit.
      pose proof (run_cost_apply_job B U p cp c b db Hplans Hwf Hloaded Hr
        Htyped Hallocated ltac:(fold next; lia) ltac:(fold next; lia)) as Hstep.
      fold next in Hstep.
      pose proof (IH next Hplans Htail Hnext Hloadnext Horiginnext HB HU) as Hrest.
      change (T_apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b))
        (fun x => (1 + T_trie_get x (bind_trie c b))%N) db + T_apply_jobs p js next +
        N.of_nat U * D.potential B (apply_jobs p js next) <=
        2 * k_driver * run_cost_scale B U p *
          N.of_nat (run_cost_job_weight p cp c b + run_cost_jobs_weight p cp js) +
        N.of_nat U * D.potential B db)%N.
      rewrite Nat2N.inj_add. clear -Hstep Hrest. nia.
  Qed.

  Lemma run_cost_actions_length : forall cp acts,
    length acts <= run_actions_weight cp acts.
  Proof.
    intros cp acts. induction acts as [|a acts IH].
    - reflexivity.
    - pose proof (run_action_weight_pos cp a) as Hpositive.
      assert (Hweight : run_actions_weight cp (a :: acts) =
        run_action_weight cp a + run_actions_weight cp acts) by (destruct a; reflexivity).
      rewrite Hweight. cbn [length]. lia.
  Qed.

  Lemma run_cost_jobs_pending : forall p cp original js db,
    plans_ok p cp -> Forall (run_job_facts p original) js ->
    D.wf db -> loaded p cp db -> (D.ids original <= D.ids db)%N ->
    D.pending (apply_jobs p js db) <= D.pending db + run_cost_jobs_weight p cp js.
  Proof.
    intros p cp original js. induction js as [|[c b] js IH];
      intros db Hplans Hfacts Hwf Hloaded Horigin.
    - cbn [apply_jobs run_cost_jobs_weight fold_right]. lia.
    - inversion Hfacts as [|cb rest Hhead Htail]; subst cb rest.
      destruct Hhead as [Hr [Henv [Halloc Hmatch]]].
      destruct (run_job_environment p original db c b Horigin Henv Halloc)
        as [Htyped Hallocated].
      set (next := apply (actions V.t (job_rule p c))
        (fun x => trie_get x (bind_trie c b)) db).
      destruct (run_apply_state p cp (job_rule p c)
        (fun x => trie_get x (bind_trie c b)) db Hplans Hwf Hloaded Hr Htyped Hallocated)
        as [Hnext [Hloadnext [Hidsnext Hpending]]].
      fold next in Hnext, Hloadnext, Hidsnext, Hpending.
      pose proof (IH next Hplans Htail Hnext Hloadnext ltac:(lia)) as Hrest.
      pose proof (run_cost_actions_length cp (actions V.t (job_rule p c))) as Hlength.
      change (D.pending (apply_jobs p js next) <=
        D.pending db + (run_cost_job_weight p cp c b + run_cost_jobs_weight p cp js)).
      unfold run_cost_job_weight. lia.
  Qed.

  Lemma run_cost_rebuild : forall B U db, D.wf db ->
    (D.ids (D.rebuild db) <= B)%N -> D.unit (D.rebuild db) <= U ->
    (D.T_rebuild db + N.of_nat U * D.potential B (D.rebuild db) <=
      D.c_db * N.of_nat U * N.of_nat (D.pending db + 1) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U db Hwf HB HU.
    pose proof (D.T_rebuild_amort B db Hwf HB) as Hrebuild.
    pose proof (unit_scale (D.T_rebuild db)
      (D.c_db * N.of_nat (D.pending db + 1)) (D.potential B db)
      (D.potential B (D.rebuild db)) (D.unit (D.rebuild db)) U
      (unit_pos _) HU Hrebuild) as Hscaled.
    nia.
  Qed.

  Definition run_cost_binding_base (p : program V.t) (cp : compiled V.t)
      (c : cplan V.t) : nat :=
    fold_right (fun x n => Pos.size_nat x + 1 + n) 0 (var_of V.t c) +
      post_work p c + rule_work p c + 1 + run_actions_weight cp (actions V.t (job_rule p c)).

  Definition run_cost_binding_weight (p : program V.t) (cp : compiled V.t)
      (c : cplan V.t) (b : list (cell V.t)) : nat :=
    run_cost_binding_base p cp c +
      N.to_nat (query_prim_work V.prim_work (query V.t (job_rule p c)) (env_of c b) +
        action_prim_work V.prim V.prim_work (program_kind p)
          (actions V.t (job_rule p c)) (env_of c b))%N.

  Definition run_cost_join_weight (db : D.t) (c : cplan V.t) : nat :=
    (J.work (join V.t c) (map (source_index db) (sources V.t c)) +
      length (sources V.t c) + source_bits c + 2) *
      (nvars (join V.t c) + 1) * (nvars (join V.t c) + 1).

  Definition run_cost_plan_weight (p : program V.t) (cp : compiled V.t)
      (db : D.t) (c : cplan V.t) : nat :=
    run_cost_join_weight db c + fold_right Nat.add 0
      (map (run_cost_binding_weight p cp c) (bindings cp c db)).

  Lemma run_cost_sum_constant : forall (A : Type) (f : A -> nat) xs a,
    fold_right Nat.add 0 (map (fun x => a + f x) xs) =
      length xs * a + fold_right Nat.add 0 (map f xs).
  Proof.
    intros A f xs. induction xs as [|x xs IH]; intro a; cbn [map fold_right length].
    - lia.
    - rewrite IH. lia.
  Qed.

  Lemma run_cost_round_work : forall p cp nv db,
    round_work p cp nv db = length (Syntax.slots V.t cp) +
      fold_right Nat.add 0 (map (run_cost_plan_weight p cp db)
        (if nv then naive V.t cp else seminaive V.t cp)).
  Proof.
    intros p cp nv db. unfold round_work. f_equal. f_equal.
    apply map_ext. intro c. unfold run_cost_plan_weight, run_cost_binding_weight.
    rewrite run_cost_sum_constant.
    unfold run_cost_join_weight, run_cost_binding_base, run_actions_weight, job_rule.
    lia.
  Qed.

  (** Mapping before a fold is the same as mapping each element at its fold step. *)
  Lemma run_cost_fold_map : forall (A B C : Type) (f : B -> C -> C)
      (g : A -> B) initial xs,
    fold_right f initial (map g xs) =
      fold_right (fun x acc => f (g x) acc) initial xs.
  Proof.
    intros A B C f g initial xs. induction xs as [|x xs IH];
      cbn [fold_right map]; [reflexivity|now rewrite IH].
  Qed.

  Lemma run_cost_sum_app : forall (A : Type) (f : A -> nat) xs ys,
    fold_right (fun x n => f x + n) 0 (xs ++ ys) =
      fold_right (fun x n => f x + n) 0 xs + fold_right (fun x n => f x + n) 0 ys.
  Proof.
    intros A f xs ys. induction xs as [|x xs IH]; cbn [app fold_right]; lia.
  Qed.

  Lemma run_cost_sum_filter : forall (A : Type) (test : A -> bool) (f : A -> nat) xs,
    fold_right (fun x n => f x + n) 0 (filter test xs) <=
      fold_right (fun x n => f x + n) 0 xs.
  Proof.
    intros A test f xs. induction xs as [|x xs IH]; cbn [filter fold_right]; [lia|].
    destruct (test x); cbn [fold_right]; lia.
  Qed.

  Lemma run_cost_sum_mono : forall (A : Type) (f g : A -> nat) xs,
    (forall x, In x xs -> f x <= g x) ->
    fold_right (fun x n => f x + n) 0 xs <= fold_right (fun x n => g x + n) 0 xs.
  Proof.
    intros A f g xs. induction xs as [|x xs IH]; intro Hle; cbn [fold_right]; [lia|].
    pose proof (Hle x (or_introl eq_refl)) as Hhead.
    assert (Htail : forall y, In y xs -> f y <= g y).
    { intros y Hy. apply Hle. now right. }
    specialize (IH Htail). lia.
  Qed.

  Lemma run_cost_job_binding : forall p cp c b,
    run_cost_job_weight p cp c b <= run_cost_binding_weight p cp c b.
  Proof.
    intros p cp c b.
    unfold run_cost_job_weight, run_cost_binding_weight, run_cost_binding_base.
    rewrite N2Nat.inj_add. lia.
  Qed.

  Lemma run_cost_jobs_weight_bound : forall p cp nv db,
    run_cost_jobs_weight p cp (jobs p cp nv db) <= round_work p cp nv db.
  Proof.
    intros p cp nv db. rewrite jobs_def, run_cost_round_work.
    assert (Hbound : forall cs,
      run_cost_jobs_weight p cp
        (flat_map (fun c => map (fun b => (c, b))
          (filter (fun b => keep p c (bind_trie c b)) (bindings cp c db))) cs) <=
      fold_right Nat.add 0 (map (run_cost_plan_weight p cp db) cs)).
    { intro cs. induction cs as [|c cs IH]; cbn [flat_map].
      - reflexivity.
      - unfold run_cost_jobs_weight in *. rewrite run_cost_sum_app.
        rewrite run_cost_fold_map. cbn [fst snd].
        pose proof (run_cost_sum_filter (list (cell V.t))
          (fun b => keep p c (bind_trie c b)) (run_cost_job_weight p cp c)
          (bindings cp c db)) as Hfilter.
        pose proof (run_cost_sum_mono (list (cell V.t))
          (run_cost_job_weight p cp c) (run_cost_binding_weight p cp c)
          (bindings cp c db) (fun b _ => run_cost_job_binding p cp c b)) as Hweight.
        cbn [map fold_right]. unfold run_cost_plan_weight in IH |- *.
        rewrite run_cost_fold_map. cbn beta. lia. }
    specialize (Hbound (if nv then naive V.t cp else seminaive V.t cp)). lia.
  Qed.

  (** * Source and binding widths *)

  Lemma run_cost_unit_mark : forall db, N.size_nat (D.wmark db) + 1 <= D.unit db.
  Proof.
    intro db. unfold D.unit. nia.
  Qed.

  Lemma run_cost_index_width : forall db slot new, D.wf db ->
    Pos.size_nat (I.next (D.index slot new db)) + I.max_cell_bits (D.index slot new db) <=
      2 * D.unit db.
  Proof.
    intros db slot new Hwf.
    destruct (D.wmark_index db slot new Hwf) as [Hnext Hcells].
    pose proof (run_cost_unit_mark db) as Hunit.
    assert (Hnextbits : Pos.size_nat (I.next (D.index slot new db)) <=
      N.size_nat (D.wmark db)).
    { destruct (D.wmark db) as [|mark]; [lia|]. cbn [N.size_nat].
      apply run_pos_size_mono. lia. }
    lia.
  Qed.

  Lemma run_cost_source_width : forall p db src, D.wf db ->
    (match src with Const _ c => exists v, c = Val v /\ In (Lit v) (program_terms p)
      | _ => True end) ->
    Pos.size_nat (I.next (source_index db src)) + I.max_cell_bits (source_index db src) <=
      2 * D.unit db + wbits p + 3.
  Proof.
    intros p db [slot|slot|c] Hwf Hsafe; cbn [source_index].
    - pose proof (run_cost_index_width db slot false Hwf). lia.
    - pose proof (run_cost_index_width db slot true Hwf). lia.
    - destruct Hsafe as [v [-> Hliteral]].
      pose proof (I.next_insert 1 [Val v] I.empty (I.wf_empty 1)) as Hnext.
      rewrite I.next_empty in Hnext. cbn [length Pos.of_nat] in Hnext.
      assert (Hnextbits : Pos.size_nat (I.next (I.insert [Val v] I.empty)) <= 2).
      { change (Pos.size_nat (I.next (I.insert [Val v] I.empty)) <= Pos.size_nat 2).
        apply run_pos_size_mono. lia. }
      pose proof (I.max_cell_bits_insert [Val v] I.empty) as Hcells.
      rewrite I.max_cell_bits_empty in Hcells.
      change (I.max_cell_bits (I.insert [Val v] I.empty) <=
        Nat.max 0 (Nat.max (cell_bits V.encode (Val v)) 0)) in Hcells.
      rewrite Nat.max_0_l, Nat.max_0_r in Hcells.
      pose proof (run_split_literal_width p v Hliteral) as Hwidth.
      change (cell_bits V.encode (Val v) <= wbits p + 1) in Hwidth. lia.
  Qed.

  Lemma run_cost_join_width : forall p cp db c, plans_ok p cp -> D.wf db ->
    In c (all_plans cp) ->
    J.wmax (join V.t c) (map (source_index db) (sources V.t c)) <=
      2 * D.unit db + wbits p + 3.
  Proof.
    intros p cp db c Hplans Hwf Hplan.
    pose proof (run_plan_constants p cp c Hplans Hplan) as Hsafe.
    unfold J.wmax. induction Hsafe as [|src srcs Hhead Htail IH].
    - cbn [map fold_right]. lia.
    - cbn [map fold_right]. apply Nat.max_lub; [|exact IH].
      now apply run_cost_source_width.
  Qed.

  Lemma run_cost_source_cell : forall p db src u cell, D.wf db ->
    (match src with Const _ c => exists v, c = Val v /\ In (Lit v) (program_terms p)
      | _ => True end) ->
    I.mem (source_index db src) u -> In cell u ->
    cell_bits V.encode cell <= D.unit db + wbits p + 1.
  Proof.
    intros p db [slot|slot|c] u cell Hwf Hsafe Hmem Hin;
      cbn [source_index] in Hmem.
    - destruct (D.index_all db slot false u Hwf Hmem)
        as [f [perm [k [o [Hslot [Hrow Heq]]]]]].
      subst u. apply run_permute_member in Hin.
      pose proof (D.wmark_cells db f k o cell Hwf Hrow Hin) as Hcell.
      pose proof (run_cost_unit_mark db). lia.
    - destruct (D.index_all db slot true u Hwf Hmem)
        as [f [perm [k [o [Hslot [Hrow Heq]]]]]].
      subst u. apply run_permute_member in Hin.
      pose proof (D.wmark_cells db f k o cell Hwf Hrow Hin) as Hcell.
      pose proof (run_cost_unit_mark db). lia.
    - destruct Hsafe as [v [-> Hliteral]].
      apply (proj1 (I.mem_insert 1 [Val v] I.empty u (I.wf_empty 1) eq_refl)) in Hmem.
      destruct Hmem as [->|Hempty].
      + cbn [In] in Hin. destruct Hin as [<-|[]].
        pose proof (run_split_literal_width p v Hliteral) as Hwidth.
        change (cell_bits V.encode (Val v) <= wbits p + 1) in Hwidth. lia.
      + exfalso. exact (I.mem_empty u Hempty).
  Qed.

  Lemma run_cost_column_cell : forall p db srcs columns b,
    D.wf db ->
    Forall (fun src => match src with
      | Const _ c => exists v, c = Val v /\ In (Lit v) (program_terms p)
      | _ => True end) srcs ->
    Forall2 (fun lv ix => exists u, J.project lv b = Some u /\ I.mem ix u)
      columns (map (source_index db) srcs) ->
    forall lv j cell, In lv columns -> In j lv -> nth_error b j = Some cell ->
      cell_bits V.encode cell <= D.unit db + wbits p + 1.
  Proof.
    intros p db srcs columns b Hwf Hsources. revert columns.
    induction Hsources as [|src srcs Hhead Htail IH];
      intros columns Hanswer lv j cell Hcolumn Hj Hnth.
    - inversion Hanswer; subst. contradiction.
    - destruct columns as [|col columns]; inversion Hanswer as
        [|lv' ix columns' ixs Hsource Hrest]; subst.
      destruct Hcolumn as [Heq|Hcolumn].
      + subst lv. destruct Hsource as [u [Hproject Hmem]].
        eapply run_cost_source_cell; [exact Hwf|exact Hhead|exact Hmem|].
        eapply run_project_selected; eassumption.
      + eapply IH; eassumption.
  Qed.

  Lemma run_cost_binding_cells : forall p cp db c b,
    plans_ok p cp -> D.wf db -> loaded p cp db -> In c (all_plans cp) ->
    In b (bindings cp c db) ->
    fold_right (fun x n => Nat.max (cell_bits V.encode x) n) 0 b <=
      D.unit db + wbits p + 1.
  Proof.
    intros p cp db c b Hplans Hwf Hloaded Hplan Hbinding.
    pose proof (run_plan_join_wf p cp db c Hplans Hwf Hloaded Hplan) as Hjoin.
    destruct (J.run_sound (join V.t c) (map (source_index db) (sources V.t c)) b
      Hjoin Hbinding) as [Hlength Hanswer].
    destruct Hjoin as [_ [_ Hcover]].
    assert (Hcells : Forall (fun cell => cell_bits V.encode cell <=
      D.unit db + wbits p + 1) b).
    { apply Forall_forall. intros cell Hin. apply In_nth_error in Hin as [j Hnth].
      assert (Hbound : j < nvars (join V.t c)).
      { rewrite <- Hlength. apply nth_error_Some. rewrite Hnth. discriminate. }
      destruct (Hcover j Hbound) as [lv [Hcol Hj]].
      eapply run_cost_column_cell; [exact Hwf| |exact Hanswer|exact Hcol|exact Hj|exact Hnth].
      now apply run_plan_constants with (cp := cp). }
    clear Hbinding Hlength Hanswer.
    induction Hcells as [|cell cells Hcell Hrest IH]; cbn [fold_right]; [lia|].
    now apply Nat.max_lub.
  Qed.

  (** * Amortized round cost *)

  Lemma run_round_scale_width : forall B U p,
    (N.of_nat U * N.of_nat (wbits p + 1) <= run_cost_scale B U p)%N.
  Proof.
    intros B U p. unfold run_cost_scale.
    change (N.of_nat U * N.of_nat (wbits p + 1) <=
      N.of_nat U * N.of_nat (N.to_nat (N.log2 B) + 1) * N.of_nat (wbits p + 1))%N.
    assert (HL : (1 <= N.of_nat (N.to_nat (N.log2 B) + 1))%N) by lia. nia.
  Qed.

  Lemma run_round_leaf_constants : (16 * (D.c_db + J.c_join + 1) <= k_driver)%N.
  Proof.
    unfold k_driver. nia.
  Qed.

  Lemma run_round_width_arithmetic : forall U W M, 1 <= U -> M <= U + W + 1 ->
    (N.of_nat (W + M + 1) <= 3 * (N.of_nat U * N.of_nat (W + 1)))%N.
  Proof.
    intros U W M HU HM. rewrite !Nat2N.inj_add.
    assert (Hu : (1 <= N.of_nat U)%N) by lia.
    assert (Hm : (N.of_nat M <= N.of_nat U + N.of_nat W + 1)%N) by lia. nia.
  Qed.

  Lemma run_round_filter_arithmetic : forall Tb Tk K A Width Vars Post Rule Acts Q AllQ : N,
    (1 <= A -> Width <= 3 * A -> Q <= AllQ ->
      Tb <= K * (Vars + 1) ->
      Tk <= K * (Post + 1) * Width + K * Q + K * Rule + K * (Vars + 1) ->
      Tb + Tk <= 8 * K * A * (Vars + Post + Rule + 1 + Acts + AllQ))%N.
  Proof.
    intros Tb Tk K A Width Vars Post Rule Acts Q AllQ HA HW HQ Hb Hk.
    assert (Hpost : (K * (Post + 1) * Width <= 3 * K * A * (Post + 1))%N) by nia.
    assert (Hvars : (K * (Vars + 1) <= K * A * (Vars + 1))%N) by nia.
    assert (Hrule : (K * Rule <= K * A * Rule)%N) by nia.
    assert (Hprim : (K * Q <= K * A * AllQ)%N) by nia.
    nia.
  Qed.

  Lemma run_round_binding_cost : forall B U p cp db c b,
    plans_ok p cp -> D.wf db -> loaded p cp db -> In c (all_plans cp) ->
    In b (bindings cp c db) -> D.unit db <= U -> 1 <= U ->
    (T_bind_trie c b + T_keep p c (bind_trie c b) <=
      8 * k_driver * run_cost_scale B U p * N.of_nat (run_cost_binding_weight p cp c b))%N.
  Proof.
    intros B U p cp db c b Hplans Hwf Hloaded Hplan Hbinding HU HUpos.
    pose proof (T_bind_trie_le c b) as Hbind.
    pose proof (T7_keep_le_checked p cp c b Hplans Hplan) as Hkeep.
    pose proof (run_cost_binding_cells p cp db c b Hplans Hwf Hloaded Hplan Hbinding)
      as Hcells.
    change (fold_right (fun x n => Nat.max (cell_bits V.encode x) n) 0 b <=
      D.unit db + wbits p + 1) in Hcells.
    pose proof (run_round_width_arithmetic U (wbits p)
      (fold_right (fun x n => Nat.max (cell_bits V.encode x) n) 0%nat b) HUpos ltac:(lia))
      as Hwidth.
    pose proof (run_round_scale_width B U p) as Hscale_width.
    destruct (run_cost_scale_factors B U p HUpos) as [Hscale Hrest].
    unfold run_cost_binding_weight, run_cost_binding_base.
    rewrite !Nat2N.inj_add, N2Nat.id.
    rewrite Nat2N.inj_add in Hbind.
    rewrite !Nat2N.inj_add in Hkeep.
    eapply run_round_filter_arithmetic with
      (Width := (N.of_nat (wbits p) + N.of_nat
        (fold_right (fun x n => Nat.max (cell_bits V.encode x) n) 0%nat b) + 1)%N).
    - exact Hscale.
    - rewrite !Nat2N.inj_add in Hwidth. nia.
    - apply N.le_add_r.
    - exact Hbind.
    - exact Hkeep.
  Qed.

  Lemma run_round_join_arithmetic : forall T K C A head larger width square : N,
    (6 * C <= K -> head <= larger -> width <= 6 * A ->
      T <= C * head * width * square -> T <= K * A * larger * square)%N.
  Proof.
    intros T K C A head larger width square HC HH HW HT.
    assert (Hfactor : (C * width <= K * A)%N) by nia.
    replace (C * head * width * square)%N with ((C * width) * (head * square))%N
      in HT by ring.
    replace (K * A * larger * square)%N with ((K * A) * (larger * square))%N by ring.
    eapply N.le_trans; [exact HT|]. apply N.mul_le_mono; [exact Hfactor|].
    now apply N.mul_le_mono_r.
  Qed.

  Lemma run_round_join_cost : forall B U p cp db c,
    plans_ok p cp -> D.wf db -> loaded p cp db -> In c (all_plans cp) ->
    D.unit db <= U -> 1 <= U ->
    (J.T_run (join V.t c) (map (source_index db) (sources V.t c)) <=
      k_driver * run_cost_scale B U p * N.of_nat (run_cost_join_weight db c))%N.
  Proof.
    intros B U p cp db c Hplans Hwf Hloaded Hplan HU HUpos.
    pose proof (J.T_run_le (join V.t c) (map (source_index db) (sources V.t c))
      (run_plan_join_wf p cp db c Hplans Hwf Hloaded Hplan)) as Hjoin.
    rewrite length_map in Hjoin.
    pose proof (run_cost_join_width p cp db c Hplans Hwf Hplan) as Hwidth.
    change (J.wmax (join V.t c) (map (source_index db) (sources V.t c)) <=
      2 * D.unit db + wbits p + 3) in Hwidth.
    pose proof (run_round_scale_width B U p) as Hscale.
    assert (HwidthN : (N.of_nat (J.wmax (join V.t c)
      (map (source_index db) (sources V.t c)) + 1) <=
      6 * run_cost_scale B U p)%N).
    { assert (Hu : (1 <= N.of_nat U)%N) by lia.
      assert (Hbound : (N.of_nat (J.wmax (join V.t c)
        (map (source_index db) (sources V.t c))) <=
        2 * N.of_nat U + N.of_nat (wbits p) + 3)%N) by lia.
      rewrite !Nat2N.inj_add in Hscale |- *. nia. }
    pose proof run_round_leaf_constants as Hconstant.
    unfold run_cost_join_weight. rewrite !Nat2N.inj_mul.
    change (J.T_run (join V.t c) (map (source_index db) (sources V.t c)) <=
      k_driver * run_cost_scale B U p *
      (N.of_nat (J.work (join V.t c) (map (source_index db) (sources V.t c)) +
        length (sources V.t c) + source_bits c + 2) * N.of_nat (nvars (join V.t c) + 1) *
        N.of_nat (nvars (join V.t c) + 1)))%N.
    replace (k_driver * run_cost_scale B U p *
      (N.of_nat (J.work (join V.t c) (map (source_index db) (sources V.t c)) +
        length (sources V.t c) + source_bits c + 2) * N.of_nat (nvars (join V.t c) + 1) *
        N.of_nat (nvars (join V.t c) + 1)))%N with
      (k_driver * run_cost_scale B U p *
        N.of_nat (J.work (join V.t c) (map (source_index db) (sources V.t c)) +
          length (sources V.t c) + source_bits c + 2) *
        N.of_nat ((nvars (join V.t c) + 1) * (nvars (join V.t c) + 1)))%N
      by (rewrite Nat2N.inj_mul; ring).
    eapply run_round_join_arithmetic with (K := k_driver) (A := run_cost_scale B U p)
      (C := J.c_join); [| |exact HwidthN|exact Hjoin].
    - change (16 * (D.c_db + J.c_join + 1) <= k_driver)%N in Hconstant. lia.
    - lia.
  Qed.

  Lemma run_round_sum_cost : forall (A : Type) (cost : A -> N) (weight : A -> nat) xs K,
    (forall x, In x xs -> (cost x <= K * N.of_nat (weight x))%N) ->
    (fold_right N.add 0 (map cost xs) <=
      K * N.of_nat (fold_right Nat.add 0%nat (map weight xs)))%N.
  Proof.
    intros A cost weight xs. induction xs as [|x xs IH]; intros K Hcost.
    - cbn [map fold_right]. nia.
    - pose proof (Hcost x (or_introl eq_refl)) as Hhead.
      assert (Hrest : forall y, In y xs -> (cost y <= K * N.of_nat (weight y))%N).
      { intros y Hy. apply Hcost. now right. }
      specialize (IH K Hrest). cbn [map fold_right].
      rewrite Nat2N.inj_add, N.mul_add_distr_l. now apply N.add_le_mono.
  Qed.

  Lemma run_round_selected : forall cp (nv : bool) c,
    In c (if nv then naive V.t cp else seminaive V.t cp) -> In c (all_plans cp).
  Proof.
    intros cp [|] c Hin; unfold all_plans; apply in_or_app; [now left|now right].
  Qed.

  Lemma run_round_joins_cost : forall B U p cp (nv : bool) db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> D.unit db <= U -> 1 <= U ->
    (fold_right N.add 0 (map (fun c => J.T_run (join V.t c)
      (map (source_index db) (sources V.t c)))
      (if nv then naive V.t cp else seminaive V.t cp)) <=
      k_driver * run_cost_scale B U p * N.of_nat (round_work p cp nv db))%N.
  Proof.
    intros B U p cp nv db Hplans Hwf Hloaded HU HUpos.
    eapply N.le_trans with (m := (k_driver * run_cost_scale B U p * N.of_nat
      (fold_right Nat.add 0%nat (map (run_cost_plan_weight p cp db)
        (if nv then naive V.t cp else seminaive V.t cp))))%N).
    - apply run_round_sum_cost. intros c Hin.
      pose proof (run_round_join_cost B U p cp db c Hplans Hwf Hloaded
        (run_round_selected cp nv c Hin) HU HUpos) as Hjoin.
      unfold run_cost_plan_weight. rewrite Nat2N.inj_add. nia.
    - apply N.mul_le_mono_l. rewrite run_cost_round_work. lia.
  Qed.

  Lemma run_round_filters_cost : forall B U p cp (nv : bool) db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> D.unit db <= U -> 1 <= U ->
    (fold_right N.add 0 (map (fun c => fold_right N.add 0
      (map (fun b => T_bind_trie c b + T_keep p c (bind_trie c b)) (bindings cp c db)))
      (if nv then naive V.t cp else seminaive V.t cp)) <=
      8 * k_driver * run_cost_scale B U p * N.of_nat (round_work p cp nv db))%N.
  Proof.
    intros B U p cp nv db Hplans Hwf Hloaded HU HUpos.
    eapply N.le_trans with (m := (8 * k_driver * run_cost_scale B U p * N.of_nat
      (fold_right Nat.add 0%nat (map (run_cost_plan_weight p cp db)
        (if nv then naive V.t cp else seminaive V.t cp))))%N).
    - apply run_round_sum_cost. intros c Hin.
      eapply N.le_trans with (m := (8 * k_driver * run_cost_scale B U p * N.of_nat
        (fold_right Nat.add 0%nat (map (run_cost_binding_weight p cp c)
          (bindings cp c db))))%N).
      + apply run_round_sum_cost. intros b Hbinding.
        eapply run_round_binding_cost; eassumption || exact (run_round_selected cp nv c Hin).
      + unfold run_cost_plan_weight. rewrite Nat2N.inj_add.
        apply N.mul_le_mono_l. apply N.le_add_l.
    - apply N.mul_le_mono_l. rewrite run_cost_round_work. lia.
  Qed.

  (** Advancing a loaded database is covered by the round's slot charge. *)
  Lemma run_round_advance_cost : forall B U p cp nv db,
    loaded p cp db -> 1 <= U ->
    (D.T_advance db <= k_driver * run_cost_scale B U p *
      (N.of_nat (round_work p cp nv db) + 1))%N.
  Proof.
    intros B U p cp nv db Hloaded HU.
    pose proof (D.T_advance_le db) as Hadvance.
    unfold D.num_slots in Hadvance. rewrite (proj1 (proj2 Hloaded)) in Hadvance.
    destruct (run_cost_scale_factors B U p HU) as [Hscale Hrest].
    destruct run_cost_constants as [_ [Hdatabase Hconstants]].
    assert (Hslots : length (Syntax.slots V.t cp) <= round_work p cp nv db).
    { rewrite round_work_def. lia. }
    eapply N.le_trans; [exact Hadvance|]. rewrite Nat2N.inj_add.
    eapply N.le_trans with
      (m := (k_driver * (N.of_nat (round_work p cp nv db) + 1))%N).
    - apply N.mul_le_mono; [exact Hdatabase|]. apply N.add_le_mono_r. lia.
    - apply N.mul_le_mono_r. rewrite <- (N.mul_1_r k_driver) at 1.
      apply N.mul_le_mono_l. exact Hscale.
  Qed.

  (** Six component estimates share one arithmetic budget. *)
  Lemma run_round_cost_arithmetic : forall T Jo Fi Ap Re Ad P Pmid Pfinal K r pending : N,
    (T <= Jo + Fi + Ap + Re + Ad + K * (r + 1) ->
      Jo <= K * r -> Fi <= 8 * K * r ->
      Ap + Pmid <= 2 * K * r + P ->
      Re + Pfinal <= K * (pending + r + 1) + Pmid ->
      Ad <= K * (r + 1) ->
      T + Pfinal <= 16 * K * (r + pending + 1) + P)%N.
  Proof.
    intros T Jo Fi Ap Re Ad P Pmid Pfinal K r pending
      Hsplit Hjoin Hfilter Happly Hrebuild Hadvance.
    nia.
  Qed.

  (** The sharper round estimate leaves room for the run wrapper and its final rebuild. *)
  Lemma run_round_cost_sharp : forall B U p cp (nv : bool) db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    (D.ids (round p cp nv db) <= B)%N -> D.unit (round p cp nv db) <= U ->
    (T_round p cp nv db + N.of_nat U * D.potential B (round p cp nv db) <=
      16 * k_driver * N.of_nat U *
        N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (round_work p cp nv db + D.pending db + 1) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U p cp nv db Hplans Hwf Hloaded HB HU.
    destruct (round_monotone p cp nv db Hplans Hwf Hloaded)
      as [Hroundwf [Hroundloaded [Hroundids Hroundunit]]].
    assert (HUpos : 1 <= U) by (pose proof (unit_pos (round p cp nv db)); lia).
    assert (Hstartunit : D.unit db <= U) by lia.
    pose proof (run_jobs_facts p cp nv db Hplans Hwf Hloaded) as Hfacts.
    destruct (run_advance_state p cp db Hwf Hloaded)
      as [Hadvancewf [Hadvanceloaded Hadvanceids]].
    assert (Horigin : (D.ids db <= D.ids (D.advance db))%N) by lia.
    set (applied := apply_jobs p (jobs p cp nv db) (D.advance db)).
    assert (Hround : round p cp nv db = D.rebuild applied) by apply round_eq_jobs.
    destruct (run_apply_jobs_state p cp db (jobs p cp nv db) (D.advance db)
      Hplans Hfacts Hadvancewf Hadvanceloaded Horigin) as [Hapwf [Haploaded Hapids]].
    change (D.wf applied) in Hapwf. change (loaded p cp applied) in Haploaded.
    destruct (run_rebuild_state p cp applied Hapwf Haploaded) as [_ [_ Hrebuildids]].
    assert (HBap : (D.ids applied <= B)%N).
    { rewrite <- Hrebuildids, <- Hround. exact HB. }
    assert (HUap : D.unit applied <= U).
    { pose proof (D.unit_mono_rebuild applied Hapwf) as Hmono.
      rewrite <- Hround in Hmono. lia. }
    assert (Hweight : run_cost_jobs_weight p cp (jobs p cp nv db) <= round_work p cp nv db).
    { apply run_cost_jobs_weight_bound. }
    assert (Happly : (T_apply_jobs p (jobs p cp nv db) (D.advance db) +
      N.of_nat U * D.potential B applied <=
      2 * k_driver * run_cost_scale B U p * N.of_nat (round_work p cp nv db) +
      N.of_nat U * D.potential B db)%N).
    { eapply N.le_trans.
      - eapply run_cost_apply_jobs; eassumption.
      - rewrite (proj2 (D.advance_credit B db Hwf)).
        apply N.add_le_mono_r. apply N.mul_le_mono_l. lia. }
    assert (Hpending : D.pending applied <= D.pending db + round_work p cp nv db).
    { pose proof (run_cost_jobs_pending p cp db (jobs p cp nv db) (D.advance db)
        Hplans Hfacts Hadvancewf Hadvanceloaded Horigin) as Hpending.
      change (D.pending applied <= D.pending (D.advance db) +
        run_cost_jobs_weight p cp (jobs p cp nv db)) in Hpending.
      rewrite (proj1 (proj2 (D.advance_keeps db Hwf))) in Hpending. lia. }
    destruct (run_cost_scale_factors B U p HUpos) as [Hscale [Hword Hunit]].
    change (N.of_nat (wbits p + 1) <= run_cost_scale B U p)%N in Hword.
    destruct run_cost_constants as [Hconstant [Hdatabase [Hjoinconstant Hrunconstant]]].
    assert (Hrebuild : (D.T_rebuild applied +
      N.of_nat U * D.potential B (round p cp nv db) <=
      k_driver * run_cost_scale B U p *
        N.of_nat (D.pending db + round_work p cp nv db + 1) +
      N.of_nat U * D.potential B applied)%N).
    { eapply N.le_trans.
      - rewrite Hround. eapply run_cost_rebuild; [exact Hapwf| |].
        + now rewrite <- Hround.
        + now rewrite <- Hround.
      - apply N.add_le_mono_r. apply N.mul_le_mono.
        + apply N.mul_le_mono; assumption.
        + lia. }
    pose proof (run_round_joins_cost B U p cp nv db Hplans Hwf Hloaded Hstartunit HUpos)
      as Hjoins.
    pose proof (run_round_filters_cost B U p cp nv db Hplans Hwf Hloaded Hstartunit HUpos)
      as Hfilters.
    pose proof (T_round_split p cp nv db Hplans Hwf Hloaded) as Hsplit.
    pose proof (run_round_advance_cost B U p cp nv db Hloaded HUpos) as Hadvance.
    assert (Hshell : (k_driver * N.of_nat (round_work p cp nv db + 1) *
      N.of_nat (wbits p + 1) <= k_driver * run_cost_scale B U p *
      (N.of_nat (round_work p cp nv db) + 1))%N).
    { rewrite Nat2N.inj_add. nia. }
    rewrite Nat2N.inj_mul.
    replace (16 * k_driver * N.of_nat U *
      (N.of_nat (N.to_nat (N.log2 B) + 1) * N.of_nat (wbits p + 1)))%N with
      (16 * (k_driver * run_cost_scale B U p))%N.
    2: { change (run_cost_scale B U p) with (N.of_nat U *
        N.of_nat (N.to_nat (N.log2 B) + 1) * N.of_nat (wbits p + 1))%N. ring. }
    rewrite !Nat2N.inj_add.
    eapply run_round_cost_arithmetic with
      (K := (k_driver * run_cost_scale B U p)%N)
      (r := N.of_nat (round_work p cp nv db)) (pending := N.of_nat (D.pending db))
      (Pmid := (N.of_nat U * D.potential B applied)%N)
      (Ap := T_apply_jobs p (jobs p cp nv db) (D.advance db))
      (Re := D.T_rebuild applied)
      (Ad := D.T_advance db)
      (Jo := (fold_right N.add 0 (map (fun c => J.T_run (join V.t c)
        (map (source_index db) (sources V.t c)))
        (if nv then naive V.t cp else seminaive V.t cp)))%N)
      (Fi := (fold_right N.add 0 (map (fun c => fold_right N.add 0
        (map (fun b => T_bind_trie c b + T_keep p c (bind_trie c b)) (bindings cp c db)))
        (if nv then naive V.t cp else seminaive V.t cp)))%N).
    - eapply N.le_trans; [exact Hsplit|]. apply N.add_le_mono_l. exact Hshell.
    - exact Hjoins.
    - replace (8 * (k_driver * run_cost_scale B U p))%N with
        (8 * k_driver * run_cost_scale B U p)%N by ring. exact Hfilters.
    - replace (2 * (k_driver * run_cost_scale B U p))%N with
        (2 * k_driver * run_cost_scale B U p)%N by ring. exact Happly.
    - rewrite !Nat2N.inj_add in Hrebuild. exact Hrebuild.
    - exact Hadvance.
  Qed.

  (** A checked round charges its joins, jobs and rebuild to one amortized budget. *)
  Lemma T_round_amort : forall B U p cp nv db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    (D.ids (round p cp nv db) <= B)%N -> D.unit (round p cp nv db) <= U ->
    (T_round p cp nv db + N.of_nat U * D.potential B (round p cp nv db) <=
      c_run * N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (round_work p cp nv db + D.pending db + 1) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U p cp nv db Hplans Hwf Hloaded HB HU.
    assert (Hcoefficient : (16 * k_driver <= c_run)%N).
    { unfold c_run, k_driver. nia. }
    eapply N.le_trans; [eapply run_round_cost_sharp; eassumption|].
    apply N.add_le_mono_r. apply N.mul_le_mono_r.
    apply N.mul_le_mono_r. apply N.mul_le_mono_r. exact Hcoefficient.
  Qed.

  (** * Amortized run cost *)


  (** A positive size code denotes its natural bit width. *)
  Lemma run_timing_positive_size : forall p, Pos.to_nat (Pos.size p) = Pos.size_nat p.
  Proof.
    intro p. induction p; cbn [Pos.size Pos.size_nat];
      rewrite ?Pos2Nat.inj_succ, ?IHp; reflexivity.
  Qed.

  (** The allocation counter's bit width fits the database spending unit. *)
  Lemma run_timing_ids_width : forall db, N.size_nat (D.ids db) <= D.unit db.
  Proof.
    intro db. assert (Hlog : forall n, N.size_nat n <= N.to_nat (N.log2 n) + 1).
    { intros [|[p|p|]]; cbn [N.size_nat N.log2 N.to_nat Pos.size_nat];
        rewrite ?run_timing_positive_size; lia. }
    pose proof (Hlog (D.ids db)). unfold D.unit. nia.
  Qed.

  (** Advance preserves both factors of the database spending unit. *)
  Lemma run_timing_advance_unit : forall db, D.wf db -> D.unit (D.advance db) = D.unit db.
  Proof.
    intros db Hwf. unfold D.unit.
    rewrite (proj1 (D.advance_keeps db Hwf)), (proj1 (D.advance_credit 0 db Hwf)).
    reflexivity.
  Qed.

  (** The fixed run coefficient leaves room for driver and fuel overhead. *)
  Lemma run_timing_constants : (c_run = 64 * k_driver /\ 32 <= k_driver /\
      D.c_db <= k_driver)%N.
  Proof.
    pose proof driver_constant_fields. unfold c_run, k_driver in *. nia.
  Qed.

  (** The allocation and syntax factors cover a terminal rebuild and fixed overhead. *)
  Lemma run_timing_factor : forall B U p, 1 <= U ->
    (1 <= N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)))%N /\
    (D.c_db * N.of_nat U <= 32 * k_driver * N.of_nat U *
      N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)))%N.
  Proof.
    intros B U p HU. destruct run_timing_constants as [_ [Hdriver Hdb]].
    assert (HL : (1 <= N.of_nat (N.to_nat (N.log2 B) + 1))%N) by lia.
    assert (HW : (1 <= N.of_nat (wbits p + 1))%N) by lia.
    rewrite Nat2N.inj_mul. split; nia.
  Qed.

  (** Binary and unary fuel return the same callback outcome. *)
  Lemma run_timing_loopN_fuel : forall (St Out : Type) (step : St -> St + Out) fuel state,
    loopN step fuel state = loop_fuel step (N.to_nat fuel) state.
  Proof.
    intros St Out step fuel state.
    assert (Hacc : forall fs (H : Acc (@loopN_lt St) fs),
      loop loopN_lt (loopN_step step) fs H =
        loop_fuel step (N.to_nat (fst fs)) (snd fs)).
    { intros fs H. induction H as [[n s] Hsmaller IH] using Acc_ind_dep.
      destruct n as [|n]; [reflexivity|].
      assert (Hpos : 0 < N.to_nat (N.pos n)) by apply Pos2Nat.is_pos.
      assert (Hpred : N.to_nat (N.pos n) = S (N.to_nat (N.pred (N.pos n)))).
      { rewrite N2Nat.inj_pred. lia. }
      cbn [fst snd]. rewrite Hpred.
      cbn [loop loopN_step loop_fuel]. destruct (step s) as [next|result];
        [apply IH|reflexivity]. }
    unfold loopN. apply Hacc.
  Qed.

  (** Every final driver state has at least the input allocation and spending unit. *)
  Lemma run_timing_loop_mono : forall p cp lim fuel nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    match loopN (driver p cp lim) fuel (nv, db) with
    | inl state => D.wf (snd state) /\ loaded p cp (snd state) /\
        (D.ids db <= D.ids (snd state))%N /\ D.unit db <= D.unit (snd state)
    | inr state => D.wf (snd state) /\ loaded p cp (snd state) /\
        (D.ids db <= D.ids (snd state))%N /\ D.unit db <= D.unit (snd state)
    end.
  Proof.
    intros p cp lim fuel nv db Hchecked Hwf Hloaded.
    refine (run_loop_database_invariant p cp lim
      (fun current => D.wf current /\ loaded p cp current /\
        (D.ids db <= D.ids current)%N /\ D.unit db <= D.unit current)
      _ fuel nv db _).
    - intros flag current [Hcurrent [Hloadcurrent [Hids Hunit]]].
      destruct (round_monotone p cp flag current Hchecked Hcurrent Hloadcurrent)
        as [Hnext [Hloadnext [Hidsnext Hunitnext]]].
      split; [exact Hnext|]. split; [exact Hloadnext|]. split; lia.
    - split; [exact Hwf|]. split; [exact Hloaded|]. split; reflexivity.
  Qed.

  (** Bounds on the rebuilt final state bound the input of any suffix of the run. *)
  Lemma run_timing_fuel_bounds : forall B U p cp lim fuel nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db ->
    let final := match loop_fuel (driver p cp lim) fuel (nv, db) with
      | inl (_, last) | inr (_, last) => last end in
    (D.ids (D.rebuild final) <= B)%N -> D.unit (D.rebuild final) <= U ->
    (D.ids db <= B)%N /\ D.unit db <= U.
  Proof.
    intros B U p cp lim fuel nv db Hchecked Hwf Hloaded.
    pose proof (run_timing_loop_mono p cp lim (N.of_nat fuel) nv db
      Hchecked Hwf Hloaded) as Hmono.
    rewrite run_timing_loopN_fuel, Nat2N.id in Hmono.
    destruct (loop_fuel (driver p cp lim) fuel (nv, db))
      as [[last_nv final]|[status final]]; cbn [snd] in Hmono |- *.
    all: intros Hids Hunit; destruct Hmono as [Hfinal [Hloadfinal [Hidsmono Hunitmono]]].
    all: rewrite (proj2 (proj2 (D.layout_rebuild final Hfinal))) in Hids.
    all: pose proof (D.unit_mono_rebuild final Hfinal); split; lia.
  Qed.

  (** Continuing callbacks return the completed round with its new rows intact. *)
  Lemma run_timing_driver_continue : forall p cp lim nv db next_nv next,
    driver p cp lim (nv, db) = inl (next_nv, next) ->
    next = round p cp nv db.
  Proof.
    intros p cp lim nv db next_nv next Hstep. rewrite driver_def in Hstep.
    cbn zeta in Hstep.
    destruct (max_ids lim <? D.ids (round p cp nv db))%N; [discriminate|].
    destruct (nv && negb (D.changed (round p cp nv db))); [discriminate|].
    now injection Hstep as <- <-.
  Qed.

  (** Stopping callbacks return the completed round without advance. *)
  Lemma run_timing_driver_stop : forall p cp lim nv db status next,
    driver p cp lim (nv, db) = inr (status, next) -> next = round p cp nv db.
  Proof.
    intros p cp lim nv db status next Hstep. rewrite driver_def in Hstep.
    cbn zeta in Hstep.
    destruct (max_ids lim <? D.ids (round p cp nv db))%N.
    - now injection Hstep as <- <-.
    - destruct (nv && negb (D.changed (round p cp nv db))); [|discriminate].
      now injection Hstep as <- <-.
  Qed.

  (** A canonical round with no pending work pays only a fixed terminal rebuild charge. *)
  Lemma run_timing_idle_rebuild : forall B U db,
    D.wf db -> D.canonical db -> D.pending db = 0 ->
    (D.ids db <= B)%N -> D.unit db <= U ->
    (D.T_rebuild db <= D.c_db * N.of_nat U)%N.
  Proof.
    intros B U db Hwf Hcanonical Hpending Hids Hunit.
    pose proof (D.rebuild_idle db Hwf Hcanonical Hpending) as Hidle.
    assert (Hids' : (D.ids (D.rebuild db) <= B)%N) by now rewrite Hidle.
    assert (Hunit' : D.unit (D.rebuild db) <= U) by now rewrite Hidle.
    pose proof (run_cost_rebuild B U db Hwf Hids' Hunit') as Hcost.
    rewrite Hidle, Hpending in Hcost. cbn [N.of_nat] in Hcost. nia.
  Qed.

  (** Driver bookkeeping fits the spare half of the round coefficient. *)
  Lemma run_timing_driver_credit : forall k u f work pending slots bits,
    (32 <= k -> 1 <= u -> 1 <= f -> slots <= work -> bits <= u ->
      k * (slots + bits + 1) + 8 <= 16 * k * u * f * (work + pending + 1))%N.
  Proof.
    intros k u f work pending slots bits Hk Hu Hf Hslots Hbits.
    set (a := (u * f)%N). set (q := (work + pending + 1)%N).
    assert (Ha : (1 <= a)%N) by (unfold a; nia).
    assert (Hua : (u <= a)%N) by (unfold a; nia).
    assert (Hq : (1 <= q)%N) by (unfold q; lia).
    assert (Hwq : (work + 1 <= q)%N) by (unfold q; lia).
    assert (Huq : (u <= a * q)%N) by nia.
    assert (Hwork : (work + 1 <= a * q)%N) by nia.
    assert (Hsmall : (k * (slots + bits + 1) + 8 <= 16 * k * a * q)%N) by nia.
    unfold a, q in Hsmall. nia.
  Qed.

  (** The sharper round estimate also pays one callback and its loop overhead. *)
  Lemma run_timing_driver_amort : forall B U p cp lim nv db,
    plans_ok p cp -> D.wf db -> loaded p cp db -> D.unit (round p cp nv db) <= U ->
    (T_round p cp nv db + N.of_nat U * D.potential B (round p cp nv db) <=
      16 * k_driver * N.of_nat U *
        N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (round_work p cp nv db + D.pending db + 1) +
      N.of_nat U * D.potential B db)%N ->
    (T_driver p cp lim (nv, db) + c_loopN +
      N.of_nat U * D.potential B (round p cp nv db) <=
      32 * k_driver * N.of_nat U *
        N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (round_work p cp nv db + D.pending db + 1) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U p cp lim nv db Hchecked Hwf Hloaded Hunit Hround.
    pose proof (T_driver_split p cp lim nv db Hchecked Hwf Hloaded) as Hdriver.
    pose proof (run_timing_ids_width (round p cp nv db)) as Hbits.
    assert (HU : 1 <= U) by (pose proof (unit_pos (round p cp nv db)); lia).
    destruct (run_timing_factor B U p HU) as [Hfactor Hdb].
    assert (Hslots : length (Syntax.slots V.t cp) <= round_work p cp nv db).
    { rewrite round_work_def. lia. }
    destruct run_timing_constants as [_ [Hconstant Hdbconstant]].
    pose proof (run_timing_driver_credit k_driver (N.of_nat U)
      (N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)))
      (N.of_nat (round_work p cp nv db)) (N.of_nat (D.pending db))
      (N.of_nat (length (Syntax.slots V.t cp)))
      (N.of_nat (N.size_nat (D.ids (round p cp nv db)))) Hconstant
      ltac:(lia) Hfactor ltac:(lia) ltac:(lia)) as Hcredit.
    rewrite !Nat2N.inj_add in Hdriver, Hround |- *. unfold c_loopN. nia.
  Qed.

  (** Callback costs telescope, retaining only initial pending work and a terminal rebuild. *)
  Lemma run_timing_fuel_cost : forall B U p cp lim,
    (forall nv db, D.wf db -> loaded p cp db ->
      (D.ids (round p cp nv db) <= B)%N -> D.unit (round p cp nv db) <= U ->
      (T_round p cp nv db + N.of_nat U * D.potential B (round p cp nv db) <=
        16 * k_driver * N.of_nat U *
          N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
          N.of_nat (round_work p cp nv db + D.pending db + 1) +
        N.of_nat U * D.potential B db)%N) ->
    plans_ok p cp -> forall fuel nv db, D.wf db -> loaded p cp db ->
    let final := match loop_fuel (driver p cp lim) fuel (nv, db) with
      | inl (_, last) | inr (_, last) => last end in
    (D.ids (D.rebuild final) <= B)%N -> D.unit (D.rebuild final) <= U ->
    (fold_right N.add 0 (map (fun st => T_driver p cp lim st + c_loopN)
        (firstn fuel (driver_trace (driver p cp lim) fuel (nv, db)))) +
      D.T_rebuild final <=
      32 * k_driver * N.of_nat U *
        N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        (fold_right N.add 0 (map (fun start =>
          N.of_nat (round_work p cp (fst start) (snd start) + 1))
          (driver_trace (driver p cp lim) fuel (nv, db))) +
         N.of_nat (D.pending db + 1)) + N.of_nat U * D.potential B db)%N.
  Proof.
    intros B U p cp lim Hround Hchecked fuel.
    induction fuel as [|fuel IH]; intros nv db Hwf Hloaded.
    - cbn [loop_fuel driver_trace firstn map fold_right fst snd]. intros Hids Hunit.
      pose proof (run_cost_rebuild B U db Hwf Hids Hunit) as Hcost.
      assert (HU : 1 <= U) by (pose proof (unit_pos (D.rebuild db)); lia).
      destruct (run_timing_factor B U p HU) as [Hfactor Hconstant].
      nia.
    - cbn [loop_fuel driver_trace firstn map fold_right fst snd].
      destruct (driver p cp lim (nv, db)) as [[next_nv next]|[status next]] eqn:Hdriver.
      + pose proof (run_timing_driver_continue p cp lim nv db next_nv next Hdriver) as Hnext.
        subst next. intros Hids Hunit.
        destruct (run_round_state p cp nv db Hchecked Hwf Hloaded)
          as [Hnext [Hloadnext Hidsnext]].
        destruct (run_timing_fuel_bounds B U p cp lim fuel next_nv
          (round p cp nv db) Hchecked Hnext Hloadnext Hids Hunit)
          as [Hround_ids Hround_unit].
        pose proof (run_timing_driver_amort B U p cp lim nv db Hchecked Hwf Hloaded
          Hround_unit (Hround nv db Hwf Hloaded Hround_ids Hround_unit)) as Hstep.
        pose proof (IH next_nv (round p cp nv db) Hnext Hloadnext
          Hids Hunit) as Htail.
        destruct (round_leaves_idle p cp nv db Hchecked Hwf Hloaded) as [Hcanonical Hpending].
        rewrite Hpending in Htail.
        cbn [N.of_nat] in Htail.
        rewrite !Nat2N.inj_add in Hstep, Htail |- *.
        nia.
      + pose proof (run_timing_driver_stop p cp lim nv db status next Hdriver) as Hnext.
        subst next. intros Hids Hunit. rewrite firstn_nil. cbn [map fold_right].
        destruct (run_round_state p cp nv db Hchecked Hwf Hloaded)
          as [Hnext [Hloadnext Hidsnext]].
        destruct (round_leaves_idle p cp nv db Hchecked Hwf Hloaded) as [Hcanonical Hpending].
        pose proof (D.rebuild_idle _ Hnext Hcanonical Hpending) as Hidle.
        rewrite Hidle in Hids, Hunit.
        pose proof (run_timing_driver_amort B U p cp lim nv db Hchecked Hwf Hloaded
          Hunit (Hround nv db Hwf Hloaded Hids Hunit)) as Hstep.
        pose proof (run_timing_idle_rebuild B U _ Hnext Hcanonical Hpending Hids Hunit)
          as Hrebuild.
        assert (HU : 1 <= U) by (pose proof (unit_pos (round p cp nv db)); lia).
        destruct (run_timing_factor B U p HU) as [Hfactor Hconstant].
        rewrite !Nat2N.inj_add in Hstep |- *. nia.
  Qed.

  (** The public run estimate follows from the sharper private round estimate. *)
  Lemma run_run_from_round :
    (forall B U p cp nv db, plans_ok p cp -> D.wf db -> loaded p cp db ->
      (D.ids (round p cp nv db) <= B)%N -> D.unit (round p cp nv db) <= U ->
      (T_round p cp nv db + N.of_nat U * D.potential B (round p cp nv db) <=
        16 * k_driver * N.of_nat U *
          N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
          N.of_nat (round_work p cp nv db + D.pending db + 1) +
        N.of_nat U * D.potential B db)%N) ->
    forall B U p cp lim db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    (D.ids (snd (run p cp lim db)) <= B)%N -> D.unit (snd (run p cp lim db)) <= U ->
    (T_run p cp lim db <=
      c_run * N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        (fold_right N.add 0 (map (fun start =>
          N.of_nat (round_work p cp (fst start) (snd start) + 1)) (trace p cp lim db)) +
         N.of_nat (D.pending db + 1)) +
      c_run * N.of_nat (N.size_nat (max_iter lim) + 1) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    intros Hround B U p cp lim db Hchecked Hwf Hloaded Hids Hunit.
    pose proof (T_run_split p cp lim db Hchecked Hwf Hloaded) as Hwrapper.
    pose proof (T_driver_loop_split p cp lim db) as Hloop.
    pose proof (run_timing_fuel_cost B U p cp lim
      (fun nv current Hcurrent Hloadcurrent Hbound Hspending =>
        Hround B U p cp nv current Hchecked Hcurrent Hloadcurrent Hbound Hspending)
      Hchecked (N.to_nat (max_iter lim)) false db Hwf Hloaded) as Hcost.
    pose proof (run_unfolds_loop p cp lim db Hchecked Hwf Hloaded) as Hrun.
    rewrite run_timing_loopN_fuel in Hwrapper, Hrun.
    destruct (loop_fuel (driver p cp lim) (N.to_nat (max_iter lim)) (false, db))
      as [[nv final]|[status final]] eqn:Houtcome.
    all: rewrite Hrun in Hids, Hunit; cbn [snd] in Hids, Hunit.
    all: specialize (Hcost Hids Hunit).
    all: rewrite trace_spec in Hloop |- *.
    all: destruct run_timing_constants as [Hconstants [Hdriver Hdb]].
    all: assert (Hbits : (1 <= N.of_nat (N.size_nat (max_iter lim) + 1))%N) by lia.
    all: unfold c_loopN in Hloop, Hcost; rewrite Hconstants in *; nia.
  Qed.

  (** A run charges its visited rounds, initial pending work and binary fuel. *)
  Lemma T_run_le : forall B U p cp lim db, plans_ok p cp -> D.wf db -> loaded p cp db ->
    (D.ids (snd (run p cp lim db)) <= B)%N -> D.unit (snd (run p cp lim db)) <= U ->
    (T_run p cp lim db <=
      c_run * N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        (fold_right N.add 0 (map (fun start =>
          N.of_nat (round_work p cp (fst start) (snd start) + 1)) (trace p cp lim db)) +
         N.of_nat (D.pending db + 1)) +
      c_run * N.of_nat (N.size_nat (max_iter lim) + 1) +
      N.of_nat U * D.potential B db)%N.
  Proof.
    apply run_run_from_round. exact run_round_cost_sharp.
  Qed.

  (** Loading costs the initialisation of its declarations and slots. The measure is the right
      side of [D.T_init_le] without its constant. *)
  Definition load_cost (p : program V.t) (cp : compiled V.t) : N :=
    N.of_nat ((length (decls V.t p) + length (Syntax.slots V.t cp) +
        layout_work (Syntax.slots V.t cp) + 1) *
      (fold_right (fun s n => length (snd s) + n) 0 (Syntax.slots V.t cp) + 1) +
      (fold_right (fun d n => Pos.size_nat (name d) + n) 0 (decls V.t p) +
       fold_right (fun s n => Pos.size_nat (fst s) + n) 0 (Syntax.slots V.t cp)) + 1).
  (** The work of a run is the sum of the round work of its trace and the pending repairs. *)
  Definition run_work (p : program V.t) (cp : compiled V.t) (lim : limits) (db : D.t) : nat :=
    fold_right Nat.add 0 (map (fun st => round_work p cp (fst st) (snd st) + 1)
      (trace p cp lim db)) + D.pending db + 1.
  (** The cost of a run at identifier bound [B] and unit bound [U]. *)
  Definition run_cost (B : N) (U : nat) (p : program V.t) (cp : compiled V.t) (lim : limits)
      (db : D.t) : N :=
    (N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (run_work p cp lim db) +
      N.of_nat (N.size_nat (max_iter lim) + 1) + N.of_nat U * D.potential B db)%N.
  (** The cost of one round at identifier bound [B] and unit bound [U]. *)
  Definition round_cost (B : N) (U : nat) (p : program V.t) (cp : compiled V.t) (nv : bool)
      (db : D.t) : N :=
    (N.of_nat U * N.of_nat ((N.to_nat (N.log2 B) + 1) * (wbits p + 1)) *
        N.of_nat (round_work p cp nv db + D.pending db + 1) +
      N.of_nat U * D.potential B db)%N.

  (** Planning is cubic in the program text, because sorting the positions of an atom
      compares unary join indices. *)
  Lemma plan_complexity :
    T_plan p ∈ 𝑂(N.of_nat ((size_program p + 1) * (size_program p + 1) * (size_program p + 1)))
      for p.
  Proof.
    apply bigO_intro with (c := c_run). intros p _.
    pose proof (T_plan_le p) as Htime.
    rewrite !Nat2N.inj_mul. nia.
  Qed.

  (** Loading is linear in its declarations and slots, with the layout work of sorting. *)
  Lemma load_complexity : T_load p cp ∈ 𝑂(load_cost p cp) for (p, cp).
  Proof.
    apply bigO_intro with (c := (c_run + D.c_db)%N). intros [p cp] _.
    pose proof (T_load_le p cp) as Hload.
    pose proof (D.T_init_le (decls V.t p) (Syntax.slots V.t cp)) as Hinit.
    unfold load_cost. rewrite !Nat2N.inj_add, !Nat2N.inj_mul.
    rewrite !Nat2N.inj_add in Hinit. nia.
  Qed.

  (** Plan checking is linear in the program and plan syntax at their identifier width. *)
  Lemma check_plan_complexity :
    T_check_plan p cp ∈ 𝑂(N.of_nat ((size_program p + size_compiled cp + 1) * (wbits p + 1)))
      for (p, cp).
  Proof.
    apply bigO_intro with (c := c_run). intros [p cp] _.
    pose proof (T_check_plan_le p cp) as Htime.
    rewrite Nat2N.inj_mul. nia.
  Qed.

  (** Converting the natural trace work commutes with summing its binary charges. *)
  Lemma run_work_binary_sum : forall (xs : list (bool * D.t)) p cp,
    fold_right N.add 0%N (map (fun st =>
      N.of_nat (round_work p cp (fst st) (snd st) + 1)) xs) =
    N.of_nat (fold_right Nat.add 0%nat (map (fun st =>
      round_work p cp (fst st) (snd st) + 1) xs)).
  Proof.
    intro xs. induction xs as [|st rest IH]; intros p cp.
    - reflexivity.
    - cbn [map fold_right]. rewrite IH, !Nat2N.inj_add. reflexivity.
  Qed.

  (** A run costs its trace work at the identifier width, its fuel counter and its scaled
      initial credit. *)
  Lemma run_complexity :
    T_run p cp lim db ∈ 𝑂(run_cost B U p cp lim db)
      for (B, U, p, cp, lim, db) |
        plans_ok p cp /\ D.wf db /\ loaded p cp db /\
        (D.ids (snd (run p cp lim db)) <= B)%N /\ D.unit (snd (run p cp lim db)) <= U.
  Proof.
    apply bigO_intro with (c := (c_run + 1)%N).
    intros [[[[[B U] p] cp] lim] db] [Hplans [Hwf [Hloaded [Hids Hunit]]]].
    pose proof (T_run_le B U p cp lim db Hplans Hwf Hloaded Hids Hunit) as Htime.
    cbn beta iota zeta. unfold run_cost, run_work.
    rewrite run_work_binary_sum in Htime.
    rewrite !Nat2N.inj_add in Htime |- *. nia.
  Qed.

  (** A round costs its round work at the identifier width and its scaled initial credit. *)
  Lemma round_complexity :
    T_round p cp nv db ∈ 𝑂(round_cost B U p cp nv db)
      for (B, U, p, cp, nv, db) |
        plans_ok p cp /\ D.wf db /\ loaded p cp db /\
        (D.ids (round p cp nv db) <= B)%N /\ D.unit (round p cp nv db) <= U.
  Proof.
    apply bigO_intro with (c := (c_run + 1)%N).
    intros [[[[[B U] p] cp] nv] db] [Hplans [Hwf [Hloaded [Hids Hunit]]]].
    pose proof (T_round_amort B U p cp nv db Hplans Hwf Hloaded Hids Hunit) as Htime.
    cbn beta iota zeta. unfold round_cost. nia.
  Qed.
End RunT.
